function openSahaProEmbedded() {
  const workspace = document.querySelector(".workspace");
  if (!workspace) return;

  let panel = workspace.querySelector("[data-saha-pro-embedded]");
  if (!panel) {
    panel = document.createElement("section");
    panel.className = "saha-pro-embedded";
    panel.dataset.sahaProEmbedded = "true";
    panel.innerHTML = `
      <div class="saha-pro-embedded-toolbar">
        <div>
          <p class="eyebrow">Saha Çalışma Aracı</p>
          <h2>Saha Pro</h2>
        </div>
        <button class="secondary-button" type="button" data-saha-pro-close>Rapor ekranına dön</button>
      </div>
      <iframe class="saha-pro-embedded-frame" src="saha-pro.html" title="Saha Pro çalışma aracı" loading="eager"></iframe>
    `;
    panel.querySelector("[data-saha-pro-close]").addEventListener("click", closeSahaProEmbedded);
    workspace.append(panel);
  }

  panel.hidden = false;
  workspace.classList.add("saha-pro-open");
  document.body.classList.add("saha-pro-active");
  sahaProToolBtn?.classList.add("is-active");
  sahaProToolBtn?.setAttribute("aria-pressed", "true");
  workspace.scrollTop = 0;
}

function closeSahaProEmbedded() {
  const workspace = document.querySelector(".workspace");
  const panel = workspace?.querySelector("[data-saha-pro-embedded]");
  if (!workspace || !panel) return;
  panel.hidden = true;
  workspace.classList.remove("saha-pro-open");
  document.body.classList.remove("saha-pro-active");
  sahaProToolBtn?.classList.remove("is-active");
  sahaProToolBtn?.setAttribute("aria-pressed", "false");
}

function loadState() {
  const savedUserDefaults = loadUserDefaults();
  const fallback = {
    fields: {
      caseName: "Yeni Ekspertiz Raporu",
    },
    uploads: {},
    sourceValues: {},
    sourceConflicts: {},
    lookupOptions: {},
    settings: {
      mapMode: "hybrid",
      mapExportRatio: "4:3",
      userDefaults: savedUserDefaults,
    },
    tables: {},
    // Çoklu TAKBİS Faz 2 (bkz. docs/coklu-takbis-import-plan.md, "state.titleUnits[]
    // veri modeli"). BİLİNÇLİ TASARIM: mevcut düz `fields`/`tables` HER ZAMAN
    // "birincil taşınmaz"ı (tek-tapu raporlarda TEK taşınmazı) temsil eder ve
    // BİREBİR KORUNUR — geriye dönük uyumluluk için sıfır risk. `titleUnits`
    // yalnızca EK taşınmazları (2. ve sonrası tab) tutar; boş dizi = tek-tapu
    // raporu (bugünkü %100 kullanıcı kitlesi). Henüz hiçbir UI bu diziyi
    // OKUMUYOR/YAZMIYOR — yalnızca veri modeli + yardımcı fonksiyonlar var.
    titleUnits: [],
    // Çoklu TAKBİS Faz 2, tab-anahtarlama motoru (2026-08-09). `activeTitleUnitIndex`:
    // 0 = birincil taşınmaz (state.fields), >0 = state.titleUnits[index-1].
    // `primaryTitleUnitShadow`: yalnızca activeTitleUnitIndex !== 0 iken dolu
    // olur — birincil taşınmazın Tapu/Takyidat verisinin GEÇİCİ yedeği (aktif
    // tab birincil değilken state.fields başka bir taşınmazı gösterdiği için
    // birincilin verisi buraya "park edilir"). Kalıcı olarak persist
    // edilmesinin nedeni: sayfa yenilendiğinde tab hâlâ birincil DEĞİLKEN
    // veri kaybı olmaması (bkz. switchActiveTitleUnit).
    activeTitleUnitIndex: 0,
    primaryTitleUnitShadow: null,
    updatedAt: null,
  };

  try {
    const stored = JSON.parse(localStorage.getItem(storageKey) || "{}");
    const merged = {
      ...fallback,
      ...stored,
      fields: { ...fallback.fields, ...(stored.fields || {}) },
      uploads: { ...fallback.uploads, ...(stored.uploads || {}) },
      sourceValues: { ...fallback.sourceValues, ...(stored.sourceValues || {}) },
      sourceConflicts: { ...fallback.sourceConflicts, ...(stored.sourceConflicts || {}) },
      lookupOptions: { ...fallback.lookupOptions, ...(stored.lookupOptions || {}) },
      settings: {
        ...fallback.settings,
        ...(stored.settings || {}),
        userDefaults: {
          ...savedUserDefaults,
          ...((stored.settings || {}).userDefaults || {}),
        },
      },
      tables: { ...fallback.tables, ...(stored.tables || {}) },
      titleUnits: Array.isArray(stored.titleUnits) ? stored.titleUnits : fallback.titleUnits,
      activeTitleUnitIndex: Number.isInteger(stored.activeTitleUnitIndex) ? stored.activeTitleUnitIndex : fallback.activeTitleUnitIndex,
      primaryTitleUnitShadow: stored.primaryTitleUnitShadow && typeof stored.primaryTitleUnitShadow === "object"
        ? stored.primaryTitleUnitShadow
        : fallback.primaryTitleUnitShadow,
    };
    merged.settings.mapMode = stored.settings?.mapMode ? normalizeMapMode(merged.settings.mapMode) : "hybrid";
    return merged;
  } catch {
    return fallback;
  }
}

// Çoklu TAKBİS Faz 2 — bkz. docs/coklu-takbis-import-plan.md. `titleUnits[]`
// dizisindeki her eleman EK bir taşınmazı temsil eder (birincil taşınmaz
// state.fields/state.tables'ta kalır, buraya girmez). Şu an yalnızca veri
// modeli + yardımcı fonksiyonlar — hiçbir UI bunları çağırmıyor.
function createEmptyTitleUnit(overrides = {}) {
  return {
    id: overrides.id || `unit-${Math.random().toString(36).slice(2, 10)}`,
    fields: { ...(overrides.fields || {}) },
    tables: { ...(overrides.tables || {}) },
    sourceValues: { ...(overrides.sourceValues || {}) },
    sourceFile: overrides.sourceFile || "",
  };
}

// Kullanıcının onayladığı tab adlandırma kuralı (bkz. docs/coklu-takbis-import-plan.md,
// "Onaylanan mimari kararlar"): aynı ada/parselde birden fazla taşınmaz varsa
// tab adı "Blok-BağımsızBölümNo" (ör. "A-3"), farklı ada/parsellerdeyse tab
// adı "Ada Parsel" olur. `allUnits`, birincil taşınmazı da (index 0 gibi
// temsil eden bir birim) İÇERMELİDİR ki "aynı ada/parselde kaç taşınmaz var"
// doğru sayılsın — bu fonksiyon kendisi state.fields'a bakmaz, çağıran taraf
// birincil taşınmazı da aynı şekle (fields: {...}) sarıp listeye eklemeli.
function computeTitleUnitTabLabel(unit, allUnits) {
  const fields = unit?.fields || {};
  const blockNo = String(fields.blockNo || "").trim();
  const parcelNo = String(fields.parcelNo || "").trim();
  const adaParselKey = `${blockNo}|${parcelNo}`;
  const list = Array.isArray(allUnits) ? allUnits : [unit];
  const sameAdaParselCount = list.filter((candidate) => {
    const candidateFields = candidate?.fields || {};
    const key = `${String(candidateFields.blockNo || "").trim()}|${String(candidateFields.parcelNo || "").trim()}`;
    return key === adaParselKey;
  }).length;

  if (sameAdaParselCount > 1) {
    const blockName = String(fields.titleBlockName || "").trim();
    const unitNo = String(fields.unitNo || "").trim();
    const label = [blockName, unitNo].filter(Boolean).join("-");
    if (label) return label;
  }
  const adaParselLabel = [blockNo, parcelNo].filter(Boolean).join(" ");
  return adaParselLabel || "Taşınmaz";
}

// Çoklu TAKBİS Faz 2 — tab-anahtarlama motoru (2026-08-09, bkz.
// docs/coklu-takbis-import-plan.md "Faz 2: state.titleUnits[] veri modeli").
// KAPSAM BİLİNÇLİ OLARAK DAR: yalnızca "title" (Tapu ve Mülkiyet) ve
// "encumbrance" (Takyidat) sekmeleri tapu-başına ayrılıyor — bunlar TAKBİS
// PDF'inden doğrudan gelen, `sections` dizisinde AÇIKÇA listelenmiş alanlar.
// "Bağımsız Bölüm"/"Değerleme" sekmeleri KASITLI OLARAK KAPSAM DIŞI: o
// sekmelerin gerçek alan yüzeyi `sections[].fields`'ta değil, onlarca ayrı
// panel/hesaplama fonksiyonuna (createUnitAreaInteriorPanel,
// createBuildingFloorDistribution, değerleme hesap zinciri vb.) YAYILMIŞ —
// bunları güvenle kapsamak ayrı, dikkatli bir denetim gerektirir (ayrı bir
// oturumda ele alınmalı, bkz. plan dosyası "Henüz yapılmadı" listesi).
// Çoklu Excel/çoklu talep akışında bir satırın bütün ana bölüm alanları aynı
// taşınmaza aittir. Çıktı/masraf ve yönetim bölümleri rapor-genelidir; burada
// bilinçli olarak taşınmaz satırlarına çoğaltılmaz.
const TITLE_UNIT_SCOPED_SECTION_IDS = [
  "case", "address", "title", "encumbrance", "planning", "documents", "land",
  "building", "unit", "comparables", "valuation",
];
const TITLE_UNIT_SCOPED_TABLE_KEYS_BASE = [
  "title", "encumbrance", "documents", "comparables",
  "encumbranceDeclarations", "encumbranceAnnotations", "encumbranceMortgages",
  // 2026-08-20: "unit"/"building" scoping-gap-fix — bölümlerin ANA veri
  // giriş yüzeyi olan satır tabloları (Katlar/Alanlar/Teraslar/İç Hacimler
  // / Ana Gayrimenkul Kat Dağılımı) bugüne kadar hiç taşınmaza-özgü
  // scoped set'te değildi, bkz. getUnitSectionFieldKeys()/getBuildingSectionFieldKeys().
  "unitFloors", "buildingFloors",
];
// Kullanıcı talebi (2026-08-19, 2026-08-20'de TÜM mülkiyet türlerine
// genişletildi — bkz. isComparablesSharedAcrossUnits() yorumu): Çoklu
// Talep raporlarında "comparables" (Emsal kayıtları) tablosu da
// (fields'lara ek olarak) taşınmaza-özgü scoped set'ten ÇIKARILIR —
// rapor-geneli TEK bir emsal listesi kalır. Eskiden düz bir `const` idi
// (TITLE_UNIT_SCOPED_TABLE_KEYS) — İmar'ın getTitleUnitScopedFieldKeys()'teki
// AYNI koşullu-hariç-tutma deseniyle fonksiyona çevrildi.
function getTitleUnitScopedTableKeys() {
  if (isComparablesSharedAcrossUnits()) {
    return TITLE_UNIT_SCOPED_TABLE_KEYS_BASE.filter((key) => key !== "comparables");
  }
  return TITLE_UNIT_SCOPED_TABLE_KEYS_BASE;
}
// Açıklamalar rapor-genelidir. Çoklu tapu sekmeleri arasında taşınmazın
// teknik verileri (ada/parsel, adres detayları, mesafeler vb.) değişir;
// ortak rapor anlatımı ve kullanıcı metinleri değişmez.
//
// 2026-08-12 kullanıcı bildirimi: "bir tabtan diğerine geçtiğimde yine
// çevresel özellik kısımlarını seçmek zorunda kalıyorum ... tüm tablar
// için geçerli ortak kısımlar bunlar" — "Adres ve Konum" sekmesindeki
// TÜM "Çevresel Özellik" alanları (environmentRegionType'tan
// environmentDescription'a kadar olan blok) eklendi. Gerekçe: çoklu
// talepteki taşınmazlar genelde AYNI iş/bölgede birlikte değerlendiriliyor
// — bölgenin yapılaşma yoğunluğu, deprem derecesi, güvenlik durumu vb.
// taşınmaza değil, ÇEVREYE ait bilgilerdir, tab başına tekrar
// seçilmesi anlamsız veri tekrarı. Yalnızca gerçekten taşınmaza özgü
// alanlar (ada/parsel, blok/kat/BB no, mesafeler) kapsam dışı kalmaya
// devam ediyor. `mainArtery`/`mainArteryId` de eklendi — `mainArteryId`
// zaten deklaratif bir alan OLMADIĞI için (getTitleUnitScopedFieldKeys
// yalnızca sections[].fields'ı tarar) dolaylı olarak zaten paylaşımlıydı;
// `mainArtery` (görünen ad) da aynı tutarlılıkta paylaşımlı olmalı.
//
// 2026-08-19: `projectReviewDescription`/`projectConformity` bu listeden
// ÇIKARILDI (kullanıcı: "Proje Uygunluk Durumu... bağımsız bölüm bazında
// kalsın hepsi" — projectConformity, projectSuitabilityStatus'un KENDİ
// açıklama/not alanı, bkz. createProjectSuitabilityField). Genel döngü
// (getTitleUnitScopedFieldKeys) onları artık otomatik taşınmaza-özgü
// toplar. DAVRANIŞ DEĞİŞİKLİĞİ: bu iki alan artık HİÇBİR çoklu-taşınmaz
// senaryosunda (kat irtifakı olsun olmasın) rapor-geneli paylaşılmıyor —
// kullanıcının doğrudan talimatının kapsamı, bkz. plan:
// idempotent-launching-kernighan.md.
const TITLE_UNIT_SHARED_EXPLANATION_FIELD_KEYS = new Set([
  "addressRaw",
  "transport",
  "nearby",
  "environmentDescription",
  "takbisSummary",
  "planRestrictionNote",
  "planningNote",
  "reviewedDocumentsDescription",
  "landNote",
  "landClimateEarthquakeExplanation",
  "comparableMarketAnalysisText",
  "saleabilityNote",
  // "Adres ve Konum" — Çevresel Özellik bloğu (2026-08-12)
  "mainArtery",
  "environmentRegionType",
  "mainArteryProximity",
  "agriculturalActivityDensity",
  "agriculturalActivityTypes",
  "agriculturalSuitability",
  "regionBuildOrder",
  "regionFloorRange",
  "regionIncomeLevel",
  "infrastructureLevel",
  "developmentSpeed",
  "regionBuildingAge",
  "developmentDensity",
  "socialNeeds",
  "regionUsePurpose",
  "earthquakeZone",
  "regionSecurityIssue",
  "propertyValueTrend",
  "commercialFunctionDensity",
  "commercialFirmType",
  "commercialFrontageRoadType",
  "commercialDevelopmentCompleted",
]);

// Kullanıcı talebi (2026-08-16): "Aynı ada parselde yer alan çoklu rapor
// bilgileri için ortak imar durumu sekmeleri olacak" — saf (state-bağımsız)
// karşılaştırma: verilen taşınmaz listesi (buildAllTitleUnitsForSummaryTable()
// çıktısı) TÜMÜYLE aynı Ada (blockNo) + Parsel (parcelNo)'de mi. Daha önce
// yalnızca buildTitleUnitsSummaryTableData() içinde INLINE duran
// "allSameAdaParsel" hesabının ÇIKARILMIŞ, yeniden kullanılabilir hali —
// davranış AYNI (yalnızca fonksiyona taşındı), tools/test-title-unit-switch.js'te
// izole test edilebilsin diye de state okumaz.
function computeTitleUnitsShareSameAdaParsel(units) {
  if (!units.length) return true;
  return units.every((unit) => (
    String(unit.fields?.blockNo || "").trim() === String(units[0].fields?.blockNo || "").trim()
    && String(unit.fields?.parcelNo || "").trim() === String(units[0].fields?.parcelNo || "").trim()
  ));
}

// "İmar Durumu" (planning) bölümü ŞU AN taşınmaza-özgü (scoped) mi olmalı?
// Yalnızca 2+ taşınmaz VE hepsi FARKLI ada/parselde olduğunda EVET — aksi
// halde (tekil rapor veya tüm taşınmazlar AYNI ada/parselde) İmar Durumu
// PAYLAŞIMLI kalır (mantıklı: aynı parselin imar durumu zaten aynıdır).
// getTitleUnitScopedFieldKeys() bunu HER çağrıda canlı olarak sorar — bkz.
// o fonksiyonun yorumunda "geçiş anında veri taşıma" ile ilgili bilinen
// sınırlama notu.
function isPlanningScopedByAdaParsel() {
  const units = buildAllTitleUnitsForSummaryTable();
  return units.length > 1 && !computeTitleUnitsShareSameAdaParsel(units);
}

// Kullanıcı talebi (2026-08-19): "BELGELER ve proje bölümünü incele bu
// bölümü çoklu formata nasıl uydurabiliriz. burada aynı ada parselde yer
// alsa da blok bazında farklı ruhsat iskan veya projeler olabiliyor." —
// computeTitleUnitsShareSameAdaParsel()'in AYNI saf ilkesi, ama BLOK
// düzeyinde: `blockNo`+`parcelNo`+`titleBlockName` ÜÇLÜSÜ birebir aynı mı.
// Yalnızca `titleBlockName` karşılaştırmak YETMEZ — farklı parsellerdeki
// taşınmazların blok adı TESADÜFEN aynı/boş olabilir ("A Blok" = "A Blok"
// ama farklı parseldeyse FARKLI bloktur); ada/parsel de dahil edilerek bu
// yanlış-pozitif önlenir.
function computeTitleUnitsShareSameBlock(units) {
  if (!units.length) return true;
  return units.every((unit) => (
    String(unit.fields?.blockNo || "").trim() === String(units[0].fields?.blockNo || "").trim()
    && String(unit.fields?.parcelNo || "").trim() === String(units[0].fields?.parcelNo || "").trim()
    && String(unit.fields?.titleBlockName || "").trim() === String(units[0].fields?.titleBlockName || "").trim()
  ));
}

// "Belgeler ve Proje" (documents) bölümünün özet tablosu/tab çubuğu ŞU AN
// anlamlı mı? İmar'ın aksine bu bölümün PAYLAŞIM MODELİ değişmiyor (her
// zaman taşınmaza-özgü kalır, bkz. getTitleUnitScopedFieldKeys — "documents"
// zaten hariç tutulmuyor) — bu yalnızca YENİ tablo/tab çubuğu katmanının
// GÖRÜNÜRLÜK kuralı: yalnızca 2+ taşınmaz VE hepsi FARKLI blokta olduğunda
// (aynı ada/parselde bile bloklar farklıysa ruhsat/iskan/proje farklı
// olabilir, kullanıcının bildirdiği gerçek budur) tablo/tab çubuğu
// gösterilir — aksi halde (tekil rapor veya tüm taşınmazlar AYNI blokta)
// karşılaştırılacak bir şey yoktur.
function isDocumentsScopedByBlock() {
  const units = buildAllTitleUnitsForSummaryTable();
  return units.length > 1 && !computeTitleUnitsShareSameBlock(units);
}

// Kullanıcı talebi (2026-08-19): "diyelim ki taşınmazlar toplam 3 blokta
// yer alıyor. bu 3 bloğu blok bazında gruplandıralım. Belgeler ve proje
// bölümünde 3 adet tab açılsın." — computeTitleUnitsShareSameBlock()'un
// (yukarıda) AYNI anahtarını (blockNo+parcelNo+titleBlockName) kullanarak
// `units`'i (buildAllTitleUnitsForSummaryTable() çıktısı) blok gruplarına
// ayırır. Her grup `{ key, unitIndices: [...], fields }` döner —
// `unitIndices`, o bloktaki HER taşınmazın (bağımsız bölümün) global
// index'i (switchActiveTitleUnit'e doğrudan verilebilir), `fields` ilk
// üyenin alanları (blok etiketi/gate kontrolü için).
function computeDocumentsBlockGroups(units) {
  const groups = [];
  (units || []).forEach((unit, index) => {
    const fields = unit?.fields || {};
    const key = [fields.blockNo, fields.parcelNo, fields.titleBlockName]
      .map((value) => String(value || "").trim())
      .join("|");
    let group = groups.find((item) => item.key === key);
    if (!group) {
      group = { key, unitIndices: [], fields };
      groups.push(group);
    }
    group.unitIndices.push(index);
  });
  return groups;
}

// Blok tab etiketi: titleBlockName ("A Blok" vb.) doluysa doğrudan o,
// boşsa sıra numarasıyla "N. Blok" (computeTitleUnitTabLabel'in taşınmaz
// etiketi ürettiği ADI kalıbından esinlenerek, ama blok GRANÜLERLİĞİNDE).
function computeDocumentsBlockLabel(group, allGroups) {
  const blockName = String(group?.fields?.titleBlockName || "").trim();
  if (blockName) return blockName;
  const list = Array.isArray(allGroups) ? allGroups : [group];
  const fallbackIndex = list.indexOf(group) + 1;
  return `${fallbackIndex > 0 ? fallbackIndex : 1}. Blok`;
}

// "Belgeler ve Proje"nin YENİ 2 katmanlı (Blok → Bağımsız Bölüm) tab
// yapısı ŞU AN anlamlı mı? Kullanıcı netleştirmesi (2026-08-19): bu yapı
// YALNIZCA Dikey/Yatay Kat İrtifakı raporlarında geçerli ("bu bölümler
// müstakil binalar için geçerli... bahsettiğimiz mimari yapı dikey ve
// yatay kat irtifakı için olacak") — Müstakil Bina/Arsa/Tarla çoklu-
// taşınmaz senaryolarında (nadir ama mümkün) 0.0.479'un ESKİ düz-tab +
// özet-tablo davranışı FALLBACK olarak korunur (bkz. renderSection gate'i).
// PRİMARY (units[0]) taşınmazın ownershipType'ı kontrol edilir — "hangi
// taşınmaz o an aktif" tutarsızlığından kaçınmak için (bir raporun TÜM
// taşınmazları normalde aynı mülkiyet türünde olur).
function isDocumentsBlockGroupingActive() {
  if (state.fields.requestType !== "Çoklu Talep") return false;
  const units = buildAllTitleUnitsForSummaryTable();
  if (units.length < 2) return false;
  if (!isCondominiumOwnershipTypeValue(units[0]?.fields?.ownershipType)) return false;
  return computeDocumentsBlockGroups(units).length > 1;
}

// "Belgeler ve Proje"de BLOK BAZINDA ORTAK (bir kez girilip bloktaki TÜM
// bağımsız bölümlere otomatik uygulanan) alanlar — kullanıcının verdiği
// TAM liste (2026-08-19): İncelenen Belgeler (ayrı ele alınır, bkz.
// syncDocumentsSharedDataToBlockSiblings), Proje İncelenen Kurum, İnceleme
// Yapılan Kurum, Tapu/Belediye Proje Farkı+Türü+Tarihi+No, Ana Gayrimenkul
// Projesine Uygunluk, EKB grubu, Cezai Karar, Statik Uygunluk, Yapı
// Denetim Sözleşme Durumu. BİLEREK YOK: hasArchitecturalProject/
// projectRegisteredInCadastre/3 kadastro detay alanı (müstakil binaya
// özgü, kullanıcı onayıyla kapsam dışı) — bkz. plan:
// idempotent-launching-kernighan.md "Kapsam dışı".
const DOCUMENTS_BLOCK_SHARED_FIELD_KEYS = [
  "projectInstitution", "documentReviewInstitution", "projectDifference",
  "projectDate", "projectNo", "projectType",
  "titleProjectDate", "titleProjectNo", "titleProjectType",
  "municipalityProjectDate", "municipalityProjectNo", "municipalityProjectType",
  "mainRealEstateProjectSuitable", "mainRealEstateProjectSuitabilityNote",
  "hasEkb", "ekbDocumentNo", "ekbIssueDate", "ekbValidUntil", "ekbEnergyClass", "ekbEmissionClass",
  "penaltyDecision", "penaltyNote",
  "staticSuitability", "staticSuitabilityNote", "staticSuitabilityExplanation",
  "buildingInspectionContractActive", "buildingInspectionProgressLevel",
  "buildingInspectionTerminationDate", "buildingInspectionTerminationLevel", "buildingInspectionExplanation",
];

// Kullanıcı talebi (2026-08-19): "blok bazında giriş yapıldığında tüm o
// blokta yer alan bağımsız bölümlere aynı bilgiler girilecek" — İmar/
// Arsa'nın "tümüne uygula" BUTONUNUN aksine bu senkron HER ilgili
// değişiklikte OTOMATİK çalışır (buton YOK). Aktif taşınmazın bloğunu
// bulur, 2+ üyesi yoksa (veya blok-tab yapısı bu an anlamlı değilse)
// no-op — HANGİ alan değiştiği önemli değil, DOCUMENTS_BLOCK_SHARED_FIELD_KEYS'in
// TAMAMI + İncelenen Belgeler tablosu her seferinde bloktaki DİĞER
// taşınmazlara (resolveTitleUnitWriteTarget/resolveTitleUnitDocumentsRowsWriteTarget
// ile) kopyalanır — küçük blok boyutları için ucuz, tek-alan senkronundan
// (İmar/Arsa) daha basit ve hatasız. Çağrı noktaları: bkz. plan, madde 7
// (çoğu zaten var olan "no-op'a düşebilen refresh" hub çağrılarının
// yanına tek satır olarak eklenir).
function syncDocumentsSharedDataToBlockSiblings() {
  if (!isDocumentsBlockGroupingActive()) return;
  const units = buildAllTitleUnitsForSummaryTable();
  const groups = computeDocumentsBlockGroups(units);
  const activeGroup = groups.find((group) => group.unitIndices.includes(state.activeTitleUnitIndex));
  if (!activeGroup || activeGroup.unitIndices.length < 2) return;

  const sourceFields = state.fields;
  const sourceDocumentsRows = state.tables?.documents || [];
  activeGroup.unitIndices.forEach((index) => {
    if (index === state.activeTitleUnitIndex) return;
    const targetFields = resolveTitleUnitWriteTarget(index);
    DOCUMENTS_BLOCK_SHARED_FIELD_KEYS.forEach((key) => {
      targetFields[key] = sourceFields[key];
    });
    const targetRows = resolveTitleUnitDocumentsRowsWriteTarget(index);
    targetRows.length = 0;
    sourceDocumentsRows.forEach((row) => targetRows.push({ ...row }));
  });
}

// Kullanıcı talebi (2026-08-20): "Ana gayrimenkul bölümünde blok bazında
// açıklama olsun kaç adet blok var ise belgeler bölümünde yer aldığı gibi
// blok bazında o kadar ana gayrimenkul açıklaması olsun." —
// isDocumentsBlockGroupingActive()'in (yukarıda) BİREBİR AYNI gövdesi,
// "building" bölümü için kendi adıyla — computeDocumentsBlockGroups()
// TAMAMEN JENERİK olduğundan doğrudan yeniden kullanılır (documents'a özgü
// hiçbir şey içermiyor).
function isBuildingBlockGroupingActive() {
  if (state.fields.requestType !== "Çoklu Talep") return false;
  const units = buildAllTitleUnitsForSummaryTable();
  if (units.length < 2) return false;
  if (!isCondominiumOwnershipTypeValue(units[0]?.fields?.ownershipType)) return false;
  return computeDocumentsBlockGroups(units).length > 1;
}

// syncDocumentsSharedDataToBlockSiblings()'in (yukarıda) BİREBİR ikizi —
// "building" (Ana Gayrimenkul Özellikleri) alanları için. getBuildingSectionFieldKeys()'in
// TAMAMI (mainPropertyDescription/mainPropertyFloorCountText DAHİL — bkz.
// getBuildingBlockSharedFieldKeys() yorumu) + state.tables.buildingFloors
// (Kat Satırları — "aynı bina" kavramının parçası) aktif taşınmazdan AYNI
// bloktaki diğer bağımsız bölümlere kopyalanır. FARKLI bloklar bağımsız
// kalır. Çağrı noktaları: building bölümünün her commit noktası (bkz. plan,
// "her input/change/save/refresh handler'ın sonuna eklenir").
function syncBuildingSharedDataToBlockSiblings() {
  if (!isBuildingBlockGroupingActive()) return;
  const units = buildAllTitleUnitsForSummaryTable();
  const groups = computeDocumentsBlockGroups(units);
  const activeGroup = groups.find((group) => group.unitIndices.includes(state.activeTitleUnitIndex));
  if (!activeGroup || activeGroup.unitIndices.length < 2) return;

  const sourceFields = state.fields;
  const sharedKeys = getBuildingBlockSharedFieldKeys();
  const sourceBuildingFloorRows = state.tables?.buildingFloors || [];
  activeGroup.unitIndices.forEach((index) => {
    if (index === state.activeTitleUnitIndex) return;
    const targetFields = resolveTitleUnitWriteTarget(index);
    sharedKeys.forEach((key) => {
      targetFields[key] = sourceFields[key];
    });
    const targetRows = resolveTitleUnitBuildingFloorsRowsWriteTarget(index);
    targetRows.length = 0;
    sourceBuildingFloorRows.forEach((row) => targetRows.push({ ...row }));
  });
}

// Seçili blokta girilen ana gayrimenkul verisini diğer bloklara da uygular.
// Aynı blok içi otomatik senkron korunur; bu komut yalnızca kullanıcı
// istediğinde blok sınırını aşar.
function applyBuildingDataToAllBlocks() {
  if (!isBuildingBlockGroupingActive()) return false;
  const units = buildAllTitleUnitsForSummaryTable();
  if (computeDocumentsBlockGroups(units).length < 2) return false;

  const sourceFields = state.fields;
  const sharedKeys = getBuildingBlockSharedFieldKeys();
  const sourceBuildingFloorRows = state.tables?.buildingFloors || [];
  units.forEach((unit, index) => {
    if (index === state.activeTitleUnitIndex) return;
    const targetFields = resolveTitleUnitWriteTarget(index);
    sharedKeys.forEach((key) => {
      const value = sourceFields[key];
      targetFields[key] = value && typeof value === "object"
        ? (Array.isArray(value) ? [...value] : { ...value })
        : value;
    });
    const targetRows = resolveTitleUnitBuildingFloorsRowsWriteTarget(index);
    targetRows.length = 0;
    sourceBuildingFloorRows.forEach((row) => targetRows.push({ ...row }));
  });
  return true;
}

// "İmar Durumu" (planning) bölümünün TÜM taşınmaza-özgü olabilecek alan
// anahtarları — declaratif `section.fields` + 6 conditionalYesNo detay
// notu (titleChangedRecords emsaliyle AYNI boşluk: yalnızca ebeveyn
// alanın detailKey'i olarak var, section.fields'ta AYRI listelenmiyor).
// Zaten HER ZAMAN paylaşımlı olan planRestrictionNote/planningNote
// (TITLE_UNIT_SHARED_EXPLANATION_FIELD_KEYS) HARİÇ. İKİ tüketicisi var:
// getTitleUnitScopedFieldKeys() (İmar Durumu farklı ada/parselde
// taşınmaza-özgü olduğunda hangi alanların TAB DEĞİŞTİRİNCE swap
// edileceği) ve applyImarDataToAllTitleUnits() (kullanıcı talebi,
// 2026-08-16: "tümüne uygula" — hangi alanların KOPYALANACAĞI) — TEK
// kaynaktan, aralarında sürüklenme (drift) riski olmadan.
function getImarSectionFieldKeys() {
  const section = sections.find((item) => item.id === "planning");
  const keys = (section?.fields || [])
    .map((field) => field.key)
    .filter((key) => !TITLE_UNIT_SHARED_EXPLANATION_FIELD_KEYS.has(key));
  return [...keys, "planCancellationStayNote", "minimumFrontageConditionNote", "tevhidConditionNote", "article18AppliedNote", "urbanTransformationAreaNote", "licenseObstacleNote"];
}

// "Arsa Özellikleri" (land) bölümünün TÜM taşınmaza-özgü olabilecek alan
// anahtarları — getImarSectionFieldKeys() ile AYNI ilke. `section.fields`'taki
// 9 deklaratif alandan (landNote/landClimateEarthquakeExplanation zaten
// TITLE_UNIT_SHARED_EXPLANATION_FIELD_KEYS'te, HARİÇ tutulur) + 4 popup
// alanının (Kadastro/İmar Yolu Cephesi, Sulu Tarım, Sınır Unsuru, Zirai
// Ürün — bkz. landDescriptionAutoRefreshFields, tek kanonik kaynak, aşağıda)
// programatik yazılan ekstra state anahtarlarından oluşur. Bu anahtarlar
// section.fields'ta AYRI listelenmiyor (titleChangedRecords/İmar'ın
// conditionalYesNo notlarıyla AYNI boşluk sınıfı) — 2026-08-17'ye kadar
// getTitleUnitScopedFieldKeys() bunları HİÇ toplamıyordu, yani tab
// değiştirince Kadastro Yolu/Sınır Unsuru/Zirai Ürün detayları YANLIŞLIKLA
// diğer taşınmaza SIZIYORDU (kullanıcı bildirmeden ÖNCE keşfedilen sessiz
// bir kusur). İKİ tüketicisi var: getTitleUnitScopedFieldKeys() (tab
// değiştirince hangi alanların taşınacağı) ve applyLandDataToAllTitleUnits()
// (kullanıcı talebi, 2026-08-17: "tüm taşınmazlara uygula" — hangi
// alanların KOPYALANACAĞI) — TEK kaynaktan, drift riski olmadan.
function getLandSectionFieldKeys() {
  const section = sections.find((item) => item.id === "land");
  const keys = (section?.fields || [])
    .map((field) => field.key)
    .filter((key) => !TITLE_UNIT_SHARED_EXPLANATION_FIELD_KEYS.has(key));
  return [
    ...keys,
    "landRoadFrontageItems", "landRoadType", "landRoadName", "landRoadDirection", "landRoadFrontageLength",
    "landIrrigationWaterSource", "landIrrigationSystem",
    "landBoundaryElementItems", "landBoundaryElementOther",
    "landAgriculturalProductItems", "landAgriculturalProductType", "landAgriculturalUnitCount", "landAgriculturalAge", "landAgriculturalYield", "landAgriculturalTotalCount",
  ];
}

// Kullanıcı talebi (2026-08-17): "bu bölümde tüm taşınmazlara uygula
// butonu da yer alsın" — applyImarDataToAllTitleUnits()'in (yukarıda)
// BİREBİR AYNI "bir kez kopyala, sürekli senkron DEĞİL" deseni. TEK
// istisna `landAgriculturalProductItems`: diğer TÜM alanlar (skaler +
// `landRoadFrontageItems`/`landBoundaryElementItems` gibi diziler DAHİL)
// aktif taşınmazdan AYNEN kopyalanır — bu diziler taşınmaza-özgü
// HESAPLANMIŞ bir değer içermez, "aynen kopyala" burada zaten doğru
// davranıştır. `landAgriculturalProductItems`'ın HER kaydındaki
// `totalCount` ise `calculateAgriculturalTotalCount(unitCount, areaValue)`
// (yukarıda, artık 2. parametreli) ile HEDEF taşınmazın KENDİ `landArea`'sı
// kullanılarak YENİDEN hesaplanır — aksi halde farklı ada/parseldeki
// (farklı yüzölçümlü) bir taşınmaza aktif taşınmazın SAYISI yanlışlıkla
// yapıştırılmış olurdu (İmar'ın `calculatedEmsal` istisnasıyla BİREBİR
// aynı risk/çözüm).
function applyLandDataToAllTitleUnits() {
  const keys = getLandSectionFieldKeys();
  const snapshot = {};
  keys.forEach((key) => { snapshot[key] = state.fields[key]; });
  const sourceAgriculturalItems = Array.isArray(snapshot.landAgriculturalProductItems)
    ? snapshot.landAgriculturalProductItems
    : [];

  const applyKeysToUnitFields = (unitFields) => {
    keys.forEach((key) => {
      if (key === "landAgriculturalProductItems") return;
      unitFields[key] = snapshot[key];
    });
    unitFields.landAgriculturalProductItems = sourceAgriculturalItems.map((item) => ({
      ...item,
      totalCount: calculateAgriculturalTotalCount(item.unitCount, unitFields.landArea),
    }));
  };

  (state.titleUnits || []).forEach((unit) => {
    if (!unit) return;
    unit.fields = unit.fields || {};
    applyKeysToUnitFields(unit.fields);
  });

  // Aktif taşınmaz birincil DEĞİLSE, birincilin "park edilmiş" verisi
  // primaryTitleUnitShadow'dadır (bkz. switchActiveTitleUnit) — o da
  // güncellenmeli, aksi halde birincile geri dönüldüğünde eski değer
  // geri gelir.
  if (state.activeTitleUnitIndex !== 0 && state.primaryTitleUnitShadow) {
    state.primaryTitleUnitShadow.fields = state.primaryTitleUnitShadow.fields || {};
    applyKeysToUnitFields(state.primaryTitleUnitShadow.fields);
  }

  return getTitleUnitCount();
}

// Kullanıcı talebi (2026-08-21): "bağımsız bölüm bilgileri için
// uyguladığımız bu yöntemi arsa özellikleri içinde aynı mantık ile
// uygulayalım" — applyUnitDataToSelectedTitleUnits()'in (bkz. "unit"
// bölümü) AYNI "bir kez snapshot al, çağıranın verdiği alt kümeye yaz"
// mekaniği, `applyLandDataToAllTitleUnits()`'in (yukarıda) YERİNE DEĞİL,
// YANINDA (İmar/Arsa'nın "tümüne uygula"sı hâlâ duruyor — bu SEÇİLEBİLİR
// bir kardeş araç). `landAgriculturalProductItems`'ın HER hedefin KENDİ
// (yeni kopyalanmış) `landArea`'sıyla yeniden hesaplanan `totalCount`
// istisnası (yukarıdaki yorum) BİREBİR korunur; diğer diziler
// (`landRoadFrontageItems`/`landBoundaryElementItems`) de applyLandDataToAllTitleUnits
// ile TUTARLI şekilde aynen kopyalanır (bilinçli tasarım, bkz. yukarıki
// yorum — bu diziler taşınmaza-özgü hesaplanmış değer içermez).
// resolveTitleUnitWriteTarget() kullanır (state.titleUnits/primaryTitleUnitShadow'u
// elle DOLAŞMAZ — applyLandDataToAllTitleUnits'ten FARKLI, çünkü hedef
// TÜMÜ değil açık bir liste). Doğrulama ve no-op kuralları
// applyUnitDataToSelectedTitleUnits ile BİREBİR aynı (geçersiz/aralık-
// dışı/tekrarlı index'ler + aktif/kaynak taşınmazın kendi index'i sessizce
// atlanır). Yalnızca state mutasyonu, uygulanan taşınmaz sayısını döner.
function applyLandDataToSelectedTitleUnits(targetIndices) {
  if (!Array.isArray(targetIndices) || !targetIndices.length) return 0;

  const keys = getLandSectionFieldKeys();
  const snapshot = {};
  keys.forEach((key) => { snapshot[key] = state.fields[key]; });
  const sourceAgriculturalItems = Array.isArray(snapshot.landAgriculturalProductItems)
    ? snapshot.landAgriculturalProductItems
    : [];

  const count = getTitleUnitCount();
  const seen = new Set();
  let appliedCount = 0;

  targetIndices.forEach((index) => {
    if (!Number.isInteger(index) || index < 0 || index >= count) return;
    if (index === state.activeTitleUnitIndex) return;
    if (seen.has(index)) return;
    seen.add(index);

    const targetFields = resolveTitleUnitWriteTarget(index);
    keys.forEach((key) => {
      if (key === "landAgriculturalProductItems") return;
      targetFields[key] = snapshot[key];
    });
    targetFields.landAgriculturalProductItems = sourceAgriculturalItems.map((item) => ({
      ...item,
      totalCount: calculateAgriculturalTotalCount(item.unitCount, targetFields.landArea),
    }));

    appliedCount += 1;
  });

  return appliedCount;
}

// Kullanıcı talebi (2026-08-16): "farklı ada parselde imar durumu
// kısmında bazen tüm taşınmazlar aynı imar planına sahip olabiliyor
// (Örnek: 5 Adet Tarla hepsi Tarım Alanı) ... tümüne uygula seçeneği
// olsun." applyTitleRecordChangeToAllTitleUnits()'in (yukarıda,
// tools/test-title-unit-switch.js'te test edilen) AYNI "bir kez kopyala,
// sürekli senkron DEĞİL" deseni — TEK farkı bir alan yerine İmar
// Durumu'nun TÜM alanlarını kopyalar. Aktif taşınmaz zaten state.fields
// üzerinden "kaynak" değeri taşıdığı için kendisine dokunulmaz; yalnızca
// DİĞER taşınmazların kendi depolama yuvaları güncellenir. Sadece
// state mutasyonu yapar — render()/saveState() ÇAĞIRMAZ (switchActiveTitleUnit'in
// AYNI kuralı), çağıran taraf (UI) sonrasında autosave()/tazeleme yapar.
function applyImarDataToAllTitleUnits() {
  const keys = getImarSectionFieldKeys();
  const snapshot = {};
  keys.forEach((key) => { snapshot[key] = state.fields[key]; });

  // Kullanıcı talebi (2026-08-16, devam): "tümüne uygula dediğimde
  // hesaplanan emsal mevcut sistemimizdeki formül ile hesaplanıp
  // yazılmalı aynı sayı yazılmamalı. bu hesaplanan emsal kısmında bir
  // istisna." "Hesaplanan Emsal" (calculatedEmsal) TEK istisna: diğer
  // alanlar (planScale/hmax/taks/kaks/floorCount/planCancellationStay vb.)
  // aktif taşınmazdan AYNEN kopyalanır, ama Hesaplanan Emsal'in kendisi
  // KOPYALANMAZ — her hedef taşınmazın KENDİ net taşınmaz yüzölçümü
  // (landArea, Tapu bölümünde zaten taşınmaza-özgü) ile composeImarCalculatedEmsal()
  // (mevcut, canlı formda da AYNI formülü kullanan buildImarCalculatedEmsal/
  // refreshPlanningNoteFromCurrentFields'in dayandığı fonksiyon) üzerinden
  // YENİDEN hesaplanır — aksi halde farklı ada/parseldeki (farklı
  // yüzölçümlü) bir taşınmaza aktif taşınmazın SAYISI yanlışlıkla
  // yapıştırılmış olurdu.
  const applyKeysToUnitFields = (unitFields) => {
    keys.forEach((key) => {
      if (key === "calculatedEmsal") return;
      unitFields[key] = snapshot[key];
    });
    unitFields.calculatedEmsal = composeImarCalculatedEmsal({
      netParcelArea: unitFields.landArea,
      kaks: unitFields.kaks,
      floorCount: unitFields.floorCount,
      planCancellationStay: unitFields.planCancellationStay,
    });
  };

  (state.titleUnits || []).forEach((unit) => {
    if (!unit) return;
    unit.fields = unit.fields || {};
    applyKeysToUnitFields(unit.fields);
  });

  // Aktif taşınmaz birincil DEĞİLSE, birincilin "park edilmiş" verisi
  // primaryTitleUnitShadow'dadır (bkz. switchActiveTitleUnit) — o da
  // güncellenmeli, aksi halde birincile geri dönüldüğünde eski değer
  // geri gelir.
  if (state.activeTitleUnitIndex !== 0 && state.primaryTitleUnitShadow) {
    state.primaryTitleUnitShadow.fields = state.primaryTitleUnitShadow.fields || {};
    applyKeysToUnitFields(state.primaryTitleUnitShadow.fields);
  }

  return getTitleUnitCount();
}

function getTitleUnitScopedFieldKeys() {
  const keys = new Set();
  // 2026-08-16: İmar Durumu artık KOŞULLU taşınmaza-özgü — tüm taşınmazlar
  // AYNI ada/parselde ise bu bölümün alanları scoped-set'e HİÇ eklenmez
  // (TITLE_UNIT_SHARED_EXPLANATION_FIELD_KEYS alanları gibi PAYLAŞIMLI
  // kalır, state.fields'ta sabit durur — hiçbir switchActiveTitleUnit onu
  // taşımaz). BİLİNEN SINIRLAMA: bir rapor "paylaşımlı"dan "taşınmaza-özgü"ye
  // GEÇTİĞİNDE (ör. kullanıcı sonradan bir taşınmazın parselNo'sunu
  // farklılaştırırsa), o ana kadar HİÇ taşınmaza-özgü gölge yuvası
  // yazılmamış olan taşınmazların İmar Durumu alanları (applyTitleUnitScopedData'nın
  // "yoksa sil" kuralı gereği) sonraki tab geçişinde BOŞ görünür — veri
  // KAYBOLMAZ (paylaşılan değer, o anda aktif/ayrılan taşınmazın kendi
  // gölgesinde kalır), yalnızca diğer taşınmazlar için yeniden girilmesi
  // gerekebilir. Otomatik taşıma BİLİNÇLİ OLARAK yazılmadı (ada/parsel
  // tipik olarak Tapu veri girişinde, İmar Durumu'ndan ÖNCE netleşir) —
  // bkz. plan: idempotent-launching-kernighan.md.
  const planningIsShared = !isPlanningScopedByAdaParsel();
  TITLE_UNIT_SCOPED_SECTION_IDS.forEach((sectionId) => {
    // "planning" ayrı ele alınıyor (aşağıda, getImarSectionFieldKeys ile) —
    // 2026-08-16'da applyImarDataToAllTitleUnits() ile TEK kaynaktan
    // (drift riski olmadan) paylaşılan bir çıkarım haline getirildi.
    if (sectionId === "planning") return;
    // Kullanıcı talebi (2026-08-19, 2026-08-20'de TÜM mülkiyet türlerine
    // genişletildi — bkz. isComparablesSharedAcrossUnits() yorumu): Çoklu
    // Talep raporlarında "comparables" (Emsaller) bölümünün alanları
    // scoped set'e HİÇ eklenmez (rapor-geneli paylaşımlı kalır). Tekli
    // Talep'te davranış DEĞİŞMİYOR.
    if (sectionId === "comparables" && isComparablesSharedAcrossUnits()) return;
    const section = sections.find((item) => item.id === sectionId);
    (section?.fields || []).forEach((field) => {
      // Talep Türü rapor-genelidir; taşınmaz tabına geçerken birim verisiyle
      // üzerine yazılırsa Çoklu Talep yanlışlıkla Tekli Talep'e döner.
      if (field.key !== "requestType" && !TITLE_UNIT_SHARED_EXPLANATION_FIELD_KEYS.has(field.key)) {
        keys.add(field.key);
      }
    });
  });
  // "titleChangedRecords" "title" sekmesinin DEKLARATİF fields listesinde
  // yer almıyor — openTitleRecordChangeModal ile programatik yazılıyor
  // (bkz. createTitleRecordChangeControl). Yine de taşınmaza özgüdür; geç
  // fark edilen bir boşluktu (2026-08-09) — elle eklendi, aksi halde tab
  // değiştirince bu alan TÜM taşınmazlar arasında PAYLAŞILIRDI (yanlışlıkla
  // sızardı).
  keys.add("titleChangedRecords");
  // İmar Durumu şu an taşınmaza-özgüyse (farklı ada/parsel) TÜM alanları
  // (declaratif + 6 detay notu — getImarSectionFieldKeys, yukarıda) scoped
  // set'e eklenir; aksi halde (paylaşımlı) hiçbiri eklenmez.
  if (!planningIsShared) {
    getImarSectionFieldKeys().forEach((key) => keys.add(key));
  }
  // "land" (Arsa Özellikleri) İmar'ın AKSİNE koşullu paylaşıma geçmiyor —
  // HER ZAMAN taşınmaza-özgü kalıyor (yukarıdaki genel döngü zaten "land"i
  // hariç tutmuyor, 9 deklaratif alan doğru toplanıyor). Yalnızca popup
  // alanlarının (Kadastro Yolu/Sınır Unsuru/Zirai Ürün vb.) section.fields'ta
  // OLMAYAN ekstra state anahtarları eksikti (2026-08-17'de keşfedilen
  // sessiz sızıntı kusuru, bkz. getLandSectionFieldKeys() yorumu) — KOŞULSUZ
  // eklenir.
  getLandSectionFieldKeys().forEach((key) => keys.add(key));
  // "documents" (Belgeler ve Proje) alanlarından bir kısmı ("Proje Uygunluk
  // Durumu - Bağımsız Bölüm" ve Tapu/Belediye proje FARKLIYSA görünen
  // varyantları) `createProjectSuitabilityField`/`createProjectSuitabilityPanel`
  // ile PROGRAMATİK yazılıyor — section.fields'ta DEKLARATİF olarak
  // listelenmiyor (titleChangedRecords'la AYNI sınıf). Bu yüzden yukarıdaki
  // genel döngü onları HİÇ toplamıyordu — "documents" TITLE_UNIT_SCOPED_SECTION_IDS'te
  // olmasına RAĞMEN, tab değiştirince bu alanlar BUGÜNE KADAR (2026-08-19'a
  // kadar) yanlışlıkla TÜM taşınmazlar arasında paylaşılıyordu (Arsa'nın
  // popup sızıntısıyla AYNI sınıf sessiz kusur, bkz. plan:
  // idempotent-launching-kernighan.md). "documents" paylaşım modeli
  // DEĞİŞMİYOR (her zaman taşınmaza-özgü) — KOŞULSUZ eklenir.
  getDocumentsPerUnitOnlyFieldKeys().forEach((key) => keys.add(key));
  // "valuation" (Değerleme) alanlarının çoğu declaratif (legalValue vb.,
  // hidden:true olsalar da scoping döngüsü hidden'a bakmaz, doğru
  // toplanıyor) — AMA Piyasa Değeri tablosunun alan/birim ALT alanları
  // (legalValueArea/currentValueArea/legalRentArea/currentRentArea/
  // legalValueUnit/currentValueUnit/legalRentUnit/currentRentUnit) ve
  // "manuel geçersiz kılma" bayrakları section.fields'ta DEKLARATİF
  // DEĞİL (createValuationInput ile PROGRAMATİK yazılıyor,
  // titleChangedRecords/documents'la AYNI sınıf sessiz kusur, 2026-08-19'da
  // keşfedildi) — bu yüzden BUGÜNE KADAR yanlışlıkla TÜM taşınmazlar
  // arasında paylaşılıyordu. "valuation" paylaşım modeli DEĞİŞMİYOR (her
  // zaman taşınmaza-özgü) — KOŞULSUZ eklenir.
  getValuationPerUnitOnlyFieldKeys().forEach((key) => keys.add(key));
  // "unit"/"building" (Bağımsız Bölüm/Ana Gayrimenkul Özellikleri)
  // scoping-gap-fix (2026-08-20, bkz. getUnitSectionFieldKeys()/
  // getBuildingSectionFieldKeys() yorumları) — paylaşım modelleri
  // DEĞİŞMİYOR (her zaman taşınmaza-özgü depo; building'in blok-arası
  // paylaşımı AYRI bir katman, bkz. syncBuildingSharedDataToBlockSiblings)
  // — KOŞULSUZ eklenir.
  getUnitSectionFieldKeys().forEach((key) => keys.add(key));
  getBuildingSectionFieldKeys().forEach((key) => keys.add(key));
  return keys;
}

// bkz. yukarıdaki getTitleUnitScopedFieldKeys() yorumu — Piyasa Değeri
// tablosunun (createValuationMarketTable) alan/birim alt alanları ve
// manuel-geçersiz-kılma bayrakları, section.fields'ta deklaratif olmayan
// programatik alanlar. Tam liste `clearLandOwnershipDependentData()`'nın
// `exactKeys` setinden (bu fonksiyonun ZATEN Arsa/Tarla'ya geçişte
// temizlediği, dolayısıyla taşınmaza-özgü olması gereken alanları
// listeleyen kanonik kaynaktan) doğrulanmıştır — tek kanonik kaynak,
// drift riski olmadan hem scoping-gap-fix hem (ileride gerekirse) başka
// tüketiciler için.
function getValuationPerUnitOnlyFieldKeys() {
  return [
    "legalValueArea", "currentValueArea", "legalRentArea", "currentRentArea",
    "legalValueUnit", "currentValueUnit", "legalRentUnit", "currentRentUnit",
    "legalValueComparableAutoManual", "currentValueComparableAutoManual",
    "legalRentComparableAutoManual", "currentRentComparableAutoManual",
    "legalValueUserDefined", "currentValueUserDefined",
  ];
}

// Kullanıcı talebi (2026-08-20): "hangi bölümü geliştirmeye başlamalıyız"
// sorusuna verilen eleştirel rapor cevabı — "Bağımsız Bölüm Özellikleri"
// (unit) hiç denetlenmemişti, en yüksek riskli alandı. getImarSectionFieldKeys()/
// getLandSectionFieldKeys() ile AYNI ilke: `section.fields`'taki 2 deklaratif
// alan (legalArea/currentArea, zaten doğru scoped) + createUnitFeaturesEditor'ün
// (genel/alan-iç mekan/dekoratif panelleri, açıklama alanları) PROGRAMATİK
// yazdığı ~50 alan — section.fields'ta HİÇ deklaratif değildi (titleChangedRecords/
// documents/valuation'la AYNI sınıf sessiz kusur). "unit" paylaşım modeli HER
// ZAMAN taşınmaza-özgü (blok kavramı burada anlamsız — aynı bloktaki iki
// bağımsız bölüm bile doğası gereği farklı alan/iç mekan/dekorasyon bilgisine
// sahiptir) — KOŞULSUZ eklenir.
function getUnitSectionFieldKeys() {
  const section = sections.find((item) => item.id === "unit");
  const keys = (section?.fields || [])
    .map((field) => field.key)
    .filter((key) => !TITLE_UNIT_SHARED_EXPLANATION_FIELD_KEYS.has(key));
  return [
    ...keys,
    // Genel panel (createUnitGeneralPanel)
    "unitUsageStatus", "unitFirstSaleStatus", "unitFirstSaleStatusManual", "unitEntrancePosition", "facades",
    "unitConstructionLevel", "unitViewStatus", "unitHeatingType", "unitHeatingMounted",
    "unitShopFrontage", "unitShopDepth",
    // Alan/iç mekan özeti (syncUnitFloorSummaryFields, unitFloors[0]'dan türetilir)
    "unitFloor", "unitAreaReductionRate", "unitLegalTerrace", "unitCurrentTerrace", "unitTerraceReductionRate", "interiorFeatures",
    // Dekoratif panel (applyUnitDecorativeFieldChange)
    "unitSalonFloor", "unitSalonWall", "unitRoomFloor", "unitRoomWall", "unitHallFloor", "unitHallWall",
    "unitKitchenFloor", "unitKitchenWall", "unitWetFloor", "unitWetWall", "unitBalconyFloor", "unitBalconyWall",
    "unitWindows", "unitExteriorDoor", "unitInteriorDoors", "unitKitchenCabinet", "unitKitchenCounter",
    "unitMaterialQuality", "unitBathroomFixture1", "unitBathroomFixture2", "unitBathroomFixture3",
    // Açıklama alanları
    "unitInteriorDescription", "unitInteriorDescriptionManual", "unitDecorativeDescription", "unitDecorativeDescriptionManual",
    // Eski/dormant fallback alanları (yalnızca unitFloors tablosu henüz
    // migrate edilmemişse getUnitFloorRows() tarafından okunur, bugünün
    // arayüzü artık yazmıyor ama tam koruma için dahil edildi)
    "unitLegalReductionRate", "unitCurrentReductionRate", "unitLegalTerraceReductionRate", "unitCurrentTerraceReductionRate",
    "unitLivingRoom", "unitRoomCount", "unitKitchen", "unitBathroom", "unitBalcony", "unitWc", "unitHall",
    "unitDressingRoom", "unitLaundryRoom",
  ];
}

// Kullanıcı talebi (2026-08-20/21): "bağımsız bölüm özellikleri bölümüne
// yeni bir bölüm eklemek istiyorum ... tümüne uygula mantığında ama
// SEÇECEĞİM bağımsız bölümlere kopyalama yapılmalı, tamamına değil.
// aktif bulunduğum bağımsız bölümün bilgilerini istediğim bağımsız
// bölümlere kopyalamak işin özeti." — applyImarDataToAllTitleUnits()/
// applyLandDataToAllTitleUnits()'in (yukarıda) AYNI "bir kez kopyala,
// sürekli senkron DEĞİL" mekaniği — TEK fark: hedefler "TÜM taşınmazlar"
// değil, çağıranın açıkça verdiği targetIndices alt kümesi.
// getUnitSectionFieldKeys() listesi (aktif taşınmazdan BİR KEZ okunur) +
// state.tables.unitFloors (Katlar/Alanlar/Teraslar/İç Hacimler, bölümün
// ANA veri yüzeyi) kopyalanır. Bu alanların TAMAMI skaler (string) —
// object/array-safe klonlama GEREKMİYOR (facades bile virgülle-birleştirilmiş
// TEK STRING, gerçek array değil, bkz. app.js'teki facades checkbox
// handler'ı) — applyLandDataToAllTitleUnits'in AYNI basit atama deseni
// yeterli. setTitleUnitFieldValue()'nun (yukarıda) AYNI index doğrulama
// kuralı — geçersiz/aralık dışı/tekrarlı index'ler SESSİZCE atlanır (throw
// etmez), aktif taşınmazın kendi index'i de (yanlışlıkla listede olsa
// bile) SESSİZCE atlanır (kendine kopyalama anlamsız, no-op olmalı, hata
// DEĞİL). Yalnızca state mutasyonu yapar — render()/saveState() ÇAĞIRMAZ
// (mevcut kural), çağıran taraf (UI) saveState()+render() yapmalı.
// Gerçekten uygulanan taşınmaz sayısını döner.
function applyUnitDataToSelectedTitleUnits(targetIndices) {
  if (!Array.isArray(targetIndices) || !targetIndices.length) return 0;

  const keys = getUnitSectionFieldKeys();
  const snapshot = {};
  keys.forEach((key) => { snapshot[key] = state.fields[key]; });
  const sourceUnitFloorRows = state.tables?.unitFloors || [];

  const count = getTitleUnitCount();
  const seen = new Set();
  let appliedCount = 0;

  targetIndices.forEach((index) => {
    if (!Number.isInteger(index) || index < 0 || index >= count) return;
    if (index === state.activeTitleUnitIndex) return;
    if (seen.has(index)) return;
    seen.add(index);

    const targetFields = resolveTitleUnitWriteTarget(index);
    keys.forEach((key) => { targetFields[key] = snapshot[key]; });

    const targetRows = resolveTitleUnitUnitFloorsRowsWriteTarget(index);
    targetRows.length = 0;
    sourceUnitFloorRows.forEach((row) => targetRows.push({ ...row }));

    appliedCount += 1;
  });

  return appliedCount;
}

// Kullanıcı talebi (2026-08-20) — AYNI rapor: "Ana Gayrimenkul Özellikleri"
// (building) section.fields'ı LİTERAL BOŞ DİZİ — hiçbir alan deklaratif
// değil, bu yüzden TITLE_UNIT_SCOPED_SECTION_IDS'te olmasına RAĞMEN genel
// döngü hiçbir şey toplamıyordu; createBuildingFloorDistribution'ın (genel
// teknik özellikler paneli, kat dağılımı, Ana Gayrimenkul Açıklaması)
// PROGRAMATİK yazdığı ~22 alan BUGÜNE KADAR TAMAMEN rapor-geneli
// paylaşımlıydı (tab değiştirmenin hiçbir etkisi yoktu — documents/
// valuation'daki sessiz kusurdan bile daha ciddisi, çünkü hiç scoped
// değildi). "building" paylaşım modeli de HER ZAMAN taşınmaza-özgü
// (temel depo) — bloklar arası paylaşım ayrıca syncBuildingSharedDataToBlockSiblings()
// ile (Kat İrtifakı + Çoklu Talep + birden fazla blok varken) sağlanır,
// bkz. aşağıdaki BUILDING_BLOCK_SHARED_FIELD_KEYS.
function getBuildingSectionFieldKeys() {
  const section = sections.find((item) => item.id === "building");
  const keys = (section?.fields || [])
    .map((field) => field.key)
    .filter((key) => !TITLE_UNIT_SHARED_EXPLANATION_FIELD_KEYS.has(key));
  return [
    ...keys,
    "buildingStyle", "buildingOrder", "buildingClass", "buildingAge", "buildingAgeManualOverride",
    "carpark", "elevator", "exteriorCladding", "stairLanding", "interiorWalls",
    "buildingEntranceDoor", "buildingFootprintReference", "buildingEntranceLevel", "buildingEntranceDirection",
    "socialFacilities", "buildingBlockCount", "buildingSubjectBlockPosition",
    "buildingFloorCounts", "totalFloors", "totalUnits",
    "mainPropertyFloorSummary", "mainPropertyDescription", "mainPropertyFloorCountText",
  ];
}

// Kullanıcı talebi (2026-08-20): "Ana gayrimenkul bölümünde blok bazında
// açıklama olsun kaç adet blok var ise belgeler bölümünde yer aldığı gibi
// blok bazında o kadar ana gayrimenkul açıklaması olsun." —
// getBuildingSectionFieldKeys()'in TÜMÜ (mainPropertyDescription/
// mainPropertyFloorCountText DAHİL) — bir bağımsız bölümde üretilen/
// düzenlenen Ana Gayrimenkul verisi, AYNI bloktaki diğer bağımsız
// bölümlere OTOMATİK yansır (Belgeler'in DOCUMENTS_BLOCK_SHARED_FIELD_KEYS
// deseninin BİREBİR ikizi) — FARKLI bloklar bağımsız kalır. Fonksiyon
// olarak tanımlandı (DOCUMENTS_BLOCK_SHARED_FIELD_KEYS gibi düz `const`
// DEĞİL) çünkü getBuildingSectionFieldKeys() `sections` dizisine bağımlı —
// modül yükleme sırasına duyarlı bir üst-seviye `const` yerine, ilk
// kullanımda (syncBuildingSharedDataToBlockSiblings içinde) tembel
// çağrılır.
function getBuildingBlockSharedFieldKeys() {
  return getBuildingSectionFieldKeys();
}

// bkz. yukarıdaki getTitleUnitScopedFieldKeys() yorumu — "Proje Uygunluk
// Durumu - Bağımsız Bölüm" (ve Tapu/Belediye proje FARKLIYSA görünen
// varyantları) section.fields'ta deklaratif olmayan, programatik alanlar.
// Kullanıcı talebi (2026-08-19): "Proje Uygunluk Durumu... bağımsız bölüm
// bazında kalsın hepsi" — tek kanonik kaynak, drift riski olmadan hem
// scoping-gap-fix hem (ileride gerekirse) başka tüketiciler için.
function getDocumentsPerUnitOnlyFieldKeys() {
  return [
    "projectSuitabilityStatus",
    "projectSuitabilitySimpleRepair",
    "titleProjectSuitabilityStatus",
    "titleProjectSuitabilityNote",
    "titleProjectSuitabilitySimpleRepair",
    "municipalityProjectSuitabilityStatus",
    "municipalityProjectSuitabilityNote",
    "municipalityProjectSuitabilitySimpleRepair",
  ];
}

// Aktif taşınmazın Tapu/Takyidat alan+tablo verisini state'ten bağımsız bir
// anlık görüntü olarak çıkarır (başka bir taşınmaza geçmeden ÖNCE "kaydet").
function snapshotTitleUnitScopedData() {
  const fields = {};
  getTitleUnitScopedFieldKeys().forEach((key) => {
    if (Object.prototype.hasOwnProperty.call(state.fields, key)) fields[key] = state.fields[key];
  });
  const tables = {};
  getTitleUnitScopedTableKeys().forEach((key) => {
    if (state.tables[key] !== undefined) tables[key] = state.tables[key];
  });
  const sourceValues = {};
  ["kml", "nearbyPlaces", "nearbyArtery", "nearbyTransport", "regionAnalysis", "localNeighborhood", "administrativeNeighborhoodFallback"].forEach((key) => {
    if (state.sourceValues?.[key] !== undefined) sourceValues[key] = state.sourceValues[key];
  });
  return { fields, tables, sourceValues };
}

// Verilen taşınmazın (snapshot şeklinde: {fields, tables}) verisini
// state.fields/state.tables'a YÜKLER — bir taşınmaza geçerken kullanılır.
// Snapshot'ta olmayan anahtarlar SİLİNİR (undefined bırakılır), böylece
// createTable() gibi tüketicilerin kendi varsayılan-satır üretme mantığı
// (`state.tables[key] || Array.from(...)`) doğru şekilde devreye girer —
// boş dizi ATAMAK bu varsayılanı YANLIŞLIKLA bastırır (bkz. yorum,
// switchActiveTitleUnit çağrı yeri).
function applyTitleUnitScopedData(snapshot) {
  const fields = snapshot?.fields || {};
  getTitleUnitScopedFieldKeys().forEach((key) => {
    if (Object.prototype.hasOwnProperty.call(fields, key)) {
      state.fields[key] = fields[key];
    } else {
      delete state.fields[key];
    }
  });
  const tables = snapshot?.tables || {};
  getTitleUnitScopedTableKeys().forEach((key) => {
    if (tables[key] !== undefined) {
      state.tables[key] = tables[key];
    } else {
      delete state.tables[key];
    }
  });
  state.sourceValues = state.sourceValues || {};
  const sourceValues = snapshot?.sourceValues || {};
  ["kml", "nearbyPlaces", "nearbyArtery", "nearbyTransport", "regionAnalysis", "localNeighborhood", "administrativeNeighborhoodFallback"].forEach((key) => {
    if (sourceValues[key] !== undefined) state.sourceValues[key] = sourceValues[key];
    else delete state.sourceValues[key];
  });
}

function getTitleUnitCount() {
  return 1 + (Array.isArray(state.titleUnits) ? state.titleUnits.length : 0);
}

// Etiket hesaplama İÇİN "index'teki taşınmazın fields'ı ne" sorusuna cevap
// verir — aktif index'te state.fields (canlı veri), diğerlerinde kendi
// depolama yuvası (birincil için primaryTitleUnitShadow, diğerleri için
// titleUnits[i-1]) kullanılır.
function getTitleUnitFieldsForLabel(index) {
  if (index === state.activeTitleUnitIndex) return state.fields;
  if (index === 0) return state.primaryTitleUnitShadow?.fields || {};
  return state.titleUnits[index - 1]?.fields || {};
}

function getTitleUnitTablesForLabel(index) {
  if (index === state.activeTitleUnitIndex) return state.tables;
  if (index === 0) return state.primaryTitleUnitShadow?.tables || {};
  return state.titleUnits[index - 1]?.tables || {};
}

function getTitleUnitTabModels() {
  const count = getTitleUnitCount();
  const all = Array.from({ length: count }, (_, index) => ({ fields: getTitleUnitFieldsForLabel(index) }));
  return all.map((unit, index) => ({
    index,
    isActive: index === state.activeTitleUnitIndex,
    label: computeTitleUnitTabLabel(unit, all),
  }));
}

// Yalnızca STATE MUTASYONU yapar — render()/saveState() ÇAĞIRMAZ (bilinçli:
// bu fonksiyonu DOM/localStorage bağımlılığı olmadan sandbox'ta test
// edebilmek için, bkz. tools/test-title-unit-switch.js). Çağıran taraf
// (UI event handler) mutasyondan SONRA saveState()+render() çağırmalı.
function switchActiveTitleUnit(newIndex) {
  const count = getTitleUnitCount();
  if (!Number.isInteger(newIndex) || newIndex < 0 || newIndex >= count || newIndex === state.activeTitleUnitIndex) return false;

  const currentSnapshot = snapshotTitleUnitScopedData();
  if (state.activeTitleUnitIndex === 0) {
    state.primaryTitleUnitShadow = currentSnapshot;
    state.primaryTitleUnitShadow.fields.ownershipType = state.fields.ownershipType;
  } else {
    const unit = state.titleUnits[state.activeTitleUnitIndex - 1];
    if (unit) {
      unit.fields = currentSnapshot.fields;
      unit.tables = currentSnapshot.tables;
      unit.sourceValues = currentSnapshot.sourceValues;
    }
  }

  if (newIndex === 0) {
    applyTitleUnitScopedData(state.primaryTitleUnitShadow || { fields: {}, tables: {} });
    state.primaryTitleUnitShadow = null;
  } else {
    const targetUnit = state.titleUnits[newIndex - 1] || createEmptyTitleUnit();
    applyTitleUnitScopedData(targetUnit);
  }

  state.activeTitleUnitIndex = newIndex;
  return true;
}

// Yeni boş bir taşınmaz birimi ekler, YENİ index'i döner (henüz oraya
// GEÇMEZ — çağıran taraf switchActiveTitleUnit(dönenIndex) ile geçmeli).
function addTitleUnitTab() {
  if (!Array.isArray(state.titleUnits)) state.titleUnits = [];
  state.titleUnits.push(createEmptyTitleUnit());
  return state.titleUnits.length;
}

const MULTI_TITLE_UNIT_OWNERSHIP_TYPES = new Set([
  "Dikey Kat İrtifakı",
  "Yatay Kat İrtifakı",
  "Müstakil Bina",
  "Arsa",
  "Tarla",
]);

// Çift Yönlü Düzenleme, Faz 3 (2026-08-15) — "tab üzerinden değiştirince
// tablo değişsin tablo üzerinden değiştirdiğimde tab değişsin" isteğinin
// AKTİF OLMAYAN taşınmazlar için tamamlanması (bkz. plan:
// idempotent-launching-kernighan.md). getTitleUnitFieldsForLabel() (yukarıda)
// SALT-OKUMA amaçlıdır: index===0 VE primaryTitleUnitShadow henüz YOKSA
// (teorik/bozuk bir çağrı) transient bir `{}` literal döner — ona yazmak
// SESSİZCE KAYBOLURDU. Bu fonksiyon YAZMA amaçlıdır: gerekli gölge yuvayı
// (yoksa) ÖNCE oluşturur, SONRA gerçek (state İÇİNDEKİ referans) fields
// nesnesini döner — mevcut syncMultiTitleUnitOwnershipType (yukarıda) ve
// applyTitleRecordChangeToAllTitleUnits'in "gölgeye doğrudan yaz" desenini
// TEK bir hedefli index için genelleştirir. switchActiveTitleUnit'in
// kuralını miras alır: SADECE state mutasyonu yapar, render()/saveState()
// ÇAĞIRMAZ — çağıran taraf gerekirse kendisi tetiklemeli.
function resolveTitleUnitWriteTarget(index) {
  if (index === state.activeTitleUnitIndex) return state.fields;
  if (index === 0) {
    if (!state.primaryTitleUnitShadow || typeof state.primaryTitleUnitShadow !== "object") {
      state.primaryTitleUnitShadow = { fields: {}, tables: {} };
    }
    state.primaryTitleUnitShadow.fields = state.primaryTitleUnitShadow.fields || {};
    return state.primaryTitleUnitShadow.fields;
  }
  if (!Array.isArray(state.titleUnits)) state.titleUnits = [];
  if (!state.titleUnits[index - 1]) state.titleUnits[index - 1] = createEmptyTitleUnit();
  state.titleUnits[index - 1].fields = state.titleUnits[index - 1].fields || {};
  return state.titleUnits[index - 1].fields;
}

// Tek bir taşınmazın TEK bir skaler alanını yazar — Faz 2'nin aktif-
// taşınmaz kısayolunun (doğrudan state.fields) AKTİF OLMAYAN taşınmazlara
// genellenmiş hali. index geçersizse (0 <= index < getTitleUnitCount()
// aralığı dışında) veya key boşsa false döner, aksi halde true.
function setTitleUnitFieldValue(index, key, value) {
  if (!Number.isInteger(index) || index < 0 || index >= getTitleUnitCount() || !key) return false;
  const fields = resolveTitleUnitWriteTarget(index);
  fields[key] = value;
  return true;
}

// Çift Yönlü Düzenleme, Faz 4 (2026-08-15) — Malik(ler)/Hisse Payı/Edinme
// Sebebi/Tapu Tarihi/Yevmiye No özet tablo sütunları TEK bir skaler alan
// DEĞİL, `state.tables.title` (Malikler tablosu) DİZİSİNİN `joinTitleUnitOwnerColumn`
// ile birleştirilmiş hali — bu yüzden resolveTitleUnitWriteTarget()'tan
// (fields nesnesi döner) AYRI bir hedef-çözücü gerekir: aynı 3 yönlü
// aktif/index-0-gölge/diğer dallanmayı `fields` yerine `tables.title`
// DİZİSİNE uygular. SADECE state mutasyonu yapar, render()/saveState()
// ÇAĞIRMAZ (resolveTitleUnitWriteTarget ile AYNI kural).
function resolveTitleUnitOwnerRowsWriteTarget(index) {
  if (index === state.activeTitleUnitIndex) {
    state.tables = state.tables || {};
    state.tables.title = state.tables.title || [];
    return state.tables.title;
  }
  if (index === 0) {
    if (!state.primaryTitleUnitShadow || typeof state.primaryTitleUnitShadow !== "object") {
      state.primaryTitleUnitShadow = { fields: {}, tables: {} };
    }
    state.primaryTitleUnitShadow.tables = state.primaryTitleUnitShadow.tables || {};
    state.primaryTitleUnitShadow.tables.title = state.primaryTitleUnitShadow.tables.title || [];
    return state.primaryTitleUnitShadow.tables.title;
  }
  if (!Array.isArray(state.titleUnits)) state.titleUnits = [];
  if (!state.titleUnits[index - 1]) state.titleUnits[index - 1] = createEmptyTitleUnit();
  const unit = state.titleUnits[index - 1];
  unit.tables = unit.tables || {};
  unit.tables.title = unit.tables.title || [];
  return unit.tables.title;
}

// Tek bir taşınmazın TEK bir malik satırındaki TEK bir sütunu (c0..c4)
// yazar. rowIndex, mevcut satır sayısının ÖTESİNDEYSE (ör. "Malik ekle"
// sonrası ilk yazım) aradaki boşluk boş `{}` satırlarla doldurulur —
// çağıran taraf (popover) satırları HER ZAMAN ardışık indeksle
// oluşturduğundan bu normalde tetiklenmez, savunma amaçlı.
function setTitleUnitOwnerRowValue(index, rowIndex, columnKey, value) {
  if (!Number.isInteger(index) || index < 0 || index >= getTitleUnitCount()) return false;
  if (!Number.isInteger(rowIndex) || rowIndex < 0 || !columnKey) return false;
  const rows = resolveTitleUnitOwnerRowsWriteTarget(index);
  while (rows.length <= rowIndex) rows.push({});
  rows[rowIndex][columnKey] = value;
  return true;
}

// resolveTitleUnitOwnerRowsWriteTarget()'ın (yukarıda) BİREBİR ikizi —
// yalnızca `tables.title` yerine `tables.documents` ("İncelenen belgeler"
// tablosu). Belgeler ve Proje blok-senkronunun (syncDocumentsSharedDataToBlockSiblings,
// 2026-08-19) aktif OLMAYAN blok kardeşlerine tablo satırlarını yazması
// için — SADECE state mutasyonu yapar, render()/saveState() ÇAĞIRMAZ.
function resolveTitleUnitDocumentsRowsWriteTarget(index) {
  if (index === state.activeTitleUnitIndex) {
    state.tables = state.tables || {};
    state.tables.documents = state.tables.documents || [];
    return state.tables.documents;
  }
  if (index === 0) {
    if (!state.primaryTitleUnitShadow || typeof state.primaryTitleUnitShadow !== "object") {
      state.primaryTitleUnitShadow = { fields: {}, tables: {} };
    }
    state.primaryTitleUnitShadow.tables = state.primaryTitleUnitShadow.tables || {};
    state.primaryTitleUnitShadow.tables.documents = state.primaryTitleUnitShadow.tables.documents || [];
    return state.primaryTitleUnitShadow.tables.documents;
  }
  if (!Array.isArray(state.titleUnits)) state.titleUnits = [];
  if (!state.titleUnits[index - 1]) state.titleUnits[index - 1] = createEmptyTitleUnit();
  const unit = state.titleUnits[index - 1];
  unit.tables = unit.tables || {};
  unit.tables.documents = unit.tables.documents || [];
  return unit.tables.documents;
}

// resolveTitleUnitDocumentsRowsWriteTarget()'ın (yukarıda) BİREBİR ikizi —
// "building" (Ana Gayrimenkul) bölümünün Kat Satırları tablosu için.
// Tüketicisi: syncBuildingSharedDataToBlockSiblings().
function resolveTitleUnitBuildingFloorsRowsWriteTarget(index) {
  if (index === state.activeTitleUnitIndex) {
    state.tables = state.tables || {};
    state.tables.buildingFloors = state.tables.buildingFloors || [];
    return state.tables.buildingFloors;
  }
  if (index === 0) {
    if (!state.primaryTitleUnitShadow || typeof state.primaryTitleUnitShadow !== "object") {
      state.primaryTitleUnitShadow = { fields: {}, tables: {} };
    }
    state.primaryTitleUnitShadow.tables = state.primaryTitleUnitShadow.tables || {};
    state.primaryTitleUnitShadow.tables.buildingFloors = state.primaryTitleUnitShadow.tables.buildingFloors || [];
    return state.primaryTitleUnitShadow.tables.buildingFloors;
  }
  if (!Array.isArray(state.titleUnits)) state.titleUnits = [];
  if (!state.titleUnits[index - 1]) state.titleUnits[index - 1] = createEmptyTitleUnit();
  const unit = state.titleUnits[index - 1];
  unit.tables = unit.tables || {};
  unit.tables.buildingFloors = unit.tables.buildingFloors || [];
  return unit.tables.buildingFloors;
}

// resolveTitleUnitBuildingFloorsRowsWriteTarget()'ın (yukarıda) BİREBİR
// ikizi — "unit" (Bağımsız Bölüm Özellikleri) bölümünün Katlar/Alanlar/
// Teraslar/İç Hacimler tablosu için. Tüketicisi: applyUnitDataToSelectedTitleUnits()
// (kullanıcı talebi, 2026-08-20: seçili taşınmazlara kopyalama).
function resolveTitleUnitUnitFloorsRowsWriteTarget(index) {
  if (index === state.activeTitleUnitIndex) {
    state.tables = state.tables || {};
    state.tables.unitFloors = state.tables.unitFloors || [];
    return state.tables.unitFloors;
  }
  if (index === 0) {
    if (!state.primaryTitleUnitShadow || typeof state.primaryTitleUnitShadow !== "object") {
      state.primaryTitleUnitShadow = { fields: {}, tables: {} };
    }
    state.primaryTitleUnitShadow.tables = state.primaryTitleUnitShadow.tables || {};
    state.primaryTitleUnitShadow.tables.unitFloors = state.primaryTitleUnitShadow.tables.unitFloors || [];
    return state.primaryTitleUnitShadow.tables.unitFloors;
  }
  if (!Array.isArray(state.titleUnits)) state.titleUnits = [];
  if (!state.titleUnits[index - 1]) state.titleUnits[index - 1] = createEmptyTitleUnit();
  const unit = state.titleUnits[index - 1];
  unit.tables = unit.tables || {};
  unit.tables.unitFloors = unit.tables.unitFloors || [];
  return unit.tables.unitFloors;
}

// Boş bir malik satırı ekler, YENİ satırın index'ini döner.
function addTitleUnitOwnerRow(index) {
  if (!Number.isInteger(index) || index < 0 || index >= getTitleUnitCount()) return -1;
  const rows = resolveTitleUnitOwnerRowsWriteTarget(index);
  rows.push({});
  return rows.length - 1;
}

function removeTitleUnitOwnerRow(index, rowIndex) {
  if (!Number.isInteger(index) || index < 0 || index >= getTitleUnitCount()) return false;
  const rows = resolveTitleUnitOwnerRowsWriteTarget(index);
  if (!Number.isInteger(rowIndex) || rowIndex < 0 || rowIndex >= rows.length) return false;
  rows.splice(rowIndex, 1);
  return true;
}

function syncMultiTitleUnitOwnershipType(value = state.fields.ownershipType) {
  const primaryFields = getTitleUnitFieldsForLabel(0) || {};
  const sourceValue = String(primaryFields.ownershipType || value || "").trim();
  if (!MULTI_TITLE_UNIT_OWNERSHIP_TYPES.has(sourceValue) || getTitleUnitCount() <= 1) return false;
  state.fields.ownershipType = sourceValue;
  if (state.primaryTitleUnitShadow?.fields) {
    state.primaryTitleUnitShadow.fields.ownershipType = sourceValue;
  }
  (state.titleUnits || []).forEach((unit) => {
    unit.fields = unit.fields || {};
    unit.fields.ownershipType = sourceValue;
  });
  return true;
}

// Aktif taşınmazı (birincil HARİÇ) siler. Önce birincile geçerek aktif
// taşınmazın son verisini kendi yuvasına düzgünce "check-in" eder, sonra
// diziden çıkarır — switchActiveTitleUnit'in mevcut mantığını tekrar
// yazmak yerine yeniden kullanır.
function removeActiveTitleUnitTab() {
  if (state.activeTitleUnitIndex === 0) return false;
  const removedIndex = state.activeTitleUnitIndex;
  switchActiveTitleUnit(0);
  state.titleUnits.splice(removedIndex - 1, 1);
  return true;
}

// Tab çubuğu UI'ı — yalnızca "title"/"encumbrance" sekmelerinde, EN ÜSTTE
// (kullanıcı talimatı) render edilir (bkz. renderSection). Admin-only:
// deneysel, gerçek rapor verisini değiştirdiği için (önizleme panelinin
// aksine) daha temkinli, kısıtlı bir kitleyle başlatılıyor.
// Kullanıcı talebi (2026-08-21): "seçili taşınmazlara kopyala butonunu
// bağımsız bölüm tablarının sonuna aynı punto ve biçimde taşı" — bu ortak
// tab çubuğu Tapu/Adres/İmar/Arsa/Değerleme/Bağımsız Bölüm'ün TAMAMINDA
// kullanıldığından (bkz. aşağıdaki not), "Seçili Taşınmazlara Kopyala"
// butonu BURAYA sabit-kodlanamaz (yalnızca "unit" bölümüne özgü) — bunun
// yerine genel bir `options.extraActions` (DOM node dizisi) parametresi
// eklendi, "+ Taşınmaz Ekle"/"Bu taşınmazı sil" butonlarının HEMEN
// ARDINA (actions satırının SONUNA) eklenir. Diğer 5 çağrı yeri parametre
// GEÇMEDEN (`createTitleUnitTabBar()`) çağırmaya devam eder — GERİYE
// DÖNÜK UYUMLU, davranışları değişmez.
function createTitleUnitTabBar(options = {}) {
  const wrap = document.createElement("div");
  wrap.className = "title-unit-tab-bar";

  const tabs = document.createElement("div");
  tabs.className = "title-unit-tab-bar-tabs";
  getTitleUnitTabModels().forEach((tab) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "title-unit-tab";
    button.classList.toggle("is-active", tab.isActive);
    button.textContent = tab.label;
    button.addEventListener("click", () => {
      if (!switchActiveTitleUnit(tab.index)) return;
      saveState();
      render();
    });
    tabs.append(button);
  });
  wrap.append(tabs);

  const actions = document.createElement("div");
  actions.className = "title-unit-tab-bar-actions";

  const addButton = document.createElement("button");
  addButton.type = "button";
  addButton.className = "title-unit-tab-add";
  addButton.textContent = "+ Taşınmaz Ekle";
  addButton.addEventListener("click", () => {
    const newIndex = addTitleUnitTab();
    switchActiveTitleUnit(newIndex);
    saveState();
    render();
  });
  actions.append(addButton);

  if (state.activeTitleUnitIndex !== 0) {
    const removeButton = document.createElement("button");
    removeButton.type = "button";
    removeButton.className = "title-unit-tab-remove";
    removeButton.textContent = "Bu taşınmazı sil";
    removeButton.addEventListener("click", () => {
      if (!window.confirm("Bu ek taşınmazı ve girilen tüm Tapu ve Mülkiyet/Takyidat verilerini silmek istediğinize emin misiniz?")) return;
      if (!removeActiveTitleUnitTab()) return;
      saveState();
      render();
    });
    actions.append(removeButton);
  }
  (options.extraActions || []).forEach((node) => actions.append(node));
  wrap.append(actions);

  // 2026-08-20: BAYAT metin düzeltildi — bu ortak tab çubuğu artık Tapu/
  // Adres/İmar (koşullu)/Arsa (koşullu)/Değerleme/Bağımsız Bölüm bölümlerinin
  // TAMAMINDA kullanılıyor (Belgeler ve Ana Gayrimenkul kendi blok-tab
  // varyantını kullanıyor, bkz. createDocumentsBlockTabBar/createBuildingBlockTabBar).
  // Eski metin hangi bölümlerin "henüz bağlı değil" olduğunu TEK TEK
  // sayıyordu — bu liste her yeni bölüm eklendiğinde bayatlıyordu (bkz.
  // handoff.md, defalarca yaşandı). Artık bölüm adı SAYMIYOR, jenerik ve
  // her zaman doğru kalacak şekilde yazıldı.
  const note = document.createElement("p");
  note.className = "muted-note title-unit-tab-bar-note";
  note.textContent = "Deneysel: bu bölümde girilen veri, sekmesi görüntülenen her taşınmaz için ayrı ayrı tutulur ve tab değiştirildiğinde otomatik kaydedilir.";
  wrap.append(note);

  return wrap;
}

// Kullanıcı talebi (2026-08-20/21): "aktif bulunduğum bağımsız bölümün
// bilgilerini istediğim bağımsız bölümlere kopyalamak" — checkbox+otomatik-
// tetikleme DEĞİL, çünkü hedef bir ALT KÜME seçimi gerektiriyor, bu yüzden
// bir düğme + modal (bkz. openUnitCopyToSelectedModal).
//
// Kullanıcı takip talebi (2026-08-21): "seçili taşınmazlara kopyala
// butonunu bağımsız bölüm tablarının sonuna aynı punto ve biçimde taşı" —
// İLK sürümde createLandApplyAllControl() gibi tab çubuğunun ALTINDA ayrı
// bir `.secondary-button` bloktu; şimdi createTitleUnitTabBar()'ın
// `extraActions`'ına (bkz. yukarıda) verilen, "+ Taşınmaz Ekle"/"Bu
// taşınmazı sil" ile AYNI `.title-unit-tab-add`/`.title-unit-tab-remove`
// punto/biçimini paylaşan (.title-unit-tab-copy-selected, styles.css) bir
// düğüm döner — tab çubuğunun actions satırının SONUNA eklenir. NOT: Arsa
// Özellikleri'ndeki KARDEŞ araç (createLandCopyToSelectedControl) BİLEREK
// DOKUNULMADI — kullanıcı yalnızca "bağımsız bölüm tabları"ndan bahsetti,
// Land kendi ayrı `.unit-copy-to-selected-wrap` blok stilinde kalmaya
// devam ediyor.
function createUnitCopyToSelectedControl() {
  const wrap = document.createElement("span");
  wrap.className = "title-unit-tab-copy-selected-wrap";

  const button = document.createElement("button");
  button.type = "button";
  button.className = "title-unit-tab-copy-selected";
  button.textContent = "Seçili Taşınmazlara Kopyala";

  const note = document.createElement("small");
  note.className = "muted-note unit-copy-to-selected-note";

  button.addEventListener("click", () => {
    if (getTitleUnitCount() < 2) return;
    openUnitCopyToSelectedModal((appliedCount) => {
      note.textContent = appliedCount
        ? `${appliedCount} bağımsız bölüme kopyalandı.`
        : "Hiçbir taşınmaz seçilmedi, kopyalama yapılmadı.";
    });
  });

  wrap.append(button, note);
  return wrap;
}

// openTitleRecordChangeModal()'ın (bkz. .checkbox-list/.checkbox-row —
// zaten stillenmiş, çalışan bir özellikte kullanılıyor) BİREBİR şablonu —
// hedef listesi getTitleUnitTabModels()'ten (aktif taşınmaz HARİÇ) gelir.
// Kaydet handler'ı applyUnitDataToSelectedTitleUnits()'i çağırıp ardından
// createTitleUnitTabBar()'ın ekle/sil butonlarıyla AYNI deseni (saveState()+
// render(), autosave() DEĞİL — bu münferit alan düzenlemesi değil YAPISAL
// çoklu-taşınmaz mutasyonu) izler.
function openUnitCopyToSelectedModal(onDone = () => {}) {
  document.querySelector(".modal-overlay")?.remove();

  const targets = getTitleUnitTabModels().filter((tab) => !tab.isActive);
  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  overlay.innerHTML = `
    <div class="modal-card modal-card-wide" role="dialog" aria-modal="true" aria-labelledby="unitCopyToSelectedModalTitle">
      <div class="modal-head">
        <h3 id="unitCopyToSelectedModalTitle">Bağımsız Bölüm Bilgilerini Kopyala</h3>
        <button class="modal-close" type="button" aria-label="Kapat">×</button>
      </div>
      <div class="modal-body">
        <p class="modal-lead">Aktif taşınmazın Bağımsız Bölüm Özellikleri bilgileri (genel/alan-iç mekan/dekoratif bilgiler ve Katlar, Alanlar ve İç Hacimler tablosu) seçtiğiniz taşınmazlara kopyalanacak.</p>
        <div class="checkbox-list">
          ${targets.map((tab) => `
            <label class="checkbox-row">
              <input type="checkbox" value="${tab.index}" data-unit-copy-target>
              <span>${escapeHtml(tab.label)}</span>
            </label>
          `).join("")}
        </div>
      </div>
      <div class="modal-actions">
        <button class="secondary-button" type="button" data-unit-copy-select-all>Tümünü Seç</button>
        <button class="secondary-button" type="button" data-unit-copy-clear>Seçimi Temizle</button>
        <button class="secondary-button" type="button" data-unit-copy-cancel>Vazgeç</button>
        <button class="primary-button" type="button" data-unit-copy-save>Seçilenlere Kopyala</button>
      </div>
    </div>
  `;

  const close = () => overlay.remove();
  overlay.querySelector(".modal-close").addEventListener("click", close);
  overlay.querySelector("[data-unit-copy-cancel]").addEventListener("click", close);
  overlay.addEventListener("click", (event) => {
    if (event.target === overlay) close();
  });
  overlay.querySelector("[data-unit-copy-select-all]").addEventListener("click", () => {
    overlay.querySelectorAll("[data-unit-copy-target]").forEach((box) => { box.checked = true; });
  });
  overlay.querySelector("[data-unit-copy-clear]").addEventListener("click", () => {
    overlay.querySelectorAll("[data-unit-copy-target]").forEach((box) => { box.checked = false; });
  });
  overlay.querySelector("[data-unit-copy-save]").addEventListener("click", () => {
    const selectedIndices = [...overlay.querySelectorAll("[data-unit-copy-target]:checked")]
      .map((box) => Number.parseInt(box.value, 10));
    const appliedCount = applyUnitDataToSelectedTitleUnits(selectedIndices);
    saveState();
    render();
    onDone(appliedCount);
    close();
  });

  document.body.append(overlay);
  overlay.querySelector("[data-unit-copy-target]")?.focus();
}

// "Belgeler ve Proje"nin YENİ 2 katmanlı (Blok → Bağımsız Bölüm) tab
// çubuğu (2026-08-19) — createTitleUnitTabBar()'ın (yukarıda) YAPISAL
// şablonu, AYNI `.title-unit-tab`/`.title-unit-tab-bar-tabs` CSS
// sınıfları yeniden kullanılır. DIŞ satır = bloklar (tıklama →
// switchActiveTitleUnit(group.unitIndices[0])); aktif bloğun 2+ üyesi
// varsa İÇ satır = o bloktaki bağımsız bölümler (tıklama →
// switchActiveTitleUnit(unitIndex)) — HER İKİ katman da AYNI mevcut
// switchActiveTitleUnit()/saveState()/render() üçlüsünü kullanır, YENİ
// bir state-geçiş mekanizması YOK. Taşınmaz ekle/sil butonları BİLEREK
// YOK (yapısal ekleme/silme Tapu sekmesinin mevcut tab çubuğundan yapılır
// — bkz. plan "Kapsam dışı").
function createDocumentsBlockTabBar() {
  const units = buildAllTitleUnitsForSummaryTable();
  const groups = computeDocumentsBlockGroups(units);

  const wrap = document.createElement("div");
  wrap.className = "title-unit-tab-bar documents-block-tab-bar";

  const outerTabs = document.createElement("div");
  outerTabs.className = "title-unit-tab-bar-tabs";
  const activeGroup = groups.find((group) => group.unitIndices.includes(state.activeTitleUnitIndex)) || groups[0];
  groups.forEach((group) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "title-unit-tab";
    button.classList.toggle("is-active", group === activeGroup);
    button.textContent = computeDocumentsBlockLabel(group, groups);
    button.addEventListener("click", () => {
      if (group === activeGroup) return;
      if (!switchActiveTitleUnit(group.unitIndices[0])) return;
      saveState();
      render();
    });
    outerTabs.append(button);
  });

  wrap.append(outerTabs);

  if (activeGroup && activeGroup.unitIndices.length > 1) {
    const innerTabs = document.createElement("div");
    innerTabs.className = "title-unit-tab-bar-tabs documents-block-unit-tabs";
    activeGroup.unitIndices.forEach((unitIndex, memberOrder) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "title-unit-tab title-unit-tab-secondary";
      button.classList.toggle("is-active", unitIndex === state.activeTitleUnitIndex);
      const unitNo = String(units[unitIndex]?.fields?.unitNo || "").trim();
      button.textContent = unitNo ? `${unitNo} no.lu BB` : `${memberOrder + 1}. BB`;
      button.addEventListener("click", () => {
        if (unitIndex === state.activeTitleUnitIndex) return;
        if (!switchActiveTitleUnit(unitIndex)) return;
        saveState();
        render();
      });
      innerTabs.append(button);
    });
    wrap.append(innerTabs);
  }

  const note = document.createElement("p");
  note.className = "muted-note title-unit-tab-bar-note";
  note.textContent = "Blok sekmesinde girilen bilgiler (İncelenen Belgeler, EKB, Statik Uygunluk, Yapı Denetim, Proje bilgileri vb.) o bloktaki TÜM bağımsız bölümlere otomatik uygulanır. Yalnızca \"Proje Uygunluk Durumu - Bağımsız Bölüm\" her bağımsız bölüme özeldir.";
  wrap.append(note);

  return wrap;
}

// createDocumentsBlockTabBar()'ın (yukarıda) BİREBİR ikizi — "Ana
// Gayrimenkul Özellikleri" (building) bölümü için. Kullanıcı talebi
// (2026-08-20): "Ana gayrimenkul bölümünde blok bazında açıklama olsun
// kaç adet blok var ise belgeler bölümünde yer aldığı gibi blok bazında o
// kadar ana gayrimenkul açıklaması olsun."
function createBuildingBlockTabBar() {
  const units = buildAllTitleUnitsForSummaryTable();
  const groups = computeDocumentsBlockGroups(units);

  const wrap = document.createElement("div");
  wrap.className = "title-unit-tab-bar building-block-tab-bar";

  const outerTabs = document.createElement("div");
  outerTabs.className = "title-unit-tab-bar-tabs";
  const activeGroup = groups.find((group) => group.unitIndices.includes(state.activeTitleUnitIndex)) || groups[0];
  groups.forEach((group) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "title-unit-tab";
    button.classList.toggle("is-active", group === activeGroup);
    button.textContent = computeDocumentsBlockLabel(group, groups);
    button.addEventListener("click", () => {
      if (group === activeGroup) return;
      if (!switchActiveTitleUnit(group.unitIndices[0])) return;
      saveState();
      render();
    });
    outerTabs.append(button);
  });

  const applyAllBlocksButton = document.createElement("button");
  applyAllBlocksButton.type = "button";
  applyAllBlocksButton.className = "title-unit-tab building-apply-all-blocks-button";
  applyAllBlocksButton.textContent = "Tüm bloklara uygula";
  applyAllBlocksButton.title = "Seçili bloktaki ana gayrimenkul özelliklerini diğer bloklara uygular";
  applyAllBlocksButton.addEventListener("click", () => {
    if (!applyBuildingDataToAllBlocks()) return;
    autosave();
    renderValidation();
    updateStatus();
    renderSection();
  });
  outerTabs.append(applyAllBlocksButton);

  wrap.append(outerTabs);

  if (activeGroup && activeGroup.unitIndices.length > 1) {
    const innerTabs = document.createElement("div");
    innerTabs.className = "title-unit-tab-bar-tabs building-block-unit-tabs";
    activeGroup.unitIndices.forEach((unitIndex, memberOrder) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "title-unit-tab title-unit-tab-secondary";
      button.classList.toggle("is-active", unitIndex === state.activeTitleUnitIndex);
      const unitNo = String(units[unitIndex]?.fields?.unitNo || "").trim();
      button.textContent = unitNo ? `${unitNo} no.lu BB` : `${memberOrder + 1}. BB`;
      button.addEventListener("click", () => {
        if (unitIndex === state.activeTitleUnitIndex) return;
        if (!switchActiveTitleUnit(unitIndex)) return;
        saveState();
        render();
      });
      innerTabs.append(button);
    });
    wrap.append(innerTabs);
  }

  const note = document.createElement("p");
  note.className = "muted-note title-unit-tab-bar-note";
  note.textContent = "Blok sekmesinde girilen Ana Gayrimenkul bilgileri (teknik özellikler, kat dağılımı, Ana Gayrimenkul Açıklaması) o bloktaki TÜM bağımsız bölümlere otomatik uygulanır.";
  wrap.append(note);

  return wrap;
}

// "Tapu ve Mülkiyet" sekmesinde, tab çubuğunun hemen altında — TÜM
// taşınmazların tapu özetini (bkz. buildTitleUnitsSummaryWordTableHtml,
// app.js) canlı önizler. Tekil raporda / ortak alanlar hiç
// farklılaşmıyorsa bilgilendirici bir not gösterir (tablo YOK demek
// "hata" değil, "henüz anlamlı bir fark yok" demek).
function createTitleUnitsSummaryTablePreview() {
  const wrap = document.createElement("div");
  wrap.className = "title-units-summary-table-preview";
  const heading = document.createElement("h5");
  heading.textContent = "Taşınmazlar Tapu Özeti";
  wrap.append(heading);

  // Faz 2 (Çift Yönlü Düzenleme, 2026-08-15): ekran önizlemesi artık
  // export'un paylaştığı buildTitleUnitsSummaryWordTableHtml() DEĞİL,
  // buildTitleUnitsSummaryTableData()'nın ham {headers, rows, columnMeta}
  // çıktısıyla beslenen AYRI, düzenlenebilir buildTitleUnitsSummaryTableHtmlEditable()
  // ile üretiliyor — export akışı (buildTitleUnitsSummaryWordTableHtml,
  // hâlâ eski salt-okunur renderer'ı kullanıyor) etkilenmez.
  const data = buildTitleUnitsSummaryTableData();
  if (!data || !data.rows.length) {
    const note = document.createElement("p");
    note.className = "muted-note";
    note.textContent = "Bu tablo yalnızca birden fazla taşınmaz eklendiğinde görünür. Banka şablonlarında {{TASINMAZLARTAPUTABLOSU}} olarak kullanılabilir.";
    wrap.append(note);
    return wrap;
  }
  const tableHtml = buildTitleUnitsSummaryTableHtmlEditable(data.headers, data.rows, data.columnMeta, state.activeTitleUnitIndex);
  const tableContainer = document.createElement("div");
  tableContainer.className = "title-units-summary-table-container";
  tableContainer.innerHTML = tableHtml;
  wrap.append(tableContainer);
  attachTitleUnitsSummaryTableEditing(tableContainer);
  const hint = document.createElement("p");
  hint.className = "muted-note";
  hint.textContent = "İl/İlçe/Mahalle/Mevkii/Pafta/Ada/Parsel/Yüzölçümü/Ana Taşınmaz Niteliği yalnızca taşınmazlar arasında FARKLIYSA gösterilir. Aktif taşınmazın hücrelerine tıklayarak doğrudan düzenleyebilirsiniz. Banka şablonlarında {{TASINMAZLARTAPUTABLOSU}} olarak kullanılabilir.";
  wrap.append(hint);
  return wrap;
}

