function refreshLandDescriptionFromCurrentFields(changedKey = "") {
  refreshLandDetailTextFieldsFromCurrentFields(changedKey);
  if (changedKey && !landDescriptionAutoRefreshFields.has(changedKey)) return;
  refreshLandMinimumParcelAssessment();
  const description = buildLandDescription();
  if (!description) return;
  state.fields.landNote = description;
  const control = document.querySelector('[data-field="landNote"]');
  if (control && control.value !== description) {
    control.value = description;
    markFieldSourceState(control, "landNote");
  }
}

// Kuveyt Türk arsa/arazi "ARSA BİLGİLERİ" 6 alt-alanını, landNote'u üreten
// mevcut cümle-üretim yapı taşlarını (buildLandAgriculturalProductSentence,
// buildLandAgricultureSentence, buildLandRoadFrontageSentence,
// buildLandBoundarySentence, buildLandMinimumParcelAssessmentSentence)
// YENİDEN KULLANARAK otomatik doldurur (kullanıcı talebi: "otomatik üret",
// landNote ile aynı mekanizma). Manuel düzenlenebilir, ilgili alan
// değişince üzerine yeniden yazılır.
function refreshLandDetailTextFieldsFromCurrentFields(changedKey = "") {
  if (changedKey && !landDetailTextAutoRefreshFields.has(changedKey)) return;
  const updates = {
    landUsageShapeText: buildLandUsageShapeSentence(),
    landUsagePurposeText: buildLandUsagePurposeSentence(),
    landDevelopmentObstacleText: buildLandDevelopmentObstacleSentence(),
    landInfrastructureTopographyText: buildLandInfrastructureTopographySentence(),
    landFrontageDepthText: buildLandFrontageDepthSentence(),
    landBoundaryStatusText: buildLandBoundaryStatusSentence(),
  };
  Object.keys(updates).forEach((key) => {
    const value = updates[key];
    if (!value) return;
    state.fields[key] = value;
    const control = document.querySelector(`[data-field="${key}"]`);
    if (control && control.value !== value) {
      control.value = value;
      markFieldSourceState(control, key);
    }
  });
}

function normalizeClimateLookupValue(value) {
  return foldTurkish(String(value || ""))
    .replace(/[()]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function findClimateEarthquakeRecord() {
  const rows = Array.isArray(globalThis.climateEarthquakeData) ? globalThis.climateEarthquakeData : [];
  const city = normalizeClimateLookupValue(state.fields.city || state.fields.titleCity);
  const district = normalizeClimateLookupValue(state.fields.district || state.fields.titleDistrict);
  if (!city || !district) return null;

  const cityRows = rows.filter((row) => normalizeClimateLookupValue(row.il) === city);
  return cityRows.find((row) => normalizeClimateLookupValue(row.ilce) === district)
    || cityRows.find((row) => normalizeClimateLookupValue(row.ilce).includes(district))
    || cityRows.find((row) => district.includes(normalizeClimateLookupValue(row.ilce)));
}

function formatClimateNumber(value, maximumFractionDigits = 0) {
  if (value === null || value === undefined || value === "") return "";
  return new Intl.NumberFormat("tr-TR", { maximumFractionDigits }).format(Number(value));
}

function formatEarthquakeZoneForReport(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  const normalized = raw.replace(/[–—]/g, "-").replace(/\s+/g, " ").trim();
  const match = normalized.match(/^(\d)\s*[-:]\s*(.+)$/);
  if (match) return `${match[1]}. Derece - ${match[2].trim()}`;
  return normalized;
}

function applyClimateEarthquakeAutoFields(record) {
  if (!record) return;

  const earthquakeZone = formatEarthquakeZoneForReport(record.depremBolgesi);
  if (!earthquakeZone) return;

  state.sourceValues.climateEarthquake = state.sourceValues.climateEarthquake || {};
  const previousAutoValue = state.sourceValues.climateEarthquake.applied?.earthquakeZone || "";
  const currentValue = state.fields.earthquakeZone || "";
  const shouldReplaceLegacyDefault = currentValue === "1. Derece" && !previousAutoValue;
  setFieldFromSource("climateEarthquake", "earthquakeZone", earthquakeZone, {
    force: shouldReplaceLegacyDefault,
  });

  const control = document.querySelector('[data-field="earthquakeZone"]');
  if (control && control.value !== state.fields.earthquakeZone) {
    control.value = state.fields.earthquakeZone || "";
  }
  if (control) markFieldSourceState(control, "earthquakeZone");
}

function isMultiTitleUnitReportForNarrative() {
  return typeof getTitleUnitCount === "function"
    ? getTitleUnitCount() > 1
    : Array.isArray(state.titleUnits) && state.titleUnits.length > 0;
}

function getNarrativeTitleUnitFields() {
  const count = typeof getTitleUnitCount === "function"
    ? getTitleUnitCount()
    : 1 + (Array.isArray(state.titleUnits) ? state.titleUnits.length : 0);
  return Array.from({ length: count }, (_, index) => {
    if (typeof getTitleUnitFieldsForLabel === "function") {
      return getTitleUnitFieldsForLabel(index) || {};
    }
    return index === 0 ? state.fields || {} : state.titleUnits?.[index - 1]?.fields || {};
  });
}

function getSharedNarrativeParcelPhrase() {
  if (!isMultiTitleUnitReportForNarrative()) return "";
  const units = getNarrativeTitleUnitFields();
  const first = units[0] || {};
  const firstBlock = String(first.blockNo || first.titleBlockNo || "").trim();
  const firstParcel = String(first.parcelNo || first.titleParcelNo || "").trim();
  if (!firstBlock || !firstParcel) return "";
  const sameParcel = units.every((unit) =>
    String(unit.blockNo || unit.titleBlockNo || "").trim() === firstBlock
    && String(unit.parcelNo || unit.titleParcelNo || "").trim() === firstParcel,
  );
  if (!sameParcel) return "";
  const blocks = [...new Set(units
    .map((unit) => String(unit.titleBlockName || unit.addressBlockName || unit.blockName || "").trim())
    .filter(Boolean))];
  const blockPhrase = blocks.length > 1
    ? ` ${blocks.join(", ")} bloklarda yer almaktadır`
    : "";
  return `${firstBlock} ada ${firstParcel} parsel üzerinde${blockPhrase}`;
}
function pluralizeEnvironmentalSubjectText(value, enabled = true) {
  if (!enabled || !value) return value;
  return String(value)
    .replace(/\bTaşınmazın\b/g, "Taşınmazların")
    .replace(/\bTaşınmaza\b/g, "Taşınmazlara")
    .replace(/\bTaşınmazda\b/g, "Taşınmazlarda")
    .replace(/\btaşınmazın\b/g, "taşınmazların")
    .replace(/\btaşınmaza\b/g, "taşınmazlara")
    .replace(/\btaşınmazda\b/g, "taşınmazlarda")
    .replace(/\bTaşınmaz\b/g, "Taşınmazlar")
    .replace(/\btaşınmaz\b/g, "taşınmazlar")
    .replace(/\bGayrimenkulün\b/g, "Gayrimenkullerin")
    .replace(/\bGayrimenkule\b/g, "Gayrimenkullere")
    .replace(/\bgayrimenkulün\b/g, "gayrimenkullerin")
    .replace(/\bgayrimenkule\b/g, "gayrimenkullere")
    .replace(/\bMülkün\b/g, "Mülklerin")
    .replace(/\bMülke\b/g, "Mülklere")
    .replace(/\bmülkün\b/g, "mülklerin")
    .replace(/\bmülke\b/g, "mülklere");
}

function getZiraatExplanationValues() {
  const value = (...keys) => keys.map((key) => String(state.fields?.[key] || "").trim()).find(Boolean) || "";
  return {
    city: value("city", "titleCity"),
    district: value("district", "titleDistrict"),
    neighborhood: value("neighborhood", "titleNeighborhood"),
    blockNo: value("blockNo", "titleBlockNo"),
    parcelNo: value("parcelNo", "titleParcelNo"),
    siteName: value("addressSiteName"),
    blockName: value("addressBlockName", "titleBlockName"),
    floor: value("addressFloor", "titleFloor"),
    unitNo: value("unitNo", "titleUnitNo"),
    nearby: value("nearby"),
    mainArtery: value("mainArtery"),
    infrastructureLevel: value("infrastructureLevel"),
    developmentDensity: value("developmentDensity"),
    socialNeeds: value("socialNeeds"),
    regionBuildingAge: value("regionBuildingAge"),
    incomeLevel: value("regionIncomeLevel"),
    developmentSpeed: value("developmentSpeed"),
    regionBuildOrder: value("regionBuildOrder"),
    regionUsePurpose: value("regionUsePurpose"),
    regionFloorRange: value("regionFloorRange"),
  };
}

function formatZiraatLocationSubject(values) {
  const isSharedMultiTitleUnitNarrative = isMultiTitleUnitReportForNarrative();
  const addressParts = [
    values.city && `${values.city} ili`,
    values.district && `${values.district} ilçesi`,
    values.neighborhood && `${values.neighborhood} mahallesi`,
    !isSharedMultiTitleUnitNarrative && values.blockNo && `${values.blockNo} ada`,
    !isSharedMultiTitleUnitNarrative && values.parcelNo && `${values.parcelNo} parsel`,
  ].filter(Boolean);
  const unitParts = [
    !isSharedMultiTitleUnitNarrative && values.siteName,
    !isSharedMultiTitleUnitNarrative && values.blockName && `${values.blockName} Blok`,
    !isSharedMultiTitleUnitNarrative && values.floor && `${values.floor}. Kat`,
    !isSharedMultiTitleUnitNarrative && values.unitNo && `${values.unitNo} no.lu bağımsız bölüm`,
  ].filter(Boolean);
  if (isSharedMultiTitleUnitNarrative) {
    const sharedParcelPhrase = getSharedNarrativeParcelPhrase();
    if (sharedParcelPhrase) {
      addressParts.push(sharedParcelPhrase);
      return `Ekspertize konu taşınmazlar, ${[...addressParts, ...unitParts].join(", ")}.`;
    }
  }
  if (!addressParts.length && !unitParts.length) return "Ekspertize konu taşınmaz";
  return `Ekspertize konu taşınmaz, ${[...addressParts, ...unitParts].join(", ")} üzerinde konumludur`;
}

function buildZiraatLocationEnvironmentalExplanation() {
  const values = getZiraatExplanationValues();
  const subject = formatZiraatLocationSubject(values);
  const sentences = [`${subject}.`];
  if (values.nearby) {
    const variants = [
      `Konu taşınmaza yakın konumda bulunan bilinen yerler; ${values.nearby} olarak ifade edilebilir.`,
      `Taşınmazın yakın çevresinde bulunan bilinen yerler arasında ${values.nearby} sayılabilir.`,
      `Söz konusu gayrimenkulün yakınında bulunan tanınmış yerler ${values.nearby} şeklinde sıralanabilir.`,
      `Mülkün yakın çevresindeki bilinen mekânlar ${values.nearby} olarak belirtilebilir.`,
    ];
    sentences.push(variants[selectVariant("buildZiraatLocationEnvironmentalExplanation:nearby", variants.length)]);
  }
  if (values.mainArtery) {
    const variants = [
      `Gayrimenkule ${values.mainArtery} güzergahında işleyen toplu taşıma araçları ve özel araç ile ulaşım mümkündür.`,
      `Taşınmaza ${values.mainArtery} güzergâhında hizmet veren toplu taşıma araçları ve özel araçla erişim sağlanabilmektedir.`,
      `${values.mainArtery} güzergâhı üzerinde çalışan toplu taşıma araçları ve özel araçlarla gayrimenkule ulaşım mümkündür.`,
      `Mülke, ${values.mainArtery} güzergâhında işleyen toplu taşıma hattı ve özel araç aracılığıyla erişilebilmektedir.`,
    ];
    sentences.push(variants[selectVariant("buildZiraatLocationEnvironmentalExplanation:mainArtery", variants.length)]);
  }
  if (values.infrastructureLevel) {
    const variants = [
      `Bölgesel altyapı ihtiyacı (yol, elektrik, su, doğalgaz, kanalizasyon vb.) ${values.infrastructureLevel} derecede karşılanabilmektedir.`,
      `Bölgenin altyapı ihtiyaçları (yol, elektrik, su, doğalgaz, kanalizasyon vb.) ${values.infrastructureLevel} düzeyde giderilebilmektedir.`,
      `Bölgesel altyapı hizmetleri (yol, elektrik, su, doğalgaz, kanalizasyon vb.) ${values.infrastructureLevel} ölçüde sağlanabilmektedir.`,
      `Bölgedeki altyapı ihtiyaçları (yol, elektrik, su, doğalgaz, kanalizasyon vb.) ${values.infrastructureLevel} seviyede karşılanmaktadır.`,
    ];
    sentences.push(variants[selectVariant("buildZiraatLocationEnvironmentalExplanation:infrastructure", variants.length)]);
  }
  return pluralizeEnvironmentalSubjectText(
    normalizeReportDescriptionText(sentences.join(" ")),
    isMultiTitleUnitReportForNarrative(),
  );
}
