function refreshZiraatExplanationSectionsFromCurrentFields() {
  const texts = {
    ziraatLocationEnvironmentalExplanation: buildZiraatLocationEnvironmentalExplanation(),
    ziraatDevelopmentAnalysisExplanation: buildZiraatDevelopmentAnalysisExplanation(),
    ziraatBuildingPatternExplanation: buildZiraatBuildingPatternExplanation(),
  };
  Object.assign(state.fields, texts);
  const panel = document.querySelector("[data-ziraat-explanation-sections]");
  if (panel) panel.hidden = !isZiraatBankSelectedForPropertyTaxDeclaration();
  Object.entries(texts).forEach(([key, text]) => {
    const control = document.querySelector(`[data-field="${key}"]`);
    if (control && control.value !== text) control.value = text;
    const panelText = document.querySelector(`[data-ziraat-explanation-text="${key}"]`);
    if (panelText) panelText.textContent = text || "Bu açıklama ilgili alanlar doldurulduğunda otomatik oluşur.";
  });
}

function createZiraatExplanationSectionsPanel() {
  refreshZiraatExplanationSectionsFromCurrentFields();
  const panel = document.createElement("div");
  panel.className = "ziraat-explanation-sections-panel";
  panel.hidden = !isZiraatBankSelectedForPropertyTaxDeclaration();
  panel.dataset.ziraatExplanationSections = "true";
  const sections = [
    ["Ziraat Bankası - Konumu ve Çevresel Özellikleri", "ziraatLocationEnvironmentalExplanation"],
    ["Ziraat Bankası - Bölgenin Gelişimine İlişkin Analiz", "ziraatDevelopmentAnalysisExplanation"],
    ["Ziraat Bankası - Bölgedeki Yapılaşma Durumu", "ziraatBuildingPatternExplanation"],
  ];
  sections.forEach(([titleText, key]) => {
    const card = document.createElement("div");
    card.className = "valuation-method-explanation-card ziraat-explanation-card";
    const head = document.createElement("div");
    head.className = "valuation-method-explanation-head";
    const title = document.createElement("h4");
    title.textContent = titleText;
    const copyButton = document.createElement("button");
    copyButton.type = "button";
    copyButton.className = "valuation-method-copy-button";
    copyButton.textContent = "Kopyala";
    copyButton.addEventListener("click", async () => {
      try {
        await navigator.clipboard.writeText(state.fields[key] || "");
        copyButton.textContent = "Kopyalandı";
      } catch {
        copyButton.textContent = "Kopyalanamadı";
      }
      setTimeout(() => { copyButton.textContent = "Kopyala"; }, 1500);
    });
    head.append(title, copyButton);
    const text = document.createElement("p");
    text.className = "valuation-method-explanation-text";
    text.dataset.ziraatExplanationText = key;
    text.textContent = state.fields[key] || "Bu açıklama ilgili alanlar doldurulduğunda otomatik oluşur.";
    card.append(head, text);
    panel.append(card);
  });
  return panel;
}

function buildClimateEarthquakeExplanation() {
  const record = findClimateEarthquakeRecord();
  if (!record) return "";

  const city = state.fields.city || state.fields.titleCity || record.il;
  const district = state.fields.district || state.fields.titleDistrict || record.ilce;
  const earthquakeZone = formatEarthquakeZoneForReport(
    state.fields.earthquakeZone || record.depremBolgesi,
  );
  const climateSentence = [
    `Taşınmazın konumlandığı ${city} ili, ${district} ilçesine ait iklimsel ve coğrafi veriler incelendiğinde;`,
    record.bolge ? `bölgenin ${record.bolge} Bölgesi iklim özelliklerini taşıdığı` : "",
    record.yagisSinifi ? `ve \"${record.yagisSinifi}\" yağış sınıfında yer aldığı görülmektedir.` : "görülmektedir.",
    record.rakimM !== null
      ? `Sahip olduğu yaklaşık ${formatClimateNumber(record.rakimM)} metre tahmini rakımla birlikte ilçede,`
      : "İlçede,",
    record.sicaklikC !== null
      ? `yıllık ortalama sıcaklık ${formatClimateNumber(record.sicaklikC, 1)} °C,`
      : "",
    record.nemYuzde !== null
      ? `yıllık ortalama nem oranı ise %${formatClimateNumber(record.nemYuzde)} olarak ölçülmektedir.`
      : "ölçülmektedir.",
    record.yagisMmYil !== null
      ? `Meteorolojik verilere göre yıllık ortalama ${formatClimateNumber(record.yagisMmYil)} mm yağış alan`
      : "Meteorolojik verilere göre yağış alan",
    record.guneslenmeSaatYil !== null
      ? `ve ${formatClimateNumber(record.guneslenmeSaatYil)} saatlik yıllık güneşlenme süresine sahip olan bölgede,`
      : "bölgede,",
    record.donGunu !== null
      ? `yıllık ortalama donlu gün sayısı ise ${formatClimateNumber(record.donGunu)} gün olarak tespit edilmiştir.`
      : "yıllık ortalama donlu gün sayısı tespit edilmiştir.",
    `Öte yandan yapısal risk ve planlama kriterleri açısından önem arz eden depremsellik verilerine göre söz konusu taşınmaz, \"${earthquakeZone}\" deprem bölgesinde yer almaktadır.`,
  ].filter(Boolean).join(" ");

  return normalizeReportDescriptionText(climateSentence);
}

function refreshClimateEarthquakeExplanationFromCurrentFields(changedKey = "") {
  if (changedKey && !["city", "district", "titleCity", "titleDistrict", "earthquakeZone"].includes(changedKey)) return;
  const record = findClimateEarthquakeRecord();
  applyClimateEarthquakeAutoFields(record);
  const text = buildClimateEarthquakeExplanation();
  state.fields.landClimateEarthquakeExplanation = text;
  const control = document.querySelector('[data-field="landClimateEarthquakeExplanation"]');
  if (control && control.value !== text) control.value = text;
  const panelText = document.querySelector("[data-land-climate-earthquake-text]");
  if (panelText) panelText.textContent = text || "İl ve ilçe seçildiğinde iklim ve deprem bilgileri burada oluşturulur.";
}

function createLandClimateEarthquakePanel() {
  refreshClimateEarthquakeExplanationFromCurrentFields();
  const text = state.fields.landClimateEarthquakeExplanation || "";
  if (!text) return null;

  const panel = document.createElement("div");
  panel.className = "land-climate-earthquake-panel";
  panel.innerHTML = `
    <div class="land-climate-earthquake-head">
      <h3>İklim ve Deprem Bilgileri</h3>
      <button type="button" class="secondary-button" data-copy-climate-earthquake> Kopyala </button>
    </div>
    <p data-land-climate-earthquake-text>${escapeHtml(text)}</p>
  `;
  panel.querySelector("[data-copy-climate-earthquake]").addEventListener("click", async () => {
    const button = panel.querySelector("[data-copy-climate-earthquake]");
    try {
      await navigator.clipboard.writeText(state.fields.landClimateEarthquakeExplanation || "");
      button.textContent = "Kopyalandı";
    } catch {
      button.textContent = "Kopyalanamadı";
    }
    setTimeout(() => { button.textContent = "Kopyala"; }, 1500);
  });
  return panel;
}

function buildLandDescription() {
  const sentences = [
    buildLandIdentitySentence(),
    buildLandGeometrySentence(),
    buildLandRoadFrontageSentence(),
    buildLandAgriculturalProductSentence(),
    buildLandAgricultureSentence(),
    buildLandBoundarySentence(),
  ].filter(Boolean);
  return normalizeReportDescriptionText(sentences.join(" "));
}

function buildLandIdentitySentence() {
  const subject = buildLandParcelSubject();
  const quality = normalizeReportTitleText(state.fields.mainPropertyQuality || state.fields.titleQuality || "Arsa") || "Arsa";
  const area = formatLandAreaForDescription(state.fields.landArea);
  return area
    ? `${subject}, tapu kaydında “${quality}” vasıflı olup ${area} yüzölçümüne sahiptir.`
    : `${subject}, tapu kaydında “${quality}” vasıflıdır.`;
}

function buildLandParcelSubject() {
  const blockNo = normalizeReportTitleText(state.fields.blockNo || "");
  const parcelNo = normalizeReportTitleText(state.fields.parcelNo || "");
  if (blockNo && parcelNo) return `Ekspertize konu ${blockNo} Ada ${parcelNo} Parsel`;
  if (parcelNo) return `Ekspertize konu ${parcelNo} Parsel`;
  return "Ekspertize konu taşınmaz";
}

function buildLandGeometrySentence() {
  const shape = toLowerText(state.fields.landShape || "");
  const topography = toLowerText(state.fields.landTopography || "");
  if (shape && topography) {
    return `Parsel geometrik olarak ${shape} forma sahip olup, topografik açıdan ${topography} zemin yapısındadır.`;
  }
  if (shape) return `Parsel geometrik olarak ${shape} forma sahiptir.`;
  if (topography) return `Parsel topografik açıdan ${topography} zemin yapısındadır.`;
  return "";
}

function buildLandRoadFrontageSentence() {
  const frontage = normalizeYesNoChoice(state.fields.landRoadFrontage);
  if (frontage === "Hayır") return "Konu parselin kadastro yoluna veya imar yoluna cephesi bulunmamaktadır.";
  if (frontage !== "Evet") return "";
  const items = getLandRoadFrontageItems()
    .map(formatLandRoadFrontagePhrase)
    .filter(Boolean);
  if (!items.length) return "";
  return `Konu parselin ${formatTurkishList(items)} cephesi bulunmaktadır.`;
}

function formatLandRoadFrontagePhrase(item = {}) {
  const direction = item.direction ? `${toLowerText(item.direction)} yönünde yer alan ` : "";
  const road = formatLandRoadNameForDescription(item);
  const length = formatLandFrontageLength(item.length);
  if (!road && !length) return "";
  return `${direction}${road || "kadastro/imar yoluna"}${length ? ` yaklaşık ${length}` : ""}`;
}

function formatLandRoadNameForDescription(item = {}) {
  const roadType = toLowerText(item.roadType || "");
  const roadName = normalizeReportTitleText(item.roadName || "");
  if (roadName) {
    return roadType.includes("imar") ? `${roadName} imar yoluna` : `${roadName} yoluna`;
  }
  if (roadType.includes("kadastro") && roadType.includes("imar")) return "kadastro ve imar yoluna";
  if (roadType.includes("imar")) return "imar yoluna";
  if (roadType.includes("kadastro")) return "kadastro yoluna";
  return "";
}

function formatLandFrontageLength(value) {
  const number = parseReportNumber(value);
  if (!Number.isFinite(number)) return normalizeReportTitleText(value || "");
  const formatted = number.toLocaleString("tr-TR", {
    minimumFractionDigits: Number.isInteger(number) ? 0 : 2,
    maximumFractionDigits: 2,
  });
  return `${formatted} metre`;
}

function buildLandAgriculturalProductSentence() {
  if (shouldHideLandAgricultureControls()) return "";
  const value = normalizeYesNoChoice(state.fields.landAgriculturalProduct);
  if (value === "Hayır") {
    return state.fields.landAgricultureType === "Kuru Tarım"
      ? "Taşınmaz üzerinde hâlihazırda herhangi bir zirai ürün bulunmamakta olup, parselin kuru tarım arazisi niteliğinde olduğu değerlendirilmektedir."
      : "Taşınmaz üzerinde hâlihazırda herhangi bir zirai ürün bulunmamaktadır.";
  }
  if (value !== "Evet") return "";
  const items = getLandAgriculturalProductItems();
  if (!items.length) return "";
  const productSentences = items
    .map(formatLandAgriculturalProductPhrase)
    .filter(Boolean);
  const yieldSentence = buildLandAgriculturalYieldSentence(items);
  return [productSentences.join(" "), yieldSentence].filter(Boolean).join(" ");
}

function formatLandAgriculturalProductPhrase(item = {}) {
  const totalCount = item.totalCount || calculateAgriculturalTotalCount(item.unitCount);
  const product = normalizeReportTitleText(item.productType || "");
  const age = normalizeReportTitleText(item.age || "");
  const parts = [];
  if (totalCount) parts.push(`yaklaşık ${totalCount} adet`);
  if (age) parts.push(`${age} yaşlarında`);
  if (product) parts.push(product);
  return parts.length ? `Taşınmaz üzerinde ${parts.join(" ")} mevcuttur.` : "";
}

function buildLandAgriculturalYieldSentence(items = []) {
  const firstYield = items.map((item) => item.yieldRate).find(Boolean) || state.fields.landAgriculturalYield || "";
  if (!firstYield) return "";
  const hasTree = items.some((item) => /ağaç|agac/i.test(foldTurkish(item.productType || "")));
  const subject = hasTree ? "Ağaçların" : "Zirai ürünlerin";
  if (/bakımsız|bakimsiz/i.test(foldTurkish(firstYield))) return `${subject} bakımsız oldukları gözlemlenmiştir.`;
  if (/yüksek|yuksek|bakımlı|bakimli/i.test(foldTurkish(firstYield))) return `${subject} bakımlı oldukları gözlemlenmiştir.`;
  if (/orta/i.test(foldTurkish(firstYield))) return `${subject} bakım durumunun orta düzeyde olduğu gözlemlenmiştir.`;
  return "";
}

function buildLandAgricultureSentence() {
  if (shouldHideLandAgricultureControls()) return "";
  const type = state.fields.landAgricultureType || "";
  if (type === "Kuru Tarım") {
    return normalizeYesNoChoice(state.fields.landAgriculturalProduct) === "Hayır"
      ? ""
      : "Parselin kuru tarım arazisi niteliğinde olduğu değerlendirilmektedir.";
  }
  if (type !== "Sulu Tarım") return "";
  const source = formatIrrigationWaterSourceForDescription(state.fields.landIrrigationWaterSource);
  const system = formatIrrigationSystemForDescription(state.fields.landIrrigationSystem);
  const sentences = [
    source
      ? `Taşınmazda sulu tarım yapılmakta olup, sulama ihtiyacı ${source} sağlanmaktadır.`
      : "Taşınmazda sulu tarım yapılmaktadır.",
    system ? `Parsel üzerinde ${system} sulama sistemi bulunmaktadır.` : "",
  ];
  return sentences.filter(Boolean).join(" ");
}

function getMinimumAgriculturalParcelLimit() {
  if (shouldHideLandAgricultureControls()) return null;
  const rows = Array.isArray(globalThis.MinimumAgriculturalParcelSizes) ? globalThis.MinimumAgriculturalParcelSizes : [];
  const city = foldTurkish(state.fields.titleCity || state.fields.city || "");
  const district = foldTurkish(state.fields.titleDistrict || state.fields.district || "");
  const area = parseReportNumber(state.fields.landArea);
  const agricultureType = normalizeReportTitleText(state.fields.landAgricultureType || "");
  const classification = normalizeReportTitleText(state.fields.landClassification || "");
  const row = rows.find((item) => foldTurkish(item.city) === city && foldTurkish(item.district) === district);
  if (!row || !Number.isFinite(area) || area <= 0 || !agricultureType || !classification) return null;

  const landKind = classification === "Dikili Tarım Arazisi"
    ? { label: "Dikili Arazi", key: "dikiliM2" }
    : agricultureType === "Sulu Tarım"
      ? { label: "Sulu Arazi", key: "suluM2" }
      : agricultureType === "Kuru Tarım"
        ? { label: "Kuru Arazi", key: "kuruM2" }
        : null;
  const minimum = landKind ? Number(row[landKind.key]) : Number.NaN;
  if (!landKind || !Number.isFinite(minimum) || minimum <= 0) return null;
  return {
    area,
    minimum,
    label: landKind.label,
    classification,
    agricultureType,
    city: state.fields.titleCity || state.fields.city,
    district: state.fields.titleDistrict || state.fields.district,
  };
}

function buildLandMinimumParcelAssessmentSentence() {
  if (shouldHideLandAgricultureControls()) return "";
  const city = state.fields.titleCity || state.fields.city || "";
  const district = state.fields.titleDistrict || state.fields.district || "";
  const area = parseReportNumber(state.fields.landArea);
  const agricultureType = normalizeReportTitleText(state.fields.landAgricultureType || "");
  const classification = normalizeReportTitleText(state.fields.landClassification || "");
  if (!city || !district || !Number.isFinite(area) || area <= 0 || !agricultureType) return "";
  if (!classification) {
    return `5403 sayılı Kanuna göre ${city}/${district} için minimum parsel kontrolü, Arazi Sınıflandırması bilgisi girilmediğinden yapılamamıştır.`;
  }
  const assessment = getMinimumAgriculturalParcelLimit();
  if (!assessment) {
    return `5403 sayılı Kanuna göre ${city}/${district} için Arazi Sınıflandırması ${classification} ve Tarım Türü ${agricultureType} bilgilerine ait minimum parsel verisi bulunamadığından kontrol yapılamamıştır.`;
  }
  const areaText = area.toLocaleString("tr-TR", { maximumFractionDigits: 2 });
  const minimumText = assessment.minimum.toLocaleString("tr-TR", { maximumFractionDigits: 2 });
  const result = area >= assessment.minimum ? "karşılamaktadır" : "karşılamamaktadır";
  return `Parselin ${areaText} m² yüzölçümü; Arazi Sınıflandırması ${assessment.classification} ve Tarım Türü ${assessment.agricultureType} dikkate alındığında, ${city}/${district} için ${assessment.label} bakımından 5403 sayılı Kanuna göre belirlenen ${minimumText} m² minimum parsel sınırını ${result}.`;
}

function refreshLandMinimumParcelAssessment() {
  const assessment = buildLandMinimumParcelAssessmentSentence();
  state.fields.landMinimumParcelAssessment = assessment;
  const control = document.querySelector('[data-field="landMinimumParcelAssessment"]');
  if (control && control.value !== assessment) control.value = assessment;
  const text = document.querySelector("[data-valuation-minimum-parcel-assessment-text]");
  if (text) text.textContent = assessment || "Minimum parsel kontrolü için gerekli tarım ve parsel bilgileri girilmelidir.";
}

function formatIrrigationWaterSourceForDescription(value) {
  const key = foldTurkish(value || "").toLocaleLowerCase("tr");
  const map = {
    "sulama kanali": "sulama kanallarından",
    "kuyu suyu": "kuyu suyundan",
    "sulama havuzu": "sulama havuzundan",
    "dere": "dereden",
    "cay": "çaydan",
    "nehir": "nehirden",
    "baraj": "barajdan",
    "sulama goleti": "sulama göletinden",
  };
  return map[key] || (value ? `${toLowerText(value)}ndan` : "");
}

function formatIrrigationSystemForDescription(value) {
  const key = foldTurkish(value || "").toLocaleLowerCase("tr");
  const map = {
    "damla sulama": "damlama tipi",
    "yer alti damla sulama": "yer altı damlama tipi",
    "yagmurlama sulama": "yağmurlama",
    "mikro yagmurlama": "mikro yağmurlama",
    "salma sulama": "salma",
    "karik sulama": "karık",
    "tava sulama": "tava",
    "pivot sulama": "pivot",
    "lineer hareketli sulama": "lineer hareketli",
  };
  return map[key] || toLowerText(value || "");
}

function buildLandBoundarySentence() {
  const value = normalizeYesNoChoice(state.fields.landBoundaryElement);
  if (value === "Hayır") return "Parsel sınırlarını arazide belirgin şekilde gösteren çit, duvar, tel örgü vb. herhangi bir unsur bulunmamaktadır.";
  if (value !== "Evet") return "";
  const items = [...getLandBoundaryElementItems()];
  if (state.fields.landBoundaryElementOther) items.push(state.fields.landBoundaryElementOther);
  const text = formatTurkishList(items.map(formatLandBoundaryElementForDescription).filter(Boolean));
  return text ? `Parsel sınırları ${text} ile belirgin vaziyettedir.` : "";
}

function formatLandBoundaryElementForDescription(item) {
  const text = toLowerText(item || "");
  if (!text) return "";
  if (foldTurkish(text) === "komsu parsel siniri") return "komşu parsel sınırları";
  return text;
}

// --- Kuveyt Türk arsa/arazi "ARSA BİLGİLERİ" 6 alt-alanı için cümle -------
// üretimi (0.0.42x, 2026-08-13). Mevcut landNote yapı taşları YENİDEN
// KULLANILIR; her biri kendi konusuna odaklanmış, tek başına anlamlı bir
// cümle/paragraf döner (veri eksikse "" döner, hiçbir varsayılan/olumlu
// kanaat cümlesi UYDURULMAZ).

function buildLandUsageShapeSentence() {
  // "Halihazırdaki Kullanım Şekli": parsel üzerinde fiilen ne var (boş/ekili/
  // dikili vb.) — mevcut zirai ürün cümlesiyle birebir örtüşüyor.
  return buildLandAgriculturalProductSentence();
}

function buildLandUsagePurposeSentence() {
  // "Halihazırdaki Kullanım Amacı": arazi sınıflandırması + tarım türü amacı.
  const classification = normalizeReportTitleText(state.fields.landClassification || "");
  const classificationSentence = classification
    ? `Parsel, Arazi Sınıflandırması bakımından ${classification} niteliğindedir.`
    : "";
  const agricultureSentence = buildLandAgricultureSentence();
  return [classificationSentence, agricultureSentence].filter(Boolean).join(" ");
}

function buildLandDevelopmentObstacleSentence() {
  // "Yapılaşmaya Engel Teşkil Edebilecek Unsurlar": yol cephesi yokluğu, çok
  // eğimli topografya ve 5403 sayılı Kanun'a göre minimum parsel büyüklüğünü
  // karşılamama — üçü de zaten başka yerlerde hesaplanan gerçek sinyaller.
  const parts = [];
  if (normalizeYesNoChoice(state.fields.landRoadFrontage) === "Hayır") {
    parts.push("Parselin kadastro veya imar yoluna cephesinin bulunmaması, yapılaşma açısından olumsuz bir unsur olarak değerlendirilmektedir.");
  }
  if (foldTurkish(state.fields.landTopography || "") === foldTurkish("Çok eğimli")) {
    parts.push("Parselin çok eğimli topografik yapısı, yapılaşmayı zorlaştırabilecek bir unsurdur.");
  }
  const minimumAssessment = buildLandMinimumParcelAssessmentSentence();
  if (minimumAssessment && minimumAssessment.includes("karşılamamaktadır")) {
    parts.push(minimumAssessment);
  }
  return parts.join(" ");
}

function buildLandInfrastructureTopographySentence() {
  // "Parselin Alt Yapısı ve Topografik Durumu": topografya (şekil HARİÇ,
  // {{LAND_SHAPE}} zaten ayrı satırda gösteriliyor — tekrar olmasın) + bölgedeki
  // altyapı seviyesi (infrastructureLevel, tüm taşınmazlarda paylaşımlı alan).
  const topography = toLowerText(state.fields.landTopography || "");
  const infrastructure = toLowerText(state.fields.infrastructureLevel || "");
  const parts = [];
  if (topography) parts.push(`Parsel topografik açıdan ${topography} zemin yapısındadır.`);
  if (infrastructure) parts.push(`Bölgedeki altyapı seviyesi ${infrastructure} olarak değerlendirilmektedir.`);
  return parts.join(" ");
}

function buildLandFrontageDepthSentence() {
  // "Parselin Cephe ve Derinlik Bilgileri": mevcut yol cephesi cümlesi
  // yeniden kullanılır. NOT: "derinlik" (parsel derinliği) için ayrı bir
  // veri alanı YOK — yalnızca cephe bilgisi üretilir, derinlik manuel
  // eklenmelidir.
  return buildLandRoadFrontageSentence();
}

function buildLandBoundaryStatusSentence() {
  // "Parselin Sınırlarının Durumu": mevcut sınır-unsuru cümlesiyle birebir.
  return buildLandBoundarySentence();
}

function formatLandAreaForDescription(value) {
  const number = parseReportNumber(value);
  if (Number.isFinite(number)) return formatSquareMeterArea(number);
  const text = normalizeReportTitleText(value || "");
  return text ? (/\bm²|\bm2/i.test(text) ? text : `${text} m²`) : "";
}

function getInsuranceConstructionCostRow(buildingClass = state.fields.buildingClass) {
  const selectedClass = String(buildingClass || "").trim();
  if (!selectedClass) return null;
  return insuranceConstructionCostRows.find((row) => row.group === selectedClass) || null;
}

function formatInsuranceUnitCost(value) {
  if (!Number.isFinite(value)) return "";
  return `${value.toLocaleString("tr-TR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} TL/m²`;
}

const insuranceConstructionCostExplanationVariants = [
  (group, cost) => `Ana gayrimenkul yapı sınıfı ${group} olarak seçildiğinden sigortaya esas yapı yaklaşık birim maliyeti ${cost} olarak alınmıştır.`,
  (group, cost) => `Ana gayrimenkulün yapı sınıfı ${group} olarak belirlendiğinden, sigortaya esas yaklaşık birim inşaat maliyeti ${cost} olarak dikkate alınmıştır.`,
  (group, cost) => `Yapı sınıfı ${group} olarak tespit edildiğinden, sigortaya esas yaklaşık birim maliyet ${cost} olarak hesaplanmıştır.`,
  (group, cost) => `Ana gayrimenkulün ${group} yapı sınıfına göre, sigortaya esas yaklaşık birim inşaat maliyeti ${cost} olarak öngörülmüştür.`,
];
registerVariantGroup("buildInsuranceConstructionCostExplanation", "Sigortaya Esas Yapı Birim Maliyeti Açıklaması (Değerleme)", insuranceConstructionCostExplanationVariants.length);

function buildInsuranceConstructionCostExplanation() {
  const row = getInsuranceConstructionCostRow();
  if (!row) return "";
  return normalizeReportDescriptionText(
    insuranceConstructionCostExplanationVariants[selectVariant("buildInsuranceConstructionCostExplanation", insuranceConstructionCostExplanationVariants.length)](
      row.group,
      formatInsuranceUnitCost(row.unitCost)
    )
  );
}

function refreshInsuranceConstructionCostFromCurrentFields(changedKey = "") {
  if (isLandOwnershipType()) {
    state.fields.insuranceConstructionClass = "";
    state.fields.insuranceUnitCost = "";
    state.fields.insuranceConstructionCostExplanation = "";
    return;
  }
  if (changedKey && changedKey !== "buildingClass") return;
  const row = getInsuranceConstructionCostRow();
  state.fields.insuranceConstructionClass = row?.group || "";
  state.fields.insuranceUnitCost = row ? formatInsuranceUnitCost(row.unitCost) : "";
  state.fields.insuranceConstructionCostExplanation = row ? buildInsuranceConstructionCostExplanation() : "";
  [
    "insuranceConstructionClass",
    "insuranceUnitCost",
    "insuranceConstructionCostExplanation",
  ].forEach((key) => {
    const control = document.querySelector(`[data-field="${key}"]`);
    if (control && control.value !== state.fields[key]) {
      control.value = state.fields[key] || "";
    }
  });
}

function getBuildingDepreciationAgeNumber() {
  const directAge = parseValuationNumber(state.fields.buildingAge);
  if (Number.isFinite(directAge)) return Math.max(0, Math.round(directAge));
  const completionDate = dateTrToIso(state.fields.buildingCompletionDate);
  if (!completionDate) return Number.NaN;
  const calculatedAge = calculateBuildingAgeText(completionDate);
  const number = parseValuationNumber(calculatedAge);
  return Number.isFinite(number) ? Math.max(0, Math.round(number)) : Number.NaN;
}

function getBuildingDepreciationAgeColumn(age = getBuildingDepreciationAgeNumber()) {
  if (!Number.isFinite(age)) return buildingDepreciationAgeColumns[0];
  return buildingDepreciationAgeColumns.find((column) => age >= column.min && age <= column.max) || buildingDepreciationAgeColumns[buildingDepreciationAgeColumns.length - 1];
}

function getBuildingDepreciationRow() {
  const style = foldTurkish(state.fields.buildingStyle || "").toLocaleUpperCase("tr");
  return buildingDepreciationRateRows.find((row) => row.match.some((item) => style.includes(item))) || buildingDepreciationRateRows[0];
}

function getBuildingDepreciationRate() {
  const row = getBuildingDepreciationRow();
  const column = getBuildingDepreciationAgeColumn();
  return Number(row?.[column.key] ?? 0);
}

function refreshBuildingDepreciationFromCurrentFields(changedKey = "") {
  if (isLandOwnershipType()) {
    state.fields.buildingDepreciationType = "";
    state.fields.buildingDepreciationRate = "";
    return;
  }
  if (changedKey && !["buildingAge", "buildingCompletionDate", "buildingStyle"].includes(changedKey)) return;
  const row = getBuildingDepreciationRow();
  const rate = getBuildingDepreciationRate();
  state.fields.buildingDepreciationType = row?.type || "";
  state.fields.buildingDepreciationRate = Number.isFinite(rate) ? `%${rate}` : "";
  ["buildingDepreciationType", "buildingDepreciationRate"].forEach((key) => {
    const control = document.querySelector(`[data-field="${key}"]`);
    if (control && control.value !== state.fields[key]) control.value = state.fields[key] || "";
  });
}

function createBuildingDepreciationRatePanel() {
  refreshBuildingDepreciationFromCurrentFields();
  const panel = document.createElement("div");
  panel.className = "subsection insurance-cost-panel";
  const header = document.createElement("div");
  header.className = "subsection-title-row";
  const title = document.createElement("h4");
  title.textContent = "Yapı Yıpranma Oranları";
  const description = document.createElement("p");
  description.textContent = "Yapı tarzı ve yapı yaşına göre değerleme hesabında kullanılacak yıpranma oranı otomatik seçilir.";
  header.append(title, description);

  const tableWrap = document.createElement("div");
  tableWrap.className = "insurance-cost-table-wrap";
  const table = document.createElement("table");
  table.className = "insurance-cost-table building-depreciation-table";
  table.innerHTML = `
    <thead>
      <tr>
        <th>İnşaatın Nevi</th>
        ${buildingDepreciationAgeColumns.map((column) => `<th>${column.label}</th>`).join("")}
      </tr>
    </thead>
  `;
  const tbody = document.createElement("tbody");
  const selectedType = state.fields.buildingDepreciationType || getBuildingDepreciationRow()?.type || "";
  const selectedColumn = getBuildingDepreciationAgeColumn();
  buildingDepreciationRateRows.forEach((row) => {
    const tr = document.createElement("tr");
    if (row.type === selectedType) tr.className = "is-selected";
    const typeCell = document.createElement("td");
    typeCell.textContent = row.type;
    tr.append(typeCell);
    buildingDepreciationAgeColumns.forEach((column) => {
      const cell = document.createElement("td");
      cell.textContent = String(row[column.key]);
      if (row.type === selectedType && column.key === selectedColumn.key) {
        cell.className = "is-selected";
      }
      tr.append(cell);
    });
    tbody.append(tr);
  });
  table.append(tbody);
  tableWrap.append(table);
  panel.append(header, tableWrap);
  return panel;
}

function formatSingleStructureCostCell(value, unit = "") {
  const text = String(value ?? "").trim();
  if (!text) return "-";
  const number = parseValuationNumber(text);
  if (!Number.isFinite(number)) return unit ? `${text} ${unit}` : text;
  const formatted = number.toLocaleString("tr-TR", {
    minimumFractionDigits: Number.isInteger(number) ? 0 : 2,
    maximumFractionDigits: 2,
  });
  return unit ? `${formatted} ${unit}` : formatted;
}

function singleStructureCostFormulaValue(value, unit = "") {
  return formatSingleStructureCostCell(value, unit);
}

function buildSingleStructureCostFormula(area, unitCost, constructionLevel, depreciationRate, result, unit) {
  const level = parseValuationNumber(constructionLevel);
  const levelFactor = Number.isFinite(level) && level === 100
    ? ""
    : ` × ${singleStructureCostFormulaValue(constructionLevel, "%")} / 100`;
  return `${singleStructureCostFormulaValue(area, "m²")} × ${singleStructureCostFormulaValue(unitCost, "TL/m²")}${levelFactor} × (1 - ${singleStructureCostFormulaValue(depreciationRate, "%")} / 100) = ${singleStructureCostFormulaValue(result, unit)}`;
}

function buildSingleStructureCostMethodRows() {
  refreshValuationComputedFields();
  return [
    {
      label: "Arsa Alanı",
      legal: state.fields.landArea,
      current: state.fields.landArea,
      unit: "m²",
    },
    {
      label: "Arsa Birim Değeri",
      legal: state.fields.landUnitValue,
      current: state.fields.landUnitValue,
      unit: "TL/m²",
    },
    {
      label: "Arsa Değeri",
      legal: state.fields.landValue,
      current: state.fields.landValue,
      unit: "TL",
      calculation: `${singleStructureCostFormulaValue(state.fields.landArea, "m²")} × ${singleStructureCostFormulaValue(state.fields.landUnitValue, "TL/m²")} = ${singleStructureCostFormulaValue(state.fields.landValue, "TL")}`,
      emphasis: true,
    },
    {
      label: "Tek Yapı Alanı",
      legal: state.fields.legalBuildingValueArea,
      current: state.fields.currentBuildingValueArea,
      unit: "m²",
    },
    {
      label: "Yapı Birim Maliyeti",
      legal: state.fields.legalBuildingUnitCost,
      current: state.fields.currentBuildingUnitCost,
      unit: "TL/m²",
    },
    {
      label: "İnşaat Seviyesi",
      legal: state.fields.legalBuildingConstructionLevel,
      current: state.fields.currentBuildingConstructionLevel,
      unit: "%",
    },
    {
      label: "Yıpranma Oranı",
      legal: state.fields.legalBuildingDepreciationRate,
      current: state.fields.currentBuildingDepreciationRate,
      unit: "%",
    },
    {
      label: "Yapı Değeri",
      legal: state.fields.legalBuildingValue,
      current: state.fields.currentBuildingValue,
      unit: "TL",
      calculation: `Yasal: ${buildSingleStructureCostFormula(state.fields.legalBuildingValueArea, state.fields.legalBuildingUnitCost, state.fields.legalBuildingConstructionLevel, state.fields.legalBuildingDepreciationRate, state.fields.legalBuildingValue, "TL")}\nMevcut: ${buildSingleStructureCostFormula(state.fields.currentBuildingValueArea, state.fields.currentBuildingUnitCost, state.fields.currentBuildingConstructionLevel, state.fields.currentBuildingDepreciationRate, state.fields.currentBuildingValue, "TL")}`,
      emphasis: true,
    },
    {
      label: "Şerefiye / Çevre Düzenlemesi",
      legal: state.fields.legalPremiumValue,
      current: state.fields.currentPremiumValue,
      unit: "TL",
      calculation: `Yasal: ${singleStructureCostFormulaValue(state.fields.legalPremiumValue, "TL")} (${singleStructureCostFormulaValue(state.fields.legalPremiumRate, "%")}) / Mevcut: ${singleStructureCostFormulaValue(state.fields.currentPremiumValue, "TL")} (${singleStructureCostFormulaValue(state.fields.currentPremiumRate, "%")})`,
    },
    {
      label: "Toplam Değer",
      legal: state.fields.legalValue,
      current: state.fields.currentValue,
      unit: "TL",
      calculation: `Arsa Değeri + Yapı Değeri + Şerefiye / Çevre Düzenlemesi = Yasal: ${singleStructureCostFormulaValue(state.fields.legalValue, "TL")} / Mevcut: ${singleStructureCostFormulaValue(state.fields.currentValue, "TL")}`,
      emphasis: true,
    },
    {
      label: "Toplam m² Birim Değeri",
      legal: state.fields.legalValueUnit,
      current: state.fields.currentValueUnit,
      unit: "TL/m²",
      calculation: `Toplam Değer / Toplam Alan = Yasal: ${singleStructureCostFormulaValue(state.fields.legalValueUnit, "TL/m²")} / Mevcut: ${singleStructureCostFormulaValue(state.fields.currentValueUnit, "TL/m²")}`,
      emphasis: true,
    },
  ];
}

function getSingleStructureLandValueHeading() {
  const ownershipType = String(state.fields.ownershipType || "").trim();
  const isCondominiumEasement = ["Dikey Kat İrtifakı", "Yatay Kat İrtifakı"].includes(ownershipType);
  if (isCondominiumEasement) {
    const block = String(state.fields.titleBlockName || state.fields.blockName || "").trim();
    const unitNo = String(state.fields.unitNo || "").trim();
    const blockText = block ? (/\bblok$/i.test(block) ? block : `${block} Blok`) : "";
    return [blockText, unitNo && `${unitNo} B.B. No`, "Arsa Payı Değeri:"]
      .filter(Boolean)
      .join(" ") || "Arsa Payı Değeri:";
  }

  const blockNo = String(state.fields.blockNo || "").trim();
  const parcelNo = String(state.fields.parcelNo || "").trim();
  return [blockNo && `${blockNo} Ada`, parcelNo && `${parcelNo} Parsel`, "Arsa Değeri"]
    .filter(Boolean)
    .join(" ") || "Arsa Değeri";
}

function buildSingleStructureCostMethodText() {
  const rows = buildSingleStructureCostMethodRows();
  return [
    "TEK YAPIDAN OLUŞAN GAYRİMENKUL - MALİYET YÖNTEMİ",
    "Kalem | Yasal Durum | Mevcut Durum | Hesaplama Adımı | Birim",
    ...rows.map((row) => [
      row.label,
      formatSingleStructureCostCell(row.legal),
      formatSingleStructureCostCell(row.current),
      String(row.calculation || "Girdi").replace(/\n/g, " / "),
      row.unit,
    ].join(" | ")),
  ].join("\n");
}

function createSingleStructureCostMethodPanel() {
  if (isLandProjectReview()) return null;
  const panel = document.createElement("div");
  panel.className = "subsection single-structure-cost-method-panel";

  const head = document.createElement("div");
  head.className = "subsection-title-row";
  const title = document.createElement("h4");
  title.textContent = "Tek Yapı Maliyet Yöntemi Hesap Tablosu";
  const description = document.createElement("p");
  description.textContent = "Tek bir ana yapıdan oluşan gayrimenkul için yasal ve mevcut durum maliyet hesabı değerleme alanlarından otomatik gösterilir.";
  head.append(title, description);

  const copyButton = document.createElement("button");
  copyButton.type = "button";
  copyButton.className = "valuation-method-copy-button";
  copyButton.textContent = "Kopyala";
  copyButton.title = "Tek yapı maliyet tablosunu metin olarak kopyala";
  copyButton.addEventListener("click", async () => {
    try {
      await navigator.clipboard.writeText(buildSingleStructureCostMethodText());
      copyButton.textContent = "Kopyalandı";
    } catch {
      copyButton.textContent = "Kopyalanamadı";
    }
    setTimeout(() => {
      copyButton.textContent = "Kopyala";
    }, 1500);
  });
  head.append(copyButton);

  const hint = document.createElement("p");
  hint.className = "subtle-text";
  hint.textContent = "Bu sürüm tek yapı içindir. Yapı ekleme ve birden fazla bina satırı sonraki aşamada eklenecektir.";

  const shell = document.createElement("div");
  shell.className = "single-structure-cost-method-sections";

  const createGridRow = (columns, values, isHeader = false) => {
    const row = document.createElement("div");
    row.className = `single-structure-cost-method-grid-row${isHeader ? " is-header" : " is-value"}`;
    columns.forEach((column, index) => {
      const cell = document.createElement("div");
      const alignment = column.align || "right";
      cell.className = `single-structure-cost-method-grid-cell is-${alignment}${isHeader ? " is-header" : ""}`;
      if (!isHeader && column.identity) cell.classList.add("is-identity");
      cell.style.gridColumn = `span ${column.span}`;
      cell.textContent = isHeader ? column.label : values[index];
      if (!isHeader && index === columns.length - 1) cell.classList.add("is-emphasis");
      row.append(cell);
    });
    return row;
  };

  const createSection = (titleText, columns, values, formulaText = "") => {
    const section = document.createElement("section");
    section.className = "single-structure-cost-method-section";
    const sectionTitle = document.createElement("h5");
    sectionTitle.textContent = titleText;
    section.append(sectionTitle);

    const gridShell = document.createElement("div");
    gridShell.className = "single-structure-cost-method-grid-shell";
    gridShell.append(createGridRow(columns, [], true), createGridRow(columns, values));
    section.append(gridShell);

    if (formulaText) {
      const formula = document.createElement("p");
      formula.className = "single-structure-cost-method-formula";
      formula.textContent = formulaText;
      section.append(formula);
    }
    return section;
  };

  const createMultiRowSection = (titleText, columns, rows, formulaText = "") => {
    const section = document.createElement("section");
    section.className = "single-structure-cost-method-section";
    const sectionTitle = document.createElement("h5");
    sectionTitle.textContent = titleText;
    section.append(sectionTitle);

    const gridShell = document.createElement("div");
    gridShell.className = "single-structure-cost-method-grid-shell";
    gridShell.append(createGridRow(columns, [], true));
    rows.forEach((row) => gridShell.append(createGridRow(columns, row)));
    section.append(gridShell);

    if (formulaText) {
      const formula = document.createElement("p");
      formula.className = "single-structure-cost-method-formula";
      formula.textContent = formulaText;
      section.append(formula);
    }
    return section;
  };

  const buildingClass = state.fields.buildingClass || state.fields.insuranceConstructionClass || "-";
  const buildingName = state.fields.buildingName || "Ana Yapı";
  const landShare = state.fields.share || "-";
  const landDenominator = state.fields.denominator || "-";
  const landValueHeading = getSingleStructureLandValueHeading();
  const legalConstructionLevel = parseValuationNumber(state.fields.legalBuildingConstructionLevel);
  const currentConstructionLevel = parseValuationNumber(state.fields.currentBuildingConstructionLevel);
  const legalShowsConstructionLevel = !Number.isFinite(legalConstructionLevel) || legalConstructionLevel !== 100;
  const currentShowsConstructionLevel = !Number.isFinite(currentConstructionLevel) || currentConstructionLevel !== 100;
  const gridColumn = (label, span, align = "right", identity = false) => ({ label, span, align, identity });
  const landColumns = [
    gridColumn("Başlık", 3, "right", true),
    gridColumn("Yüzölçümü", 3),
    gridColumn("Arsa Pay / Payda", 2),
    gridColumn("Arsa m² Birim Değeri", 2),
    gridColumn("Arsa Değeri", 2),
  ];
  const legalBuildingColumns = legalShowsConstructionLevel
    ? [
      gridColumn("Yapı Adı", 2, "right", true),
      gridColumn("Yapı Sınıfı", 1),
      gridColumn("Yapı Alanı", 2),
      gridColumn("İnşaat Seviyesi", 2),
      gridColumn("Yıpranma Oranı", 1),
      gridColumn("Yapı Birim Değeri", 2),
      gridColumn("Yapı Değeri", 2),
    ]
    : [
      gridColumn("Yapı Adı", 3, "right", true),
      gridColumn("Yapı Sınıfı", 1),
      gridColumn("Yapı Alanı", 2),
      gridColumn("Yıpranma Oranı", 2),
      gridColumn("Yapı Birim Değeri", 2),
      gridColumn("Yapı Değeri", 2),
    ];
  const currentBuildingColumns = currentShowsConstructionLevel
    ? [
      gridColumn("Yapı Adı", 2, "right", true),
      gridColumn("Yapı Sınıfı", 1),
      gridColumn("Yapı Alanı", 2),
      gridColumn("İnşaat Seviyesi", 2),
      gridColumn("Yıpranma Oranı", 1),
      gridColumn("Yapı Birim Değeri", 2),
      gridColumn("Yapı Değeri", 2),
    ]
    : [
      gridColumn("Yapı Adı", 3, "right", true),
      gridColumn("Yapı Sınıfı", 1),
      gridColumn("Yapı Alanı", 2),
      gridColumn("Yıpranma Oranı", 2),
      gridColumn("Yapı Birim Değeri", 2),
      gridColumn("Yapı Değeri", 2),
    ];
  const premiumColumns = [
    gridColumn("Durum", 3, "right", true),
    gridColumn("Arsa Değeri", 3),
    gridColumn("Yapı Değeri", 2),
    gridColumn("Şerefiye Oranı", 2),
    gridColumn("Şerefiye Tutarı", 2),
  ];
  const resultColumns = [
    gridColumn("Durum", 5, "right", true),
    gridColumn("Toplam m² Birim Değeri", 5),
    gridColumn("Toplam Değer", 2),
  ];

  shell.append(
    createSection(
      "Arsa Değeri",
      landColumns,
      [
        landValueHeading,
        formatSingleStructureCostCell(state.fields.landArea, "m²"),
        `${landShare} / ${landDenominator}`,
        formatSingleStructureCostCell(state.fields.landUnitValue, "TL/m²"),
        formatSingleStructureCostCell(state.fields.landValue, "TL"),
      ],
    ),
    createSection(
      "Yasal Yapı Değeri",
      legalBuildingColumns,
      [
        buildingName,
        buildingClass,
        formatSingleStructureCostCell(state.fields.legalBuildingValueArea, "m²"),
        ...(legalShowsConstructionLevel ? [formatSingleStructureCostCell(state.fields.legalBuildingConstructionLevel, "%")] : []),
        formatSingleStructureCostCell(state.fields.legalBuildingDepreciationRate, "%"),
        formatSingleStructureCostCell(state.fields.legalBuildingUnitCost, "TL/m²"),
        formatSingleStructureCostCell(state.fields.legalBuildingValue, "TL"),
      ],
    ),
    createSection(
      "Mevcut Yapı Değeri",
      currentBuildingColumns,
      [
        buildingName,
        buildingClass,
        formatSingleStructureCostCell(state.fields.currentBuildingValueArea, "m²"),
        ...(currentShowsConstructionLevel ? [formatSingleStructureCostCell(state.fields.currentBuildingConstructionLevel, "%")] : []),
        formatSingleStructureCostCell(state.fields.currentBuildingDepreciationRate, "%"),
        formatSingleStructureCostCell(state.fields.currentBuildingUnitCost, "TL/m²"),
        formatSingleStructureCostCell(state.fields.currentBuildingValue, "TL"),
      ],
    ),
    createMultiRowSection(
      "Şerefiye / Çevre Düzenlemesi",
      premiumColumns,
      [
        [
          "Yasal Durum",
          formatSingleStructureCostCell(state.fields.legalPremiumLandValue || state.fields.landValue, "TL"),
          formatSingleStructureCostCell(state.fields.legalBuildingValue, "TL"),
          formatSingleStructureCostCell(state.fields.legalPremiumRate, "%"),
          formatSingleStructureCostCell(state.fields.legalPremiumValue, "TL"),
        ],
        [
          "Mevcut Durum",
          formatSingleStructureCostCell(state.fields.currentPremiumLandValue || state.fields.landValue, "TL"),
          formatSingleStructureCostCell(state.fields.currentBuildingValue, "TL"),
          formatSingleStructureCostCell(state.fields.currentPremiumRate, "%"),
          formatSingleStructureCostCell(state.fields.currentPremiumValue, "TL"),
        ],
      ],
    ),
    createMultiRowSection(
      "Değerleme Sonucu",
      resultColumns,
      [
        [
          "Maliyet Yöntemine Göre Yasal Durum Değeri",
          formatSingleStructureCostCell(state.fields.legalValueUnit, "TL/m²"),
          formatSingleStructureCostCell(state.fields.legalValue, "TL"),
        ],
        [
          "Maliyet Yöntemine Göre Mevcut Durum Değeri",
          formatSingleStructureCostCell(state.fields.currentValueUnit, "TL/m²"),
          formatSingleStructureCostCell(state.fields.currentValue, "TL"),
        ],
      ],
      "Toplam Değer = Arsa Değeri + Yapı Değeri + Şerefiye / Çevre Düzenlemesi",
    ),
  );
  panel.append(head, hint, shell);
  return panel;
}

