const valuationMarketRows = [
  { label: "Yasal Durum Değeri", areaKey: "legalValueArea", unitKey: "legalValueUnit", totalKey: "legalValue", unitLabel: "M2 Birim Değeri" },
  { label: "Mevcut Durum Değeri", areaKey: "currentValueArea", unitKey: "currentValueUnit", totalKey: "currentValue", unitLabel: "M2 Birim Değeri" },
  { label: "Yasal Kira Değeri", areaKey: "legalRentArea", unitKey: "legalRentUnit", totalKey: "legalRent", unitLabel: "M2 Birim Değeri" },
  { label: "Mevcut Kira Değeri", areaKey: "currentRentArea", unitKey: "currentRentUnit", totalKey: "currentRent", unitLabel: "M2 Birim Değeri" },
];

const valuationUrgentSaleRows = [
  { label: "Yasal Acil Satış Değeri", marketKey: "legalValue", totalKey: "legalUrgentSaleValue" },
  { label: "Mevcut Acil Satış Değeri", marketKey: "currentValue", totalKey: "currentUrgentSaleValue" },
];

// Kullanıcı talebi (2026-08-19): "değerleme kısmında tab mantığı ve çift
// taraflı tablo mantığı olmalı" — kullanıcının netleştirmesiyle (alan×birim
// detayı DAHİL) kapsam Piyasa Değeri tablosunun TAMAMI. `valuationMarketRows`/
// `valuationUrgentSaleRows`'un (yukarıda) TEK kaynağından türetilir (drift
// riski olmadan) — her satır kendi Acil Satış karşılığını (varsa) taşır.
const VALUATION_UNITS_TABLE_ROW_DEFS = valuationMarketRows.map((row) => {
  const urgentSaleRow = valuationUrgentSaleRows.find((item) => item.marketKey === row.totalKey);
  return {
    ...row,
    includeArea: !row.totalKey.includes("Rent"),
    urgentSaleKey: urgentSaleRow ? urgentSaleRow.totalKey : null,
    urgentSaleLabel: urgentSaleRow ? urgentSaleRow.label : null,
  };
});

// Tabloyu (başlıklar + satırlar) hesaplar; YALNIZCA 2+ taşınmaz varsa bir
// sonuç döner (Tapu/Adres'in en basit deseni — Değerleme değerleri HER
// ZAMAN taşınmaza-özgüdür, ada/parsel veya bloğa göre koşullu paylaşım
// YOK). Piyasa değerinde Alan `scalar`, M2 Birim Değeri `readonly` ve
// Değer `scalar` sütunları; kira değerinde ise aynı alan tekrar edilmeden
// yalnızca M2 Birim Değeri `readonly` ve Kira Değeri `scalar` sütunları
// üretilir. Yasal/Mevcut piyasa satırları ayrıca Acil Satış Değeri
// (`readonly`) taşır.
function buildValuationUnitsSummaryTableData() {
  const units = buildAllTitleUnitsForSummaryTable();
  if (units.length < 2) return null;

  const headers = ["Sıra No"];
  const columnMeta = [{ kind: "seq" }];
  VALUATION_UNITS_TABLE_ROW_DEFS.forEach((row) => {
    if (row.includeArea) {
      headers.push(`${row.label} - Alan`);
      columnMeta.push({ kind: "scalar", fieldKey: row.areaKey });
    }
    headers.push(`${row.label} - ${row.unitLabel}`, row.label);
    columnMeta.push({ kind: "readonly" }, { kind: "scalar", fieldKey: row.totalKey });
    if (row.urgentSaleKey) {
      headers.push(row.urgentSaleLabel);
      columnMeta.push({ kind: "readonly" });
    }
  });

  const rows = units.map((unit, index) => {
    const fields = unit.fields || {};
    const row = [index + 1];
    VALUATION_UNITS_TABLE_ROW_DEFS.forEach((rowDef) => {
      if (rowDef.includeArea) {
        row.push(String(fields[rowDef.areaKey] || "").trim() || "-");
      }
      row.push(
        String(fields[rowDef.unitKey] || "").trim() || "-",
        String(fields[rowDef.totalKey] || "").trim() || "-",
      );
      if (rowDef.urgentSaleKey) {
        row.push(String(fields[rowDef.urgentSaleKey] || "").trim() || "-");
      }
    });
    return row;
  });

  // "eğer sistemde hücrede veri yoksa ... tabloda bu sütunlar gözükmemeli"
  // (Tapu/Adres/İmar/Arsa/Belgeler tablolarındaki AYNI kural — Arsa/Tarla
  // raporlarında Kira satırları zaten boş kalacağından, createValuationMarketTable'ın
  // KENDİ `landOwnership` filtresiyle TUTARLI şekilde bu sütunlar OTOMATİK
  // kalkar) — TÜM taşınmazlarda boş ("-") kalan bir sütun tamamen kaldırılır.
  const columnHasData = headers.map((_, columnIndex) => (
    columnIndex === 0 || rows.some((row) => {
      const value = row[columnIndex];
      return value !== undefined && value !== null && String(value).trim() !== "" && String(value).trim() !== "-";
    })
  ));
  const filteredHeaders = headers.filter((_, columnIndex) => columnHasData[columnIndex]);
  const filteredRows = rows.map((row) => row.filter((_, columnIndex) => columnHasData[columnIndex]));
  const filteredColumnMeta = columnMeta.filter((_, columnIndex) => columnHasData[columnIndex]);

  return { headers: filteredHeaders, rows: filteredRows, columnMeta: filteredColumnMeta };
}

function getValuationUnitsSummaryHeaderGroup(label) {
  const normalized = String(label || "");
  if (normalized.startsWith("Yasal ")) return "Yasal Durum Değeri";
  if (normalized.startsWith("Mevcut ")) return "Mevcut Durum Değeri";
  return "Diğer";
}

function getValuationUnitsSummarySubheader(label) {
  const normalized = String(label || "");
  if (normalized === "Sıra No") return "No";
  if (normalized.endsWith(" - Alan")) return "Alan\n(m²)";
  if (normalized.endsWith(" - M2 Birim Değeri")) {
    return normalized.includes("Kira") ? "Kira M2 Birim Değeri\n(TL/m²)" : "M2 Birim Değeri\n(TL/m²)";
  }
  if (normalized.includes("Acil Satış")) return "Acil Satış Değeri\n(TL)";
  if (normalized.includes("Kira Değeri")) return "Kira Değeri\n(TL/ay)";
  return "Piyasa Değeri\n(TL)";
}

// Çoklu değerleme özeti iki katmanlıdır: üst satır Yasal/Mevcut durum
// gruplarını, alt satır her grubun hesaplama sütunlarını gösterir. Aynı
// renderer ekran önizlemesi ve banka şablonu çıktısı tarafından kullanılır.
function buildValuationUnitsSummaryTableHtml(data, activeRowIndex, { editable = false } = {}) {
  const headers = data?.headers || [];
  const rows = data?.rows || [];
  const columnMeta = data?.columnMeta || [];
  if (!headers.length || !rows.length) return "";

  const ink = getReportThemeToken("--ink", "#152238");
  const line = getReportThemeToken("--line", "#dde3ef");
  const blue = getReportThemeToken("--blue", "#3a5691");
  const surface = getReportThemeToken("--surface", "#ffffff");
  const surfaceMuted = getReportThemeToken("--surface-muted", "#eef2fa");
  const border = `border:1pt solid ${line};`;
  const baseCell = `${border}padding:3pt 4pt;text-align:center;vertical-align:middle;line-height:1.15;color:${ink};background:${surface};font-size:6.5pt;white-space:normal;`;
  const headerCell = `${baseCell}background:${surfaceMuted};color:${blue};font-weight:800;`;
  const zebraCell = `${baseCell}background:${surfaceMuted};`;
  const groupedColumns = headers.slice(1).reduce((groups, label, offset) => {
    const group = getValuationUnitsSummaryHeaderGroup(label);
    if (!groups[group]) groups[group] = [];
    groups[group].push({ label, index: offset + 1 });
    return groups;
  }, {});
  const groupOrder = ["Yasal Durum Değeri", "Mevcut Durum Değeri", "Diğer"].filter((group) => groupedColumns[group]?.length);
  const topHeaderHtml = `<tr><th rowspan="2" style="${headerCell}">${toTitleFieldUppercase(headers[0])}</th>${groupOrder.map((group) => `<th colspan="${groupedColumns[group].length}" style="${headerCell}">${toTitleFieldUppercase(group)}</th>`).join("")}</tr>`;
  const subHeaderHtml = `<tr>${groupOrder.flatMap((group) => groupedColumns[group]).map(({ label }) => {
    const subheader = toTitleFieldUppercase(getValuationUnitsSummarySubheader(label));
    return `<th style="${headerCell}">${escapeHtml(subheader).replace(/\n/g, "<br>")}</th>`;
  }).join("")}</tr>`;
  const bodyHtml = rows.map((row, rowIndex) => {
    const cellStyle = rowIndex % 2 === 1 ? zebraCell : baseCell;
    const cellsHtml = row.map((cell, columnIndex) => {
      const meta = columnMeta[columnIndex] || null;
      const isEditable = editable && meta?.kind === "scalar";
      if (!isEditable) return `<td style="${cellStyle}">${formatWordCell(toTitleFieldUppercase(cell))}</td>`;
      return `<td style="${cellStyle}cursor:text;" class="tus-editable-cell" data-unit-index="${rowIndex}" data-field-key="${escapeHtml(meta.fieldKey)}" title="Düzenlemek için tıklayın">${formatWordCell(toTitleFieldUppercase(cell))}</td>`;
    }).join("");
    const rowAttr = editable && rowIndex === activeRowIndex ? ' class="tus-active-row"' : "";
    return `<tr${rowAttr}>${cellsHtml}</tr>`;
  }).join("");

  return `<table class="word-table title-units-summary-table title-units-summary-table${editable ? " title-units-summary-table-editable" : ""}" style="border-collapse:collapse;width:100%;margin:5pt 0 12pt;table-layout:auto;">
    <thead>${topHeaderHtml}${subHeaderHtml}</thead>
    <tbody>${bodyHtml}</tbody>
  </table>`;
}

