  add("insuranceValue", "Sigortaya Esas Değer");
  add("share", "Arsa Değeri - Arsa Payı");
  add("denominator", "Arsa Değeri - Arsa Payda");
  add("landArea", "Arsa Değeri - Yüzölçüm");
