function getBuildingFloorCounts() {
  const counts = state.fields.buildingFloorCounts && typeof state.fields.buildingFloorCounts === "object"
    ? state.fields.buildingFloorCounts
    : {};
  return buildingFloorCountFields.reduce((result, field) => {
    result[field.key] = normalizeNonNegativeInteger(counts[field.key]);
    return result;
  }, {});
}

function getBuildingBasementFloorCount() {
  return getBuildingFloorCounts().basement || "";
}

function getBuildingAboveRoadFloorCount() {
  const counts = getBuildingFloorCounts();
  const ground = Number.parseInt(counts.ground || "0", 10) || 0;
  const normal = Number.parseInt(counts.normal || "0", 10) || 0;
  const total = ground + normal;
  return total ? String(total) : "";
}

function getProjectSuitabilityDifferenceStatus() {
  if (shouldUseProjectDifferenceComparison()) {
    const titleSuitable = isProjectSuitabilityOk(state.fields.titleProjectSuitabilityStatus);
    const municipalitySuitable = isProjectSuitabilityOk(state.fields.municipalityProjectSuitabilityStatus);
    return titleSuitable && municipalitySuitable ? "YOK" : "VAR";
  }
  return isProjectSuitabilityOk(state.fields.projectSuitabilityStatus) ? "YOK" : "VAR";
}

function getPenaltyDecisionStatus() {
  return normalizeYesNoChoice(state.fields.penaltyDecision) === "Evet" ? "VAR" : "YOK";
}

function getLatestBuildingPermitStatus() {
  return getLatestBuildingPermitDocumentRow() ? "VAR" : "YOK";
}

function normalizeNonNegativeInteger(value) {
  const parsed = Number.parseInt(String(value || "").replace(/[^\d]/g, ""), 10);
  return Number.isFinite(parsed) && parsed > 0 ? String(parsed) : "";
}

function buildBuildingFloorRowsFromCounts(counts, existingRows = []) {
  const existingByName = new Map(
    existingRows
      .filter((row) => row?.floorName)
      .map((row) => [row.floorName, row])
  );
  return getBuildingFloorNamesFromCounts(counts).map((floorName) => ({
    floorName,
    common: existingByName.get(floorName)?.common || "",
    residential: existingByName.get(floorName)?.residential || "",
    shop: existingByName.get(floorName)?.shop || "",
    office: existingByName.get(floorName)?.office || "",
    storage: existingByName.get(floorName)?.storage || "",
  }));
}

function getBuildingFloorNamesFromCounts(counts) {
  const names = [];
  const basementCount = Number.parseInt(counts.basement || "0", 10) || 0;
  for (let index = basementCount; index >= 1; index -= 1) {
    names.push(`${index}. Bodrum`);
  }
  if ((Number.parseInt(counts.ground || "0", 10) || 0) > 0) names.push("Zemin");
  const mezzanineCount = Number.parseInt(counts.mezzanine || "0", 10) || 0;
  for (let index = 1; index <= mezzanineCount; index += 1) {
    names.push(mezzanineCount === 1 ? "Asma" : `${index}. Asma`);
  }
  const intermediateCount = Number.parseInt(counts.intermediate || "0", 10) || 0;
  for (let index = 1; index <= intermediateCount; index += 1) {
    names.push(intermediateCount === 1 ? "Ara" : `${index}. Ara`);
  }
  const normalCount = Number.parseInt(counts.normal || "0", 10) || 0;
  for (let index = 1; index <= normalCount; index += 1) {
    names.push(`${index}. Normal`);
  }
  const roofCount = Number.parseInt(counts.roof || "0", 10) || 0;
  for (let index = 1; index <= roofCount; index += 1) {
    names.push(roofCount === 1 ? "Çatı" : `${index}. Çatı`);
  }
  const terraceCount = Number.parseInt(counts.terrace || "0", 10) || 0;
  for (let index = 1; index <= terraceCount; index += 1) {
    names.push(terraceCount === 1 ? "Teras" : `${index}. Teras`);
  }
  return names;
}

function createBuildingFloorRowsTable() {
  const panel = document.createElement("div");
  panel.className = "subsection is-detail building-floor-table-panel";
  const rows = Array.isArray(state.tables.buildingFloors) ? state.tables.buildingFloors : [];
  state.tables.buildingFloors = rows;

  const heading = document.createElement("div");
  heading.className = "subsection-table-head";
  heading.innerHTML = `<h4>Kat Satırları</h4>`;

  const shell = document.createElement("div");
  shell.className = "table-shell";

  if (!rows.length) {
    const empty = document.createElement("p");
    empty.className = "empty-frontage-list";
    empty.textContent = "Kat adedi girilip Kaydet düğmesine basıldığında kat satırları burada oluşur.";
    shell.append(empty);
    panel.append(heading, shell);
    return panel;
  }

  const table = document.createElement("table");
  table.className = "table-building-floors";
  const thead = document.createElement("thead");
  thead.innerHTML = `
    <tr>
      <th>Kat Adı</th>
      ${buildingFloorUnitColumns.map((column) => `<th>${column.label}</th>`).join("")}
    </tr>
  `;
  const tbody = document.createElement("tbody");
  rows.forEach((row, rowIndex) => {
    const tr = document.createElement("tr");
    const nameCell = document.createElement("td");
    nameCell.textContent = row.floorName || "";
    tr.append(nameCell);

    buildingFloorUnitColumns.forEach((column) => {
      const td = document.createElement("td");
      const input = document.createElement("input");
      input.type = column.numeric ? "number" : "text";
      // Kullanıcı talebi: "ana taşınmaz katları ... TAB tuşuna basıldığında
      // alt hücreye geçmesini istiyorum" (Emsaller'deki gibi) — bkz.
      // attachBuildingFloorColumnTabNavigation, bu iki data-attribute'u
      // sütun/satır kimliği olarak kullanır.
      input.dataset.buildingFloorRow = String(rowIndex);
      input.dataset.buildingFloorColumn = column.key;
      if (column.numeric) {
        input.min = "0";
        input.step = "1";
        input.inputMode = "numeric";
      }
      if (column.freeText) {
        // Daha önce büyük/karışık harfle kaydedilmiş satırları da sessizce
        // düzeltir (kendi kendine iyileşme) — kullanıcı tekrar dokunmasa
        // bile hücre küçük harfle görünür.
        const formattedExisting = normalizeLowercaseFreeText(row[column.key] || "");
        if (formattedExisting !== (row[column.key] || "")) {
          row[column.key] = formattedExisting;
        }
        input.value = formattedExisting;
      } else {
        input.value = row[column.key] || "";
      }
      input.addEventListener("input", (event) => {
        row[column.key] = column.numeric
          ? normalizeNonNegativeInteger(event.target.value)
          : event.target.value;
        if (column.numeric) event.target.value = row[column.key];
        updateBuildingFloorTotals();
        updateBuildingFloorSummary(panel);
        autosave();
      });
      input.addEventListener("blur", () => {
        if (!column.freeText) return;
        const formattedValue = normalizeLowercaseFreeText(input.value);
        input.value = formattedValue;
        row[column.key] = formattedValue;
        // Blok bazlı paylaşım (2026-08-20) — "input" olayı satırı zaten
        // senkronladı, ama blur'daki büyük/küçük harf normalizasyonu
        // SONRADAN değiştiriyor; drift olmaması için tekrar senkronlanır.
        syncBuildingSharedDataToBlockSiblings();
        autosave();
      });
      td.append(input);
      tr.append(td);
    });
    tbody.append(tr);
  });

  table.append(thead, tbody);
  shell.append(table);
  attachBuildingFloorColumnTabNavigation(shell);
  panel.append(heading, shell);
  const summary = document.createElement("div");
  summary.className = "building-floor-summary";
  panel.append(summary);
  updateBuildingFloorSummary(panel);
  return panel;
}

function attachBuildingFloorColumnTabNavigation(shell) {
  const columnOrder = buildingFloorUnitColumns.map((column) => column.key);
  const isUsableTabStop = (el) => {
    if (!el || el.disabled) return false;
    if (typeof el.focus !== "function") return false;
    return el.offsetParent !== null;
  };
  const stopsForColumn = (columnKey) =>
    [...shell.querySelectorAll(`[data-building-floor-column="${columnKey}"]`)].filter(isUsableTabStop);

  shell.addEventListener("keydown", (event) => {
    if (event.key !== "Tab") return;
    const target = event.target;
    const columnKey = target?.dataset?.buildingFloorColumn;
    if (columnKey === undefined) return;
    const columnPos = columnOrder.indexOf(columnKey);
    if (columnPos === -1) return;

    const stops = stopsForColumn(columnKey);
    const currentIndex = stops.indexOf(target);
    if (currentIndex === -1) return;
    const forward = !event.shiftKey;
    const nextIndex = currentIndex + (forward ? 1 : -1);
    if (nextIndex >= 0 && nextIndex < stops.length) {
      event.preventDefault();
      stops[nextIndex].focus();
      return;
    }

    const nextColumnPos = columnPos + (forward ? 1 : -1);
    if (nextColumnPos < 0 || nextColumnPos >= columnOrder.length) return;
    const nextStops = stopsForColumn(columnOrder[nextColumnPos]);
    if (!nextStops.length) return;
    event.preventDefault();
    (forward ? nextStops[0] : nextStops[nextStops.length - 1]).focus();
  });
}

function updateBuildingFloorTotals() {
  const rows = Array.isArray(state.tables.buildingFloors) ? state.tables.buildingFloors : [];
  const totalFloors = rows.filter((row) => isCountableBuildingFloor(row.floorName)).length;
  const totalUnits = rows.reduce((sum, row) => (
    sum
    + parseBuildingFloorCount(row.residential)
    + parseBuildingFloorCount(row.shop)
    + parseBuildingFloorCount(row.office)
    + parseBuildingFloorCount(row.storage)
  ), 0);
  state.fields.totalFloors = totalFloors ? String(totalFloors) : "";
  state.fields.totalUnits = totalUnits ? String(totalUnits) : "";
}

function isCountableBuildingFloor(floorName) {
  const name = String(floorName || "").toLocaleLowerCase("tr");
  return !/(asma|ara|çatı|cati)/i.test(name);
}

function updateBuildingFloorSummary(container) {
  const summary = container.querySelector(".building-floor-summary");
  if (!summary) return;
  updateBuildingFloorTotals();
  const summaryText = buildBuildingFloorMacroSummary();
  state.fields.mainPropertyFloorSummary = summaryText;
  summary.innerHTML = "";
  const totalLine = document.createElement("strong");
  totalLine.textContent = `Toplam kat: ${state.fields.totalFloors || "0"} | Toplam bağımsız bölüm: ${state.fields.totalUnits || "0"}`;
  summary.append(totalLine);
  if (summaryText) {
    const detail = document.createElement("p");
    detail.textContent = summaryText;
    summary.append(detail);
  }
  refreshMainPropertyDescriptionFromCurrentFields("buildingFloorRows");
}

function parseBuildingFloorCount(value) {
  const parsed = Number.parseInt(String(value || "").replace(/[^\d]/g, ""), 10);
  return Number.isFinite(parsed) ? parsed : 0;
}

function createMainPropertyDescriptionPanel() {
  // Kullanıcı talebi: "Ana gayrimenkul kısmında Ana Gayrimenkul Açıklaması
  // ve Ana Gayrimenkul Kat Adedi bölümlerini gizle" — normal kullanıcılar bu
  // paneli görmesin. Rapor çıktısının bozulmaması için state hesaplaması
  // (mainPropertyDescription/mainPropertyFloorCountText) GÖRÜNÜRLÜKTEN
  // BAĞIMSIZ olarak yine de yapılır; yalnızca DOM'a eklenmesi atlanır.
  const nextDescription = state.fields.mainPropertyDescription || buildMainPropertyDescription();
  state.fields.mainPropertyDescription = nextDescription;
  refreshMainPropertyFloorCountTextFromCounts();
  if (!canViewSensitiveContent()) return document.createDocumentFragment();

  const panel = document.createElement("div");
  panel.className = "subsection is-detail building-description-panel";
  panel.innerHTML = `
    <div class="subsection-title-row">
      <h4>Ana Gayrimenkul Açıklaması</h4>
      <p>Seçilen teknik bilgiler ve kat dağılımına göre ana taşınmaz paragrafı oluşturulur.</p>
    </div>
  `;

  const floorCountLabel = createMainPropertyFloorCountTextControl();
  const label = document.createElement("label");
  label.className = "field field-wide";
  const textarea = document.createElement("textarea");
  textarea.dataset.field = "mainPropertyDescription";
  textarea.rows = 8;
  textarea.value = nextDescription;
  textarea.addEventListener("input", (event) => {
    state.fields.mainPropertyDescription = event.target.value;
    // Blok bazlı paylaşım (2026-08-20) — elle düzenlenen Ana Gayrimenkul
    // Açıklaması da aynı bloktaki diğer bağımsız bölümlere yansır.
    syncBuildingSharedDataToBlockSiblings();
    autosave();
    renderValidation();
    updateStatus();
  });
  textarea.addEventListener("blur", () => {
    const formattedValue = normalizeReportDescriptionText(textarea.value);
    textarea.value = formattedValue;
    state.fields.mainPropertyDescription = formattedValue;
    syncBuildingSharedDataToBlockSiblings();
    autosave();
  });

  const actions = document.createElement("div");
  actions.className = "unit-decorative-actions";
  const refreshButton = document.createElement("button");
  refreshButton.type = "button";
  refreshButton.className = "secondary-button";
  refreshButton.textContent = "Ana taşınmaz açıklamasını yenile";
  refreshButton.addEventListener("click", () => {
    state.fields.mainPropertyDescription = buildMainPropertyDescription();
    syncBuildingSharedDataToBlockSiblings();
    autosave();
    renderSection();
    renderValidation();
    updateStatus();
  });
  actions.append(refreshButton);

  label.classList.add("has-field-copy");
  label.append(createSpan("Ana Gayrimenkul Açıklaması"), createFieldCopyButton(), textarea, actions);
  panel.append(floorCountLabel, label);
  return panel;
}

function createMainPropertyFloorCountTextControl() {
  refreshMainPropertyFloorCountTextFromCounts();
  const label = document.createElement("label");
  label.className = "field field-wide";
  const input = document.createElement("input");
  input.type = "text";
  input.dataset.field = "mainPropertyFloorCountText";
  input.placeholder = "BODRUM + ZEMİN + 5 NORMAL";
  input.value = state.fields.mainPropertyFloorCountText || "";
  input.addEventListener("input", (event) => {
    const upperValue = formatMainPropertyFloorCountText(event.target.value);
    event.target.value = upperValue;
    state.fields.mainPropertyFloorCountText = upperValue;
    syncBuildingSharedDataToBlockSiblings();
    autosave();
    renderValidation();
    updateStatus();
  });
  input.addEventListener("blur", () => {
    const upperValue = formatMainPropertyFloorCountText(input.value);
    input.value = upperValue;
    state.fields.mainPropertyFloorCountText = upperValue;
    syncBuildingSharedDataToBlockSiblings();
    autosave();
  });
  label.classList.add("has-field-copy");
  label.append(createSpan("Ana Gayrimenkul Kat Adedi"), createFieldCopyButton(), input);
  return label;
}

function refreshMainPropertyFloorCountTextFromCounts(options = {}) {
  const existing = String(state.fields.mainPropertyFloorCountText || "").trim();
  if (existing && !options.force) return existing;
  const generated = formatMainPropertyFloorCountText(buildMainPropertyFloorComposition().replace(/\s+kat[ıi]?(?=\s*\+|$)/gi, ""));
  if (generated) state.fields.mainPropertyFloorCountText = generated;
  return generated;
}

function formatMainPropertyFloorCountText(value) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .replace(/\s*\+\s*/g, " + ")
    .trim()
    .toLocaleUpperCase("tr-TR");
}

