function createTitleRecordChangeControl(field) {
  const label = document.createElement("label");
  label.className = "field field-wide";
  label.classList.toggle("is-required", isCompletionCriticalField("title", field.key));
  label.classList.toggle("is-critical", isCompletionCriticalField("title", field.key));
  label.classList.toggle("is-missing", isCompletionCriticalField("title", field.key) && !hasCompletionValue(state.fields[field.key]));

  const control = document.createElement("div");
  control.className = "title-record-change-control";

  const select = document.createElement("select");
  select.dataset.field = field.key;
  ["", "Evet", "Hayır"].forEach((option) => {
    const item = document.createElement("option");
    item.value = option;
    item.textContent = option || "Seçiniz";
    select.append(item);
  });
  select.value = normalizeYesNoChoice(state.fields.titleRecordChange);

  const detailButton = document.createElement("button");
  detailButton.type = "button";
  detailButton.className = "conditional-detail-button";
  detailButton.textContent = "Kayıt Seç";
  detailButton.disabled = select.value !== "Evet";

  const summary = document.createElement("small");
  summary.className = "conditional-summary";
  summary.textContent = formatTitleRecordChangeSummary();

  select.addEventListener("input", (event) => {
    const nextValue = normalizeYesNoChoice(event.target.value);
    state.fields.titleRecordChange = nextValue;
    select.value = nextValue;
    detailButton.disabled = nextValue !== "Evet";

    if (nextValue !== "Evet") {
      state.fields.titleChangedRecords = [];
    }

    summary.textContent = formatTitleRecordChangeSummary();
    refreshEncumbranceSummaryFromCurrentData();
    autosave();
    renderValidation();
    updateStatus();

    if (nextValue === "Evet") {
      openTitleRecordChangeModal(() => {
        summary.textContent = formatTitleRecordChangeSummary();
        refreshEncumbranceSummaryFromCurrentData();
      });
    }
  });

  detailButton.addEventListener("click", () => {
    openTitleRecordChangeModal(() => {
      summary.textContent = formatTitleRecordChangeSummary();
      refreshEncumbranceSummaryFromCurrentData();
    });
  });

  control.append(select, detailButton, summary);
  label.append(createSpan(field.label), control);

  // Kullanıcı talebi (2026-08-09): "Tapu Kaydı Değişikliği Var Mı? yanına
  // tüm taşınmazlara uygulansın mı seçeneği olsun. seçildiğinde tüm
  // taşınmazlara mevcut değer uygulansın, sonra kullanıcı isterse manuel
  // değiştirebilsin." Yalnızca birden fazla taşınmaz varken (Çoklu Talep,
  // admin) anlamlı — TEK taşınmazlı raporda hiç gösterilmez. Sürekli bir
  // "senkron modu" DEĞİL: işaretlenince BİR KEZ tüm taşınmazlara kopyalanır,
  // ardından kutucuk kendiliğinden işareti kaldırır — her taşınmaz yine
  // bağımsız düzenlenebilir kalır (kullanıcının "sonra manuel değiştirebilsin"
  // isteğiyle birebir).
  if (isCurrentUserAdmin() && getTitleUnitCount() > 1) {
    const applyAllLabel = document.createElement("label");
    applyAllLabel.className = "title-record-change-apply-all";
    const applyAllCheckbox = document.createElement("input");
    applyAllCheckbox.type = "checkbox";
    const applyAllText = document.createElement("span");
    applyAllText.textContent = "Tüm taşınmazlara uygulansın mı?";
    applyAllLabel.append(applyAllCheckbox, applyAllText);

    const applyAllNote = document.createElement("small");
    applyAllNote.className = "muted-note title-record-change-apply-all-note";

    applyAllCheckbox.addEventListener("change", () => {
      if (!applyAllCheckbox.checked) return;
      const unitCount = applyTitleRecordChangeToAllTitleUnits();
      applyAllNote.textContent = `${unitCount} taşınmaza uygulandı.`;
      applyAllCheckbox.checked = false;
      autosave();
    });

    const controlRow = document.createElement("div");
    controlRow.className = "title-record-change-row";
    controlRow.append(select, detailButton, applyAllLabel);
    control.insertBefore(controlRow, summary);
    control.append(applyAllNote);
  }

  return label;
}

// Aktif taşınmazın titleRecordChange (Evet/Hayır) + titleChangedRecords
// (hangi kayıtların değiştiği, modal seçimi) değerlerini TÜM taşınmazlara
// (birincil + state.titleUnits) kopyalar. Aktif taşınmaz zaten state.fields
// üzerinden "kaynak" değeri taşıdığı için kendisine dokunmaya gerek yok —
// yalnızca DİĞER taşınmazların kendi depolama yuvaları güncellenir.
function applyTitleRecordChangeToAllTitleUnits() {
  const value = state.fields.titleRecordChange;
  const changedRecords = Array.isArray(state.fields.titleChangedRecords) ? [...state.fields.titleChangedRecords] : [];

  (state.titleUnits || []).forEach((unit) => {
    if (!unit) return;
    unit.fields = unit.fields || {};
    unit.fields.titleRecordChange = value;
    unit.fields.titleChangedRecords = [...changedRecords];
  });

  // Aktif taşınmaz birincil DEĞİLSE, birincilin "park edilmiş" verisi
  // primaryTitleUnitShadow'dadır (bkz. switchActiveTitleUnit) — o da
  // güncellenmeli, aksi halde birincile geri dönüldüğünde eski değer
  // geri gelir.
  if (state.activeTitleUnitIndex !== 0 && state.primaryTitleUnitShadow) {
    state.primaryTitleUnitShadow.fields = state.primaryTitleUnitShadow.fields || {};
    state.primaryTitleUnitShadow.fields.titleRecordChange = value;
    state.primaryTitleUnitShadow.fields.titleChangedRecords = [...changedRecords];
  }

  return getTitleUnitCount();
}

function getSelectedTitleRecordChangeKeys() {
  return Array.isArray(state.fields.titleChangedRecords) ? state.fields.titleChangedRecords : [];
}

function formatTitleRecordChangeSummary() {
  const value = normalizeYesNoChoice(state.fields.titleRecordChange);
  if (!value) return "Seçiniz.";
  if (value !== "Evet") return "Tapu kaydı değişikliği yok.";
  const selected = getSelectedTitleRecordChangeKeys()
    .map((key) => titleRecordChangeOptions.find((option) => option.key === key)?.label)
    .filter(Boolean);
  return selected.length ? `Seçilen kayıtlar: ${selected.join(", ")}` : "Değişiklik olan tapu kayıtları seçilmedi.";
}

function openTitleRecordChangeModal(onSave = () => {}) {
  document.querySelector(".modal-overlay")?.remove();

  const selected = new Set(getSelectedTitleRecordChangeKeys());
  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  overlay.innerHTML = `
    <div class="modal-card modal-card-wide" role="dialog" aria-modal="true" aria-labelledby="titleRecordChangeModalTitle">
      <div class="modal-head">
        <h3 id="titleRecordChangeModalTitle">Tapu Kaydı Değişikliği</h3>
        <button class="modal-close" type="button" aria-label="Kapat">×</button>
      </div>
      <div class="modal-body">
        <p class="modal-lead">Değişiklik olan Tapu Kayıtlarını seçiniz.</p>
        <div class="checkbox-list">
          ${titleRecordChangeOptions.map((option) => `
            <label class="checkbox-row">
              <input type="checkbox" value="${escapeHtml(option.key)}" ${selected.has(option.key) ? "checked" : ""}>
              <span>${escapeHtml(option.label)}</span>
            </label>
          `).join("")}
        </div>
      </div>
      <div class="modal-actions">
        <button class="secondary-button" type="button" data-title-change-cancel>Vazgeç</button>
        <button class="primary-button" type="button" data-title-change-save>Kaydet</button>
      </div>
    </div>
  `;

  const close = () => overlay.remove();
  overlay.querySelector(".modal-close").addEventListener("click", close);
  overlay.querySelector("[data-title-change-cancel]").addEventListener("click", close);
  overlay.addEventListener("click", (event) => {
    if (event.target === overlay) close();
  });
  overlay.querySelector("[data-title-change-save]").addEventListener("click", () => {
    state.fields.titleRecordChange = "Evet";
    state.fields.titleChangedRecords = [...overlay.querySelectorAll(".checkbox-list input:checked")].map((input) => input.value);
    autosave();
    renderValidation();
    updateStatus();
    onSave();
    refreshEncumbranceSummaryFromCurrentData();
    close();
  });

  document.body.append(overlay);
  overlay.querySelector(".checkbox-list input")?.focus();
}

function normalizeYesNoChoice(value) {
  const text = String(value || "").trim();
  const folded = foldTurkish(text);
  if (/^(EVET|VAR|YES|TRUE|1)$/.test(folded)) return "Evet";
  if (/^(HAYIR|YOK|NO|FALSE|0)$/.test(folded)) return "Hayır";
  return "";
}

function formatRoadSetbackSummary() {
  if (state.fields.roadSetback !== "Evet") return "Seçiniz / Hayır durumunda ek bilgi alınmaz.";
  const parts = [];
  if (state.fields.roadSetbackAmount) parts.push(`Terk miktarı: ${state.fields.roadSetbackAmount}`);
  if (state.fields.roadSetbackBuildingImpact) parts.push(`Yapıya etkisi: ${state.fields.roadSetbackBuildingImpact}`);
  return parts.length ? parts.join(" - ") : "Terk detayları bekliyor.";
}

function createConditionalYesNoControl(field) {
  const label = document.createElement("label");
  label.className = "field";
  if (field.layoutClass) label.classList.add(field.layoutClass);
  label.classList.toggle("is-required", Boolean(field.required || field.critical));
  label.classList.toggle("is-critical", Boolean(field.critical));
  label.classList.toggle("is-missing", Boolean(field.required || field.critical) && !hasCompletionValue(state.fields[field.key]));
  label.classList.toggle("field-wide", Boolean(field.wide));

  const control = document.createElement("div");
  control.className = "conditional-yes-no-control";

  const select = document.createElement("select");
  select.dataset.field = field.key;
  ["", "Evet", "Hayır"].forEach((option) => {
    const item = document.createElement("option");
    item.value = option;
    item.textContent = option || "Seçiniz";
    select.append(item);
  });
  const initialValue = normalizeYesNoChoice(state.fields[field.key]) || getEffectiveDefaultValueForField(field) || "";
  if (!state.fields[field.key] && initialValue && !isFieldKeyOwnedBySource(field.key)) {
    state.fields[field.key] = initialValue;
  }
  select.value = initialValue;

  const detailButton = document.createElement("button");
  detailButton.type = "button";
  detailButton.className = "conditional-detail-button";
  detailButton.textContent = "Açıklama";
  detailButton.disabled = !shouldOpenConditionalDetail(field, select.value);
  detailButton.hidden = Boolean(field.hideInactiveDetail && !shouldOpenConditionalDetail(field, select.value));

  const summary = document.createElement("small");
  summary.className = "conditional-summary";
  summary.textContent = formatConditionalYesNoSummary(field);
  summary.hidden = Boolean(field.hideInactiveDetail && !shouldOpenConditionalDetail(field, select.value));

  select.addEventListener("input", (event) => {
    const nextValue = normalizeYesNoChoice(event.target.value);
    state.fields[field.key] = nextValue;
    select.value = nextValue;
    detailButton.disabled = !shouldOpenConditionalDetail(field, nextValue);
    detailButton.hidden = Boolean(field.hideInactiveDetail && !shouldOpenConditionalDetail(field, nextValue));

    if (!shouldOpenConditionalDetail(field, nextValue)) {
      state.fields[field.detailKey] = "";
    }

    summary.textContent = formatConditionalYesNoSummary(field);
    summary.hidden = Boolean(field.hideInactiveDetail && !shouldOpenConditionalDetail(field, nextValue));
    refreshPlanningNoteFromCurrentFields(field.key);
    refreshPlanningNoteFromCurrentFields(field.detailKey);
    refreshPenaltyDecisionExplanationFromCurrentFields(field.key);
    refreshStaticSuitabilityExplanationFromCurrentFields(field.key);
    refreshEkbExplanationFromCurrentFields(field.key);
    // Belgeler ve Proje blok-senkronu (2026-08-19) — bu HUB fonksiyon
    // İmar/Arazi/Belgeler'de ONLARCA alan için ortak kullanılıyor; diğer
    // refresh...FromCurrentFields çağrılarıyla AYNI "ilgiliyse çalış,
    // değilse no-op" deseninde (field.key documents'e özgü DEĞİLSE
    // DOCUMENTS_BLOCK_SHARED_FIELD_KEYS'te bulunmaz, sessizce atlanır).
    if (DOCUMENTS_BLOCK_SHARED_FIELD_KEYS.includes(field.key)) {
      syncDocumentsSharedDataToBlockSiblings();
    }
    autosave();
    renderValidation();
    updateStatus();

    if (shouldOpenConditionalDetail(field, nextValue)) {
      openConditionalExplanationModal(field, () => {
        summary.textContent = formatConditionalYesNoSummary(field);
      });
    }
  });

  detailButton.addEventListener("click", () => {
    openConditionalExplanationModal(field, () => {
      summary.textContent = formatConditionalYesNoSummary(field);
    });
  });

  control.append(select, detailButton, summary);
  label.append(createSpan(field.label), control);
  return label;
}

function createMultiCheckboxControl(field) {
  const wrapper = document.createElement("div");
  wrapper.className = "field multi-checkbox-dropdown";
  wrapper.classList.toggle("field-wide", Boolean(field.wide));
  wrapper.classList.toggle("is-critical", Boolean(field.critical));

  const options = getFieldOptions(field);
  const effectiveField = { ...field, options };
  let selected = getMultiCheckboxValues(field.key, effectiveField).filter((value) => !options.length || options.includes(value));
  if (state.fields[field.key] && selected.length !== getMultiCheckboxValues(field.key, effectiveField).length) {
    state.fields[field.key] = formatMultiCheckboxValue(selected, field);
  }
  const summaryButton = document.createElement("button");
  summaryButton.type = "button";
  summaryButton.className = "multi-checkbox-summary";
  summaryButton.setAttribute("aria-expanded", "false");
  summaryButton.textContent = formatMultiCheckboxSummary(selected, field);

  const persistMultiSelection = (values) => {
    values = normalizeMultiCheckboxValues(values, field);
    clearFieldSourceOwnership(field.key);
    state.fields[field.key] = formatMultiCheckboxValue(values, field);
    summaryButton.textContent = formatMultiCheckboxSummary(values, field);
    refreshEnvironmentDescriptionFromCurrentFields(field.key);
    refreshReviewedDocumentsDescriptionFromCurrentFields(field.key);
    autosave();
    renderValidation();
    updateStatus();
    return values;
  };

  const list = document.createElement("div");
  list.className = "inline-checkbox-list";
  list.hidden = true;

  options.forEach((option) => {
    const item = document.createElement("label");
    item.className = "checkbox-row";
    item.innerHTML = `
      <input type="checkbox" value="${escapeHtml(option)}" ${selected.includes(option) ? "checked" : ""}>
      <span>${escapeHtml(option)}</span>
    `;
    list.append(item);
  });

  list.querySelectorAll("input[type='checkbox']").forEach((input) => {
    input.addEventListener("change", () => {
      if (field.key === "projectInstitution" && input.value === imarOsbInstitutionOption && input.checked) {
        input.checked = false;
        setOpen(false);
        openImarOsbInstitutionModal((institutionName) => {
          selected = persistMultiSelection([
            ...selected.filter((value) => value !== imarOsbInstitutionOption),
            institutionName,
          ]);
          multiCheckboxFieldToReopen = field.key;
          renderSection();
        });
        return;
      }

      let values = [...list.querySelectorAll("input[type='checkbox']:checked")].map((checkbox) => checkbox.value);
      if (field.maxSelections && values.length > field.maxSelections) {
        input.checked = false;
        values = values.filter((value) => value !== input.value);
      }
      selected = persistMultiSelection(values);
      if (field.key === "projectInstitution") {
        multiCheckboxFieldToReopen = field.key;
        renderSection();
      }
    });
  });

  let outsideClickListener = null;
  const setOpen = (isOpen) => {
    list.hidden = !isOpen;
    wrapper.classList.toggle("is-open", isOpen);
    summaryButton.setAttribute("aria-expanded", String(isOpen));

    if (outsideClickListener) {
      document.removeEventListener("pointerdown", outsideClickListener);
      outsideClickListener = null;
    }

    if (isOpen) {
      outsideClickListener = (event) => {
        if (!wrapper.contains(event.target)) {
          setOpen(false);
        }
      };
      const currentOutsideClickListener = outsideClickListener;
      setTimeout(() => {
        if (outsideClickListener === currentOutsideClickListener) {
          document.addEventListener("pointerdown", currentOutsideClickListener);
        }
      }, 0);
    }
  };

  if (multiCheckboxFieldToReopen === field.key) {
    multiCheckboxFieldToReopen = "";
    setOpen(true);
  }

  summaryButton.addEventListener("click", () => {
    setOpen(list.hidden);
  });

  list.addEventListener("pointerdown", (event) => {
    event.stopPropagation();
  });

  wrapper.append(createSpan(field.label), summaryButton, list);
  return wrapper;
}

function createImarInstitutionControl(field) {
  const reopenKey = `imar-institution:${field.key}`;
  const wrapper = document.createElement("div");
  wrapper.className = "field multi-checkbox-dropdown imar-institution-dropdown";
  wrapper.classList.toggle("field-wide", Boolean(field.wide));
  wrapper.classList.toggle("is-critical", Boolean(field.critical));

  let selected = getImarInstitutionValues();
  const options = getImarInstitutionOptions(selected);
  const summaryButton = document.createElement("button");
  summaryButton.type = "button";
  summaryButton.className = "multi-checkbox-summary";
  summaryButton.dataset.field = field.key;
  summaryButton.setAttribute("aria-expanded", "false");
  summaryButton.textContent = formatImarInstitutionSummary(selected);
  markFieldSourceState(summaryButton, field.key, field.autoFill);

  const list = document.createElement("div");
  list.className = "inline-checkbox-list";
  list.hidden = true;

  options.forEach((option) => {
    const item = document.createElement("label");
    item.className = "checkbox-row";
    item.innerHTML = `
      <input type="checkbox" value="${escapeHtml(option)}" ${selected.includes(option) ? "checked" : ""}>
      <span>${escapeHtml(option)}</span>
    `;
    list.append(item);
  });

  const persistSelection = (values) => {
    selected = normalizeMultiCheckboxValues(values);
    clearFieldSourceOwnership(field.key);
    state.fields[field.key] = formatMultiCheckboxValue(selected);
    summaryButton.textContent = formatImarInstitutionSummary(selected);
    refreshPlanningNoteFromCurrentFields(field.key);
    autosave();
    renderValidation();
    updateStatus();
  };

  list.querySelectorAll("input[type='checkbox']").forEach((input) => {
    input.addEventListener("change", () => {
      if (input.value === imarOsbInstitutionOption && input.checked) {
        input.checked = false;
        setOpen(false);
        openImarOsbInstitutionModal((institutionName) => {
          persistSelection([...selected, institutionName]);
          multiCheckboxFieldToReopen = reopenKey;
          renderSection();
        });
        return;
      }

      const values = [...list.querySelectorAll("input[type='checkbox']:checked")]
        .map((checkbox) => checkbox.value)
        .filter((value) => value !== imarOsbInstitutionOption);
      persistSelection(values);
      multiCheckboxFieldToReopen = reopenKey;
      renderSection();
    });
  });

  let outsideClickListener = null;
  const setOpen = (isOpen) => {
    list.hidden = !isOpen;
    wrapper.classList.toggle("is-open", isOpen);
    summaryButton.setAttribute("aria-expanded", String(isOpen));

    if (outsideClickListener) {
      document.removeEventListener("pointerdown", outsideClickListener);
      outsideClickListener = null;
    }

    if (isOpen) {
      outsideClickListener = (event) => {
        if (!wrapper.contains(event.target)) setOpen(false);
      };
      const currentOutsideClickListener = outsideClickListener;
      setTimeout(() => {
        if (outsideClickListener === currentOutsideClickListener) {
          document.addEventListener("pointerdown", currentOutsideClickListener);
        }
      }, 0);
    }
  };

  if (multiCheckboxFieldToReopen === reopenKey) {
    multiCheckboxFieldToReopen = "";
    setOpen(true);
  }

  summaryButton.addEventListener("click", () => {
    setOpen(list.hidden);
  });
  list.addEventListener("pointerdown", (event) => {
    event.stopPropagation();
  });

  wrapper.append(createSpan(field.label), summaryButton, list);
  return wrapper;
}

function getImarInstitutionValues(value = state.fields.imarInfoInstitution) {
  if (Array.isArray(value)) return normalizeMultiCheckboxValues(value);
  return normalizeMultiCheckboxValues(String(value || "")
    .split(/\s*,\s*/)
    .map((item) => item.trim())
    .filter(Boolean));
}

function getImarInstitutionOptions(selectedValues = getImarInstitutionValues()) {
  const city = normalizeReportTitleText(state.fields.titleCity || state.fields.city || "").trim();
  const district = normalizeReportTitleText(state.fields.titleDistrict || state.fields.district || "").trim();
  const regionalInstitution = city
    ? `${city} ${isMetropolitanProvince(city) ? "Büyükşehir Belediyesi" : "İl Özel İdaresi"}`
    : "";
  const suggested = [
    district ? `${district} Belediyesi` : "",
    regionalInstitution,
    imarOsbInstitutionOption,
  ];
  return [...new Set([...suggested, ...selectedValues].map((value) => String(value || "").trim()).filter(Boolean))];
}

function isMetropolitanProvince(value) {
  return metropolitanProvinceNames.has(foldTurkish(value));
}

function formatImarInstitutionSummary(values = getImarInstitutionValues()) {
  return values.length ? values.join(", ") : "Seçiniz";
}

function formatImarOsbInstitutionName(value) {
  const cleanName = normalizeReportTitleText(String(value || "")
    .replace(/\s+(?:Organize Sanayi|OSB)\s+Bölge Müdürlüğü\s*$/i, "")
    .trim());
  return cleanName ? `${cleanName} Organize Sanayi Bölge Müdürlüğü` : "";
}

function openImarOsbInstitutionModal(onSave = () => {}) {
  document.querySelector(".modal-overlay")?.remove();
  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  overlay.innerHTML = `
    <div class="modal-card imar-osb-institution-modal" role="dialog" aria-modal="true" aria-labelledby="imarOsbInstitutionModalTitle">
      <div class="modal-head">
        <h3 id="imarOsbInstitutionModalTitle">OSB Bölge Müdürlüğü</h3>
        <button class="modal-close" type="button" aria-label="Kapat" title="Kapat">×</button>
      </div>
      <div class="modal-body">
        <label class="field">
          <span>OSB adını yazınız</span>
          <input type="text" data-osb-name autocomplete="off" placeholder="Örn. Hasanağa">
          <small>Yalnızca OSB adını girin. Kurum adı otomatik tamamlanacaktır.</small>
        </label>
      </div>
      <div class="modal-actions">
        <button class="secondary-button" type="button" data-modal-cancel>Vazgeç</button>
        <button class="primary-button" type="button" data-modal-save>Kaydet</button>
      </div>
    </div>
  `;
  const input = overlay.querySelector("[data-osb-name]");
  const close = () => overlay.remove();
  const save = () => {
    const institutionName = formatImarOsbInstitutionName(input.value);
    if (!institutionName) {
      input.setCustomValidity("OSB adını yazınız.");
      input.reportValidity();
      return;
    }
    input.setCustomValidity("");
    close();
    onSave(institutionName);
  };
  overlay.querySelector(".modal-close").addEventListener("click", close);
  overlay.querySelector("[data-modal-cancel]").addEventListener("click", close);
  overlay.querySelector("[data-modal-save]").addEventListener("click", save);
  input.addEventListener("input", () => input.setCustomValidity(""));
  input.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      save();
    }
  });
  document.body.append(overlay);
  input.focus();
}

function createCheckboxControl(section, field) {
  const label = document.createElement("label");
  label.className = "field checkbox-field";
  label.classList.toggle("field-wide", Boolean(field.wide));
  label.classList.toggle("is-critical", Boolean(field.critical));

  const checkedValue = field.checkedValue || "Evet";
  const uncheckedValue = field.uncheckedValue || "Hayır";
  const effectiveDefaultValue = getEffectiveDefaultValueForField(field) || checkedValue;
  if (!state.fields[field.key] && effectiveDefaultValue && !isFieldKeyOwnedBySource(field.key)) {
    state.fields[field.key] = effectiveDefaultValue;
  }

  const input = document.createElement("input");
  input.type = "checkbox";
  input.dataset.field = field.key;
  input.checked = (state.fields[field.key] || effectiveDefaultValue) === checkedValue;

  input.addEventListener("change", () => {
    clearFieldSourceOwnership(field.key);
    state.fields[field.key] = input.checked ? checkedValue : uncheckedValue;
    if (field.key === "usageNatureDifference") {
      if (syncCurrentUsageNatureWithLegalNature()) clearFieldSourceOwnership("currentUsageNature");
    }
    refreshPlanningNoteFromCurrentFields(field.key);
    refreshEnvironmentDescriptionFromCurrentFields(field.key);
    refreshReviewedDocumentsDescriptionFromCurrentFields(field.key);
    refreshEncumbranceSummaryFromCurrentFields(field.key);
    refreshExpenseFeesFromCurrentFields(field.key);
    if (field.key === "usageNatureDifference") {
      refreshValuationMethodExplanation();
    }
    autosave();
    renderValidation();
    updateStatus();
    if (
      (section.id === "documents" && field.key === "hasArchitecturalProject")
      || (section.id === "case" && field.key === "usageNatureDifference")
      || (section.id === "planning" && field.key === "hasPlanningIssue")
    ) {
      renderSection();
    }
  });

  const text = document.createElement("span");
  text.textContent = formatUiHeading(field.label);
  label.append(input, text);
  return label;
}

function getFieldOptions(field = {}) {
  if (field.key === "imarInfoInstitution") {
    return getImarInstitutionOptions();
  }
  if (field.key === "projectInstitution") {
    return [...new Set([...(field.options || []), ...getSelectedProjectInstitutions()])];
  }
  if (field.key === "regionUsePurpose" && detectEnvironmentalRegionType(state.fields.environmentRegionType) === "Sanayi Bölgesi") {
    return industrialRegionUsePurposeOptions;
  }
  return field.options || [];
}

function normalizeRegionUsePurposeForEnvironment() {
  const options = getFieldOptions({ key: "regionUsePurpose", options: regionUsePurposeOptions });
  const current = getMultiCheckboxValues("regionUsePurpose", { options: regionUsePurposeOptions });
  const next = current.filter((value) => options.includes(value));
  if (next.length !== current.length) {
    state.fields.regionUsePurpose = formatMultiCheckboxValue(next, { options });
  }
}
function getMultiCheckboxValues(key, field = {}) {
  const value = state.fields[key];
  if (Array.isArray(value)) return value;
  const text = String(value || "").trim();
  const separator = field.rangeSummary ? /[,;-]/ : ",";
  const optionValues = field.rangeSummary ? [] : parseStoredMultiCheckboxOptions(text, field.options || []);
  return normalizeMultiCheckboxValues((optionValues.length ? optionValues : text.split(separator))
    .map((item) => item.trim())
    .filter(Boolean), field);
}

function parseStoredMultiCheckboxOptions(value, options = []) {
  const text = String(value || "").trim();
  const candidates = [...new Set(options.map((option) => String(option || "").trim()).filter(Boolean))]
    .sort((a, b) => b.length - a.length);
  if (!text || !candidates.length) return [];
  if (candidates.includes(text)) return [text];

  const memo = new Map();
  const readFrom = (index) => {
    if (index === text.length) return [];
    if (memo.has(index)) return memo.get(index);
    for (const option of candidates) {
      if (!text.startsWith(option, index)) continue;
      const optionEnd = index + option.length;
      if (optionEnd === text.length) return [option];
      const separatorMatch = text.slice(optionEnd).match(/^,\s*/);
      if (!separatorMatch) continue;
      const remaining = readFrom(optionEnd + separatorMatch[0].length);
      if (remaining) return [option, ...remaining];
    }
    memo.set(index, null);
    return null;
  };

  return readFrom(0) || [];
}

function normalizeMultiCheckboxValues(values, field = {}) {
  const uniqueValues = [...new Set(values.map((item) => String(item || "").trim()).filter(Boolean))];
  if (!field.rangeSummary) return uniqueValues;
  return uniqueValues.sort((a, b) => Number(a) - Number(b)).slice(0, field.maxSelections || uniqueValues.length);
}

function formatMultiCheckboxValue(values, field = {}) {
  if (!values.length) return "";
  if (field.rangeSummary) return values.join("-");
  return values.join(", ");
}

function formatMultiCheckboxSummary(values, field = {}) {
  if (!values.length) return "Seçiniz";
  return formatMultiCheckboxValue(values, field);
}

function createDocumentDecisionControls() {
  const wrapper = document.createElement("div");
  wrapper.className = "document-decision-grid";
  const isLandReport = typeof isLandProjectReview === "function" && isLandProjectReview();
  wrapper.append(
    createConditionalYesNoControl({
      key: "penaltyDecision",
      label: "Cezai Karar Var mı?",
      type: "conditionalYesNo",
      critical: true,
      detailWhen: "Evet",
      detailKey: "penaltyNote",
      detailLabel: "Cezai karar açıklama",
      detailTitle: "Cezai Karar Açıklama",
      defaultValue: "Hayır",
      hideInactiveDetail: true,
    })
  );

  if (isLandReport) {
    // Arsa/Tarla raporlarında yapı niteliğiyle ilgili bu iki karar alanı
    // anlamlı değildir; önceki rapor verisi varsa çıktıya sızmaması için temizlenir.
    state.fields.staticSuitability = "";
    state.fields.staticSuitabilityNote = "";
    state.fields.staticSuitabilityExplanation = "";
    state.fields.buildingInspectionContractActive = "";
    state.fields.buildingInspectionProgressLevel = "";
    state.fields.buildingInspectionTerminationDate = "";
    state.fields.buildingInspectionTerminationLevel = "";
    state.fields.buildingInspectionExplanation = "";
    return wrapper;
  }

  wrapper.append(
    createConditionalYesNoControl({
      key: "staticSuitability",
      label: "Statik Uygunluk",
      type: "conditionalYesNo",
      critical: true,
      detailWhen: "Hayır",
      detailKey: "staticSuitabilityNote",
      detailLabel: "Statik uygunluk açıklama",
      detailTitle: "Statik Uygunluk Açıklama",
      hideInactiveDetail: true,
    })
  );

  if (hasReviewedOccupancyPermitDocument()) {
    state.fields.buildingInspectionContractActive = "";
    state.fields.buildingInspectionProgressLevel = "";
    state.fields.buildingInspectionTerminationDate = "";
    state.fields.buildingInspectionTerminationLevel = "";
    state.fields.buildingInspectionExplanation = "";
    return wrapper;
  }

  if (isBuildingInspectionLawExempt()) {
    // 13.07.2001 öncesi yapı ruhsatında sözleşme durumu/hakediş seviyesi
    // sorusu anlamsızlaşır; hücreler gizlenir, yalnızca kanun kapsamı dışı
    // olduğunu belirten açıklama gösterilir (kullanıcı talebi).
    state.fields.buildingInspectionContractActive = "";
    state.fields.buildingInspectionProgressLevel = "";
    state.fields.buildingInspectionTerminationDate = "";
    state.fields.buildingInspectionTerminationLevel = "";
    wrapper.append(createBuildingInspectionExplanationPreview());
    return wrapper;
  }

  const contractTitle = document.createElement("h4");
  contractTitle.className = "document-decision-title";
  contractTitle.textContent = "Yapı Denetim Sözleşme Durumu";
  wrapper.append(
    contractTitle,
    createDocumentDecisionSelect({
      key: "buildingInspectionContractActive",
      label: "Sözleşme Aktif mi?",
      options: ["", "Evet", "Hayır (Fesihli)"],
      critical: true,
      onChange: (nextValue) => {
        if (nextValue === "Hayır (Fesihli)") {
          openBuildingInspectionTerminationModal(() => renderSection());
        } else {
          state.fields.buildingInspectionTerminationDate = "";
          state.fields.buildingInspectionTerminationLevel = "";
        }
      },
    })
  );
  if (state.fields.buildingInspectionContractActive === "Evet") {
    wrapper.append(
      createDocumentDecisionSelect({
        key: "buildingInspectionProgressLevel",
        label: "Yapı Denetim Hakediş Seviyesi",
        options: ["", ...Array.from({ length: 100 }, (_, index) => `%${100 - index}`)],
      })
    );
  } else {
    state.fields.buildingInspectionProgressLevel = "";
  }
  wrapper.append(createBuildingInspectionExplanationPreview());
  return wrapper;
}

function createBuildingInspectionExplanationPreview() {
  // Kullanıcı talebi: "Belgeler ve proje kısmında Yapı Denetim Açıklaması
  // bölümünü gizle" — normal kullanıcılar bu önizlemeyi görmesin.
  if (!canViewSensitiveContent()) return document.createDocumentFragment();
  const label = document.createElement("label");
  label.className = "field field-wide document-decision-explanation";
  label.append(createSpan("Yapı Denetim Açıklaması"));

  const textarea = document.createElement("textarea");
  textarea.rows = 3;
  textarea.readOnly = true;
  textarea.value = state.fields.buildingInspectionExplanation || buildBuildingInspectionExplanation();
  label.append(textarea);
  return label;
}

function createDocumentDecisionSelect(field) {
  const label = document.createElement("label");
  label.className = "field";
  label.classList.toggle("is-required", Boolean(field.required || field.critical));
  label.classList.toggle("is-critical", Boolean(field.critical));
  label.classList.toggle("is-missing", Boolean(field.required || field.critical) && !hasCompletionValue(state.fields[field.key]));

  const select = document.createElement("select");
  select.dataset.field = field.key;
  (field.options || []).forEach((option) => {
    const item = document.createElement("option");
    item.value = option;
    item.textContent = option || "Seçiniz";
    select.append(item);
  });
  select.value = field.normalize ? field.normalize(state.fields[field.key]) : state.fields[field.key] || "";

  select.addEventListener("input", (event) => {
    const nextValue = field.normalize ? field.normalize(event.target.value) : event.target.value;
    state.fields[field.key] = nextValue;
    select.value = nextValue;
    field.onChange?.(nextValue);
    refreshBuildingInspectionExplanationFromCurrentFields(field.key);
    // Belgeler ve Proje blok-senkronu (2026-08-19) — bu fonksiyon zaten
    // documents'e özgü (buildingInspectionContractActive/ProgressLevel).
    syncDocumentsSharedDataToBlockSiblings();
    autosave();
    renderValidation();
    updateStatus();
    if (field.key === "buildingInspectionContractActive") renderSection();
  });

  label.append(createSpan(field.label), select);
  return label;
}

function openBuildingInspectionTerminationModal(onSave = () => {}) {
  document.querySelector(".modal-overlay")?.remove();

  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  overlay.innerHTML = `
    <div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="buildingInspectionTerminationModalTitle">
      <div class="modal-head">
        <h3 id="buildingInspectionTerminationModalTitle">Yapı Denetim Sözleşme Feshi</h3>
        <button class="modal-close" type="button" aria-label="Kapat">×</button>
      </div>
      <div class="modal-body">
        <label class="field">
          <span>Sözleşme Fesih Tarihi</span>
          <input type="date" data-building-inspection-termination-date>
        </label>
        <label class="field">
          <span>Fesih Seviyesi</span>
          <select data-building-inspection-termination-level></select>
        </label>
      </div>
      <div class="modal-actions">
        <button class="secondary-button" type="button" data-building-inspection-termination-cancel>Vazgeç</button>
        <button class="primary-button" type="button" data-building-inspection-termination-save>Kaydet</button>
      </div>
    </div>
  `;

  const dateInput = overlay.querySelector("[data-building-inspection-termination-date]");
  const levelSelect = overlay.querySelector("[data-building-inspection-termination-level]");
  ["", ...Array.from({ length: 100 }, (_, index) => `%${100 - index}`)].forEach((option) => {
    const item = document.createElement("option");
    item.value = option;
    item.textContent = option || "Seçiniz";
    levelSelect.append(item);
  });
  dateInput.value = state.fields.buildingInspectionTerminationDate || "";
  levelSelect.value = state.fields.buildingInspectionTerminationLevel || "";

  const close = () => overlay.remove();
  overlay.querySelector(".modal-close").addEventListener("click", close);
  overlay.querySelector("[data-building-inspection-termination-cancel]").addEventListener("click", close);
  overlay.addEventListener("click", (event) => {
    if (event.target === overlay) close();
  });
  overlay.querySelector("[data-building-inspection-termination-save]").addEventListener("click", () => {
    state.fields.buildingInspectionContractActive = "Hayır (Fesihli)";
    state.fields.buildingInspectionTerminationDate = dateInput.value;
    state.fields.buildingInspectionTerminationLevel = levelSelect.value;
    refreshBuildingInspectionExplanationFromCurrentFields();
    // Belgeler ve Proje blok-senkronu (2026-08-19) — bu modal documents'e özgü.
    syncDocumentsSharedDataToBlockSiblings();
    autosave();
    renderValidation();
    updateStatus();
    onSave();
    close();
  });

  document.body.append(overlay);
  dateInput.focus();
}

function shouldOpenConditionalDetail(field, value) {
  return normalizeYesNoChoice(value) === (field.detailWhen || "Evet");
}

function formatConditionalYesNoSummary(field) {
  const value = normalizeYesNoChoice(state.fields[field.key]);
  if (!value) return "Seçiniz.";
  if (!shouldOpenConditionalDetail(field, value)) return "Ek açıklama gerekmez.";
  return state.fields[field.detailKey] || "Açıklama bekliyor.";
}

function openConditionalExplanationModal(field, onSave = () => {}) {
  document.querySelector(".modal-overlay")?.remove();

  const modalTitle = field.detailTitle || field.label;
  const explanationLabel = field.detailLabel || "Açıklama";
  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  overlay.innerHTML = `
    <div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="conditionalModalTitle">
      <div class="modal-head">
        <h3 id="conditionalModalTitle">${escapeHtml(modalTitle)}</h3>
        <button class="modal-close" type="button" aria-label="Kapat">×</button>
      </div>
      <div class="modal-body">
        <label class="field">
          <span>${escapeHtml(explanationLabel)}</span>
          <textarea data-conditional-explanation rows="5"></textarea>
        </label>
      </div>
      <div class="modal-actions">
        <button class="secondary-button" type="button" data-conditional-cancel>Vazgeç</button>
        <button class="primary-button" type="button" data-conditional-save>Kaydet</button>
      </div>
    </div>
  `;

  const explanation = overlay.querySelector("[data-conditional-explanation]");
  explanation.value = state.fields[field.detailKey] || "";

  const close = () => overlay.remove();
  overlay.querySelector(".modal-close").addEventListener("click", close);
  overlay.querySelector("[data-conditional-cancel]").addEventListener("click", close);
  overlay.addEventListener("click", (event) => {
    if (event.target === overlay) close();
  });
  overlay.querySelector("[data-conditional-save]").addEventListener("click", () => {
    state.fields[field.key] = field.detailWhen || "Evet";
    state.fields[field.detailKey] = normalizeReportDescriptionText(explanation.value);
    refreshPlanningNoteFromCurrentFields(field.key);
    refreshPlanningNoteFromCurrentFields(field.detailKey);
    refreshPenaltyDecisionExplanationFromCurrentFields(field.detailKey);
    refreshStaticSuitabilityExplanationFromCurrentFields(field.detailKey);
    refreshEkbExplanationFromCurrentFields(field.detailKey);
    // Belgeler ve Proje blok-senkronu (2026-08-19) — bu ORTAK modal
    // penaltyNote/staticSuitabilityNote/mainRealEstateProjectSuitabilityNote
    // gibi birden fazla bölümün detay notu için kullanılıyor; AYNI
    // "ilgiliyse çalış, değilse no-op" deseni.
    if (DOCUMENTS_BLOCK_SHARED_FIELD_KEYS.includes(field.key) || DOCUMENTS_BLOCK_SHARED_FIELD_KEYS.includes(field.detailKey)) {
      syncDocumentsSharedDataToBlockSiblings();
    }
    autosave();
    renderValidation();
    updateStatus();
    onSave();
    close();
  });

  document.body.append(overlay);
  explanation.focus();
}

