function createMainArteryComposer(field) {
  const wrapper = document.createElement("div");
  wrapper.className = "artery-composer";
  const source = state.sourceValues.nearbyPlaces || {};
  clearOutOfRangeMainArterySelection(source.places || []);
  const roads = getAllMainArteryPlacesWithUser(source.places || []);
  const selectedId = state.fields.mainArteryId || "";
  const selectedRoad = roads.find((road) => road.id === selectedId);

  wrapper.innerHTML = `
    <div class="artery-head">
      <div>
        <span>${escapeHtml(field.label)}</span>
      </div>
    </div>
    <div class="artery-selected">${selectedRoad ? escapeHtml(formatPlaceWithDistance(selectedRoad)) : state.fields.mainArtery ? escapeHtml(state.fields.mainArtery) : "Henüz ana arter seçilmedi."}</div>
    <div class="artery-list"></div>
    <label class="manual-main-artery-field">
      <span>Manuel ana arter</span>
      <input type="text" value="${selectedRoad ? "" : escapeHtml(state.fields.mainArtery || "")}" placeholder="Cadde/bulvar adını yazın" />
    </label>
  `;

  const list = wrapper.querySelector(".artery-list");
  if (!roads.length) {
    const empty = document.createElement("p");
    empty.className = "muted-note";
    empty.textContent = `${getNearbySelectionRadiusMeters()} m içinde cadde/bulvar bulunamadı.`;
    list.append(empty);
  } else {
    roads.slice(0, mainArteryAutoLimit + getUserMainArteryPlaces().length).forEach((road) => {
      const item = document.createElement("label");
      item.className = "nearby-item artery-item";
      item.innerHTML = `
        <input type="radio" name="mainArtery" data-artery-id="${escapeHtml(road.id)}" ${selectedId === road.id ? "checked" : ""} />
        <span>${escapeHtml(formatPlaceWithDistance(road))}</span>
      `;
      list.append(item);
    });
  }

  wrapper.querySelectorAll("[data-artery-id]").forEach((input) => {
    input.addEventListener("change", () => {
      selectMainArtery(input.dataset.arteryId);
      autosave();
      renderSection();
    });
  });

  const manualInput = wrapper.querySelector(".manual-main-artery-field input");
  manualInput.addEventListener("input", () => {
    const value = normalizeReportTitleText(manualInput.value);
    state.fields.mainArteryId = "";
    state.fields.mainArtery = value;
    wrapper.querySelector(".artery-selected").textContent = value || "Henüz ana arter seçilmedi.";
    state.sourceValues.nearbyArtery = state.sourceValues.nearbyArtery || {};
    state.sourceValues.nearbyArtery.applied = {
      ...(state.sourceValues.nearbyArtery.applied || {}),
      mainArtery: value,
    };
    autosave();
    renderValidation();
    updateStatus();
  });
  manualInput.addEventListener("blur", () => {
    manualInput.value = normalizeReportTitleText(manualInput.value);
    autosave();
    renderSection();
  });

  return wrapper;
}

function getUploadInputAccept(upload) {
  const accept = String(upload?.accept || "").trim();
  const isIos = /iPad|iPhone|iPod/i.test(navigator.userAgent || "")
    || (navigator.platform === "MacIntel" && Number(navigator.maxTouchPoints) > 1);

  // iOS Dosyalar seçicisi, bazı KML dosyalarını MIME kaydı bulunmadığında
  // `.kml` uzantısı doğru olsa dahi seçilemez gösterir. KML için filtreyi
  // kaldırıyoruz; seçimden sonra mevcut ayrıştırıcı dosyanın geçerliliğini
  // yine denetler.
  if (upload?.id === "kml" && isIos) return "";
  return accept;
}

function createUploadGrid(uploads) {
  const grid = document.createElement("div");
  grid.className = "upload-grid";

  uploads.forEach((upload) => {
    const card = document.createElement("div");
    card.className = "upload-card";
    const stored = state.uploads[upload.id];
    const uploadError = state.uploadErrors?.[upload.id] || "";
    const accept = getUploadInputAccept(upload);
    // "takbis" alanı admin için çoklu dosya seçebilir (2026-08-09, bkz.
    // docs/coklu-takbis-import-plan.md) — çoklu-kayıtlı TEK PDF veya
    // birden fazla tek-kayıtlı PDF tespiti processTakbisUpload() içinde
    // yapılır. Diğer 5 yükleme alanı ve normal kullanıcılar için DEĞİŞMEDİ
    // (tek dosya).
    const allowMultipleFiles = upload.id === "takbis" || upload.id === "kml";
    // "KML'i tek seferde yükleyip tüm taşınmazlara uygula" kutucuğu yalnızca
    // Çoklu Talep + admin + 2'den fazla taşınmaz varken anlamlı (bkz.
    // createTitleRecordChangeControl'deki AYNI gate deseni) — tek taşınmazlı
    // raporda zaten tek hedef vardır, kutucuk gereksiz kafa karıştırır.
    const kmlApplyAllEligible = upload.id === "kml" && isCurrentUserAdmin() && getTitleUnitCount() > 1;
    card.innerHTML = `
      <strong>${upload.title}</strong>
      <p>${upload.hint}</p>
      <input type="file" data-upload="${upload.id}" ${accept ? `accept="${accept}"` : ""} ${allowMultipleFiles ? "multiple" : ""} />
      ${kmlApplyAllEligible ? `
      <label class="kml-apply-all-label">
        <input type="checkbox" class="kml-apply-all-checkbox" />
        <span>Tek dosya seçilirse tüm taşınmazlara uygulansın (aynı ada/parsel)</span>
      </label>` : ""}
      <p>${stored ? `Seçilen dosya: ${stored}` : "Henüz dosya seçilmedi."}</p>
      ${uploadError ? `<p class="upload-error">${escapeHtml(uploadError)}</p>` : ""}
    `;

    card.querySelector('input[type="file"]').addEventListener("change", async (event) => {
      if (upload.id === "takbis") {
        const files = Array.from(event.target.files || []);
        if (!files.length) return;
        try {
          await processTakbisUpload(files);
          state.uploadErrors = { ...(state.uploadErrors || {}), takbis: "" };
        } catch (error) {
          state.uploadErrors = { ...(state.uploadErrors || {}), takbis: error.message || "Dosya okunamadı." };
        }
        autosave();
        renderDocuments();
        renderSection();
        return;
      }
      const files = Array.from(event.target.files || []);
      const file = files[0];
      if (!file) return;
      state.uploads[upload.id] = files.length > 1 ? `${files.length} dosya` : file.name;
      try {
        if (upload.id === "kml") {
          // "Tek dosya seçilirse tüm taşınmazlara uygulansın" kutucuğu
          // işaretliyse VE gerçekten TEK dosya seçildiyse (birden fazla
          // dosya seçilmişse zaten her biri kendi ada/parseline eşlenen
          // NORMAL çoklu-KML akışı geçerli olmalı — kutucuk bu durumda
          // görmezden gelinir) applyKmlFileToAllTitleUnits() kullanılır.
          const applyAllCheckbox = card.querySelector(".kml-apply-all-checkbox");
          if (applyAllCheckbox?.checked && files.length === 1) {
            await applyKmlFileToAllTitleUnits(files[0]);
            applyAllCheckbox.checked = false;
          } else {
            await processKmlFiles(files);
          }
        } else if (upload.id === "address") {
          await processAddressFile(file);
        } else if (upload.id === "ekb") {
          await processEkbFile(file);
        } else if (upload.id === "imar") {
          await processImarFile(file);
        } else if (upload.id === "jsonDraft") {
          await processJsonDraftFile(file);
        }
        state.uploadErrors = { ...(state.uploadErrors || {}), [upload.id]: "" };
      } catch (error) {
        state.uploadErrors = { ...(state.uploadErrors || {}), [upload.id]: error.message || "Dosya okunamadı." };
      }
      autosave();
      renderDocuments();
      renderSection();
    });

    grid.append(card);
  });

  return grid;
}

async function processJsonDraftFile(file) {
  const text = await readFileAsText(file);
  let payload;
  try {
    payload = JSON.parse(text);
  } catch (error) {
    throw new Error("JSON dosyası okunamadı. Dosyanın rapor taslağı olduğundan emin olun.");
  }
  restoreStateFromImportedJson(payload, file.name || "taslak.json");
}

function restoreStateFromImportedJson(payload, fileName = "") {
  const imported = payload?.state && typeof payload.state === "object" ? payload.state : payload;
  if (!imported || typeof imported !== "object" || Array.isArray(imported)) {
    throw new Error("JSON taslak yapısı geçerli değil.");
  }

  const previousUserDefaults = loadUserDefaults();
  localStorage.removeItem(storageKey);
  const fallback = loadState();
  state = {
    ...fallback,
    ...imported,
    fields: { ...(fallback.fields || {}), ...(imported.fields || {}) },
    uploads: { ...(fallback.uploads || {}), ...(imported.uploads || {}) },
    sourceValues: { ...(fallback.sourceValues || {}), ...(imported.sourceValues || {}) },
    sourceConflicts: { ...(fallback.sourceConflicts || {}), ...(imported.sourceConflicts || {}) },
    lookupOptions: { ...(fallback.lookupOptions || {}), ...(imported.lookupOptions || {}) },
    settings: {
      ...(fallback.settings || {}),
      ...(imported.settings || {}),
      userDefaults: {
        ...previousUserDefaults,
        ...((imported.settings || {}).userDefaults || {}),
      },
    },
    tables: { ...(fallback.tables || {}), ...(imported.tables || {}) },
    importedAt: new Date().toISOString(),
    importedFileName: fileName,
  };
  normalizeAddressSourceState(state);
  applySystemDefaults(state);
  applyUserFieldDefaults(state);
  hydrateImportedAddressAdministrativeFields(state);
  applyImarDerivedBusinessRules(state);
  normalizeReportStateFields(state);
  splitReviewedDocumentsDescriptionsIfNeeded();
  saveState();
  setSyncState("JSON yüklendi", "Taslak verileri bu cihaza aktarıldı.", "saved");
  // Faz 3: paket kökünde activeSectionId varsa (bkz. buildReportJsonExportPayload,
  // cloud/report-library.js), kullanıcı diğer cihazda kaldığı bölümden devam
  // eder; yoksa (eski dosyalar / dış kaynak) her zamanki gibi 1. bölümden başlar.
  const requestedSectionId = typeof payload?.activeSectionId === "string" ? payload.activeSectionId : "";
  if (requestedSectionId && sections.some((section) => section.id === requestedSectionId)) {
    setActiveSection(requestedSectionId);
  } else {
    activeSectionId = sections[0].id;
    render();
  }
}

function hydrateImportedAddressAdministrativeFields(appState) {
  if (!appState || typeof appState !== "object") return;
  const fields = appState.fields || {};
  const kmlFields = appState.sourceValues?.kml?.fields || {};
  const addressFields = appState.sourceValues?.address?.fields || {};
  const fillIfBlank = (targetKey, sourceKeys) => {
    if (String(fields[targetKey] || "").trim()) return;
    const nextValue = sourceKeys
      .map((key) => fields[key] || kmlFields[key] || addressFields[key])
      .find((value) => String(value || "").trim());
    if (nextValue) fields[targetKey] = String(nextValue).trim();
  };
  fillIfBlank("city", ["city", "titleCity"]);
  fillIfBlank("district", ["district", "titleDistrict"]);
  fillIfBlank("neighborhood", ["neighborhood", "titleNeighborhood"]);
}

function syncRenderedAddressFields() {
  ["city", "district", "neighborhood", "postalCode"].forEach((key) => {
    const control = document.querySelector(`[data-field="${key}"]`);
    if (control && control.value !== String(state.fields[key] || "")) {
      control.value = state.fields[key] || "";
    }
  });
}

// Çoklu talep Excel akışı: bir satır bir talep/taşınmazdır. Formda tanımlı
// bütün ana bölüm alanları aynı çalışma sayfasında sütun olarak taşınır.
const MULTI_REQUEST_SECTION_IDS = [
  "case", "address", "title", "encumbrance", "planning", "documents", "land",
  "building", "unit", "comparables", "valuation",
];

function getMultiRequestFieldDefinitions() {
  const seen = new Set();
  const definitions = [];
  MULTI_REQUEST_SECTION_IDS.forEach((sectionId) => {
    const section = sections.find((item) => item.id === sectionId);
    (section?.fields || []).forEach((field) => {
      if (!field?.key || seen.has(field.key)) return;
      seen.add(field.key);
      definitions.push({ key: field.key, label: field.label || field.key });
    });
  });
  return definitions;
}

function getMultiRequestColumnDefinitions() {
  return [
    ...getMultiRequestFieldDefinitions(),
    ...getTitleUnitScopedTableKeys().map((key) => ({
      key: `__table:${key}`,
      label: `Tablo - ${key}`,
      tableKey: key,
    })),
  ];
}

function getMultiRequestUnitFields(index) {
  if (index === state.activeTitleUnitIndex) return state.fields || {};
  if (index === 0) return state.primaryTitleUnitShadow?.fields || {};
  return state.titleUnits?.[index - 1]?.fields || {};
}

function buildMultiRequestExcelRows() {
  const definitions = getMultiRequestColumnDefinitions();
  const headers = ["Talep No", ...definitions.map((field) => field.label)];
  const rows = [headers];
  const count = getTitleUnitCount();
  for (let index = 0; index < count; index += 1) {
    const fields = getMultiRequestUnitFields(index);
    const tables = index === state.activeTitleUnitIndex
      ? state.tables || {}
      : (index === 0 ? state.primaryTitleUnitShadow?.tables || {} : state.titleUnits?.[index - 1]?.tables || {});
    rows.push([String(index + 1), ...definitions.map((field) => field.tableKey
      ? JSON.stringify(tables[field.tableKey] || [])
      : fields[field.key] ?? "")]);
  }
  return { rows };
}

function normalizeMultiRequestValue(value) {
  return String(value ?? "").trim();
}

function importMultiRequestRows(rows) {
  if (!Array.isArray(rows) || rows.length < 2) throw new Error("Excel dosyasında başlık ve en az bir talep satırı bulunmalı.");
  const headers = rows[0].map((value) => window.RaporMultiRequestXlsx.normalizeHeader(value));
  const definitions = getMultiRequestColumnDefinitions();
  const definitionByHeader = new Map(definitions.map((field) => [window.RaporMultiRequestXlsx.normalizeHeader(field.label), field.key]));
  definitions.forEach((field) => definitionByHeader.set(window.RaporMultiRequestXlsx.normalizeHeader(field.key), field.key));
  const mapped = headers.map((header) => definitionByHeader.get(header) || "");
  const recognized = mapped.filter(Boolean);
  if (!recognized.includes("uavt")) throw new Error("Excel başlıklarında UAVT sütunu bulunamadı.");

  const imported = [];
  const invalidRows = [];
  const seenUavt = new Set();
  rows.slice(1).forEach((row, rowOffset) => {
    const fields = {};
    const tables = {};
    mapped.forEach((key, index) => {
      if (!key) return;
      if (key.startsWith("__table:")) {
        const tableKey = key.slice("__table:".length);
        const raw = normalizeMultiRequestValue(row[index]);
        if (!raw) return;
        try { tables[tableKey] = JSON.parse(raw); } catch { invalidRows.push(rowOffset + 2); }
        return;
      }
      fields[key] = normalizeMultiRequestValue(row[index]);
    });
    const uavt = fields.uavt || "";
    if (!Object.values(fields).some(Boolean)) return;
    if (!/^\d{5,15}$/.test(uavt)) {
      invalidRows.push(rowOffset + 2);
      return;
    }
    if (seenUavt.has(uavt)) return;
    seenUavt.add(uavt);
    imported.push({ fields, tables });
  });
  if (!imported.length) throw new Error("Excel dosyasında geçerli UAVT içeren talep satırı bulunamadı.");
  if (invalidRows.length) {
    const suffix = invalidRows.length > 8 ? ` ve ${invalidRows.length - 8} satır daha` : "";
    if (!window.confirm(`Şu Excel satırlarında geçerli UAVT bulunamadı: ${invalidRows.slice(0, 8).join(", ")}${suffix}. Geçerli satırlarla devam edilsin mi?`)) return 0;
  }
  if (getTitleUnitCount() > 1 || Object.values(state.fields || {}).some(Boolean)) {
    if (!window.confirm("Excel verileri mevcut rapor alanlarını ve çoklu talep listesini değiştirecek. Devam edilsin mi?")) return 0;
  }
  if (state.activeTitleUnitIndex !== 0) switchActiveTitleUnit(0);
  if (imported.length > 1) imported.forEach((item) => { item.fields.requestType = "Çoklu Talep"; });
  state.fields = { ...state.fields, ...(imported[0].fields || {}) };
  state.tables = { ...state.tables, ...(imported[0].tables || {}) };
  state.titleUnits = imported.slice(1).map((item) => createEmptyTitleUnit(item));
  state.primaryTitleUnitShadow = null;
  state.activeTitleUnitIndex = 0;
  if (imported.length > 1) state.fields.requestType = "Çoklu Talep";
  return imported.length;
}

function createMultiRequestExcelPanel() {
  if (!isCurrentUserAdmin() || !window.RaporMultiRequestXlsx) return null;
  const panel = document.createElement("div");
  panel.className = "subsection multi-request-excel-panel";
  panel.innerHTML = `
    <div class="subsection-heading"><div><span class="eyebrow">Çoklu talep</span><h3>Excel ile toplu giriş</h3></div></div>
    <p class="muted-note">Bir satır bir talep olur. Formda tanımlı ana bölüm alanları Excel sütunlarına aktarılır; UAVT sütunu zorunludur.</p>
    <div class="output-export-actions">
      <button type="button" class="secondary-button" data-multi-request-template>Excel şablonunu indir</button>
      <label class="secondary-button file-button">Excel yükle<input type="file" accept=".xlsx,.csv,text/csv" data-multi-request-import hidden /></label>
    </div>
    <p class="export-status" data-multi-request-status aria-live="polite"></p>
  `;
  const status = panel.querySelector("[data-multi-request-status]");
  panel.querySelector("[data-multi-request-template]").addEventListener("click", () => {
    try {
      const { rows } = buildMultiRequestExcelRows();
      window.RaporMultiRequestXlsx.exportRows(rows, `${buildExportBaseFileName()}-coklu-talep.xlsx`);
      status.textContent = "Excel şablonu/listesi indirildi.";
    } catch (error) { status.textContent = error.message || "Excel oluşturulamadı."; }
  });
  panel.querySelector("[data-multi-request-import]").addEventListener("change", async (event) => {
    const file = event.target.files?.[0];
    if (!file) return;
    try {
      const rows = await window.RaporMultiRequestXlsx.readRows(file);
      const count = importMultiRequestRows(rows);
      if (!count) return;
      autosave();
      status.textContent = `${count} talep Excel'den aktarıldı.`;
      render();
    } catch (error) { status.textContent = error.message || "Excel okunamadı."; }
    event.target.value = "";
  });
  return panel;
}

// Kullanıcı talebi: "Farklı Kaydet" (JSON) ve "Tüm Tabloları Excel Olarak
// İndir" ayrı düğmeleri kaldırıldı — "Banka Şablonuyla Kaydet" artık bu
// ikisini (Word ile birlikte) zaten tek bir .zip'te üretiyor
// (bkz. buildBankTemplateZipBundle), bu yüzden ayrı düğmeler tekrarcı hale
// geldi. Alttaki dışa aktarma fonksiyonları (buildReportJsonExportPayload,
// window.RaporReportTablesXlsx.exportAllTables) SİLİNMEDİ — zip paketleme
// akışı onları hâlâ {download:false} ile doğrudan çağırıyor.
function getSectionExcelOptions(field) {
  const configured = Array.isArray(field?.options) ? field.options : [];
  const remembered = state.lookupOptions?.[field?.key] || [];
  const rendered = field?.type === "select"
    ? [...document.querySelectorAll(`[data-field="${field.key}"] option`)].map((option) => option.value)
    : [];
  return [...new Set([...configured, ...remembered, ...rendered].map((value) => String(value ?? "")))];
}

function getSectionExcelFieldDefinitions(section) {
  const seen = new Set();
  return (section?.fields || []).filter((field) => {
    if (!field?.key || seen.has(field.key)) return false;
    seen.add(field.key);
    return true;
  }).map((field) => ({ key: field.key, label: field.label || field.key, type: field.type, options: getSectionExcelOptions(field) }));
}

function getSectionExcelTableKeys(sectionId) {
  const tableKeys = {
    title: ["title"],
    encumbrance: ["encumbrance", "encumbranceDeclarations", "encumbranceAnnotations", "encumbranceMortgages"],
    documents: ["documents"],
    comparables: ["comparables"],
  };
  return (tableKeys[sectionId] || []).filter((key) => getTitleUnitScopedTableKeys().includes(key));
}

function getSectionExcelColumnLetter(index) {
  let value = index + 1;
  let result = "";
  while (value > 0) {
    const remainder = (value - 1) % 26;
    result = String.fromCharCode(65 + remainder) + result;
    value = Math.floor((value - 1) / 26);
  }
  return result;
}

function getSectionExcelDefinitions(section) {
  return [
    ...getSectionExcelFieldDefinitions(section),
    ...getSectionExcelTableKeys(section.id).map((key) => ({ key: `__table:${key}`, label: `Tablo - ${key}`, tableKey: key, type: "table" })),
  ];
}

function getSectionExcelRows(section) {
  const definitions = getSectionExcelDefinitions(section);
  const rows = [["Kayıt No", ...definitions.map((definition) => definition.label)]];
  for (let index = 0; index < getTitleUnitCount(); index += 1) {
    const fields = getMultiRequestUnitFields(index);
    const tables = index === state.activeTitleUnitIndex
      ? state.tables || {}
      : (index === 0 ? state.primaryTitleUnitShadow?.tables || {} : state.titleUnits?.[index - 1]?.tables || {});
    rows.push([String(index + 1), ...definitions.map((definition) => definition.tableKey
      ? JSON.stringify(tables[definition.tableKey] || [])
      : fields[definition.key] ?? "")]);
  }
  return { rows, definitions };
}

function getSectionExcelValidations(definitions) {
  return definitions.flatMap((definition, index) => {
    if (definition.type !== "select" || !Array.isArray(definition.options) || !definition.options.length) return [];
    const options = definition.options.map((option) => String(option ?? "")).join(",");
    if (options.length > 240 || options.includes('"')) return [];
    const column = getSectionExcelColumnLetter(index + 1);
    return [{ sqref: `${column}2:${column}1048576`, formula1: `"${options}"` }];
  });
}

function importSectionExcelRows(section, rows) {
  if (!Array.isArray(rows) || rows.length < 2) throw new Error("Excel dosyasında başlık ve en az bir veri satırı bulunmalı.");
  const definitions = getSectionExcelDefinitions(section);
  const byHeader = new Map();
  definitions.forEach((definition) => {
    byHeader.set(window.RaporMultiRequestXlsx.normalizeHeader(definition.label), definition);
    byHeader.set(window.RaporMultiRequestXlsx.normalizeHeader(definition.key), definition);
  });
  const normalizedHeaders = rows[0].map((header) => window.RaporMultiRequestXlsx.normalizeHeader(header));
  let mapped = normalizedHeaders.map((header) => byHeader.get(header) || null);
  // Excel bazen başlık hücrelerini yeniden biçimlendirir. Uygulamanın kendi
  // dışa aktardığı dosyalarda ilk sütun sabit olduğu için kolon sırası güvenilir
  // bir yedek eşleme olarak kullanılabilir.
  if (!mapped.some(Boolean) && normalizedHeaders[0] === window.RaporMultiRequestXlsx.normalizeHeader("Kayıt No")) {
    mapped = rows[0].slice(1, definitions.length + 1).map((_, index) => definitions[index] || null);
    mapped.unshift(null);
  }
  if (!mapped.some(Boolean)) throw new Error("Excel başlıkları bu ana bölümle eşleşmedi.");
  const imported = rows.slice(1).map((row) => {
    const fields = {};
    const tables = {};
    mapped.forEach((definition, index) => {
      if (!definition) return;
      const value = normalizeMultiRequestValue(row[index]);
      if (definition.tableKey) {
        if (!value) return;
        try { tables[definition.tableKey] = JSON.parse(value); } catch { throw new Error(`${definition.label} hücresindeki JSON okunamadı.`); }
      } else {
        fields[definition.key] = value;
      }
    });
    return { fields, tables };
  }).filter((item) => Object.values(item.fields).some(Boolean) || Object.values(item.tables).some(Boolean));
  if (!imported.length) throw new Error("Excel dosyasında aktarılacak veri bulunamadı.");
  if (getTitleUnitCount() > 1 || Object.values(state.fields || {}).some(Boolean)) {
    if (!window.confirm("Bu Excel aktif ana bölümdeki mevcut verilerin üzerine yazacak. Devam edilsin mi?")) return 0;
  }
  if (state.activeTitleUnitIndex !== 0) switchActiveTitleUnit(0);
  // Bölüm Excel'i mevcut taşınmaz listesini temsil eder. Eski bir içe aktarmadan
  // kalan fazla tablar korunursa aynı taşınmaz grubu ekranda ikinci kez görünür.
  state.titleUnits.length = Math.max(imported.length - 1, 0);
  imported.forEach((item, index) => {
    if (index === 0) {
      state.fields = { ...state.fields, ...item.fields };
      state.tables = { ...state.tables, ...item.tables };
      return;
    }
    const existing = state.titleUnits[index - 1] || createEmptyTitleUnit();
    state.titleUnits[index - 1] = createEmptyTitleUnit({
      ...existing,
      fields: { ...(existing.fields || {}), ...item.fields },
      tables: { ...(existing.tables || {}), ...item.tables },
    });
  });
  if (imported.length > 1) state.fields.requestType = "Çoklu Talep";
  state.activeTitleUnitIndex = 0;
  return imported.length;
}

function hasMixedTitleUnitParcels() {
  if (getTitleUnitCount() < 2) return false;
  const keys = getNarrativeTitleUnitFields().map((fields) => {
    const block = String(fields.blockNo || fields.titleBlockNo || "").trim();
    const parcel = String(fields.parcelNo || fields.titleParcelNo || "").trim();
    return block && parcel ? `${block}/${parcel}` : "";
  });
  return new Set(keys).size > 1;
}

function getSectionExcelIconMarkup(direction) {
  const isDownload = direction === "download";
  const arrowPath = isDownload
    ? '<path d="M44 37V47M44 47L40 43M44 47L48 43" stroke="white" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" />'
    : '<path d="M44 51V41M44 41L40 45M44 41L48 45" stroke="white" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" />';
  return `<svg viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false">
    <path d="M14 8C14 5.79086 15.7909 4 18 4H38L50 16V56C50 58.2091 48.2091 60 46 60H18C15.7909 60 14 58.2091 14 56V8Z" fill="#107C41" />
    <path d="M38 4L50 16H40C38.8954 16 38 15.1046 38 14V4Z" fill="#0E6B37" />
    <path d="M22 22L27 30L22 38H25.5L28.8 32.6L32.1 38H35.5L30.5 30L35.5 22H32L28.8 27.2L25.5 22H22Z" fill="white" />
    <circle cx="44" cy="44" r="12" fill="#1F9A55" stroke="white" stroke-width="2" />
    ${arrowPath}
  </svg>`;
}

function createSectionExcelPanel(section) {
  if (!window.RaporMultiRequestXlsx || !section?.fields?.length) return null;
  const panel = document.createElement("div");
  panel.className = "subsection section-excel-panel";
  const mixedParcels = hasMixedTitleUnitParcels();
  panel.classList.toggle("section-excel-panel--mixed-parcels", mixedParcels);
  panel.dataset.parcelScope = mixedParcels ? "mixed" : "shared-or-single";
  panel.innerHTML = `
    <div class="subsection-heading"><div><span class="eyebrow">Aktif ana bölüm</span><h3>${escapeHtml(section.title)} Excel</h3></div></div>
    <p class="muted-note">Yalnızca bu bölümün alanları aktarılır. Açılır liste alanları Excel'de de seçim listesi olarak korunur.</p>
    <div class="output-export-actions">
      <button type="button" class="secondary-button" data-section-excel-export>Excel indir</button>
      <label class="secondary-button file-button">Excel yükle<input type="file" accept=".xlsx,.csv,text/csv" data-section-excel-import hidden /></label>
    </div>
    <p class="export-status" data-section-excel-status aria-live="polite"></p>
  `;
  const exportButton = panel.querySelector("[data-section-excel-export]");
  exportButton.className = "section-excel-icon-button";
  exportButton.innerHTML = getSectionExcelIconMarkup("download");
  exportButton.setAttribute("aria-label", `${section.title} Excel indir`);
  exportButton.title = `${section.title} Excel indir`;
  const importLabel = panel.querySelector(".file-button");
  importLabel.className = "section-excel-icon-button file-button";
  importLabel.insertAdjacentHTML("afterbegin", getSectionExcelIconMarkup("upload"));
  importLabel.setAttribute("aria-label", `${section.title} Excel yükle`);
  importLabel.title = `${section.title} Excel yükle`;
  panel.querySelector(".subsection-heading")?.remove();
  panel.querySelector(".muted-note")?.remove();
  const status = panel.querySelector("[data-section-excel-status]");
  panel.querySelector("[data-section-excel-export]").addEventListener("click", () => {
    try {
      const { rows, definitions } = getSectionExcelRows(section);
      window.RaporMultiRequestXlsx.exportRows(rows, `${buildExportBaseFileName()}-${slugifyFileName(section.id)}.xlsx`, {
        validations: getSectionExcelValidations(definitions),
      });
      status.textContent = "Bölüm Excel dosyası indirildi.";
    } catch (error) { status.textContent = error.message || "Excel oluşturulamadı."; }
  });
  panel.querySelector("[data-section-excel-import]").addEventListener("change", async (event) => {
    const file = event.target.files?.[0];
    if (!file) return;
    try {
      const rows = await window.RaporMultiRequestXlsx.readRows(file);
      const count = importSectionExcelRows(section, rows);
      if (!count) return;
      autosave();
      status.textContent = `${count} kayıt bu bölüme aktarıldı.`;
      render();
    } catch (error) { status.textContent = error.message || "Excel okunamadı."; }
    event.target.value = "";
  });
  return panel;
}

// Kullanıcı talebi (2026-08-12): Takyidat kayıtlarının hangi taşınmazlarda
// ORTAK (aynı yevmiye no ile birden fazla taşınmazda), hangilerinin
// taşınmaza-özel/AYRI olduğunu ayrı, salt-okunur bir Excel özeti olarak
// indirebilmek. Yalnızca Çoklu Talep'te (birden fazla taşınmaz varken)
// anlamlı olduğundan admin-only + getTitleUnitCount() > 1 iken gösterilir.
// Bölüm Excel'inden (createSectionExcelPanel) KASITLI OLARAK AYRI bir
// panel — içe aktarımı YOK, çünkü ortak/ayrı bilgisi yevmiye no'dan
// OTOMATİK hesaplanır; elle düzenlenip geri yüklenebilir bir alan olursa
// gerçek veriyle çelişen yanlış bir "ortak" işareti kalıcı hâle gelebilir.
function createEncumbranceSharedSummaryPanel() {
  if (!window.RaporMultiRequestXlsx || !isCurrentUserAdmin() || getTitleUnitCount() <= 1) return null;
  const panel = document.createElement("div");
  panel.className = "subsection section-excel-panel";
  panel.innerHTML = `
    <div class="output-export-actions">
      <button type="button" class="secondary-button" data-encumbrance-summary-export>Ortak/Ayrı Takyidat Özeti (Excel)</button>
    </div>
    <p class="export-status" data-encumbrance-summary-status aria-live="polite"></p>
  `;
  const status = panel.querySelector("[data-encumbrance-summary-status]");
  panel.querySelector("[data-encumbrance-summary-export]").addEventListener("click", () => {
    try {
      const rows = getEncumbranceMultiUnitSummaryRows();
      if (rows.length <= 1) {
        status.textContent = "Özetlenecek bir takyidat kaydı bulunamadı.";
        return;
      }
      window.RaporMultiRequestXlsx.exportRows(rows, `${buildExportBaseFileName()}-takyidat-ortak-ayri-ozet.xlsx`);
      status.textContent = "Özet Excel dosyası indirildi (salt-okunur, geri yüklenmez).";
    } catch (error) { status.textContent = error.message || "Excel oluşturulamadı."; }
  });
  return panel;
}

function createOutputExportPanel() {
  const panel = document.createElement("div");
  panel.className = "subsection output-export-panel";
  panel.append(createExpenseFeesSummaryPanel());
  appendBankTemplateExportBlock(panel);
  panel.append(createReportPhotosPanel());
  return panel;
}

// "8. Ekler" fotoğraf modülü (2026-08-13, 2. tur — kategori/sayfa yerleşim
// şeması) — kullanıcı talebi: "ben görsellerin eklenmesini ve
// kullanılabilmesini istiyorum ancak bunlar kullanıcı cihazında kalmalı ve
// server a hiç gitmemeli". Şu an yalnızca Emlak Katılım (.docx) export'unda
// "8.1 Fotoğraflar" bölümüne (23 kategori, TEK konsolide token) gömülüyor —
// kullanıcı bilerek diğer banka şablonlarını kapsam dışı bıraktı. Depolama:
// src/exports/report-photos.js (window.RaporReportPhotos, IndexedDB —
// sunucuya hiçbir çağrı yapmaz).
//
// UX (kullanıcı talebi — rakip programın ekran görüntüsüne göre): TEK
// "+ Fotoğraf Ekle" düğmesi → 1) kategori seç (23 seçenek) → 2) fotoğraf(lar)
// seç → 3) sayfa yerleşim şablonu seç (4 görsel seçenek, en-boy oranına göre
// bir varsayılan ÖNERİLİR). Aşağıda yalnızca fotoğrafı OLAN kategoriler,
// Word çıktısındakiyle aynı lacivert başlık önizlemesiyle listelenir —
// fotoğrafsız kategoriler burada da (ve Word'de) hiç görünmez.
function createReportPhotosPanel() {
  const panel = document.createElement("div");
  panel.className = "subsection report-photos-panel";
  panel.innerHTML = `
    <div class="subsection-title-row">
      <div>
        <h4>Fotoğraflar</h4>
        <p class="subtle-text">Bu görseller yalnızca bu cihazda (tarayıcınızda) saklanır, sunucuya hiç gönderilmez. Şu an yalnızca <strong>Emlak Katılım Rapor Formatı</strong> dışa aktarılırken "8. Ekler" bölümüne otomatik gömülür (her görsel en fazla 15 cm genişlikte). <strong>Kapak Fotoğrafı</strong> kategorisi ayrı, tek bir yer tutucu olarak eklenir — Word çıktısında istediğiniz konuma (ör. gerçek kapak sayfasına) taşıyabilirsiniz.</p>
      </div>
      <button type="button" class="primary-button report-photos-add-trigger">+ Fotoğraf Ekle</button>
    </div>
    <div data-report-photos-groups></div>
  `;
  const groupsContainer = panel.querySelector("[data-report-photos-groups]");
  const addTrigger = panel.querySelector(".report-photos-add-trigger");
  if (!window.RaporReportPhotos?.isSupported?.()) {
    addTrigger.disabled = true;
    const warn = document.createElement("p");
    warn.className = "subtle-text";
    warn.textContent = "Bu tarayıcı yerel fotoğraf depolamayı (IndexedDB) desteklemiyor.";
    groupsContainer.append(warn);
    return panel;
  }
  addTrigger.addEventListener("click", () => {
    openReportPhotoCategoryModal((categoryKey) => {
      triggerReportPhotoFilePick(categoryKey, () => refreshReportPhotosGroups(groupsContainer));
    });
  });
  refreshReportPhotosGroups(groupsContainer);
  return panel;
}

async function refreshReportPhotosGroups(groupsContainer) {
  const photos = await window.RaporReportPhotos.listPhotos(state.reportId).catch(() => []);
  groupsContainer.innerHTML = "";
  if (!photos.length) {
    const empty = document.createElement("p");
    empty.className = "subtle-text";
    empty.textContent = "Henüz fotoğraf eklenmedi.";
    groupsContainer.append(empty);
    return;
  }
  window.RaporReportPhotos.PHOTO_CATEGORIES.forEach((category) => {
    const categoryPhotos = photos.filter((p) => p.category === category.key);
    if (!categoryPhotos.length) return; // fotoğrafsız kategori — Word'de de görünmüyor, burada da gösterilmez
    groupsContainer.append(createReportPhotoCategoryGroup(category, categoryPhotos, groupsContainer));
  });
}

function createReportPhotoCategoryGroup(category, categoryPhotos, groupsContainer) {
  const group = document.createElement("div");
  group.className = "report-photos-category-group";
  group.dataset.category = category.key;
  group.innerHTML = `
    <div class="report-photos-category-banner">${escapeHtml(category.label)}</div>
    <div class="report-photos-grid" data-report-photos-grid></div>
  `;
  const grid = group.querySelector("[data-report-photos-grid]");
  categoryPhotos.forEach((photo) => {
    grid.append(createReportPhotoCard(photo, groupsContainer));
  });
  return group;
}

function createReportPhotoCard(photo, groupsContainer) {
  const card = document.createElement("div");
  card.className = "report-photo-card";
  const objectUrl = URL.createObjectURL(photo.blob);
  const orientationLabel = photo.orientation === "portrait" ? "Dikey" : photo.orientation === "square" ? "Kare" : "Yatay";
  card.innerHTML = `
    <img src="${objectUrl}" alt="" class="report-photo-thumb">
    <span class="report-photo-orientation-badge">${escapeHtml(orientationLabel)}</span>
    <input type="text" class="text-input report-photo-caption" placeholder="Açıklama (opsiyonel)" value="${escapeHtml(photo.caption || "")}">
    <div class="report-photo-actions">
      <button type="button" class="mini-button library-danger-button" data-action="delete">Sil</button>
    </div>
  `;
  const img = card.querySelector("img");
  img.addEventListener("load", () => URL.revokeObjectURL(objectUrl), { once: true });
  const captionInput = card.querySelector(".report-photo-caption");
  captionInput.addEventListener("change", async () => {
    await window.RaporReportPhotos.updatePhoto(photo.id, { caption: captionInput.value.trim() });
  });
  card.querySelector('[data-action="delete"]').addEventListener("click", async () => {
    if (!window.confirm("Bu fotoğraf silinsin mi?")) return;
    await window.RaporReportPhotos.removePhoto(photo.id);
    refreshReportPhotosGroups(groupsContainer);
  });
  return card;
}

// Adım 1 — kategori seçim modalı (23 seçenek, tek seçim). Seçim yapılınca
// modal kapanır ve onSelectCategory(categoryKey) çağrılır.
function openReportPhotoCategoryModal(onSelectCategory) {
  document.querySelector(".modal-overlay")?.remove();
  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  overlay.innerHTML = `
    <div class="modal-card modal-card-wide report-photo-category-modal" role="dialog" aria-modal="true" aria-labelledby="reportPhotoCategoryModalTitle">
      <div class="modal-head">
        <h3 id="reportPhotoCategoryModalTitle">Fotoğraf/Belge Türü Seçin</h3>
        <button class="modal-close" type="button" aria-label="Kapat">×</button>
      </div>
      <div class="modal-body">
        <div class="report-photo-category-choice-list" data-report-photo-category-choices></div>
      </div>
    </div>
  `;
  const choicesContainer = overlay.querySelector("[data-report-photo-category-choices]");
  window.RaporReportPhotos.PHOTO_CATEGORIES.forEach((category) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "report-photo-category-choice";
    button.textContent = category.label;
    button.addEventListener("click", () => {
      overlay.remove();
      onSelectCategory(category.key);
    });
    choicesContainer.append(button);
  });
  const close = () => overlay.remove();
  overlay.querySelector(".modal-close").addEventListener("click", close);
  document.body.append(overlay);
}

// Adım 2 — native dosya seçiciyi programatik olarak açar (kategori seçim
// düğmesinin click handler'ı içinden çağrıldığı için tarayıcı bunu kullanıcı
// etkileşimi sayar). Dosyalar seçilince Adım 3'e (yerleşim seçimi) geçer.
function triggerReportPhotoFilePick(categoryKey, onDone) {
  const fileInput = document.createElement("input");
  fileInput.type = "file";
  fileInput.accept = "image/*";
  fileInput.multiple = true;
  fileInput.style.display = "none";
  fileInput.addEventListener("change", async () => {
    const files = fileInput.files?.length ? Array.from(fileInput.files) : [];
    fileInput.remove();
    if (!files.length) return;
    const orientations = await window.RaporReportPhotos.peekOrientations(files).catch(() => []);
    const suggestedLayoutKey = window.RaporReportPhotos.suggestLayoutForOrientations(orientations);
    openReportPhotoLayoutModal(suggestedLayoutKey, async (layoutKey) => {
      try {
        await window.RaporReportPhotos.addPhotos(state.reportId, files, categoryKey, layoutKey);
      } catch (error) {
        window.alert(`Fotoğraf eklenemedi: ${error?.message || error}`);
      } finally {
        onDone();
      }
    });
  });
  document.body.append(fileInput);
  fileInput.click();
}

// Adım 3 — sayfa yerleşim şablonu seçimi (4 görsel seçenek: Yatay İkili/
// Dikey Tekli/Alt Alta İkili/6'lı Grid). Fotoğrafların çoğunluğunun
// yönüne göre hesaplanan suggestedLayoutKey öne çıkarılır (rozet), kullanıcı
// yine de diğerini seçebilir.
function openReportPhotoLayoutModal(suggestedLayoutKey, onSelectLayout) {
  document.querySelector(".modal-overlay")?.remove();
  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  overlay.innerHTML = `
    <div class="modal-card modal-card-wide report-photo-layout-modal" role="dialog" aria-modal="true" aria-labelledby="reportPhotoLayoutModalTitle">
      <div class="modal-head">
        <h3 id="reportPhotoLayoutModalTitle">Sayfa Yerleşimi Seçin</h3>
        <button class="modal-close" type="button" aria-label="Kapat">×</button>
      </div>
      <div class="modal-body">
        <div class="report-photo-layout-choice-list" data-report-photo-layout-choices></div>
      </div>
    </div>
  `;
  const choicesContainer = overlay.querySelector("[data-report-photo-layout-choices]");
  window.RaporReportPhotos.LAYOUT_TEMPLATES.forEach((layout) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = `report-photo-layout-choice report-photo-layout-choice-${layout.key}`;
    const isSuggested = layout.key === suggestedLayoutKey;
    button.innerHTML = `
      <span class="report-photo-layout-icon" data-columns="${layout.columns}" data-rows="${layout.rows}">
        ${Array.from({ length: layout.columns * layout.rows }, () => '<span class="report-photo-layout-icon-cell"></span>').join("")}
      </span>
      <span class="report-photo-layout-label">${escapeHtml(layout.label)}</span>
      ${isSuggested ? '<span class="report-photo-layout-badge">Önerilen</span>' : ""}
    `;
    button.addEventListener("click", () => {
      overlay.remove();
      onSelectLayout(layout.key);
    });
    choicesContainer.append(button);
  });
  const close = () => overlay.remove();
  overlay.querySelector(".modal-close").addEventListener("click", close);
  document.body.append(overlay);
}

// Masraf yazısı ücret kalemlerinin (Rapor/Değerleme Ücreti, KDV oranları,
// tapu/belediye harcı, GBM ve Birlik Payı, Toplam) canlı bir özetini
// "Banka ve Çıktı" bölümünde gösterir — kullanıcı isbankasi-masraf.html
// gibi bir şablon indirmeden önce tutarları burada görebilir. Değerler
// seçili bankanın masraf grubuna (A/B/C/D) göre hesaplanır (bkz.
// recalculateExpenseFees). Tapu Adedi / Belediye Masrafı / KDV kutucuğu
// değiştikçe updateExpenseFeesSummaryPanel() ile canlı güncellenir.
// Seçili bankanın masraf grubuna (A/B/C/D) göre, Tapu Adedi ve Belediye
// Masrafı alanlarının NASIL doldurulacağını anlatan kullanıcıya-yönelik
// metin. Kullanıcı talebi: "hangi banka formatında belediye ve tapu
// masrafını nasıl gireceğine dair yönlendirme var mı" — yoktu, eklendi.
// Kaynak: Fatura_Masraf_Otomasyon_Sablon.xlsm Module1/Module2 VBA mantığı
// (bkz. recalculateExpenseFees).
const EXPENSE_BANK_GROUP_GUIDANCE = {
  A: {
    tapu: "Tapu Harcı birim tutarını (KDV hariç) sistem otomatik olarak 2026 tarifesinden alır; siz yalnızca tapu adedini girin.",
    belediye: "Makbuzda KDV ayrıca belirtilmişse yukarıdaki kutucuğu işaretleyip makbuzdaki tutarı aynen girin (sistem KDV'yi ayıklar, örn. 1.000 TL → 833,33 TL + %20 KDV = 1.000 TL). Makbuzda KDV belirtilmemişse kutucuğu boş bırakın, makbuzdaki toplam tutarı girin (sistem üzerine %20 KDV ekler, örn. 1.000 TL → 1.000 TL + %20 KDV = 1.200 TL).",
  },
  B: {
    tapu: "Tapu Harcı birim tutarını (KDV hariç) sistem otomatik olarak 2026 tarifesinden alır; siz yalnızca tapu adedini girin.",
    belediye: "Bu bankada makbuz tutarı HER ZAMAN KDV dahil kabul edilir — kutucuk bu bankada görünmez/devre dışıdır. Makbuzdaki toplam tutarı aynen girin, sistem KDV'yi otomatik ayıklar (örn. 1.000 TL → 833,33 TL + %20 KDV = 1.000 TL).",
  },
  C: {
    tapu: "Tapu Harcı KDV ayrıştırmasız, düz gösterilir; siz yalnızca tapu adedini girin.",
    belediye: "Bu bankada belediye harcına KDV eklenmez/ayrıştırılmaz — kutucuk bu bankada görünmez/devre dışıdır. Makbuzdaki tutarı aynen girin, sistem üzerine KDV eklemez (örn. 850 TL → 850 TL, KDV yok).",
  },
  D: {
    tapu: "Tapu Harcı KDV dahil tutar olarak sisteme girilir; siz yalnızca tapu adedini girin.",
    belediye: "Makbuzda KDV ayrıca belirtilmişse yukarıdaki kutucuğu işaretleyip makbuzdaki tutarı aynen girin (sistem KDV'yi ayıklar). Makbuzda KDV belirtilmemişse kutucuğu boş bırakın, makbuzdaki toplam tutarı girin (sistem üzerine %20 KDV ekler).",
  },
};

function getExpenseBankGroupGuidance(bankGroup) {
  return EXPENSE_BANK_GROUP_GUIDANCE[bankGroup] || EXPENSE_BANK_GROUP_GUIDANCE.A;
}

let expenseFeeCloudSyncSelfHealAttempted = false;
function createExpenseFeesSummaryPanel() {
  // Yeni bir taslak (Yeni İş) açıldığında admin masraf sabitleri (KDV oranı,
  // birim ücretler, tarife tablosu) state'ten kaybolabilir; buluttan tekrar
  // çekilmezse bu panel her zaman boş görünür. Bir kez yeniden dener.
  if (!expenseFeeCloudSyncSelfHealAttempted && !state.fields.expenseVatRatePercent && !state.fields.expenseTransportFeeExVat) {
    expenseFeeCloudSyncSelfHealAttempted = true;
    syncExpenseFeesFromCloud();
  }
  recalculateExpenseFees();
  const panel = document.createElement("div");
  panel.className = "subsection expense-fees-summary-panel";
  panel.dataset.expenseSummaryPanel = "true";
  panel.innerHTML = `
    <div class="subsection-title-row" style="margin-top:14px;">
      <div>
        <h4>Masraf Tablosu</h4>
        <p>Değerleme (Rapor) Ücreti, KDV oranı ve diğer masraf kalemleri; seçili bankanın masraf kuralına göre otomatik hesaplanır. Tapu Adedi ve Belediye Masrafı yukarıda girilir.</p>
      </div>
    </div>
    <div class="table-shell">
      <table class="valuation-summary-table expense-fees-summary-table">
        <thead>
          <tr>
            <th>Kalem</th>
            <th class="valuation-summary-value-col">KDV Hariç</th>
            <th class="valuation-summary-value-col">KDV Dahil</th>
          </tr>
        </thead>
        <tbody>
          <tr><td class="valuation-summary-label">Değerleme (Rapor) Ücreti</td><td class="valuation-summary-value-col" data-expense-summary-field="expenseAppraisalFeeExVat"></td><td class="valuation-summary-value-col" data-expense-summary-field="expenseAppraisalFeeIncVat"></td></tr>
          <tr><td class="valuation-summary-label">Ulaşım Bedeli</td><td class="valuation-summary-value-col" data-expense-summary-field="expenseTransportFeeExVat"></td><td class="valuation-summary-value-col" data-expense-summary-field="expenseTransportFeeIncVat"></td></tr>
          <tr><td class="valuation-summary-label">Tapu Harcı</td><td class="valuation-summary-value-col" data-expense-summary-field="expenseTitleDeedFeeExVat"></td><td class="valuation-summary-value-col" data-expense-summary-field="expenseTitleDeedFeeIncVat"></td></tr>
          <tr><td class="valuation-summary-label">Belediye Harcı</td><td class="valuation-summary-value-col" data-expense-summary-field="expenseMunicipalityFeeExVat"></td><td class="valuation-summary-value-col" data-expense-summary-field="expenseMunicipalityFeeIncVat"></td></tr>
          <tr><td class="valuation-summary-label">Gayrimenkul Bilgi Merkezi Payı</td><td class="valuation-summary-value-col" data-expense-summary-field="expenseInfoCenterShareExVat"></td><td class="valuation-summary-value-col" data-expense-summary-field="expenseInfoCenterShareIncVat"></td></tr>
          <tr><td class="valuation-summary-label">Birlik Payı</td><td class="valuation-summary-value-col" data-expense-summary-field="expenseUnionShareExVat"></td><td class="valuation-summary-value-col" data-expense-summary-field="expenseUnionShareIncVat"></td></tr>
          <tr class="expense-fees-summary-total-row"><td class="valuation-summary-label">Toplam Ücret</td><td class="valuation-summary-value-col" data-expense-summary-field="expenseTotalFeeExVat"></td><td class="valuation-summary-value-col" data-expense-summary-field="expenseTotalFeeIncVat"></td></tr>
          <tr class="expense-fees-guidance-row"><td class="valuation-summary-label">Tapu Adedi</td><td colspan="2" data-expense-guidance="tapu"></td></tr>
          <tr class="expense-fees-guidance-row"><td class="valuation-summary-label">Belediye Masrafı</td><td colspan="2" data-expense-guidance="belediye"></td></tr>
        </tbody>
      </table>
    </div>
  `;
  updateExpenseFeesSummaryPanelIn(panel);
  return panel;
}

function updateExpenseFeesSummaryPanelIn(scope) {
  scope.querySelectorAll("[data-expense-summary-field]").forEach((cell) => {
    const key = cell.dataset.expenseSummaryField;
    const raw = String(state.fields[key] || "").trim();
    cell.textContent = raw ? `${raw} TL` : "—";
  });
  const guidance = getExpenseBankGroupGuidance(getExpenseBankGroup(state.fields.bank));
  scope.querySelectorAll("[data-expense-guidance]").forEach((el) => {
    el.textContent = guidance[el.dataset.expenseGuidance] || "";
  });
}

function updateExpenseFeesSummaryPanel() {
  document.querySelectorAll("[data-expense-summary-panel]").forEach((panel) => updateExpenseFeesSummaryPanelIn(panel));
}

// Banka şablonlarıyla dışa aktarma (templates/*.html + src/templates/template-engine.js).
// Motor yüklenmemişse blok hiç görünmez; app.js tek başına da çalışmaya devam eder.
function appendBankTemplateExportBlock(panel) {
  if (!window.RaporTemplates) return;
  const block = document.createElement("div");
  block.className = "output-template-export";
  const options = window.RaporTemplates.listTemplates()
    .filter((entry) => !entry.hiddenFromList)
    .map((entry) => `<option value="${escapeHtml(entry.key)}">${escapeHtml(entry.title)}</option>`)
    .join("");
  block.innerHTML = `
    <div class="subsection-title-row" style="margin-top:14px;">
      <div>
        <h4>Banka Şablonuyla Kaydet</h4>
      </div>
      <span class="export-status" data-output-export-status aria-live="polite"></span>
    </div>
    <div class="output-export-actions">
      <select data-template-select class="text-input" style="max-width:320px;">${options}</select>
      <button type="button" class="primary-button" data-export-template>Banka şablonuyla kaydet (.zip)</button>
    </div>
  `;
  const select = block.querySelector("[data-template-select]");
  const status = block.querySelector("[data-output-export-status]");
  // Kullanıcı bildirimi (2026-08-13): "Banka ve Çıktı bölümünde template
  // türü otomatik gelmiyor" — GERÇEK BUG: burada isLandOwnership=true
  // geçilince defaultTemplateKeyForBank() gizli (hiddenFromList:true)
  // "...-arsa-arazi" anahtarını döndürüyordu, ama `options` listesi az
  // yukarıda TAM OLARAK bu gizli anahtarları FİLTRELİYOR — yani
  // select.value hiçbir <option>'a karşılık gelmeyen bir değere
  // ayarlanıyor, tarayıcı da seçimi boşa/ilk seçeneğe düşürüyor (görünürde
  // "otomatik seçim çalışmıyor" gibi duruyor). Doğrusu: açılır liste HER
  // ZAMAN bankanın GÖRÜNÜR (arsa-arazi olmayan) anahtarını göstermeli —
  // arsa/arazi yönlendirmesi zaten "sessizce" export tıklanınca
  // resolveTemplateKeyForExport() ile aşağıda ayrıca yapılıyor.
  const defaultKey = window.RaporTemplates.defaultTemplateKeyForBank(state.fields.bank);
  if (defaultKey) select.value = defaultKey;
  block.querySelector("[data-export-template]").addEventListener("click", async () => {
    if (!confirmExportWithMissingFields()) return;
    try {
      saveState();
      // Mülkiyet (ownershipType) Arsa/Tarla ise VEYA Mevcut Kullanım Niteliği
      // Arsa/Arazi ise, dropdown'da gösterilmeyen "arsa-arazi" varyantına
      // sessizce yönlendirilir (kullanıcı deneyimini sadeleştirmek için banka
      // basina tek secenek gosterilir).
      const templateKey = window.RaporTemplates.resolveTemplateKeyForExport(select.value, isLandPropertyForBankTemplate());
      const exportCertificate = await createOfficialExportCertificate(templateKey);
      const result = await buildBankTemplateZipBundle(templateKey, { exportCertificate });
      pingReportEvent("exported", state.reportId, buildReportSummaryForPing());
      const suffix = result.ziraatFailed
        ? " (Ziraat ek tablosu pakete eklenemedi.)"
        : (result.ziraatCount != null ? ` Ziraat ek tablosu da pakete eklendi (${result.ziraatCount} alan).` : "");
      if (result.missing.length) {
        showOutputExportStatus(status, `Paket hazırlandı; ${result.missing.length} placeholder eşleşmedi.${suffix}`);
        window.alert(`Paket hazırlandı ancak şu placeholder adları eşleşmedi (Word çıktısında ⚠ ile işaretli):\n\n${[...new Set(result.missing)].join("\n")}\n\nYazımı templates/PLACEHOLDER-REHBERI.md dosyasından kontrol edebilirsiniz.`);
      } else {
        showOutputExportStatus(status, `${result.title} paketi (.zip) hazırlandı.${suffix}`);
      }
    } catch (error) {
      console.error("Şablon paketleme hatası:", error);
      showOutputExportStatus(status, "Paket hazırlanamadı.");
      window.alert(`Paket hazırlanamadı: ${error?.message || error}`);
    }
  });
  panel.append(block);
}

async function exportZiraatEkTabloWithBankTemplateIfNeeded(templateKey, options = {}) {
  if (templateKey !== "ziraat" && templateKey !== "ziraat-arsa-arazi") return null;
  if (!window.RaporZiraatEkTablo?.export) {
    throw new Error("Ziraat ek tablo XLSX motoru yüklenmedi.");
  }
  try {
    return await window.RaporZiraatEkTablo.export(options);
  } catch (error) {
    console.error("Ziraat ek tablo XLSX hatası:", error);
    throw new Error(`Word şablonu hazırlandı ancak Ziraat ek tablosu hazırlanamadı: ${error?.message || error}`);
  }
}

function textToUint8Array(text) {
  return new TextEncoder().encode(String(text ?? ""));
}

async function blobToUint8Array(blob) {
  return new Uint8Array(await blob.arrayBuffer());
}

async function sha256Text(text) {
  if (!globalThis.crypto?.subtle) throw new Error("Tarayıcı rapor doğrulaması için gerekli kripto desteğini sunmuyor.");
  const bytes = new TextEncoder().encode(text);
  const digest = await globalThis.crypto.subtle.digest("SHA-256", bytes);
  return Array.from(new Uint8Array(digest), (value) => value.toString(16).padStart(2, "0")).join("");
}

async function createOfficialExportCertificate(templateKey) {
  const stateDigest = await sha256Text(JSON.stringify(state));
  const response = await fetchRaporApi("/api/export-authorization", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ reportId: state.reportId, templateKey, stateDigest }),
  }, 15000);
  const payload = await response.json().catch(() => null);
  if (!response.ok || !payload?.certificate) {
    throw new Error(payload?.error || "Resmi çıktı yetkilendirmesi alınamadı.");
  }
  return payload.certificate;
}

// Kullanıcı talebi: "excel tablo indirme json dosyası ve rapor word formatı
// Banka Şablonu ile kaydet butonu tıklandığında otomatik zip yada rar
// içinde insin" — Word şablonu, JSON taslağı, Tüm Tablolar Excel dosyası
// (doluysa) ve Ziraat ek tablosu (varsa) STORED bir .zip'te TEK dosya
// olarak iner (bkz. window.RaporXlsxFill.writeStoredZip — .xlsx üretimi
// için zaten var olan bağımlılıksız ZIP yazıcı burada da yeniden kullanılır).
async function buildBankTemplateZipBundle(templateKey, options = {}) {
  // Word şablonu asıl talep edilen çıktı olduğundan burada başarısız olursa
  // zip HİÇ oluşturulmaz (mevcut davranış). Ziraat ek tablosu VE Tüm
  // Tablolar Excel'i ise ikincil eklerdir — biri başarısız olursa paketin
  // geri kalanı yine de indirilsin diye ayrı ayrı try/catch içine alınır.
  const templateResult = await window.RaporTemplates.exportTemplate(templateKey, { download: false });

  const entries = [
    {
      name: templateResult.fileName,
      bytes: templateResult.isBinary ? templateResult.bytes : textToUint8Array(templateResult.content),
    },
  ];

  const jsonPayload = buildReportJsonExportPayload();
  entries.push({ name: jsonPayload.fileName, bytes: textToUint8Array(jsonPayload.content) });
  if (options.exportCertificate) {
    entries.push({
      name: "experify-rapor-dogrulama.json",
      bytes: textToUint8Array(JSON.stringify(options.exportCertificate, null, 2)),
    });
  }
  if (templateResult.valuationVerification) {
    entries.push({
      name: "experify-degerleme-dogrulama.json",
      bytes: textToUint8Array(JSON.stringify(templateResult.valuationVerification, null, 2)),
    });
  }

  if (window.RaporReportTablesXlsx?.exportAllTables) {
    try {
      const xlsxResult = window.RaporReportTablesXlsx.exportAllTables({ download: false });
      entries.push({ name: xlsxResult.fileName, bytes: await blobToUint8Array(xlsxResult.blob) });
    } catch (error) {
      // Dolu tablo yoksa (ör. hiç emsal/malik/takyidat girilmemiş) sessizce
      // atlanır — zip'in geri kalanı yine de hazırlanır.
      console.warn("Tüm Tablolar Excel paketlenemedi, zip'e eklenmeden devam edildi:", error);
    }
  }

  let ziraatResult = null;
  let ziraatFailed = false;
  try {
    ziraatResult = await exportZiraatEkTabloWithBankTemplateIfNeeded(templateKey, { download: false });
  } catch (error) {
    console.warn("Ziraat ek tablosu paketlenemedi, zip'in geri kalanı yine de hazırlanıyor:", error);
    ziraatFailed = true;
  }
  if (ziraatResult?.blob) {
    entries.push({ name: ziraatResult.fileName, bytes: await blobToUint8Array(ziraatResult.blob) });
  }

  if (!window.RaporXlsxFill?.writeStoredZip) {
    throw new Error("Zip paketleme motoru yüklenmedi (xlsx-fill.js).");
  }
  const zipBytes = window.RaporXlsxFill.writeStoredZip(entries);
  const zipBlob = new Blob([zipBytes], { type: "application/zip" });
  const zipFileName = `${buildExportBaseFileName()}-${templateKey}-paket.zip`;
  window.RaporXlsxFill.downloadBlob(zipFileName, zipBlob);

  return {
    zipFileName,
    missing: templateResult.missing,
    title: templateResult.title,
    ziraatCount: ziraatResult?.count ?? null,
    ziraatFailed,
  };
}

function showOutputExportStatus(status, text) {
  if (!status) return;
  status.textContent = text;
  setTimeout(() => {
    if (status.textContent === text) status.textContent = "";
  }, 1800);
}

function buildReportJsonExportPayload() {
  const payload = {
    schema: "rapor-yazma-programi-state",
    schemaVersion: 1,
    exportedAt: new Date().toISOString(),
    appVersion: "20260707-1101",
    activeSectionId,
    state,
  };
  return {
    fileName: `${buildExportBaseFileName()}.json`,
    content: JSON.stringify(payload, null, 2),
    mimeType: "application/json;charset=utf-8",
  };
}

function downloadTextFile(fileName, content, mimeType) {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function buildExportBaseFileName() {
  const textParts = [
    state.fields.caseName || "ekspertiz-raporu",
    state.fields.bank || "",
  ].filter(Boolean).map(slugifyFileName).filter(Boolean);
  const outputDate = dateIsoToTr(new Date().toISOString().slice(0, 10));
  return [...textParts, outputDate].filter(Boolean).join("-") || "ekspertiz-raporu";
}

function slugifyFileName(value) {
  return String(value || "")
    .toLocaleLowerCase("tr-TR")
    .replace(/[ç]/g, "c")
    .replace(/[ğ]/g, "g")
    .replace(/[ı]/g, "i")
    .replace(/[ö]/g, "o")
    .replace(/[ş]/g, "s")
    .replace(/[ü]/g, "u")
    .replace(/[^a-z0-9]+/gi, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 120);
}

function buildWordMhtmlPackage(html, imageAssets = []) {
  const boundary = `----=_RaporYazma_${Date.now().toString(36)}`;
  const lines = [
    "MIME-Version: 1.0",
    `Content-Type: multipart/related; boundary="${boundary}"`,
    "",
    `--${boundary}`,
    "Content-Type: text/html; charset=\"utf-8\"",
    "Content-Transfer-Encoding: base64",
    "Content-Location: report.html",
    "",
    toBase64Utf8(html),
    "",
  ];
  imageAssets.forEach((asset) => {
    lines.push(
      `--${boundary}`,
      `Content-Type: ${asset.mimeType || "image/png"}`,
      "Content-Transfer-Encoding: base64",
      `Content-Location: ${asset.location}`,
      "",
      asset.base64,
      ""
    );
  });
  lines.push(`--${boundary}--`, "");
  return lines.join("\r\n");
}

function toBase64Utf8(value) {
  return btoa(unescape(encodeURIComponent(String(value || ""))));
}


function buildComparableMatrixWordTableHtml() {
  const rows = getComparableRows().filter((row) => Object.values(row || {}).some((value) => String(value || "").trim()));
  if (!rows.length) return "";
  // Kullanıcı talebi: emsal listesinde arsa/tarla ile konut/yapı emsalleri
  // birlikte gösterilir (bkz. 0.0.62 "Tüm Emsaller" kararı), ama Word
  // çıktısındaki tablo bu raporun GERÇEK emsal bileşimine göre alakasız
  // satırları içermemeli — ör. hiçbir emsal arsa/tarla değilse "İmar
  // Lejandı"/"Yapılaşma Nizamı" gibi arsaya özel satırlar hiç görünmemeli,
  // hiçbiri konut/yapı değilse Oda Sayısı gibi konuta özel satırlar da öyle.
  const hasLandComparable = rows.some((row) => isLandComparable(row));
  const hasResidentialComparable = rows.some((row) => !isLandComparable(row));
  const showWorkplaceFields = isWorkplaceLikeUsageNature();
  const fields = comparableFields.filter((field) => {
    if (field.hidden) return false;
    if (!showWorkplaceFields && comparableWorkplaceOnlyFieldKeys.has(field.key)) return false;
    if (showWorkplaceFields && comparableHiddenForWorkplaceFieldKeys.has(field.key)) return false;
    if (!hasLandComparable && comparableLandOnlyFieldKeys.has(field.key)) return false;
    if (!hasResidentialComparable && comparableResidentialOnlyFieldKeys.has(field.key)) return false;
    return true;
  });
  const headers = ["Alan", ...rows.map((_, index) => `Emsal ${index + 1}`)];
  const bodyRows = fields
    .map((field) => [
      field.label,
      ...rows.map((row, rowIndex) => {
        if (field.key === "workplaceFloors") return formatComparableWorkplaceFloorsSummary(row);
        if (field.key === "c1") return formatComparablePhoneForOutput(row.c1);
        return field.computed
          ? calculateComparableFieldValue(field.key, row, rowIndex)
          : formatOutputFieldValue(row[field.key] || "", field);
      }),
    ])
    .filter((row) => row.slice(1).some((value) => String(value || "").trim()));
  const distanceRow = buildComparableDistanceWordMatrixRow(rows);
  if (distanceRow) {
    const locationRowIndex = bodyRows.findIndex((row) => row[0] === "Emsal Konumu");
    if (locationRowIndex >= 0) {
      bodyRows.splice(locationRowIndex + 1, 0, distanceRow);
    } else {
      bodyRows.push(distanceRow);
    }
  }
  if (!bodyRows.length) return "";
  return buildSimpleHtmlTable(headers, bodyRows, "is-matrix", { compact: true });
}

function buildComparableDistanceWordMatrixRow(rows) {
  const values = rows.map((row) => getComparableDistanceTextForWord(row));
  if (!values.some((value) => String(value || "").trim())) return null;
  return ["Taşınmaza Olan Mesafesi", ...values];
}

function getComparableDistanceTextForWord(row = {}) {
  const savedText = String(row.c20 || "").trim();
  if (savedText) return savedText;
  const lat = Number.parseFloat(String(row.c18 || "").replace(",", "."));
  const lng = Number.parseFloat(String(row.c19 || "").replace(",", "."));
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return "";
  return buildComparableLocationText(lat, lng);
}

// Kullanıcı bildirimi (2026-08-16, ARSA emsal export düzeltmesinin devamı):
// canlı ekrandaki "Emsal Değerleme Tablosu" (createComparableValuationSummaryTable)
// TÜM emsaller arsa/tarla nitelikliyken (landMode) FARKLI bir sütun kümesi
// gösterir — Alan yerine Yüzölçümü + Hesaplanan Emsal, İç Özellik Şerefiye/
// Kira sütunları YOK (arazi emsalinde anlamsız), bunun yerine Hesaplanan
// Emsal M² Birim Değeri + İnd. Hesaplanan Emsal M² Birim Değeri EKLENİR.
// Bu fonksiyon (Word/Excel export'un TEK kaynağı, safeCall ile hem
// template-engine.js hem report-tables-xlsx.js tarafından dinamik
// çağrılıyor) o ayrımı HİÇ yapmıyordu — arsa raporlarında export edilen
// tablo her zaman genel (konut) sütun kümesiyle çıkıyordu (İç Özellik/Kira
// sütunları boş "—", Hesaplanan Emsal sütunları HİÇ yoktu) — ekrandakiyle
// AYNI görünmüyordu. Düzeltme: getComparableValuationRows()'un zaten
// döndürdüğü row.landComparable ile AYNI landMode ayrımı burada da
// uygulanıp, ekrandaki İKİ farklı sütun kümesinin BİREBİR export karşılığı
// üretiliyor.
function buildComparableValuationWordTableHtml() {
  const rows = getComparableValuationRows();
  if (!rows.length) return "";
  const landMode = rows.length > 0 && rows.every((row) => row.landComparable);
  const bodyRows = rows.map((row) => formatComparableValuationWordRow(row, landMode));
  bodyRows.push(formatComparableValuationWordRow({ no: "ORTALAMA", ...calculateComparableValuationAverages(rows) }, landMode));
  const ink = getReportThemeToken("--ink", "#152238");
  const blue = getReportThemeToken("--blue", "#3a5691");
  const blueSoft = getReportThemeToken("--blue-soft", "#e4ebf8");
  const rowStyle = "height:0.5cm;mso-height-source:userset;mso-height-rule:exactly;";
  const groupHeaderRowStyle = "height:0.55cm;mso-height-source:userset;mso-height-rule:exactly;";
  const detailHeaderRowStyle = "height:0.8cm;mso-height-source:userset;mso-height-rule:exactly;";
  const widths = landMode
    ? ["6%", "8%", "9%", "13%", "7%", "13%", "9%", "8%", "10%", "9%", "8%"]
    : ["9%", "6%", "12%", "6%", "12%", "8%", "7%", "6%", "10%", "6%", "8%", "10%"];
  const baseCell = `border:0;border-bottom:.25pt solid #ccd6e4;padding:3pt 2pt;mso-padding-alt:3pt 2pt 3pt 2pt;vertical-align:middle;line-height:6pt;mso-line-height-rule:exactly;font-family:Arial,sans-serif;font-size:6pt;color:${ink};white-space:nowrap;`;
  const headerStyle = `${baseCell}background:${blueSoft};color:${blue};font-weight:700;text-align:center;white-space:normal;`;
  const blueHeaderStyle = `${headerStyle}background:#315fae;color:#ffffff;`;
  const darkHeaderStyle = `${headerStyle}background:#23447d;color:#ffffff;`;
  const calculatedHeaderStyle = `${headerStyle}background:#6a3fa0;color:#ffffff;`;
  const bodyStyle = `${baseCell}background:#edf2f8;`;
  const alternateBodyStyle = `${baseCell}background:#e6edf5;`;
  const adjustedStyle = `${baseCell}background:#d5e1f4;color:#1e55a5;font-weight:700;`;
  const calculatedStyle = `${baseCell}background:#e8def4;color:#5a2f92;font-weight:700;`;
  const premiumStyle = `${baseCell}background:#edf2f8;color:#e96f00;font-weight:700;`;
  const alternatePremiumStyle = `${baseCell}background:#e6edf5;color:#e96f00;font-weight:700;`;
  const averageStyle = `${baseCell}background:#24313f;color:#ffffff;font-weight:700;`;
  const averageAdjustedStyle = `${baseCell}background:#315fae;color:#ffffff;font-weight:700;`;
  const averageCalculatedStyle = `${baseCell}background:#6a3fa0;color:#ffffff;font-weight:700;`;
  const groupEdgeStyle = landMode
    ? (index) => {
      if (index === 0) return "border-left:1pt solid #1f2a32;border-right:1pt solid #1f2a32;";
      if ([2, 6, 7, 10].includes(index)) return "border-right:1pt solid #1f2a32;";
      return "";
    }
    : (index) => {
      if (index === 0) return "border-left:1pt solid #1f2a32;border-right:1pt solid #1f2a32;";
      if ([1, 5, 7, 8, 11].includes(index)) return "border-right:1pt solid #1f2a32;";
      return "";
    };
  const headerCell = (text, index, extra = "") => `<th style="${headerStyle}width:${widths[index]};${groupEdgeStyle(index)}${extra}">${escapeHtml(text).replace(/\n/g, "<br>")}</th>`;
  const thead = landMode
    ? `<thead>
      <tr height="21" style="${groupHeaderRowStyle}">
        <th rowspan="2" style="${headerStyle}width:${widths[0]};${groupEdgeStyle(0)}">NO</th>
        <th rowspan="2" style="${headerStyle}width:${widths[1]};${groupEdgeStyle(1)}">YÜZÖLÇÜMÜ<br>m²</th>
        <th rowspan="2" style="${headerStyle}width:${widths[2]};${groupEdgeStyle(2)}">HESAPLANAN EMSAL<br>m²</th>
        <th colspan="4" style="${headerStyle}border-right:1pt solid #1f2a32;">SATIŞ / ARSA DEĞERLEMESİ</th>
        <th rowspan="2" style="${headerStyle}color:#e96f00;width:${widths[7]};${groupEdgeStyle(7)}">KONUM<br>ŞEREFİYESİ</th>
        <th rowspan="2" style="${blueHeaderStyle}width:${widths[8]};${groupEdgeStyle(8)}">İND. M² BİRİM DEĞER<br>TL/m²</th>
        <th rowspan="2" style="${calculatedHeaderStyle}width:${widths[9]};${groupEdgeStyle(9)}">HESAPLANAN EMSAL M² BİRİM DEĞERİ<br>TL/m²</th>
        <th rowspan="2" style="${calculatedHeaderStyle}width:${widths[10]};${groupEdgeStyle(10)}">İND. HESAPLANAN EMSAL M² BİRİM DEĞERİ<br>TL/m²</th>
      </tr>
      <tr height="30" style="${detailHeaderRowStyle}">
        ${headerCell("TALEP EDİLEN DEĞER", 3, "")}
        ${headerCell("P. PAYI", 4, "")}
        ${headerCell("PAZARLIKLI DEĞER", 5, "")}
        ${headerCell("M² BİRİM\nDEĞERİ", 6, "")}
      </tr>
    </thead>`
    : `<thead>
      <tr height="21" style="${groupHeaderRowStyle}">
        <th rowspan="2" style="${headerStyle}width:${widths[0]};${groupEdgeStyle(0)}">NO</th>
        <th rowspan="2" style="${headerStyle}width:${widths[1]};${groupEdgeStyle(1)}">ALAN<br>m²</th>
        <th colspan="4" style="${headerStyle}border-right:1pt solid #1f2a32;">SATIŞ / PİYASA DEĞERLEMESİ</th>
        <th colspan="2" style="${headerStyle}color:#e96f00;border-right:1pt solid #1f2a32;">ŞEREFİYE</th>
        <th rowspan="2" style="${blueHeaderStyle}width:${widths[8]};${groupEdgeStyle(8)}">İND. M² BİRİM<br>TL/m²</th>
        <th colspan="3" style="${headerStyle}border-right:1pt solid #1f2a32;">KİRA DEĞERLEMESİ</th>
      </tr>
      <tr height="30" style="${detailHeaderRowStyle}">
        ${headerCell("TALEP EDİLEN DEĞER", 2, "" )}
        ${headerCell("P. PAYI", 3, "" )}
        ${headerCell("PAZARLIKLI DEĞER", 4, "" )}
        ${headerCell("M² BİRİM\nDEĞERİ", 5, "" )}
        ${headerCell("İÇ ÖZELLİK", 6, "" )}
        ${headerCell("KONUM", 7, "" )}
        <th style="${headerStyle}width:${widths[9]};">KİRA<br>TL/ay</th>
        <th style="${headerStyle}width:${widths[10]};">KİRA BİRİM<br>TL/m²</th>
        <th style="${darkHeaderStyle}width:${widths[11]};">İND. KİRA BİRİM<br>TL/m²</th>
      </tr>
    </thead>`;
  const accentIndexes = landMode ? [8, 9, 10] : [8, 11];
  const meritIndexes = landMode ? [7] : [6, 7];
  const table = `<table class="word-table is-wide comparable-valuation-word-table" style="border-collapse:collapse;width:100%;margin:0;table-layout:fixed;font-family:Arial,sans-serif;font-size:6pt;">
    <colgroup>${widths.map((width) => `<col style="width:${width};">`).join("")}</colgroup>
    ${thead}
    <tbody>${bodyRows.map((row, rowIndex) => {
      const isAverage = rowIndex === bodyRows.length - 1;
      const rowCellStyle = isAverage ? averageStyle : (rowIndex % 2 ? alternateBodyStyle : bodyStyle);
      return `<tr height="19" style="${rowStyle}">${row.map((cell, cellIndex) => {
        const isCalculated = landMode && (cellIndex === 9 || cellIndex === 10);
        const isAdjustedSale = cellIndex === 8;
        const isAdjustedRent = !landMode && cellIndex === 11;
        const style = isAverage
          ? (isCalculated ? averageCalculatedStyle : ((isAdjustedSale || isAdjustedRent) ? averageAdjustedStyle : averageStyle))
          : (isCalculated
            ? calculatedStyle
            : ((isAdjustedSale || isAdjustedRent)
              ? adjustedStyle
              : (meritIndexes.includes(cellIndex) ? (rowIndex % 2 ? alternatePremiumStyle : premiumStyle) : rowCellStyle)));
        return `<td style="${style}width:${widths[cellIndex]};${groupEdgeStyle(cellIndex)}text-align:${cellIndex === 0 ? "center" : "right"};">${formatWordCell(cell)}</td>`;
      }).join("")}</tr>`;
    }).join("")}</tbody>
  </table>`;
  // Word .doc HTML içindeki div çerçevelerini parçalayabildiği için, başlık ve
  // iç tabloyu tek hücreli bir dış tabloyla sarıyoruz. Böylece dört kenar da
  // Word'de tek, kesintisiz bir çerçeve olarak kalır.
  const frame = `<table role="presentation" style="border-collapse:collapse;width:100%;margin:3pt 0 12pt;border:2pt solid #1f2a32;">
    <tr><td style="border-bottom:1.5pt solid #1f2a32;background:#e7e7e7;padding:3pt 5pt;font-family:Arial,sans-serif;font-size:7pt;color:#111;">Emsal Değerleme Tablosu</td></tr>
    <tr><td style="padding:10pt 3pt 3pt;">${table}</td></tr>
  </table>`;
  return wrapWordLandscapeSection("", frame);
}

function formatComparableValuationWordRow(row, landMode = false) {
  if (landMode) {
    return [
      row.no,
      formatComparableSummaryNumber(row.area, { decimals: 2 }),
      formatComparableSummaryNumber(row.calculatedEmsalArea, { decimals: 2 }),
      formatComparableSummaryMoney(row.askingPrice),
      formatComparableSummaryPercent(row.negotiationRate),
      formatComparableSummaryMoney(row.saleValue),
      formatComparableSummaryNumber(row.unitValue, { decimals: 2 }),
      formatComparableSummarySignedPercent(row.locationAdjustment),
      formatComparableSummaryNumber(row.adjustedUnitValue, { decimals: 2 }),
      formatComparableSummaryNumber(row.calculatedEmsalUnitValue, { decimals: 2 }),
      formatComparableSummaryNumber(row.adjustedCalculatedEmsalUnitValue, { decimals: 2 }),
    ];
  }
  return [
    row.no,
    formatComparableSummaryNumber(row.area, { decimals: 2 }),
    formatComparableSummaryMoney(row.askingPrice),
    formatComparableSummaryPercent(row.negotiationRate),
    formatComparableSummaryMoney(row.saleValue),
    formatComparableSummaryNumber(row.unitValue, { decimals: 2 }),
    formatComparableSummarySignedPercent(row.featureAdjustment),
    formatComparableSummarySignedPercent(row.locationAdjustment),
    formatComparableSummaryNumber(row.adjustedUnitValue, { decimals: 2 }),
    formatComparableSummaryMoney(row.rent),
    formatComparableSummaryNumber(row.rentUnitValue, { decimals: 2 }),
    formatComparableSummaryNumber(row.adjustedRentUnitValue, { decimals: 2 }),
  ];
}

// İncelenen belgeler ve takyidat, banka şablonlarının tamamında aynı sıkı
// Word görünümünü korur. Satır yüksekliği Word'ün "0,5 cm / Tam" ayarıdır.
function buildCompactReportWordTableHtml(headers, rows, options = {}) {
  const columnWidths = Array.isArray(options.columnWidths) ? options.columnWidths : [];
  const safeRows = (Array.isArray(rows) ? rows : []).filter((row) => Array.isArray(row));
  const outer = "border:2pt solid #1f2a32;";
  const inner = "border:0.5pt solid #b8c4d8;";
  // Word'de satir yuksekligi, hem sabit yukseklik hem de "exactly" kuralinda
  // metni kirpabiliyor. Tum kompakt rapor tablolarini %20 gevsetip en az
  // belirtilen yukseklikte kalacak sekilde uretiriz.
  const base = `${inner}padding:3.6pt 2.4pt;mso-padding-alt:3.6pt 2.4pt 3.6pt 2.4pt;vertical-align:middle;font-family:Arial,sans-serif;font-size:6pt;line-height:7.2pt;mso-line-height-rule:at-least;color:#152238;`;
  const header = `${base}background:#d7e0f1;color:#2756a4;font-weight:700;text-align:center;`;
  const section = `${base}background:#e6edf8;color:#1f4e92;font-weight:700;`;
  const plain = `${base}background:#f8fbff;`;
  const zebra = `${base}background:#edf3fb;`;
  const columnGroup = columnWidths.length
    ? `<colgroup>${columnWidths.map((width) => `<col style="width:${escapeHtml(width)};">`).join("")}</colgroup>`
    : "";
  const headerHtml = `<tr height="25" style="height:0.66cm;mso-height-source:userset;mso-height-rule:at-least;">${headers.map((label) => `<th style="${header}">${escapeHtml(label)}</th>`).join("")}</tr>`;
  const bodyHtml = safeRows.map((row, index) => {
    const isSection = Boolean(row.__section);
    if (isSection) {
      return `<tr height="23" style="height:0.6cm;mso-height-source:userset;mso-height-rule:at-least;"><td colspan="${headers.length}" style="${section}">${formatWordCell(row[0])}</td></tr>`;
    }
    const cellStyle = index % 2 ? zebra : plain;
    return `<tr height="23" style="height:0.6cm;mso-height-source:userset;mso-height-rule:at-least;">${headers.map((_, cellIndex) => `<td style="${cellStyle}">${formatWordCell(row[cellIndex])}</td>`).join("")}</tr>`;
  }).join("");

  return `<table class="word-table word-table-compact-report" style="border-collapse:collapse;width:100%;margin:6pt 0 12pt;table-layout:fixed;${outer}">
    ${columnGroup}
    <thead>${headerHtml}</thead>
    <tbody>${bodyHtml}</tbody>
  </table>`;
}

function buildReviewedDocumentsWordTableHtml() {
  const formatDocumentDate = (value) => {
    const text = String(value || "").trim();
    const match = text.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    return match ? `${match[3]}.${match[2]}.${match[1]}` : text;
  };
  const rows = getReviewedDocumentTableEntries(state.tables?.documents)
    .map(({ row }) => row)
    .filter((row) => Object.values(row || {}).some((value) => String(value || "").trim()))
    .map((row) => [row.c0 || "", row.c1 || "", formatDocumentDate(row.c2), row.c3 || "", row.c4 || ""]);
  if (!rows.length) return "";
  return buildCompactReportWordTableHtml(
    ["Belge Türü", "İncelenen Kurum", "Tarih", "No", "Kapsam"],
    rows,
    { columnWidths: ["18%", "27%", "12%", "12%", "31%"] },
  );
}

// Çoklu taşınmazlı (state.titleUnits) raporlarda TÜM taşınmazların tapu
// bilgilerini TEK bir tabloda özetler — kullanıcı talebi (2026-08-14):
// "çoklu raporlarda tapu bilgilerini oluşturan tablo yapalım il ilçe
// mahalle mevkii pafta ada parsel yüzölçümü ana taşınmaz niteliği aynı
// ise tabloda gözükmeyecek. diğer bölümler her biri bir sütun olacak
// şekilde tablo oluşsun" — kullanıcı AskUserQuestion ile hem uygulama
// içi önizleme HEM DE export token'ı istedi, "diğer bölümler" için
// TÜM 4 grup (Blok/Kat/BB No, Bağımsız Bölüm Niteliği, Malik+Hisse,
// Edinme Sebebi+Tapu Tarihi/No) onaylandı.
//
// TÜM taşınmazları (birincil + state.titleUnits[]) tek bir listede
// döner. DİKKAT: aktif OLMAYAN taşınmazların güncel verisi state.fields'ta
// DEĞİL, kendi "gölge" yuvasında durur (bkz. switchActiveTitleUnit,
// getTitleUnitFieldsForLabel/getTitleUnitTablesForLabel — SADECE aktif
// index state.fields/state.tables'ı, diğerleri primaryTitleUnitShadow
// veya titleUnits[i-1]'i okur). getTitleUnitTabModels() ile AYNI deseni
// kullanıyoruz ki hangi tab açık olursa olsun tablo HER taşınmazın
// GÜNCEL verisini göstersin.
function buildAllTitleUnitsForSummaryTable() {
  const count = getTitleUnitCount();
  return Array.from({ length: count }, (_, index) => ({
    fields: getTitleUnitFieldsForLabel(index) || {},
    tables: getTitleUnitTablesForLabel(index) || {},
  }));
}

// "İl ilçe mahalle mevkii pafta ada parsel yüzölçümü" — kullanıcının
// AYNI ise gizlenmesini istediği alanlar, TAM bu sırayla. Anahtarlar
// Tapu bölümünün KENDİ alanları (adres bölümüyle KARIŞTIRILMASIN —
// bkz. CLAUDE.md 0.0.342 "_BUYUK/_DUZGUN" notu). NOT: "Ana Taşınmaz
// Niteliği" (mainPropertyQuality) BURADAN 2026-08-15'te ÇIKARILDI —
// kullanıcı talebi "Ana taşınmaz niteliği bölümünü ekle" ile artık
// buildTitleUnitsSummaryTableData()'da HER ZAMAN gösterilen (aynı ise
// gizlenmeyen) sabit bir sütun oldu, bkz. o fonksiyondaki yorum.
const TITLE_UNITS_TABLE_SHARED_FIELD_DEFS = [
  { key: "titleCity", label: "İl" },
  { key: "titleDistrict", label: "İlçe" },
  { key: "titleNeighborhood", label: "Mahalle" },
  { key: "locationName", label: "Mevkii" },
  { key: "sheetNo", label: "Pafta" },
  { key: "blockNo", label: "Ada" },
  { key: "parcelNo", label: "Parsel" },
  { key: "landArea", label: "Yüzölçümü" },
];

// units[].tables.title satırlarındaki (bkz. applyTakbisOwnersToTable:
// c0=Malik, c1=Hisse Payı, c2=Edinme Sebebi, c3=Tapu Tarihi, c4=Yevmiye)
// BİRDEN FAZLA malik/hissedar VARSA, aynı sütun içinde alt alta (\n,
// formatWordCell tarafından <br>'a çevrilir) listelenir.
function joinTitleUnitOwnerColumn(ownerRows, pick) {
  const values = ownerRows.map(pick).map((v) => String(v || "").trim()).filter(Boolean);
  return values.length ? values.join("\n") : "-";
}

// Tabloyu (başlıklar + satırlar) hesaplar; YALNIZCA 2+ taşınmaz varsa
// (tekil raporda "aynı/farklı" karşılaştırması anlamsız) bir sonuç
// döner, aksi halde null.
function buildTitleUnitsSummaryTableData() {
  const units = buildAllTitleUnitsForSummaryTable();
  if (units.length < 2) return null;

  // Kullanıcı talebi (2026-08-14/15, devam): "pafta bölümünü kaldır aynı
  // ada parselde yer alan işlemlerde" / "kml den alınan pafta bilgisi
  // aynı ada parselde ise belirtilmesin" / "İl İlçe Mahalle Pafta ...
  // aynı ada parsel taleplerinde tabloda yer almamalı" — bu ÜÇ mesaj
  // BİRLİKTE dört alanı (İl, İlçe, Mahalle, Pafta) kapsıyor, SADECE
  // Pafta değil (ilk uygulamada kapsam yanlışlıkla Pafta'ya daraltılmıştı
  // — "İL İLÇE MAHALLE HALA ÇIKIYOR AYNI OLMASINA RAĞMEN" ile düzeltildi).
  // Bu dört alan tanım gereği ada/parsel tarafından belirlenir (aynı ada/
  // parsel = aynı il/ilçe/mahalle/pafta, HER ZAMAN); ancak değerleri
  // KML/TAKBİS'ten taşınmaz başına AYRI AYRI içeri alındığından veri
  // girişi tutarsızlığı (boşluk, farklı kaynak, büyük/küçük harf vb.)
  // yüzünden metin olarak FARKLI görünebilir. TÜM taşınmazlar AYNI ada/
  // parseldeyse, bu dört alanın KENDİ metin değeri farklı olsa BİLE
  // zorla GİZLENİR — ada/parsel eşitliği bunların karşılaştırmasından
  // daha ÖNCELİKLİDİR.
  // 2026-08-16: bu karşılaştırma computeTitleUnitsShareSameAdaParsel()'e
  // ÇIKARILDI (İmar Durumu'nun koşullu paylaşımlı/taşınmaza-özgü mantığı da
  // AYNI karşılaştırmayı kullanıyor, bkz. isPlanningScopedByAdaParsel) —
  // davranış BURADA DEĞİŞMEDİ, yalnızca fonksiyona taşındı.
  const allSameAdaParsel = computeTitleUnitsShareSameAdaParsel(units);
  const HIDE_WHEN_SAME_ADA_PARSEL_KEYS = new Set(["titleCity", "titleDistrict", "titleNeighborhood", "sheetNo"]);

  // "aynı ise tabloda gözükmeyecek" — TÜM taşınmazlarda BİREBİR aynı
  // (boşluk arındırılmış) değere sahip alanlar sütun listesinden
  // tamamen ÇIKARILIR.
  const sharedFieldsToShow = TITLE_UNITS_TABLE_SHARED_FIELD_DEFS.filter((def) => {
    if (HIDE_WHEN_SAME_ADA_PARSEL_KEYS.has(def.key) && allSameAdaParsel) return false;
    const values = units.map((unit) => String(unit.fields?.[def.key] || "").trim());
    return !values.every((value) => value === values[0]);
  });

  // Kullanıcı talebi (2026-08-14, devam): "Taşınmaz Kimlik No arsa pay
  // payda cilt sayfa eksik" — bu alanlar "aynı ise gizlensin" listesinde
  // (TITLE_UNITS_TABLE_SHARED_FIELD_DEFS) YOK, dolayısıyla "diğer
  // bölümler" gibi (koşullu Arsa Payı/Payda/Hissesine Düşen Arsa Payı
  // HARİÇ) HER ZAMAN gösterilen sütunlara ekleniyor. "en sola Sıra No
  // sütunu ekle 1 den başla saymaya" — en sol sütun HER ZAMAN 1'den
  // başlayan satır numarası. "taşınmaz kimlik no sıra nodan sonra
  // gelsin" (2026-08-15) — Taşınmaz Kimlik No artık Sıra No'nun HEMEN
  // ardından, paylaşımlı alanlardan (İl/İlçe/Parsel vb.) ÖNCE geliyor.
  //
  // "farklı ada parsellerden oluşan çoklu taleplerde ARSA PAYI ARSA
  // PAYDA KALDIR" (2026-08-15) — Arsa Payı/Payda, taşınmazların TEK bir
  // ORTAK parselin (aynı ada/parsel) toplam alanındaki payını ifade
  // eder (ör. aynı binadaki bağımsız bölümler). Taşınmazlar FARKLI
  // parsellerdeyse her satırın payı/paydası KENDİ (birbirinden bağımsız)
  // parseline aittir — yan yana göstermek YANILTICI olur (kıyaslanamaz
  // değerler aynı sütunda). Bu yüzden bu üç sütun (Arsa Payı, Arsa
  // Payda VE bunlardan hesaplanan Hissesine Düşen Arsa Payı — aynı
  // gerekçeyle) yalnızca TÜM taşınmazlar AYNI ada/parselde
  // (allSameAdaParsel) İSE gösterilir.
  //
  // "Ana taşınmaz niteliği bölümünü ekle" (2026-08-15) — mainPropertyQuality
  // artık TITLE_UNITS_TABLE_SHARED_FIELD_DEFS'te DEĞİL (bkz. o sabitin
  // yorumu); "Bağımsız Bölüm Niteliği" (bağımsız bölümün KENDİ niteliği,
  // ör. Daire/Dükkan) gibi HER ZAMAN gösterilen sabit bir sütun oldu —
  // farklı parsellerde bu alan ayrıca ÖNEMLİDİR (ör. biri Tarla, biri
  // Arsa olabilir) ve yalnızca "aynı metin" diye kaybolmamalı.
  const showShareColumns = allSameAdaParsel;
  const headers = [
    "Sıra No",
    "Taşınmaz Kimlik No",
    ...sharedFieldsToShow.map((def) => def.label),
    "Blok", "Kat", "Bağımsız Bölüm No", "Bağımsız Bölüm Niteliği", "Ana Taşınmaz Niteliği",
    ...(showShareColumns ? ["Arsa Payı", "Arsa Payda", "Hissesine Düşen Arsa Payı"] : []),
    "Malik(ler)", "Hisse Payı",
    "Edinme Sebebi", "Tapu Tarihi", "Yevmiye No", "Cilt", "Sayfa",
  ];

  const rows = units.map((unit, index) => {
    const fields = unit.fields || {};
    const ownerRows = (Array.isArray(unit.tables?.title) ? unit.tables.title : [])
      .filter((row) => String(row?.c0 || "").trim());
    return [
      index + 1,
      String(fields.titlePropertyId || "").trim() || "-",
      ...sharedFieldsToShow.map((def) => String(fields[def.key] || "").trim() || "-"),
      String(fields.titleBlockName || "").trim() || "-",
      String(fields.titleFloor || "").trim() || "-",
      String(fields.unitNo || "").trim() || "-",
      String(fields.titleQuality || "").trim() || "-",
      String(fields.mainPropertyQuality || "").trim() || "-",
      ...(showShareColumns ? [
        String(fields.share || "").trim() || "-",
        String(fields.denominator || "").trim() || "-",
        computeTitleUnitShareOfLandArea(fields),
      ] : []),
      joinTitleUnitOwnerColumn(ownerRows, (r) => r.c0),
      joinTitleUnitOwnerColumn(ownerRows, (r) => r.c1),
      joinTitleUnitOwnerColumn(ownerRows, (r) => r.c2),
      joinTitleUnitOwnerColumn(ownerRows, (r) => r.c3),
      joinTitleUnitOwnerColumn(ownerRows, (r) => r.c4),
      String(fields.registryVolume || "").trim() || "-",
      String(fields.registryPage || "").trim() || "-",
    ];
  });

  // Kullanıcı talebi (2026-08-15, Çift Yönlü Düzenleme Faz 2): hangi
  // hücrenin hangi taşınmaz alanına karşılık geldiğini (headers ile
  // BİREBİR aynı sırada/uzunlukta) taşıyan "gölge" dizi — export yolu
  // (buildTitleUnitsSummaryWordTableHtml) BUNU OKUMAZ, yalnızca
  // düzenlenebilir önizleme (buildTitleUnitsSummaryTableHtmlEditable)
  // kullanır. "seq" = Sıra No (asla düzenlenemez, satır numarası),
  // "scalar" = doğrudan fields[fieldKey] (düzenlenebilir), "computed" =
  // Hissesine Düşen Arsa Payı (landArea/denominator/share'den TÜRETİLİR,
  // düzenlenemez), "owner" = Malik(ler)/Hisse Payı/Edinme Sebebi/Tapu
  // Tarihi/Yevmiye No (N malik satırının BİRLEŞTİRİLMİŞ hücresi — Faz
  // 4'ün popover'ı gelene kadar düzenlenemez, bkz. plan).
  const columnMeta = [
    { kind: "seq" },
    { kind: "scalar", fieldKey: "titlePropertyId" },
    ...sharedFieldsToShow.map((def) => ({ kind: "scalar", fieldKey: def.key })),
    { kind: "scalar", fieldKey: "titleBlockName" },
    { kind: "scalar", fieldKey: "titleFloor" },
    { kind: "scalar", fieldKey: "unitNo" },
    { kind: "scalar", fieldKey: "titleQuality" },
    { kind: "scalar", fieldKey: "mainPropertyQuality" },
    ...(showShareColumns ? [
      { kind: "scalar", fieldKey: "share" },
      { kind: "scalar", fieldKey: "denominator" },
      { kind: "computed" },
    ] : []),
    { kind: "owner", ownerColumn: "c0" },
    { kind: "owner", ownerColumn: "c1" },
    { kind: "owner", ownerColumn: "c2" },
    { kind: "owner", ownerColumn: "c3" },
    { kind: "owner", ownerColumn: "c4" },
    { kind: "scalar", fieldKey: "registryVolume" },
    { kind: "scalar", fieldKey: "registryPage" },
  ];

  // Kullanıcı talebi (2026-08-15): "eğer sistemde hücrede veri yoksa.
  // örnek tarla raporu bb no kat bölümler boş o zaman tabloda bu
  // sütunlar gözükmemeli" — ör. tarla/arazi raporlarında Kat/Bağımsız
  // Bölüm No gibi "diğer bölümler" sütunları TÜM taşınmazlarda boş ("-")
  // kalabilir (arazinin katı/bağımsız bölümü yoktur). Böyle bir sütun,
  // TÜM taşınmazlarda boşsa TAMAMEN KALDIRILIR. "Sıra No" (index 0)
  // hiçbir zaman boş olmadığından (her zaman 1'den başlayan sayı)
  // filtreden etkilenmez — yine de niyeti netleştirmek için elle korunur.
  const columnHasData = headers.map((_, columnIndex) => (
    columnIndex === 0 || rows.some((row) => {
      const value = row[columnIndex];
      return value !== undefined && value !== null && String(value).trim() !== "" && String(value).trim() !== "-";
    })
  ));
  const filteredHeaders = headers.filter((_, columnIndex) => columnHasData[columnIndex]);
  const filteredRows = rows.map((row) => row.filter((_, columnIndex) => columnHasData[columnIndex]));
  const filteredColumnMeta = columnMeta.filter((_, columnIndex) => columnHasData[columnIndex]);
  // sharedFieldsToShow sütunları headers'ta index 2..2+sharedFieldsToShow.length
  // aralığında (0=Sıra No, 1=Taşınmaz Kimlik No — "sıra nodan sonra
  // gelsin" değişikliğiyle kaydı, bkz. yukarıdaki headers dizisi);
  // sharedColumnCount de bu filtreden SONRA gerçekten kalan sayıyı
  // yansıtmalı (aksi halde tüketiciler yanlış bölme noktası kullanır).
  const survivingSharedColumnCount = columnHasData.slice(2, 2 + sharedFieldsToShow.length).filter(Boolean).length;

  return { headers: filteredHeaders, rows: filteredRows, columnMeta: filteredColumnMeta, sharedColumnCount: survivingSharedColumnCount };
}

// "her bir taşınmazın 'Hissesine Düşen Arsa Payı' bölümünü hesapla.
// (Yüzölçümü) / Arsa Payda X Arsa Pay" — kullanıcının verdiği formül
// BİREBİR: (landArea / denominator) × share. parseReportNumber ondalık
// virgül/nokta karışıklığını (Türkçe biçim) çözer; sonuç
// formatSquareMeterArea ile "X.XXX,XX m²" olarak biçimlenir. Herhangi
// bir girdi eksik/geçersizse veya payda 0 ise "-" döner (hesap
// güvenilir değil).
function computeTitleUnitShareOfLandArea(fields) {
  const area = parseReportNumber(fields.landArea);
  const denominator = parseReportNumber(fields.denominator);
  const share = parseReportNumber(fields.share);
  if (!Number.isFinite(area) || !Number.isFinite(denominator) || !Number.isFinite(share) || denominator === 0) return "-";
  return formatSquareMeterArea((area / denominator) * share);
}

// Banka şablonlarına {{TASINMAZLARTAPUTABLOSU}} ile enjekte edilecek
// gerçek HTML tablo (bkz. template-engine.js). Tekil raporda ya da hiç
// taşınmaz yoksa boş döner (placeholder normal {{TOKEN}} akışıyla
// temiz şekilde silinir, "eksik alan" uyarısı OLUŞTURMAZ — diğer tüm
// tablo placeholder'larıyla aynı desen, bkz. buildReviewedDocumentsWordTableHtml).
// "sütun genişliklerini dinamik yap başlıkları metin kaydır yaparak
// birden fazla satır yapabilirsin. tüm hücreler yatay ve dikey ortalı
// olsun" — bu tabloya ÖZEL, KENDİ HTML üretici fonksiyonu var
// (buildCompactReportWordTableHtml PAYLAŞILAN/başka raporlarda da
// kullanılan bir fonksiyon — onu değiştirmek DİĞER tabloları etkilerdi).
function buildTitleUnitsSummaryWordTableHtml() {
  const data = buildTitleUnitsSummaryTableData();
  if (!data || !data.rows.length) return "";
  return buildTitleUnitsSummaryTableHtmlFromData(data.headers, data.rows);
}

// "sütun başlıklarını 2 satır yap böylelikle hücre genişliği bir nebze
// azalacaktır" — table-layout:auto'da tarayıcı, yeterli yatay alan
// olduğunda white-space:normal'e RAĞMEN çok kelimeli başlıkları TEK
// SATIRDA bırakabiliyor (sarma yalnızca alan YETMEYİNCE devreye giriyor),
// bu da o sütunun gereğinden GENİŞ hesaplanmasına yol açıyor. Her başlığı
// elle kırmak yerine, birden fazla kelimeli başlıklarda ORTAYA en yakın
// boşluktan ZORLA <br> ekleyen genel bir yardımcı — tek kelimelik
// başlıklar (İl, Blok, Kat, Cilt, Sayfa...) DOKUNULMADAN kalır (kıracak
// boşluk yok), böylece o sütunlar zaten dar.
function splitTableHeaderLabelIntoTwoLines(label) {
  const text = String(label || "");
  const spaceIndexes = [];
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] === " ") spaceIndexes.push(i);
  }
  if (!spaceIndexes.length) return escapeHtml(text);
  const middle = text.length / 2;
  let bestIndex = spaceIndexes[0];
  let bestDistance = Math.abs(bestIndex - middle);
  spaceIndexes.forEach((index) => {
    const distance = Math.abs(index - middle);
    if (distance < bestDistance) {
      bestDistance = distance;
      bestIndex = index;
    }
  });
  return `${escapeHtml(text.slice(0, bestIndex))}<br>${escapeHtml(text.slice(bestIndex + 1))}`;
}

// "Sıra No" hariç tüm sütun genişlikleri "auto" (içeriğe göre dinamik,
// table-layout:fixed DEĞİL) — Word/tarayıcı en uygun genişliği kendi
// hesaplar. Başlıklar `white-space:normal` (gerekirse birden fazla
// satıra sarar) VE çok kelimeliyse ZORLA 2 satıra bölünür (bkz.
// splitTableHeaderLabelIntoTwoLines). HER hücre (başlık + gövde) hem
// yatay (text-align:center) hem dikey (vertical-align:middle) ortalı.
// Kullanıcı talebi (2026-08-15): "sistemde harfler küçükte olsa
// büyükte olsa tabloda tüm harfler daima büyük olacak" — kaynak veri
// (malik adı, edinme sebebi, taşınmaz niteliği vb.) sistemde HANGİ
// harf büyüklüğüyle girilmiş olursa olsun, bu tabloda HER ZAMAN Türkçe
// büyük harfe (İ/ı dahil) zorlanır — mevcut `toTitleFieldUppercase()`
// (app.js'te Tapu bölümü alanlarının giriş-anı büyütmesi için zaten
// var olan `toLocaleUpperCase("tr-TR")` sarmalayıcısı) burada da
// yeniden kullanılıyor, tekrar yazılmadı. Sayılar (Sıra No vb.)
// büyük/küçük harften etkilenmediğinden zararsız şekilde string'e
// çevrilir.
function buildTitleUnitsSummaryTableHtmlFromData(headers, rows) {
  const ink = getReportThemeToken("--ink", "#152238");
  const line = getReportThemeToken("--line", "#dde3ef");
  const blue = getReportThemeToken("--blue", "#3a5691");
  const surface = getReportThemeToken("--surface", "#ffffff");
  const surfaceMuted = getReportThemeToken("--surface-muted", "#eef2fa");
  const border = `border:1pt solid ${line};`;
  const baseCell = `${border}padding:3pt 4pt;text-align:center;vertical-align:middle;line-height:1.15;color:${ink};background:${surface};font-size:6.5pt;white-space:normal;`;
  const headerCell = `${baseCell}background:${surfaceMuted};color:${blue};font-weight:800;`;
  const zebraCell = `${baseCell}background:${surfaceMuted};`;

  const headerHtml = `<tr>${headers.map((label) => `<th style="${headerCell}">${splitTableHeaderLabelIntoTwoLines(toTitleFieldUppercase(label))}</th>`).join("")}</tr>`;
  const bodyHtml = rows.map((row, rowIndex) => {
    const cellStyle = rowIndex % 2 === 1 ? zebraCell : baseCell;
    return `<tr>${row.map((cell) => `<td style="${cellStyle}">${formatWordCell(toTitleFieldUppercase(cell))}</td>`).join("")}</tr>`;
  }).join("");

  return `<table class="word-table title-units-summary-table" style="border-collapse:collapse;width:100%;margin:5pt 0 12pt;table-layout:auto;">
    <thead>${headerHtml}</thead>
    <tbody>${bodyHtml}</tbody>
  </table>`;
}

// Çift Yönlü Düzenleme, Faz 2 (2026-08-15): "tablo üzerinden değiştirince
// tab değişsin" — yukarıdaki buildTitleUnitsSummaryTableHtmlFromData()
// hem Word export'un HEM DE (Faz 2'ye kadar) salt-okunur ekran önizlemesinin
// PAYLAŞTIĞI fonksiyondu; export'a asla dokunulmaması gerektiğinden
// (bkz. plan: idempotent-launching-kernighan.md) bu TAMAMEN AYRI bir
// renderer — YALNIZCA ekran-içi düzenlenebilir önizleme
// (createTitleUnitsSummaryTablePreview/createAddressUnitsSummaryTablePreview)
// tarafından çağrılır, export akışı (buildTitleUnitsSummaryWordTableHtml/
// buildAddressUnitsSummaryWordTableHtml) hâlâ eski fonksiyonu kullanır.
// Aynı görsel dili (satır içi style=, iki satırlı başlık, zebra) miras
// alır; ek olarak columnMeta[i].kind === "scalar" VE satır aktif taşınmaza
// (activeRowIndex — satır indeksi === taşınmaz indeksi, bkz.
// buildAllTitleUnitsForSummaryTable) aitse hücreye data-unit-index/
// data-field-key + yalnızca bu render'a özel (styles.css'te tanımlı,
// export HTML'ine hiç SIZMAYAN) "tus-editable-cell" sınıfı eklenir.
// "owner" (Malik(ler) vb. — Faz 4'ün popover'ını bekliyor) ve "computed"
// (Hissesine Düşen Arsa Payı — türetilmiş, asla düzenlenemez) sütunları
// ile aktif OLMAYAN taşınmazların satırları (Faz 3'ü bekliyor) düz metin
// kalır. Tıklama/klavye kancası attachTitleUnitsSummaryTableEditing()
// içinde (aşağıda) ayrıca bağlanır.
function buildTitleUnitsSummaryTableHtmlEditable(headers, rows, columnMeta, activeRowIndex) {
  const ink = getReportThemeToken("--ink", "#152238");
  const line = getReportThemeToken("--line", "#dde3ef");
  const blue = getReportThemeToken("--blue", "#3a5691");
  const surface = getReportThemeToken("--surface", "#ffffff");
  const surfaceMuted = getReportThemeToken("--surface-muted", "#eef2fa");
  const border = `border:1pt solid ${line};`;
  const baseCell = `${border}padding:3pt 4pt;text-align:center;vertical-align:middle;line-height:1.15;color:${ink};background:${surface};font-size:6.5pt;white-space:normal;`;
  const headerCell = `${baseCell}background:${surfaceMuted};color:${blue};font-weight:800;`;
  const zebraCell = `${baseCell}background:${surfaceMuted};`;

  const headerHtml = `<tr>${headers.map((label) => `<th style="${headerCell}">${splitTableHeaderLabelIntoTwoLines(toTitleFieldUppercase(label))}</th>`).join("")}</tr>`;
  const bodyHtml = rows.map((row, rowIndex) => {
    const cellStyle = rowIndex % 2 === 1 ? zebraCell : baseCell;
    const cellsHtml = row.map((cell, columnIndex) => {
      const meta = (columnMeta && columnMeta[columnIndex]) || null;
      // Faz 3 (2026-08-15): "yalnızca AKTİF satır" kısıtlaması KALDIRILDI —
      // artık HER satırın "scalar" hücresi düzenlenebilir (gölge-yazma,
      // bkz. resolveTitleUnitWriteTarget/setTitleUnitFieldValue).
      // Faz 4 (2026-08-15): "owner" (Malik(ler)/Hisse Payı/Edinme Sebebi/
      // Tapu Tarihi/Yevmiye No — N malik satırının BİRLEŞTİRİLMİŞ hücresi)
      // artık bir POPOVER tetikleyicisi olarak tıklanabilir (tek hücrede
      // inline düzenleme YAPILMAZ — 5 sütun BAĞIMSIZ \n-birleştiği için
      // satır hizası bozulmasın diye, bkz. plan). "computed" (Hissesine
      // Düşen Arsa Payı) tek istisna: satır farketmeksizin HİÇBİR ZAMAN
      // tıklanabilir değil.
      if (meta && meta.kind === "owner") {
        return `<td style="${cellStyle}cursor:pointer;" class="tus-owner-cell" data-unit-index="${rowIndex}" title="Malik(ler) bilgilerini düzenlemek için tıklayın">${formatWordCell(toTitleFieldUppercase(cell))}</td>`;
      }
      const isEditable = Boolean(meta) && meta.kind === "scalar";
      if (!isEditable) {
        return `<td style="${cellStyle}">${formatWordCell(toTitleFieldUppercase(cell))}</td>`;
      }
      return `<td style="${cellStyle}cursor:text;" class="tus-editable-cell" data-unit-index="${rowIndex}" data-field-key="${escapeHtml(meta.fieldKey)}" title="Düzenlemek için tıklayın">${formatWordCell(toTitleFieldUppercase(cell))}</td>`;
    }).join("");
    // "activeRowIndex" artık düzenlenebilirliği DEĞİL, yalnızca hangi
    // satırın şu an ekranda açık olan tab'a karşılık geldiğini görsel
    // olarak işaretlemek için kullanılıyor (styles.css: .tus-active-row) —
    // kullanıcı tablo üzerinden aktif OLMAYAN bir satırı düzenlerken bile
    // hangi taşınmazın "canlı form" tarafı olduğunu ayırt edebilsin.
    const rowAttr = rowIndex === activeRowIndex ? ' class="tus-active-row"' : "";
    return `<tr${rowAttr}>${cellsHtml}</tr>`;
  }).join("");

  return `<table class="word-table title-units-summary-table title-units-summary-table-editable" style="border-collapse:collapse;width:100%;margin:5pt 0 12pt;table-layout:auto;">
    <thead>${headerHtml}</thead>
    <tbody>${bodyHtml}</tbody>
  </table>`;
}

// Çift Yönlü Düzenleme, Faz 2 — düzenlenebilir önizleme konteynerine
// (buildTitleUnitsSummaryTableHtmlEditable'ın ürettiği HTML'i barındıran
// DOM düğümü) tıklama dinleyicilerini bağlar. tableKind burada
// kullanılmıyor gibi görünse de Faz 4'te (Malik popover'ı) tablo türüne
// göre farklı davranış eklemek için imzada TUTULUYOR.
function attachTitleUnitsSummaryTableEditing(container) {
  if (!container) return;
  container.querySelectorAll(".tus-editable-cell").forEach((cell) => {
    cell.addEventListener("click", () => beginEditingTitleUnitsSummaryCell(cell));
  });
  // Faz 4 (2026-08-15) — "owner" hücreleri (Malik(ler) vb.) inline değil,
  // popover ile düzenlenir (bkz. openTitleUnitOwnerRowEditor).
  container.querySelectorAll(".tus-owner-cell").forEach((cell) => {
    cell.addEventListener("click", () => {
      const unitIndex = Number(cell.dataset.unitIndex);
      if (Number.isInteger(unitIndex)) openTitleUnitOwnerRowEditor(unitIndex);
    });
  });
}

// Kullanıcı talebi (2026-08-17): "bu tablolarda kullanıcı değişiklik
// yaparken eğer değişiklik yaptığı bölüm açılır liste ise tablo üzerinde
// değişiklik yapılmaya çalışıldığında da aynı açılır liste olmalı." —
// Taşınmazlar Tapu/Adres/İmar/Arsa Özeti tablolarının TÜMÜ bu TEK
// fonksiyonu paylaşıyor, bu yüzden buradaki düzeltme HEPSİNE otomatik
// yayılır. Alanın GERÇEK formundaki sabit seçenek listesini (varsa) bulur:
//   1) `landIrrigationWaterSource`/`landIrrigationSystem` — "Sulu Tarım
//      Detayı" popup'ında (openLandIrrigationModal) elle yerleştirilen,
//      section.fields'ta AYRI listelenmeyen 2 istisna, elle eşlenir.
//   2) Diğer TÜM alanlar için `sections[].fields[]`'ta ARANIR — yalnızca
//      `type === "select"` VE statik (boş olmayan) bir `options` dizisi
//      varsa kullanılır. İl/İlçe/İdari Mahalle gibi CANLI (idari
//      veritabanından async doldurulan, bkz. populateAddressLocationSelect/
//      populateTitleLocationSelect) alanların declaratif tanımında STATİK
//      bir `options` dizisi YOK — bu yüzden bu fonksiyon onlar için
//      BİLEREK null döner, o alanlar KAPSAM DIŞI kalmaya devam eder (metin
//      girişi, önceki davranış — canlı ağ sorgusunu tablo hücresi içinde
//      tekrarlamak bu görevin kapsamı dışı).
function getSelectOptionsForFieldKey(fieldKey) {
  if (fieldKey === "landIrrigationWaterSource") return irrigationWaterSourceOptions;
  if (fieldKey === "landIrrigationSystem") return irrigationSystemOptions;
  // Bağımsız Bölüm Genel panelindeki select alanları sections[]'te DEKLARATİF
  // DEĞİL (saf programatik) — yukarıdaki iki İmar istisnasıyla AYNI desen,
  // yoksa bu 6 alan tabloda düz-metin girişine düşer (bkz. plan).
  if (fieldKey === "unitUsageStatus") return unitUsageStatusOptions;
  if (fieldKey === "unitFirstSaleStatus") return unitFirstSaleStatusOptions;
  if (fieldKey === "unitEntrancePosition") return unitEntrancePositionOptions;
  if (fieldKey === "unitConstructionLevel") return unitConstructionLevelOptions;
  if (fieldKey === "unitViewStatus") return unitViewStatusOptions;
  if (fieldKey === "unitHeatingType") return unitHeatingOptions;
  // "unitFloor" Genel panelde DEĞİL, Katlar/Alanlar satır tablosunda
  // (createUnitFloorRowSelect) seçiliyor — aynı seçenek listesi.
  if (fieldKey === "unitFloor") return unitFloorOptions;
  for (const section of sections) {
    const field = (section.fields || []).find((item) => item.key === fieldKey);
    if (field && field.type === "select" && Array.isArray(field.options) && field.options.length) {
      return field.options;
    }
  }
  return null;
}

function beginEditingTitleUnitsSummaryCell(cell) {
  if (!cell || cell.classList.contains("is-editing")) return;
  const unitIndex = Number(cell.dataset.unitIndex);
  const fieldKey = cell.dataset.fieldKey;
  if (!Number.isInteger(unitIndex) || unitIndex < 0 || unitIndex >= getTitleUnitCount() || !fieldKey) return;

  // Faz 3 (2026-08-15): "yalnızca AKTİF taşınmaz" kısıtlaması KALDIRILDI —
  // getTitleUnitFieldsForLabel() aktif/gölge ayrımını KENDİSİ çözer (aktif
  // taşınmaz için state.fields, diğerleri için kendi gölge yuvası).
  const currentValue = String(getTitleUnitFieldsForLabel(unitIndex)[fieldKey] ?? "");
  cell.classList.add("is-editing");
  const originalHtml = cell.innerHTML;
  const selectOptions = getSelectOptionsForFieldKey(fieldKey);
  const input = document.createElement(selectOptions ? "select" : "input");
  input.className = "tus-editable-cell-input";
  if (selectOptions) {
    selectOptions.forEach((option) => {
      const optionElement = document.createElement("option");
      optionElement.value = option;
      optionElement.textContent = option || "Seçiniz";
      input.append(optionElement);
    });
    // Mevcut değer seçenekler DIŞINDAYSA (ör. eski/serbest bir değer)
    // kaybolmasın diye ekstra bir seçenek olarak eklenir — Tapu il/ilçe
    // açılır listesindeki "liste dışı değer korunur" ilkesiyle AYNI
    // (bkz. populateLocationSelect).
    if (currentValue && !selectOptions.includes(currentValue)) {
      const extraOption = document.createElement("option");
      extraOption.value = currentValue;
      extraOption.textContent = currentValue;
      input.append(extraOption);
    }
    input.value = currentValue;
  } else {
    input.type = "text";
    input.value = currentValue;
  }
  cell.innerHTML = "";
  cell.append(input);
  input.focus();
  if (!selectOptions) input.select();

  let settled = false;
  const cancelEdit = () => {
    if (settled) return;
    settled = true;
    cell.classList.remove("is-editing");
    cell.innerHTML = originalHtml;
  };
  const commitEdit = () => {
    if (settled) return;
    settled = true;
    const newValue = input.value;
    cell.classList.remove("is-editing");
    commitTitleUnitsSummaryCellEdit(fieldKey, newValue, unitIndex);
  };

  input.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      input.blur();
    } else if (event.key === "Escape") {
      event.preventDefault();
      cancelEdit();
    }
  });
  input.addEventListener("blur", commitEdit);
  // <select> için seçim yapılınca (bazı tarayıcılarda blur gecikebilir)
  // ANINDA da commit edilir — "settled" bayrağı sayesinde blur'un ardından
  // TEKRAR çalışması zararsızdır (ikinci çağrı sessizce no-op olur).
  if (selectOptions) {
    input.addEventListener("change", commitEdit);
  }
}

// Yeni değeri hedef taşınmaza yazar. Mimari kararlar (plan): "hedef taşınmaz
// AKTİFSE, ekrandaki gerçek <input>'a da değer basılır ve senkron bir
// input event dispatch edilir" (createForm'un dev kaskadını YENİDEN
// YAZMAK yerine TETİKLEMEK için — titleTextUppercaseKeys gibi alan-özel
// davranışlar böylece bedavaya miras alınır). Alan o an ekranda
// render edilmiyorsa (ör. koşullu görünürlük) gerçek kontrol DOM'da
// yoktur — bu durumda normalizeReportFieldValue (createForm'un da
// kullandığı saf fonksiyon) ile state.fields'a doğrudan yazılır ve
// autosave/renderValidation/updateStatus elle tetiklenir (createForm'un
// input dinleyicisinin yaptığının en az kapsamlı ama doğru alt kümesi).
// Faz 3 (2026-08-15): hedef taşınmaz AKTİF DEĞİLSE (unitIndex !==
// state.activeTitleUnitIndex) yukarıdaki İKİ yol da YANLIŞ olurdu —
// state.fields o an BAŞKA bir taşınmazı temsil ediyor, ona yazmak ya da
// createForm'un aktif-taşınmaza-göre hesaplanan kaskadını tetiklemek
// veri karışıklığına yol açardı. Bunun yerine setTitleUnitFieldValue()
// ile DOĞRUDAN hedef taşınmazın gölge yuvasına yazılır — createForm
// kaskadı (refreshXFromCurrentFields vb.) BİLEREK atlanır, çünkü o
// kaskad şu an ekranda görünen (aktif) taşınmaza göre hesaplama yapar.
function commitTitleUnitsSummaryCellEdit(fieldKey, rawValue, unitIndex) {
  if (unitIndex === state.activeTitleUnitIndex) {
    const control = document.querySelector(`[data-field="${fieldKey}"]`);
    if (control) {
      control.value = rawValue;
      control.dispatchEvent(new Event("input", { bubbles: true }));
    } else {
      state.fields[fieldKey] = normalizeReportFieldValue(fieldKey, rawValue);
      autosave();
      renderValidation();
      updateStatus();
    }
  } else {
    setTitleUnitFieldValue(unitIndex, fieldKey, normalizeReportFieldValue(fieldKey, rawValue));
    autosave();
  }
  // Bağımsız Bölüm'ün 7 aynalı alanı (unitFloor/legalArea/currentArea/...)
  // için KAYNAK satırı (unitFloors[0]) da günceller — bkz. yorum,
  // applyUnitFloorMirrorFieldEdit(). Diğer TÜM alanlar için no-op (false
  // döner), bu yüzden koşulsuz çağrılabilir.
  applyUnitFloorMirrorFieldEdit(fieldKey, normalizeReportFieldValue(fieldKey, rawValue), unitIndex);
  // createForm'un kancası (getTitleUnitScopedFieldKeys ile) zaten
  // debounce'lu bir tazeleme tetikliyor — ama kullanıcı bir hücreyi
  // düzenleyip commit ettiğinde tablo GECİKMESİZ güncellenmeli (form
  // alanına yazarken titreşimi önlemek için gereken debounce, tek bir
  // hücre commit'i için gerekli değil), bu yüzden burada AYRICA anında
  // (debounce'suz) çağrılıyor.
  refreshTitleUnitsSummaryTablePreview();
  refreshAddressUnitsSummaryTablePreview();
  refreshImarUnitsSummaryTablePreview();
  refreshLandUnitsSummaryTablePreview();
  refreshDocumentsUnitsSummaryTablePreview();
  refreshValuationUnitsSummaryTablePreview();
  refreshUnitUnitsSummaryTablePreview();
  // Faz 3: Ada/Parsel/Blok/Bağımsız Bölüm No gibi alanlar tab çubuğu
  // etiketlerini (computeTitleUnitTabLabel) etkileyebilir — hangi alan
  // düzenlendiğinden bağımsız olarak HER commit'te tab çubuğu da
  // tazelenir (ucuz; ilgisiz bir alan için çağrılması zararsız).
  refreshTitleUnitTabBar();
}

// Çift Yönlü Düzenleme, Faz 4 (2026-08-15) — kullanıcının PLANDA verdiği TAM
// örneği ("malik ismi hatalı gelmiş, tablo üzerinden düzeltmek") karşılar.
// Bu, mevcut createTable()'ın "title" (Malikler) bölümü mantığıyla AYNI
// LİVE-COMMIT davranışını (her tuş vuruşunda anında state'e yazma, ayrı bir
// "Kaydet" adımı YOK) yalnızca farklı bir DOM konteynerinde (popover)
// tekrarlar — mevcut modal-overlay/modal-card deseni (bkz. openTitleRecordChangeModal,
// yukarıda) yeniden kullanılır. Sütun etiketleri `sections` dizisindeki
// "title" bölümünün `table.columns` tanımıyla ("Malik", "Hisse", "Edinme
// sebebi", "Tapu tarihi", "Yevmiye") BİREBİR AYNI tutulur (elle senkron —
// section tanımı değişirse burası da güncellenmeli, test bunu doğrular).
function openTitleUnitOwnerRowEditor(unitIndex) {
  if (!Number.isInteger(unitIndex) || unitIndex < 0 || unitIndex >= getTitleUnitCount()) return;
  document.querySelector(".modal-overlay")?.remove();

  const columns = ["Malik", "Hisse", "Edinme sebebi", "Tapu tarihi", "Yevmiye"];
  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  overlay.innerHTML = `
    <div class="modal-card modal-card-wide" role="dialog" aria-modal="true" aria-labelledby="titleUnitOwnerEditorTitle">
      <div class="modal-head">
        <h3 id="titleUnitOwnerEditorTitle">Malik(ler) — Taşınmaz ${unitIndex + 1}</h3>
        <button class="modal-close" type="button" aria-label="Kapat">×</button>
      </div>
      <div class="modal-body">
        <p class="modal-lead">Bu taşınmazın malik/hissedar satırlarını düzenleyin — değişiklikler anında kaydedilir.</p>
        <div class="table-shell">
          <table class="table-title owners-table tus-owner-editor-table">
            <thead><tr>${columns.map((label) => `<th>${escapeHtml(label)}</th>`).join("")}<th></th></tr></thead>
            <tbody data-owner-editor-body></tbody>
          </table>
        </div>
        <button class="secondary-button" type="button" data-owner-editor-add>+ Malik ekle</button>
      </div>
      <div class="modal-actions">
        <button class="primary-button" type="button" data-owner-editor-close>Kapat</button>
      </div>
    </div>
  `;

  const tbody = overlay.querySelector("[data-owner-editor-body]");
  // Gerçek Malikler tablosunun (createTable, "title" bölümü) blur'da
  // uyguladığı normalizeReportTableValue (Malik: HER ZAMAN büyük harf,
  // Edinme Sebebi: Başlık Harfleri vb.) İLE AYNI davranış — aksi halde
  // popover'dan girilen değer, gerçek tablodan girilenle FARKLI biçimde
  // saklanırdı (kaynak-düzeyinde bulundu, canlı testte doğrulandı).
  const titleTableSection = sections.find((item) => item.id === "title");

  // Aktif taşınmaz için ekranda GERÇEK bir Malikler tablosu (createTable,
  // "title" bölümü) render edilmiş olabilir — varsa, o tablonun kendi
  // input'una da değer basılıp senkron bir input event dispatch edilir
  // (Faz 2/3'teki "gerçek kontrol varsa TETİKLE" felsefesiyle AYNI): bu
  // sayede o tablonun KENDİ değişim mantığı (refreshTitleOwnershipKindFromOwners/
  // updateOwnerShareSummary) da BEDAVAYA tetiklenmiş olur. Gerçek tablo
  // DOM'da yoksa (farklı sekmedeyiz ya da hedef aktif değil) sessizce
  // atlanır — state zaten setTitleUnitOwnerRowValue ile YAZILMIŞ olur.
  const syncRealOwnersTableInput = (rowIndex, columnIndex, value) => {
    if (unitIndex !== state.activeTitleUnitIndex) return;
    const realRow = document.querySelectorAll(".table-title.owners-table tbody tr")[rowIndex];
    const realCell = realRow?.children?.[columnIndex];
    const realControl = realCell?.querySelector("input, select, textarea");
    if (!realControl || realControl.closest(".tus-owner-editor-table")) return;
    realControl.value = value;
    realControl.dispatchEvent(new Event("input", { bubbles: true }));
  };

  const renderRows = () => {
    const rows = getTitleUnitTablesForLabel(unitIndex).title || [];
    tbody.innerHTML = "";
    if (!rows.length) {
      const tr = document.createElement("tr");
      const td = document.createElement("td");
      td.colSpan = columns.length + 1;
      td.className = "muted-note";
      td.textContent = "Henüz malik satırı yok.";
      tr.append(td);
      tbody.append(tr);
      return;
    }
    rows.forEach((row, rowIndex) => {
      const tr = document.createElement("tr");
      columns.forEach((_, columnIndex) => {
        const key = `c${columnIndex}`;
        const td = document.createElement("td");
        const input = document.createElement("input");
        input.type = "text";
        input.value = row[key] || "";
        input.addEventListener("input", () => {
          setTitleUnitOwnerRowValue(unitIndex, rowIndex, key, input.value);
          autosave();
          refreshTitleUnitsSummaryTablePreview();
          syncRealOwnersTableInput(rowIndex, columnIndex, input.value);
        });
        input.addEventListener("blur", () => {
          const formattedValue = normalizeReportTableValue(titleTableSection, columns[columnIndex], input.value);
          if (formattedValue === input.value) return;
          input.value = formattedValue;
          setTitleUnitOwnerRowValue(unitIndex, rowIndex, key, formattedValue);
          autosave();
          refreshTitleUnitsSummaryTablePreview();
          syncRealOwnersTableInput(rowIndex, columnIndex, formattedValue);
        });
        td.append(input);
        tr.append(td);
      });
      const deleteTd = document.createElement("td");
      const deleteButton = document.createElement("button");
      deleteButton.type = "button";
      deleteButton.className = "row-delete-button";
      deleteButton.setAttribute("aria-label", "Maliki sil");
      deleteButton.textContent = "×";
      deleteButton.addEventListener("click", () => {
        removeTitleUnitOwnerRow(unitIndex, rowIndex);
        autosave();
        refreshTitleUnitsSummaryTablePreview();
        renderRows();
      });
      deleteTd.append(deleteButton);
      tr.append(deleteTd);
      tbody.append(tr);
    });
  };

  renderRows();

  const close = () => overlay.remove();
  overlay.querySelector(".modal-close").addEventListener("click", close);
  overlay.querySelector("[data-owner-editor-close]").addEventListener("click", close);
  overlay.addEventListener("click", (event) => {
    if (event.target === overlay) close();
  });
  overlay.querySelector("[data-owner-editor-add]").addEventListener("click", () => {
    addTitleUnitOwnerRow(unitIndex);
    autosave();
    refreshTitleUnitsSummaryTablePreview();
    renderRows();
    tbody.querySelector("tr:last-child input")?.focus();
  });

  document.body.append(overlay);
  tbody.querySelector("input")?.focus();
}

// Kullanıcı talebi (2026-08-15): "adres ve konum bölümü için aynı mantıkta
// tablo oluşturalım" — Tapu özet tablosuyla (buildTitleUnitsSummaryTableData/
// buildTitleUnitsSummaryWordTableHtml, yukarıda) AYNI DESEN, Adres ve Konum
// bölümü alanları için: İl/İlçe/İdari Mahalle/Sokak-Cadde/Site-Apartman +
// HER ZAMAN gösterilen taşınmaza özgü alanlar (Blok/Giriş/Dış Kapı No/Kat/
// İç Kapı No). buildAllTitleUnitsForSummaryTable() DOĞRUDAN yeniden
// kullanılıyor (o fonksiyon zaten TÜM alanları içeren tam `fields` nesnesini
// döner — Tapu'ya özgü değil); buildTitleUnitsSummaryTableHtmlFromData()
// (2 satırlı başlık + dinamik genişlik + tam ortalama + HER ZAMAN büyük
// harf) de AYNEN yeniden kullanılıyor — ikinci bir HTML üretici YAZILMADI.
//
// NOT (2026-08-15, devam): "Aynı ise gizlensin: İl, İlçe, İdari Mahalle,
// Sokak/Cadde, Site/Apartman bu madde adres tablosu için iptal edilsin" —
// Tapu tablosunun AKSİNE, bu alanlar artık "aynı ise gizle" FİLTRESİNE TABİ
// DEĞİL — TÜM taşınmazlarda birebir aynı olsalar BİLE HER ZAMAN gösterilir
// (yalnızca TÜMÜ boşsa, aşağıdaki genel "boş sütun kaldırılır" kuralıyla
// kalkar). ADDRESS_UNITS_TABLE_SHARED_FIELD_DEFS adı KORUNDU (bu alanların
// "adres kimliği" anlamını hâlâ taşıyor) ama artık eşitlik KARŞILAŞTIRMASI
// YAPILMIYOR.
//
// GÜNCELLEME (2026-08-17): kullanıcı talebi — "adres ve konumda yer alan
// çoklu taleplerde kullanılan tabloda Mevkii Ada ve Parsel Bilgisi Tapu
// Kayıtlarından çekilsin". Adres ve Konum bölümünün KENDİ Mevkii/Ada/Parsel
// alanı YOK — bu üçü zaten Tapu ve Mülkiyet bölümünün alanlarıdır
// (`locationName`/`blockNo`/`parcelNo`, bkz. TITLE_UNITS_TABLE_SHARED_FIELD_DEFS
// yukarıda — anahtarlar "title" öneki TAŞIMAZ, çünkü raporda TEK bir Mevkii/
// Ada/Parsel kavramı vardır, Tapu'ya özgü ayrı bir kopyası yoktur). Bu
// yüzden yeni bir Adres-alanı EKLEMEK yerine, Tapu'nun MEVCUT taşınmaza-özgü
// alanları doğrudan bu tabloya (üçüncü bir "kaynak" tablo YAZILMADAN)
// sütun olarak ekleniyor — hücreye tıklayıp düzenlemek de (mevcut genel
// "scalar" tıkla-düzenle mekanizmasıyla) AYNI alanı günceller, yani Tapu
// sekmesindeki değerle her zaman senkron kalır (iki ayrı kopya YOK).
const ADDRESS_UNITS_TABLE_SHARED_FIELD_DEFS = [
  { key: "city", label: "İl" },
  { key: "district", label: "İlçe" },
  { key: "neighborhood", label: "İdari Mahalle" },
  { key: "locationName", label: "Mevkii" },
  { key: "blockNo", label: "Ada" },
  { key: "parcelNo", label: "Parsel" },
  { key: "street", label: "Sokak / Cadde" },
  { key: "addressSiteName", label: "Site / Apartman" },
];

// Tabloyu (başlıklar + satırlar) hesaplar; YALNIZCA 2+ taşınmaz varsa bir
// sonuç döner, aksi halde null (Tapu tablosuyla AYNI kural).
function buildAddressUnitsSummaryTableData() {
  const units = buildAllTitleUnitsForSummaryTable();
  if (units.length < 2) return null;

  // "UAVT" taşınmazın adres-bazlı kimlik numarasıdır (Tapu tablosundaki
  // "Taşınmaz Kimlik No" ile AYNI konumsal mantık) — Sıra No'nun HEMEN
  // ardından, İl/İlçe/İdari Mahalle/Sokak-Cadde/Site-Apartman'dan ÖNCE
  // gelir. Bu 5 alan (yukarıdaki not) artık HER ZAMAN gösterilir.
  const headers = [
    "Sıra No",
    "UAVT",
    ...ADDRESS_UNITS_TABLE_SHARED_FIELD_DEFS.map((def) => def.label),
    "Blok", "Giriş", "Dış Kapı No", "Kat", "İç Kapı No",
  ];

  const rows = units.map((unit, index) => {
    const fields = unit.fields || {};
    return [
      index + 1,
      String(fields.uavt || "").trim() || "-",
      ...ADDRESS_UNITS_TABLE_SHARED_FIELD_DEFS.map((def) => String(fields[def.key] || "").trim() || "-"),
      String(fields.addressBlockName || "").trim() || "-",
      String(fields.addressEntrance || "").trim() || "-",
      String(fields.outerDoor || "").trim() || "-",
      String(fields.addressFloor || "").trim() || "-",
      String(fields.innerDoor || "").trim() || "-",
    ];
  });

  // "eğer sistemde hücrede veri yoksa ... tabloda bu sütunlar gözükmemeli"
  // (Tapu tablosundaki AYNI kural, 0.0.451) — TÜM taşınmazlarda boş ("-")
  // kalan bir sütun (ör. site içi taşınmazlarda "Giriş" hiç kullanılmıyorsa)
  // tamamen kaldırılır. "Sıra No" (index 0) hiçbir zaman boş olmadığından
  // etkilenmez.
  // Faz 2 (Çift Yönlü Düzenleme, 2026-08-15) — bkz. buildTitleUnitsSummaryTableData()'daki
  // aynı isimli yorum: headers ile BİREBİR aynı sırada/uzunlukta, hangi
  // hücrenin hangi taşınmaz alanına karşılık geldiğini taşıyan gölge dizi.
  // Adres tablosunda "owner"/"computed" sütunu yok — tamamı seq/scalar.
  const columnMeta = [
    { kind: "seq" },
    { kind: "scalar", fieldKey: "uavt" },
    ...ADDRESS_UNITS_TABLE_SHARED_FIELD_DEFS.map((def) => ({ kind: "scalar", fieldKey: def.key })),
    { kind: "scalar", fieldKey: "addressBlockName" },
    { kind: "scalar", fieldKey: "addressEntrance" },
    { kind: "scalar", fieldKey: "outerDoor" },
    { kind: "scalar", fieldKey: "addressFloor" },
    { kind: "scalar", fieldKey: "innerDoor" },
  ];

  const columnHasData = headers.map((_, columnIndex) => (
    columnIndex === 0 || rows.some((row) => {
      const value = row[columnIndex];
      return value !== undefined && value !== null && String(value).trim() !== "" && String(value).trim() !== "-";
    })
  ));
  const filteredHeaders = headers.filter((_, columnIndex) => columnHasData[columnIndex]);
  const filteredRows = rows.map((row) => row.filter((_, columnIndex) => columnHasData[columnIndex]));
  const filteredColumnMeta = columnMeta.filter((_, columnIndex) => columnHasData[columnIndex]);

  return { headers: filteredHeaders, rows: filteredRows, columnMeta: filteredColumnMeta };
}

// Banka şablonlarına {{TASINMAZLARADRESTABLOSU}} ile enjekte edilecek
// gerçek HTML tablo (bkz. template-engine.js) — Tapu tablosunun export
// akışıyla (buildTitleUnitsSummaryWordTableHtml) BİREBİR AYNI desen.
function buildAddressUnitsSummaryWordTableHtml() {
  const data = buildAddressUnitsSummaryTableData();
  if (!data || !data.rows.length) return "";
  return buildTitleUnitsSummaryTableHtmlFromData(data.headers, data.rows);
}

// İmar Durumu Faz B (Çift Yönlü Düzenleme, 2026-08-16) — kullanıcı talebi:
// "farklı ada parselde yer alan taşınmazların oluşturduğu çoklu raporlarda
// tapu bömlümündeki gibi her bölüme ait sütundan oluşan tablo olacak...
