// `projectInstitution` (multiCheckbox) hem dizi hem virgülle-ayrılmış
// metin olarak saklanmış olabilir (bkz. getMultiCheckboxValues) — bu
// SADECE görüntüleme amaçlı readonly sütun için, o fonksiyonun tam
// ayrıştırma mantığını (options eşleştirme vb.) TEKRARLAMADAN, iki
// saklama şeklini de okunabilir tek satıra çevirir.
function formatDocumentsProjectInstitutionCell(fields) {
  const value = fields.projectInstitution;
  if (Array.isArray(value)) return value.map((item) => String(item || "").trim()).filter(Boolean).join(", ");
  return String(value || "").trim();
}

// Bir taşınmazın "İncelenen Belgeler" (Ruhsat/İskan/Proje kayıtları,
// `unit.tables.documents`) kayıtlarını TEK bir okunabilir satıra
// formatlar — dinamik "Belge N" sütunlarında kullanılır.
// getReviewedDocumentChronologicalEntries() (mevcut, ARBİTRER bir
// taşınmazın tablosuyla çağrılabilir, YENİDEN PARAMETRELEŞTİRMEYE gerek
// yok) + normalizeReviewedDocumentRow() (mevcut) DOĞRUDAN yeniden
// kullanılır — YENİ bir ayrıştırıcı YAZILMAZ.
function formatReviewedDocumentSummaryLine(entry) {
  const normalized = normalizeReviewedDocumentRow(entry.row);
  const parts = [normalized.type];
  if (normalized.date) parts.push(normalized.date);
  if (normalized.no) parts.push(`No: ${normalized.no}`);
  return parts.filter(Boolean).join(" - ");
}

// Tabloyu (başlıklar + satırlar) hesaplar; YALNIZCA 2+ taşınmaz VE hepsi
// FARKLI BLOKTA ise bir sonuç döner (Arsa/İmar'ın "farklı ada/parsel"
// koşulunun AKSİNE — bkz. isDocumentsScopedByBlock, "documents" bölümü
// ada/parsel değil BLOK düzeyinde karşılaştırılıyor, kullanıcının
// bildirdiği gerçek budur). "documents" alanlarının paylaşım modeli
// DEĞİŞMİYOR (her zaman taşınmaza-özgü) — bu yalnızca YENİ tablo/tab
// çubuğunun görünürlük kuralı.
function buildDocumentsUnitsSummaryTableData() {
  const units = buildAllTitleUnitsForSummaryTable();
  if (units.length < 2 || !isDocumentsScopedByBlock()) return null;

  const documentColumns = buildTitleUnitsDynamicColumnGroup(
    units, "İncelenen Belge",
    // Boş taşınmazlarda `unit.tables?.documents` undefined olabilir — bunu
    // AÇIKÇA bir boş diziye çevirmeden geçirmek TEHLİKELİ: fonksiyonun
    // varsayılan parametresi (`= state.tables?.documents || []`) yalnızca
    // argüman TAM OLARAK undefined ise devreye girer, bu durumda AKTİF
    // taşınmazın (yanlış) verisine düşerdi — Arsa'nın land getter'larında
    // ÇÖZÜLEN AYNI sınıf hata (bkz. plan) burada da BİLEREK önlenir.
    (unit) => getReviewedDocumentChronologicalEntries(unit.tables?.documents || []),
    (entry) => formatReviewedDocumentSummaryLine(entry),
  );

  const headers = [
    "Sıra No",
    ...DOCUMENTS_UNITS_TABLE_FIELD_DEFS.map((def) => def.label),
    ...documentColumns.map((group) => group.label),
  ];
  const columnMeta = [
    { kind: "seq" },
    ...DOCUMENTS_UNITS_TABLE_FIELD_DEFS.map((def) => ({ kind: def.kind, fieldKey: def.key })),
    ...documentColumns.map(() => ({ kind: "readonly" })),
  ];

  const rows = units.map((unit, index) => {
    const fields = unit.fields || {};
    return [
      index + 1,
      ...DOCUMENTS_UNITS_TABLE_FIELD_DEFS.map((def) => (
        def.key === "projectInstitution"
          ? formatDocumentsProjectInstitutionCell(fields) || "-"
          : String(fields[def.key] || "").trim() || "-"
      )),
      ...documentColumns.map((group) => group.values[index]),
    ];
  });

  // "eğer sistemde hücrede veri yoksa ... tabloda bu sütunlar gözükmemeli"
  // (Tapu/Adres/İmar/Arsa tablolarındaki AYNI kural) — TÜM taşınmazlarda
  // boş ("-") kalan bir sütun tamamen kaldırılır.
  const columnHasData = headers.map((_, columnIndex) => (
    columnIndex === 0 || rows.some((row) => {
      const value = row[columnIndex];
      return value !== undefined && value !== null && String(value).trim() !== "" && String(value).trim() !== "-";
    })
  ));
  const filteredHeaders = headers.filter((_, columnIndex) => columnHasData[columnIndex]);
  const filteredRows = rows.map((row) => row.filter((_, columnIndex) => columnHasData[columnIndex]));
  const filteredColumnMeta = columnMeta.filter((_, columnIndex) => columnHasData[columnIndex]);

  return { headers: filteredHeaders, rows: filteredRows, columnMeta: filteredColumnMeta };
}

// Banka şablonlarına {{TASINMAZLARBELGETABLOSU}} ile enjekte edilecek
// gerçek HTML tablo (bkz. template-engine.js) — Tapu/Adres/İmar/Arsa
// tablolarının export akışıyla BİREBİR AYNI desen.
function buildDocumentsUnitsSummaryWordTableHtml() {
  const data = buildDocumentsUnitsSummaryTableData();
  if (!data || !data.rows.length) return "";
  return buildTitleUnitsSummaryTableHtmlFromData(data.headers, data.rows);
}

// Kullanıcı talebi (2026-08-21): "çift taraflı tablo mantığını dekoratif
// özellikler hariç bağımsız bölüm özellikleri bölümüne uygulayalım" —
// Arsa'nın (LAND_UNITS_TABLE_FIELD_DEFS) BİREBİR AYNI şekli, dinamik sütun
// grubu YOK. Dekoratif Özellikler paneli (unitSalonFloor/.../unitBathroom
// Fixture3, 20 alan) BİLEREK dışarıda — açık kullanıcı talebi. Açıklama
// alanları (unitInteriorDescription/unitDecorativeDescription, uzun
// otomatik-üretilen paragraf) ve eski/dormant fallback alanları da hiçbir
// diğer özet tablosunda sütunlaşmadığı için dışarıda.
//
// Kullanıcı takip talebi (2026-08-21, devam): "çift taraflı düzenleme
// yapabilmeliyim" — Alan/İç Hacim özeti (unitFloor/legalArea/currentArea/
// unitAreaReductionRate/unitLegalTerrace/unitCurrentTerrace/
// unitTerraceReductionRate) İLK sürümde "readonly" bırakılmıştı çünkü bu 7
// alan syncUnitFloorSummaryFields() tarafından TEK YÖNLÜ olarak
// state.tables.unitFloors[0]'dan türetiliyor — tabloya doğrudan yazma
// izni verilseydi, taşınmazın Katlar/Alanlar panelinde İLGİSİZ bir satır
// değiştiğinde bile senkron tekrar tetiklenip tablo-üzerinden girilen
// değeri SESSİZCE ezerdi. Şimdi "scalar" yapıldı AMA riski kapatan asıl
// düzeltme commitTitleUnitsSummaryCellEdit()'teki applyUnitFloorMirrorFieldEdit()
// çağrısı — tablo hücresi düzenlendiğinde YALNIZCA aynalı state.fields[key]
// DEĞİL, kaynağın KENDİSİ (unitFloors[0][rowKey]) de güncellenir; böylece
// sonraki her senkron ZATEN güncel değeri okur, ezme riski kalmaz (bkz.
// UNIT_FLOOR_MIRROR_FIELD_TO_ROW_KEY).
//
// Kullanıcı takip talebi (2026-08-21, devam #2): "tabloda blok ve bağımsız
// bölüm numarası bulunmuyor" — `titleBlockName`("Blok")/`unitNo`("Bağımsız
// Bölüm No") EN BAŞA (Sıra No'nun hemen ardına) eklendi; bunlar Tapu
// bölümünün KENDİ alanları (kendi özet tablosunda zaten düzenlenebilir),
// burada SADECE satırın hangi taşınmaza ait olduğunu tanımlamak için
// "readonly" — Sıra No'nun (kind:"seq") mantıksal devamı.
//
// Kullanıcı takip talebi (2026-08-21, devam #3): "kat sütununu blok ve
// bağımsız bölüm sütunu arasına al. indirgenmiş yasal ve mevcut toplam
// alanlar sütunlarını göster İÇ HACİMLER BÖLÜMÜ salt okunur şekilde
// görseldeki gibi olsun." — üç değişiklik:
// 1) `unitFloor` ("Kat") Blok/Bağımsız Bölüm No ARASINA taşındı (Blok-Kat-BB
//    No, Türkiye'de bir bağımsız bölümün kimliğini tanımlayan ÜÇLÜ — ör.
//    "A Blok, 1. Kat, 5 No'lu Daire").
// 2) `calculateReducedUnitFloorTotal(rows, mode)` (satır panelindeki AYNI
//    hesap, app.js~13229 — TÜM unitFloors satırlarının indirgenmiş
//    alan+teras toplamı) ile "İndirgenmiş Toplam Yasal/Mevcut Alan" (2
//    readonly, computed sütun) eklendi.
// 3) "İç Hacimler - Kat N" (0.0.495, TEK taşınmazın HER kat satırını AYRI
//    metin sütununda gösteren dinamik grup) kullanıcının paylaştığı görsele
//    göre YANLIŞ granülerlikte çıktı — kullanıcı bunun yerine SABİT,
//    oda-TÜRÜ bazlı sayısal sütunlar istedi (Salon/Oda/Mutfak/Banyo/Wc/
//    Antre/Balkon/Diğer, TÜM kat satırları toplanmış). KALDIRILDI, yerine
//    `getUnitFloorInteriorTableGroupCounts()` (aşağıda) ile 8 SABİT
//    (dinamik-DEĞİL, sayısı hep 8) readonly sütun eklendi.
const UNIT_UNITS_TABLE_FIELD_DEFS = [
  { key: "titleBlockName", label: "Blok", kind: "readonly" },
  { key: "unitFloor", label: "Kat", kind: "scalar" },
  { key: "unitNo", label: "Bağımsız Bölüm No", kind: "readonly" },
  { key: "unitUsageStatus", label: "Kullanım Durumu", kind: "scalar" },
  { key: "unitFirstSaleStatus", label: "İlk Satış Durumu", kind: "scalar" },
  { key: "unitEntrancePosition", label: "Bina Girişine Göre Konum", kind: "scalar" },
  { key: "facades", label: "Cepheli Olduğu Yönler", kind: "scalar" },
  { key: "unitConstructionLevel", label: "İnşaat Seviyesi", kind: "scalar" },
  { key: "unitViewStatus", label: "Manzara Durumu", kind: "scalar" },
  { key: "unitHeatingType", label: "Isınma Sistemi", kind: "scalar" },
  { key: "unitHeatingMounted", label: "Isıtma Monte mi?", kind: "scalar" },
  { key: "unitShopFrontage", label: "Cephe (m)", kind: "scalar" },
  { key: "unitShopDepth", label: "Derinlik (m)", kind: "scalar" },
  { key: "legalArea", label: "Yasal Alan (m²)", kind: "scalar" },
  { key: "currentArea", label: "Mevcut Alan (m²)", kind: "scalar" },
  { key: "unitAreaReductionRate", label: "Alan İnd. Oranı", kind: "scalar" },
  { key: "unitLegalTerrace", label: "Yasal Teras (m²)", kind: "scalar" },
  { key: "unitCurrentTerrace", label: "Mevcut Teras (m²)", kind: "scalar" },
  { key: "unitTerraceReductionRate", label: "Teras İnd. Oranı", kind: "scalar" },
];

// İndirgenmiş Toplam Yasal/Mevcut Alan — computed, editable DEĞİL (satır
// panelindeki "İndirgenmiş Toplam ... Alanı" alanlarıyla AYNI hesap,
// calculateReducedUnitFloorTotal, TÜM unitFloors satırlarının toplamı).
const UNIT_UNITS_TABLE_REDUCED_AREA_DEFS = [
  { label: "İndirgenmiş Toplam Yasal Alan (m²)", mode: "legal" },
  { label: "İndirgenmiş Toplam Mevcut Alan (m²)", mode: "current" },
];

// İç Hacimler grup sayıları — SABİT 8 sütun (Antre AYRI, Diğer dahil).
const UNIT_UNITS_TABLE_INTERIOR_GROUP_DEFS = [
  { key: "salon", label: "Salon" },
  { key: "oda", label: "Oda" },
  { key: "mutfak", label: "Mutfak" },
  { key: "banyo", label: "Banyo" },
  { key: "wc", label: "Wc" },
  { key: "antre", label: "Antre" },
  { key: "balkon", label: "Balkon" },
  { key: "diger", label: "Diğer" },
];

// TEK bir iç hacim kalemi adını (parseUnitInteriorItem'dan gelen, normalize
// edilmiş) yukarıdaki 8 gruptan birine sınıflandırır. GABIM Veri Seti'nin
// isKnownUnitInteriorGroupName()/UNIT_INTERIOR_KNOWN_GROUP_PREFIXES'İYLE
// (app.js~35412) KARIŞTIRILMASIN — o, GDYS'ye özgü AYRI/6-gruplu SABİT bir
// sözleşme (Antre orada "Diğer"e düşer); burası o sözleşmeyi DEĞİŞTİRMEDEN
// yalnızca BU tablo için TAMAMEN İZOLE bir sınıflandırma (Antre kendi
// grubu).
function classifyUnitFloorInteriorItemGroup(name) {
  const folded = foldTurkish(name || "").toLocaleLowerCase("tr");
  if (folded.startsWith("salon")) return "salon";
  if (folded.startsWith("oda")) return "oda";
  if (folded.startsWith("mutfak")) return "mutfak";
  if (folded.startsWith("banyo") || folded.startsWith("dus")) return "banyo";
  if (folded.startsWith("wc") || folded.startsWith("tuvalet")) return "wc";
  if (folded.startsWith("antre") || folded.startsWith("hol")) return "antre";
  if (folded.startsWith("balkon") || folded.startsWith("teras") || folded.startsWith("veranda")) return "balkon";
  return "diger";
}

// Bağımsız Bölüm özet tablosunun "İç Hacimler" grubu için — TÜM unitFloors
// satırlarındaki (rows) iç hacim kalemlerini toplayıp 8 grup+adet döner.
function getUnitFloorInteriorTableGroupCounts(rows = []) {
  const counts = { salon: 0, oda: 0, mutfak: 0, banyo: 0, wc: 0, antre: 0, balkon: 0, diger: 0 };
  (rows || []).forEach((row) => {
    String(row.interiors || "").split(",").map((item) => item.trim()).filter(Boolean).forEach((item) => {
      const parsed = parseUnitInteriorItem(item);
      if (!parsed.name) return;
      counts[classifyUnitFloorInteriorItemGroup(parsed.name)] += parsed.count;
    });
  });
  return counts;
}

// fieldKey -> unitFloors satırındaki (row0) karşılık gelen anahtar. Yalnızca
// TEK bir satırın basit aynası olan 7 alan burada — interiorFeatures (ÇOK
// satırlı birleşik özet) BİLEREK YOK, bkz. yukarıdaki yorum.
const UNIT_FLOOR_MIRROR_FIELD_TO_ROW_KEY = {
  unitFloor: "floor",
  legalArea: "legalArea",
  currentArea: "currentArea",
  unitAreaReductionRate: "areaReductionRate",
  unitLegalTerrace: "legalTerrace",
  unitCurrentTerrace: "currentTerrace",
  unitTerraceReductionRate: "terraceReductionRate",
};

// Özet tablodan bu 7 aynalı alandan biri düzenlendiğinde, KAYNAK satırın
// (unitFloors[0]) KENDİSİNİ de günceller — böylece o taşınmazın Katlar/
// Alanlar panelinde SONRADAN alakasız bir satır değişikliği olsa bile,
// syncUnitFloorSummaryFields() ZATEN güncel değeri row0'dan okur (ezme
// riski yok). fieldKey eşleşmiyorsa (bu 7 alandan biri değilse) no-op,
// false döner — commitTitleUnitsSummaryCellEdit() HER hücre için koşulsuz
// çağırabilir.
function applyUnitFloorMirrorFieldEdit(fieldKey, normalizedValue, unitIndex) {
  const rowKey = UNIT_FLOOR_MIRROR_FIELD_TO_ROW_KEY[fieldKey];
  if (!rowKey) return false;
  const rows = resolveTitleUnitUnitFloorsRowsWriteTarget(unitIndex);
  if (!rows[0]) rows[0] = createEmptyUnitFloorRow();
  rows[0][rowKey] = normalizedValue;
  return true;
}

function buildUnitUnitsSummaryTableData() {
  const units = buildAllTitleUnitsForSummaryTable();
  if (units.length < 2) return null;

  const headers = [
    "Sıra No",
    ...UNIT_UNITS_TABLE_FIELD_DEFS.map((def) => def.label),
    ...UNIT_UNITS_TABLE_REDUCED_AREA_DEFS.map((def) => def.label),
    ...UNIT_UNITS_TABLE_INTERIOR_GROUP_DEFS.map((def) => def.label),
  ];
  const columnMeta = [
    { kind: "seq" },
    ...UNIT_UNITS_TABLE_FIELD_DEFS.map((def) => ({ kind: def.kind, fieldKey: def.key })),
    ...UNIT_UNITS_TABLE_REDUCED_AREA_DEFS.map(() => ({ kind: "readonly" })),
    ...UNIT_UNITS_TABLE_INTERIOR_GROUP_DEFS.map(() => ({ kind: "readonly" })),
  ];

  const rows = units.map((unit, index) => {
    const fields = unit.fields || {};
    const floorRows = Array.isArray(unit.tables && unit.tables.unitFloors) ? unit.tables.unitFloors : [];
    const interiorCounts = getUnitFloorInteriorTableGroupCounts(floorRows);
    return [
      index + 1,
      ...UNIT_UNITS_TABLE_FIELD_DEFS.map((def) => String(fields[def.key] || "").trim() || "-"),
      ...UNIT_UNITS_TABLE_REDUCED_AREA_DEFS.map((def) => (
        formatUnitReducedAreaValue(calculateReducedUnitFloorTotal(floorRows, def.mode)) || "-"
      )),
      // Oda-türü sayıları "0" DAHİL her zaman GÖSTERİLİR (aşağıdaki
      // columnHasData'nın "-" / boş varsayımından BİLEREK muaf — bu sabit,
      // her zaman anlamlı bir sayısal döküm, "veri yok" değil).
      ...UNIT_UNITS_TABLE_INTERIOR_GROUP_DEFS.map((def) => String(interiorCounts[def.key] || 0)),
    ];
  });

  // "eğer sistemde hücrede veri yoksa ... tabloda bu sütunlar gözükmemeli"
  // (diğer 6 bölümdeki AYNI kural) — TÜM taşınmazlarda boş ("-") kalan bir
  // sütun tamamen kaldırılır.
  const columnHasData = headers.map((_, columnIndex) => (
    columnIndex === 0 || rows.some((row) => {
      const value = row[columnIndex];
      return value !== undefined && value !== null && String(value).trim() !== "" && String(value).trim() !== "-";
    })
  ));
  const filteredHeaders = headers.filter((_, columnIndex) => columnHasData[columnIndex]);
  const filteredRows = rows.map((row) => row.filter((_, columnIndex) => columnHasData[columnIndex]));
  const filteredColumnMeta = columnMeta.filter((_, columnIndex) => columnHasData[columnIndex]);

  return { headers: filteredHeaders, rows: filteredRows, columnMeta: filteredColumnMeta };
}

// Banka şablonlarına {{TASINMAZLARBAGIMSIZBOLUMTABLOSU}} ile enjekte
// edilecek gerçek HTML tablo (bkz. template-engine.js) — diğer 6 bölümün
// export akışıyla BİREBİR AYNI desen.
function buildUnitUnitsSummaryWordTableHtml() {
  const data = buildUnitUnitsSummaryTableData();
  if (!data || !data.rows.length) return "";
  return buildTitleUnitsSummaryTableHtmlFromData(data.headers, data.rows);
}

function buildTakyidatWordTableHtml() {
  const rows = buildTakyidatTableGroups().flatMap((group) => {
    const items = group.items.length ? group.items : ["Herhangi bir kayıt bulunmamaktadır."];
    return [
      Object.assign([group.title], { __section: true }),
      ...items.map((item, index) => [index + 1, item]),
    ];
  });
  return buildCompactReportWordTableHtml(
    ["No", "Açıklama"],
    rows,
    { columnWidths: ["8%", "92%"] },
  );
}

// Tum uretilen tablolar (banka sablonlarina {{...}} ile enjekte edilenler
// dahil) SATIR ICI stille boyanir; boylece hangi banka sablonuna
// yerlestirilirse yerlestirilsin uygulamanin GERCEK ekran-ici renkleriyle
// (bkz. .malikler-table / .takyidat-table) ayni gorunur — sablonun kendi
// marka rengi (orn. Kuveyt Turk INVEX yesili) veri tablolarini etkilemez.
// class niteligi geriye donuk uyumluluk icin korunur (harici .word-table
// kurallari yalnizca burada belirtilmeyen ozellikler icin devreye girer).
function buildSimpleHtmlTable(headers, rows, className = "", options = {}) {
  const classNames = String(className || "").split(/\s+/).filter(Boolean);
  const isEmphasisFirstCol = classNames.includes("meta") || classNames.includes("is-matrix");
  const isSummaryLastRow = classNames.includes("is-summary");
  const isWide = headers.length > 6;
  // Emsaller/Değerleme/Ziraat Ekspertiz Sistemi Yardımcı/Gabim bölümleri kendi sayfasında
  // başlayıp tek sayfaya sığmalı (kullanıcı talebi) — `options.compact`
  // bu tabloları çağıran yerde (ör. Emsaller matrisi) daha küçük punto ve
  // hücre boşluğuyla üretir; diğer çağrılar (Takyidat, İncelenen Belgeler
  // vb.) etkilenmez.
  const compact = Boolean(options.compact);
  const ink = getReportThemeToken("--ink", "#152238");
  const line = getReportThemeToken("--line", "#dde3ef");
  const blue = getReportThemeToken("--blue", "#3a5691");
  const blueSoft = getReportThemeToken("--blue-soft", "#e4ebf8");
  const surface = getReportThemeToken("--surface", "#ffffff");
  const surfaceMuted = getReportThemeToken("--surface-muted", "#eef2fa");
  const border = `border:1pt solid ${line};`;
  const pad = compact ? "padding:1pt 1.6pt;" : isWide ? "padding:1.8pt 2.2pt;" : "padding:2.4pt 3pt;";
  const baseCell = `${border}${pad}vertical-align:top;line-height:1.05;color:${ink};background:${surface};`;
  const headerCell = `${baseCell}background:${surfaceMuted};color:${blue};font-weight:800;text-align:left;`;
  const emphasisCell = `${baseCell}background:${blueSoft};color:${blue};font-weight:900;`;
  const summaryCell = `${baseCell}background:#1f2a32;color:#ffffff;font-weight:900;`;
  const zebraCell = `${baseCell}background:${surfaceMuted};`;
  const classes = ["word-table"];
  if (isWide) classes.push("is-wide");
  classes.push(...classNames);
  const theadHtml = `<tr>${headers.map((header) => `<th style="${headerCell}">${escapeHtml(header)}</th>`).join("")}</tr>`;
  const lastIndex = rows.length - 1;
  const bodyHtml = rows.map((row, rowIndex) => {
    const isSummaryRow = isSummaryLastRow && rowIndex === lastIndex;
    return `<tr>${row.map((cell, cellIndex) => {
      let cellStyle = baseCell;
      if (isSummaryRow) cellStyle = summaryCell;
      else if (isEmphasisFirstCol && cellIndex === 0) cellStyle = emphasisCell;
      else if (rowIndex % 2 === 1) cellStyle = zebraCell;
      return `<td style="${cellStyle}">${formatWordCell(cell)}</td>`;
    }).join("")}</tr>`;
  }).join("");
  const fontSize = compact ? "5.5pt" : isWide ? "6pt" : "7pt";
  return `<table class="${escapeHtml(classes.join(" "))}" style="border-collapse:collapse;width:100%;margin:${compact ? "3pt 0 12pt" : "5pt 0 12pt"};table-layout:${isWide ? "auto" : "fixed"};font-size:${fontSize};">
    <thead>${theadHtml}</thead>
    <tbody>${bodyHtml}</tbody>
  </table>`;
}

function getReportThemeToken(name, fallback) {
  try {
    const value = getComputedStyle(document.body).getPropertyValue(name).trim();
    return value || fallback;
  } catch (error) {
    return fallback;
  }
}

function buildValuationSummaryWordTableHtml() {
  if (!hasValuationSummaryData()) return "";
  const line = getReportThemeToken("--line", "#dde3ef");
  const ink = getReportThemeToken("--ink", "#152238");
  const muted = getReportThemeToken("--muted", "#5a6576");
  const surface = getReportThemeToken("--surface", "#ffffff");
  const surfaceMuted = getReportThemeToken("--surface-muted", "#eef2fa");
  const blue = getReportThemeToken("--blue", "#3a5691");
  const blueSoft = getReportThemeToken("--blue-soft", "#e4ebf8");
  const amber = getReportThemeToken("--amber", "#9a6a16");
  const amberSoft = getReportThemeToken("--amber-soft", "#f6ecd6");
  const green = getReportThemeToken("--green", "#213f77");
  const greenSoft = getReportThemeToken("--green-soft", "#dde7f6");
  const red = getReportThemeToken("--red", "#b23434");
  // Değerleme Bölümü tek sayfaya sığmalı (kullanıcı talebi) — bu tablo
  // yalnızca o bölümde kullanıldığı için punto/hücre boşluğu doğrudan
  // burada sıkıştırılır.
  const tableStyle = `border-collapse:collapse;width:100%;margin:3pt 0 12pt;table-layout:fixed;font-family:Arial,sans-serif;font-size:6pt;`;
  const cellBase = `border:0;border-bottom:.5pt solid ${line};padding:3pt 5pt;mso-padding-alt:3pt 5pt 3pt 5pt;text-align:left;vertical-align:middle;color:${ink};background:${surface};line-height:6pt;mso-line-height-rule:exactly;`;
  const headerCell = `${cellBase}background:${blueSoft};color:${blue};font-size:6pt;font-weight:700;text-transform:uppercase;`;
  const summaryWidths = ["24%", "56%", "20%"];
  const summaryCell = (index, extra = "") => `${cellBase}width:${summaryWidths[index]};white-space:nowrap;${extra}`;
  const groupColors = {
    market: [blueSoft, blue],
    land: [amberSoft, amber],
    building: [greenSoft, green],
    premium: ["#ece3f6", "#5a3e8c"],
    insurance: ["#f6dede", red],
  };
  const body = buildValuationSummaryGroups().map((group) => {
    const [background, color] = groupColors[group.key] || [surfaceMuted, ink];
    const groupStyle = `${cellBase}background:${background};color:${color};font-weight:700;font-size:6pt;text-transform:uppercase;letter-spacing:.04em;`;
    const heading = `<tr height="19" style="height:0.5cm;mso-height-source:userset;mso-height-rule:exactly;"><th colspan="3" style="${groupStyle}">${escapeHtml(group.title.toLocaleUpperCase("tr-TR"))}</th></tr>`;
    const rows = group.rows.map((row) => `<tr height="19" style="height:0.5cm;mso-height-source:userset;mso-height-rule:exactly;">
      <td style="${summaryCell(0, "font-weight:700;")}">${escapeHtml(row.label)}</td>
      <td style="${summaryCell(1, `color:${muted};font-size:6pt;`)}">${escapeHtml(row.detail)}</td>
      <td style="${summaryCell(2, "text-align:right;font-weight:800;")}">${escapeHtml(row.value)}</td>
    </tr>`).join("");
    return heading + rows;
  }).join("");
  return `<table class="valuation-summary-table ziraat-valuation-summary-table" style="${tableStyle}">
    <colgroup><col style="width:24%;"><col style="width:56%;"><col style="width:20%;"></colgroup>
    <thead><tr height="19" style="height:0.5cm;mso-height-source:userset;mso-height-rule:exactly;">
      <th style="${headerCell}width:${summaryWidths[0]};">Kalem</th>
      <th style="${headerCell}width:${summaryWidths[1]};">Birim Değer / Oran</th>
      <th style="${headerCell}width:${summaryWidths[2]};text-align:right;">Tutar</th>
    </tr></thead>
    <tbody>${body}</tbody>
  </table>`;
}

function wrapWordLandscapeSection(title, html) {
  const heading = title ? `<h3>${escapeHtml(title)}</h3>` : "";
  return `<div class="word-landscape-section">${heading}${html}</div>`;
}

function formatWordCell(value) {
  return escapeHtml(value == null ? "" : value).replace(/\n/g, "<br>");
}

function formatWordParagraphs(value, className = "") {
  const paragraphs = String(value || "")
    .replace(/m²/gi, "m2")
    .split(/\n{2,}|\n/)
    .map((line) => line.trim())
    .filter(Boolean);
  const classAttribute = className ? ` class="${escapeHtml(className)}"` : "";
  return paragraphs.map((line) => `<p${classAttribute}>${escapeHtml(line)}</p>`).join("") || "<p>-</p>";
}

function createLocationMapTools() {
  const wrapper = document.createElement("div");
  wrapper.className = "location-map-tools";

  const parsed = state.sourceValues.kml;
  const latitudeValue = state.fields.latitude || parsed?.centroid?.lat || "";
  const longitudeValue = state.fields.longitude || parsed?.centroid?.lng || "";

  wrapper.innerHTML = `
    <div class="subsection-title-row">
      <div>
        <h4>Harita ve Konum Seçimi</h4>
      </div>
    </div>
    <div class="user-poi-tools">
      <label class="field compact-field">
        <span>Kullanıcı Önemli Noktası</span>
        <input type="text" data-user-poi-name placeholder="Örn. Ali İhsan Dikmen İlkokulu" />
      </label>
      <button class="mini-button" type="button" data-map-save>${state.sourceValues?.reportImages?.location ? "Kroki Kaydedildi" : "Kroki Kaydet"}</button>
      <div class="map-export-menu">
        <button class="mini-button map-export-trigger" type="button" data-map-export-menu
          aria-haspopup="menu" aria-expanded="false">
          <span>JPG</span>
          <strong data-map-export-current-ratio>${escapeHtml(state.settings.mapExportRatio || "4:3")}</strong>
        </button>
        <div class="map-export-options" data-map-export-options role="menu" aria-label="JPG boyutu" hidden>
          ${getMapExportRatioMenuMarkup()}
        </div>
      </div>
      <button class="mini-button" type="button" data-user-poi-save>Yakın Çevre Kaydet</button>
      <button class="mini-button" type="button" data-user-artery-save>Ulaşım Arteri Kaydet</button>
      <button class="mini-button" type="button" data-user-poi-refresh>Kullanıcı Noktalarını Getir</button>
    </div>
    <div class="user-poi-statuses">
      <span class="export-status" data-map-export-status aria-live="polite"></span>
      <span class="export-status" data-user-poi-status aria-live="polite"></span>
    </div>
    <div class="map-panel-wrap">
      <label class="field compact-field map-mode-field map-mode-overlay">
        <select data-map-mode aria-label="Harita görünümü">
          ${getMapModeOptionsMarkup()}
        </select>
      </label>
      <div class="map-panel" id="kmlMapPanel">
        <div class="map-placeholder" id="kmlMapPlaceholder">KML yüklendiğinde harita burada OpenStreetMap altlığıyla gösterilecek.</div>
      </div>
    </div>
    <div class="map-coordinate-fields">
      <label class="field">
        <span>Enlem</span>
        <input type="text" data-field="latitude" data-map-coordinate-field="latitude" value="${escapeHtml(latitudeValue)}" />
      </label>
      <label class="field">
        <span>Boylam</span>
        <input type="text" data-field="longitude" data-map-coordinate-field="longitude" value="${escapeHtml(longitudeValue)}" />
      </label>
    </div>
  `;

  wrapper.querySelector("[data-map-mode]").addEventListener("change", (event) => {
    state.settings.mapMode = normalizeMapMode(event.target.value);
    autosave();
    renderLeafletKmlMap();
  });

  const mapExportMenu = wrapper.querySelector(".map-export-menu");
  const mapExportMenuButton = wrapper.querySelector("[data-map-export-menu]");
  const mapExportOptions = wrapper.querySelector("[data-map-export-options]");
  let mapExportOutsideClickListener = null;
  const setMapExportMenuOpen = (isOpen) => {
    mapExportOptions.hidden = !isOpen;
    mapExportMenu.classList.toggle("is-open", isOpen);
    mapExportMenuButton.setAttribute("aria-expanded", String(isOpen));
    if (mapExportOutsideClickListener) {
      document.removeEventListener("pointerdown", mapExportOutsideClickListener);
      mapExportOutsideClickListener = null;
    }
    if (isOpen) {
      mapExportOutsideClickListener = (event) => {
        if (mapExportMenu.contains(event.target)) return;
        setMapExportMenuOpen(false);
      };
      window.setTimeout(() => document.addEventListener("pointerdown", mapExportOutsideClickListener), 0);
    }
  };

  mapExportMenuButton.addEventListener("click", () => {
    setMapExportMenuOpen(mapExportOptions.hidden);
  });

  mapExportMenu.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    setMapExportMenuOpen(false);
    mapExportMenuButton.focus();
  });

  wrapper.querySelectorAll("[data-map-export-ratio-option]").forEach((button) => {
    button.addEventListener("click", () => {
      const ratio = button.dataset.mapExportRatioOption;
      state.settings.mapExportRatio = ratio;
      mapExportMenuButton.querySelector("[data-map-export-current-ratio]").textContent = ratio;
      mapExportOptions.querySelectorAll("[data-map-export-ratio-option]").forEach((option) => {
        option.setAttribute("aria-checked", String(option === button));
      });
      autosave();
      setMapExportMenuOpen(false);
      exportMapAsJpeg(mapExportMenuButton);
    });
  });

  wrapper.querySelector("[data-map-save]").addEventListener("click", (event) => {
    saveLocationMapForReport(event.currentTarget);
  });

  wrapper.querySelector("[data-user-poi-save]").addEventListener("click", async () => {
    await saveUserPoiFromMap(wrapper.querySelector("[data-user-poi-name]"), wrapper.querySelector("[data-user-poi-status]"));
  });

  wrapper.querySelector("[data-user-artery-save]").addEventListener("click", async () => {
    await saveUserMainArteryFromMap(wrapper.querySelector("[data-user-poi-name]"), wrapper.querySelector("[data-user-poi-status]"));
  });

  wrapper.querySelector("[data-user-poi-refresh]").addEventListener("click", async () => {
    await refreshUserPoisFromServer({ force: true, select: true, userOnly: true });
    autosave();
    renderSection();
  });

  wrapper.querySelectorAll("[data-map-coordinate-field]").forEach((input) => {
    const key = input.dataset.mapCoordinateField;
    markFieldSourceState(input, key);
    input.addEventListener("input", (event) => {
      clearFieldSourceOwnership(key);
      state.fields[key] = event.target.value;
      autosave();
      renderValidation();
      updateStatus();
    });
    input.addEventListener("blur", () => {
      const formattedValue = normalizeReportFieldValue(key, input.value);
      if (formattedValue !== input.value) {
        input.value = formattedValue;
        state.fields[key] = formattedValue;
        autosave();
        renderValidation();
        updateStatus();
      }
      renderLeafletKmlMap();
    });
  });

  queueMicrotask(() => {
    if (state.sourceValues.kml?.coordinates?.length) {
      renderLeafletKmlMap();
    } else {
      renderKmlMapFallback();
    }
  });

  return wrapper;
}

function readFileAsText(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(reader.error);
    reader.readAsText(file, "utf-8");
  });
}

function readFileAsArrayBuffer(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(reader.error);
    reader.readAsArrayBuffer(file);
  });
}

function clonePdfBuffer(buffer) {
  return buffer && typeof buffer.slice === "function" ? buffer.slice(0) : buffer;
}

function configurePdfWorker(pdfjs) {
  if (pdfjs && pdfjs.GlobalWorkerOptions) {
    pdfjs.GlobalWorkerOptions.workerSrc = new URL("./vendor/pdfjs/pdf.worker.local.js", window.location.href).href;
  }
}

function isPdfWorkerFailure(error) {
  const message = String((error && error.message) || error || "");
  return /worker|fake worker|module|script|fetch|load|network/i.test(message);
}

function formatUploadErrorDetails(upload, error) {
  const parts = [];
  const title = upload?.title || upload?.id || "Belge";
  const name = error?.name ? String(error.name) : "Hata";
  const message = error?.message ? String(error.message) : String(error || "Dosya okunamadı.");
  parts.push(`${title} okunamadı.`);
  parts.push(`${name}: ${message}`);
  if (navigator.userAgent) {
    parts.push(`Cihaz: ${navigator.userAgent}`);
  }
  if (error?.stack) {
    parts.push(String(error.stack));
  }
  return parts.filter(Boolean).join("\n").slice(0, 1800);
}
function resolvePdfLoadingTask(loadingTask) {
  if (loadingTask && loadingTask.promise) {
    return loadingTask.promise;
  }

  if (loadingTask && typeof loadingTask.then === "function") {
    return loadingTask;
  }

  throw new Error("PDF okuma işlemi başlatılamadı.");
}

function shouldDisablePdfWorkerForThisDevice() {
  const userAgent = String(navigator.userAgent || "");
  const platform = String(navigator.platform || "");
  return /iPad|iPhone|iPod/i.test(userAgent) || (platform === "MacIntel" && Number(navigator.maxTouchPoints || 0) > 1);
}

function shouldUsePdfTextOnlyMode() {
  return shouldDisablePdfWorkerForThisDevice();
}

function getIosPdfTextOnlyError() {
  return new Error("iOS cihazlarda OCR devre dışı. Lütfen metin katmanı olan PDF yükleyin.");
}

async function loadPdfDocument(pdfjs, buffer, options = {}) {
  configurePdfWorker(pdfjs);
  const baseOptions = { ...options };

  if (shouldDisablePdfWorkerForThisDevice()) {
    return resolvePdfLoadingTask(pdfjs.getDocument({
      ...baseOptions,
      data: clonePdfBuffer(buffer),
      disableWorker: true
    }));
  }

  try {
    return await resolvePdfLoadingTask(pdfjs.getDocument({ ...baseOptions, data: clonePdfBuffer(buffer) }));
  } catch (error) {
    if (!isPdfWorkerFailure(error)) throw error;
    return resolvePdfLoadingTask(pdfjs.getDocument({
      ...baseOptions,
      data: clonePdfBuffer(buffer),
      disableWorker: true
    }));
  }
}

async function processAddressFile(file) {
  const text = await readAddressFileText(file);
  const parsed = parseAddressCodeText(text);
  resetAddressDerivedFields();
  state.sourceValues.address = {
    fields: parsed,
    rawText: text,
    readAt: new Date().toISOString(),
    fileName: file.name,
    applied: {},
  };
  mergeLookupOptions({
    city: parsed.city,
    district: parsed.district,
    neighborhood: parsed.neighborhood,
    postalCode: parsed.postalCode,
  });
  // Posta kodu düzeltmesi mahalle veritabanını (async) beklediğinden, ilk
  // yüklemede yanlış (PDF'ten gelen) posta kodunun görünmemesi için düzeltmeyi
  // await ediyoruz; böylece yükleme bittiğinde posta kodu kesin olarak doğru olur.
  await applyAddressFieldsToReport({ force: true });
  refreshTransportAfterAddressChange();
}

// Adres kodu YALNIZCA PDF metin katmanından okunur; OCR ve sunucu tarafı
// okuma kaldırıldı (kullanıcı isteği, 2026-07-08).
async function readAddressFileText(file) {
  const lowerName = file.name.toLowerCase();
  const isPdf = file.type === "application/pdf" || lowerName.endsWith(".pdf");

  if (!isPdf) {
    throw new Error("Adres kodu görselden okuma (OCR) kaldırıldı; lütfen metin katmanlı PDF yükleyin.");
  }

  const text = await readPdfTextLayerOnly(file);
  if (text.trim()) return text;
  throw new Error("Adres kodu PDF'inde metin katmanı bulunamadı. Taranmış görüntü yerine metin içeren PDF yükleyin.");
}

async function processEkbFile(file) {
  const text = await readEkbFileText(file);
  const parsed = parseEkbFields(text);
  resetEkbDerivedFields();
  state.fields.hasEkb = "Evet";
  state.sourceValues.ekb = {
    fields: parsed,
    rawText: text,
    readAt: new Date().toISOString(),
    fileName: file.name,
    applied: {},
  };
  state.fields.ekbRawText = text;
  applyEkbFieldsToReport({ force: true });
}

// EKB YALNIZCA PDF metin katmanından okunur; OCR ve sunucu tarafı okuma
// kaldırıldı (kullanıcı isteği, 2026-07-08). Koordinatlı okuma da pdf.js
// metin katmanı kullanır, OCR değildir.
async function readEkbFileText(file) {
  const lowerName = file.name.toLowerCase();
  const isPdf = file.type === "application/pdf" || lowerName.endsWith(".pdf");

  if (!isPdf) {
    throw new Error("EKB görselden okuma (OCR) kaldırıldı; lütfen metin katmanlı PDF yükleyin.");
  }

  const text = await readCoordinatePdfText(file, 3);
  if (text.trim()) return text;
  const plainText = await readPdfTextLayerOnly(file);
  if (plainText.trim()) return plainText;
  throw new Error("EKB PDF'inde metin katmanı bulunamadı. Taranmış görüntü yerine metin içeren PDF yükleyin.");
}

async function processImarFile(file) {
  const source = await readImarFileText(file);
  const text = typeof source === "string" ? source : source.text;
  const parsed = parseImarFields(text);
  resetImarDerivedFields();
  state.sourceValues.imar = {
    fields: parsed,
    rawText: text,
    readAt: new Date().toISOString(),
    fileName: file.name,
    applied: {},
    meta: typeof source === "string" ? {} : source.meta || {},
  };
  applyImarFieldsToReport({ force: true });
}

async function readImarFileText(file) {
  const lowerName = file.name.toLowerCase();
  const isPdf = file.type === "application/pdf" || lowerName.endsWith(".pdf");
  const isImage = file.type.startsWith("image/") || /\.(jpe?g|png|webp)$/i.test(lowerName);

  if (isPdf) {
    const coordinateText = await readCoordinatePdfText(file, 4).catch(() => "");
    const text = await readPdfText(file).catch(() => "");
    const chunks = [];
    appendUniqueImarChunk(chunks, coordinateText);
    appendUniqueImarChunk(chunks, text);

    let ocrText = "";
    const combinedBeforeOcr = chunks.join("\n");
    const previewFields = combinedBeforeOcr.trim() ? parseImarFields(combinedBeforeOcr) : {};
    if (!shouldUsePdfTextOnlyMode() && (!hasStrongImarSignals(combinedBeforeOcr) || !previewFields.planFonk || !previewFields.insaatNizami || !previewFields.katAdedi)) {
      ocrText = await readImarPdfOcrText(file, 2).catch(() => "");
      appendUniqueImarChunk(chunks, ocrText ? `OCR:\n${ocrText}` : "");
    }

    const combined = chunks.join("\n").trim();
    if (combined) {
      return {
        text: combined,
        meta: {
          source: "pdf",
          usedOcr: Boolean(ocrText.trim()),
          coordinateLayer: Boolean(coordinateText.trim()),
          textLayer: Boolean(text.trim()),
        },
      };
    }

    if (shouldUsePdfTextOnlyMode()) throw getIosPdfTextOnlyError();
    const fallbackOcr = await readImarPdfOcrText(file, 2);
    return {
      text: fallbackOcr,
      meta: { source: "pdf", usedOcr: true, coordinateLayer: false, textLayer: false },
    };
  }

  if (isImage) {
    if (shouldUsePdfTextOnlyMode()) throw getIosPdfTextOnlyError();
    const text = await recognizeImageText(file);
    return { text, meta: { source: "image", usedOcr: true } };
  }

  throw new Error("İmar durumu için PDF veya görsel dosyası yükleyin.");
}

function appendUniqueImarChunk(chunks, text) {
  const clean = String(text || "").trim();
  if (!clean) return;
  const normalized = clean.replace(/\s+/g, " ");
  const exists = chunks.some((chunk) => {
    const current = String(chunk || "").replace(/\s+/g, " ");
    return current.includes(normalized) || normalized.includes(current);
  });
  if (!exists) chunks.push(clean);
}

function hasStrongImarSignals(text) {
  const folded = foldTurkish(text);
  const signals = [
    /IMAR\s+DURUM/,
    /PLAN\s+(ADI|FONKSIYON|TASDIK|ONAY)/,
    /T\.?\s*A\.?\s*K\.?\s*S/,
    /K\.?\s*A\.?\s*K\.?\s*S|EMSAL/,
    /INSAAT\s+NIZAM|YAPI\s+NIZAM|\bNIZAM\b/,
    /BINA\s+YUKSEKLIGI|H\s*MAX/,
    /KAT\s+ADEDI/,
    /ON\s+BAHCE|YAN\s+BAHCE|ARKA\s+BAHCE/,
  ];
  return signals.filter((pattern) => pattern.test(folded)).length >= 2;
}

async function readImarPdfOcrText(file, pageLimit = 2) {
  const pdfjs = window.pdfjsLib || globalThis.pdfjsLib;
  if (!pdfjs?.getDocument) {
    throw new Error("PDF okuyucu yüklenemedi.");
  }
  if (!window.Tesseract?.recognize) {
    throw new Error("OCR kütüphanesi yüklenemedi. İnternet bağlantısını kontrol edin.");
  }

  const buffer = await readFileAsArrayBuffer(file);
  const pdf = await loadPdfDocument(pdfjs, buffer);
  const pageCount = Math.min(pdf.numPages || 1, pageLimit);
  const texts = [];

  for (let pageIndex = 1; pageIndex <= pageCount; pageIndex += 1) {
    const page = await pdf.getPage(pageIndex);
    const canvas = await renderImarPageForOcr(pdfjs, buffer, page, pageIndex);
    if (pageIndex === 1) {
      window._imarColorCanvas = canvas;
    }
    const thresholdCanvas = thresholdImarCanvas(canvas);
    if (pageIndex === 1) {
      window._imarPageCanvas = thresholdCanvas;
    }
    const result = await Tesseract.recognize(thresholdCanvas, "tur+eng");
    const ocrText = result?.data?.text || "";
    if (ocrText.trim()) texts.push(`Sayfa ${pageIndex}\n${ocrText}`);
  }

  return texts.join("\n");
}

async function renderImarPageForOcr(pdfjs, buffer, page, pageIndex) {
  const viewport = page.getViewport({ scale: 1 });
  const maxSide = Math.max(viewport.width, viewport.height) || 1;
  const scale = Math.min(2, Math.max(1.2, 1800 / maxSide));

  try {
    const canvas = await renderPdfPageToCanvas(page, scale, 12000);
    if (isCanvasUsableForOcr(canvas)) return canvas;
    throw new Error("Imar PDF image is blank.");
  } catch (primaryError) {
    const fallbackPdf = await loadPdfDocument(pdfjs, buffer);
    const fallbackPage = await fallbackPdf.getPage(pageIndex);
    const lowCanvas = await renderPdfPageToCanvas(fallbackPage, 0.3, 8000);
    if (!isCanvasUsableForOcr(lowCanvas)) throw primaryError;
    return upscaleCanvasForOcr(lowCanvas, 4);
  }
}

function isCanvasUsableForOcr(canvas) {
  if (!canvas?.width || !canvas?.height) return false;
  const context = canvas.getContext("2d", { willReadFrequently: true });
  if (!context) return false;
  const sampleWidth = Math.min(canvas.width, 240);
  const sampleHeight = Math.min(canvas.height, 240);
  const image = context.getImageData(0, 0, sampleWidth, sampleHeight);
  let dark = 0;
  let colored = 0;
  const total = image.data.length / 4;
  for (let i = 0; i < image.data.length; i += 4) {
    const gray = image.data[i] * 0.299 + image.data[i + 1] * 0.587 + image.data[i + 2] * 0.114;
    if (gray < 245) colored += 1;
    if (gray < 210) dark += 1;
  }
  const darkRatio = dark / total;
  const coloredRatio = colored / total;
  return coloredRatio > 0.001 && darkRatio < 0.98;
}

function upscaleCanvasForOcr(sourceCanvas, factor = 4) {
  const canvas = document.createElement("canvas");
  canvas.width = Math.max(1, Math.floor(sourceCanvas.width * factor));
  canvas.height = Math.max(1, Math.floor(sourceCanvas.height * factor));
  const context = canvas.getContext("2d", { willReadFrequently: true });
  context.imageSmoothingEnabled = true;
  context.imageSmoothingQuality = "high";
  context.drawImage(sourceCanvas, 0, 0, canvas.width, canvas.height);
  return canvas;
}

function renderPdfPageToCanvas(page, scale = 1.5, timeoutMs = 12000) {
  const viewport = page.getViewport({ scale });
  const canvas = document.createElement("canvas");
  const context = canvas.getContext("2d", { willReadFrequently: true });
  canvas.width = Math.max(1, Math.floor(viewport.width));
  canvas.height = Math.max(1, Math.floor(viewport.height));
  const renderTask = page.render({ canvasContext: context, viewport });

  return new Promise((resolve, reject) => {
    const timer = window.setTimeout(() => {
      try {
        renderTask.cancel();
      } catch (error) {
        // Rendering cancellation is best-effort; callers use the timeout rejection.
      }
      reject(new Error("İmar PDF görsel okuma zaman aşımına uğradı."));
    }, timeoutMs);

    renderTask.promise
      .then(() => {
        window.clearTimeout(timer);
        resolve(canvas);
      })
      .catch((error) => {
        window.clearTimeout(timer);
        reject(error);
      });
  });
}

function thresholdImarCanvas(sourceCanvas) {
  const canvas = document.createElement("canvas");
  canvas.width = sourceCanvas.width;
  canvas.height = sourceCanvas.height;
  const context = canvas.getContext("2d", { willReadFrequently: true });
  context.drawImage(sourceCanvas, 0, 0);
  const image = context.getImageData(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < image.data.length; i += 4) {
    const gray = image.data[i] * 0.299 + image.data[i + 1] * 0.587 + image.data[i + 2] * 0.114;
    const value = gray < 160 ? 0 : 255;
    image.data[i] = value;
    image.data[i + 1] = value;
    image.data[i + 2] = value;
    image.data[i + 3] = 255;
  }
  context.putImageData(image, 0, 0);
  return canvas;
}

async function processTakbisFile(file) {
  const parsed = await readTakbisPdf(file);
  resetTakbisTitleDerivedFields();
  state.sourceValues.takbis = {
    ...parsed,
    readAt: new Date().toISOString(),
    fileName: file.name,
    applied: {},
  };
  applyTakbisTitleFieldsToReport({ force: true });
  applyTakbisOwnersToTable(parsed.owners || []);
  applyTakbisEncumbranceFieldsToReport(parsed, { force: true });
  applyTakbisEncumbrancesToTable(parsed.encumbrances || []);
  // Adres kodu PDF'i il/ilçe içermeyebiliyor; TAKBİS'ten gelen tapu il/ilçe ile,
  // daha önce yüklenmiş adresin posta kodu doğru ile göre yeniden hesaplanır
  // (yükleme sırası ne olursa olsun posta kodu doğru gelsin).
  if (String(state.fields.neighborhood || "").trim()) {
    await triggerPostalCodeLookupAfterAddressApply({
      city: state.fields.city || state.fields.titleCity,
      district: state.fields.district || state.fields.titleDistrict,
      neighborhood: state.fields.neighborhood,
    });
  }
}

// Çoklu TAKBİS PDF ayrıştırma — Faz 1 (2026-08-09, bkz. docs/coklu-takbis-import-plan.md).
// Tek bir PDF'te birden fazla taşınmaz kaydı olduğunda (ya da tek-kayıtlı
// birden fazla PDF art arda yüklendiğinde) HER kaydı ayrı ayrı ayrıştırır.
// Ayırıcı olarak "TAPU KAYIT BİLGİSİ" bölüm başlığı kullanılır — bu başlık
// her taşınmaz kaydında BİR KEZ, kaydın en başında görünür ve
// readTakbisPdfRows()'un gürültü filtresi tarafından SİLİNMEZ (banner
// satırı "BU BELGE TOPLAM ... BİLGİ AMAÇLIDIR." SİLİNİR, o yüzden AYIRICI
// OLARAK KULLANILAMAZ — bu ayrımı yaparken bu hataya düşülmüştü, pdf.js
// çıktısı canlı test edilerek yakalandı, bkz. plan dosyasındaki not).
// Tek kayıtlı bir PDF'te başlık yalnızca 1 kez bulunur → tek blok (tüm
// rows, başlıktan ÖNCEKİ makbuz/dekont satırları dahil) döner — bu, MEVCUT
// tek-kayıt davranışını (readTakbisPdf) BİREBİR korur, geriye dönük uyumlu.
function splitMultiTakbisRowBlocks(rows) {
  const startIndexes = [];
  (rows || []).forEach((row, index) => {
    const current = foldTurkish(row?.text || "")
      .replace(/[\u00A0\u2007\u202F]/g, " ")
      .replace(/\s+/g, " ")
      .trim();
    if (!/\bTAPU\b/.test(current)) return;
    const headerWindow = (rows || [])
      .slice(index, index + 3)
      .map((candidate) => foldTurkish(candidate?.text || ""))
      .join(" ")
      .replace(/[\u00A0\u2007\u202F]/g, " ")
      .replace(/\s+/g, " ")
      .trim();
    if (/\bTAPU\s+KAYIT\s+BILGISI\b/.test(headerWindow)) startIndexes.push(index);
  });
  const identityIndexes = [];
  (rows || []).forEach((row, index) => {
    const current = foldTurkish(row?.text || "")
      .replace(/[\u00A0\u2007\u202F]/g, " ")
      .replace(/\s+/g, " ")
      .trim();
    if (/\bTASINMAZ\s+KIMLIK\s+NO\b/.test(current)) identityIndexes.push(index);
  });
  // Bazı PDF.js çıktılarında başlık harf harf öğelere ayrıldığı için
  // readTakbisPdfRows() filtresinden sonra hiç başlık satırı kalmayabilir.
  // Kimlik numarası her tapu kaydında bulunduğundan güvenilir yedek ayırıcıdır.
  const boundaryIndexes = startIndexes.length > 1
    ? startIndexes
    : identityIndexes.length > 1
      ? identityIndexes
      : startIndexes;
  if (boundaryIndexes.length <= 1) return [rows || []];
  return boundaryIndexes.map((start, i) => {
    const end = i + 1 < boundaryIndexes.length ? boundaryIndexes[i + 1] : rows.length;
    return rows.slice(start, end);
  });
}

// pdfData.rows'u splitMultiTakbisRowBlocks() ile bloklara ayırıp HER blok
// için mevcut (tek-kayıt) ayrıştırma fonksiyonlarını (parseTakbisTitleRows/
// parseTakbisOwners/parseTakbisEncumbrances/parseTakbisAttachments) TEKRAR
// çalıştırır — sıfırdan bir ayrıştırıcı YAZILMADI, kanıtlanmış tek-kayıt
// mantığı N kez uygulanıyor. BİLİNÇLİ SADELEŞTİRME: readTakbisPdf()'teki OCR
// yedek akışı (eksik kesir/malik/rehin tutarı durumunda devreye giren) BURADA
// YOK — N kayıt için OCR çalıştırmak yavaş/pahalı olurdu; bir kayıt eksik
// gelirse kullanıcı o kaydı elle tamamlayabilir. Henüz HİÇBİR UI'a
// BAĞLANMADI (bkz. plan dosyası, Faz 1 kapsamı budur — UI/state modeli
// SONRAKİ adım).
async function readMultiTakbisPdf(file) {
  const lowerName = file.name.toLowerCase();
  const isPdf = file.type === "application/pdf" || lowerName.endsWith(".pdf");
  if (!isPdf) {
    throw new Error("TAKBİS için PDF dosyası yükleyin.");
  }
  const pdfData = await readTakbisPdfRows(file);
  const blocks = splitMultiTakbisRowBlocks(pdfData.rows);
  const records = blocks.map((blockRows) => {
    const titleRaw = parseTakbisTitleRows(blockRows, pdfData.pageWidth);
    const fields = mapTakbisTitleToReportFields(titleRaw, blockRows);
    const attachments = parseTakbisAttachments(blockRows);
    fields.titleAttachment = formatTakbisAttachmentsForReport(attachments);
    const owners = parseTakbisOwners(blockRows);
    const encumbrances = reconcileTakbisRestrictedOwners(
      parseTakbisEncumbrances(blockRows, pdfData.pageWidth),
      owners,
    );
    return {
      titleRaw,
      fields,
      attachments,
      owners,
      encumbrances,
      ownerShareWarning: getOwnerShareWarning(owners),
    };
  });

  if (!records.some((record) => Object.values(record.fields).some(Boolean))) {
    throw new Error("TAKBİS tapu kayıt bilgisi okunamadı. Farklı PDF düzeni olabilir.");
  }

  return { records, pageWidth: pdfData.pageWidth, blockCount: blocks.length };
}

// Rapora Aktar — Faz 2 (2026-08-09, bkz. docs/coklu-takbis-import-plan.md
// "Sıradaki adımlar" madde 1). Sıfırdan bir alan/tablo eşleme fonksiyonu
// YAZILMADI — processTakbisFile()'ın (mevcut, kanıtlanmış tek-dosya TAKBİS
// yükleme akışı) kullandığı AYNI applyTakbisTitleFieldsToReport/
// applyTakbisOwnersToTable/applyTakbisEncumbranceFieldsToReport/
// applyTakbisEncumbrancesToTable fonksiyonları HER kayıt için tekrar
// çalıştırılır. Birden fazla kayıt varsa requestType otomatik "Çoklu
// Talep"a çekilir ki tab çubuğu hemen görünür olsun.
//
// Kullanıcı bildirimi (2026-08-15, gerçek dosyalarla test — ZRT-202606006):
// "önce takbis sonra kml sırasını da otomatik düzelt" — ÖNCEKİ davranış
// HER ZAMAN "1. kayıt birincile (index 0), kalanlar YENİ tab'lara" idi;
// KML'ler ÖNCE yüklenip taşınmaz sekmelerini ada/parsel bilgisiyle zaten
// doldurmuşsa, bu MEVCUT sekmelerle hiç eşleştirme YAPMADAN üstüne yeni
// tab'lar açıyor, mükerrer/yetim taşınmazlara yol açıyordu. Artık
// getTakbisTargetIndexes() (KML'nin getKmlTargetIndexes()'iyle AYNI ada/
// parsel eşleştirme deseni — bkz. o fonksiyonun yorumu) her kaydı ÖNCE
// ada/parseli eşleşen MEVCUT bir taşınmaza yönlendirir; eşleşme yoksa
// sırayla boşta olan ilk taşınmaza (gerekirse addTitleUnitTab() ile
// büyütülerek) düşer — sıra ARTIK ÖNEMLİ DEĞİL. Ada/parseli olmayan
// (ör. bu alanları set etmeyen) kayıtlar için davranış DEĞİŞMEDİ (boş
// eşleştirme anahtarı → doğrudan sıradaki boş taşınmaza düşer, ESKİ "1.
// kayıt birincile" davranışıyla BİREBİR aynı sonucu verir — bkz.
// tools/test-title-unit-import.js'in mevcut senaryoları, hepsi ada/parsel
// SET ETMEYEN fixture kullandığından etkilenmeden geçmeye devam eder).
//
// BİLİNEN SINIRLAMA: state.sourceValues.takbis ("bu alan TAKBİS'ten mi
// geldi" rozeti için kaynak-izleme kaydı) taşınmaz-bazlı DEĞİL, takas
// kapsamının (TITLE_UNIT_SCOPED_*) DIŞINDA — yalnızca EN SON aktarılan
// kaydı yansıtır. Alan DEĞERLERİNİN kendisi TÜM taşınmazlar için doğru
// aktarılır; yalnızca "kaynak" rozeti diğer taşınmazlar için güncel
// kalmayabilir (kozmetik, veri kaybı DEĞİL).
function normalizeTakbisDuplicatePart(value) {
  return String(value ?? "")
    .trim()
    .replace(/\s+/g, " ")
    .toLocaleLowerCase("tr-TR");
}

function normalizeTakbisDuplicateDate(value) {
  const normalized = normalizeTakbisDuplicatePart(value);
  if (!normalized) return "";
  const isoMatch = normalized.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);
  if (isoMatch) return `${isoMatch[1]}-${isoMatch[2].padStart(2, "0")}-${isoMatch[3].padStart(2, "0")}`;
  const trMatch = normalized.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})/);
  if (trMatch) return `${trMatch[3]}-${trMatch[2].padStart(2, "0")}-${trMatch[1].padStart(2, "0")}`;
  return normalized;
}

function getTakbisDuplicateKey(fields = {}) {
  const propertyId = normalizeTakbisDuplicatePart(fields.titlePropertyId);
  const reportDate = normalizeTakbisDuplicateDate(
    fields.takbisReportDate || fields.takbisDate || fields.takbisReceivedDate,
  );
  return propertyId && reportDate ? `${propertyId}::${reportDate}` : "";
}

function getExistingTakbisDuplicateKeys() {
  const keys = new Set();
  for (let index = 0; index < getTitleUnitCount(); index += 1) {
    const key = getTakbisDuplicateKey(getTitleUnitFieldsForLabel(index));
    if (key) keys.add(key);
  }
  return keys;
}

// getKmlTargetIndexes() (bkz. app.js, KML ada/parsel eşleştirme) ile AYNI
// desen — TAKBİS kayıtları için. getKmlParcelMatchKey/kmlParcelMatchesTitleUnit
// isim olarak "kml" taşısa da uygulamaları YALNIZCA blockNo/parcelNo
// karşılaştırıyor (KML'e özgü hiçbir şey yok), bu yüzden burada AYNEN
// yeniden kullanılıyor — ikinci bir eşleştirme fonksiyonu YAZILMADI.
// "önce takbis sonra kml sırasını da otomatik düzelt" (2026-08-15): her
// kayıt ÖNCE ada/parseli eşleşen MEVCUT bir taşınmaza yönlendirilir;
// eşleşme yoksa (ör. kayıtta ada/parsel yoksa, ya da eşleşen taşınmaz
// zaten başka bir kayda ayrılmışsa) sırayla boşta olan ilk taşınmaza
// düşer, gerekirse addTitleUnitTab() ile yeni sekme açılır.
function getTakbisTargetIndexes(records) {
  while (getTitleUnitCount() < records.length) addTitleUnitTab();
  const available = new Set(Array.from({ length: getTitleUnitCount() }, (_, index) => index));
  return records.map((record, orderIndex) => {
    const takbisKey = getKmlParcelMatchKey(record.fields);
    let targetIndex = -1;
    if (takbisKey) {
      targetIndex = [...available].find(
        (index) => kmlParcelMatchesTitleUnit(record.fields, getTitleUnitFieldsForLabel(index)),
      ) ?? -1;
    }
    if (targetIndex < 0) targetIndex = [...available][0] ?? orderIndex;
    available.delete(targetIndex);
    return targetIndex;
  });
}

function importTakbisRecordsIntoTitleUnits(records) {
  const existingKeys = getExistingTakbisDuplicateKeys();
  const incomingKeys = new Set();
  const validRecords = (records || []).filter((record) => {
    if (
      !record ||
      !record.fields ||
      !Object.values(record.fields).some((value) => String(value ?? "").trim())
    ) {
      return false;
    }
    const duplicateKey = getTakbisDuplicateKey(record.fields);
    if (duplicateKey && (existingKeys.has(duplicateKey) || incomingKeys.has(duplicateKey))) {
      return false;
    }
    if (duplicateKey) incomingKeys.add(duplicateKey);
    return true;
  });
  if (!validRecords.length) return 0;

  const targetIndexes = getTakbisTargetIndexes(validRecords);
  validRecords.forEach((record, index) => {
    const targetIndex = targetIndexes[index];
    switchActiveTitleUnit(targetIndex);
    state.sourceValues.takbis = {
      ...record,
      readAt: new Date().toISOString(),
      fileName: record.sourceFile || "",
      applied: {},
    };
    applyTakbisTitleFieldsToReport({ force: true });
    applyTakbisOwnersToTable(record.owners || []);
    applyTakbisEncumbranceFieldsToReport(record, { force: true });
    applyTakbisEncumbrancesToTable(record.encumbrances || []);
  });

  if (getTitleUnitCount() > 1) state.fields.requestType = "Çoklu Talep";
  switchActiveTitleUnit(0);
  return validRecords.length;
}

// Kullanıcı geri bildirimi (2026-08-09): "zaten mevcutta takbis ekle
// butonu vardı buradan çözemez miydik" — HAKLI: önceki artışta AYRI bir
// "Çoklu TAKBİS Önizleme" paneli/butonu eklenmişti, bu KALDIRILDI. Artık
// TEK buton ("Dosya ve Rapor" > TAKBİS PDF) hem tek hem çoklu kaydı otomatik
// algılıyor — bkz. processTakbisUpload() (createUploadGrid'in "takbis"
// dalından çağrılır) ve createMultiTakbisPendingImportPanel().
//
// pendingMultiTakbisImport: modül-seviyesi (state İÇİNDE DEĞİL — activeSectionId
// gibi geçici bir UI durumu) — çoklu kayıt tespit edildiğinde kullanıcı
// "Rapora Aktar"a basana/"Vazgeç"e basana kadar burada bekler, render()
// döngüsünde renderSection'ın "case" bölümünde gösterilir.
let pendingMultiTakbisImport = null;

// createUploadGrid'in "takbis" dalından çağrılır (bkz. aşağıdaki fonksiyon
// içindeki yorum). files.length 1 veya daha fazla olabilir (admin için
// input.multiple=true, bkz. createUploadGrid).
//
// KRİTİK TASARIM: admin + TEK dosya durumunda ÖNCE readMultiTakbisPdf ile
// "kaç kayıt var" DIŞARIDAN SESSİZCE yoklanır (probe). Yoklama BAŞARISIZ
// olursa (hata fırlatırsa) VEYA 1 kayıt bulunursa, HER ZAMAN eski/kanıtlanmış
// processTakbisFile()'a (readTakbisPdf, OCR yedek akışı DAHİL) düşülür —
// yani normal tek-tapu yükleme akışı BİREBİR korunur, sıfır regresyon.
// Yalnızca yoklama GERÇEKTEN >1 kayıt bulursa (veya birden fazla dosya
// seçilmişse) yeni çoklu-taşınmaz akışına geçilir.
//
// DÜZELTME (2026-08-15, canlı dosyalarla test sırasında bulundu — kullanıcı
// onayı ile): önceki sürüm çoklu kayıt tespit edilince importTakbisRecordsIntoTitleUnits()'i
// DOĞRUDAN çağırıyordu — pendingMultiTakbisImport'u HİÇ set etmiyordu,
// yalnızca null'a set ediyordu. Bu yüzden createMultiTakbisPendingImportPanel()
// (aşağıda tam çalışır halde duran "Rapora Aktar / Vazgeç" onay ekranı,
// render()'da zaten doğru koşulla gösteriliyordu — bkz. renderSection'ın
// "case" bölümü) HİÇBİR ZAMAN tetiklenmiyordu: birden fazla taşınmaz
// kaydı, kullanıcıya HİÇ SORULMADAN, birincil taşınmazın mevcut Tapu ve
// Mülkiyet/Takyidat verisinin üzerine sessizce yazılıyordu. Artık bu
// fonksiyon doğrudan içe aktarmıyor — bulunan kayıtları pendingMultiTakbisImport'a
// yazıp DÖNÜYOR; asıl içe aktarma yalnızca kullanıcı panelde "Rapora
// Aktar"a bastığında (importButton'un click handler'ı) gerçekleşiyor.
async function processTakbisUpload(files) {
  if (!files.length) return;
  state.uploads.takbis = files.length === 1 ? files[0].name : `${files.length} dosya`;
  // Önceki (kullanıcı hiç yanıtlamadığı) bekleyen bir onay varsa, YENİ bir
  // yükleme başlarken bayat kalmasın diye temizlenir — aşağıda gerçekten
  // çoklu kayıt bulunursa zaten taze bir değerle DOLDURULACAK.
  pendingMultiTakbisImport = null;

  if (files.length === 1) {
    let probe = null;
    try {
      probe = await readMultiTakbisPdf(files[0]);
    } catch {
      probe = null; // yoklama başarısız -> sessizce tek-kayıt (OCR'lı) akışa düş
    }
    if (probe && probe.records.length > 1) {
      pendingMultiTakbisImport = {
        records: probe.records.map((record) => ({ ...record, sourceFile: files[0].name })),
        errors: [],
      };
      return;
    }
  } else if (files.length > 1) {
    const allRecords = [];
    const errors = [];
    for (const file of files) {
      try {
        const result = await readMultiTakbisPdf(file);
        result.records.forEach((record) => allRecords.push({ ...record, sourceFile: file.name }));
      } catch (error) {
        errors.push(`${file.name}: ${error?.message || error}`);
      }
    }
    if (allRecords.length) {
      pendingMultiTakbisImport = { records: allRecords, errors };
      return;
    }
    if (errors.length) throw new Error(`Hiçbir dosya okunamadı: ${errors.join(" | ")}`);
    return;
  }

  await processTakbisFile(files[0]);
}

// Çoklu kayıt tespit edildiğinde "case" sekmesinde (bkz. renderSection)
// gösterilen inceleme paneli — mevcut createMultiTakbisPreviewTable()'ı
// (değişmedi) yeniden kullanır, üstüne Rapora Aktar/Vazgeç düğmeleri ekler.
function createMultiTakbisPendingImportPanel() {
  const { records, errors } = pendingMultiTakbisImport || { records: [], errors: [] };
  const card = document.createElement("div");
  card.className = "subsection multi-takbis-preview-card";

  const head = document.createElement("div");
  head.className = "open-address-head";
  const title = document.createElement("h4");
  title.textContent = "TAKBİS'te birden fazla taşınmaz bulundu";
  head.append(title);
  card.append(head);

  const note = document.createElement("p");
  note.className = "muted-note";
  note.textContent = `${records.length} taşınmaz kaydı tespit edildi. Listeyi kontrol edin: "Rapora Aktar" basılırsa her kayıt, ada/parseli eşleşen bir taşınmaz varsa (ör. daha önce yüklenmiş KML) ONUN mevcut Tapu ve Mülkiyet/Takyidat verisinin ÜZERİNE yazılır; eşleşme yoksa yeni bir tab açılır. "Talep Türü" otomatik "Çoklu Talep" olur.`;
  card.append(note);

  card.append(createMultiTakbisPreviewTable(records, errors));

  const actions = document.createElement("div");
  actions.className = "multi-takbis-import-row";
  const importButton = document.createElement("button");
  importButton.type = "button";
  importButton.className = "title-unit-tab-add";
  importButton.textContent = "Rapora Aktar";
  importButton.addEventListener("click", () => {
    if (!window.confirm(`${records.length} taşınmaz kaydı rapora aktarılacak. Devam edilsin mi?`)) return;
    const importedCount = importTakbisRecordsIntoTitleUnits(records);
    pendingMultiTakbisImport = null;
    if (!importedCount) return;
    saveState();
    render();
  });
  const cancelButton = document.createElement("button");
  cancelButton.type = "button";
  cancelButton.className = "title-unit-tab-remove";
  cancelButton.textContent = "Vazgeç";
  cancelButton.addEventListener("click", () => {
    pendingMultiTakbisImport = null;
    render();
  });
  actions.append(importButton, cancelButton);
  card.append(actions);

  return card;
}

function createMultiTakbisPreviewTable(records, errors) {
  const wrap = document.createElement("div");
  if (errors.length) {
    const errorList = document.createElement("p");
    errorList.className = "muted-note";
    errorList.style.color = "var(--red)";
    errorList.textContent = "Okunamayan dosyalar: " + errors.join(" | ");
    wrap.append(errorList);
  }
  if (!records.length) return wrap;

  const table = document.createElement("table");
  table.className = "table-shell multi-takbis-preview-table";
  const thead = document.createElement("thead");
  thead.innerHTML = "<tr><th>#</th><th>Kaynak dosya</th><th>Taşınmaz Kimlik No</th><th>Ada/Parsel</th><th>Blok/Kat/BB No</th><th>Nitelik</th><th>Malik(ler)</th><th>Rehin</th><th>Uyarı</th></tr>";
  table.append(thead);
  const tbody = document.createElement("tbody");
  records.forEach((record, index) => {
    const tr = document.createElement("tr");
    const missing = !record.fields.titlePropertyId || !record.fields.blockNo || !record.owners?.length;
    if (missing) tr.classList.add("is-warning");
    const ownerNames = (record.owners || []).map((owner) => cleanTakbisOwnerDisplayName(owner.name || "")).filter(Boolean).join(", ");
    const adaParsel = [record.fields.blockNo, record.fields.parcelNo].filter(Boolean).join("/");
    const blokKatBB = [record.fields.titleBlockName, record.fields.titleFloor, record.fields.unitNo].filter(Boolean).join(" / ");
    const cells = [
      String(index + 1),
      record.sourceFile || "",
      record.fields.titlePropertyId || "",
      adaParsel,
      blokKatBB,
      record.fields.titleQuality || record.fields.mainPropertyQuality || "",
      ownerNames,
      (record.encumbrances || []).length ? `${record.encumbrances.length} kayıt` : "-",
      missing ? "⚠ eksik alan" : "",
    ];
    cells.forEach((text) => {
      const td = document.createElement("td");
      td.textContent = text;
      tr.append(td);
    });
    tbody.append(tr);
  });
  table.append(tbody);
  wrap.append(table);
  return wrap;
}

async function readTakbisPdf(file) {
  const lowerName = file.name.toLowerCase();
  const isPdf = file.type === "application/pdf" || lowerName.endsWith(".pdf");
  if (!isPdf) {
    throw new Error("TAKBİS için PDF dosyası yükleyin.");
  }

  const pdfData = await readTakbisPdfRows(file);
  let titleRaw = parseTakbisTitleRows(pdfData.rows, pdfData.pageWidth);
  let extraRows = [];
  let fields = mapTakbisTitleToReportFields(titleRaw, pdfData.rows);
  let attachments = parseTakbisAttachments(pdfData.rows);
  fields.titleAttachment = formatTakbisAttachmentsForReport(attachments);
  let owners = parseTakbisOwners(pdfData.rows);
  let encumbrances = parseTakbisEncumbrances(pdfData.rows, pdfData.pageWidth);

  const hasMissingLienAmount = hasTakbisAnnotationMissingLienAmount(encumbrances);
  if (!shouldUsePdfTextOnlyMode() && (isTakbisFractionFieldsMissing(fields) || !owners.length || hasMissingLienAmount)) {
    const ocrPageLimit = hasMissingLienAmount ? 8 : owners.length ? 1 : 3;
    const ocrText = await readTakbisOcrText(file, ocrPageLimit).catch(() => "");
    if (ocrText.trim()) {
      const ocrRaw = parseTakbisTitleFromText(ocrText);
      titleRaw = mergeTakbisTitleRaw(titleRaw, ocrRaw);
      fields = mapTakbisTitleToReportFields(titleRaw, pdfData.rows);
      fields.titleAttachment = formatTakbisAttachmentsForReport(attachments);
      owners = owners.length ? owners : parseTakbisOwnersFromText(ocrText);
      encumbrances = attachTakbisOcrTextToMissingLienRecords(encumbrances, ocrText);
      extraRows = ocrText
        .split(/\n+/)
        .map((line) => line.replace(/\s+/g, " ").trim())
        .filter(Boolean)
        .map((text) => ({ page: "OCR", y: 0, text }));
    }
  }

  if (!Object.values(fields).some(Boolean)) {
    throw new Error("TAKBİS tapu kayıt bilgisi okunamadı. Farklı PDF düzeni olabilir.");
  }

  encumbrances = reconcileTakbisRestrictedOwners(encumbrances, owners);

  return {
    titleRaw,
    fields,
    attachments,
    owners,
    encumbrances,
    ownerShareWarning: getOwnerShareWarning(owners),
    rows: [
      ...pdfData.rows.map((row) => ({ page: row.page, y: row.y, text: row.text })),
      ...extraRows,
    ],
    pageWidth: pdfData.pageWidth,
  };
}

function hasTakbisAnnotationMissingLienAmount(encumbrances) {
  return (encumbrances || []).some((record) => {
    if (getEncumbranceReportTableKey(record) !== "encumbranceAnnotations") return false;
    const parsed = parseTakbisAnnotationRecord(record);
    return Boolean(parsed.__amountMissing);
  });
}

function attachTakbisOcrTextToMissingLienRecords(encumbrances, ocrText) {
  return (encumbrances || []).map((record) => {
    if (getEncumbranceReportTableKey(record) !== "encumbranceAnnotations") return record;
    const parsed = parseTakbisAnnotationRecord(record);
    return parsed.__amountMissing
      ? { ...record, _ocrText: ocrText }
      : record;
  });
}

async function readTakbisPdfRows(file) {
  if (window.pdfReady) {
    await window.pdfReady;
  }
  const pdfjs = window.pdfjsLib || globalThis.pdfjsLib;
  if (!pdfjs?.getDocument) {
    throw new Error("PDF okuma kütüphanesi yüklenemedi.");
  }

  if (pdfjs.GlobalWorkerOptions) {
    pdfjs.GlobalWorkerOptions.workerSrc = new URL("./vendor/pdfjs/pdf.worker.local.js", window.location.href).href;
  }

  const buffer = await readFileAsArrayBuffer(file);
  const pdf = await loadPdfDocument(pdfjs, buffer);
  const allItems = [];
  let pageWidth = 595;

  for (let pageNumber = 1; pageNumber <= pdf.numPages; pageNumber += 1) {
    const page = await pdf.getPage(pageNumber);
    const viewport = page.getViewport({ scale: 1 });
    pageWidth = viewport.width;
    const pageHeight = viewport.height;
    const content = await page.getTextContent({ normalizeWhitespace: true });

    content.items.forEach((item) => {
      const text = (item.str || "").trim();
      if (!text) return;
      const [, b, c, d, x, y] = item.transform;
      if (Math.abs(b) > 0.3 || Math.abs(c) > 0.3) return;
      if (/BİLGİ AMAÇLIDIR|BILGI AMACLIDIR|DEVREDİLEMEZ|DEVREDILEMEZ|BU BELGE TOPLAM|tapunun kısayolu/i.test(text)) return;
      if (text.length === 1 && /[A-ZÇĞİÖŞÜ]/.test(text)) return;
      allItems.push({
        str: text,
        x,
        y: (pageNumber - 1) * pageHeight + (pageHeight - y),
        page: pageNumber,
        fs: Math.abs(d),
      });
    });
  }

  return { rows: groupPdfItemsIntoRows(allItems), pageWidth };
}

function groupPdfItemsIntoRows(items) {
  const sorted = [...items].sort((a, b) => a.y - b.y || a.x - b.x);
  const rows = [];
  const tolerance = 3.5;

  sorted.forEach((item) => {
    const last = rows[rows.length - 1];
    if (last && Math.abs(item.y - last.y) <= tolerance) {
      last.items.push(item);
    } else {
      rows.push({ y: item.y, page: item.page, items: [item] });
    }
  });

  rows.forEach((row) => {
    row.items.sort((a, b) => a.x - b.x);
    row.text = row.items.map((item) => item.str).join(" ").replace(/\s+/g, " ").trim();
  });

  return rows;
}

function parseTakbisTitleRows(rows, pageWidth) {
  const bounds = findTakbisSectionBounds(rows);
  const titleRows = bounds.tapu ? rows.slice(bounds.tapu.start, bounds.tapu.end) : rows;
  const raw = extractTakbisTitleTable(titleRows, pageWidth);
  enrichTakbisTitleFromRows(raw, titleRows);
  if (!Object.values(raw).some(Boolean)) {
    return parseTakbisTitleFromText(titleRows.map((row) => row.text).join("\n"));
  }
  return raw;
}

function parseTakbisAttachments(rows) {
  const sourceRows = rows || [];
  const start = sourceRows.findIndex((row) => /EKLENTI\s+BILGILERI/.test(foldTurkish(row?.text || "")));
  if (start < 0) return [];
  const stopPattern = /MULKIYET\s+BILGILERI|MULKIYETE\s+AIT\s+REHIN|IPOTEK\s+BILGILERI|TASINMAZA\s+AIT\s+SERH|SERH\s+BEYAN\s+IRTIFAK/i;
  const end = sourceRows.findIndex((row, index) => index > start && stopPattern.test(foldTurkish(row?.text || "")));
  const sectionRows = sourceRows.slice(start + 1, end > start ? end : sourceRows.length);

  return sectionRows.map((row) => cleanTakbisValue(row?.text || ""))
    .filter((text) => text && !/^(Sistem\s+No|Tip\s+Tanım|Tesis\s+Kurum|Tarih|Yevmiye)/i.test(text))
    .map((text) => {
      const match = text.match(/^([0-9]+)\s+(.+?)\s+EKLENT[İI]S[İI]\s*:?\s*(.+)$/i);
      if (!match) return null;
      return {
        systemNo: cleanTakbisValue(match[1]),
        type: normalizeTakbisAttachmentType(match[2]),
        description: cleanTakbisValue(match[3]),
      };
    })
    .filter(Boolean);
}

function normalizeTakbisAttachmentType(value) {
  const text = cleanTakbisValue(value);
  const folded = foldTurkish(text);
  if (folded === "KOMURLUK") return "Kömürlük";
  if (folded === "DEPO") return "Depo";
  if (folded === "OTOPARK") return "Otopark";
  return toTitleCaseTr(text);
}

function formatTakbisAttachmentsForReport(attachments) {
  return (attachments || [])
    .map((attachment) => {
      const type = cleanTakbisValue(attachment?.type || "");
      const description = cleanTakbisValue(attachment?.description || "");
      if (type && description) return `${type}: ${description}`;
      return description || type;
    })
    .filter(Boolean)
    .join("; ");
}

function enrichTakbisTitleFromRows(raw, rows) {
  const text = rows.map((row) => row.text).join("\n");
  const compact = text.replace(/\s+/g, " ");
  const takePair = (patterns) => {
    for (const pattern of patterns) {
      const match = compact.match(pattern) || text.match(pattern);
      if (match?.[1] && match?.[2]) return [cleanTakbisValue(match[1]), cleanTakbisValue(match[2])];
    }
    return ["", ""];
  };
  const take = (patterns) => {
    for (const pattern of patterns) {
      const match = compact.match(pattern) || text.match(pattern);
      if (match?.[1]) return cleanTakbisValue(match[1]);
    }
    return "";
  };
  const takeNearbyValue = (labelPattern, valuePattern) => {
    const rowTexts = rows.map((row) => row.text || "");
    for (let index = 0; index < rowTexts.length; index += 1) {
      const rowText = rowTexts[index];
      if (!labelPattern.test(rowText)) continue;
      const afterLabel = rowText.slice(Math.max(rowText.search(labelPattern), 0));
      const sameLineValue = afterLabel.match(valuePattern);
      if (sameLineValue?.[1]) return cleanTakbisValue(sameLineValue[1]);
      const nextText = rowTexts.slice(index + 1, index + 4).join(" ");
      const nextValue = nextText.match(valuePattern);
      if (nextValue?.[1]) return cleanTakbisValue(nextValue[1]);
    }
    return "";
  };

  raw.Ada = raw.Ada || "";
  raw.Parsel = raw.Parsel || "";
  const [directAda, directParsel] = takePair([
    /\bAda\s*\/\s*Parsel\s*:?\s*([0-9]+)\s*\/\s*([0-9]+)/i,
    /\bAda\s*\/\s*Parsel\s*:?\s*([0-9]+)\s+([0-9]+)/i,
  ]);
  if (directAda && directParsel) {
    raw.Ada = directAda;
    raw.Parsel = directParsel;
    raw.__adaParsel = `${directAda}/${directParsel}`;
  }
  const nearbyAdaParsel = takeNearbyValue(/Ada\s*\/\s*Parsel\s*:?/i, /\b([0-9]+\s*\/\s*[0-9]+)\b/);
  if (nearbyAdaParsel) raw.__adaParsel = raw.__adaParsel || nearbyAdaParsel;

  if ((!raw.__adaParsel && (!raw.Ada || !raw.Parsel)) || raw.__adaParsel === raw.Ada) {
    const block = take([
      /\bAda\s*:?\s*([0-9]+)\b/i,
      /\bAda\s*\/\s*Parsel\s*:?\s*([0-9]+)\s*\/\s*[0-9]+/i,
    ]);
    const parcel = take([
      /\bParsel\s*:?\s*([0-9]+)\b/i,
      /\bAda\s*\/\s*Parsel\s*:?\s*[0-9]+\s*\/\s*([0-9]+)/i,
    ]);
    if (block && parcel) raw.__adaParsel = `${block}/${parcel}`;
  }

  const [directShare, directDenominator] = takePair([
    /Arsa\s*Pay(?:ı|i)?\s*\/\s*Payda\s*:?\s*([0-9]+)\s*[\/⁄∕]\s*([0-9]+)/i,
    /Arsa\s*Pay(?:ı|i)?\s*\/\s*Payda\s*:?\s*([0-9]+)\s+([0-9]+)/i,
    /Arsa\s*Pay(?:ı|i)?\s*:?\s*([0-9]+)\s+Payda\s*:?\s*([0-9]+)/i,
  ]);
  if (directShare && directDenominator) {
    raw["Arsa Pay/Payda"] = `${directShare}/${directDenominator}`;
  }
  raw["Arsa Pay/Payda"] = raw["Arsa Pay/Payda"] ||
    takeNearbyValue(/Arsa\s*Pay(?:ı|i)?\s*\/\s*Payda\s*:?/i, /\b([0-9]+\s*\/\s*[0-9]+)\b/);

  raw["Arsa Pay/Payda"] = raw["Arsa Pay/Payda"] || take([
    /Arsa\s*Pay(?:ı|i)?\s*\/\s*Payda\s*:?\s*([0-9]+(?:\s*[\/⁄∕]\s*[0-9]+)?)/i,
    /Arsa\s*Pay(?:ı|i)?\s*:?\s*([0-9]+)\s+Payda\s*:?\s*([0-9]+)/i,
  ]).replace(/\s+/g, "");
  if (raw["Arsa Pay/Payda"] && !raw["Arsa Pay/Payda"].includes("/") && /Payda/i.test(compact)) {
    const pair = compact.match(/Arsa\s*Pay(?:ı|i)?\s*:?\s*([0-9]+)\s+Payda\s*:?\s*([0-9]+)/i);
    if (pair) raw["Arsa Pay/Payda"] = `${pair[1]}/${pair[2]}`;
  }

  const [directVolume, directPage] = takePair([
    /Cilt\s*\/\s*Sayfa\s*No\s*:?\s*([0-9]+)\s*[\/⁄∕]\s*([0-9]+)/i,
    /Cilt\s*\/\s*Sayfa\s*No\s*:?\s*([0-9]+)\s+([0-9]+)/i,
    /Cilt\s*:?\s*([0-9]+)\s+Sayfa\s*:?\s*([0-9]+)/i,
  ]);
  if (directVolume && directPage) {
    raw.Cilt = directVolume;
    raw.Sayfa = directPage;
    raw.__ciltSayfa = `${directVolume}/${directPage}`;
  }
  raw.__ciltSayfa = raw.__ciltSayfa ||
    takeNearbyValue(/Cilt\s*\/\s*Sayfa\s*No\s*:?/i, /\b([0-9]+\s*\/\s*[0-9]+)\b/);

  raw.__ciltSayfa = raw.__ciltSayfa || take([
    /Cilt\s*\/\s*Sayfa\s*No\s*:?\s*([0-9]+(?:\s*[\/⁄∕]\s*[0-9]+)?)/i,
    /Cilt\s*:?\s*([0-9]+)\s+Sayfa\s*:?\s*([0-9]+)/i,
  ]).replace(/\s+/g, "");
  if (raw.__ciltSayfa && !raw.__ciltSayfa.includes("/") && /Sayfa/i.test(compact)) {
    const pair = compact.match(/Cilt\s*:?\s*([0-9]+)\s+Sayfa\s*:?\s*([0-9]+)/i);
    if (pair) raw.__ciltSayfa = `${pair[1]}/${pair[2]}`;
  }

  const exactCiltRow = rows
    .map((row) => row.text || "")
    .find((rowText) => /Cilt\s*\/\s*Sayfa\s*No/i.test(rowText) && /\b[0-9]+\s*[\/⁄∕]\s*[0-9]+\b/.test(rowText));
  const exactCiltMatch = exactCiltRow?.match(/Cilt\s*\/\s*Sayfa\s*No\s*:?\s*([0-9]+)\s*[\/⁄∕]\s*([0-9]+)/i);
  if (exactCiltMatch) {
    raw.Cilt = cleanTakbisValue(exactCiltMatch[1]);
    raw.Sayfa = cleanTakbisValue(exactCiltMatch[2]);
    raw.__ciltSayfa = `${raw.Cilt}/${raw.Sayfa}`;
  }

  if ((!raw.Ada || !raw.Parsel) && raw.__adaParsel) {
    const [ada, parsel] = splitFirst(raw.__adaParsel, "/");
    raw.Ada = raw.Ada || ada;
    raw.Parsel = raw.Parsel || parsel;
  }

  if ((!raw.Cilt || !raw.Sayfa) && raw.__ciltSayfa) {
    const [volume, page] = splitFirst(raw.__ciltSayfa, "/");
    raw.Cilt = raw.Cilt || volume;
    raw.Sayfa = raw.Sayfa || page;
  }
}

function findTakbisSectionBounds(rows) {
  const sectionPatterns = {
    tapu: /TAPU\s+KAYIT\s+BILGISI/,
    serh: /TASINMAZA\s+AIT\s+SERH|SERH\s+BEYAN\s+IRTIFAK/,
    malik: /MULKIYET\s+BILGILERI/,
    rehin: /MULKIYETE\s+AIT\s+REHIN/,
    ipotek: /IPOTEK\s+BILGILERI/,
  };
  const found = {};

  rows.forEach((row, index) => {
    const text = foldTurkish(row.text);
    Object.entries(sectionPatterns).forEach(([key, pattern]) => {
      if (!found[key] && pattern.test(text)) found[key] = index;
    });
  });

  const keys = Object.keys(found).sort((a, b) => found[a] - found[b]);
  const bounds = {};
  keys.forEach((key, index) => {
    bounds[key] = {
      start: found[key],
      end: index + 1 < keys.length ? found[keys[index + 1]] : rows.length,
    };
  });
  return bounds;
}

function extractTakbisTitleTable(rows, pageWidth) {
  const splitX = Math.min(pageWidth * 0.55, 400);
  const raw = {};
  let lastLeft = "";
  let lastRight = "";
  const labelMap = {
    "ZEMIN TIPI": "Zemin Tipi",
    "TASINMAZ KIMLIK NO": "Taşınmaz Kimlik No",
    "IL/ILCE": "__ilIlce",
    "KURUM ADI": "Kurum Adı",
    "MAHALLE/KOY ADI": "Mahalle",
    "MEVKII": "Mevkii",
    "MEVKI": "Mevkii",
    "CILT/SAYFA NO": "__ciltSayfa",
    "KAYIT DURUMU": "Kayıt Durumu",
    "KAYIT DURUM": "Kayıt Durumu",
    "ADA/PARSEL": "__adaParsel",
    "AT YUZOLCUM(M2)": "Yüzölçüm (m²)",
    "AT YUZOLCUM (M2)": "Yüzölçüm (m²)",
    "BAGIMSIZ BOLUM NITELIK": "Bağımsız Bölüm Nitelik",
    "BAGIMSIZ BOLUM BRUT YUZOLCUMU": "BB Brüt Yüzölçüm (m²)",
    "BAGIMSIZ BOLUM NET YUZOLCUMU": "BB Net Yüzölçüm (m²)",
    "BLOK/KAT/GIRIS/BBNO": "Blok/Kat/Giriş/BBNo",
    "ARSA PAY/PAYDA": "Arsa Pay/Payda",
    "ANA TASINMAZ NITELIK": "Ana Taşınmaz Nitelik",
  };
  const normalizeLabel = (value) => foldTurkish(value).replace(/\s*\/\s*/g, "/").replace(/\s+/g, " ").trim();

  const processCell = (text, side) => {
    if (!text) return;
    const colonPositions = [...text].map((char, index) => (char === ":" ? index : -1)).filter((index) => index >= 0);
    if (!colonPositions.length) {
      const lastField = side === "left" ? lastLeft : lastRight;
      if (lastField && (lastField === "Ana Taşınmaz Nitelik" || lastField === "Bağımsız Bölüm Nitelik" || !raw[lastField])) {
        raw[lastField] = `${raw[lastField] || ""} ${text}`.replace(/\s+/g, " ").trim();
      }
      return;
    }

    let cursor = 0;
    colonPositions.forEach((colonPosition, index) => {
      const nextColon = index + 1 < colonPositions.length ? colonPositions[index + 1] : text.length;
      const before = text.slice(cursor, colonPosition).trim().split(/\s+/).filter(Boolean);
      const after = text.slice(colonPosition + 1, nextColon).trim();
      let field = "";

      for (let wordCount = Math.min(5, before.length); wordCount >= 1; wordCount -= 1) {
        const candidate = normalizeLabel(before.slice(-wordCount).join(" "));
        if (labelMap[candidate]) {
          field = labelMap[candidate];
          break;
        }
      }
      if (!field) {
        cursor = colonPosition + 1;
        return;
      }

      let value = after;
      if (index + 1 < colonPositions.length) {
        const afterWords = after.split(/\s+/).filter(Boolean);
        for (let wordCount = Math.min(5, afterWords.length); wordCount >= 1; wordCount -= 1) {
          const candidate = normalizeLabel(afterWords.slice(-wordCount).join(" "));
          if (labelMap[candidate]) {
            value = afterWords.slice(0, -wordCount).join(" ").trim();
            break;
          }
        }
      }

      if (!raw[field]) raw[field] = cleanTakbisValue(value);
      if (side === "left") lastLeft = field;
      if (side === "right") lastRight = field;
      cursor = colonPosition + 1;
    });
  };

  rows.forEach((row) => {
    const left = row.items.filter((item) => item.x < splitX).sort((a, b) => a.x - b.x).map((item) => item.str).join(" ");
    const right = row.items.filter((item) => item.x >= splitX).sort((a, b) => a.x - b.x).map((item) => item.str).join(" ");
    processCell(left.replace(/\s+/g, " ").trim(), "left");
    processCell(right.replace(/\s+/g, " ").trim(), "right");
  });

  const [city, district] = splitFirst(raw.__ilIlce, "/");
  const [blockNo, parcelNo] = splitFirst(raw.__adaParsel, "/");
  const [registryVolume, registryPage] = splitFirst(raw.__ciltSayfa, "/");

  return {
    "Zemin Tipi": raw["Zemin Tipi"] || "",
    "Taşınmaz Kimlik No": raw["Taşınmaz Kimlik No"] || "",
    "İl": city,
    "İlçe": district,
    "Mahalle": raw.Mahalle || "",
    "Mevkii": raw.Mevkii || "",
    "Ada": blockNo,
    "Parsel": parcelNo,
    "Yüzölçüm (m²)": raw["Yüzölçüm (m²)"] || "",
    "Bağımsız Bölüm Nitelik": raw["Bağımsız Bölüm Nitelik"] || "",
    "BB Brüt Yüzölçüm (m²)": raw["BB Brüt Yüzölçüm (m²)"] || "",
    "BB Net Yüzölçüm (m²)": raw["BB Net Yüzölçüm (m²)"] || "",
    "Blok/Kat/Giriş/BBNo": normalizeSlash(raw["Blok/Kat/Giriş/BBNo"] || ""),
    "Arsa Pay/Payda": normalizeSlash(raw["Arsa Pay/Payda"] || ""),
    "Cilt": registryVolume,
    "Sayfa": registryPage,
    "Ana Taşınmaz Nitelik": raw["Ana Taşınmaz Nitelik"] || "",
    "Kayıt Durumu": (raw["Kayıt Durumu"] || "").split(/\s+/)[0] || "",
    "Kurum Adı": raw["Kurum Adı"] || "",
  };
}

function parseTakbisTitleFromText(text) {
  const value = (pattern) => {
    const match = String(text || "").match(pattern);
    return match ? cleanTakbisValue(match[1]) : "";
  };
  const raw = {
    "__ilIlce": value(/[İI]l\s*\/\s*[İI]l[çc]e\s*[:\s]\s*([A-ZÇĞİÖŞÜ/ ]+)/i),
    "__adaParsel": value(/Ada\s*\/\s*Parsel\s*[:\s]\s*([\d/]+)/i),
    "__ciltSayfa": value(/Cilt\s*\/\s*Sayfa\s*No\s*[:\s]\s*([\d/]+)/i),
    "Zemin Tipi": value(/Zemin\s*Tipi\s*[:\s]\s*([^\n]+)/i).split(/Ada\s*\/\s*Parsel/i)[0],
    "Taşınmaz Kimlik No": value(/Taşınmaz\s*Kimlik\s*No\s*[:\s]\s*(\d+)/i),
    "Mahalle": value(/Mahalle\s*\/\s*Köy\s*Adı\s*[:\s]\s*([^\n]+)/i),
    "Mevkii": value(/Mevki+i?\s*[:\s]\s*([^\n]+)/i).split(/Cilt\s*\/\s*Sayfa/i)[0],
    "Bağımsız Bölüm Nitelik": value(/Bağımsız\s*Bölüm\s*Nitelik\s*[:\s]\s*([^\n]+)/i),
    "Blok/Kat/Giriş/BBNo": value(/Blok\s*\/\s*Kat\s*\/\s*Giriş\s*\/\s*BBNo\s*[:\s]\s*([^\n]+)/i),
    "Arsa Pay/Payda": value(/Arsa\s*Pay\s*\/\s*Payda\s*[:\s]\s*([\d/]+)/i),
    "Ana Taşınmaz Nitelik": value(/Ana\s*Taşınmaz\s*Nitelik\s*[:\s]\s*([^\n]+)/i),
  };
  const [city, district] = splitFirst(raw.__ilIlce, "/");
  const [blockNo, parcelNo] = splitFirst(raw.__adaParsel, "/");
  const [registryVolume, registryPage] = splitFirst(raw.__ciltSayfa, "/");
  return {
    ...raw,
    "İl": city,
    "İlçe": district,
    "Ada": blockNo,
    "Parsel": parcelNo,
    "Cilt": registryVolume,
    "Sayfa": registryPage,
    "Zemin Tipi": cleanTakbisValue(raw["Zemin Tipi"]),
    "Mevkii": cleanTakbisValue(raw.Mevkii),
  };
}

function isTakbisFractionFieldsMissing(fields) {
  return !fields.blockNo ||
    !fields.parcelNo ||
    !fields.share ||
    !fields.denominator ||
    !fields.registryVolume ||
    !fields.registryPage;
}

function mergeTakbisTitleRaw(primary, fallback) {
  const merged = { ...primary };
  Object.entries(fallback || {}).forEach(([key, value]) => {
    if (!merged[key] && value) merged[key] = value;
  });
  return merged;
}

function mapTakbisTitleToReportFields(tapu, rows = []) {
  const blockInfo = parseTakbisBlockFloorUnit(tapu["Blok/Kat/Giriş/BBNo"]);
  const groundType = cleanTakbisValue(tapu["Zemin Tipi"] || "");
  const isMainPropertyGround = /ANATASINMAZ|ANA\s*TASINMAZ/i.test(foldTurkish(groundType));
  const share = isMainPropertyGround ? ["1", "1"] : splitFirst(tapu["Arsa Pay/Payda"], "/");
  const reportDateInfo = extractTakbisReportDateTime(rows);
  const titleDateInfo = extractTakbisTitleDateAndJournal(rows);
  return {
    takbisReportDate: reportDateInfo.date,
    takbisReportTime: reportDateInfo.time,
    groundType,
    titleQuality: cleanTakbisQuality(tapu["Bağımsız Bölüm Nitelik"] || tapu["Ana Taşınmaz Nitelik"] || ""),
    titlePropertyId: tapu["Taşınmaz Kimlik No"] || "",
    titleCity: toTitleCaseTr(tapu["İl"] || ""),
    titleDistrict: toTitleCaseTr(tapu["İlçe"] || ""),
    titleNeighborhood: toTitleCaseTr(tapu.Mahalle || ""),
    locationName: cleanTakbisValue(tapu.Mevkii || ""),
    blockNo: tapu.Ada || "",
    parcelNo: tapu.Parsel || "",
    titleBlockName: blockInfo.blockName,
    titleEntrance: blockInfo.entrance,
    titleFloor: blockInfo.floor,
    unitNo: blockInfo.unitNo,
    share: share[0],
    denominator: share[1],
    landArea: tapu["Yüzölçüm (m²)"] || "",
    registryVolume: tapu.Cilt || "",
    registryPage: tapu.Sayfa || "",
    mainPropertyQuality: tapu["Ana Taşınmaz Nitelik"] || "",
    titleDate: titleDateInfo.date,
    journalNo: titleDateInfo.journalNo,
  };
}

function extractTakbisReportDateTime(rows) {
  const text = (rows || []).map((row) => row.text || "").join("\n");
  const match = text.match(/Tarih\s*:?\s*(\d{1,2})[-.](\d{1,2})[-.](\d{4})[-\s]+(\d{1,2}:\d{2})/i);
  if (!match) return { date: "", time: "" };
  const day = match[1].padStart(2, "0");
  const month = match[2].padStart(2, "0");
  const year = match[3];
  const time = match[4].padStart(5, "0");
  return { date: `${year}-${month}-${day}`, time };
}

function parseTakbisBlockFloorUnit(value) {
  const rawParts = normalizeSlash(value).split("/").map((part) => cleanTakbisValue(part));
  const parts = rawParts.filter((part) => part && part !== "-");
  const hasStructuredSlots = rawParts.length >= 4;
  const cleanSlot = (index) => {
    const slot = cleanTakbisValue(rawParts[index] || "");
    return slot === "-" ? "" : slot;
  };
  const blockName = hasStructuredSlots ? cleanSlot(0) : (parts.length >= 3 ? parts[0] : "");
  const floor = hasStructuredSlots ? cleanSlot(1) : (
    parts.find((part) => /(?:normal|kat|zemin|bodrum|asma|teras|\d+\.?\s*(?:normal|kat)?)/i.test(part)) ||
    (parts.length >= 2 ? parts[parts.length - 2] : "")
  );
  // TAKBİS "Blok/Kat/Giriş/BBNo" biçiminde 4. alan Giriş harfidir (ör. "G").
  // Yapısal (4 alanlı) biçim dışında güvenilir şekilde ayırt edilemediği için
  // yalnızca hasStructuredSlots durumunda okunur.
  const entrance = hasStructuredSlots ? cleanSlot(2) : "";
  return {
    blockName,
    floor,
    entrance,
    unitNo: parts.length ? parts[parts.length - 1] : "",
  };
}

function extractTakbisTitleDateAndJournal(rows) {
  const sectionRows = getTakbisSectionRows(rows, "malik");
  const texts = (sectionRows.length ? sectionRows : rows).map((row) => row.text);
  for (let index = 0; index < texts.length; index += 1) {
    const text = texts[index];
    const match = text.match(/\b(\d{2})[-.](\d{2})[-.](\d{4})\b(?:\s+\d{1,2}:\d{2})?(?:\s*[-–—]\s*|\s+)([0-9]{3,})\b/);
    if (match) {
      return { date: `${match[3]}-${match[2]}-${match[1]}`, journalNo: match[4] };
    }

    const dateOnly = text.match(/\b(\d{2})[-.](\d{2})[-.](\d{4})\b/);
    if (dateOnly) {
      const nextText = texts.slice(index + 1, index + 4).join(" ");
      const journalMatch = nextText.match(/\b([0-9]{3,})\b/);
      return {
        date: `${dateOnly[3]}-${dateOnly[2]}-${dateOnly[1]}`,
        journalNo: journalMatch ? journalMatch[1] : "",
      };
    }
  }
  return { date: "", journalNo: "" };
}

function getTakbisSectionRows(rows, sectionKey) {
  if (sectionKey === "malik") return getTakbisOwnerSectionRows(rows);
  const bounds = findTakbisSectionBounds(rows);
  const bound = bounds[sectionKey];
  return bound ? rows.slice(bound.start, bound.end) : [];
}

function getTakbisOwnerSectionRows(rows) {
  const start = rows.findIndex((row) => /MULKIYET\s+BILGILERI/.test(foldTurkish(row.text)));
  if (start < 0) return [];
  const stopPattern = /MULKIYETE\s+AIT\s+SERH|TASINMAZA\s+AIT\s+SERH|SERH\s+BEYAN\s+IRTIFAK|MULKIYETE\s+AIT\s+REHIN|IPOTEK\s+BILGILERI|IPOTEGIN\s+KONULDUGU/i;
  const end = rows.findIndex((row, index) => index > start && stopPattern.test(foldTurkish(row.text)));
  return rows.slice(start, end > start ? end : rows.length);
}

function parseTakbisEncumbrances(rows, pageWidth = 842) {
  const groups = getTakbisEncumbranceGroups(rows);

  const records = groups
    .flatMap((group) => parseTakbisEncumbranceRows(group.rows, group.key, pageWidth))
    .flatMap(expandTakbisEmbeddedMortgageAnnotations)
    // Yalnızca tarih/yevmiye taşıyan satır, sonraki taşınmazın belge metadata'sıdır;
    // gerçek takyidat kaydında en az tür veya açıklama bulunmalıdır.
    .filter((record) => (record.type || record.description) && !isTakbisEncumbranceNoiseRecord(record));

  return dedupeTakbisEncumbrances(records);
}

function getTakbisEncumbranceGroups(rows) {
  const sourceRows = rows || [];
  const starts = [];
  const definitions = [
    { key: "serh", pattern: /TASINMAZA\s+AIT\s+SERH|MULKIYETE\s+AIT\s+SERH/ },
    { key: "rehin", pattern: /MULKIYETE\s+AIT\s+REHIN/ },
    { key: "ipotek", pattern: /IPOTEK\s+BILGILERI|IPOTEGIN\s+KONULDUGU/ },
  ];

  sourceRows.forEach((row, index) => {
    const folded = foldTurkish(row?.text || "");
    const match = definitions.find((definition) => definition.pattern.test(folded));
    if (!match) return;
    const previous = starts[starts.length - 1];
    if (previous && previous.key === match.key && index - previous.index <= 2) return;
    starts.push({ key: match.key, index });
  });

  if (!starts.length) {
    return [
      { key: "serh", rows: getTakbisSectionRows(sourceRows, "serh") },
      { key: "rehin", rows: getTakbisSectionRows(sourceRows, "rehin") },
      { key: "ipotek", rows: getTakbisSectionRows(sourceRows, "ipotek") },
    ].filter((group) => group.rows.length);
  }

  return starts.map((start, startIndex) => {
    const nextSectionIndex = startIndex + 1 < starts.length ? starts[startIndex + 1].index : sourceRows.length;
    // Mülkiyet ve Eklenti bölümleri şerh grubuna dahil edilmez; eklenti sistem
    // numaraları yevmiye sanılmasın diye grup bu başlıklarda kesilir.
    // Bir sonraki taşınmaz kaydının başlığı takyidat grubuna dahil edilmez.
    const boundaryStart = sourceRows.findIndex((row, index) => {
      if (index <= start.index || index >= nextSectionIndex) return false;
      const foldedText = foldTurkish(row?.text || "");
      return /MULKIYET\s+BILGILERI|EKLENTI\s+BILGILERI|TAPU\s+KAYIT\s+BILGISI|TASINMAZ\s+KIMLIK\s+NO/.test(foldedText)
        || (/BU\s+BELGE/.test(foldedText) && /\d{1,2}[.\/-]\d{1,2}[.\/-]\d{4}/.test(foldedText));
    });
    const end = boundaryStart > start.index ? boundaryStart : nextSectionIndex;
    return { key: start.key, rows: sourceRows.slice(start.index, end) };
  }).filter((group) => group.rows.length);
}

function parseTakbisEncumbranceRows(rows, sectionKey, pageWidth = 842) {
  if (!rows?.length) return [];
  const layout = inferTakbisEncumbranceLayout(rows, pageWidth);
  const entries = rows.map((row) => {
    const rowText = row?.text || "";
    if (!rowText || isTakbisEncumbranceHeaderRow(rowText)) return null;
    const cells = splitTakbisEncumbranceCells(row, layout);
    const type = getTakbisEncumbranceStartType(cells.type);
    const hasContent = Boolean(type || cells.type || cells.description || cells.dateJournal || rowText);
    return hasContent ? { row, cells, type } : null;
  }).filter(Boolean);

  const scopes = buildTakbisEncumbranceScopes(entries, sectionKey);

  const records = scopes.map((recordScope) => {
    const scope = recordScope.entries.slice(0, 35);
    const descriptionParts = [];
    const dateParts = [];
    const restrictedOwnerParts = [];

    scope.forEach((entry, scopeIndex) => {
      const descriptionText = getTakbisEncumbranceScopeDescription(entry, scopeIndex === 0);
      if (descriptionText) descriptionParts.push(descriptionText);
      if (entry.cells.dateJournal) dateParts.push(entry.cells.dateJournal);
      if (entry.cells.restrictedOwner) restrictedOwnerParts.push(entry.cells.restrictedOwner);
    });

    let description = stripTakbisEncumbranceLeadingTypeNoise(cleanTakbisEncumbranceText(descriptionParts.join(" ")));
    let dateInfo = extractTakbisEncumbranceDateInfo(dateParts.join(" "));
    const restrictedOwner = cleanTakbisEncumbranceText(restrictedOwnerParts.join(" "));

    if (!description) {
      description = extractTakbisEncumbranceDescriptionFromScope(scope, recordScope.type);
    }
    if (!dateInfo.date && !dateInfo.journalNo) {
      dateInfo = extractTakbisEncumbranceDateInfo(
        sanitizeTakbisEncumbranceDateFallbackText(scope.map((entry) => entry.row?.text || "").join(" ")),
      );
    }

    return {
      type: recordScope.type || normalizeTakbisEncumbranceType("", sectionKey),
      description,
      date: dateInfo.date,
      journalNo: dateInfo.journalNo,
      restrictedOwner,
      rawText: cleanTakbisEncumbranceText(scope.map((entry) => entry.row?.text || "").join(" ")),
    };
  }).filter((record) => record.type || record.description || record.date || record.journalNo);

  return records;
}

function buildTakbisEncumbranceScopes(entries, sectionKey) {
  const scopes = [];
  let current = null;

  const openScope = (entry) => {
    current = {
      type: entry.type || normalizeTakbisEncumbranceType("", sectionKey),
      entries: [entry],
    };
    scopes.push(current);
  };

  entries.forEach((entry) => {
    if (!current) {
      if (entry.type || sectionKey === "rehin" || sectionKey === "ipotek") {
        openScope(entry);
      }
      return;
    }

    const currentType = foldTurkish(current?.type || "");
    const nextType = foldTurkish(entry.type || "");
    if (sectionKey === "ipotek" && entry.type && currentType.includes("IPOTEK") && !nextType.includes("IPOTEK")) {
      openScope(entry);
      return;
    }

    if (entry.type && shouldStartNewTakbisEncumbranceScope(current, entry)) {
      openScope(entry);
      return;
    }

    current.entries.push(entry);
  });

  return scopes;
}

function expandTakbisEmbeddedMortgageAnnotations(record) {
  if (getEncumbranceReportTableKey(record) !== "encumbranceMortgages") return [record];

  const rawText = cleanTakbisEncumbranceText(record?.rawText || record?.description || "");
  const splitIndex = findTakbisEmbeddedMortgageAnnotationIndex(rawText);
  if (splitIndex < 0) return [record];

  const mortgageText = rawText.slice(0, splitIndex).trim();
  const embeddedText = rawText.slice(splitIndex).trim();
  const annotation = parseTakbisEmbeddedMortgageAnnotation(embeddedText, record);
  const mortgageDateInfo = extractTakbisEncumbranceDateInfo(mortgageText);
  const mortgageRecord = {
    ...record,
    description: sliceBeforeFolded(record.description || mortgageText, /REHINE\s+AIT\s+SERH|150\s*\/?\s*C\s*(?:MD|MADDE|SERH|SERHI)/),
    date: mortgageDateInfo.date || record.date || "",
    journalNo: mortgageDateInfo.journalNo || record.journalNo || "",
    rawText: mortgageText || record.rawText,
  };

  return annotation ? [mortgageRecord, annotation] : [mortgageRecord];
}

function findTakbisEmbeddedMortgageAnnotationIndex(value) {
  const text = String(value || "");
  const folded = foldTurkish(text);
  const patterns = [
    /REHINE\s+AIT\s+SERH\s+BEYAN\s+BILGISI/,
    /\b(?:SERH|BEYAN|IRTIFAK)\b\s+[^]{0,80}\b150\s*\/?\s*C\b/,
    /\b150\s*\/?\s*C\s*(?:MD|MADDE|SERH|SERHI)\b/,
  ];

  for (const pattern of patterns) {
    const match = folded.match(pattern);
    if (match) return match.index;
  }
  return -1;
}

function parseTakbisEmbeddedMortgageAnnotation(value, parentRecord = {}) {
  const raw = cleanTakbisEncumbranceText(value);
  if (!raw) return null;
  const folded = foldTurkish(raw);
  const type = /BEYAN/.test(folded) && !/SERH/.test(folded) ? "Beyan" : "Şerh";
  const dateInfo = extractTakbisEncumbranceDateInfo(raw);
  const description = cleanTakbisEmbeddedMortgageAnnotationDescription(raw, dateInfo);
  if (!description) return null;
  return {
    type,
    description,
    date: dateInfo.date || parentRecord.date || "",
    journalNo: dateInfo.journalNo || parentRecord.journalNo || "",
    rawText: raw,
  };
}

function cleanTakbisEmbeddedMortgageAnnotationDescription(value, dateInfo = {}) {
  let text = cleanTakbisEncumbranceText(value)
    .replace(/Rehine\s+Ait\s+Şerh\s+Beyan\s+Bilgisi/gi, " ")
    .replace(/Rehine\s+Ait\s+Serh\s+Beyan\s+Bilgisi/gi, " ")
    .replace(/\b(?:Ş\/B\/İ|S\/B\/I|Açıklama|Aciklama|Malik|Tarih\s*-\s*Yevmiye|Terkin\s*Sebebi)\b/gi, " ")
    .replace(/^(?:Şerh|Serh|Beyan|İrtifak|Irtifak)\s+/i, " ")
    .replace(/\s+/g, " ")
    .trim();

  const tailDatePattern = /\b[A-Za-zÇĞİÖŞÜçğıöşü]+\s*-\s*\d{1,2}[-.\/]\d{1,2}[-.\/]\d{4}(?:\s+\d{1,2}:\d{2})?\s*[-–—]\s*\d{3,8}\b\s*$/i;
  text = text.replace(tailDatePattern, "").trim();
  if (dateInfo.date && dateInfo.journalNo) {
    const [day, month, year] = dateInfo.date.split(".");
    const datePattern = new RegExp(`\\b[A-Za-zÇĞİÖŞÜçğıöşü]+\\s*-\\s*${day}[-.\\/]${month}[-.\\/]${year}(?:\\s+\\d{1,2}:\\d{2})?\\s*[-–—]\\s*${dateInfo.journalNo}\\b\\s*$`, "i");
    text = text.replace(datePattern, "").trim();
  }

  return stripTakbisEncumbranceLeadingTypeNoise(text)
    .replace(/\s+/g, " ")
    .trim();
}

function shouldStartNewTakbisEncumbranceScope(currentScope, entry) {
  const currentEntries = currentScope?.entries || [];
  if (!currentEntries.length) return true;
  if (hasCompleteTakbisEncumbranceDateInfo(currentEntries)) return true;

  const hasExistingDescription = currentEntries.some((item, index) => getTakbisEncumbranceScopeDescription(item, index === 0));
  // S/B/İ sütununda kendi tip etiketi (Beyan/Şerh/İrtifak) olan satır yeni
  // kaydın başlangıcıdır; önceki kayıt tarihsiz bir beyan olsa bile
  // birleştirilmez (tarihsiz Yönetim Planı beyanı sonraki kaydın
  // tarih-yevmiyesini almamalı). Yalnızca gerçek Ş/B/İ etiketleri kayıt
  // başlatır: satır sarmasında sola taşan "Haciz Yazısı..." gibi kelimeler
  // Rehin/İpotek tipi üretir ve kayıt ortasından bölmemelidir.
  if (hasExistingDescription && isTakbisSbiStartType(entry?.type)) return true;

  const lastEntry = currentEntries[currentEntries.length - 1];
  const rowGap = Math.abs((entry?.row?.y || 0) - (lastEntry?.row?.y || 0));
  if (hasExistingDescription && rowGap > 20) return true;

  return false;
}

// Ş/B/İ sütununun gerçek kayıt-başlangıç etiketleri. Rehin/İpotek çıkarımı
// ("Haciz Yazısı..." gibi sarma satırlarından) şerh bölümünde kayıt başlatmaz.
function isTakbisSbiStartType(typeValue) {
  return typeValue === "Beyan" || typeValue === "Şerh" || typeValue === "İrtifak";
}

function hasCompleteTakbisEncumbranceDateInfo(entries) {
  const dateText = (entries || [])
    .map((entry) => entry.cells?.dateJournal || "")
    .filter(Boolean)
    .join(" ");
  const dateInfo = extractTakbisEncumbranceDateInfo(dateText);
  return Boolean(dateInfo.date && dateInfo.journalNo);
}

function inferTakbisEncumbranceLayout(rows, pageWidth = 842) {
  const headerItems = [];
  (rows || []).forEach((row) => {
    const folded = foldTurkish(row?.text || "");
    if (/S\/B\/I|ACIKLAMA|MALIK\/LEHTAR|TESIS\s+KURUM|TERKIN\s+SEBEBI/.test(folded)) {
      (row.items || []).forEach((item) => {
        headerItems.push({ x: Number(item.x) || 0, text: foldTurkish(item.str || "") });
      });
    }
  });

  const firstX = (pattern) => {
    const item = headerItems
      .filter((candidate) => pattern.test(candidate.text))
      .sort((a, b) => a.x - b.x)[0];
    return item ? item.x : null;
  };

  const typeX = firstX(/S\/B\/I|SERH|BEYAN|IRTIFAK/) ?? pageWidth * 0.11;
  const descX = firstX(/ACIKLAMA/) ?? pageWidth * 0.36;
  const restrictedOwnerX = firstX(/KISITLI|HISSE/);
  const malikX = firstX(/MALIK\/LEHTAR|LEHTAR/) ?? pageWidth * 0.53;
  const tesisX = firstX(/TESIS|TERKIN/) ?? pageWidth * 0.78;

  const typeEnd = clampNumber((typeX + descX) / 2, pageWidth * 0.12, pageWidth * 0.26);
  const descBoundaryX = restrictedOwnerX && restrictedOwnerX > descX ? restrictedOwnerX : malikX;
  const descEnd = clampNumber(descBoundaryX - 14, pageWidth * 0.38, pageWidth * 0.62);
  const restrictedOwnerEnd = restrictedOwnerX && malikX > restrictedOwnerX
    ? clampNumber((restrictedOwnerX + malikX) / 2, pageWidth * 0.42, pageWidth * 0.68)
    : null;
  const dateStart = clampNumber(tesisX - 12, pageWidth * 0.72, pageWidth * 0.88);
  return { typeEnd, descEnd, restrictedOwnerEnd, dateStart };
}

function clampNumber(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function splitTakbisEncumbranceCells(row, layout) {
  const cells = { type: "", description: "", restrictedOwner: "", dateJournal: "" };
  (row.items || []).forEach((item) => {
    const text = cleanTakbisEncumbranceText(item.str);
    if (!text) return;
    if (item.x < layout.typeEnd) {
      cells.type = `${cells.type} ${text}`.trim();
    } else if (item.x >= layout.dateStart) {
      cells.dateJournal = `${cells.dateJournal} ${text}`.trim();
    } else if (item.x < layout.descEnd) {
      cells.description = `${cells.description} ${text}`.trim();
    } else if (layout.restrictedOwnerEnd && item.x < layout.restrictedOwnerEnd) {
      cells.restrictedOwner = `${cells.restrictedOwner} ${text}`.trim();
    }
  });
  return cells;
}

function getTakbisEncumbranceScopeDescription(entry, isStartRow = false) {
  const parts = [];
  const typeCell = cleanTakbisEncumbranceText(entry?.cells?.type || "");
  const descriptionCell = cleanTakbisEncumbranceText(entry?.cells?.description || "");

  if (typeCell && !entry?.type) {
    parts.push(typeCell);
  } else if (typeCell && isStartRow) {
    const foldedType = foldTurkish(entry.type || "");
    const withoutType = typeCell.replace(
      /^(?:S\/B\/I|BEYANLAR?|ŞERHLER?|SERHLER?|İRTİFAKLAR?|IRTIFAKLAR?|REHINLER?|REHİNLER?|HACIZLAR?|IPOTEKLER?|İPOTEKLER?|B|S|İ|I)\s*(?:BOLUMU|BÖLÜMÜ)?\s*[:\-]?\s*/i,
      "",
    );
    if (withoutType && foldTurkish(withoutType) !== foldedType) {
      parts.push(withoutType);
    }
  }

  if (descriptionCell) {
    parts.push(descriptionCell);
  }

  return stripTakbisEncumbranceLeadingTypeNoise(cleanTakbisEncumbranceText(parts.join(" ")));
}

function isTakbisEncumbranceHeaderRow(text) {
  const folded = foldTurkish(text);
  return /TASINMAZA\s+AIT\s+SERH|MULKIYETE\s+AIT\s+SERH|SERH\s+BEYAN\s+IRTIFAK|MULKIYETE\s+AIT\s+REHIN|IPOTEK\s+BILGILERI|S\/B\/I|ACIKLAMA|MALIK\/LEHTAR|TESIS\s+KURUM|TERKIN\s+SEBEBI|^\s*\d+\s*\/\s*\d+\s*$/.test(folded);
}

function normalizeTakbisEncumbranceType(value, sectionKey = "") {
  const folded = foldTurkish(value);
  if (/IPOTEK/.test(folded) || sectionKey === "ipotek") return "İpotek";
  if (/REHIN|HACIZ/.test(folded) || sectionKey === "rehin") return "Rehin";
  if (/BEYAN|\bB\b/.test(folded)) return "Beyan";
  if (/SERH|\bS\b/.test(folded)) return "Şerh";
  if (/IRTIFAK|\bI\b/.test(folded)) return "İrtifak";
  return sectionKey === "serh" ? "" : "Takyidat";
}

function getTakbisEncumbranceStartType(value) {
  const folded = foldTurkish(cleanTakbisValue(value)).replace(/\s+/g, " ").trim();
  if (!folded) return "";
  if (/S\/B\/I|SERH\s*\/\s*BEYAN\s*\/\s*IRTIFAK/.test(folded)) {
    const trailingCode = folded.match(/\b([BSI])$/);
    if (trailingCode?.[1] === "B") return "Beyan";
    if (trailingCode?.[1] === "S") return "Şerh";
    if (trailingCode?.[1] === "I") return "İrtifak";
    const trailingType = folded.match(/\b(BEYANLAR?|SERHLER?|IRTIFAKLAR?|REHINLER?|HACIZLAR?|IPOTEKLER?)\s*(?:BOLUMU)?$/);
    if (!trailingType) return "";
    const marker = trailingType[1];
    if (/^BEYAN/.test(marker)) return "Beyan";
    if (/^SERH/.test(marker)) return "Şerh";
    if (/^IRTIFAK/.test(marker)) return "İrtifak";
    if (/^REHIN|^HACIZ/.test(marker)) return "Rehin";
    if (/^IPOTEK/.test(marker)) return "İpotek";
    return "";
  }
  if (/^(BEYAN|BEYANLAR)(?:\b|\s+BOLUMU|:|-)/.test(folded) || folded === "B") return "Beyan";
  if (/^(SERH|SERHLER)(?:\b|\s+BOLUMU|:|-)/.test(folded) || folded === "S") return "Şerh";
  if (/^(IRTIFAK|IRTIFAKLAR)(?:\b|\s+BOLUMU|:|-)/.test(folded) || folded === "I") return "İrtifak";
  if (/^(REHIN|REHINLER|HACIZ|HACIZLAR)(?:\b|\s+BOLUMU|:|-)/.test(folded)) return "Rehin";
  if (/^(IPOTEK|IPOTEKLER)(?:\b|\s+BOLUMU|:|-)/.test(folded)) return "İpotek";
  return "";
}

function extractTakbisEncumbranceDescriptionFromScope(scope, type) {
  const text = cleanTakbisEncumbranceText(
    (scope || [])
      .map((entry) => entry.cells?.description || entry.row?.text || "")
      .filter(Boolean)
      .join(" "),
  );
  if (!text) return "";
  const foldedType = foldTurkish(type);
  const leadingTypePattern = foldedType
    ? new RegExp(`^(?:${foldedType}|${foldedType}LER|${foldedType}LAR)\\s*(?:BOLUMU)?\\s*[:\\-]?\\s*`, "i")
    : null;
  return stripTakbisEncumbranceLeadingTypeNoise(leadingTypePattern ? text.replace(leadingTypePattern, "") : text)
    .replace(/\b\d{1,2}[-.\/]\d{1,2}[-.\/]\d{4}(?:\s+\d{1,2}:\d{2})?\b/g, "")
    .replace(/\b\d{3,8}\b\s*$/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function cleanTakbisEncumbranceText(value) {
  return cleanTakbisValue(value)
    .replace(/\b(?:S\/B\/I|A[CÇ]IKLAMA|ACIKLAMA|AÇIKLAMA|MALIK\/LEHTAR|MALİK\/LEHTAR|TESIS\s+KURUM|TESİS\s+KURUM|TERKIN\s+SEBEBI|TERKİN\s+SEBEBİ)\b/gi, "")
    .replace(/\s*\d+\s*\/\s*\d+\s*$/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function isTakbisEncumbranceNoiseRecord(record) {
  const description = foldTurkish(record?.description || "").replace(/\s+/g, " ").trim();
  if (!description) return false;
  return /^(YEVMIYE\s+SEBEBI|TARIH\s*[-\s]*YEVMIYE|TESIS\s+KURUM|TERKIN\s+SEBEBI)\b/.test(description);
}

function stripTakbisEncumbranceLeadingTypeNoise(value) {
  return cleanTakbisValue(value)
    .replace(/^(?:S\/B\/I|Beyanlar?|eyanlar?|Beyan|eyan|Şerhler?|Serhler?|erhler?|Şerh|Serh|erh|İrtifaklar?|Irtifaklar?|rtifaklar?|İrtifak|Irtifak|rtifak|Rehinler?|ehinler?|Rehin|ehin|İpotekler?|Ipotekler?|potekler?|İpotek|Ipotek|potek)\s*(?:Bölümü|Bolumu)?\s*[:.\-]?\s*/i, "")
    .replace(/\s+/g, " ")
    .trim();
}

// Tarih-yevmiye fallback metninden içerik tarihlerini ayıklar: "( Şablon: ...)"
// kalıpları ve "YÖNETİM PLANI : 17/07/1981" gibi etiket tarihleri tesis
// tarih-yevmiyesi değildir; tarihsiz beyanlar tarihsiz kalmalıdır.
function sanitizeTakbisEncumbranceDateFallbackText(value) {
  return String(value || "")
    .replace(/\(\s*[SŞsş]ablon\s*:[^)]*\)?/g, " ")
    .replace(/:\s*\d{1,2}[-.\/]\d{1,2}[-.\/]\d{4}\s*\(?/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function extractTakbisEncumbranceDateInfo(value) {
  const text = cleanTakbisValue(value)
    .replace(/\b(?:Tesis\s+Kurum|Tesis|Terkin\s+Sebebi|Terkin|Tarih|Yevmiye|TARİH|YEVMİYE)\b/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!text) return { date: "", journalNo: "" };

  const dates = [...text.matchAll(/\b(\d{1,2})[-.\/](\d{1,2})[-.\/](\d{4})(?:\s+\d{1,2}:\d{2})?\b/g)];
  const dateMatch = dates.length ? dates[dates.length - 1] : null;
  const date = dateMatch
    ? `${dateMatch[1].padStart(2, "0")}.${dateMatch[2].padStart(2, "0")}.${dateMatch[3]}`
    : "";
  const afterDate = dateMatch ? text.slice(dateMatch.index + dateMatch[0].length) : text;

  // Yevmiye numarası 1-2 haneli de olabilir (örn. yıl başında "33"); ancak
  // kısa sayılar yalnızca tarihe bitişik tire sonrasında kabul edilir ki
  // "Ada - 8 Parsel" gibi içerik sayıları yevmiye sanılmasın.
  const dashJournal = afterDate.match(/[-–—]\s*([0-9]{3,8})\b/)
    || afterDate.match(/^\s*[-–—]\s*([0-9]{1,2})\b/);
  let journalNo = dashJournal ? dashJournal[1] : "";
  if (!journalNo) {
    const candidates = [...afterDate.matchAll(/\b([0-9]{3,8})\b/g)]
      .map((match) => match[1])
      .filter((numberText) => !/^(19|20)\d{2}$/.test(numberText));
    journalNo = candidates.length ? candidates[candidates.length - 1] : "";
  }
  if (!journalNo && !dateMatch) {
    const candidates = [...text.matchAll(/\b([0-9]{3,8})\b/g)]
      .map((match) => match[1])
      .filter((numberText) => !/^(19|20)\d{2}$/.test(numberText));
    journalNo = candidates.length ? candidates[candidates.length - 1] : "";
  }

  return { date, journalNo };
}

function dedupeTakbisEncumbrances(records) {
  const seen = new Set();
  return (records || []).filter((record) => {
    const type = foldTurkish(record.type || "");
    const restrictedOwner = normalizeTakbisOwnerMatchKey(record.restrictedOwner);
    const key = record.journalNo
      ? `${type}|${record.journalNo}|${restrictedOwner}`
      : `${type}|${foldTurkish(record.description || "")}|${restrictedOwner}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function parseTakbisOwners(rows) {
  const sectionRows = getTakbisSectionRows(rows, "malik");
  const sourceRows = sectionRows.length ? sectionRows : rows;
  const rowOwners = parseTakbisOwnersFromRows(sourceRows);
  if (rowOwners.length) return rowOwners;
  return parseTakbisOwnersFromText(sourceRows.map((row) => row.text || "").join(" "));
}

function normalizeTakbisOwnerMatchKey(value) {
  return foldTurkish(value || "").replace(/[^A-Z0-9]/g, "");
}

function reconcileTakbisRestrictedOwners(encumbrances, owners) {
  const ownerNamesByKey = new Map(
    (owners || [])
      .map((owner) => cleanTakbisOwnerDisplayName(owner?.name || ""))
      .filter(Boolean)
      .map((name) => [normalizeTakbisOwnerMatchKey(name), name]),
  );

  return (encumbrances || []).map((record) => {
    const restrictedOwner = cleanTakbisOwnerDisplayName(record?.restrictedOwner || "");
    if (!restrictedOwner) return { ...record, restrictedOwner: "" };
    const canonicalName = ownerNamesByKey.get(normalizeTakbisOwnerMatchKey(restrictedOwner));
    return { ...record, restrictedOwner: canonicalName || restrictedOwner };
  });
}

function parseTakbisOwnersFromRows(rows) {
  const sourceRows = (rows || []).filter((row) => row?.text);
  const starts = sourceRows
    .map((row, index) => (/^\s*\d{8,10}\s*\(\s*SN\s*:\s*\d+\s*\)/i.test(row.text || "") ? index : -1))
    .filter((index) => index >= 0);
  if (!starts.length) return [];

  const owners = mergeTakbisSameOwnerShares(starts.map((start, index) => {
    const nextStart = starts[index + 1] ?? sourceRows.length;
    return parseTakbisOwnerRows(sourceRows.slice(start, nextStart));
  }).filter((owner) => owner.name));

  if (owners.length === 1 && !owners[0].share) owners[0].share = "1/1";
  return owners;
}

// Aynı malikin (aynı SN, aynı ad) birden fazla hisse kaydını tek satırda
// toplar; hisse payları BigInt kesir toplamı ile birleştirilir (örn. Uşak tipi
// "Mülkiyet ve Hisse Oranlarının Düzeltilmesi" kayıtları). SN yoksa
// birleştirme yapılmaz.
function mergeTakbisSameOwnerShares(owners) {
  const merged = [];
  const bySn = new Map();
  (owners || []).forEach((owner) => {
    const sn = String(owner?.sn || "").trim();
    if (!sn) {
      merged.push(owner);
      return;
    }
    const existing = bySn.get(sn);
    const sameName = existing && (!existing.name || !owner.name
      || foldTurkish(existing.name) === foldTurkish(owner.name));
    if (!existing || !sameName) {
      const copy = { ...owner };
      if (!existing) bySn.set(sn, copy);
      merged.push(copy);
      return;
    }
    const total = sumOwnerFractionsBigInt([existing.share, owner.share]);
    if (existing.share && owner.share && total && total.validCount === 2) {
      existing.share = `${total.numerator}/${total.denominator}`;
    } else if (!existing.share && owner.share) {
      existing.share = owner.share;
    }
    if (!existing.name && owner.name) existing.name = owner.name;
    if (!existing.acquisition && owner.acquisition) existing.acquisition = owner.acquisition;
    if (!existing.date && owner.date) existing.date = owner.date;
    if (!existing.journalNo && owner.journalNo) existing.journalNo = owner.journalNo;
  });
  return merged;
}

// Malik ismi çok uzunsa (birden fazla satıra sarılan tüzel kişi unvanı gibi)
// TAKBİS tablosunda o satırların Y bandı, "Edinme Sebebi" sütununun kendi
// sarma satırlarıyla ÇAKIŞIR — pdf.js metnini satıra göre gruplayan
// `groupPdfItemsIntoRows` bu iki farklı sütunun metnini TEK satırda
// birleştirir (ör. "SERAMİK GRANİT İNŞAAT TAAHHÜT Kanun"). Malik/Edinme
// Sebebi sütunları arasında (El Birliği/Hisse/Metrekare sütunları asla
// sarılmadığı için) her zaman geniş bir boş x aralığı kalır; bu sabit eşik
// devam satırlarında hangi metin parçasının Malik'e, hangisinin Edinme/
// Terkin Sebebi'ne ait olduğunu ayırt etmek için kullanılır. İlk satır
// (SN ile başlayan) dokunulmadan bırakılır — oradaki mevcut kesir/tarih
// tabanlı ayrıştırma zaten doğru çalışıyor, yalnızca SARMA satırları
// (index > 0) bu sorunu yaşıyor.
const OWNER_ROW_NAME_COLUMN_MAX_X = 400;

function splitTakbisOwnerRowByColumn(row) {
  const items = row?.items || [];
  const join = (list) => list.map((item) => item.str || "").join(" ").replace(/\s+/g, " ").trim();
  return {
    nameText: join(items.filter((item) => Number(item.x) < OWNER_ROW_NAME_COLUMN_MAX_X)),
    restText: join(items.filter((item) => Number(item.x) >= OWNER_ROW_NAME_COLUMN_MAX_X)),
  };
}

function parseTakbisOwnerRows(rows) {
  const fullText = rows.map((row, index) => {
    if (index === 0 || !(row?.items || []).length) return row.text || "";
    return splitTakbisOwnerRowByColumn(row).restText;
  }).join(" ");
  const baseOwner = parseTakbisOwnerSegment(fullText);
  const columnFraction = findTakbisFractionFromOwnerRows(rows);
  if (columnFraction) {
    baseOwner.share = columnFraction.value;
  }
  const rowName = buildTakbisOwnerNameFromRows(rows, baseOwner.share, baseOwner.acquisition) || baseOwner.name;
  return {
    ...baseOwner,
    name: cleanTakbisOwnerDisplayName(rowName),
  };
}

function findTakbisFractionFromOwnerRows(rows) {
  const rowList = rows || [];
  const ownerText = cleanTakbisValue(rowList.map((row) => row?.text || "").join(" "));
  const hasStructuredCoordinates = rowList.some((row) => (row?.items || []).length > 0);
  for (let rowIndex = 0; rowIndex < rowList.length; rowIndex += 1) {
    const row = rowList[rowIndex];
    const items = row?.items || [];
    for (const item of items) {
      const text = cleanTakbisValue(item.str || "");
      const match = text.match(/\b(\d+)\s*\/\s*(\d+)\b/);
      if (!match) continue;
      let denominator = match[2];
      let original = match[0];
      const continuation = findWrappedDenominatorPart(rowList, rowIndex + 1, item.x, item.page);
      const textContinuation = continuation || hasStructuredCoordinates
        ? null
        : findWrappedDenominatorPartInText(ownerText.slice(ownerText.indexOf(match[0]) + match[0].length), match[1], denominator);
      if (continuation) {
        denominator += continuation.text;
        original += ` ${continuation.text}`;
      } else if (textContinuation) {
        denominator += textContinuation;
        original += ` ${textContinuation}`;
      }
      return { original, value: `${match[1]}/${denominator}` };
    }
  }
  return null;
}

function findWrappedDenominatorPart(rows, startIndex, fractionX, page) {
  for (let index = startIndex; index < Math.min(rows.length, startIndex + 3); index += 1) {
    const row = rows[index];
    if (!row || /^\s*\d{8,10}\s*\(\s*SN\s*:\s*\d+\s*\)/i.test(row.text || "")) return null;
    const sourcePage = Number(page);
    const rowPage = Number(row.page);
    const isSameOrNextPage = row.page === page
      || (Number.isFinite(sourcePage) && Number.isFinite(rowPage) && rowPage === sourcePage + 1);
    if (!isSameOrNextPage) return null;
    if (/^\s*\d+\s*\/\s*\d+\s*$/.test(row.text || "")) continue;
    // Devam rakamı kesir hücresinin yatay aralığında kalır: soldaki komşu kolon
    // (El Birliği No sarması) elenir, adaylar arasında kesre en yakın x seçilir.
    const candidates = (row.items || [])
      .map((item) => ({ text: cleanTakbisValue(item.str || ""), delta: Number(item.x) - Number(fractionX) }))
      .filter(({ text, delta }) => /^\d{1,2}$/.test(text) && delta >= -18 && delta <= 45)
      .sort((a, b) => Math.abs(a.delta) - Math.abs(b.delta));
    if (candidates.length) return { text: candidates[0].text };
    if (/\b\d{1,2}[-.\/]\d{1,2}[-.\/]\d{4}\b/.test(row.text || "")) return null;
  }
  return null;
}

function findWrappedDenominatorPartInText(afterFraction, numerator, denominator) {
  if (!/^\d{3,4}$/.test(String(denominator || ""))) return "";
  const scanText = cleanTakbisValue(afterFraction)
    .replace(/\b\d+\s*\/\s*\d+\b/g, " ")
    .split(/\b\d{1,2}[-.\/]\d{1,2}[-.\/]\d{4}\b/)[0]
    .slice(0, 180);
  const candidates = [...scanText.matchAll(/(^|[\s:;,-])(\d{1,2})(?=$|[\s:;,-])/g)]
    .map((match) => match[2])
    .filter((value) => value !== String(numerator || ""));
  return candidates[0] || "";
}

function buildTakbisOwnerNameFromRows(rows, shareValue = "", acquisitionText = "") {
  const nameParts = [];
  const sharePattern = shareValue ? new RegExp(`\\b${escapeRegExp(shareValue).replace("/", "\\s*\\/\\s*")}\\b`) : null;

  for (const [index, row] of rows.entries()) {
    // Devam satırlarında (index > 0) Malik sütununun sarma metnine başka bir
    // sütunun (Edinme/Terkin Sebebi) aynı Y bandındaki metni karışabilir —
    // bkz. splitTakbisOwnerRowByColumn yorumu. `row.items` yoksa (ör. metin-
    // tabanlı yedek akış) mevcut davranış (tam row.text) korunur.
    const useColumnSplit = index > 0 && (row?.items || []).length > 0;
    let text = cleanTakbisValue((useColumnSplit ? splitTakbisOwnerRowByColumn(row).nameText : row.text) || "");
    if (!text || /^\d+\s*\/\s*\d+$/.test(text)) continue;
    if (index === 0) {
      text = text.replace(/^\s*\d{8,10}\s*\(\s*SN\s*:\s*\d+\s*\)\s*/i, "");
    }
    let hasRelationBreak = /\s*:\s*/.test(text);
    if (sharePattern && sharePattern.test(text)) {
      text = text.split(sharePattern)[0] || "";
    } else {
      text = text.replace(/\b\d{1,2}[-.\/]\d{1,2}[-.\/]\d{4}\b.*$/g, "");
      text = text.replace(/\s+\d{3,}\s*$/g, "");
    }
    if (hasRelationBreak) {
      text = text.split(/\s*:\s*/)[0] || "";
    }
    text = cleanTakbisOwnerNameFragment(text, acquisitionText);
    if (text) nameParts.push(text);
    if (hasRelationBreak) break;
  }

  return toTitleCaseTr(nameParts.join(" ").replace(/\s+/g, " ").trim());
}

function cleanTakbisOwnerNameFragment(value, acquisitionText = "") {
  const [beforeRelation] = cleanTakbisValue(value).split(/\s*:\s*/);
  let text = cleanTakbisValue(beforeRelation)
    .replace(/\b(?:Tüzel|Tuzel)?\s*Kişiliklerin\s+(?:Ünvan|Unvan)\s+Değiş(?:imi|ikliği)\b/gi, " ")
    .replace(/\b[VT]\s+Kişiliklerin\s+(?:Ünvan|Unvan)\s+Değiş(?:imi|ikliği)\b/gi, " ")
    .replace(/\bV\s*\.?\s*\d+\s*İmar\b.*$/gi, " ")
    .replace(/\b\d+\s*İmar\b/gi, " ")
    .replace(/\b\d+(?:[.,]\d+)?\s+\d+(?:[.,]\d+)?\b/g, " ")
    .replace(/\b(?:Hissesine|Düşen|Dusen|Arsa|Payı|Payi|Metrekare|M2|m²)\b/gi, " ")
    .replace(/\b\d+\s*\/\s*\d+(?:\s+\d{1,3})?\b/g, " ")
    .replace(/\b\d+(?:[.,]\d+)?\b/g, " ")
    .replace(/\s+\d{3,}\s*$/g, " ");
  if (acquisitionText) {
    text = text.replace(new RegExp(escapeRegExp(acquisitionText), "ig"), " ");
  }
  return removeTakbisAcquisitionTokens(text)
    .replace(/\([^)]*\)/g, " ")
    .replace(/\s+[A-ZÇĞİÖŞÜa-zçğıöşü]+\s+(?:Oğlu|Oglu|Kızı|Kizi)\b.*$/iu, " ")
    .replace(/(^|\s)[VT](?=\s|$)/gi, "$1")
    .replace(/\s*[-–—]\s*/g, " ")
    .replace(/\s+\d{3,}\s*$/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function parseTakbisOwnersFromText(text) {
  const compact = cleanTakbisValue(text);
  if (!compact) return [];

  const starts = [...compact.matchAll(/\b\d{8,10}\s*\(\s*SN\s*:\s*\d+\s*\)/gi)].map((match) => match.index);
  if (!starts.length) return [];

  const owners = mergeTakbisSameOwnerShares(starts.map((start, index) => {
    const nextStart = starts[index + 1] ?? compact.length;
    return parseTakbisOwnerSegment(compact.slice(start, nextStart));
  }).filter((owner) => owner.name));

  if (owners.length === 1 && !owners[0].share) owners[0].share = "1/1";
  return owners;
}

function parseTakbisOwnerSegment(segment) {
  const text = cleanTakbisValue(segment);
  const snMatch = text.match(/\(\s*SN\s*:\s*(\d+)\s*\)/i);
  const withoutSystem = text.replace(/^\s*\d{8,10}\s*\(\s*SN\s*:\s*\d+\s*\)\s*/i, "");
  const fraction = findTakbisFraction(withoutSystem);
  // Sarmalanmış payda ("8117/8728" + devam "8") birleştirilmiş fraction.original
  // metinde birebir geçmez; kesrin gerçek konumu taban kesir üzerinden bulunur.
  // Aksi halde tail tüm segment olur ve malik adı edinme sebebi sanılır.
  let fractionIndex = -1;
  let fractionLength = 0;
  if (fraction) {
    fractionIndex = withoutSystem.indexOf(fraction.original);
    fractionLength = fraction.original.length;
    if (fractionIndex < 0) {
      const baseFraction = fraction.original.split(/\s+/)[0] || "";
      fractionIndex = baseFraction ? withoutSystem.indexOf(baseFraction) : -1;
      fractionLength = baseFraction.length;
    }
  }
  const tail = fractionIndex >= 0 ? withoutSystem.slice(fractionIndex + fractionLength) : withoutSystem;
  const dateMatch = tail.match(/\b(\d{1,2})[-.\/](\d{1,2})[-.\/](\d{4})\b/);
  const date = dateMatch ? `${dateMatch[3]}-${dateMatch[2].padStart(2, "0")}-${dateMatch[1].padStart(2, "0")}` : "";
  const afterDate = dateMatch ? tail.slice(dateMatch.index + dateMatch[0].length) : "";
  const journalMatch = afterDate.match(/\b([0-9]{3,})\b/);
  const edinme = extractTakbisAcquisitionReason(withoutSystem, tail.slice(0, dateMatch ? dateMatch.index : tail.length));
  const name = cleanTakbisOwnerName(withoutSystem, fraction?.original, edinme);

  return {
    name,
    sn: snMatch ? snMatch[1] : "",
    share: fraction ? fraction.value : "",
    acquisition: edinme,
    date,
    journalNo: journalMatch ? journalMatch[1] : "",
  };
}

function findTakbisFraction(text) {
  const normalized = cleanTakbisValue(text);
  const direct = normalized.match(/\b(\d+)\s*\/\s*(\d+)\b/);
  if (direct) {
    const afterFraction = normalized.slice(direct.index + direct[0].length);
    const suffix = afterFraction.match(/^\s+(\d{1,2})\b/);
    const textContinuation = suffix ? "" : findWrappedDenominatorPartInText(afterFraction, direct[1], direct[2]);
    const shouldJoinWrappedDenominator =
      suffix &&
      direct[2].length >= 3 &&
      direct[2].length <= 4 &&
      suffix[1] !== direct[1];
    const continuation = shouldJoinWrappedDenominator ? suffix[1] : textContinuation;
    const denominator = continuation ? `${direct[2]}${continuation}` : direct[2];
    return {
      original: direct[0] + (continuation ? ` ${continuation}` : ""),
      value: `${direct[1]}/${denominator}`,
    };
  }
  return null;
}

function cleanTakbisOwnerName(value, fractionText = "", acquisitionText = "") {
  const [beforeFather] = String(value || "").split(/\s*:\s*/);
  let cleaned = cleanTakbisValue(beforeFather)
    .replace(/\(\s*SN\s*:\s*\d+\s*\)/gi, "")
    .replace(/\bSN\s*:\s*\d+\b/gi, "")
    .replace(/\b\d{8,10}\b/g, "")
    .replace(/\b(?:Tüzel|Tuzel)?\s*Kişiliklerin\s+(?:Ünvan|Unvan)\s+Değiş(?:imi|ikliği)\b/gi, " ")
    .replace(/\b[VT]\s+Kişiliklerin\s+(?:Ünvan|Unvan)\s+Değiş(?:imi|ikliği)\b/gi, " ")
    .replace(/\bV\s*\.?\s*\d+\s*İmar\b.*$/gi, " ")
    .replace(/\b\d+\s*İmar\b/gi, " ")
    .replace(/\b\d+(?:[.,]\d+)?\s+\d+(?:[.,]\d+)?\b/g, " ")
    .replace(/\b(?:Hissesine|Düşen|Dusen|Arsa|Payı|Payi|Metrekare|M2|m²)\b/gi, " ")
    .replace(/\b\d+\s*\/\s*\d+(?:\s+\d{1,3})?\b/g, " ")
    .replace(/\b\d+(?:[.,]\d+)?\b/g, " ")
    .replace(/\b\d{1,2}[-.\/]\d{1,2}[-.\/]\d{4}\b.*$/g, " ");
  if (fractionText) {
    cleaned = cleaned.replace(fractionText, " ");
  }
  if (acquisitionText) {
    cleaned = cleaned.replace(new RegExp(escapeRegExp(acquisitionText), "ig"), " ");
  }
  return cleanTakbisOwnerDisplayName(removeTakbisAcquisitionTokens(cleaned)
    .replace(/\b(?:Satış|Satis|İntikal|Intikal|Bağış|Bagis|Bağis|Taksim|Trampa|Kadastro|İfraz|Ifraz|Tevhid)\b/gi, " ")
    .trim());
}

function cleanTakbisOwnerDisplayName(value) {
  const [beforeRelation] = cleanTakbisValue(value).split(/\s*:\s*/);
  const cleaned = cleanTakbisValue(beforeRelation)
    .replace(/\b(?:Tüzel|Tuzel)?\s*Kişiliklerin\s+(?:Ünvan|Unvan)\s+Değiş(?:imi|ikliği)\b/gi, " ")
    .replace(/\b[VT]\s+Kişiliklerin\s+(?:Ünvan|Unvan)\s+Değiş(?:imi|ikliği)\b/gi, " ")
    .replace(/\bV\s*\.?\s*\d+\s*İmar\b.*$/gi, " ")
    .replace(/\b\d+\s*İmar\b/gi, " ")
    .replace(/\([^)]*\)/g, " ")
    .replace(/\s+[A-ZÇĞİÖŞÜa-zçğıöşü]+\s+(?:Oğlu|Oglu|Kızı|Kizi)\b.*$/iu, " ")
    .replace(/\b\d+(?:[.,]\d+)?\b/g, " ")
    .replace(/(^|\s)[VT](?=\s|$)/gi, "$1")
    .replace(/\s*[-–—]\s*/g, " ")
    .replace(/\s+\d{3,}\s*$/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  return toTitleCaseTr(removeTakbisParentTail(cleaned));
}

function removeTakbisParentTail(value) {
  const words = cleanTakbisValue(value).split(/\s+/).filter(Boolean);
  if (words.length < 2) return cleanTakbisValue(value);
  const last = foldTurkish(words[words.length - 1]).replace(/[^A-Z]/g, "");
  if (!["OGLU", "KIZI"].includes(last)) return cleanTakbisValue(value);
  return words.length >= 4 ? words.slice(0, -2).join(" ") : words.slice(0, -1).join(" ");
}

function cleanTakbisAcquisition(value) {
  return cleanTakbisValue(value)
    .replace(/^[-–—\s]+/, "")
    .replace(/[-–—\s]+$/, "")
    .replace(/\s+-\s+/g, " ")
    .trim();
}

function extractTakbisAcquisitionReason(segment, fallback) {
  const source = cleanTakbisValue(segment);
  const reason = findTakbisAcquisitionToken(source);
  if (reason) return reason;
  const fallbackText = cleanTakbisAcquisition(String(fallback || "").replace(/:\s*.*$/g, ""));
  const folded = foldTurkish(fallbackText);
  if (/\d+[.,]\d+|HISSESINE|DUSEN|ARSA|PAY|METREKARE|M2|TUZEL|GERCEK|KISI/.test(folded)) return "";
  return fallbackText;
}

function findTakbisAcquisitionToken(value) {
  const aliases = [
    ["SATIS", "Satış"],
    ["INTIKAL", "İntikal"],
    ["BAGIS", "Bağış"],
    ["TAKSIM", "Taksim"],
    ["TRAMPA", "Trampa"],
    ["KADASTRO", "Kadastro"],
    ["IFRAZ", "İfraz"],
    ["TEVHID", "Tevhid"],
  ];
  const tokens = cleanTakbisValue(value).split(/\s+/);
  for (const token of tokens) {
    const folded = foldTurkish(token).replace(/[^A-Z0-9]/g, "");
    const found = aliases.find(([alias]) => folded === alias);
    if (found) return found[1];
  }
  const foldedText = foldTurkish(value).replace(/\s+/g, " ");
  if (/\bKAT\s+IRTIFAKI?\b/.test(foldedText) && /\bTESIS(?:I)?\b/.test(foldedText)) return "Kat İrtifakı Tesisi";
  if (/\bHISSE\s+ORANLARININ\s+DUZELTILMESI\b/.test(foldedText)) {
    return /\bMULKIYET\s+VE\b/.test(foldedText)
      ? "Mülkiyet ve Hisse Oranlarının Düzeltilmesi"
      : "Hisse Oranlarının Düzeltilmesi";
  }
  if (/\bIMAR\b/.test(foldedText)) return "İmar";
  if (/\b(?:TUZEL\s+)?KISILIKLERIN\s+UNVAN\s+DEGIS(?:IMI|IKLIGI)\b/.test(foldedText) || /\b[VT]\s+KISILIKLERIN\s+UNVAN\s+DEGIS(?:IMI|IKLIGI)\b/.test(foldedText)) return "Tüzel Kişiliklerin Ünvan Değişikliği";
  if (/\bKAT\s+IRTIFAKI\b/.test(foldedText)) return "Kat İrtifakı";
  if (/\bKAT\s+MULKIYETI\b/.test(foldedText)) return "Kat Mülkiyeti";
  if (/\bCINS\s+TASHIHI\b/.test(foldedText)) return "Cins Tashihi";
  if (/\bMAHKEME\s+KARARI\b/.test(foldedText)) return "Mahkeme Kararı";
  return "";
}

function removeTakbisAcquisitionTokens(value) {
  const acquisitionAliases = new Set(["SATIS", "INTIKAL", "BAGIS", "TAKSIM", "TRAMPA", "KADASTRO", "IFRAZ", "TEVHID", "KAT", "IRTIFAK", "IRTIFAKI", "TESIS", "TESISI", "MULKIYETI"]);
  return cleanTakbisValue(value)
    .split(/\s+/)
    .filter((token) => !acquisitionAliases.has(foldTurkish(token).replace(/[^A-Z0-9]/g, "")))
    .join(" ");
}

function escapeRegExp(value) {
  return String(value || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function getOwnerShareWarning(owners) {
  if (!owners?.length) return "";
  if (owners.some((owner) => !owner.share)) return "Bazı malik hisse payları okunamadı; toplam hisse 1/1 kontrol edilemedi.";
  const total = sumOwnerFractionsBigInt(owners.map((owner) => owner.share).filter(Boolean));
  if (!total) return "Malik hisse payları okunamadı; toplam hisse 1/1 kontrol edilemedi.";
  return total.numerator === total.denominator
    ? ""
    : `Malik hisse toplamı ${total.numerator}/${total.denominator}; 1/1 değil. Kontrol edin.`;
}

function sumOwnerFractionsBigInt(fractions) {
  if (!fractions.length) return null;
  let numerator = 0n;
  let denominator = 1n;
  let validCount = 0;
  fractions.forEach((fraction) => {
    const match = String(fraction || "").match(/^(\d+)\s*\/\s*(\d+)$/);
    if (!match) return;
    const partNumerator = BigInt(match[1]);
    const partDenominator = BigInt(match[2]);
    if (partNumerator === 0n || partDenominator === 0n) return;
    numerator = numerator * partDenominator + partNumerator * denominator;
    denominator *= partDenominator;
    const divisor = gcdBigInt(numerator, denominator);
    numerator /= divisor;
    denominator /= divisor;
    validCount += 1;
  });
  return validCount ? { numerator, denominator, validCount } : null;
}

function formatOwnerShareSummary(rows) {
  const fractions = (rows || []).map((row) => cleanTakbisValue(row?.c1 || "")).filter(Boolean);
  const total = sumOwnerFractionsBigInt(fractions);
  if (!fractions.length || !total || total.validCount !== fractions.length) {
    return {
      ok: false,
      text: "Toplam hisse: okunamayan veya hatalı hisse var. Kontrol edin.",
    };
  }
  const percent = Number(total.numerator * 10000n / total.denominator) / 100;
  const percentText = Number.isFinite(percent) ? `%${percent.toLocaleString("tr-TR", { maximumFractionDigits: 2 })}` : "%-";
  const fractionText = `${total.numerator}/${total.denominator}`;
  const ok = total.numerator === total.denominator;
  return {
    ok,
    text: ok
      ? `Toplam hisse: ${fractionText} (${percentText})`
      : `Toplam hisse: ${fractionText} (${percentText}); 1/1 değil. Kontrol edin.`,
  };
}

function gcd(a, b) {
  let x = Math.abs(a);
  let y = Math.abs(b);
  while (y) {
    const next = x % y;
    x = y;
    y = next;
  }
  return x || 1;
}

function gcdBigInt(a, b) {
  let x = a < 0n ? -a : a;
  let y = b < 0n ? -b : b;
  while (y) {
    const next = x % y;
    x = y;
    y = next;
  }
  return x || 1n;
}

function cleanTakbisQuality(value) {
  return cleanTakbisValue(value)
    .replace(/\s*Bağımsız\s+Bölüm\s+Brüt.*$/i, "")
    .replace(/\s*Bağımsız\s+Bölüm\s+Net.*$/i, "")
    .replace(/\s*BB\s+Brüt.*$/i, "")
    .replace(/\s*BB\s+Net.*$/i, "")
    .replace(/\s*Blok\s*\/\s*Kat.*$/i, "")
    .trim();
}

function cleanTakbisValue(value) {
  return normalizeSlash(value).replace(/\s+/g, " ").replace(/^[-–—]\s*$/, "").trim();
}

function normalizeSlash(value) {
  return String(value || "").replace(/[⁄∕]/g, "/");
}

function splitFirst(value, separator) {
  const text = normalizeSlash(value);
  const index = text.indexOf(separator);
  return index >= 0 ? [text.slice(0, index).trim(), text.slice(index + 1).trim()] : [text.trim(), ""];
}

async function readCoordinatePdfText(file, pageLimit = 3) {
  if (window.pdfReady) {
    await window.pdfReady;
  }
  const pdfjs = window.pdfjsLib || globalThis.pdfjsLib;
  if (!pdfjs?.getDocument) {
    throw new Error("PDF okuma kütüphanesi yüklenemedi.");
  }

  if (pdfjs.GlobalWorkerOptions) {
    pdfjs.GlobalWorkerOptions.workerSrc = new URL("./vendor/pdfjs/pdf.worker.local.js", window.location.href).href;
  }

  const buffer = await readFileAsArrayBuffer(file);
  const pdf = await loadPdfDocument(pdfjs, buffer);
  const pages = [];

  for (let pageNumber = 1; pageNumber <= Math.min(pdf.numPages, pageLimit); pageNumber += 1) {
    const page = await pdf.getPage(pageNumber);
    const viewport = page.getViewport({ scale: 1 });
    const pageHeight = viewport.height;
    const content = await page.getTextContent({ normalizeWhitespace: true });
    const items = content.items
      .filter((item) => item.str && item.str.trim())
      .map((item) => {
        const [, b, c, , x, y] = item.transform;
        return { text: item.str.trim(), x, y: pageHeight - y, rotated: Math.abs(b) > 0.3 || Math.abs(c) > 0.3 };
      })
      .filter((item) => !item.rotated)
      .sort((a, b) => a.y - b.y || a.x - b.x);

    const rows = [];
    const tolerance = 4;
    items.forEach((item) => {
      const last = rows[rows.length - 1];
      if (last && Math.abs(item.y - last.y) <= tolerance) {
        last.items.push(item);
      } else {
        rows.push({ y: item.y, items: [item] });
      }
    });

    pages.push(rows
      .map((row) => row.items.sort((a, b) => a.x - b.x).map((item) => item.text).join(" "))
      .join("\n"));
  }

  return pages.join("\n");
}

async function readTakbisOcrText(file, pageLimit = 1) {
  if (!window.Tesseract?.recognize) return "";
  if (window.pdfReady) {
    await window.pdfReady;
  }
  const pdfjs = window.pdfjsLib || globalThis.pdfjsLib;
  if (!pdfjs?.getDocument) return "";

  if (pdfjs.GlobalWorkerOptions) {
    pdfjs.GlobalWorkerOptions.workerSrc = new URL("./vendor/pdfjs/pdf.worker.local.js", window.location.href).href;
  }

  const buffer = await readFileAsArrayBuffer(file);
  const pdf = await loadPdfDocument(pdfjs, buffer);
  const texts = [];

  for (let pageNumber = 1; pageNumber <= Math.min(pdf.numPages, pageLimit); pageNumber += 1) {
    const page = await pdf.getPage(pageNumber);
    const viewport = page.getViewport({ scale: 2.6 });
    const canvas = document.createElement("canvas");
    const context = canvas.getContext("2d");
    canvas.width = viewport.width;
    canvas.height = viewport.height;
    await page.render({ canvasContext: context, viewport }).promise;
    const result = await Tesseract.recognize(canvas, "tur+eng", {
      tessedit_char_whitelist: "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyzÇĞİÖŞÜçğıöşü/:.,;-() ",
    });
    texts.push(result?.data?.text || "");
  }

  return texts.join("\n");
}

// EKB ve Adres Kodu akışları için: YALNIZCA PDF metin katmanını okur.
// OCR ve sunucu tarafı (python) okuma bilinçli olarak devre dışıdır
// (kullanıcı isteği, 2026-07-08 — iOS'ta OCR/sunucu kaynaklı hatalar).
// Taranmış/görüntü PDF'lerde metin bulunamazsa boş metin döner; çağıran
// akış anlamlı Türkçe hata üretir.
async function readPdfTextLayerOnly(file) {
  if (window.pdfReady) {
    await window.pdfReady;
  }
  const pdfjs = window.pdfjsLib || globalThis.pdfjsLib;
  if (!pdfjs?.getDocument) {
    throw new Error("PDF okuma kütüphanesi yüklenemedi. Sayfayı yenileyip tekrar deneyin.");
  }
  if (pdfjs.GlobalWorkerOptions) {
    pdfjs.GlobalWorkerOptions.workerSrc = new URL("./vendor/pdfjs/pdf.worker.local.js", window.location.href).href;
  }
  const buffer = await readFileAsArrayBuffer(file);
  const pdf = await loadPdfDocument(pdfjs, buffer);
  const pages = [];
  for (let pageNumber = 1; pageNumber <= pdf.numPages; pageNumber += 1) {
    const page = await pdf.getPage(pageNumber);
    const content = await page.getTextContent();
    pages.push(content.items.map((item) => item.str).join(" "));
  }
  return pages.join("\n");
}

async function readPdfText(file) {
  if (shouldUsePdfTextOnlyMode()) {
    // Sunucu tarafı okuma birincil yoldur; sunucu ya da Python bulunamazsa
    // tarayıcı içi (worker'sız) metin katmanı okumaya düşülür. OCR iOS'ta
    // kapalı kalır; metin katmanı da boşsa sunucu hatası aynen bildirilir.
    try {
      return await readPdfTextOnServer(file);
    } catch (serverError) {
      const fallbackText = await readPdfTextInBrowser(file).catch(() => "");
      if (String(fallbackText || "").trim()) return fallbackText;
      throw serverError;
    }
  }
  return readPdfTextInBrowser(file);
}

async function readPdfTextInBrowser(file) {
  if (window.pdfReady) {
    await window.pdfReady;
  }
  const pdfjs = window.pdfjsLib || globalThis.pdfjsLib;
  if (!pdfjs?.getDocument) {
    throw new Error("PDF okuma kütüphanesi yüklenemedi. İnternet bağlantısını kontrol edin veya ekran alıntısı yükleyin.");
  }

  if (pdfjs.GlobalWorkerOptions) {
    pdfjs.GlobalWorkerOptions.workerSrc = new URL("./vendor/pdfjs/pdf.worker.local.js", window.location.href).href;
  }

  const buffer = await readFileAsArrayBuffer(file);
  const pdf = await loadPdfDocument(pdfjs, buffer);
  const pages = [];

  for (let pageNumber = 1; pageNumber <= pdf.numPages; pageNumber += 1) {
    const page = await pdf.getPage(pageNumber);
    const content = await page.getTextContent();
    pages.push(content.items.map((item) => item.str).join(" "));
  }

  const text = pages.join("\n");
  if (text.trim()) return text;

  if (shouldUsePdfTextOnlyMode()) throw getIosPdfTextOnlyError();
  return recognizePdfPages(pdf);
}

async function fetchRaporApi(input, init = {}, timeoutMs = 0) {
  const token = await window.RaporCloudSync?.getIdToken?.();
  if (!token) throw new Error("Sunucu işlemleri için geçerli bir oturum açın.");
  const headers = new Headers(init.headers || {});
  headers.set("Authorization", `Bearer ${token}`);
  headers.set("X-Rapor-Client", "1");
  const requestInit = { ...init, headers };
  return timeoutMs > 0 ? fetchWithTimeout(input, timeoutMs, requestInit) : fetch(input, requestInit);
}

// Admin dashboard'daki "kaç rapor oluşturdu / ne kadar sürede tamamladı"
// istatistikleri için sunucuya sessiz bir olay bildirimi gönderir (kullanıcı
// talebi: "kullanıcı istatistikleri ... görmek ve analiz edebilmek için").
// Rapor İÇERİĞİ ASLA gönderilmez — yalnızca opaque reportId, ve (0.0.348,
// kullanıcının AÇIKÇA onayladığı DAR bir istisna: "sistem içerisinde
// oluşturulan her raporun ana başlıklarını liste halinde görmek istiyorum")
// opsiyonel bir `summary` — bkz. buildReportSummaryForPing(), yalnızca
// server.js'teki REPORT_SUMMARY_FIELDS whitelist'iyle sınırlı 9 alan.
// Bulut oturumu yoksa (ör. yalnızca bu cihazda çalışılıyor) sessizce
// atlanır; bu olay kaydı normal kullanım akışını ASLA bloklamamalı/bozmamalı.
function pingReportEvent(type, reportId, summary) {
  if (!reportId || !window.RaporCloudSync?.getStatus?.()?.signedIn) return;
  fetchRaporApi("/api/report-event", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(summary ? { type, reportId, summary } : { type, reportId }),
  }).catch(() => {});
}

// Admin "rapor listesi" özeti için gönderilecek 9 alanı state.fields'tan
// derler. server.js'teki REPORT_SUMMARY_FIELDS ile BİREBİR aynı anahtar
// adları kullanılmalı (city/district/neighborhood/blockNo/parcelNo/
// titleBlockName/unitNo/titleQuality/bank) — biri değişirse diğeri de
// güncellenmeli.
function buildReportSummaryForPing() {
  return {
    city: state.fields?.city || "",
    district: state.fields?.district || "",
    neighborhood: state.fields?.neighborhood || "",
    blockNo: state.fields?.blockNo || "",
    parcelNo: state.fields?.parcelNo || "",
    titleBlockName: state.fields?.titleBlockName || "",
    unitNo: state.fields?.unitNo || "",
    titleQuality: state.fields?.titleQuality || "",
    bank: state.fields?.bank || "",
  };
}

function formatTcmbRate(value) {
  const numeric = Number(value);
  return Number.isFinite(numeric)
    ? numeric.toLocaleString("tr-TR", { minimumFractionDigits: 4, maximumFractionDigits: 4 })
    : "-";
}

function formatTcmbDate(value) {
  const match = String(value || "").match(/^(\d{2})[./-](\d{2})[./-](\d{4})$/);
  return match ? `${match[1]}.${match[2]}.${match[3]}` : String(value || "").trim();
}

const foreignCurrencyValuationDefinitions = [
  { valueKey: "legalValue", label: "Yasal Durum Değeri", code: "USD", key: "legalValueUsd", title: "Yasal Durum Değeri - USD" },
  { valueKey: "legalValue", label: "Yasal Durum Değeri", code: "EUR", key: "legalValueEur", title: "Yasal Durum Değeri - EUR" },
  { valueKey: "currentValue", label: "Mevcut Durum Değeri", code: "USD", key: "currentValueUsd", title: "Mevcut Durum Değeri - USD" },
  { valueKey: "currentValue", label: "Mevcut Durum Değeri", code: "EUR", key: "currentValueEur", title: "Mevcut Durum Değeri - EUR" },
  { valueKey: "legalUrgentSaleValue", label: "Yasal Acil Satış Değeri", code: "USD", key: "legalUrgentSaleValueUsd", title: "Yasal Acil Satış Değeri - USD" },
  { valueKey: "legalUrgentSaleValue", label: "Yasal Acil Satış Değeri", code: "EUR", key: "legalUrgentSaleValueEur", title: "Yasal Acil Satış Değeri - EUR" },
  { valueKey: "currentUrgentSaleValue", label: "Mevcut Acil Satış Değeri", code: "USD", key: "currentUrgentSaleValueUsd", title: "Mevcut Acil Satış Değeri - USD" },
  { valueKey: "currentUrgentSaleValue", label: "Mevcut Acil Satış Değeri", code: "EUR", key: "currentUrgentSaleValueEur", title: "Mevcut Acil Satış Değeri - EUR" },
];

const tcmbRatePlaceholderDefinitions = [
  { code: "USD", rateKey: "buying", key: "usdBuyingRate", title: "USD Alış Kuru" },
  { code: "USD", rateKey: "selling", key: "usdSellingRate", title: "USD Satış Kuru" },
  { code: "EUR", rateKey: "buying", key: "eurBuyingRate", title: "EUR Alış Kuru" },
  { code: "EUR", rateKey: "selling", key: "eurSellingRate", title: "EUR Satış Kuru" },
];

function getTcmbRatePlaceholderRows() {
  return tcmbRatePlaceholderDefinitions.map((definition) => {
    const currency = tcmbRatePayload?.[definition.code.toLowerCase()];
    const rate = Number(currency?.[definition.rateKey]);
    return {
      ...definition,
      value: Number.isFinite(rate) && rate > 0 ? formatTcmbRate(rate) : "",
    };
  });
}

function getTcmbBuyingRate(code) {
  const currency = tcmbRatePayload?.[String(code || "").toLowerCase()];
  const rate = Number(currency?.buying);
  return Number.isFinite(rate) && rate > 0 ? rate : null;
}

function formatForeignCurrencyValuation(value, code) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric) || numeric <= 0) return "";
  return `${numeric.toLocaleString("tr-TR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ${code}`;
}

function getForeignCurrencyValuationRows() {
  return foreignCurrencyValuationDefinitions.map((definition) => {
    const tlValue = parseValuationNumber(state.fields[definition.valueKey]);
    const buyingRate = getTcmbBuyingRate(definition.code);
    const convertedValue = Number.isFinite(tlValue) && buyingRate ? tlValue / buyingRate : null;
    return {
      ...definition,
      buyingRate,
      tlValue,
      value: formatForeignCurrencyValuation(convertedValue, definition.code),
    };
  });
}

function buildForeignCurrencyValuationExplanation() {
  const usdRate = getTcmbBuyingRate("USD");
  const eurRate = getTcmbBuyingRate("EUR");
  if (!usdRate || !eurRate) return "";
  const rows = getForeignCurrencyValuationRows();
  const date = formatTcmbDate(tcmbRatePayload?.date);
  const amounts = ["legalValue", "currentValue", "legalUrgentSaleValue", "currentUrgentSaleValue"].map((valueKey) => {
    const valueRows = rows.filter((row) => row.valueKey === valueKey);
    const first = valueRows[0];
    if (!first?.value) return "";
    const usd = valueRows.find((row) => row.code === "USD")?.value || "-";
    const eur = valueRows.find((row) => row.code === "EUR")?.value || "-";
    return `${first.label}: ${formatValuationMoney(first.tlValue)} TL karşılığı ${usd} ve ${eur}`;
  }).filter(Boolean);
  if (!amounts.length) return "";
  const rateText = `USD alış kuru ${formatTcmbRate(usdRate)} TL, EUR alış kuru ${formatTcmbRate(eurRate)} TL`;
  return `TCMB${date ? ` ${date} tarihli` : ""} döviz alış kurları esas alınarak ${amounts.join("; ")}. Hesaplamada ${rateText} olarak dikkate alınmıştır.`;
}

function refreshForeignCurrencyValuationExplanation() {
  const explanation = buildForeignCurrencyValuationExplanation();
  state.fields.foreignCurrencyValuationExplanation = explanation;
  const text = document.querySelector("[data-foreign-currency-valuation-explanation-text]");
  if (text) text.textContent = explanation || "TCMB alış kurları alındığında döviz bazlı değerler otomatik hesaplanacaktır.";
}

function createForeignCurrencyValuationPanel() {
  refreshForeignCurrencyValuationExplanation();
  const panel = document.createElement("section");
  panel.className = "subsection foreign-currency-valuation-panel";
  const heading = document.createElement("h3");
  heading.textContent = "Döviz Bazlı Değerleme";
  const note = document.createElement("p");
  note.className = "subtle-text";
  note.textContent = tcmbRatePayload
    ? `TCMB ${formatTcmbDate(tcmbRatePayload.date) || "güncel"} alış kurları üzerinden hesaplanır.`
    : "TCMB alış kurları alındığında döviz bazlı değerler otomatik hesaplanacaktır.";
  panel.append(heading, note);

  const table = document.createElement("table");
  table.className = "foreign-currency-valuation-table";
  table.innerHTML = "<thead><tr><th>Değer</th><th>TL</th><th>USD</th><th>EUR</th></tr></thead>";
  const tbody = document.createElement("tbody");
  const rows = getForeignCurrencyValuationRows();
  ["legalValue", "currentValue", "legalUrgentSaleValue", "currentUrgentSaleValue"].forEach((valueKey) => {
    const pair = rows.filter((row) => row.valueKey === valueKey);
    const first = pair[0];
    if (!first) return;
    const tr = document.createElement("tr");
    [
      first.label,
      first.tlValue ? `${formatValuationMoney(first.tlValue)} TL` : "-",
      pair.find((row) => row.code === "USD")?.value || "-",
      pair.find((row) => row.code === "EUR")?.value || "-",
    ].forEach((value) => {
      const cell = document.createElement("td");
      cell.textContent = value;
      tr.append(cell);
    });
    tbody.append(tr);
  });
  table.append(tbody);
  const explanation = document.createElement("p");
  explanation.className = "foreign-currency-valuation-explanation";
  explanation.dataset.foreignCurrencyValuationExplanationText = "true";
  explanation.textContent = state.fields.foreignCurrencyValuationExplanation || "TCMB alış kurları alındığında döviz bazlı değerler otomatik hesaplanacaktır.";
  panel.append(table, explanation);
  return panel;
}

function setTcmbRateStatus(message) {
  if (!tcmbRateContent) return;
  const status = document.createElement("span");
  status.className = "tcmb-rate-status";
  status.textContent = message;
  tcmbRateContent.replaceChildren(status);
}

function createTcmbQuote(label, value) {
  const quote = document.createElement("div");
  quote.className = "tcmb-rate-quote";
  const quoteLabel = document.createElement("span");
  quoteLabel.textContent = label;
  const quoteValue = document.createElement("strong");
  quoteValue.textContent = formatTcmbRate(value);
  quote.append(quoteLabel, quoteValue);
  return quote;
}

function createTcmbCurrencyCard(code, currency) {
  const card = document.createElement("section");
  card.className = "tcmb-currency-card";
  const heading = document.createElement("strong");
  heading.className = "tcmb-currency-code";
  heading.textContent = `${code} / TRY`;
  card.append(
    heading,
    createTcmbQuote("Alış", currency?.buying),
    createTcmbQuote("Satış", currency?.selling),
  );
  return card;
}

function renderTcmbRates(payload) {
  if (!tcmbRateContent) return;
  const currencies = document.createElement("div");
  currencies.className = "tcmb-rate-currencies";
  currencies.append(
    createTcmbCurrencyCard("USD", payload.usd),
    createTcmbCurrencyCard("EUR", payload.eur),
  );
  const meta = document.createElement("div");
  meta.className = "tcmb-rate-meta";
  const metaLabel = document.createElement("span");
  metaLabel.textContent = payload.stale ? "Son başarılı veri" : "TCMB tarihi";
  const metaDate = document.createElement("strong");
  metaDate.textContent = formatTcmbDate(payload.date) || "-";
  meta.append(metaLabel, metaDate);
  tcmbRateContent.replaceChildren(currencies, meta);
}

async function refreshTcmbRates() {
  if (!tcmbRateContent) return;
  try {
    const response = await fetchRaporApi("/api/tcmb-rates");
    const payload = await response.json();
    if (!response.ok || !payload?.ok) throw new Error(payload?.error || "TCMB kurlari alinamadi.");
    tcmbRatePayload = payload;
    renderTcmbRates(payload);
    refreshForeignCurrencyValuationExplanation();
    tcmbRateStrip?.classList.toggle("is-unavailable", Boolean(payload.stale));
    tcmbRateRetryCount = 0;
  } catch (error) {
    // app.js, cloud-sync.js'den once yuklenir. Ilk anda Firebase ID token'i
    // henuz hazir olmayabilir; bu teknik baslangic sirasi kur bandini kalici
    // hataya dusurmemeli. Kisa ve sinirli tekrarlar token hazir oldugunda
    // otomatik olarak ayni istegi tamamlar.
    const shouldRetry = tcmbRateRetryCount < 6;
    if (shouldRetry) {
      tcmbRateRetryCount += 1;
      setTcmbRateStatus("TCMB kurları bağlantı hazırlanırken yeniden deneniyor...");
      window.setTimeout(refreshTcmbRates, 2500);
    } else {
      setTcmbRateStatus("TCMB kurları şu an alınamadı.");
    }
    tcmbRateStrip?.classList.add("is-unavailable");
  }
}

async function readPdfTextOnServer(file) {
  const response = await fetchRaporApi("/api/pdf-text", {
    method: "POST",
    headers: {
      "Content-Type": "application/pdf",
      "X-File-Name": encodeURIComponent(file.name || "belge.pdf"),
    },
    body: file,
  });

  let payload = null;
  try {
    payload = await response.json();
  } catch {
    payload = null;
  }

  if (!response.ok || !payload?.ok) {
    throw new Error(payload?.error || "PDF metni sunucu tarafında okunamadı.");
  }

  const text = String(payload.text || "");
  if (text.trim()) return text;
  throw getIosPdfTextOnlyError();
}

async function recognizePdfPages(pdf) {
  if (!window.Tesseract?.recognize) {
    throw new Error("PDF metin katmanı boş. OCR kütüphanesi yüklenemediği için görsel PDF okunamadı.");
  }

  const texts = [];
  const pageLimit = Math.min(pdf.numPages, 2);

  for (let pageNumber = 1; pageNumber <= pageLimit; pageNumber += 1) {
    const page = await pdf.getPage(pageNumber);
    const viewport = page.getViewport({ scale: 2 });
    const canvas = document.createElement("canvas");
    const context = canvas.getContext("2d");
    canvas.width = viewport.width;
    canvas.height = viewport.height;
    await page.render({ canvasContext: context, viewport }).promise;
    const result = await Tesseract.recognize(canvas, "tur+eng");
    texts.push(result?.data?.text || "");
  }

  return texts.join("\n");
}

async function recognizeImageText(file) {
  if (!window.Tesseract?.recognize) {
    throw new Error("OCR kütüphanesi yüklenemedi. İnternet bağlantısını kontrol edin.");
  }

  const result = await Tesseract.recognize(file, "tur+eng");
  return result?.data?.text || "";
}

function parseEkbFields(text) {
  return globalThis.RaporEkbParser.parseEkbFields(text);
}

function parseImarFields(text) {
  const raw = String(text || "");
  const allLines = raw.split(/\n+/).map((line) => line.replace(/\s+/g, " ").trim()).filter(Boolean);
  const lines = extractImarPlanInfoLines(allLines);
  const joined = lines.join("\n");
  const flat = lines.join(" ");
  const nextFieldPattern = /(Plan\s+Ad[ıi]|Plan\s+Fonksiyon|Tasdik|Onay|T\.?A\.?K\.?S|K\.?A\.?K\.?S|Emsal|Bah[çc]e|Nizam|Kat\s+Adedi|Bina\s+Y[üu]ksekli[ğg]i|Yola\s+Terk)/i;
  const planSpecialNote = extractImarPrePlanBlock(allLines, ["PLAN OZEL NOTU", "PLAN OZEL NOT"]);
  const restrictionNote = extractImarPrePlanBlock(allLines, ["KISITLAMA ACIKLAMA", "KISITLAMA ACIKL"]);
  const planRestrictionNote = buildImarPlanRestrictionNote(planSpecialNote, restrictionNote);
  const bilgiAlinanKurum = extractImarInfoInstitution(allLines);

  const pick = (...patterns) => {
    for (const pattern of patterns) {
      const match = flat.match(pattern);
      if (match?.[1]) return cleanImarToken(match[1]);
    }
    return "";
  };

  const collectAfterLabel = (labelPattern) => {
    const start = lines.findIndex((line) => labelPattern.test(line));
    if (start < 0) return "";
    const first = lines[start].replace(labelPattern, "").replace(/^[:\-]\s*/, "").trim();
    const parts = [];
    if (first) parts.push(first);
    for (let i = start + 1; i < lines.length; i += 1) {
      const line = lines[i];
      if (nextFieldPattern.test(line)) break;
      if (/^(not|uyar[ıi]|a[çc][ıi]klama|otopark)\b/i.test(line)) break;
      if (line.length > 120) break;
      parts.push(line);
      if (parts.join(" ").length > 160) break;
    }
    return cleanImarToken(parts.join(" "));
  };

  const findLine = (pattern) => lines.find((line) => pattern.test(line)) || "";
  const findLineByFold = (...needles) => {
    return lines.find((line) => {
      const folded = foldTurkish(line);
      return needles.some((needle) => folded.includes(needle));
    }) || "";
  };
  const valueFromKnownLine = (line, pattern) => {
    if (!line) return "";
    return cleanImarToken(line.replace(pattern, "").replace(/^[:\-]\s*/, ""));
  };
  const valueFromLine = (pattern) => {
    const line = findLine(pattern);
    if (!line) return "";
    return cleanImarToken(line.replace(pattern, "").replace(/^[:\-]\s*/, ""));
  };

  const scaleLineRaw = findLineByFold("OLCEGI");
  const tasdikLine = findLineByFold("TASDIK TARIHI");
  const planNameRaw = findLineByFold("PLANI ADI", "PLAN ADI");
  const scaleLine = valueFromKnownLine(scaleLineRaw, /^[^\d]*(?=\d)/i);
  const planNameLine = valueFromKnownLine(planNameRaw, /^Plan[ıiİI]\s+Ad[ıiİI]\s*/i);
  const heightLine = findLineByFold("BINA YUKSEKLIGI");
  const frontLine = findLineByFold("ON BAHCE");
  const sideLine = findLineByFold("YAN BAHCE");
  const backLine = findLineByFold("ARKA BAHCE");

  const frontNizamMatch = frontLine.match(/[ÖO]n\s+Bah[çc]e\s+(.+?)\s+[İI]n[şs]aat\s+Nizam[ıi]\s+(.+)$/i);
  const sideTaksMatch = sideLine.match(/Yan\s+Bah[çc]e\s+(.+?)\s+T\.?\s*A\.?\s*K\.?\s*S\.?\s+([0-9]+(?:[.,][0-9]+)?|-)/i);
  const backKaksMatch = backLine.match(/Arka\s+Bah[çc]e\s+(.+?)\s+K\.?\s*A\.?\s*K\.?\s*S\.?\s*(?:\(\s*Emsal\s*\))?\s+([0-9]+(?:[.,][0-9]+)?|-)/i);
  const heightValuePattern = "(?:[0-9]+(?:[.,][0-9]+)?\\s*m?|serbest|-)";
  const heightKatMatch = heightLine.match(new RegExp(`Bina\\s+Y[üu]ksekli[ğg]i\\s+(${heightValuePattern})\\s+Kat\\s+Adedi\\s+(\\d+)`, "i"));

  let planAdi = cleanImarPlanName(planNameLine) || pick(
    /Plan[ıi]\s+Ad[ıi]\s*:?\s*([^\n]+?)(?=\s+(?:Plan\s+Fonksiyon|Tasdik|Onay|T\.?A\.?K\.?S|K\.?A\.?K\.?S)|$)/i,
    /Mer['’]?[ıi]\s+[İi]mar\s+Plan[ıi]\s*:?\s*([^\n]+)/i
  );
  const scaleFromName = planAdi.match(/(\d+\s*\/\s*\d+)/);
  let planOlcegi = cleanImarToken(scaleLine.match(/(\d+\s*\/\s*\d+)/)?.[1] || (scaleFromName || flat.match(/[ÖöOo]l[çc][eğg]?[iı]\s*:?\s*(\d+\s*\/\s*\d+)/i) || [])[1] || "");
  planAdi = cleanImarPlanName(planAdi);

  const planTarihi = extractImarPlanDate(lines) || extractImarPlanDate(allLines) || normalizeImarDate(tasdikLine || pick(
    /(?:Plan\s+)?(?:Tasdik|Onay)\s+Tarih(?:i)?(?:\s+ve\s+No)?\s*:?\s*(\d{1,2}[./-]\d{1,2}[./-]\d{4})/i,
    /Tasdik\s*:?\s*(\d{1,2}[./-]\d{1,2}[./-]\d{4})/i
  ));

  const legendFromPlanBlock = extractImarLegendFromLines(lines);
  const legendFromFullText = extractImarLegendFromLines(allLines);
  let planFonk = legendFromPlanBlock || legendFromFullText || detectImarFunctionFromText(planAdi) || normalizeImarPlanFunction(collectAfterLabel(/Plan\s+Fonksiyon(?:u)?\s*:?\s*/i) || pick(
    /Plan\s+Fonksiyon(?:u)?\s*:?\s*([^\n]+?)(?=\s+(?:T\.?A\.?K\.?S|K\.?A\.?K\.?S|Emsal|Nizam|Bah[çc]e)|$)/i
  ));

  const taks = normalizeDecimalToken(sideTaksMatch?.[2] || pick(
    /T\.?\s*A\.?\s*K\.?\s*S\.?\s*:?\s*([0-9]+(?:[.,][0-9]+)?|-)/i,
    /Taban\s+Alan[ıi]\s+Katsay[ıi]s[ıi]\s*:?\s*([0-9]+(?:[.,][0-9]+)?|-)/i
  ));
  const kaks = normalizeDecimalToken(backKaksMatch?.[2] || pick(
    /K\.?\s*A\.?\s*K\.?\s*S\.?\s*(?:\(\s*Emsal\s*\))?\s*:?\s*([0-9]+(?:[.,][0-9]+)?|-)/i,
    /Emsal\s*:?\s*([0-9]+(?:[.,][0-9]+)?|-)/i,
    /\bE\s*=\s*([0-9]+(?:[.,][0-9]+)?)/i
  ));

  const onBahce = normalizeImarSetbackToken(frontNizamMatch?.[1] || pick(/[ÖO]n\s+Bah[çc]e(?:\s+Mesafesi)?\s*:?\s*([0-9]+(?:[.,][0-9]+)?\s*m?|-)/i));
  const yanBahce = normalizeImarSetbackToken(sideTaksMatch?.[1] || pick(/Yan\s+Bah[çc]e(?:\s+Mesafesi)?\s*:?\s*([0-9]+(?:[.,][0-9]+)?\s*m?|-)/i));
  const arkaBahce = normalizeImarSetbackToken(backKaksMatch?.[1] || pick(/Arka\s+Bah[çc]e(?:\s+Mesafesi)?\s*:?\s*([0-9]+(?:[.,][0-9]+)?\s*m?|-)/i));
  let insaatNizami = imarNizamCodeToLabel(frontNizamMatch?.[2] || pick(
    /(?:[İI]n[şs]aat|Yap[ıi])\s+Nizam[ıi]\s*:?\s*([A-ZÇĞİÖŞÜ]{1,3}|[A-Za-zÇĞİÖŞÜçğıöşü\s]+?)(?=\s+(?:Kat|Bina|T\.?A\.?K\.?S|K\.?A\.?K\.?S|Bah[çc]e)|$)/i,
    /\bNizam[ıi]\s*:?\s*([A-ZÇĞİÖŞÜ]{1,3}|[A-Za-zÇĞİÖŞÜçğıöşü\s]+?)(?=\s+(?:Kat|Bina|T\.?A\.?K\.?S|K\.?A\.?K\.?S|Bah[çc]e)|$)/i
  ));

  let katAdedi = heightKatMatch?.[2] || pick(/Kat\s+Adedi\s*:?\s*(\d+)/i);
  let binaYuksekligi = normalizeMeterToken(heightKatMatch?.[1] || pick(
    new RegExp(`Bina\\s+Y[üu]ksekli[ğg]i\\s*:?\\s*(${heightValuePattern})`, "i"),
    new RegExp(`H\\s*max\\s*:?\\s*(${heightValuePattern})`, "i")
  ));
  const nizamFallback = detectImarNizamFromText(joined);
  if (!insaatNizami && nizamFallback.insaatNizami) {
    insaatNizami = nizamFallback.insaatNizami;
  }
  if (!katAdedi && nizamFallback.katAdedi) {
    katAdedi = nizamFallback.katAdedi;
  }
  if (!planFonk) {
    planFonk = detectImarFunctionFromText(joined);
  }
  if (kaks) {
    insaatNizami = "Ayrık";
  }
  const calculatedKatAdedi = calculateImarKatFromHeight(binaYuksekligi);
  if (calculatedKatAdedi) {
    katAdedi = calculatedKatAdedi;
  }
  if (!binaYuksekligi && katAdedi) {
    binaYuksekligi = `${(Number(katAdedi) * 3 + 0.5).toLocaleString("tr-TR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} m`;
  }

  return {
    bilgiAlinanKurum,
    planOlcegi,
    planAdi,
    planTarihi,
    planFonk,
    taks,
    kaks,
    onBahce,
    yanBahce,
    arkaBahce,
    insaatNizami,
    binaYuksekligi,
    katAdedi,
    yolaTerk: "",
    planSpecialNote,
    restrictionNote,
    planRestrictionNote,
    imarNeighborhood: cleanImarToken(valueFromLine(/^İdari\s+Mahalle\s+Ad[ıi]\s*/i)),
    imarStreet: formatImarAddressStreet(valueFromLine(/^Cadde\s*\/\s*Sokak\s*/i)),
    imarOuterDoor: cleanImarToken(valueFromLine(/^Kap[ıi]\s+No\s*/i)),
  };
}

function cleanImarToken(value) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .replace(/[;,\s]+$/g, "")
    .trim();
}

function extractImarInfoInstitution(lines) {
  return globalThis.RaporImarNormalizer.extractImarInfoInstitution(lines);
}

function cleanImarInstitutionName(value) {
  return globalThis.RaporImarNormalizer.cleanImarInstitutionName(value);
}

function extractImarPlanInfoLines(lines) {
  const source = Array.isArray(lines) ? lines : [];
  const start = source.findIndex((line) => {
    const folded = foldTurkish(line);
    return folded.includes("YURURLUKTEKI IMAR PLANI") && folded.includes("YAPILASMA BILGILERI");
  });
  if (start < 0) return source;

  const end = source.findIndex((line, index) => {
    if (index <= start) return false;
    const folded = foldTurkish(line);
    return folded.includes("KADASTRO PARSEL ADRESI")
      || folded.includes("TAPU KUTUGU")
      || folded.includes("ACIKLAMALAR")
      || folded.includes("NOTLAR");
  });

  const block = source.slice(start + 1, end > start ? end : undefined);
  return block.length ? block : source;
}

function extractImarPrePlanBlock(lines, labelNeedles) {
  const source = Array.isArray(lines) ? lines : [];
  const start = source.findIndex((line) => {
    const folded = foldTurkish(line);
    return labelNeedles.some((needle) => folded.includes(needle));
  });
  if (start < 0) return "";

  const parts = [];
  const startLine = cleanImarToken(source[start]);
  const sameLineValue = cleanImarPrePlanLabelValue(startLine, labelNeedles);
  if (sameLineValue && sameLineValue !== "-") parts.push(sameLineValue);
  if (hasAnotherImarPrePlanBoundaryAfterLabel(startLine, labelNeedles)) {
    return cleanImarToken(parts.join(" "));
  }

  for (let index = start + 1; index < source.length; index += 1) {
    const line = cleanImarToken(source[index]);
    if (!line) continue;
    if (isImarPrePlanSectionBoundary(line)) break;
    if (line === "-") continue;
    parts.push(line);
  }

  return cleanImarToken(parts.join(" "));
}

function cleanImarPrePlanLabelValue(line, labelNeedles) {
  const clean = cleanImarToken(line);
  if (!clean) return "";
  const folded = foldTurkish(clean);
  const label = labelNeedles.find((needle) => folded.includes(needle));
  if (!label) return "";
  const labelEnd = folded.indexOf(label) + label.length;
  const afterLabel = trimImarPrePlanAtNextBoundary(clean.slice(Math.min(clean.length, labelEnd)).replace(/^[:\-]\s*/, "").trim());
  if (!afterLabel || afterLabel === "-") return "";
  if (afterLabel.startsWith("-")) return cleanImarToken(afterLabel.slice(1));
  return afterLabel;
}

function buildImarPlanRestrictionNote(planSpecialNote, restrictionNote) {
  const parts = [];
  if (planSpecialNote) parts.push(planSpecialNote);
  if (restrictionNote) parts.push(restrictionNote);
  return cleanImarPlanRestrictionNote(parts.join("\n"));
}

function cleanImarPlanRestrictionNote(value) {
  return String(value || "")
    .split(/\n+/)
    .filter((line) => !isImarPlanRestrictionExcludedLine(line))
    .map((line) => trimImarPrePlanAtNextBoundary(line))
    .filter((line) => line && !isImarPrePlanSectionBoundary(line))
    .join("\n")
    .trim();
}

function isImarPlanRestrictionExcludedLine(value) {
  const folded = foldTurkish(value).replace(/[^A-Z0-9]+/g, " ").trim();
  return /^(ZEMIN\s+DURUMU|HAVA\s+MANIA|PARSELASYON)\b/.test(folded)
    || /\bPARSELASYON\b/.test(folded)
    || /\bENCUMEN\s+TASDIKLI\b/.test(folded);
}

function hasAnotherImarPrePlanBoundaryAfterLabel(line, labelNeedles) {
  const clean = cleanImarToken(line);
  if (!clean) return false;
  const folded = foldTurkish(clean).replace(/[^A-Z0-9]+/g, " ").trim();
  const label = labelNeedles.find((needle) => folded.includes(needle));
  if (!label) return false;
  const afterLabel = folded.slice(folded.indexOf(label) + label.length);
  return isImarPrePlanSectionBoundary(afterLabel);
}

function isImarPrePlanSectionBoundary(value) {
  const folded = foldTurkish(value).replace(/[^A-Z0-9]+/g, " ").trim();
  return /\bPLAN\s+FONKSIYON/.test(folded)
    || /\bPLAN\s+OZEL\s+NOTU/.test(folded)
    || /\bKISITLAMA\s+ACIKL/.test(folded)
    || /\bYAPI\s+ADASI\s+NOTU/.test(folded)
    || /\bZEMIN\s+DURUMU/.test(folded)
    || /\bHAVA\s+MANIA/.test(folded)
    || /\bPARSELASYON/.test(folded)
    || /\bKADASTRO\s+PARSEL/.test(folded)
    || /\bYURURLUKTEKI\s+IMAR\s+PLANI/.test(folded);
}

function trimImarPrePlanAtNextBoundary(value) {
  const text = cleanImarToken(value);
  if (!text) return "";
  const boundaryPatterns = [
    /Plan\s+Fonksiyon(?:u)?/i,
    /Plan\s+[ÖO]zel\s+Notu/i,
    /K[ıi]s[ıi]tlama\s+A[çc][ıi]klama/i,
    /Yap[ıi]\s+Adas[ıi]\s+Notu/i,
    /Zemin\s+Durumu/i,
    /Hava\s+Mania/i,
    /Parselasyon/i,
    /\b[0-9]{1,2}[./][0-9]{1,2}[./][0-9]{4}\s+Tarihli[^.]*Parselasyon/i,
    /Enc[uü]men\s+Tasdikli\s+Parselasyon/i,
    /Kadastro\s+Parsel/i,
    /Y[üu]r[üu]rl[üu]kteki\s+[İI]mar\s+Plan[ıi]/i,
  ];
  const indexes = boundaryPatterns
    .map((pattern) => {
      const match = text.match(pattern);
      return match ? match.index : -1;
    })
    .filter((index) => index > 0);
  if (!indexes.length) return text;
  return cleanImarToken(text.slice(0, Math.min(...indexes)));
}

function extractImarLegendFromLines(lines) {
  const source = Array.isArray(lines) ? lines : [];
  const start = source.findIndex((line) => foldTurkish(line).includes("PLAN FONKSIYON"));
  if (start < 0) return "";

  const items = [];
  const seen = new Set();
  for (const line of source.slice(start + 1)) {
    const raw = cleanImarToken(line);
    if (!raw) continue;
    const folded = foldTurkish(raw);

    if (
      folded.includes("BINA YUKSEKLIGI")
      || folded.includes("KAT ADEDI")
      || folded.includes("ON BAHCE")
      || folded.includes("YAN BAHCE")
      || folded.includes("ARKA BAHCE")
      || folded.includes("INSAAT NIZAMI")
      || folded.includes("TAKS")
      || folded.includes("KAKS")
      || folded.includes("EMSAL")
      || folded.includes("KOT ALINACAK")
      || folded.includes("BINA DERINLIGI")
      || folded.includes("KADASTRO PARSEL")
    ) {
      break;
    }

    if (
      folded.includes("PLAN FONKSIYON")
      || folded.includes("FONKSIYON UYARI")
      || folded.includes("PLAN NOT")
      || folded.includes("PARANTEZ")
      || folded.includes("GOSTERIR")
      || folded.includes("TAPU ALANI")
      || folded.includes("UYGULAMA IMAR PLANI")
    ) {
      continue;
    }

    if (!/\b(ALANI|BOLGESI|BOLGE|KONUT|TICARET|SANAYI|KIRSAL|KENTSEL|TURIZM|REKREASYON|PARK|YESIL)\b/.test(folded)) {
      continue;
    }

    const item = cleanImarLegendItem(raw);
    if (!item) continue;
    if (hasImarLegendAreaParenthesis(raw)) {
      return item;
    }
    const key = foldTurkish(item);
    if (seen.has(key)) continue;
    seen.add(key);
    items.push(item);
  }

  return items.join(", ");
}

function hasImarLegendAreaParenthesis(value) {
  return /\([^)]*\d+(?:[.,]\d+)?\s*m\s*(?:²|2)?[^)]*\)/i.test(String(value || ""));
}

function cleanImarLegendItem(value) {
  return globalThis.RaporImarNormalizer.cleanImarLegendItem(value);
}

function cleanImarPlanName(value) {
  return globalThis.RaporImarNormalizer.cleanImarPlanName(value);
}

function normalizeImarSetbackToken(value) {
  const clean = cleanImarToken(value);
  if (!clean || clean === "-") return "";
  if (/^[0-9]+(?:[.,][0-9]+)?\s*m?$/i.test(clean)) return normalizeMeterToken(clean);
  return clean;
}

function formatImarAddressStreet(value) {
  const raw = cleanImarToken(value);
  if (!raw) return "";
  const shortMatch = raw.match(/^(.+?)\s+(SK|SK\.|SOK|SOK\.|CD|CD\.|CAD|CAD\.|BLV|BLV\.|BUL|BUL\.)$/i);
  if (!shortMatch) return formatStreetWithType(raw);
  const typeMap = {
    SK: "Sokak",
    SOK: "Sokak",
    CD: "Caddesi",
    CAD: "Caddesi",
    BLV: "Bulvarı",
    BUL: "Bulvarı",
  };
  const key = shortMatch[2].replace(/\./g, "").toLocaleUpperCase("tr");
  const name = toTitleCaseTr(shortMatch[1]);
  return `${name} ${typeMap[key] || ""}`.trim();
}

function normalizeImarDate(value) {
  const match = String(value || "").match(/(\d{1,2})[./-](\d{1,2})[./-](\d{4})/);
  if (!match) return "";
  return `${match[1].padStart(2, "0")}.${match[2].padStart(2, "0")}.${match[3]}`;
}

function extractImarPlanDate(lines) {
  return globalThis.RaporImarNormalizer.extractImarPlanDate(lines);
}

function normalizeDecimalToken(value) {
  const clean = cleanImarToken(value);
  if (!clean || clean === "-") return "";
  return clean.replace(",", ".");
}

function normalizeMeterToken(value) {
  const clean = cleanImarToken(value);
  if (!clean || clean === "-") return "";
  if (/^serbest$/i.test(clean)) return "Serbest";
  return /\bm\b/i.test(clean) ? clean : `${clean} m`;
}

function normalizeImarPlanFunction(value) {
  return globalThis.RaporImarNormalizer.normalizeImarPlanFunction(value);
}

function normalizeImarLegendLabel(value) {
  return globalThis.RaporImarNormalizer.normalizeImarLegendLabel(value);
}

function imarNizamCodeToLabel(value) {
  const clean = cleanImarToken(value);
  const upper = clean.toLocaleUpperCase("tr").replace(/\s+/g, "");
  if (upper === "A") return "Ayrık";
  if (upper === "B") return "Bitişik";
  if (upper === "BL") return "Blok";
  if (upper === "IK" || upper === "İK") return "İkiz";
  if (upper === "CB") return "Çekme bölge";
  return clean;
}

function detectImarNizamFromText(text) {
  const folded = foldTurkish(text);
  const codePatterns = [
    /\b(BL|IK|CB)\s*[-–—]?\s*(\d{1,2})\b/g,
    /\b([AB])\s*[-–—]\s*(\d{1,2})\b/g,
  ];

  for (const pattern of codePatterns) {
    for (const match of folded.matchAll(pattern)) {
      const code = match[1] === "IK" ? "İK" : match[1];
      const label = imarNizamCodeToLabel(code);
      if (label && /^\d{1,2}$/.test(match[2])) {
        return { insaatNizami: label, katAdedi: match[2] };
      }
    }
  }

  const textPatterns = [
    [/BLOK\s+NIZAM/, "Blok"],
    [/BITISIK\s+NIZAM/, "Bitişik"],
    [/AYRIK\s+NIZAM/, "Ayrık"],
    [/IKIZ\s+NIZAM/, "İkiz"],
  ];
  const found = textPatterns.find(([pattern]) => pattern.test(folded));
  return found ? { insaatNizami: found[1], katAdedi: "" } : { insaatNizami: "", katAdedi: "" };
}

function detectImarFunctionFromText(text) {
  return globalThis.RaporImarNormalizer.detectImarFunctionFromText(text);
}

function calculateImarKatFromHeight(heightValue) {
  const match = String(heightValue || "").replace(",", ".").match(/(\d+(?:\.\d+)?)/);
  if (!match) return "";
  const height = Number(match[1]);
  if (!Number.isFinite(height) || height <= 0.5) return "";
  const kat = Math.round((height - 0.5) / 3);
  return kat > 0 ? String(kat) : "";
}

function extractEkbDocumentNo(text) {
  const belgePattern = /\b([A-Z]\d[A-Z0-9]{11})\b/i;
  const windIndex = foldTurkish(text).search(/RUZGAR\s+ENERJISI/);
  if (windIndex >= 0) {
    const match = text.slice(windIndex).match(belgePattern);
    if (match) return match[1].toUpperCase();
  }
  const labeled = text.match(/Numaras[ıi]\s*:?\s*([A-Z]\d[A-Z0-9]{11})\b/i);
  if (labeled) return labeled[1].toUpperCase();
  const fallback = text.match(belgePattern);
  return fallback ? fallback[1].toUpperCase() : "";
}

function extractEkbDates(lines) {
  const datePattern = /\b(\d{1,2}\.\d{1,2}\.\d{4})\b/g;
  const allDates = lines.flatMap((line, lineIndex) =>
    [...line.matchAll(datePattern)]
      .map((match) => ({
        value: normalizeEkbDate(match[1]),
        lineIndex,
        index: match.index || 0,
      }))
      .filter((date) => date.value),
  );
  const uniqueDates = [...new Set(allDates.map((date) => date.value))];
  let issueDate = "";
  let validUntil = "";

  lines.forEach((line) => {
    const folded = foldTurkish(line);
    const date = normalizeEkbDate((line.match(/\b(\d{1,2}\.\d{1,2}\.\d{4})\b/) || [])[1]);
    if (!date) return;
    if (!issueDate && /VERILIS\s+TARIHI/.test(folded)) issueDate = date;
    if (!validUntil && /(SON\s+)?GECERLILIK\s+TARIHI/.test(folded)) validUntil = date;
  });

  const tenYearPair = findEkbTenYearDatePair(allDates);
  if (tenYearPair && (!issueDate || !validUntil)) {
    issueDate = issueDate || tenYearPair.issueDate;
    validUntil = validUntil || tenYearPair.validUntil;
  }

  if (issueDate && !validUntil) {
    const expectedValidUntil = addYearsToTrDate(issueDate, 10);
    if (uniqueDates.includes(expectedValidUntil)) validUntil = expectedValidUntil;
  }
  if (validUntil && !issueDate) {
    const expectedIssueDate = addYearsToTrDate(validUntil, -10);
    if (uniqueDates.includes(expectedIssueDate)) issueDate = expectedIssueDate;
  }

  if (!issueDate && uniqueDates.length >= 1) {
    issueDate = uniqueDates[uniqueDates.length >= 2 ? uniqueDates.length - 2 : 0];
  }
  if (!validUntil && uniqueDates.length >= 2) {
    validUntil = uniqueDates[uniqueDates.length - 1];
  }

  return { issueDate, validUntil };
}

function normalizeEkbDate(value) {
  const match = String(value || "").match(/\b(\d{1,2})\.(\d{1,2})\.(\d{4})\b/);
  if (!match) return "";
  return `${match[1].padStart(2, "0")}.${match[2].padStart(2, "0")}.${match[3]}`;
}

function findEkbTenYearDatePair(dates) {
  const list = Array.isArray(dates) ? dates.filter((date) => date.value) : [];
  let pair = null;
  for (let i = 0; i < list.length; i += 1) {
    const expectedValidUntil = addYearsToTrDate(list[i].value, 10);
    if (!expectedValidUntil) continue;
    const later = list.slice(i + 1).find((date) => date.value === expectedValidUntil);
    if (later) {
      pair = { issueDate: list[i].value, validUntil: later.value };
    }
  }
  return pair;
}

function addYearsToTrDate(value, years) {
  const normalized = normalizeEkbDate(value);
  const match = normalized.match(/^(\d{2})\.(\d{2})\.(\d{4})$/);
  if (!match) return "";
  const year = Number(match[3]) + years;
  return `${match[1]}.${match[2]}.${String(year).padStart(4, "0")}`;
}

function extractEkbClasses(lines, text) {
  let energyClass = pickClassNearLabel(lines, /PERFORMANS\s+SINIFI|ENERJI\s+SINIFI/);
  let emissionClass = pickClassNearLabel(lines, /EMISYON\s+SINIFI|SERA\s+GAZI/);

  if (!energyClass) {
    energyClass = findGraphClass(lines, 0);
  }
  if (!emissionClass) {
    emissionClass = findGraphClass(lines, 1);
  }
  if (!emissionClass && energyClass && /SERA|EMISYON/i.test(foldTurkish(text))) {
    emissionClass = findGraphClass(lines, 1) || "";
  }

  return { energyClass, emissionClass };
}

function pickClassNearLabel(lines, labelPattern) {
  for (let i = 0; i < lines.length; i += 1) {
    const folded = foldTurkish(lines[i]);
    if (!labelPattern.test(folded)) continue;
    const sameLine = lines[i].match(/\b([A-G])\b(?!.*\b[A-G]\b)/i);
    if (sameLine) return sameLine[1].toUpperCase();
    for (let offset = 1; offset <= 3; offset += 1) {
      const next = lines[i + offset] || "";
      const match = next.match(/\b([A-G])\b(?!.*\b[A-G]\b)/i);
      if (match) return match[1].toUpperCase();
    }
  }
  return "";
}

function findGraphClass(lines, occurrenceIndex = 0) {
  const matches = [];
  lines.forEach((line) => {
    const graphMatch =
      line.match(/\b\d+\s*[-–]\s*\d+\s+\d+\s+\d+\s*[-–]\s*\d+\s+\d+\s+([A-G])\b/i) ||
      line.match(/\b\d+\s*[-–]\s*\d+\s+\d+\s+([A-G])\s*$/i) ||
      line.match(/\b\d{1,3}(?:\.\d{3})+,\d+\s+([A-G])\s*$/i);
    if (graphMatch) matches.push(graphMatch[1].toUpperCase());
  });
  return matches[occurrenceIndex] || matches[0] || "";
}

function dateTrToIso(value) {
  const match = normalizeEkbDate(value).match(/^(\d{2})\.(\d{2})\.(\d{4})$/);
  return match ? `${match[3]}-${match[2]}-${match[1]}` : "";
}

function dateIsoToTr(value) {
  const text = String(value || "").trim();
  if (!text) return "";

  const isoMatch = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T\s].*)?$/);
  if (isoMatch) {
    return `${isoMatch[3].padStart(2, "0")}.${isoMatch[2].padStart(2, "0")}.${isoMatch[1]}`;
  }

  const localMatch = text.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})$/);
  if (localMatch) {
    return `${localMatch[1].padStart(2, "0")}.${localMatch[2].padStart(2, "0")}.${localMatch[3]}`;
  }

  return text;
}

function isOutputDateColumnLabel(label = "") {
  const folded = foldTurkish(label).replace(/[^A-Z0-9]+/g, " ").trim();
  return folded.includes("TARIH") || folded === "SATIS ZAMANI";
}

function formatOutputFieldValue(value, fieldDefinition = {}) {
  return fieldDefinition?.type === "date" ? dateIsoToTr(value) : value;
}

function refreshReviewedDocumentsDescriptionFromCurrentRows() {
  state.fields.projectReviewDescription = buildProjectReviewExplanation();
  const projectControl = document.querySelector('[data-field="projectReviewDescription"]');
  if (projectControl) {
    projectControl.value = state.fields.projectReviewDescription || "";
    markFieldSourceState(projectControl, "projectReviewDescription", true);
  }
  state.fields.reviewedDocumentsDescription = buildReviewedDocumentsDescription();
  const control = document.querySelector('[data-field="reviewedDocumentsDescription"]');
  if (control) {
    control.value = state.fields.reviewedDocumentsDescription || "";
    markFieldSourceState(control, "reviewedDocumentsDescription", true);
  }
  refreshBuildingCompletionFromCurrentFields();
  refreshBuildingInspectionExplanationFromCurrentFields();
}

function refreshReviewedDocumentsDescriptionFromCurrentFields(changedKey) {
  const watchedKeys = [
    "municipalityInspectionDate",
    "appointmentDate",
    "district",
    "titleDistrict",
    "ownershipType",
    "mainPropertyQuality",
    "oldBlockNo",
    "oldParcelNo",
    "documentReviewInstitution",
    "hasArchitecturalProject",
    "projectRegisteredInCadastre",
    "cadastralRegisteredBaseArea",
    "cadastralFootprintMatches",
    "cadastralCorrectionFloorCount",
    "projectInstitution",
    "takbisMethod",
    "projectDifference",
    "projectType",
    "projectDate",
    "projectNo",
    "titleProjectType",
    "titleProjectDate",
    "titleProjectNo",
    "municipalityProjectType",
    "municipalityProjectDate",
    "municipalityProjectNo",
    "projectSuitabilityStatus",
    "projectConformity",
    "projectSuitabilitySimpleRepair",
    "buildingFootprintReference",
    "buildingEntranceLevel",
    "buildingEntranceDirection",
    "titleProjectSuitabilityStatus",
    "titleProjectSuitabilityNote",
    "titleProjectSuitabilitySimpleRepair",
    "municipalityProjectSuitabilityStatus",
    "municipalityProjectSuitabilityNote",
    "municipalityProjectSuitabilitySimpleRepair",
    "mainRealEstateProjectSuitable",
    "mainRealEstateProjectSuitabilityNote",
    "hasEkb",
    "ekbDocumentNo",
    "ekbIssueDate",
    "ekbValidUntil",
    "ekbEnergyClass",
  ];
  if (!watchedKeys.includes(changedKey)) return;
  if (changedKey === "projectInstitution") {
    ensureDocumentReviewInstitutionDefault(true);
  } else if (["district", "titleDistrict"].includes(changedKey)) {
    ensureDocumentReviewInstitutionDefault();
  }
  refreshReviewedDocumentsDescriptionFromCurrentRows();
}

function ensureDocumentReviewInstitutionDefault(force = false) {
  if (!force && String(state.fields.documentReviewInstitution || "").trim()) return;
  if (!getSelectedProjectInstitutions().length) return;
  const summary = buildProjectReviewInstitutionSummary();
  if (!summary) return;
  state.fields.documentReviewInstitution = summary;
}

function getSelectedProjectInstitutions() {
  const seen = new Set();
  return String(state.fields.projectInstitution || "")
    .split(",")
    .map((item) => normalizeReportTitleText(item).trim())
    .filter((value) => value && !/^seçiniz$/i.test(value))
    .filter((value) => {
      const key = foldTurkish(value);
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

function projectInstitutionIncludes(keyword) {
  const foldedKeyword = foldTurkish(keyword);
  if (foldedKeyword.includes("OSB") || foldedKeyword.includes("ORGANIZE SANAYI")) {
    return getSelectedProjectInstitutions().some(isOsbInstitutionValue);
  }
  return getSelectedProjectInstitutions().some((institution) => foldTurkish(institution).includes(foldedKeyword));
}

function isOsbInstitutionValue(value) {
  const folded = foldTurkish(value);
  return folded.includes("OSB") || folded.includes("ORGANIZE SANAYI BOLGE MUDURLUGU");
}

function buildProjectReviewInstitutionSummary() {
  const selected = getSelectedProjectInstitutions();
  const district = getProjectReviewDistrictText();
  const mapped = selected.map((institution) => formatProjectInstitutionForSummary(institution, district)).filter(Boolean);
  if (mapped.length) return joinTurkishList(mapped);
  return district ? `${district} Belediyesi` : "";
}

function formatProjectInstitutionForSummary(institution, district = getProjectReviewDistrictText()) {
  const clean = normalizeReportTitleText(institution || "").trim();
  const folded = foldTurkish(clean);
  if (folded.includes("WEBTAPU")) return "Webtapu Portalı";
  if (folded.includes("BELEDIYE")) return district ? `${district} Belediyesi` : "Belediye";
  if (isOsbInstitutionValue(clean)) {
    return folded === foldTurkish(imarOsbInstitutionOption) ? imarOsbInstitutionOption : clean;
  }
  if (folded.includes("OZEL IDARE")) return "İl Özel İdaresi";
  if (folded.includes("BUYUKSEHIR")) return "Büyükşehir Belediyesi";
  if (folded.includes("ANITLAR")) return "Anıtlar Kurulu";
  return clean;
}

function getProjectDetailLabelPrefix() {
  const selected = getSelectedProjectInstitutions();
  if (selected.length === 1) {
    const folded = foldTurkish(selected[0]);
    if (folded.includes("WEBTAPU")) return "Tapu";
    if (folded.includes("BELEDIYE")) return "Belediye";
    return normalizeReportTitleText(selected[0]).trim() || "Proje";
  }
  if (projectInstitutionIncludes("Webtapu") && projectInstitutionIncludes("Belediye")) return "Tapu/Belediye";
  return "Tapu/Belediye";
}

function getProjectReviewDateText() {
  return dateIsoToTr(state.fields.municipalityInspectionDate || state.fields.appointmentDate || "").trim();
}

function getProjectReviewDistrictText() {
  return normalizeReportTitleText(state.fields.titleDistrict || state.fields.district || "").trim();
}

function formatProjectReviewLocation(institution) {
  const district = getProjectReviewDistrictText();
  const clean = normalizeReportTitleText(institution || "").trim();
  const folded = foldTurkish(clean);
  if (folded.includes("WEBTAPU")) {
    return district ? `${district} Tapu Müdürlüğü Webtapu Portalında` : "Tapu Müdürlüğü Webtapu Portalında";
  }
  if (folded.includes("BELEDIYE")) {
    return district ? `${district} Belediyesi İmar ve Şehircilik Müdürlüğünde` : "Belediye İmar ve Şehircilik Müdürlüğünde";
  }
  if (folded.includes("OSB")) return `${clean} arşivinde`;
  if (folded.includes("OZEL IDARE")) return `${clean} arşivinde`;
  if (folded.includes("BUYUKSEHIR")) return `${clean} arşivinde`;
  if (folded.includes("ANITLAR")) return `${clean} arşivinde`;
  return clean ? `${clean} arşivinde` : "ilgili kurum arşivinde";
}

function formatProjectReviewLocationForMissing(institution) {
  const district = getProjectReviewDistrictText();
  const folded = foldTurkish(institution || "");
  if (folded.includes("WEBTAPU")) return "Webtapu Portalında";
  if (folded.includes("BELEDIYE")) return district ? `${district} Belediyesi İmar ve Şehircilik Müdürlüğünde` : "Belediye İmar ve Şehircilik Müdürlüğünde";
  return formatProjectReviewLocation(institution);
}

function formatProjectReference(dateValue, noValue, typeValue = "") {
  const date = dateIsoToTr(dateValue || "").trim();
  const no = String(noValue || "").trim();
  const type = normalizeReportTitleText(typeValue || "Mimari Proje").trim() || "Mimari Proje";
  const parts = [];
  if (date) parts.push(`${date} tarih`);
  if (no) parts.push(`${no} sayılı`);
  parts.push(type.toLocaleLowerCase("tr-TR"));
  return parts.join(" ");
}

function formatOldAdaParcelProjectNote() {
  const oldAda = String(state.fields.oldBlockNo || "").trim();
  const oldParcel = String(state.fields.oldParcelNo || "").trim();
  if (oldAda && oldParcel) return `(Projenin taşınmazın geçmişi olan ${oldAda} ada ${oldParcel} parsel için hazırlanmış olduğu görülmüştür.)`;
  if (oldAda) return `(Projenin taşınmazın geçmişi olan ${oldAda} ada için hazırlanmış olduğu görülmüştür.)`;
  if (oldParcel) return `(Projenin taşınmazın geçmişi olan ${oldParcel} parsel için hazırlanmış olduğu görülmüştür.)`;
  return "";
}

function buildNoArchitecturalProjectDescription() {
  const district = getProjectReviewDistrictText() || "İlgili";
  if (isLandProjectReview()) {
    const quality = normalizeReportTitleText(
      state.fields.mainPropertyQuality || state.fields.titleQuality || state.fields.legalUsageNature || "Arsa"
    ).trim() || "Arsa";
    return `Ekspertize konu taşınmaz ${quality} niteliğinde olup, ${district} Belediyesinde yapılan incelemelerde taşınmaza ait ruhsat ve mimari proje bulunmamaktadır.`;
  }
  const paragraphs = [
    `${district} Belediyesi ve Webtapu Portalında yapılan incelemelerde ekspertize konu taşınmaza ait mimari proje bulunamamıştır.`,
  ];
  const cadastreValue = normalizeYesNoChoice(state.fields.projectRegisteredInCadastre);
  const cadastrePrefix = `${district} Kadastro Müdürlüğünden alınan sözlü bilgiye göre parsel üzerinde yer alan yapının kadastral paftasına`;
  if (cadastreValue === "Hayır") {
    paragraphs.push(`${cadastrePrefix} işli olmadığı bilgisi alınmıştır.`);
  } else if (cadastreValue === "Evet") {
    const cadastralParts = [`${cadastrePrefix} işli olduğu`];
    const baseArea = parseReportNumber(state.fields.cadastralRegisteredBaseArea);
    if (Number.isFinite(baseArea) && baseArea > 0) {
      cadastralParts.push(`pafta üzerine işli taban alanının ${formatSquareMeterArea(baseArea)} olduğu bilgisi alınmıştır`);
    } else {
      cadastralParts.push("bilgisi alınmıştır");
    }
    const footprint = normalizeYesNoChoice(state.fields.cadastralFootprintMatches);
    const sentences = [`${cadastralParts.join(", ")}.`];
    if (footprint) {
      sentences.push(
        `Yerinde yapılan incelemeler ve ölçümlerde parsel üzerindeki yapının taban oturumunun kadastral paftaya ${footprint === "Evet" ? "uygun olduğu" : "uygun olmadığı"} tespit edilmiştir.`
      );
    }
    const quality = normalizeReportTitleText(state.fields.mainPropertyQuality || "").trim();
    const floorCount = String(state.fields.cadastralCorrectionFloorCount || "").trim();
    if (quality || floorCount) {
      const qualityText = quality ? `Ana taşınmaz niteliği ${quality} olup` : "Ana taşınmaz yönünden";
      const floorText = floorCount ? `Cins Tashihine Esas Kat Sayısı ${floorCount} kat olduğu` : "cins tashihi bilgisinin mevcut olduğu";
      sentences.push(`${qualityText}, ${floorText} görüş ve kanaatindeyiz.`);
    }
    paragraphs.push(sentences.join(" "));
  }
  return normalizeReportDescriptionText(paragraphs.filter(Boolean).join("\n\n"));
}

function buildSingleInstitutionCondominiumProjectDescription(institution, projectReference, dateLead) {
  const district = getProjectReviewDistrictText();
  const folded = foldTurkish(institution || "");
  if (folded.includes("BELEDIYE") && !folded.includes("WEBTAPU")) {
    const reviewedAt = formatProjectReviewLocation("Belediye");
    if (state.fields.takbisMethod === "Tapu Kaydı Alınmamıştır.") {
      return `${dateLead}${reviewedAt} ekspertize konu taşınmaza ait ${projectReference} incelenmiştir. TAKBİS belgesi alınmadığından taşınmaza ait tapu projesi incelenememiştir.`;
    }
    const missingPlace = district ? `Webtapu Portalında ve ${district} Tapu Müdürlüğünde` : "Webtapu Portalında ve Tapu Müdürlüğünde";
    return `${dateLead}${reviewedAt} ekspertize konu taşınmaza ait ${projectReference} incelenmiştir. ${missingPlace} taşınmazın yer aldığı binaya ait mimari proje bulunamamıştır.`;
  }
  if (folded.includes("WEBTAPU")) {
    const missingPlace = district ? `${district} Belediyesi İmar ve Şehircilik Arşivinde` : "Belediye İmar ve Şehircilik Arşivinde";
    return `${dateLead}Webtapu Portalında ekspertize konu taşınmaza ait ${projectReference} incelenmiştir. ${missingPlace} taşınmazın yer aldığı binaya ait mimari proje bulunamamıştır.`;
  }
  return "";
}

function buildProjectReviewDescription() {
  const hasArchitecturalProject = normalizeYesNoChoice(state.fields.hasArchitecturalProject || "Evet") !== "Hayır";
  const selectedInstitutions = getSelectedProjectInstitutions();
  const hasProjectData = [
    "projectDate",
    "projectNo",
    "projectType",
    "titleProjectDate",
    "titleProjectNo",
    "titleProjectType",
    "municipalityProjectDate",
    "municipalityProjectNo",
    "municipalityProjectType",
  ].some((key) => String(state.fields[key] || "").trim());
  if (hasArchitecturalProject && !selectedInstitutions.length && !hasProjectData) return "";
  const reviewDate = getProjectReviewDateText();
  const dateLead = reviewDate ? `${reviewDate} tarihinde ` : "";
  const oldAdaParcelNote = formatOldAdaParcelProjectNote();
  const locationLead =
    "Ana gayrimenkulle ilgili olarak ada, parsel bazında yerinin doğruluğu parselasyon planından ve imar planından tespit edilmiştir.";

  if (!hasArchitecturalProject) {
    return normalizeReportDescriptionText([buildNoArchitecturalProjectDescription(), oldAdaParcelNote].filter(Boolean).join("\n\n"));
  }

  const hasDifferentProjects = shouldUseProjectDifferenceComparison();
  const reviewItems = [];
  if (hasDifferentProjects) {
    if (projectInstitutionIncludes("Webtapu") || !selectedInstitutions.length) {
      reviewItems.push(
        `${formatProjectReviewLocation("Webtapu")} ${formatProjectReference(
          state.fields.titleProjectDate,
          state.fields.titleProjectNo,
          state.fields.titleProjectType,
        )} incelenmiştir.`
      );
    }
    if (projectInstitutionIncludes("Belediye") || !selectedInstitutions.length) {
      reviewItems.push(
        `${formatProjectReviewLocation("Belediye")} ${formatProjectReference(
          state.fields.municipalityProjectDate,
          state.fields.municipalityProjectNo,
          state.fields.municipalityProjectType,
        )} incelenmiştir.`
      );
    }
  } else {
    const institutions = selectedInstitutions.length ? selectedInstitutions : ["Webtapu", "Belediye"];
    const projectReference = formatProjectReference(state.fields.projectDate, state.fields.projectNo, state.fields.projectType);
    if (institutions.length === 1 && isCondominiumOwnershipType()) {
      const singleText = buildSingleInstitutionCondominiumProjectDescription(institutions[0], projectReference, dateLead);
      if (singleText) {
        reviewItems.push(singleText.replace(dateLead, ""));
      } else {
        reviewItems.push(`${formatProjectReviewLocation(institutions[0])} ekspertize konu taşınmaza ait ${projectReference} incelenmiştir.`);
      }
    } else {
      const institutionSummary = normalizeReportTitleText(state.fields.documentReviewInstitution || buildProjectReviewInstitutionSummary()).trim();
      const placeText = institutionSummary ? `${institutionSummary} kurumlarında` : joinTurkishList(institutions.map(formatProjectReviewLocation));
      reviewItems.push(`${placeText} ekspertize konu taşınmaza ait ${projectReference} incelenmiştir.`);
    }
  }

  return normalizeReportDescriptionText(
    [locationLead, dateLead ? `${dateLead}${reviewItems.join(" ")}` : reviewItems.join(" "), oldAdaParcelNote]
      .filter(Boolean)
      .join("\n\n")
  );
}

function buildProjectReviewExplanation() {
  if (!shouldShowArchitecturalProjectFields() && isLandProjectReview()) {
    return buildProjectReviewDescription();
  }
  return normalizeReportDescriptionText(
    [
      buildProjectReviewDescription(),
      buildBuildingFootprintAndEntranceExplanation(),
      buildProjectSuitabilityDescription(),
    ]
      .filter(Boolean)
      .join("\n\n")
  );
}

function buildProjectSuitabilityDescription() {
  const hasDifferentProjects = shouldUseProjectDifferenceComparison();
  const parts = [];

  if (hasDifferentProjects) {
    const titleOk = isProjectSuitabilityOk(state.fields.titleProjectSuitabilityStatus);
    const municipalityOk = isProjectSuitabilityOk(state.fields.municipalityProjectSuitabilityStatus);
    if (titleOk && municipalityOk) {
      const district = normalizeReportTitleText(state.fields.titleDistrict || state.fields.district || "").trim();
      const municipalityText = district ? `${district} Belediyesinde` : "Belediye arşivinde";
      const bothOkVariants = [
        `Webtapu Portalında incelenen mimari proje ve ${municipalityText} incelenen proje karşılaştırıldığında taşınmazın konumunu ve alanını etkileyen herhangi bir farklılık bulunmamaktadır. Taşınmaz incelenen her iki projeye de uygun olarak inşa edilmiştir.`,
        `Webtapu Portalında incelenen mimari proje ile ${municipalityText} incelenen proje karşılaştırıldığında, taşınmazın konumu ve alanını etkileyen bir farklılığa rastlanmamıştır. Taşınmaz, incelenen her iki projeye de uygun şekilde inşa edilmiştir.`,
        `Webtapu Portalında incelenen mimari proje ile ${municipalityText} incelenen proje karşılaştırıldığında, taşınmazın konumu ve alanını etkileyen bir farka rastlanmamıştır. Gayrimenkul, incelenen her iki projeye de uygun şekilde inşa edilmiştir.`,
        `Webtapu Portalı'ndaki mimari proje ile ${municipalityText} incelenen proje karşılaştırıldığında, taşınmazın konum ve alanını etkileyecek bir uyumsuzluk tespit edilmemiştir. Mülk, her iki projeye de uygun olarak inşa edilmiştir.`,
        `Webtapu Portalında yer alan mimari proje ile ${municipalityText} incelenen proje kıyaslandığında, taşınmazın konumu ve alanı bakımından farklılık bulunmamıştır. Söz konusu gayrimenkul, incelenen her iki proje ile de uyumlu şekilde inşa edilmiştir.`,
      ];
      parts.push(bothOkVariants[selectVariant("buildProjectSuitabilityDescription:bothOk", bothOkVariants.length)]);
    } else {
      const titleSentence = buildProjectSuitabilityStatusSentence(
        state.fields.titleProjectSuitabilityStatus,
        state.fields.titleProjectSuitabilityNote,
        state.fields.titleProjectSuitabilitySimpleRepair,
        "Webtapu Portalında incelenen mimari proje yönünden",
      );
      const municipalitySentence = buildProjectSuitabilityStatusSentence(
        state.fields.municipalityProjectSuitabilityStatus,
        state.fields.municipalityProjectSuitabilityNote,
        state.fields.municipalityProjectSuitabilitySimpleRepair,
        "Belediye arşivinde incelenen mimari proje yönünden",
      );
      if (titleSentence) parts.push(titleSentence);
      if (municipalitySentence) parts.push(municipalitySentence);
      if (!parts.length) {
        parts.push(
          "Webtapu Portalında ve belediye arşivinde incelenen mimari projeler arasında vaziyet planı ve kat planı bazında taşınmazın konumunu ve kullanım alanını etkileyen bir farklılık bulunmamaktadır."
        );
      }
    }
  } else {
    const statusSentence = buildProjectSuitabilityStatusSentence(
      state.fields.projectSuitabilityStatus,
      state.fields.projectConformity,
      state.fields.projectSuitabilitySimpleRepair,
      "",
    );
    if (statusSentence) parts.push(statusSentence);
  }

  const mainProjectSuitable = normalizeYesNoChoice(state.fields.mainRealEstateProjectSuitable || "Evet");
  if (mainProjectSuitable === "Hayır") {
    const note = normalizeReportDescriptionText(state.fields.mainRealEstateProjectSuitabilityNote || "").trim();
    parts.push(`Ana gayrimenkul projesine uygunluk yönünden ${note || "uyumsuzluk tespit edilmiştir."}`);
  }

  return normalizeReportDescriptionText(parts.join(" "));
}
registerVariantGroup("buildProjectSuitabilityDescription:bothOk", "Onaylı Projesine Uygunluk — Webtapu/Belediye her ikisi uygun (İmar Durumu)", 5);

