const projectSuitabilityRepairVariants = [
  (repair) => `Basit bir tadilat ile ${repair === "Evet" ? "düzeltilebilir" : "düzeltilemez"} niteliktedir.`,
  (repair) => `Basit bir tadilat uygulanarak ${repair === "Evet" ? "düzeltilebilir" : "düzeltilemez"} durumdadır.`,
  (repair) => `Küçük çaplı bir tadilat ile ${repair === "Evet" ? "giderilebilir" : "giderilemez"} durumdadır.`,
  (repair) => `Basit onarımla ${repair === "Evet" ? "düzeltilmesi mümkündür" : "düzeltilmesi mümkün değildir"}.`,
];
registerVariantGroup("buildProjectSuitabilityStatusSentence:repair", "Onaylı Projesine Uygunluk — Tadilat Notu (İmar Durumu)", projectSuitabilityRepairVariants.length);

function buildProjectSuitabilityStatusSentence(statusValue, noteValue, repairValue, prefix = "") {
  const status = normalizeReportDescriptionText(statusValue || "").trim();
  const statusKey = projectSuitabilityStatusKey(status);
  const note = normalizeReportDescriptionText(noteValue || "").trim();
  const repair = normalizeYesNoChoice(repairValue);
  const lead = prefix ? `${prefix} ` : "";
  let sentence = "";

  let registryKey = statusKey;
  if (registryKey === "") registryKey = "UYGUNDUR";
  if (registryKey === "PROJEYE UYGUNLUK TESPIT EDILEMEMISTIR") registryKey = "PROJEYE UYGUNLUK TESPIT EDILMEMISTIR";
  const variantBuilders = projectSuitabilityStatusVariants[registryKey];
  if (variantBuilders) {
    const variantIndex = selectVariant(`buildProjectSuitabilityStatusSentence:${registryKey}`, variantBuilders.length);
    sentence = variantBuilders[variantIndex](lead);
  } else {
    sentence = `${lead}${status}`;
  }

  const additions = [];
  const acceptsConformityNote = [
    "BLOK BAZINDA KONUM OLARAK UYGUN DEGILDIR",
    "MIMARI OLARAK UYGUN DEGILDIR",
    "KULLANIM ALANI OLARAK UYGUN DEGILDIR",
    "KULLANIM ALANI VE MIMARI OLARAK UYGUN DEGILDIR",
  ].includes(statusKey);
  const cleanNote = stripProjectSuitabilityRepairSentence(note);
  if (acceptsConformityNote && cleanNote) additions.push(cleanNote);
  if (shouldShowProjectSuitabilityRepair(status) && repair) {
    const repairIndex = selectVariant("buildProjectSuitabilityStatusSentence:repair", projectSuitabilityRepairVariants.length);
    additions.push(projectSuitabilityRepairVariants[repairIndex](repair));
  }
  return normalizeReportDescriptionText([sentence, ...additions].filter(Boolean).join(" "));
}

function buildProjectSuitabilityBuildingReferenceSentence(options = {}) {
  if (options.includeWhenPrefixed === false) return "";
  const sentences = [];
  const footprintReference = normalizeReportDescriptionText(state.fields.buildingFootprintReference || "").trim();
  if (footprintReference) {
    sentences.push(`Bina oturumu; vaziyet planında belirtilen ${toLowerText(footprintReference)} referansından tespit edilmiştir.`);
  }

  const entranceLevel = formatProjectSuitabilityEntranceLevel(state.fields.buildingEntranceLevel);
  const entranceDirection = toLowerText(state.fields.buildingEntranceDirection || "");
  if (entranceLevel && entranceDirection) {
    sentences.push(`Bina girişi, projesine göre binanın ${entranceLevel} ve yapının ${entranceDirection} cephesinden sağlanmaktadır.`);
  } else if (entranceLevel) {
    sentences.push(`Bina girişi, projesine göre binanın ${entranceLevel} sağlanmaktadır.`);
  } else if (entranceDirection) {
    sentences.push(`Bina girişi, projesine göre yapının ${entranceDirection} cephesinden sağlanmaktadır.`);
  }
  return sentences.length ? `${sentences.join(" ")} ` : "";
}

function buildBuildingFootprintAndEntranceExplanation() {
  return buildProjectSuitabilityBuildingReferenceSentence().trim();
}

function formatProjectSuitabilityEntranceLevel(value) {
  const text = toLowerText(value || "");
  if (!text) return "";
  if (text.endsWith("katından") || text.endsWith("seviyesinden")) return text;
  if (text.includes("kat")) return `${text}ından`;
  return `${text} katından`;
}

function stripProjectSuitabilityRepairSentence(value = "") {
  return normalizeReportDescriptionText(value || "")
    .replace(/Basit bir tadilat ile\s+(düzeltilebilir|düzeltilemez)\s+niteliktedir\.?/gi, "")
    .replace(/\s{2,}/g, " ")
    .trim();
}

function stripProjectSuitabilityUndeterminedSentence(value = "") {
  return normalizeReportDescriptionText(value || "")
    .replace(/Projeye\s+uygunluk\s+tespit\s+edil(?:e)?mem[iı][şs]t[iı]r\.?/gi, "")
    .replace(/\s{2,}/g, " ")
    .trim();
}

function cleanProjectReviewDescriptionForCurrentSuitability(value = "") {
  const hasDifferentProjects = shouldUseProjectDifferenceComparison();
  const statuses = hasDifferentProjects
    ? [state.fields.titleProjectSuitabilityStatus, state.fields.municipalityProjectSuitabilityStatus]
    : [state.fields.projectSuitabilityStatus];
  const hasUndeterminedStatus = statuses.some(isProjectSuitabilityUndetermined);
  let cleaned = String(value || "");
  if (hasUndeterminedStatus) {
    cleaned = stripProjectSuitabilityUndeterminedSentence(cleaned);
  }
  return normalizeReportDescriptionText(cleaned);
}

function isProjectSuitabilityUndetermined(value) {
  const statusKey = projectSuitabilityStatusKey(value);
  return [
    "PROJEYE UYGUNLUK TESPIT EDILMEMISTIR",
    "PROJEYE UYGUNLUK TESPIT EDILEMEMISTIR",
  ].includes(statusKey)
    || /projeye\s+uygunluk\s+tespit\s+edil(?:e)?mem[iı][şs]t[iı]r\.?/i.test(String(value || ""));
}

function cleanProjectSuitabilityNote(statusValue, value = "") {
  return isProjectSuitabilityUndetermined(statusValue)
    ? stripProjectSuitabilityUndeterminedSentence(value)
    : stripProjectSuitabilityRepairSentence(value);
}

function sanitizeUndeterminedProjectSuitabilityState() {
  const hasDifferentProjects = shouldUseProjectDifferenceComparison();
  const pairs = hasDifferentProjects
    ? [
      ["titleProjectSuitabilityStatus", "titleProjectSuitabilityNote"],
      ["municipalityProjectSuitabilityStatus", "municipalityProjectSuitabilityNote"],
    ]
    : [["projectSuitabilityStatus", "projectConformity"]];
  let changed = false;
  let hasUndeterminedStatus = false;

  pairs.forEach(([statusKey, noteKey]) => {
    if (!isProjectSuitabilityUndetermined(state.fields[statusKey])) return;
    hasUndeterminedStatus = true;
    const cleaned = stripProjectSuitabilityUndeterminedSentence(state.fields[noteKey]);
    if (cleaned === String(state.fields[noteKey] || "")) return;
    state.fields[noteKey] = cleaned;
    changed = true;
  });

  // Eski taslaklarda bu sabit cümle doğrudan üretilmiş açıklama alanına
  // yazılmıştı. Not değişmemiş olsa bile, seçili durum tespit edilememişse
  // rapora girecek kayıtlı metinden de çıkarılır.
  if (hasUndeterminedStatus) {
    const cleanedDescription = cleanProjectReviewDescriptionForCurrentSuitability(state.fields.projectReviewDescription);
    if (cleanedDescription !== String(state.fields.projectReviewDescription || "")) {
      state.fields.projectReviewDescription = cleanedDescription;
      changed = true;
    }
  }

  if (changed && !hasUndeterminedStatus) {
    state.fields.projectReviewDescription = buildProjectReviewExplanation();
  }
  return changed;
}

function buildMissingReviewedDocumentSentences(institutionValue = "") {
  const prefix = buildDocumentArchivePrefix(institutionValue);
  const occupancyPrefix = buildMissingOccupancyPermitArchivePrefix(institutionValue);
  return [
    `${occupancyPrefix} yapılan incelemelerde taşınmaza ait yapı kullanma izin belgesi bulunamamıştır.`,
    `${prefix} yapılan incelemelerde taşınmaza ait yeni yapı ruhsatı bulunamamıştır.`,
  ];
}

// Kullanıcı talebi (2026-08-19, devam): "İncelenen belgeler açıklaması
// ortak olmalı yalnızca bu ortak açıklamada blok bazında ayrım
// gözetilmeli." — `reviewedDocumentsDescription` ZATEN rapor-geneli ortak
// (TITLE_UNIT_SHARED_EXPLANATION_FIELD_KEYS, değişmedi), ama onu üreten
// `buildReviewedDocumentsDescription()` yalnızca AKTİF taşınmazın
// `state.tables.documents`'ını (bir tek bloğun kayıtlarını) okuyordu —
// blok-tab yapısı (0.0.480) devreye girdiğinde bile açıklama metni yalnızca
// hangi taşınmaz aktifse ONUN bloğunu yansıtıyordu. Bu fonksiyon, blok/BB
// tab yapısı aktifken (isDocumentsBlockGroupingActive) TÜM bloklardan
// (her bloğun temsilci/ilk üyesinin tablosu — bloktaki tüm üyeler zaten
// syncDocumentsSharedDataToBlockSiblings ile senkron) kayıt toplar; aksi
// halde (kat irtifakı dışı / tek blok / tekil taşınmaz) DAVRANIŞ AYNEN
// KORUNUR (yalnızca aktif taşınmazın tablosu, blok etiketi YOK).
function collectDocumentsDescriptionRowGroups() {
  if (!isDocumentsBlockGroupingActive()) {
    return [{ blockLabel: null, rows: state.tables?.documents || [] }];
  }
  const units = buildAllTitleUnitsForSummaryTable();
  const groups = computeDocumentsBlockGroups(units);
  return groups.map((group) => ({
    blockLabel: computeDocumentsBlockLabel(group, groups),
    rows: units[group.unitIndices[0]]?.tables?.documents || [],
  }));
}

// "A Blok"/"B Blok" gibi " Blok" ekiyle biten etiketlerden ayırt edici
// kısmı ("A"/"B") çıkarır — birden fazla bloğun AYNI belgeyi paylaştığı
// durumda "A ve B Blok'a ait" gibi TEK "Blok" kelimesiyle birleştirilmiş
// bir ifade kurabilmek için (kullanıcı örneği: "A ve B Bloka ait ...").
// 2026-08-19 DÜZELTME: kullanıcı taşınmazın "Blok" alanına (titleBlockName)
// yalnızca "A" gibi TEK harf/kısa ad girdiğinde ("A Blok" DEĞİL) çıktı
// "A'ya ait" oluyordu — "Blok" kelimesi TAMAMEN kayboluyordu (kullanıcı
// bildirimi: "A Blok olacak sadece Blok harfi olmayacak"). Artık etiket
// zaten "...Blok" ile bitiyorsa o kısım TEKRARLANMADAN kullanılır, AKSİ
// HALDE ham etiketin kendisi "Blok" kelimesinin ÖNÜNE eklenir — sonuç HER
// ZAMAN "{ad} Blok'a ait" olur, etiketin kendisinde "Blok" kelimesi olsun
// ya da olmasın.
function normalizeBlockLabelPrefixForAttribution(label) {
  const trimmed = String(label || "").trim();
  if (!trimmed) return "";
  const match = trimmed.match(/^(.*?)\s*Blok$/i);
  const stripped = match ? match[1].trim() : "";
  return stripped || trimmed;
}

// Bir belgeye "sahip" bloklardan (etiket dizisi, GÖRÜNÜM SIRASINA göre
// zaten sıralanmış) okunabilir, HER ZAMAN "Blok" kelimesini içeren bir
// "X Blok'a ait"/"X ve Y Blok'a ait" ifadesi kurar.
function formatDocumentBlockAttributionPhrase(blockLabels) {
  const prefixes = (blockLabels || []).filter(Boolean).map(normalizeBlockLabelPrefixForAttribution).filter(Boolean);
  if (!prefixes.length) return "";
  return `${joinTurkishList(prefixes)} Blok'a ait`;
}

// Bir arşiv-önek (kurum/tarih) grubu içindeki belge referanslarını
// (bkz. formatReviewedDocumentReference) blok etiketine göre gruplar:
// AYNI blok(lar)dan gelen TÜM referanslar TEK bir "X Blok'a ait ..., ..."
// öbeğinde birleşir; birden fazla bloğun BİREBİR AYNI referansı varsa
// (aynı tarih+no+tür) TEK bir "A ve B Blok'a ait ..." öbeğinde toplanır
// (kullanıcının "ortak olarak cümle kurulabilir" örneği). Blok etiketi
// hiç YOKSA (isDocumentsBlockGroupingActive false) ESKİ/DEĞİŞMEYEN
// davranış: referanslar düz joinTurkishList ile birleştirilir.
function buildDocumentsPermitGroupPhrase(items, blockOrder) {
  const hasAnyBlockLabel = items.some((item) => item.blockLabel);
  if (!hasAnyBlockLabel) {
    return joinTurkishList(items.map((item) => item.referenceText));
  }

  const labelsByReference = new Map();
  const referenceOrder = [];
  items.forEach(({ referenceText, blockLabel }) => {
    if (!labelsByReference.has(referenceText)) {
      labelsByReference.set(referenceText, new Set());
      referenceOrder.push(referenceText);
    }
    if (blockLabel) labelsByReference.get(referenceText).add(blockLabel);
  });

  const sortByBlockOrder = (labels) => labels.slice().sort((a, b) => (blockOrder.get(a) ?? 0) - (blockOrder.get(b) ?? 0));

  const groupsByAttribution = new Map();
  const attributionOrder = [];
  referenceOrder.forEach((referenceText) => {
    const labels = sortByBlockOrder(Array.from(labelsByReference.get(referenceText)));
    const key = labels.join("||");
    if (!groupsByAttribution.has(key)) {
      groupsByAttribution.set(key, { labels, references: [] });
      attributionOrder.push(key);
    }
    groupsByAttribution.get(key).references.push(referenceText);
  });

  return attributionOrder
    .map((key) => {
      const { labels, references } = groupsByAttribution.get(key);
      const attribution = formatDocumentBlockAttributionPhrase(labels);
      const referenceList = references.join(", ");
      return attribution ? `${attribution} ${referenceList}` : referenceList;
    })
    .join(", ");
}

// Kullanıcı talebi (2026-08-19, devam): "eğer bir blok için yapı kullanma
// izin belgesi eklenmedi ise bu blokun yapı kullanma izin belgesinin
// bulunamadığı açıklamada belirtilmeli. aynı mantıkta eğer A ve B blokta
// var ise yapı kullanma izin belgesi açıklama girilmeli. C ve D Blokta
// yok ise 'Ekspertize konu taşınmazların yer aldığı C ve D Bloka ait yapı
// kullanma izin belgesi bulunamamıştır.' cümlesi ... gelmeli." — ruhsat
// (permit-like) belgelerdeki AYNI blok-bazlı mantık (bkz.
// buildDocumentsPermitGroupPhrase) İSKAN/yapı kullanma izin belgesine de
// uygulanır: HER blok ayrı ayrı "bulundu mu" diye kontrol edilir — bulunan
// bloklar (varsa) block-etiketli/birleştirilmiş "incelenmiştir" cümle(leri)
// üretir (ruhsatla BİREBİR aynı `buildDocumentsPermitGroupPhrase` yeniden
// kullanılır), bulunamayan bloklar TEK bir birleştirilmiş "Ekspertize konu
// taşınmazların yer aldığı {bloklar} yapı kullanma izin belgesi
// bulunamamıştır." cümlesinde toplanır (formatDocumentBlockAttributionPhrase
// ile AYNI birleştirme). Blok gruplama AKTİF DEĞİLSE (kat irtifakı dışı/
// tek blok/tekil taşınmaz) davranış AYNEN korunur — her satır kendi
// (mevcut, değiştirilmeyen) cümlesini üretir, hiçbiri yoksa TEK genel
// "bulunamamıştır" cümlesi (buildOccupancyPermitDocumentSentence({})).
function buildDocumentsOccupancyParts(rowGroups, rows, blockOrder) {
  if (!isDocumentsBlockGroupingActive()) {
    const occupancyTexts = rows.filter((row) => isOccupancyPermitDocument(row.type)).map((row) => buildOccupancyPermitDocumentSentence(row));
    return occupancyTexts.length ? occupancyTexts : [buildOccupancyPermitDocumentSentence({})];
  }

  const foundGroups = new Map();
  const missingBlockLabels = [];
  rowGroups.forEach((group) => {
    const validRows = rows.filter((row) => row.blockLabel === group.blockLabel && isOccupancyPermitDocument(row.type) && row.date && row.no);
    if (!validRows.length) {
      missingBlockLabels.push(group.blockLabel);
      return;
    }
    validRows.forEach((row) => {
      const prefix = buildDocumentArchivePrefix(row.institution);
      if (!foundGroups.has(prefix)) foundGroups.set(prefix, []);
      foundGroups.get(prefix).push({ referenceText: formatReviewedDocumentReference(row), blockLabel: row.blockLabel });
    });
  });

  const parts = [];
  foundGroups.forEach((items, prefix) => {
    parts.push(`${prefix} yer alan ${buildDocumentsPermitGroupPhrase(items, blockOrder)} incelenmiştir.`);
  });
  if (missingBlockLabels.length) {
    const sortedMissingLabels = missingBlockLabels.slice().sort((a, b) => (blockOrder.get(a) ?? 0) - (blockOrder.get(b) ?? 0));
    const attribution = formatDocumentBlockAttributionPhrase(sortedMissingLabels);
    parts.push(`Ekspertize konu taşınmazların yer aldığı ${attribution} yapı kullanma izin belgesi bulunamamıştır.`);
  }
  return parts;
}

function buildReviewedDocumentsDescription() {
  const rowGroups = collectDocumentsDescriptionRowGroups();
  const blockOrder = new Map(rowGroups.map((group, index) => [group.blockLabel, index]));
  const rows = rowGroups.flatMap((group) => (
    getReviewedDocumentChronologicalEntries(group.rows)
      .map(({ row }) => ({ ...normalizeReviewedDocumentRow(row), blockLabel: group.blockLabel }))
  )).filter((row) => row.type);
  const ekbExplanation = buildEkbExplanation();
  if (!rows.length) {
    return normalizeReportDescriptionText([...buildMissingReviewedDocumentSentences(), ekbExplanation].filter(Boolean).join("\n\n"));
  }

  const permitGroups = new Map();

  rows.forEach((row) => {
    if (isOccupancyPermitDocument(row.type)) return;
    if (isPermitLikeDocument(row.type) && row.date && row.no) {
      const prefix = buildDocumentArchivePrefix(row.institution);
      if (!permitGroups.has(prefix)) permitGroups.set(prefix, []);
      permitGroups.get(prefix).push({ referenceText: formatReviewedDocumentReference(row), blockLabel: row.blockLabel });
    }
  });

  const parts = [];
  if (permitGroups.size) {
    permitGroups.forEach((permitItems, prefix) => {
      parts.push(`${prefix} yer alan ${buildDocumentsPermitGroupPhrase(permitItems, blockOrder)} incelenmiştir.`);
    });
  } else {
    const prefix = buildDocumentArchivePrefix();
    parts.push(`${prefix} yapılan incelemelerde taşınmaza ait yeni yapı ruhsatı bulunamamıştır.`);
  }
  parts.push(...buildDocumentsOccupancyParts(rowGroups, rows, blockOrder));
  if (ekbExplanation) parts.push(ekbExplanation);

  return normalizeReportDescriptionText(parts.join("\n\n"));
}

function splitReviewedDocumentsDescriptionsIfNeeded() {
  const generatedProjectText = buildProjectReviewExplanation();
  const ekbExplanation = buildEkbExplanation();
  let changed = false;

  if (generatedProjectText && !String(state.fields.projectReviewDescription || "").trim()) {
    state.fields.projectReviewDescription = generatedProjectText;
    changed = true;
  }

  const currentDocumentsText = normalizeReportDescriptionText(state.fields.reviewedDocumentsDescription || "").trim();
  if (generatedProjectText && currentDocumentsText && currentDocumentsText.includes(generatedProjectText)) {
    const nextDocumentsText = normalizeReportDescriptionText(
      currentDocumentsText
        .replace(generatedProjectText, "")
        .replace(/^\s*[\r\n]+/, "")
        .replace(/[\r\n]+\s*$/, "")
    ) || buildReviewedDocumentsDescription();
    if (nextDocumentsText !== state.fields.reviewedDocumentsDescription) {
      state.fields.reviewedDocumentsDescription = nextDocumentsText;
      changed = true;
    }
  } else if (currentDocumentsText && ekbExplanation && !currentDocumentsText.includes(ekbExplanation)) {
    const withoutLegacyEkb = stripEkbExplanationFromReviewedDocumentsText(currentDocumentsText);
    const nextDocumentsText = normalizeReportDescriptionText([withoutLegacyEkb, ekbExplanation].filter(Boolean).join("\n\n"));
    if (nextDocumentsText !== state.fields.reviewedDocumentsDescription) {
      state.fields.reviewedDocumentsDescription = nextDocumentsText;
      changed = true;
    }
  } else if (!currentDocumentsText) {
    const generatedDocumentsText = buildReviewedDocumentsDescription();
    if (generatedDocumentsText) {
      state.fields.reviewedDocumentsDescription = generatedDocumentsText;
      changed = true;
    }
  }

  return changed;
}

function stripEkbExplanationFromReviewedDocumentsText(value = "") {
  return normalizeReportDescriptionText(value || "")
    .replace(/Enerji Kimlik Belgesinin son geçerlilik tarihi sona erdiği için dikkate alınmamıştır\.?/gi, "")
    .replace(/(?:İnceleme tarihinde|\d{2}\.\d{2}\.\d{4}\s+tarihinde) taşınmaza ait(?:\s+veriliş tarihi\s+\d{2}\.\d{2}\.\d{4}(?:\s+tarihli)?(?:,\s+geçerlilik tarihi\s+\d{2}\.\d{2}\.\d{4}(?:\s+tarihli)?)?)?(?:\s+olan)?\s+Enerji Kimlik Belgesi incelenmiştir\.\s*Enerji Kimlik Belgesinin son geçerlilik tarihi sona erdiği için değerleme raporunda dikkate alınmamıştır\.?/gi, "")
    .replace(/(?:İnceleme tarihinde|\d{2}\.\d{2}\.\d{4}\s+tarihinde) EKB sistemi, E Devlet, resmi kurumlar ve saha araştırması sonucunda taşınmaza ait Enerji Kimlik Belgesi bulunamamıştır\.?/gi, "")
    .trim();
}

function normalizeReviewedDocumentRow(row = {}) {
  const migrated = normalizeReviewedDocumentStorageRow(row);
  return {
    type: normalizeReportTitleText(migrated.c0 || "").trim(),
    institution: normalizeDocumentInstitutionText(migrated.c1 || buildDefaultDocumentReviewInstitution() || ""),
    date: dateIsoToTr(migrated.c2 || "").trim(),
    no: String(migrated.c3 || "").trim(),
    scope: normalizeReviewedDocumentScope(migrated.c4 || ""),
  };
}

function getReviewedDocumentChronologicalEntries(rows = state.tables?.documents || []) {
  return (Array.isArray(rows) ? rows : [])
    .map((row, index) => ({
      row,
      index,
      date: parseReviewedDocumentDate(row?.c2),
    }))
    .sort((left, right) => {
      if (left.date && right.date && left.date !== right.date) return left.date.localeCompare(right.date);
      if (left.date && !right.date) return -1;
      if (!left.date && right.date) return 1;
      return left.index - right.index;
    });
}

function getArchitecturalProjectReviewedDocumentRows() {
  if (normalizeYesNoChoice(state.fields.hasArchitecturalProject || "Evet") === "Hayır") return [];

  const createProjectRow = (projectType, date, no, institution) => {
    if (![projectType, date, no].some((value) => String(value || "").trim())) return null;
    return {
      c0: String(projectType || "Onaylı Mimari Projesi").trim(),
      c1: String(institution || "").trim(),
      c2: String(date || "").trim(),
      c3: String(no || "").trim(),
      c4: String(projectType || "Mimari Proje").trim(),
    };
  };

  if (shouldUseProjectDifferenceComparison()) {
    return [
      createProjectRow(
        state.fields.titleProjectType,
        state.fields.titleProjectDate,
        state.fields.titleProjectNo,
        formatProjectInstitutionForSummary("Webtapu"),
      ),
      createProjectRow(
        state.fields.municipalityProjectType,
        state.fields.municipalityProjectDate,
        state.fields.municipalityProjectNo,
        formatProjectInstitutionForSummary("Belediye"),
      ),
    ].filter(Boolean);
  }

  return [createProjectRow(
    state.fields.projectType,
    state.fields.projectDate,
    state.fields.projectNo,
    normalizeDocumentInstitutionText(state.fields.documentReviewInstitution || buildProjectReviewInstitutionSummary()),
  )].filter(Boolean);
}

function getReviewedDocumentTableEntries(rows = state.tables?.documents || []) {
  const documentEntries = getReviewedDocumentChronologicalEntries(rows);
  const projectEntries = getArchitecturalProjectReviewedDocumentRows().map((row, index) => ({
    row,
    index: documentEntries.length + index,
    isArchitecturalProject: true,
    date: parseReviewedDocumentDate(row.c2),
  }));

  return [...documentEntries, ...projectEntries]
    .sort((left, right) => {
      if (left.date && right.date && left.date !== right.date) return left.date.localeCompare(right.date);
      if (left.date && !right.date) return -1;
      if (!left.date && right.date) return 1;
      return left.index - right.index;
    });
}

function hasReviewedDocumentInfo() {
  return (state.tables.documents || [])
    .map(normalizeReviewedDocumentRow)
    .some((row) => row.type);
}

function canEditBuildingAgeManually() {
  return true;
}

function hasManualBuildingAgeOverride() {
  return state.fields.buildingAgeManualOverride === true;
}

function isFieldReadOnly(field = {}) {
  if (field.key === "buildingAge" && canEditBuildingAgeManually()) return false;
  if (field.adminEditableOnly) return !isCurrentUserAdmin();
  return Boolean(field.readOnly);
}

function refreshBuildingCompletionFromCurrentFields() {
  const result = calculateBuildingCompletionFromReviewedDocuments();
  const previousBuildingAge = state.fields.buildingAge || "";
  state.fields.buildingCompletionDate = result.displayDate;
  state.fields.buildingConstructionYear = calculateConstructionYearText(result.isoDate);
  state.fields.buildingAge = hasManualBuildingAgeOverride() ? previousBuildingAge : calculateBuildingAgeText(result.isoDate);
  state.fields.buildingCompletionExplanation = buildBuildingCompletionExplanation(result);
  refreshUnitFirstSaleStatusFromCurrentFields();
  refreshBuildingDepreciationFromCurrentFields();
  ["buildingCompletionDate", "buildingConstructionYear", "buildingAge", "buildingCompletionExplanation"].forEach((key) => {
    const control = document.querySelector(`[data-field="${key}"]`);
    if (control && control.value !== (state.fields[key] || "")) {
      control.value = state.fields[key] || "";
    }
  });
}

function calculateBuildingCompletionFromReviewedDocuments() {
  const rows = (state.tables.documents || []).map(normalizeReviewedDocumentRow).filter((row) => row.type);
  const occupancyRow = rows.find((row) => isBuildingCompletionOccupancyDocument(row.type) && parseReviewedDocumentDate(row.date));
  if (occupancyRow) {
    const isoDate = parseReviewedDocumentDate(occupancyRow.date);
    return {
      source: "occupancy",
      isoDate,
      displayDate: dateIsoToTr(isoDate),
      documentType: occupancyRow.type,
    };
  }

  const permitRows = rows
    .map((row) => ({
      ...row,
      isoDate: isBuildingCompletionPermitDocument(row.type) ? parseReviewedDocumentDate(row.date) : "",
    }))
    .filter((row) => row.isoDate)
    .sort((a, b) => b.isoDate.localeCompare(a.isoDate));
  if (permitRows.length) {
    const latestPermit = permitRows[0];
    const completionIso = addYearsToIsoDate(latestPermit.isoDate, 2);
    return {
      source: "permit",
      isoDate: completionIso,
      displayDate: dateIsoToTr(completionIso),
      documentType: latestPermit.type,
      permitDate: dateIsoToTr(latestPermit.isoDate),
    };
  }

  return {
    source: "unknown",
    isoDate: "",
    displayDate: "Belirsiz",
    documentType: "",
  };
}

function isBuildingCompletionOccupancyDocument(value) {
  const text = foldTurkish(value || "").toLocaleUpperCase("tr");
  return text.includes("ISKAN")
    || text.includes("KULLANMA")
    || text.includes("KULLANIM")
    || text.includes("OTURMA");
}

function isBuildingCompletionPermitDocument(value) {
  return foldTurkish(value || "").toLocaleUpperCase("tr").includes("RUHSAT");
}

function parseReviewedDocumentDate(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  const iso = dateTrToIso(text) || (/^\d{4}-\d{2}-\d{2}$/.test(text) ? text : "");
  return iso;
}

function addYearsToIsoDate(value, years) {
  const match = String(value || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return "";
  const date = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
  date.setFullYear(date.getFullYear() + years);
  return [
    date.getFullYear(),
    String(date.getMonth() + 1).padStart(2, "0"),
    String(date.getDate()).padStart(2, "0"),
  ].join("-");
}

function calculateBuildingAgeText(completionIsoDate) {
  const match = String(completionIsoDate || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return "";
  const completionDate = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
  const today = new Date();
  const diffYears = (today.getTime() - completionDate.getTime()) / (365.25 * 24 * 60 * 60 * 1000);
  return `${Math.max(0, Math.round(diffYears)).toLocaleString("tr-TR")} yıl`;
}

function calculateConstructionYearText(completionIsoDate) {
  const match = String(completionIsoDate || "").match(/^(\d{4})-\d{2}-\d{2}$/);
  return match ? match[1] : "";
}

// Varyantlar docs/cumle-envanteri.md Bölüm 4'te belgelendi (HER raporda
// çıkan bir açıklama — iskan var/yok/tarih tespit edilemedi 3 alt-durumu).
registerVariantGroup("buildBuildingCompletionExplanation:no-date", "Yapı Bitiş Tarihi — Tarih Tespit Edilemedi (Ana Gayrimenkul)", 2);
registerVariantGroup("buildBuildingCompletionExplanation:occupancy", "Yapı Bitiş Tarihi — İskan Var (Ana Gayrimenkul)", 2);
registerVariantGroup("buildBuildingCompletionExplanation:permit-plus-2y", "Yapı Bitiş Tarihi — İskan Yok, Ruhsat+2 Yıl (Ana Gayrimenkul)", 2);

function buildBuildingCompletionExplanation(result = calculateBuildingCompletionFromReviewedDocuments()) {
  if (!result.isoDate) {
    const variants = [
      "İncelenen belgeler içerisinde yapı kullanma izin belgesi/iskan veya ruhsat tarihi tespit edilemediğinden yapı bitiş tarihi belirsizdir.",
      "İncelenen belgeler içerisinde yapı kullanma izin belgesi/iskan veya ruhsat tarihine rastlanmadığından yapı bitiş tarihi belirsiz kalmıştır.",
    ];
    return variants[selectVariant("buildBuildingCompletionExplanation:no-date", variants.length)];
  }
  const ageText = calculateBuildingAgeText(result.isoDate);
  if (result.source === "occupancy") {
    const variants = [
      `İncelenen belgeler içerisinde yer alan ${result.documentType} tarihine göre yapı bitiş tarihi ${result.displayDate} olarak alınmıştır.${ageText ? ` Buna göre yapı yaşı ${ageText} olarak hesaplanmıştır.` : ""}`,
      `İncelenen belgeler arasında yer alan ${result.documentType} tarihi esas alındığında yapı bitiş tarihinin ${result.displayDate} olduğu belirlenmiştir.${ageText ? ` Bu doğrultuda yapı yaşı ${ageText} olarak hesaplanmıştır.` : ""}`,
    ];
    return variants[selectVariant("buildBuildingCompletionExplanation:occupancy", variants.length)];
  }
  const variants = [
    `İncelenen belgeler içerisinde yapı kullanma izin belgesi/iskan bulunmadığından, en son ruhsat tarihi olan ${result.permitDate} tarihine 2 yıl eklenerek yapı bitiş tarihi ${result.displayDate} olarak alınmıştır.${ageText ? ` Buna göre yapı yaşı ${ageText} olarak hesaplanmıştır.` : ""}`,
    `İncelenen belgeler arasında yapı kullanma izin belgesi/iskan bulunmadığından, mevcut en son ruhsat tarihi olan ${result.permitDate} üzerine 2 yıl eklenmek suretiyle yapı bitiş tarihi ${result.displayDate} olarak kabul edilmiştir.${ageText ? ` Buna göre yapı yaşı ${ageText} olarak hesaplanmıştır.` : ""}`,
  ];
  return variants[selectVariant("buildBuildingCompletionExplanation:permit-plus-2y", variants.length)];
}

function normalizeReviewedDocumentStorageRow(row = {}) {
  const c1LooksLikeDate = looksLikeReviewedDocumentDate(row.c1);
  const c2LooksLikeInstitution = looksLikeDocumentInstitution(row.c2);
  if (c1LooksLikeDate && c2LooksLikeInstitution) {
    return {
      c0: row.c0 || "",
      c1: row.c2 || "",
      c2: row.c1 || "",
      c3: row.c3 || "",
      c4: row.c4 || "",
    };
  }
  if (row.c4 !== undefined && String(row.c1 || "").trim()) return row;
  const c1LooksLikeInstitution = looksLikeDocumentInstitution(row.c1);
  if (!c1LooksLikeDate && c1LooksLikeInstitution) return row;
  return {
    c0: row.c0 || "",
    c1: buildDefaultDocumentReviewInstitution(),
    c2: row.c1 || "",
    c3: row.c2 || "",
    c4: row.c3 || "",
  };
}

function looksLikeReviewedDocumentDate(value = "") {
  const text = String(value || "").trim();
  return /^\d{4}-\d{2}-\d{2}$/.test(text) || /^\d{1,2}(?:[.]|\/|-)\d{1,2}(?:[.]|\/|-)\d{2,4}$/.test(text);
}

function looksLikeDocumentInstitution(value = "") {
  const folded = foldTurkish(value || "");
  return /BELEDIYE|BAKANLIK|BAKANLIGI|IDARE|BUYUKSEHIR|OZEL|WEBTAPU|OSB|MUDURLUGU/.test(folded);
}

function normalizeDocumentInstitutionText(value = "") {
  const raw = String(value || "").replace(/\s+/g, " ").trim();
  if (!raw) return "";
  const folded = foldTurkish(raw);
  if (/CEVRE\s+VE\s+SEHIRCILIK\s+BAKANLIGI/.test(folded)) {
    return "T.C. Çevre ve Şehircilik Bakanlığı";
  }
  if (/OSB\s+BOLGE\s+MUDURLUGU/.test(folded)) {
    return "OSB Bölge Müdürlüğü";
  }
  return normalizeReportTitleText(raw)
    .replace(/\bT\.c\./g, "T.C.")
    .replace(/\bA\.ş\./g, "A.Ş.")
    .replace(/\bT\.a\.o\./g, "T.A.O.")
    .replace(/\bVe\b/g, "ve")
    .replace(/\bOsb\b/g, "OSB")
    .trim();
}

function isPermitLikeDocument(type) {
  const folded = foldTurkish(type);
  return /RUHSAT/.test(folded) || /YAPI\s*KAYIT\s*BELGESI/.test(folded);
}

function isOccupancyPermitDocument(type) {
  return isBuildingCompletionOccupancyDocument(type);
}

// Vakıf Katılım "İncelenen Belgeler" ekranı üç ayrı belge sütunu ister:
// yapı kullanma izin belgesi (iskan), EN YENİ yapı ruhsatı ve tasdikli
// mimari proje.
//
// Kaynak olarak getReviewedDocumentTableEntries() kullanılır — düz
// state.tables.documents DEĞİL. Sebebi: mimari proje satırı kullanıcı
// tarafından girilmez, getArchitecturalProjectReviewedDocumentRows()
// tarafından tapu/belediye proje alanlarından ÜRETİLİR ve yalnızca bu
// birleşik listede yer alır. Yalnızca documents okunduğunda "Tasdikli
// Mimari Projesi" sütunu boş kalıyordu (kullanıcı bildirimi).
// Liste eskiden yeniye sıralı olduğu için SON eşleşme en yeni kayıttır.
function findReviewedDocumentRowBy(predicate, { newest = true } = {}) {
  const matches = getReviewedDocumentTableEntries()
    .filter((entry) => predicate(String(entry.row?.c0 || "")));
  if (!matches.length) return null;
  return (newest ? matches[matches.length - 1] : matches[0]).row;
}

function getLatestBuildingPermitDocumentRow() {
  return findReviewedDocumentRowBy((type) => isPermitLikeDocument(type) && !isOccupancyPermitDocument(type));
}

function getOccupancyPermitDocumentRow() {
  return findReviewedDocumentRowBy((type) => isOccupancyPermitDocument(type));
}

function getArchitecturalProjectDocumentRow() {
  return findReviewedDocumentRowBy((type) => /PROJE/.test(foldTurkish(type)));
}

// Şablon yer tutucuları için tarih (gün.ay.yıl) ve belge no okuyucuları.
function reviewedDocumentDateText(row) {
  return row ? dateIsoToTr(String(row.c2 || "").trim()) : "";
}

function reviewedDocumentNoText(row) {
  return row ? String(row.c3 || "").trim() : "";
}

// "İncelendiği Kurum" sütunu yalnızca BELEDİYE olmalı (kullanıcı talimatı).
// Belge satırının kurumu "Webtapu Portalı ve X Belediyesi" gibi birleşik
// olabiliyor; bu durumda sadece belediye parçası alınır. Kurum hiç yoksa ya
// da yalnızca Webtapu ise ilçeden varsayılan belediye adı üretilir.
function municipalityOnlyInstitution(value) {
  const text = String(value || "").trim();
  if (!text) return buildDefaultDocumentReviewInstitution();
  const municipality = text
    .split(/\s+ve\s+/i)
    .map((part) => part.trim())
    .filter(Boolean)
    .find((part) => foldTurkish(part).includes("BELEDIYE"));
  if (municipality) return municipality;
  if (foldTurkish(text).includes("WEBTAPU")) return buildDefaultDocumentReviewInstitution();
  return text;
}

function reviewedDocumentInstitutionText(row) {
  return municipalityOnlyInstitution(row ? row.c1 : "");
}

// Yapı kullanma izin belgesi (iskan) ve yapı ruhsatı sütunları İncelenen
// Belgeler tablosundaki kendi satırlarından gelir ve belediyeye indirgenir.
function getOccupancyPermitInstitutionText() { return reviewedDocumentInstitutionText(getOccupancyPermitDocumentRow()); }
function getLatestBuildingPermitInstitutionText() { return reviewedDocumentInstitutionText(getLatestBuildingPermitDocumentRow()); }

// Mimari proje sütunu FARKLI: kurum indirgenmez, proje inceleme kurumu olarak
// hangileri seçildiyse hepsi yazılır (Belediye + Webtapu seçiliyse ikisi de).
// buildProjectReviewInstitutionSummary bu birleşimi zaten üretiyor.
function getArchitecturalProjectInstitutionText() {
  const summary = String(buildProjectReviewInstitutionSummary() || "").trim();
  if (summary) return summary;
  const row = getArchitecturalProjectDocumentRow();
  return row ? String(row.c1 || "").trim() : "";
}

// "Kullanım Türü" sütunu: blokta hangi nitelikler var? Kat dağılımı
// tablosundaki (state.tables.buildingFloors) daire/dükkan/ofis/depo adetleri
// toplanır. Yalnızca daire varsa "Mesken"; dükkan veya ofis de varsa
// "Mesken ve İşyeri" biçiminde birleşik yazılır (kullanıcı talimatı).
function getBuildingUsageTypesText() {
  const rows = Array.isArray(state.tables?.buildingFloors) ? state.tables.buildingFloors : [];
  const totals = { residential: 0, shop: 0, office: 0, storage: 0 };
  rows.forEach((row) => {
    Object.keys(totals).forEach((key) => {
      totals[key] += parseBuildingFloorCount(row?.[key]) || 0;
    });
  });
  const labels = [];
  if (totals.residential) labels.push("Mesken");
  if (totals.shop || totals.office) labels.push("İşyeri");
  if (totals.storage) labels.push("Depo");
  if (!labels.length) return "";
  if (labels.length === 1) return labels[0];
  return `${labels.slice(0, -1).join(", ")} ve ${labels[labels.length - 1]}`;
}

// Kullanıcı talebi (Vakıfbank şablonu ek alanlar, 2026-08-07): "Mesken
// Kullanım Durumu (Ana gayrimenkulde mesken kullanımı var mı?) eğer ana
// gayrimenkulde yer alan katlardan herhangi birinde en az 1 daire var ise
// Evet" — getBuildingUsageTypesText() ile AYNI kaynak veriyi (state.tables.
// buildingFloors) kullanır, ama açıklayıcı metin yerine Evet/Hayır döner.
function getResidentialUsagePresentText() {
  const rows = Array.isArray(state.tables?.buildingFloors) ? state.tables.buildingFloors : [];
  const totalResidential = rows.reduce((sum, row) => sum + (parseBuildingFloorCount(row?.residential) || 0), 0);
  return totalResidential > 0 ? "Evet" : "Hayır";
}

// Kullanıcı talebi: "Karma Yapı Var mı? (Evet/Hayır) Bölge Yapılaşma Kul.
// Amacı zemin ve normal kat konut ise hayır diğer seçenekler evet" —
// regionUsePurpose (çoklu seçim) SADECE "zemin ve normal katları konut"
// tek başına seçiliyse "Hayır", başka HERHANGİ bir seçim (tek başına veya
// birlikte) varsa "Evet"; hiç seçim yoksa boş (henüz cevaplanmamış).
function getMixedUseBuildingText() {
  const selected = getMultiCheckboxValues("regionUsePurpose", { options: regionUsePurposeOptions });
  if (!selected.length) return "";
  return selected.length === 1 && selected[0] === "zemin ve normal katları konut" ? "Hayır" : "Evet";
}

// Değerler ekranindaki "İnşaa Seviyesi" hücresi: yapı %100 tamamlanmışsa
// natamam satırları anlamsız olduğu için hücre BOŞ bırakılır (kullanıcı
// talimatı). Yalnızca gerçekten inşa halindeyken (< %100) yazılır.
function getIncompleteConstructionLevelText() {
  const raw = String(state.fields?.unitConstructionLevel ?? "").trim();
  if (!raw) return "";
  const level = parseValuationNumber(raw);
  if (Number.isFinite(level) && level >= 100) return "";
  return `İnşaa Seviyesi: ${raw} %`;
}

function getLatestBuildingPermitDateText() { return reviewedDocumentDateText(getLatestBuildingPermitDocumentRow()); }
function getLatestBuildingPermitNoText() { return reviewedDocumentNoText(getLatestBuildingPermitDocumentRow()); }
function getOccupancyPermitNoText() { return reviewedDocumentNoText(getOccupancyPermitDocumentRow()); }
function getArchitecturalProjectDateText() { return reviewedDocumentDateText(getArchitecturalProjectDocumentRow()); }
function getArchitecturalProjectNoText() { return reviewedDocumentNoText(getArchitecturalProjectDocumentRow()); }

// Kullanıcı talebi: Halkbank'ın kendi sistemindeki "Ruhsat Özellikleri ve
// Dosya İncelemeleri" ekranında ~21 alan varken bizim şablonumuzda yalnızca
// 4 satır vardı. Aşağıdaki yardımcılar, kullanıcının belirttiği türetme
// kurallarına göre bu eksik alanları MEVCUT verilerden (İncelenen Belgeler
// tablosu, proje türü, randevu türü, bağımsız bölüm kullanım durumu, proje
// uygunluk durumu) hesaplar — yeni bir manuel giriş alanı EKLENMEDİ.
function getReviewedBuildingPermitAvailabilityText() {
  return getLatestBuildingPermitDocumentRow() ? "Var" : "Yok";
}

function getLatestRenovationPermitDocumentRow() {
  return findReviewedDocumentRowBy(
    (type) =>
      isPermitLikeDocument(type) &&
      !isOccupancyPermitDocument(type) &&
      !/YENI\s*YAPI\s*RUHSATI/.test(foldTurkish(type))
  );
}
function getLatestRenovationPermitDateText() {
  return reviewedDocumentDateText(getLatestRenovationPermitDocumentRow());
}

function isKatIrtifakiProjectReviewed() {
  return [state.fields.projectType, state.fields.titleProjectType, state.fields.municipalityProjectType].includes(
    "Kat İrtifakı Projesi"
  );
}
function getKatIrtifakiProjectReviewedText() {
  return isKatIrtifakiProjectReviewed() ? "Evet" : "Hayır";
}

function getUnitLeaseAgreementStatusText() {
  return state.fields.unitUsageStatus === "Kiracı" ? "Evet" : "Hayır";
}

function getUnitActivelyUsedStatusText() {
  const status = state.fields.unitUsageStatus || "";
  const isVacant = status === "Boş (Hiç Kullanılmamış)" || status === "Boş (Kullanılmış)";
  return isVacant ? "Hayır" : "Evet";
}

// Kullanıcı talebi (Emlak Katılım şablonu, "5.5. Kira Kabiliyeti"):
// "eğer kullanım durumu kiracı değil ise cevap hayır, kontrat tarihi aidat
// ve kira değeri kısımlarını boş bırak" — kullanım durumu Kiracı DEĞİLSE
// hem "Daire İçinde Kiracı" hem "Kiracının Kontratı" VAR/YOK sorularının
// ikisi de "YOK" olur; Kiracı İSE kiracı varlığı "VAR" olur ama kontrat
// bilgisi sistemde tutulmadığından boş bırakılır (elle doldurulur).
function isUnitTenantOccupied() {
  return state.fields.unitUsageStatus === "Kiracı";
}
function getUnitTenantPresenceText() {
  return isUnitTenantOccupied() ? "VAR" : "YOK";
}
function getUnitTenantContractStatusText() {
  return isUnitTenantOccupied() ? "" : "YOK";
}

const PROJECT_SUITABILITY_AREA_MISMATCH_KEYS = [
  "KULLANIM ALANI OLARAK UYGUN DEGILDIR",
  "KULLANIM ALANI VE MIMARI OLARAK UYGUN DEGILDIR",
  "TRAMPA",
];
const PROJECT_SUITABILITY_LOCATION_MISMATCH_KEYS = [
  "BLOK BAZINDA KONUM OLARAK UYGUN DEGILDIR",
  "TRAMPA",
  "TRAMPA VE AYNA SIMETRISI",
];

function getActiveProjectSuitabilityStatusValues() {
  return shouldUseProjectDifferenceComparison()
    ? [state.fields.titleProjectSuitabilityStatus, state.fields.municipalityProjectSuitabilityStatus]
    : [state.fields.projectSuitabilityStatus];
}

function getUnitProjectSuitabilityAreaMatchText() {
  const mismatch = getActiveProjectSuitabilityStatusValues().some((value) =>
    PROJECT_SUITABILITY_AREA_MISMATCH_KEYS.includes(projectSuitabilityStatusKey(value))
  );
  return mismatch ? "Hayır" : "Evet";
}

function getUnitProjectSuitabilityLocationMatchText() {
  const mismatch = getActiveProjectSuitabilityStatusValues().some((value) =>
    PROJECT_SUITABILITY_LOCATION_MISMATCH_KEYS.includes(projectSuitabilityStatusKey(value))
  );
  return mismatch ? "Hayır" : "Evet";
}

function buildOccupancyPermitDocumentSentence(row) {
  const prefix = buildMissingOccupancyPermitArchivePrefix(row.institution);
  if (!row.date || !row.no) {
    return `${prefix} yapılan incelemelerde taşınmaza ait yapı kullanma izin belgesi bulunamamıştır.`;
  }
  return `${buildDocumentArchivePrefix(row.institution)} yer alan ${formatReviewedDocumentReference(row)} incelenmiştir.`;
}

function buildMissingOccupancyPermitArchivePrefix(institutionValue = "") {
  if (shouldUseMunicipalityOnlyForMissingOccupancyPermit()) {
    return buildDocumentArchivePrefix(buildDefaultDocumentReviewInstitution());
  }
  return buildDocumentArchivePrefix(institutionValue);
}

function shouldUseMunicipalityOnlyForMissingOccupancyPermit() {
  return projectInstitutionIncludes("Webtapu") && projectInstitutionIncludes("Belediye");
}

function buildMunicipalityArchivePrefix() {
  return buildDocumentArchivePrefix();
}

function buildDocumentArchivePrefix(institutionValue = "") {
  const date = dateIsoToTr(state.fields.municipalityInspectionDate || state.fields.appointmentDate || "");
  const institution = normalizeDocumentInstitutionText(
    institutionValue || state.fields.documentReviewInstitution || buildDefaultDocumentReviewInstitution() || ""
  );
  const archiveText = formatDocumentArchiveLocation(institution);
  if (date && archiveText) return `${date} tarihinde, ${archiveText}`;
  if (date) return `${date} tarihinde, inceleme yapılan kurum imar arşiv dosyasında`;
  if (archiveText) return archiveText;
  return "İnceleme yapılan kurum imar arşiv dosyasında";
}

function formatDocumentArchiveLocation(institution) {
  const clean = normalizeDocumentInstitutionText(institution || "");
  if (!clean) return "";
  if (/BELEDIYE/.test(foldTurkish(clean))) return `${clean} İmar Arşiv dosyasında`;
  return `${clean} arşivinde`;
}

function buildDefaultDocumentReviewInstitution() {
  const district = normalizeReportTitleText(state.fields.titleDistrict || state.fields.district || "").trim();
  return district ? `${district} Belediyesi` : "";
}

function buildPenaltyDecisionExplanation() {
  const decision = normalizeYesNoChoice(state.fields.penaltyDecision);
  if (!["Evet", "Hayır"].includes(decision)) return "";
  const date = dateIsoToTr(state.fields.municipalityInspectionDate || state.fields.appointmentDate || "");
  const dateText = date ? `${date} tarihinde ` : "";
  const archiveText = formatPenaltyDecisionArchiveText();
  if (decision === "Evet") {
    const note = normalizeReportDescriptionText(state.fields.penaltyNote || "").trim();
    return normalizeReportDescriptionText(
      `${dateText}${archiveText} yapılan incelemeye göre${note ? ` ${note}` : ""}`
    );
  }
  return normalizeReportDescriptionText(
    `${dateText}${archiveText} yapılan incelemede herhangi bir cezai tutanak, zabıt, yıkım kararı vb. evraka rastlanılmamıştır.`
  );
}

function hasPenaltyDecisionSpecialInstitution() {
  return projectInstitutionIncludes("Büyükşehir") || projectInstitutionIncludes("Özel İdare");
}

function getPenaltyDecisionArchiveInstitutions() {
  const institutions = [];
  if (projectInstitutionIncludes("Büyükşehir")) {
    institutions.push(buildCitySpecificInstitution("Büyükşehir Belediyesi"));
  }
  if (projectInstitutionIncludes("Özel İdare")) {
    institutions.push(buildCitySpecificInstitution("İl Özel İdaresi"));
  }
  institutions.push(buildDefaultDocumentReviewInstitution());
  return institutions.map(formatPenaltyDecisionArchiveInstitution).filter(Boolean);
}

function formatPenaltyDecisionArchiveText() {
  const archiveInstitutions = hasPenaltyDecisionSpecialInstitution()
    ? joinTurkishList(getPenaltyDecisionArchiveInstitutions())
    : formatPenaltyDecisionArchiveInstitution(buildDefaultDocumentReviewInstitution());
  return archiveInstitutions ? `${archiveInstitutions} Arşivinde` : "ilgili kurum arşivinde";
}

function formatPenaltyDecisionArchiveInstitution(value) {
  const institution = normalizeReportTitleText(value || "").trim();
  if (!institution) return "";
  if (/BELEDIYE/.test(foldTurkish(institution)) && !/IMAR\s+VE\s+SEHIRCILIK/.test(foldTurkish(institution))) {
    return `${institution} İmar ve Şehircilik Müdürlüğü`;
  }
  return institution;
}

function refreshPenaltyDecisionExplanationFromCurrentFields(changedKey = "") {
  const watchedKeys = [
    "penaltyDecision",
    "penaltyNote",
    "municipalityInspectionDate",
    "appointmentDate",
    "documentReviewInstitution",
    "projectInstitution",
    "district",
    "titleDistrict",
  ];
  if (changedKey && !watchedKeys.includes(changedKey)) return;
  if (["district", "titleDistrict"].includes(changedKey)) {
    ensureDocumentReviewInstitutionDefault();
  }

  state.fields.penaltyDecisionExplanation = buildPenaltyDecisionExplanation();
  const control = document.querySelector('[data-field="penaltyDecisionExplanation"]');
  if (control && control.value !== state.fields.penaltyDecisionExplanation) {
    control.value = state.fields.penaltyDecisionExplanation || "";
  }
}

// Varyantlar docs/cumle-envanteri.md Bölüm 3'te belgelendi.
const staticSuitabilityOkVariants = [
  (fileText) => `Taşınmazın ${fileText} bulunan statik proje incelenmiştir. Statik proje, mimari proje ve mahal durum ile uyumludur.`,
  (fileText) => `Gayrimenkule ait ${fileText} bulunan statik proje incelenmiş olup, statik projenin mimari proje ve yerinde tespit edilen mahal durumu ile uyumlu olduğu görülmüştür.`,
  (fileText) => `${fileText} yer alan statik proje incelenmiş, mimari proje ve mahal durumu ile uyumlu olduğu belirlenmiştir.`,
  (fileText) => `Taşınmazın ${fileText} bulunan statik projesi incelenmiş olup, mimari proje ve yerinde tespit edilen mahal durumuyla uyumluluğu saptanmıştır.`,
  (fileText) => `Gayrimenkulün ${fileText} bulunan statik projesi değerlendirilmiş, mimari proje ve mahal durumuyla uyumlu olduğu görülmüştür.`,
];
const staticSuitabilityNotOkVariants = [
  (fileText) => `Taşınmazın ${fileText} bulunan statik proje incelenmiştir. Statik proje, mimari proje ve mahal durum ile uyumlu değildir.`,
  (fileText) => `Gayrimenkule ait ${fileText} bulunan statik proje incelenmiş olup, statik projenin mimari proje ve yerinde tespit edilen mahal durumu ile uyumlu olmadığı görülmüştür.`,
  (fileText) => `${fileText} yer alan statik proje incelenmiş, mimari proje ve mahal durumu ile uyumsuz olduğu belirlenmiştir.`,
  (fileText) => `Taşınmazın ${fileText} bulunan statik projesi incelenmiş olup, mimari proje ve yerinde tespit edilen mahal durumuyla uyumsuzluğu saptanmıştır.`,
  (fileText) => `Gayrimenkulün ${fileText} bulunan statik projesi değerlendirilmiş, mimari proje ve mahal durumuyla uyumsuz olduğu görülmüştür.`,
];
registerVariantGroup("buildStaticSuitabilityExplanation:evet", "Statik Proje Uygunluğu — Uyumlu (İmar Durumu)", staticSuitabilityOkVariants.length);
registerVariantGroup("buildStaticSuitabilityExplanation:hayir", "Statik Proje Uygunluğu — Uyumsuz (İmar Durumu)", staticSuitabilityNotOkVariants.length);

function buildStaticSuitabilityExplanation() {
  const decision = normalizeYesNoChoice(state.fields.staticSuitability);
  if (!["Evet", "Hayır"].includes(decision)) return "";
  const institution = formatStaticSuitabilityInstitution(
    state.fields.documentReviewInstitution || buildDefaultDocumentReviewInstitution() || ""
  );
  const fileText = institution ? `${institution} dosyasında` : "ilgili kurum dosyasında";
  if (decision === "Evet") {
    const variantIndex = selectVariant("buildStaticSuitabilityExplanation:evet", staticSuitabilityOkVariants.length);
    return normalizeReportDescriptionText(staticSuitabilityOkVariants[variantIndex](fileText));
  }
  const note = normalizeReportDescriptionText(state.fields.staticSuitabilityNote || "").trim();
  const variantIndex = selectVariant("buildStaticSuitabilityExplanation:hayir", staticSuitabilityNotOkVariants.length);
  return normalizeReportDescriptionText(
    `${staticSuitabilityNotOkVariants[variantIndex](fileText)}${note ? ` ${note}` : ""}`
  );
}

function formatStaticSuitabilityInstitution(value) {
  const municipality = buildDefaultDocumentReviewInstitution();
  if (municipality) return municipality;
  const institution = normalizeReportTitleText(value || "").trim();
  if (institution && !foldTurkish(institution).includes("WEBTAPU")) return institution;
  return buildDefaultDocumentReviewInstitution();
}

function refreshStaticSuitabilityExplanationFromCurrentFields(changedKey = "") {
  const watchedKeys = [
    "staticSuitability",
    "staticSuitabilityNote",
    "documentReviewInstitution",
    "district",
    "titleDistrict",
  ];
  if (changedKey && !watchedKeys.includes(changedKey)) return;
  if (["district", "titleDistrict"].includes(changedKey)) {
    ensureDocumentReviewInstitutionDefault();
  }

  state.fields.staticSuitabilityExplanation = buildStaticSuitabilityExplanation();
  const control = document.querySelector('[data-field="staticSuitabilityExplanation"]');
  if (control && control.value !== state.fields.staticSuitabilityExplanation) {
    control.value = state.fields.staticSuitabilityExplanation || "";
  }
}

function hasReviewedOccupancyPermitDocument() {
  return (state.tables.documents || [])
    .map(normalizeReviewedDocumentRow)
    .some((row) => isOccupancyPermitDocument(row.type));
}

// "İncelenen Belgeler" tablosuna en az bir gerçek satır (Belge Türü seçili)
// girilip girilmediğini kontrol eder. Satır eklenmiş ama Belge Türü boş
// bırakılmışsa yine "belge girilmemiş" sayılır.
function hasAnyReviewedDocumentEntered() {
  return (state.tables.documents || [])
    .map(normalizeReviewedDocumentRow)
    .some((row) => String(row.type || "").trim());
}

// 4708 sayılı Yapı Denetimi Hakkında Kanun'un yürürlük/yayım tarihi. Yeni
// yapı ruhsatı bu tarihten önce alınmış taşınmazlar (yapı kullanma izin
// belgesi bulunmasa dahi) yapı denetim kanunu kapsamı dışında kalır —
// kullanıcı talimatı.
const BUILDING_INSPECTION_LAW_EFFECTIVE_ISO_DATE = "2001-07-13";

function isBuildingInspectionLawExempt() {
  const permitRow = getLatestBuildingPermitDocumentRow();
  const permitDateIso = permitRow ? parseReviewedDocumentDate(permitRow.c2) : "";
  return Boolean(permitDateIso) && permitDateIso < BUILDING_INSPECTION_LAW_EFFECTIVE_ISO_DATE;
}

const buildingInspectionLawExemptVariants = [
  (permitDateText) => `Ekspertize konu taşınmazın yeni yapı ruhsat tarihi ${permitDateText} olup, 13.07.2001 tarih ve 4708 sayılı Yapı Denetimi Hakkında Kanun'un kapsamı dışında kalmaktadır.`,
  (permitDateText) => `Söz konusu taşınmazın yeni yapı ruhsat tarihi ${permitDateText} olup, 13.07.2001 tarih ve 4708 sayılı Yapı Denetimi Hakkında Kanun kapsamına girmemektedir.`,
  (permitDateText) => `Rapor konusu gayrimenkulün yeni yapı ruhsatı ${permitDateText} tarihli olup, 4708 sayılı Yapı Denetimi Hakkında Kanun'un kapsamı dışında bulunmaktadır.`,
  (permitDateText) => `Mülkün yeni yapı ruhsat tarihi ${permitDateText} olup, 13.07.2001 tarih ve 4708 sayılı Kanun'un uygulama alanına girmemektedir.`,
];
registerVariantGroup("buildBuildingInspectionLawExemptionExplanation", "Yapı Denetim Kanunu Kapsamı Dışı (Ana Gayrimenkul)", buildingInspectionLawExemptVariants.length);

function buildBuildingInspectionLawExemptionExplanation() {
  if (!isBuildingInspectionLawExempt()) return "";
  const permitRow = getLatestBuildingPermitDocumentRow();
  const permitDateText = dateIsoToTr(parseReviewedDocumentDate(permitRow.c2));
  const variantIndex = selectVariant("buildBuildingInspectionLawExemptionExplanation", buildingInspectionLawExemptVariants.length);
  return normalizeReportDescriptionText(buildingInspectionLawExemptVariants[variantIndex](permitDateText));
}

const buildingInspectionActiveVariants = [
  (dateText, municipality, level) => `${dateText}${municipality} alınan sözlü bilgiye göre taşınmazın yer aldığı binanın yapı denetim sözleşmesinin aktif olduğu${level ? ` ve yapı denetim hakediş seviyesinin ${level} olduğu` : ""} bilgisine ulaşılmıştır.`,
  (dateText, municipality, level) => `${dateText}${municipality} edinilen sözlü bilgiye göre, taşınmazın bulunduğu binanın yapı denetim sözleşmesinin aktif durumda olduğu${level ? ` ve yapı denetim hakediş seviyesinin ${level} olduğu` : ""} bilgisine erişilmiştir.`,
];
const buildingInspectionTerminatedVariants = [
  (dateText, municipality, terminationDate, level) => `${dateText}${municipality} alınan sözlü bilgiye göre taşınmazın yer aldığı binanın yapı denetim sözleşmesinin${terminationDate ? ` ${terminationDate} tarihinde` : ""} feshedildiği${level ? ` ve yapı denetim fesih seviyesinin ${level} olduğu` : ""} bilgisine ulaşılmıştır.`,
  (dateText, municipality, terminationDate, level) => `${dateText}${municipality} edinilen sözlü bilgiye göre, taşınmazın bulunduğu binanın yapı denetim sözleşmesinin${terminationDate ? ` ${terminationDate} tarihinde` : ""} feshedildiği${level ? ` ve yapı denetim fesih seviyesinin ${level} olduğu` : ""} bilgisine erişilmiştir.`,
];
registerVariantGroup("buildBuildingInspectionExplanation:active", "Yapı Denetim Sözleşmesi — Aktif (Ana Gayrimenkul)", buildingInspectionActiveVariants.length);
registerVariantGroup("buildBuildingInspectionExplanation:terminated", "Yapı Denetim Sözleşmesi — Feshedilmiş (Ana Gayrimenkul)", buildingInspectionTerminatedVariants.length);

function buildBuildingInspectionExplanation() {
  if (hasReviewedOccupancyPermitDocument()) return "";
  const lawExemptionExplanation = buildBuildingInspectionLawExemptionExplanation();
  if (lawExemptionExplanation) return lawExemptionExplanation;
  const status = String(state.fields.buildingInspectionContractActive || "").trim();
  if (!status) return "";
  const date = dateIsoToTr(state.fields.municipalityInspectionDate || state.fields.appointmentDate || "");
  const district = normalizeReportTitleText(state.fields.titleDistrict || state.fields.district || "").trim();
  const municipality = district ? `${district} Belediyesinden` : "ilgili belediyeden";
  const dateText = date ? `${date} tarihinde ` : "";
  if (status === "Evet") {
    const level = state.fields.buildingInspectionProgressLevel || "";
    const variantIndex = selectVariant("buildBuildingInspectionExplanation:active", buildingInspectionActiveVariants.length);
    return normalizeReportDescriptionText(buildingInspectionActiveVariants[variantIndex](dateText, municipality, level));
  }
  if (status === "Hayır (Fesihli)") {
    const terminationDate = dateIsoToTr(state.fields.buildingInspectionTerminationDate || "");
    const level = state.fields.buildingInspectionTerminationLevel || "";
    const variantIndex = selectVariant("buildBuildingInspectionExplanation:terminated", buildingInspectionTerminatedVariants.length);
    return normalizeReportDescriptionText(buildingInspectionTerminatedVariants[variantIndex](dateText, municipality, terminationDate, level));
  }
  return "";
}

function buildBuildingInspectionTerminationExplanation() {
  if (String(state.fields.buildingInspectionContractActive || "").trim() !== "Hayır (Fesihli)") return "";
  const date = dateIsoToTr(state.fields.municipalityInspectionDate || state.fields.appointmentDate || "");
  const district = normalizeReportTitleText(state.fields.titleDistrict || state.fields.district || "").trim();
  const municipality = district ? `${district} Belediyesinden` : "ilgili belediyeden";
  const terminationDate = dateIsoToTr(state.fields.buildingInspectionTerminationDate || "");
  const level = state.fields.buildingInspectionTerminationLevel || "";
  const dateText = date ? `${date} tarihinde ` : "";
  // Ayni "feshedilmis" varyant havuzunu buildBuildingInspectionExplanation
  // ile PAYLAŞIR (ayni anahtar) — bu iki fonksiyon ayni bilgiyi farkli
  // placeholder'lar icin uretir, tutarli olmasi icin ayni secim kullanilir.
  const variantIndex = selectVariant("buildBuildingInspectionExplanation:terminated", buildingInspectionTerminatedVariants.length);
  return normalizeReportDescriptionText(buildingInspectionTerminatedVariants[variantIndex](dateText, municipality, terminationDate, level));
}

function refreshBuildingInspectionExplanationFromCurrentFields(changedKey = "") {
  const watchedKeys = [
    "buildingInspectionContractActive",
    "buildingInspectionProgressLevel",
    "buildingInspectionTerminationDate",
    "buildingInspectionTerminationLevel",
    "municipalityInspectionDate",
    "appointmentDate",
    "district",
    "titleDistrict",
  ];
  if (changedKey && !watchedKeys.includes(changedKey)) return;
  state.fields.buildingInspectionExplanation = buildBuildingInspectionExplanation();
  const control = document.querySelector('[data-field="buildingInspectionExplanation"]');
  if (control && control.value !== state.fields.buildingInspectionExplanation) {
    control.value = state.fields.buildingInspectionExplanation || "";
  }
}

function getEkbInspectionDateIso() {
  return state.fields.appointmentDate || "";
}

function buildEkbExplanation() {
  const hasEkb = normalizeYesNoChoice(state.fields.hasEkb);
  const inspectionDate = getEkbInspectionDateIso();
  const inspectionDateIso = dateTrToIso(inspectionDate) || inspectionDate;
  const inspectionDateText = dateIsoToTr(inspectionDateIso || inspectionDate);
  const inspectionLead = inspectionDateText ? `${inspectionDateText} tarihinde` : "İnceleme tarihinde";
  if (hasEkb === "Hayır") {
    return `${inspectionLead} EKB sistemi, E Devlet, resmi kurumlar ve saha araştırması sonucunda taşınmaza ait Enerji Kimlik Belgesi bulunamamıştır.`;
  }
  if (hasEkb !== "Evet") return "";

  const validUntil = state.fields.ekbValidUntil || "";
  const validUntilIso = dateTrToIso(validUntil) || validUntil;
  const issueDate = dateIsoToTr(state.fields.ekbIssueDate || "");
  const validUntilText = dateIsoToTr(validUntilIso || validUntil);
  if (validUntilIso && inspectionDateIso && validUntilIso < inspectionDateIso) {
    const dateParts = [];
    if (issueDate) dateParts.push(`veriliş tarihi ${issueDate}`);
    if (validUntilText) dateParts.push(`geçerlilik tarihi ${validUntilText}`);
    const certificateDateText = dateParts.length ? ` ${dateParts.join(", ")}` : "";
    const certificateDateSuffix = certificateDateText ? `${certificateDateText} olan` : "";
    return normalizeReportDescriptionText(`${inspectionLead} taşınmaza ait${certificateDateSuffix} Enerji Kimlik Belgesi incelenmiştir. Enerji Kimlik Belgesinin son geçerlilik tarihi sona erdiği için değerleme raporunda dikkate alınmamıştır.`);
  }

  const documentNo = toTitleFieldUppercase(state.fields.ekbDocumentNo || "").trim();
  const energyClass = normalizeReportTitleText(state.fields.ekbEnergyClass || "").trim();
  const certificateParts = [];
  if (issueDate) certificateParts.push(`${issueDate} tarih`);
  if (documentNo) certificateParts.push(`${documentNo} belge numaralı`);
  if (validUntilText) certificateParts.push(`${validUntilText} tarihine kadar geçerliliği bulunan`);

  const certificateLead = certificateParts.length
    ? `${certificateParts.join(", ")} Enerji Kimlik Belgesi`
    : "Enerji Kimlik Belgesi";
  const sentences = [`Konu taşınmazın yer aldığı binaya ait ${certificateLead} bulunmaktadır.`];
  if (energyClass) {
    sentences.push(`Belgeye göre taşınmazın yer aldığı binanın enerji performans sınıfı ${energyClass} sınıfıdır.`);
  }
  return normalizeReportDescriptionText(sentences.join(" "));
}

function refreshEkbExplanationFromCurrentFields(changedKey = "") {
  const watchedKeys = [
    "hasEkb",
    "ekbDocumentNo",
    "ekbIssueDate",
    "ekbValidUntil",
    "ekbEnergyClass",
    "appointmentDate",
  ];
  if (changedKey && !watchedKeys.includes(changedKey)) return;

  state.fields.ekbExplanation = buildEkbExplanation();
  const control = document.querySelector('[data-field="ekbExplanation"]');
  if (control && control.value !== state.fields.ekbExplanation) {
    control.value = state.fields.ekbExplanation || "";
  }
  refreshReviewedDocumentsDescriptionFromCurrentRows();
}

function formatReviewedDocumentReference(row) {
  const scope = row.scope ? ` (${row.scope})` : "";
  return `${dateIsoToTr(row.date)} tarih, ${row.no} sayılı ${row.type}${scope}`;
}

function normalizeReviewedDocumentScope(value) {
  const text = normalizeReportDescriptionText(value || "").trim();
  const folded = foldTurkish(text).replace(/\s+/g, " ").trim();
  if (!folded) return "";
  if (folded === "TAMAMI") return "Tamamı için";
  const blockMatch = folded.match(/^([A-ZÇĞİÖŞÜ0-9]+)\s+BLOK$/);
  if (blockMatch) return `${blockMatch[1]} Blok Tamamı için`;
  return text;
}

function joinTurkishList(items = []) {
  const clean = items.filter(Boolean);
  if (clean.length <= 1) return clean[0] || "";
  if (clean.length === 2) return `${clean[0]} ve ${clean[1]}`;
  return `${clean.slice(0, -1).join(", ")} ve ${clean[clean.length - 1]}`;
}

function foldTurkish(value) {
  return String(value || "")
    .toLocaleUpperCase("tr")
    .replace(/İ/g, "I")
    .replace(/İ/g, "I")
    .replace(/Ş/g, "S")
    .replace(/Ğ/g, "G")
    .replace(/Ü/g, "U")
    .replace(/Ö/g, "O")
    .replace(/Ç/g, "C")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function parseAddressCodeText(text) {
  const clean = normalizeAddressText(text);
  const addressRaw = findAddressRaw(clean);
  const fromAddress = parseAddressLine(addressRaw);
  const uavt = extractUavt(clean);
  const tableValues = extractAddressTableValues(getAddressTableText(clean), uavt);
  const neighborhood = cleanNeighborhoodName(fromAddress.neighborhood || extractNeighborhoodFromAddressText(clean));

  return {
    city: fromAddress.city,
    district: fromAddress.district,
    neighborhood,
    street: fromAddress.street,
    outerDoor: tableValues.outerDoor || fromAddress.outerDoor,
    innerDoor: tableValues.innerDoor,
    addressSiteName: tableValues.siteName,
    addressBlockName: "",
    blockName: "",
    uavt,
    postalCode: tableValues.postalCode,
    addressRaw,
  };
}

function normalizeAddressText(text) {
  return String(text || "")
    .replace(/[\uE000-\uF8FF]/g, " ")
    .replace(/\r+/g, "\n")
    .replace(/[ \t]+/g, " ")
    .replace(/\s+\n/g, "\n")
    .replace(/\n\s+/g, "\n")
    .trim();
}

function getAddressTableText(text) {
  const normalized = String(text || "");
  const tableStart = normalized.search(/Numarataj\s*Bilgileri|Kimlik\s*No\s*Ada|Kimlik\s*NoAda/i);
  const tableEnd = normalized.search(/\b[A-ZÇĞİÖŞÜ]+\s*\/\s*[A-ZÇĞİÖŞÜ]+\s*\/\s*[^/]*MAHALLESİ\s*\/\s*[^/]*(?:Sokak|Cadde|Bulvar)/i);
  const tableSlice = tableStart >= 0
    ? normalized.slice(tableStart, tableEnd > tableStart ? tableEnd : undefined)
    : normalized;

  return tableSlice
    .split(/\n+/)
    .filter((line) => !(line.includes("/") && /mesken|kullanım|kullanim|kapı|kapi/i.test(line) && !/Numarataj|Kimlik\s*No|Bina\s*Ana/i.test(line)))
    .join("\n");
}

function findAddressRaw(text) {
  const headerCandidate = String(text || "")
    .split(/\n+/)
    .map((line) => line.trim())
    .filter(Boolean)
    .map(extractAddressCandidateFromLine)
    .find(Boolean);
  if (headerCandidate) return headerCandidate;

  const lines = text
    .split(/\n+/)
    .map((line) => line.trim())
    .filter(Boolean);
  const line = lines.find((item) => item.includes("/") && /İç\s*Kapı|Ic\s*Kapi|Kullanım|Kullanim|Mesken/i.test(item));
  if (line) return line.replace(/^[^\p{L}\d]*(?=[A-ZÇĞİÖŞÜ])/u, "").trim();

  const inline = text.match(/([A-ZÇĞİÖŞÜ]+)\s*\/\s*([A-ZÇĞİÖŞÜ]+)\s*\/\s*[^]+?(?:İç\s*Kapı\s*No\s*:?\s*\d+|Ic\s*Kapi\s*No\s*:?\s*\d+)/i);
  return inline ? inline[0].trim() : "";
}

function extractAddressCandidateFromLine(line) {
  if (!String(line || "").includes("/")) return "";
  const direct = String(line || "").match(/([A-ZÇĞİÖŞÜ]+)\s*\/\s*([A-ZÇĞİÖŞÜ]+)\s*\/\s*([^/]*\b(?:MAHALLESİ|MAHALLE|MAH\.?|MH\.?))\s*\/\s*([^/]*(?:Sokak|Cadde|Bulvar)[^/]*)/i);
  if (direct) {
    return direct.slice(1, 5).map((part) => part.trim()).join(" / ");
  }

  const parts = String(line || "")
    .replace(/^[^\p{L}\d]+/u, "")
    .split("/")
    .map((part) => part.trim())
    .filter(Boolean);

  for (let start = 0; start <= Math.max(0, parts.length - 4); start += 1) {
    const candidate = parts.slice(start, start + 4);
    if (isLikelyAddressHeader(candidate)) return candidate.join(" / ");
  }

  return "";
}

function isLikelyAddressHeader(parts) {
  if (parts.length < 4) return false;
  const firstTwo = `${parts[0] || ""} ${parts[1] || ""}`;
  const neighborhood = parts[2] || "";
  const street = parts[3] || "";
  if (/(cerez|kimlik|kapi|kapı|blok|posta|numarataj|bagimsiz|bağımsız)/i.test(firstTwo)) return false;
  return /\b(?:mahalle|mah\.?|mh\.?)\b/i.test(neighborhood) && /sokak|cadde|bulvar|\((?:sokak|cadde|bulvar)\)/i.test(street);
}

function extractNeighborhoodFromAddressText(text) {
  const lines = String(text || "")
    .split(/\n+/)
    .map((line) => line.trim())
    .filter(Boolean);
  const patterns = [
    /(?:^|\/|\s)([A-ZÇĞİÖŞÜ0-9.'’\-\s]{2,80}?)\s+(?:MAHALLESİ|MAHALLE|MAH\.?|MH\.?)(?=\s|\/|,|$)/i,
    /(?:İdari|Idari)?\s*Mahalle(?:si)?\s*[:\-]?\s*([A-ZÇĞİÖŞÜ0-9.'’\-\s]{2,80})/i,
  ];

  for (const line of lines) {
    if (/numarataj|kimlik\s*no|posta\s*kod|kapı|kapi/i.test(line)) continue;
    for (const pattern of patterns) {
      const match = line.match(pattern);
      const value = match ? cleanupAddressNeighborhoodCandidate(match[1]) : "";
      if (value) return value;
    }
  }

  const compact = String(text || "").replace(/\s+/g, " ");
  for (const pattern of patterns) {
    const match = compact.match(pattern);
    const value = match ? cleanupAddressNeighborhoodCandidate(match[1]) : "";
    if (value) return value;
  }
  return "";
}

function cleanupAddressNeighborhoodCandidate(value) {
  let text = String(value || "")
    .replace(/.*\//g, "")
    .replace(/\b(?:İl|Il|İlçe|Ilce|Adres|Sokak|Cadde|Bulvar)\b.*$/i, "")
    .replace(/\s+/g, " ")
    .trim();
  text = text.split(/\s+(?:Sokak|Cadde|Bulvar)\b/i)[0].trim();
  if (!text || text.length < 2) return "";
  return text;
}

function parseAddressLine(addressRaw) {
  const result = {
    city: "",
    district: "",
    neighborhood: "",
    street: "",
    outerDoor: "",
    innerDoor: "",
  };

  if (!addressRaw) return result;

  const parts = addressRaw.split("/").map((part) => part.trim()).filter(Boolean);
  // Adres kodu satırı "İL / İLÇE / MAHALLE(Sİ) / SOKAK (Sokak) / KAPINO" düzenindedir.
  // Yapı doğrulanırsa il/ilçe de çekilir; böylece posta kodu eşleşmesi TAKBİS'e
  // bağımlı kalmadan sunucu mahalle sorgusunda doğru il ile yapılır.
  const looksLikeFullAddress = parts.length >= 4
    && /mahalle/i.test(parts[2] || "")
    && /sokak|cadde|bulvar/i.test(parts[3] || "");
  result.city = looksLikeFullAddress ? toTitleCaseTr(parts[0] || "") : "";
  result.district = looksLikeFullAddress ? toTitleCaseTr(parts[1] || "") : "";
  result.neighborhood = parts[2] || "";
  const streetPart = parts[3] || "";
  result.street = /sokak|cadde|bulvar|\((?:sokak|cadde|bulvar)\)/i.test(streetPart)
    ? formatStreetWithType(streetPart)
    : "";

  const doorPart = parts[4] || "";
  result.outerDoor = parseOuterDoor(doorPart);

  const innerMatch = addressRaw.match(/(?:İç|Ic|Iç|İc|ic|iç)?\s*Kap(?:ı|i|I|İ)\s*No\s*:?\s*([0-9A-Za-zÇĞİÖŞÜçğıöşü/-]+)/i);
  result.innerDoor = innerMatch ? onlyDigits(innerMatch[1]) || innerMatch[1].trim() : "";

  result.outerDoor = "";
  result.innerDoor = "";
  return result;
}

function parseOuterDoor(text) {
  const first = String(text || "").split("-")[0].trim();
  const match = first.match(/^([0-9]+[A-Za-zÇĞİÖŞÜçğıöşü]*)/);
  return match ? match[1] : "";
}

function formatStreetWithType(value) {
  const raw = String(value || "").replace(/\s+/g, " ").trim();
  const typeMatch = raw.match(/\((Sokak|Cadde|Bulvar)\)|\b(Sokak|Cadde|Bulvarı|Bulvar)\b/i);
  const streetType = normalizeStreetType(typeMatch ? (typeMatch[1] || typeMatch[2]) : "");
  const name = raw
    .replace(/\(.+?\)/g, "")
    .replace(/(Sokak|Cadde|Bulvarı|Bulvar)/gi, "")
    .trim();
  return [toTitleCaseTr(name), streetType].filter(Boolean).join(" ").trim();
}

function normalizeStreetType(value) {
  const text = String(value || "").toLocaleLowerCase("tr");
  if (text.includes("cadde")) return "Caddesi";
  if (text.includes("bulvar")) return "Bulvarı";
  if (text.includes("sokak")) return "Sokak";
  return "";
}

function toTitleCaseTr(value) {
  return String(value || "")
    .toLocaleLowerCase("tr")
    .split(/(\s+|-)/)
    .map((part) => (/^\s+$|^-$/.test(part) || !part ? part : part.charAt(0).toLocaleUpperCase("tr") + part.slice(1)))
    .join("")
    .replace(/([.!?]\s*)([a-zçğıöşü])/giu, (_, prefix, letter) => prefix + letter.toLocaleUpperCase("tr-TR"));
}

function normalizeReportFieldValue(key, value) {
  const text = String(value ?? "");
  if (!text.trim()) return text.trim();
  if (titleTextUppercaseKeys.has(key)) return toTitleFieldUppercase(text).trim();
  if (key === "postalCode") return normalizePostalCodeValue(text);
  if (key === "planName") return normalizeImarPlanNameForReport(text);
  const field = findReportFieldDefinition(key);
  if (isReportTechnicalField(key, field)) return text.trim();
  if (isReportDescriptionField(key, field)) return normalizeReportDescriptionText(text);
  if (isReportTitleField(key, field)) return normalizeReportTitleText(text);
  return text.trim();
}

function normalizePostalCodeValue(value) {
  const digits = onlyDigits(value);
  if (digits.length === 4) return digits.padStart(5, "0");
  if (digits.length === 5) return digits;
  return String(value || "").trim();
}

function normalizeReportStateFields(targetState) {
  let changed = false;
  Object.entries(targetState.fields || {}).forEach(([key, value]) => {
    if (typeof value !== "string") return;
    const normalized = normalizeReportFieldValue(key, value);
    if (normalized !== value) {
      targetState.fields[key] = normalized;
      changed = true;
    }
  });

  Object.entries(targetState.tables || {}).forEach(([tableKey, rows]) => {
    if (!Array.isArray(rows)) return;
    // Emsal matrisi kendi şemasını (comparableFields) ve değer formatlamasını hücre
    // bazında yönetir. Toplu normalizasyon burada section.table.columns ile yanlış
    // sütun eşleştirip select/multiSelect değerlerini (ör. "1. normal kat" → "1. Normal
    // Kat") bozar ve kat/mülkiyet seçimlerini silinmiş gibi gösterirdi; bu yüzden atlanır.
    if (tableKey === "comparables") return;
    // unitFloors satırları da c0/c1... değil ADLANDIRILMIŞ anahtarlar kullanır
    // (floor, interiors, note...) ve kendi section.id'si yoktur. section bulunamadığı
    // için column="" olur ve normalizeReportTableValue varsayılan dala (başlık
    // büyütme) düşer — "İç Hacimler" seçici kutusundaki "WC" değeri her autosave'de
    // "Wc"ye çevrilip <option value="WC"> ile eşleşmeyince sekme değişince seçim
    // boş görünüyordu (kullanıcı bildirimi). Bu tablo da atlanır.
    if (tableKey === "unitFloors") return;
    const section = sections.find((item) => item.id === tableKey);
    rows.forEach((row) => {
      if (!row || typeof row !== "object") return;
      Object.entries(row).forEach(([cellKey, value]) => {
        if (typeof value !== "string") return;
        const columnIndex = Number(String(cellKey).replace(/^c/, ""));
        const column = section?.table?.columns?.[columnIndex] || "";
        const normalized = normalizeReportTableValue(section, column, value);
        if (normalized !== value) {
          row[cellKey] = normalized;
          changed = true;
        }
      });
    });
  });

  return changed;
}

function findReportFieldDefinition(key) {
  for (const section of sections) {
    const field = (section.fields || []).find((item) => item.key === key);
    if (field) return field;
  }
  return null;
}

function isReportTechnicalField(key, field = {}) {
  if (!field) return false;
  if (field.hidden) return true;
  if (["date", "time", "number", "select"].includes(field.type)) return true;
  return /(^|\.)(date|time|no|number|kod|code|uavt|postal|postcode|latitude|longitude|ada|parsel|pafta|share|hisse|amount|tutar|distance|mesafe)$/i.test(String(key || ""))
    || /^(planScale|taks|kaks|hmax|floorCount|frontGarden|sideGarden|roadSetback|outerDoor|innerDoor|buildingCode|postalCode|parcelArea|grossArea|netArea|legalArea|currentArea|legalValue|currentValue|legalRent|currentRent|landUnitValue|takbisReportTime|takbisTime|nearestNeighborhoodDistance|boundNeighborhoodDistance|districtCenterDistance|cityCenterDistance)$/i.test(String(key || ""));
}

function isReportDescriptionField(key, field = {}) {
  if (!field) return false;
  return field.type === "textarea"
    || /(note|summary|description|explanation|transport|nearby|planning|restriction|conformity|features|codes|açıklama|aciklama|notu)$/i.test(String(key || ""))
    || /Açıklama|Not|Tarif|Yakın Çevre|Ulaşım|Uygunluk|Özellik|Risk/i.test(String(field.label || ""));
}

function isReportTitleField(key, field = {}) {
  if (!field) return false;
  if (field.type && field.type !== "text" && field.type !== "textarea") return false;
  return !isReportDescriptionField(key, field) && !isReportTechnicalField(key, field);
}

function normalizeReportTableValue(section, column, value) {
  const text = String(value ?? "");
  if (!text.trim()) return text.trim();
  if (section?.id === "title" && !isReportTechnicalTableColumn(column)) {
    return toTitleFieldUppercase(text).trim();
  }
  if (section?.id === "encumbranceMortgages" && /ipotek lehdar/i.test(String(column || ""))) {
    return normalizeMortgageCreditorDisplay(text);
  }
  if (section?.id === "documents" && /kurum/i.test(String(column || ""))) {
    return normalizeDocumentInstitutionText(text);
  }
  if (isReportTechnicalTableColumn(column)) return text.trim();
  if (isReportDescriptionTableColumn(column)) return normalizeReportDescriptionText(text);
  return normalizeReportTitleText(text);
}

function isReportTechnicalTableColumn(column) {
  return /(hisse|tarih|yevmiye|no|tutar|derece|alan|fiyat|düzeltme|duzeltme)/i.test(String(column || ""));
}

function isReportDescriptionTableColumn(column) {
  return /(açıklama|aciklama|kapsam|edinme sebebi)/i.test(String(column || ""));
}

function normalizeReportTitleText(value) {
  return preserveReportSpecialWords(toTitleCaseTr(normalizeReportWhitespace(value)));
}

function normalizeReportDescriptionText(value) {
  const text = normalizeReportWhitespace(value)
    .split("\n")
    .map((line) => normalizeReportSentenceLine(line))
    .join("\n")
    .trim();
  return normalizeReportNumberFormats(preserveReportSpecialWords(text));
}

function normalizeReportSentenceLine(value) {
  const line = String(value || "").trim();
  if (!line) return "";
  const normalized = shouldLowercaseReportLine(line)
    ? line.toLocaleLowerCase("tr")
    : line;
  const sentenceCased = normalized.replace(/(^|[.!?]\s+)([a-zçğıöşü])/g, (match, prefix, letter) => prefix + letter.toLocaleUpperCase("tr"));
  return normalizeReportProperPhrases(sentenceCased);
}

function shouldLowercaseReportLine(value) {
  const letters = String(value || "").replace(/[^A-Za-zÇĞİÖŞÜçğıöşü]/g, "");
  if (letters.length < 4) return false;
  const upperLetters = letters.replace(/[^A-ZÇĞİÖŞÜ]/g, "");
  return upperLetters.length / letters.length > 0.65;
}

function normalizeReportWhitespace(value) {
  return String(value || "")
    .replace(/\r\n?/g, "\n")
    .split("\n")
    .map((line) => line.replace(/\s+/g, " ").trim())
    .filter(Boolean)
    .join("\n");
}

function normalizeReportProperPhrases(value) {
  return String(value || "").replace(
    /\b([a-zçğıöşü0-9.'’/-]+(?:\s+[a-zçğıöşü0-9.'’/-]+){0,8}\s+imar\s+plan[ıi]?)\b/gi,
    (match) => {
      const folded = foldTurkish(match);
      if (!/(UYGULAMA|NAZIM|REVIZYON|ILAVE|MERKEZ|KORUMA|CEVRE)/.test(folded)) return match;
      return toTitleCaseTr(match);
    },
  );
}

function preserveReportSpecialWords(value) {
  const replacements = [
    ["takbis", "TAKBİS"],
    ["uavt", "UAVT"],
    ["ekb", "EKB"],
    ["taks", "TAKS"],
    ["kaks", "KAKS"],
    ["hmax", "Hmax"],
    ["tl", "TL"],
    ["m²", "m2"],
    ["m2", "m2"],
  ];
  let text = String(value || "");
  replacements.forEach(([from, to]) => {
    if (from === "tl") {
      text = text.replace(/(^|[^A-Za-zÇĞİÖŞÜçğıöşü])tl(?=$|[^A-Za-zÇĞİÖŞÜçğıöşü])/gi, `$1${to}`);
      return;
    }
    text = text.replace(new RegExp(`\\b${escapeRegExp(from)}\\b`, "gi"), to);
  });
  return text;
}

function escapeRegExp(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function toTitleCaseTakbisEntity(value) {
  return String(value || "")
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => {
      const compact = word.replace(/[^A-Za-z0-9İIıiŞşĞğÜüÖöÇç]/g, "");
      if (word.includes(".") && compact.length <= 6) return word.toLocaleUpperCase("tr");
      return toTitleCaseTr(word);
    })
    .join(" ")
    .trim();
}

function extractUavt(text) {
  const preferred = [
    /Bağımsız\s*Bölüm\s*Kimlik\s*No\s*:?\s*([0-9]{10})/i,
    /Bagimsiz\s*Bolum\s*Kimlik\s*No\s*:?\s*([0-9]{10})/i,
    /Kimlik\s*No[^0-9]{0,80}([0-9]{10})[^0-9]{0,30}(?:İç|Ic|Iç|İc)\s*Kap(?:ı|i|I|İ)/i,
  ];

  for (const pattern of preferred) {
    const match = text.match(pattern);
    if (match) return match[1];
  }

  const all10 = [...text.matchAll(/\b[0-9]{10}\b/g)].map((match) => match[0]);
  return all10.length ? all10[all10.length - 1] : "";
}

function extractAddressTableValues(text, preferredUavt = "") {
  const values = {
    siteName: "",
    blockName: "",
    outerDoor: "",
    innerDoor: "",
    postalCode: "",
  };

  const compact = normalizeAddressTableSpacing(text.replace(/\s+/g, " ").trim());
  const byUavt = extractAddressTableValuesByUavt(compact, preferredUavt || extractUavt(compact));
  if (byUavt) {
    const names = splitRepeatedName(beforeNumericCleanup(byUavt.nameSegment));
    values.siteName = chooseSiteApartmentName(names);
    values.blockName = "";
    values.outerDoor = byUavt.outerDoor;
    values.innerDoor = byUavt.innerDoor;
  }
  const afterType = compact.match(/Bina\s*Ana\s*G(?:iriş|iris|iri[şs]|iri.)\s*(.+?)\s+([0-9A-Za-zÇĞİÖŞÜçğıöşü/-]+)\s+([0-9]{10})\s+([0-9A-Za-zÇĞİÖŞÜçğıöşü/-]+)/i);
  if (afterType) {
    const names = splitRepeatedName(beforeNumericCleanup(afterType[1]));
    const siteOrApartment = chooseSiteApartmentName(names);
    if (siteOrApartment && (!values.siteName || siteOrApartment.length > values.siteName.length)) {
      values.siteName = siteOrApartment;
      values.blockName = "";
    }
    values.outerDoor = values.outerDoor || afterType[2];
    values.innerDoor = values.innerDoor || afterType[4];
  }

  if (!values.outerDoor || !values.innerDoor || !values.siteName) {
    const fallback = matchAddressTableRowFallback(compact);
    if (fallback) {
      const names = splitRepeatedName(beforeNumericCleanup(fallback[1]));
      values.siteName = values.siteName || chooseSiteApartmentName(names);
      values.blockName = "";
      values.outerDoor = values.outerDoor || fallback[2];
      values.innerDoor = values.innerDoor || fallback[4];
    }
  }

  const postalMatch = compact.match(/Posta\s*Kod[^\d]{0,30}([0-9]{5})/i);
  if (postalMatch) values.postalCode = postalMatch[1];

  return values;
}

function extractAddressTableValuesByUavt(text, uavt) {
  const compact = String(text || "");
  const uavtValue = String(uavt || "").trim();
  if (!uavtValue) return null;

  const index = compact.indexOf(uavtValue);
  if (index < 0) return null;

  const before = compact.slice(0, index).trim();
  const after = compact.slice(index + uavtValue.length).trim();
  const beforeTokens = before.split(/\s+/).filter(Boolean);
  const outerDoor = beforeTokens.pop() || "";
  if (!outerDoor) return null;

  let typeIndex = -1;
  for (let i = 0; i < beforeTokens.length - 2; i += 1) {
    if (/^Bina$/i.test(beforeTokens[i]) && /^Ana$/i.test(beforeTokens[i + 1]) && /^G/i.test(beforeTokens[i + 2])) {
      typeIndex = i + 3;
    }
  }

  const nameSegment = typeIndex >= 0 ? beforeTokens.slice(typeIndex).join(" ") : "";
  const innerMatch = after.match(/^([^\s]+)/);

  return {
    nameSegment,
    outerDoor,
    innerDoor: innerMatch ? innerMatch[1] : "",
  };
}

function matchAddressTableRowFallback(text) {
  const compact = String(text || "");
  const patterns = [
    /Bina\s*Ana\s*G\S*\s*(.+?)\s+([0-9A-Za-zÇĞİÖŞÜçğıöşü/-]+)\s+([0-9]{10})\s*([0-9A-Za-zÇĞİÖŞÜçğıöşü/-]+)/i,
    /Bina\s*Ana\s*G\S*\s*(.+?)\s+([0-9A-Za-z/-]+)\s+([0-9]{10})\s*([0-9A-Za-z/-]+)/i,
  ];

  for (const pattern of patterns) {
    const match = compact.match(pattern);
    if (match) return match;
  }

  return null;
}

function normalizeAddressTableSpacing(text) {
  return String(text || "")
    .replace(/(Giriş)(?=[A-ZÇĞİÖŞÜ])/g, "$1 ")
    .replace(/(Giris)(?=[A-Z])/gi, "$1 ")
    .replace(/([A-Za-zÇĞİÖŞÜçğıöşü])([0-9]{1,5}\s+[0-9]{10})/g, "$1 $2")
    .replace(/([0-9]{10})([0-9A-Za-zÇĞİÖŞÜçğıöşü/-])/g, "$1 $2")
    .replace(/\s+/g, " ")
    .trim();
}

function beforeNumericCleanup(value) {
  return String(value || "")
    .replace(/\bKimlik\s*No\b.*$/i, "")
    .replace(/\bMesken\b.*$/i, "")
    .trim();
}

function splitRepeatedName(value) {
  const text = String(value || "").replace(/\s+/g, " ").trim();
  if (!text) return ["", ""];
  const apartmentOnly = text.match(/^[-–—]\s*(.+)$/);
  if (apartmentOnly) return ["", cleanAddressTableName(apartmentOnly[1])];
  const words = text.split(" ");

  for (let size = 1; size <= Math.floor(words.length / 2); size += 1) {
    const first = words.slice(0, size).join(" ");
    const second = words.slice(size, size * 2).join(" ");
    if (normalizeNameForCompare(first) === normalizeNameForCompare(second)) {
      return [cleanAddressTableName(first), cleanAddressTableName(second)];
    }
  }

  return [cleanAddressTableName(text), ""];
}

function chooseSiteApartmentName(names) {
  const siteName = cleanAddressTableName(names?.[0]);
  const apartmentName = cleanAddressTableName(names?.[1]);
  return siteName || apartmentName;
}

function cleanAddressTableName(value) {
  const text = String(value || "")
    .replace(/^[-–—]\s*/, "")
    .replace(/\s*[-–—]\s*$/, "")
    .replace(/\b[A-ZÇĞİÖŞÜ0-9]+\s*Blok\b/gi, "")
    .replace(/\bBlok\b/gi, "")
    .replace(/\s+\d+[A-ZÇĞİÖŞÜ]?$/i, "")
    .replace(/\s+/g, " ")
    .trim();
  if (!text || text === "-") return "";
  return toTitleCaseTr(text);
}

function normalizeNameForCompare(value) {
  return String(value || "")
    .toLocaleLowerCase("tr")
    .replace(/[ıiİI]/g, "i")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function onlyDigits(value) {
  return String(value || "").replace(/\D+/g, "");
}

function applyAddressFieldsToReport(options = {}) {
  const fields = state.sourceValues.address?.fields || {};
  state.sourceConflicts.address = {};

  Object.entries(fields).forEach(([key, value]) => {
    if (!value) return;
    if (options.preserveShared && TITLE_UNIT_SHARED_EXPLANATION_FIELD_KEYS.has(key)) return;
    const nextValue = key === "addressSiteName" ? cleanAddressTableName(value) : value;
    if (!nextValue) return;
    setFieldFromSource("address", key, nextValue, options);
  });
  syncAddressBlockFromTakbis(options);
  return triggerPostalCodeLookupAfterAddressApply(fields);
}

function triggerPostalCodeLookupAfterAddressApply(fields = {}) {
  if (!fields.city && !fields.district && !fields.neighborhood) return Promise.resolve(false);
  // Adres PDF'inden gelen posta kodu güvenilmez (yanlış il koduyla gelebiliyor);
  // mahalle veritabanında eşleşme varsa DB değeri force ile yazılır. await
  // edilebilmesi için promise döndürülür (bkz. processAddressFile).
  return applyPostalCodeFromSelectedNeighborhood({ silent: true, force: true }).then((changed) => {
    if (!changed) return false;
    autosave();
    if (activeSectionId === "address") renderSection();
    renderValidation();
    updateStatus();
    return true;
  }).catch(() => false);
}

function applyTakbisTitleFieldsToReport(options = {}) {
  const fields = state.sourceValues.takbis?.fields || {};
  state.sourceConflicts.takbis = {};

  Object.entries(fields).forEach(([key, value]) => {
    if (!value) return;
    setFieldFromSource("takbis", key, value, options);
  });
  if (fields.titleFloor) {
    setFieldFromSource("takbis", "addressFloor", fields.titleFloor, options);
  }
  applyAdministrativeNeighborhoodFallback("takbis", fields.titleNeighborhood);
  syncAddressBlockFromTakbis(options);
  refreshEnvironmentDescriptionFromCurrentFields("titleFloor");
  // Kullanıcı bildirimi (2026-08-12): İmar Durumu PDF'i TAKBİS'ten ÖNCE
  // yüklenirse "Hesaplanan Emsal" boş kalıyordu. Sebep: `applyImarFieldsToReport`
  // calculatedEmsal'i İMAR işlenirken TEK SEFERLİK hesaplıyor
  // (`buildImarCalculatedEmsal` o an `state.fields.landArea`'ya bakıyor) —
  // landArea henüz TAKBİS'ten gelmediyse hesap boş kalıp bir daha
  // tetiklenmiyordu. `landArea` burada (TAKBİS'ten) set edildiği için,
  // yükleme sırası ne olursa olsun planningNote/calculatedEmsal'i güncel
  // state.fields ile YENİDEN hesaplat — İmar henüz hiç işlenmediyse bu
  // no-op'tur (planCancellationStay boş, kaks boş).
  refreshPlanningNoteFromCurrentFields("landArea");
}

function syncAddressBlockFromTakbis(options = {}) {
  const block = cleanTakbisValue(state.sourceValues.takbis?.fields?.titleBlockName || "");
  if (block) setFieldFromSource("takbis", "addressBlockName", block, options);
  const entrance = cleanTakbisValue(state.sourceValues.takbis?.fields?.titleEntrance || "");
  if (entrance) setFieldFromSource("takbis", "addressEntrance", entrance, options);
}

function applyTakbisOwnersToTable(owners) {
  const ownerRows = (owners || []).map((owner) => ({
    c0: cleanTakbisOwnerDisplayName(owner.name || ""),
    c1: owner.share || "",
    c2: owner.acquisition || "",
    c3: dateIsoToTr(owner.date) || "",
    c4: owner.journalNo || "",
  }));
  state.tables.title = ownerRows.length
    ? ownerRows
    : Array.from({ length: sections.find((section) => section.id === "title")?.table?.rows || 3 }, () => ({}));
  refreshTitleOwnershipKindFromOwners();
}

function refreshTitleOwnershipKindFromOwners() {
  const nextKind = inferTitleOwnershipKindFromOwnerRows(state.tables.title || []);
  if (!nextKind) return;
  state.sourceValues.takbis = state.sourceValues.takbis || {};
  state.sourceConflicts.takbis = state.sourceConflicts.takbis || {};
  const currentValue = state.fields.titleOwnershipKind || "";
  const previousSourceValue = state.sourceValues.takbis?.applied?.titleOwnershipKind || "";
  setFieldFromSource("takbis", "titleOwnershipKind", nextKind);
  const wasApplied = !currentValue || currentValue === previousSourceValue;
  const control = document.querySelector('[data-field="titleOwnershipKind"]');
  if (control && wasApplied) {
    control.value = state.fields.titleOwnershipKind || "";
    markFieldSourceState(control, "titleOwnershipKind");
  }
  refreshShareExplanationFromCurrentFields("titleOwnershipKind");
}

// Varyantlar docs/cumle-envanteri.md Bölüm 2'de belgelendi (BDDK riski
// açısından en yüksek öncelikli aday — hisseli olan HER raporda çıkıyor).
const shareExplanationVariants = [
  "Değerleme konusu taşınmaz hisseli olup, TAŞINMAZIN TÜM HİSSELERİNİN (AÇIKTA HİSSE KALMAYACAK ŞEKİLDE) İPOTEK ALTINA ALINMASI ŞARTIYLA uzman kanaati SATILABİLİR olarak takdir edilmiştir.",
  "Değerlemeye konu gayrimenkul hisseli mülkiyete tabi olup, GAYRİMENKULÜN TÜM HİSSELERİNİN (AÇIKTA HİSSE BIRAKILMAKSIZIN) İPOTEK ALTINA ALINMASI KOŞULUYLA uzman kanaatimizce SATILABİLİR nitelikte olduğu değerlendirilmiştir.",
  "Söz konusu mülk hisseli tapu kaydına sahip olup, TÜM HİSSELERİN (AÇIKTA HİSSE KALMAKSIZIN) İPOTEK KAPSAMINA ALINMASI ŞARTIYLA taşınmazın SATILABİLİR olduğu kanaatine varılmıştır.",
];
registerVariantGroup("buildShareExplanation", "Hisse Açıklaması (Tapu ve Mülkiyet)", shareExplanationVariants.length);

function buildShareExplanation() {
  const variantIndex = selectVariant("buildShareExplanation", shareExplanationVariants.length);
  return shareExplanationVariants[variantIndex];
}

function refreshShareExplanationFromCurrentFields(changedKey = "") {
  if (changedKey && changedKey !== "titleOwnershipKind") return;
  const autoText = buildShareExplanation();
  const currentText = String(state.fields.shareExplanation || "").trim();
  const isAutoText = currentText === autoText;

  if (state.fields.titleOwnershipKind === "Hisseli Mülkiyet") {
    if (currentText && !isAutoText) return;
    state.fields.shareExplanation = autoText;
  } else if (isAutoText) {
    state.fields.shareExplanation = "";
  } else {
    return;
  }

  const control = document.querySelector('[data-field="shareExplanation"]');
  if (control && control.value !== state.fields.shareExplanation) {
    control.value = state.fields.shareExplanation;
  }
  const valuationText = document.querySelector("[data-valuation-share-explanation-text]");
  if (valuationText) valuationText.textContent = state.fields.shareExplanation || "";
}

function isSharedTitleOwnership() {
  return foldTurkish(state.fields.titleOwnershipKind || "").replace(/\s+/g, " ").trim() === "HISSELI MULKIYET";
}

function inferTitleOwnershipKindFromOwnerRows(rows = []) {
  const filledRows = rows.filter((row) => cleanTakbisValue(row?.c0 || row?.c1 || row?.c2 || row?.c3 || row?.c4 || ""));
  if (!filledRows.length) return "";
  if (filledRows.length > 1) return "Hisseli Mülkiyet";
  const share = normalizeOwnerShareValue(filledRows[0]?.c1 || "");
  return share === "1/1" ? "Tam Mülkiyet" : "Hisseli Mülkiyet";
}

function normalizeOwnerShareValue(value) {
  return cleanTakbisValue(value)
    .replace(/\s+/g, "")
    .replace(/\\/g, "/");
}

function applyTakbisEncumbranceFieldsToReport(parsed, options = {}) {
  const fields = parsed?.fields || {};
  const values = {
    takbisDate: fields.takbisReportDate || "",
    takbisTime: fields.takbisReportTime || "",
  };

  Object.entries(values).forEach(([key, value]) => {
    setFieldFromSource("takbis", key, value, options);
  });
}

function applyTakbisEncumbrancesToTable(encumbrances) {
  const encumbranceRows = (encumbrances || []).map((record) => ({
    c0: record.type || "",
    c1: record.description || "",
    c2: record.date || "",
    c3: record.journalNo || "",
    c4: record.restrictedOwner || "",
  }));
  state.tables.encumbrance = encumbranceRows.length
    ? encumbranceRows
    : Array.from({ length: sections.find((section) => section.id === "encumbrance")?.table?.rows || 5 }, () => ({}));

  const groupedRows = createEmptyEncumbranceReportTables();
  (encumbrances || []).forEach((record) => {
    const tableKey = getEncumbranceReportTableKey(record);
    groupedRows[tableKey].push(tableKey === "encumbranceMortgages"
      ? parseTakbisMortgageRecord(record)
      : tableKey === "encumbranceAnnotations"
        ? parseTakbisAnnotationRecord(record)
      : {
          c0: record.type || "",
          c1: record.description || "",
          c2: record.date || "",
          c3: record.journalNo || "",
          c4: record.restrictedOwner || "",
        });
  });

  encumbranceReportTables.forEach((table) => {
    state.tables[table.key] = groupedRows[table.key].filter((row) => hasMeaningfulEncumbranceTableRow(table.key, row));
  });
  refreshEncumbranceSummaryFromCurrentData();
}

function createEmptyEncumbranceReportTables() {
  return encumbranceReportTables.reduce((tables, table) => {
    tables[table.key] = [];
    return tables;
  }, {});
}

function createEmptyEncumbranceRows() {
  return Array.from({ length: encumbranceEmptyRowCount }, () => ({}));
}

// İş Bankası masraf yazısı ücret kalemleri. Kaynak: kullanıcının 2026 yılı
// "RAPOR YAZMA PROGRAMI" Excel/VBA dosyasındaki "FATURA VE ÜCRETLENDİRME"
// sayfası + DegerlemeUcreti() makrosu, ve resmi "2026 Yılı Gayrimenkul
// Değerleme Asgari Ücret Tarifesi" tablosu (kullanıcının paylaştığı görsel).
// Değerleme Ücreti tek bir sabit değil, gayrimenkul türü × brüt/mevcut alana
// göre kademeli bir tarifeden seçiliyor. Tarifedeki 9 gruptan yalnız sayısal
// (kademeli) ücret içerenler burada modellenmiştir — Toplu Değerleme (%20/
// %15 indirimli çoklu taşınmaz kuralı), Yeniden Değerleme (%30/%50 indirim),
// Proje/Hak/Fayda ve "Diğer" grupları "Belirlenmemiştir" veya ayrı iş kuralı
// gerektirdiğinden (rapor sayısı, önceki rapor tarihi vb.) buraya dahil
// edilmedi. Belediye Harcı admin sabiti DEĞİL, rapora özgü elle girilen bir
// alan (Excel'de de böyle: BELEDİYEHARÇ hücresi). Tapu Harcı = birim tutar ×
// tapu adedi (ISBANKTAPUADEDI).
//
// Kademe SINIRLARI sabit kod (yılda bir değişmez); yalnızca TL tutarları
// admin tarafından "expenseFees" bölümünden (adminEditableOnly) güncellenir
