// Banka → masraf grubu (A/B/C/D). Kaynak: kullanıcının
// "Fatura_Masraf_Otomasyon_Sablon.xlsm" dosyasındaki KURALLAR sayfası +
// Module1/Module2 VBA makroları. Gruplar tapu ve belediye harcının KDV
// muamelesini belirler (bkz. recalculateExpenseFees). Listede olmayan banka
// → Grup A (Excel'deki varsayılan). Grup A bankaların çoğunlukta olması ve
// varsayılan olması nedeniyle yalnız B/C/D bankaları burada sıralanır.
const EXPENSE_BANK_GROUP_MAP = {
  // Grup B: makbuz tutarı her zaman KDV-DAHİL kabul edilir (checkbox yok sayılır)
  "TURKIYE IS BANKASI A.S.": "B",
  "FIBABANKA A.S.": "B",
  "ALTERNATIFBANK A.S.": "B",
  // Grup C: belediye makbuz tutarı düz girilir (KDV ayrıştırılmaz); tapu KDV-dahil
  "YAPI VE KREDI BANKASI A.S.": "C",
  "T.C. ZIRAAT BANKASI A.S.": "C",
  "TURKIYE CUMHURIYETI ZIRAAT BANKASI A.S.": "C",
  // Grup D: belediye checkbox'a bağlı; tapu KDV-dahil
  "EMLAK KATILIM BANKASI A.S.": "D",
};

function normalizeExpenseBankName(name) {
  return String(name || "")
    .toLocaleUpperCase("tr-TR")
    .replace(/İ/g, "I").replace(/I/g, "I").replace(/Ş/g, "S").replace(/Ğ/g, "G")
    .replace(/Ü/g, "U").replace(/Ö/g, "O").replace(/Ç/g, "C")
    .replace(/\s+/g, " ")
    .trim();
}

function getExpenseBankGroup(bankName) {
  return EXPENSE_BANK_GROUP_MAP[normalizeExpenseBankName(bankName)] || "A";
}

// Admin tarafından yönetilen, bulutta ortak sabitler (tarife kademeleri +
// birim ücretler + KDV oranı). Belediye Harcı ve tapu adedi burada YOK —
// onlar rapora özgü, herkes girebilir.
const EXPENSE_FEE_ADMIN_KEYS = [
  ...Object.values(EXPENSE_APPRAISAL_TIERS).flatMap((tiers) => tiers.map((tier) => tier.key)),
  "expenseTransportFeeExVat",
  "expenseTitleDeedUnitFeeExVat",
  "expenseInfoCenterShareExVat",
  "expenseUnionShareExVat",
  "expenseVatRatePercent",
  "expenseAppraisalBulkFlatFee201Plus",
];

// 6. GRUP — Toplu Değerleme: en büyük alanlı taşınmaz tam ücret alır,
// diğerleri KENDİ tarifelerindeki ücretin bir yüzdesini alır (1. Grup %20,
// 2. Grup %15). 2. Grup'ta 201 ve üzeri taşınmaz varsa sabit ücrete geçilir.
const EXPENSE_BULK_MODE_1 = "1. Grup - Farklı Taşınmazlar (Aynı Mahalle/Köy)";
const EXPENSE_BULK_MODE_2 = "2. Grup - Aynı Parsel Birden Fazla Bağımsız Bölüm";
const EXPENSE_BULK_MODE_2_FLAT_THRESHOLD = 201;
const EXPENSE_BULK_MODE_DISCOUNT = {
  [EXPENSE_BULK_MODE_1]: 0.2,
  [EXPENSE_BULK_MODE_2]: 0.15,
};

// KDV-hariç → KDV-dahil eşleşmeleri (sabit oranlı basit kalemler). Belediye
// ve Tapu Harcı bu haritada YOK — ikisinin de KDV muamelesi bankanın
// grubuna (A/B/C/D) göre değiştiğinden recalculateExpenseFees içinde ayrıca
// ele alınır.
const EXPENSE_FEE_PAIR_MAP = {
  expenseAppraisalFeeExVat: "expenseAppraisalFeeIncVat",
  expenseTransportFeeExVat: "expenseTransportFeeIncVat",
  expenseInfoCenterShareExVat: "expenseInfoCenterShareIncVat",
  expenseUnionShareExVat: "expenseUnionShareIncVat",
};

// Bir alan değiştiğinde yeniden hesaplama/senkron tetikleyen tüm anahtarlar.
const EXPENSE_FEE_WATCHED_KEYS = [
  ...EXPENSE_FEE_ADMIN_KEYS,
  "bank",
  "expenseAppraisalPropertyType",
  "expenseMunicipalityFeeReceipt",
  "expenseMunicipalityVatIncluded",
  "expenseTitleDeedCount",
  "expenseBulkValuationMode",
  "expenseBulkPropertyCount",
  "expenseBulkOtherPropertiesFeeSum",
];

// Arsa/Tarım kategorilerinde tarife "brüt alan" = ana taşınmazın PARSEL
// yüzölçümü (landArea); Daire/Villa/Ofis, Dükkan, Depo kategorilerinde ise
// bağımsız bölümün mevcut kullanım alanı (currentArea) esas alınır.
const EXPENSE_LAND_BASED_APPRAISAL_TYPES = new Set([
  "Arsa / Tarım Alanı (İmarsız)",
  "Arsa (İmarlı)",
]);

// Akaryakıt İstasyonu tarifesi "Tamamı" — tek sabit tutar, alan büyüklüğüne
// bakılmaksızın uygulanır; bu yüzden alan şartı aranmaz.
const EXPENSE_FLAT_APPRAISAL_TYPES = new Set(["Akaryakıt İstasyonu"]);

function getExpenseAppraisalAreaField(propertyType) {
  return EXPENSE_LAND_BASED_APPRAISAL_TYPES.has(propertyType) ? "landArea" : "currentArea";
}

// "Mevcut Kullanım Niteliği" (currentUsageNature) ve "Mülkiyet" (ownershipType)
// alanlarından Değerleme Ücreti Tarife Türü'nü otomatik önerir (kullanıcı
// talebi). Mülkiyet Arsa/Tarla ise doğrudan arazi tarifesi seçilir (daha
// spesifik/otoriter bilgi); aksi halde mevcut kullanım niteliğine bakılır:
// Konut/Ofis → Daire/Villa/Ofis, İşyeri/Ticari Bina → Dükkan,
// Sanayi Tesisi → Depo (resmi tarifede "Üretim, Depolama, Zirai ve Sınai
// Nitelikli Yapılar" grubu sanayiyi de kapsar), Arazi → Arsa/Tarım Alanı
// (İmarsız), Arsa → Arsa (İmarlı).
function suggestExpenseAppraisalPropertyType() {
  // foldTurkish BÜYÜK harfe çevirir (örn. "İşyeri" -> "ISYERI") — karşılaştırmalar buna göre.
  // "Mevcut Kullanım Niteliği" HER ZAMAN önceliklidir — kullanıcı niteliği
  // değiştirdiğinde tarife her seferinde güncellenmeli. "Mülkiyet" (ownershipType)
  // yalnızca nitelik boşken (ör. rapor henüz doldurulmamışken) ve yalnızca
  // Tarla için yedek sinyal olarak kullanılır ("Mevcut Kullanım Niteliği"nde
  // Tarla seçeneği yok). ÖNCEKİ HATA: ownershipType Arsa/Tarla olduğunda
  // nitelik degisiklikleri tamamen goz ardi ediliyordu.
  const usage = foldTurkish(state.fields.currentUsageNature || "");
  if (usage === "KONUT" || usage === "OFIS") return "Daire / Villa / Ofis";
  if (usage === "ISYERI" || usage === "TICARI BINA") return "Dükkan";
  if (usage === "SANAYI TESISI") return "Depo";
  if (usage === "ARAZI") return "Arsa / Tarım Alanı (İmarsız)";
  if (usage === "ARSA") return "Arsa (İmarlı)";

  const ownership = foldTurkish(state.fields.ownershipType || "");
  if (ownership === "ARSA") return "Arsa (İmarlı)";
  if (ownership === "TARLA") return "Arsa / Tarım Alanı (İmarsız)";
  return "";
}

// Kullanıcı Tarife Türü'nü elle değiştirirse otomatik öneri onu bir daha
// ezmez (diğer "manual override" alanlarıyla aynı desen).
// İzlenen anahtarlar: "currentUsageNature" doğrudan değişebilir AMA
// çoğu raporda gizlidir (usageNatureDifference "Hayır" iken) — bu durumda
// kullanıcı "Yasal Kullanım Niteliği"ni (legalUsageNature) değiştirir ve
// syncCurrentUsageNatureWithLegalNature() currentUsageNature'ı SESSİZCE
// (kendi input olayı fırlatmadan) senkronize eder. Bu yüzden legalUsageNature
// ve usageNatureDifference de tetikleyici olarak izlenir.
const EXPENSE_APPRAISAL_PROPERTY_TYPE_WATCHED_KEYS = ["currentUsageNature", "legalUsageNature", "usageNatureDifference", "ownershipType"];

function refreshExpenseAppraisalPropertyTypeFromCurrentFields(changedKey) {
  if (changedKey === "expenseAppraisalPropertyType") {
    state.fields.expenseAppraisalPropertyTypeManual = "Evet";
    return;
  }
  if (!EXPENSE_APPRAISAL_PROPERTY_TYPE_WATCHED_KEYS.includes(changedKey)) return;
  if (state.fields.expenseAppraisalPropertyTypeManual === "Evet") return;
  const suggestion = suggestExpenseAppraisalPropertyType();
  if (suggestion && state.fields.expenseAppraisalPropertyType !== suggestion) {
    state.fields.expenseAppraisalPropertyType = suggestion;
    recalculateExpenseFees();
    updateExpenseFeesSummaryPanel();
  }
}

function lookupExpenseAppraisalFeeExVat(propertyType, area) {
  const tiers = EXPENSE_APPRAISAL_TIERS[propertyType];
  if (!tiers) return Number.NaN;
  if (EXPENSE_FLAT_APPRAISAL_TYPES.has(propertyType)) {
    return parseValuationNumber(state.fields[tiers[0].key]);
  }
  const numericArea = parseValuationNumber(area);
  if (!Number.isFinite(numericArea) || numericArea <= 0) return Number.NaN;
  const tier = tiers.find((item) => numericArea >= item.min && numericArea <= item.max);
  if (!tier) return Number.NaN;
  return parseValuationNumber(state.fields[tier.key]);
}

function recalculateExpenseFees() {
  const vatRate = parseValuationNumber(state.fields.expenseVatRatePercent);
  const multiplier = 1 + (Number.isFinite(vatRate) && vatRate >= 0 ? vatRate : 20) / 100;

  const appraisalAreaField = getExpenseAppraisalAreaField(state.fields.expenseAppraisalPropertyType);
  let appraisalFee = lookupExpenseAppraisalFeeExVat(state.fields.expenseAppraisalPropertyType, state.fields[appraisalAreaField]);

  const bulkMode = state.fields.expenseBulkValuationMode;
  const bulkCount = parseValuationNumber(state.fields.expenseBulkPropertyCount);
  const bulkOtherSum = parseValuationNumber(state.fields.expenseBulkOtherPropertiesFeeSum);
  if (bulkMode === EXPENSE_BULK_MODE_2 && Number.isFinite(bulkCount) && bulkCount >= EXPENSE_BULK_MODE_2_FLAT_THRESHOLD) {
    appraisalFee = parseValuationNumber(state.fields.expenseAppraisalBulkFlatFee201Plus);
  } else if (EXPENSE_BULK_MODE_DISCOUNT[bulkMode] && Number.isFinite(appraisalFee) && Number.isFinite(bulkOtherSum) && bulkOtherSum > 0) {
    appraisalFee += bulkOtherSum * EXPENSE_BULK_MODE_DISCOUNT[bulkMode];
  }
  state.fields.expenseAppraisalFeeExVat = Number.isFinite(appraisalFee) ? formatValuationMoney(appraisalFee, { decimals: 2 }) : "";

  const bankGroup = getExpenseBankGroup(state.fields.bank);

  let total = 0;
  let totalExVat = 0;
  // NOT: expenseAppraisalFeeExVat burada elle toplama eklenmez — aşağıdaki
  // EXPENSE_FEE_PAIR_MAP döngüsü zaten bu anahtarı işliyor (INC-VAT toplamın
  // hep yaptığı gibi). Burada da eklersek çift sayım olur.

  // TAPU HARCI: KDV-dahil toplam her grupta aynıdır → birim(KDV hariç) × KDV
  // oranı × adet (2026: 255,83 × 1,20 = 307 TL/tapu). Fark yalnız KDV
  // kırılımında: A,B gruplarında 307 içinden ayrıştırılır (hariç 255,83 +
  // KDV 51,17); C,D gruplarında düz gösterilir (hariç = 307, KDV = 0).
  const titleDeedUnitFee = parseValuationNumber(state.fields.expenseTitleDeedUnitFeeExVat);
  const titleDeedCount = parseValuationNumber(state.fields.expenseTitleDeedCount);
  if (Number.isFinite(titleDeedUnitFee) && titleDeedUnitFee > 0 && Number.isFinite(titleDeedCount) && titleDeedCount > 0) {
    const titleDeedIncVat = titleDeedUnitFee * multiplier * titleDeedCount;
    const titleDeedExVat = (bankGroup === "C" || bankGroup === "D") ? titleDeedIncVat : titleDeedIncVat / multiplier;
    state.fields.expenseTitleDeedFeeExVat = formatValuationMoney(titleDeedExVat, { decimals: 2 });
    state.fields.expenseTitleDeedFeeIncVat = formatValuationMoney(titleDeedIncVat, { decimals: 2 });
    total += titleDeedIncVat;
    totalExVat += titleDeedExVat;
  } else {
    state.fields.expenseTitleDeedFeeExVat = "";
    state.fields.expenseTitleDeedFeeIncVat = "";
  }

  // BELEDİYE HARCI: kullanıcı makbuz tutarını girer. KDV muamelesi gruba göre:
  //  A, D → "Makbuzda KDV Belirtilmiş mi?" kutucuğuna bağlı: işaretliyse tutar
  //         KDV-DAHİL (hariç = tutar/oran); işaretsizse KDV-HARİÇ (dahil =
  //         tutar × oran).
  //  B    → her zaman KDV-DAHİL kabul edilir (kutucuk yok sayılır).
  //  C    → düz: tutar aynen (hariç = dahil = tutar, KDV = 0).
  const municipalityReceipt = parseValuationNumber(state.fields.expenseMunicipalityFeeReceipt);
  if (Number.isFinite(municipalityReceipt) && municipalityReceipt > 0) {
    let municipalityExVat;
    let municipalityIncVat;
    if (bankGroup === "C") {
      municipalityExVat = municipalityReceipt;
      municipalityIncVat = municipalityReceipt;
    } else if (bankGroup === "B") {
      municipalityExVat = municipalityReceipt / multiplier;
      municipalityIncVat = municipalityReceipt;
    } else {
      const vatIncluded = String(state.fields.expenseMunicipalityVatIncluded || "").trim() === "Evet";
      municipalityExVat = vatIncluded ? municipalityReceipt / multiplier : municipalityReceipt;
      municipalityIncVat = vatIncluded ? municipalityReceipt : municipalityReceipt * multiplier;
    }
    state.fields.expenseMunicipalityFeeExVat = formatValuationMoney(municipalityExVat, { decimals: 2 });
    state.fields.expenseMunicipalityFeeIncVat = formatValuationMoney(municipalityIncVat, { decimals: 2 });
    total += municipalityIncVat;
    totalExVat += municipalityExVat;
  } else {
    state.fields.expenseMunicipalityFeeExVat = "";
    state.fields.expenseMunicipalityFeeIncVat = "";
  }

  Object.keys(EXPENSE_FEE_PAIR_MAP).forEach((baseKey) => {
    const incKey = EXPENSE_FEE_PAIR_MAP[baseKey];
    const base = parseValuationNumber(state.fields[baseKey]);
    if (Number.isFinite(base) && base > 0) {
      const inclusive = base * multiplier;
      state.fields[incKey] = formatValuationMoney(inclusive, { decimals: 2 });
      total += inclusive;
      totalExVat += base;
    } else {
      state.fields[incKey] = "";
    }
  });
  state.fields.expenseTotalFeeIncVat = total > 0 ? formatValuationMoney(total, { decimals: 2 }) : "";
  state.fields.expenseTotalFeeExVat = totalExVat > 0 ? formatValuationMoney(totalExVat, { decimals: 2 }) : "";
}

function refreshExpenseFeesFromCurrentFields(changedKey) {
  if (!EXPENSE_FEE_WATCHED_KEYS.includes(changedKey) && changedKey !== "currentArea" && changedKey !== "landArea") return;
  recalculateExpenseFees();
  updateExpenseFeesSummaryPanel();
  if (EXPENSE_FEE_ADMIN_KEYS.includes(changedKey) && isCurrentUserAdmin()) scheduleExpenseFeeCloudSave();
}

let expenseFeeCloudSaveTimer = null;
function scheduleExpenseFeeCloudSave() {
  clearTimeout(expenseFeeCloudSaveTimer);
  expenseFeeCloudSaveTimer = setTimeout(() => {
    const payload = {};
    EXPENSE_FEE_ADMIN_KEYS.forEach((key) => { payload[key] = state.fields[key] || ""; });
    window.RaporCloudSync?.saveExpenseFees?.(payload)?.catch?.((error) => {
      console.warn("Masraf bilgileri buluta kaydedilemedi:", error?.code || error);
    });
  }, 800);
}

async function syncExpenseFeesFromCloud() {
  try {
    const remote = await window.RaporCloudSync?.loadExpenseFees?.();
    if (!remote) {
      // Bulutta hiç kayıt yok: admin ilk girişte 2026 varsayılanlarını
      // otomatik doldurup buluta kaydeder (bir daha bu dal çalışmaz, çünkü
      // bundan sonra remote her zaman dolu olur).
      if (isCurrentUserAdmin()) {
        Object.entries(EXPENSE_FEE_2026_DEFAULTS).forEach(([key, value]) => { state.fields[key] = value; });
        recalculateExpenseFees();
        saveState();
        render();
        scheduleExpenseFeeCloudSave();
      }
      return;
    }
    let changed = false;
    EXPENSE_FEE_ADMIN_KEYS.forEach((key) => {
      const value = remote[key];
      if (value !== undefined && state.fields[key] !== value) {
        state.fields[key] = value;
        changed = true;
      }
    });
    if (changed) {
      recalculateExpenseFees();
      saveState();
      render();
    }
  } catch (error) {
    console.warn("Masraf bilgileri buluttan alınamadı:", error?.code || error);
  }
}

function refreshEncumbranceSummaryFromCurrentFields(changedKey) {
  if (!["bank", "takbisDate", "takbisMethod", "titleRecordChange"].includes(changedKey)) return;
  refreshEncumbranceSummaryFromCurrentData();
}

function refreshEncumbranceSummaryFromCurrentData() {
  const variants = buildEncumbranceSummaryVariants();
  if (!variants.exceedsLimit) {
    state.fields.encumbranceSummaryMode = "summary";
  }
  const summary = selectEncumbranceSummaryVariant(
    variants,
    state.fields.encumbranceSummaryMode,
  );
  state.fields.takbisSummary = summary;
  const control = document.querySelector('[data-field="takbisSummary"]');
  if (control && control.value !== summary) {
    control.value = summary;
    markFieldSourceState(control, "takbisSummary", true);
  }
  syncEncumbranceSummaryModeControl(variants);
}

function createEncumbranceSummaryModeControl() {
  const variants = buildEncumbranceSummaryVariants();
  const group = document.createElement("div");
  group.className = "encumbrance-summary-mode-control";
  group.hidden = !variants.exceedsLimit;
  group.setAttribute("role", "group");
  group.setAttribute("aria-label", "Takyidat açıklaması görünümü");

  [
    ["summary", "Özet"],
    ["detail", "Detay"],
  ].forEach(([mode, label]) => {
    const button = document.createElement("button");
    button.type = "button";
    button.dataset.encumbranceSummaryMode = mode;
    button.textContent = label;
    button.addEventListener("click", () => {
      state.fields.encumbranceSummaryMode = mode;
      refreshEncumbranceSummaryFromCurrentData();
      autosave();
      renderValidation();
      updateStatus();
    });
    group.append(button);
  });

  syncEncumbranceSummaryModeControl(variants, group);
  return group;
}

function syncEncumbranceSummaryModeControl(
  variants = buildEncumbranceSummaryVariants(),
  root = document,
) {
  const groups = root.matches?.(".encumbrance-summary-mode-control")
    ? [root]
    : [...root.querySelectorAll(".encumbrance-summary-mode-control")];
  const selectedMode = variants.exceedsLimit && state.fields.encumbranceSummaryMode === "detail"
    ? "detail"
    : "summary";
  groups.forEach((group) => {
    group.hidden = !variants.exceedsLimit;
    group.querySelectorAll("[data-encumbrance-summary-mode]").forEach((button) => {
      const isSelected = button.dataset.encumbranceSummaryMode === selectedMode;
      button.classList.toggle("is-active", isSelected);
      button.setAttribute("aria-pressed", String(isSelected));
    });
  });
}

function selectEncumbranceSummaryVariant(variants, requestedMode = "summary") {
  if (!variants?.exceedsLimit) return variants?.detail || "";
  return requestedMode === "detail" ? variants.detail : variants.summary;
}

function buildEncumbranceSummary(mode = state.fields.encumbranceSummaryMode) {
  return selectEncumbranceSummaryVariant(buildEncumbranceSummaryVariants(), mode);
}

const isbankEncumbranceExplanationVariants = [
  (reviewedAt) => `TKGM (TAKBİS) kayıtlarında incelemeler ${reviewedAt} gerçekleştirilmiştir.`,
  (reviewedAt) => `TKGM (TAKBİS) kayıtları üzerinde yapılan incelemeler ${reviewedAt} tamamlanmıştır.`,
];
registerVariantGroup("buildIsbankEncumbranceExplanation", "İş Bankası TAKBİS İnceleme Tarihi Cümlesi (Takyidat)", isbankEncumbranceExplanationVariants.length);

function buildIsbankEncumbranceExplanation() {
  const date = encumbranceDateOrBila(state.fields.takbisDate);
  const time = String(state.fields.takbisTime || "").trim();
  if (!date || date === "Bila") return "";
  const reviewedAt = time ? `${date} tarihinde saat ${time}'de` : `${date} tarihinde`;
  return isbankEncumbranceExplanationVariants[selectVariant("buildIsbankEncumbranceExplanation", isbankEncumbranceExplanationVariants.length)](reviewedAt);
}

// Kullanıcı talebi: "03.08.2026 tarihinde saat 17:32 Webtapu Sistemi
// üzerinden alınan TAKBİS belgesine göre, konu taşınmaz üzerinde aşağıdaki
// takyidatlar bulunmaktadır. takyidatlar bölümünde yer alan bu açıklama
// bölümünü de ayrı bir placeholder olarak ekleyelim" — daha önce yalnızca
// buildEncumbranceSummaryVariants() İÇİNDE (birleşik özetin ilk cümlesi
// olarak) üretiliyordu; artık ayrı bir fonksiyona çıkarıldı ki hem orada
// hem yeni placeholder'da AYNI kaynak kullanılsın.
// Varyantlar docs/cumle-envanteri.md Bölüm 8'de belgelendi (TAKBİS
// alınabildiyse HER raporda birebir aynı çıkan giriş cümlesi).
registerVariantGroup("buildEncumbranceIntroSentence", "Takyidat Bölümü Giriş Cümlesi", 3);

function buildEncumbranceIntroSentence() {
  const date = encumbranceDateOrBila(state.fields.takbisDate);
  const time = String(state.fields.takbisTime || "").trim();
  const method = encumbranceTextOrBila(state.fields.takbisMethod || "Webtapu Sistemi");
  const isMultiTitleUnitReport = typeof getTitleUnitCount === "function"
    ? getTitleUnitCount() > 1
    : Array.isArray(state.titleUnits) && state.titleUnits.length > 0;
  // Kullanıcı bildirimi (2026-08-12): Çoklu Talep raporlarında her
  // taşınmazın kendi TAKBİS PDF'i genelde aynı GÜN içinde ama FARKLI
  // SAATLERDE (birkaç dakika arayla) alınmış oluyor — bu "saat", hangi
  // taşınmaz aktifken cümle üretildiyse O taşınmazınkini gösteriyordu
  // ("tek ortak açıklama" yerine taşınmaza göre değişen bir metin).
  // Çoklu talepte saat TAMAMEN KALDIRILDI, yalnızca tarih kullanılır —
  // tarih genelde aynı gün olduğundan tek ortak/kararlı bir cümle çıkar.
  // Tekli raporlarda davranış DEĞİŞMEDİ (saat varsa gösterilmeye devam eder).
  const receivedAt = (time && !isMultiTitleUnitReport) ? `${date} tarihinde saat ${time}` : `${date} tarihinde`;
  const takbisDocumentLabel = isMultiTitleUnitReport ? "TAKBİS belgelerine" : "TAKBİS belgesine";
  const subjectPropertyLabel = isMultiTitleUnitReport ? "taşınmazlar" : "taşınmaz";
  const variants = [
    `${receivedAt} ${method} üzerinden alınan ${takbisDocumentLabel} göre, konu ${subjectPropertyLabel} üzerinde aşağıdaki takyidatlar bulunmaktadır.`,
    `${receivedAt} ${method} aracılığıyla temin edilen ${takbisDocumentLabel} göre, ekspertize konu ${subjectPropertyLabel} üzerinde aşağıda belirtilen takyidatlar tespit edilmiştir.`,
    `${method} üzerinden ${receivedAt} alınan ${isMultiTitleUnitReport ? "TAKBİS kayıtlarına" : "TAKBİS kaydına"} göre, söz konusu ${subjectPropertyLabel} üzerinde aşağıdaki takyidat kalemleri bulunmaktadır.`,
  ];
  return variants[selectVariant("buildEncumbranceIntroSentence", variants.length)];
}

function getEncumbranceIntroSentenceForPlaceholder() {
  if (state.fields.takbisMethod === "Tapu Kaydı Alınmamıştır.") return "";
  const declarationRows = typeof getMultiTitleUnitEncumbranceRows === "function"
    ? getMultiTitleUnitEncumbranceRows("encumbranceDeclarations")
    : getFilledEncumbranceRows("encumbranceDeclarations");
  const mortgageRows = typeof getMultiTitleUnitEncumbranceRows === "function"
    ? getMultiTitleUnitEncumbranceRows("encumbranceMortgages")
    : getFilledEncumbranceRows("encumbranceMortgages");
  const annotationRows = typeof getMultiTitleUnitEncumbranceRows === "function"
    ? getMultiTitleUnitEncumbranceRows("encumbranceAnnotations")
    : getFilledEncumbranceRows("encumbranceAnnotations");
  const hasRows = declarationRows.length || mortgageRows.length || annotationRows.length;
  const hasTitleChange = Boolean(normalizeYesNoChoice(state.fields.titleRecordChange));
  if (!hasRows && !state.fields.takbisDate && !state.fields.takbisMethod && !hasTitleChange) return "";
  return buildEncumbranceIntroSentence();
}

const encumbranceUnavailableVariants = [
  "Talep tarihi itibarıyla konu taşınmaza ilişkin TAKBİS belgesi temin edilememiş olup, değerleme çalışması takyidat kayıtlarından bağımsız olarak gerçekleştirilmiştir.",
  "Talep tarihi itibarıyla söz konusu taşınmaza ait TAKBİS belgesine ulaşılamamış olup, değerleme çalışması takyidat kayıtları dikkate alınmaksızın yürütülmüştür.",
  "Talep tarihi itibarıyla taşınmaza ait TAKBİS kaydına erişilememiş olup, değerleme takyidat bilgisinden bağımsız olarak yürütülmüştür.",
  "Talep tarihi itibarıyla konu taşınmazın TAKBİS belgesi elde edilememiş, bu nedenle değerleme çalışması takyidat kayıtları olmaksızın gerçekleştirilmiştir.",
];
registerVariantGroup("buildEncumbranceSummaryVariants:unavailable", "TAKBİS Temin Edilemedi Açıklaması (Takyidat)", encumbranceUnavailableVariants.length);

function buildEncumbranceSummaryVariants() {
  if (state.fields.takbisMethod === "Tapu Kaydı Alınmamıştır.") {
    const detail = encumbranceUnavailableVariants[selectVariant("buildEncumbranceSummaryVariants:unavailable", encumbranceUnavailableVariants.length)];
    return { detail, summary: detail, exceedsLimit: false };
  }

  const declarationRows = typeof getMultiTitleUnitEncumbranceRows === "function"
    ? getMultiTitleUnitEncumbranceRows("encumbranceDeclarations")
    : getFilledEncumbranceRows("encumbranceDeclarations");
  const mortgageRows = typeof getMultiTitleUnitEncumbranceRows === "function"
    ? getMultiTitleUnitEncumbranceRows("encumbranceMortgages")
    : getFilledEncumbranceRows("encumbranceMortgages");
  const annotationRows = typeof getMultiTitleUnitEncumbranceRows === "function"
    ? getMultiTitleUnitEncumbranceRows("encumbranceAnnotations")
    : getFilledEncumbranceRows("encumbranceAnnotations");
  const hasRows = declarationRows.length || mortgageRows.length || annotationRows.length;
  const hasTitleChange = Boolean(normalizeYesNoChoice(state.fields.titleRecordChange));
  if (!hasRows && !state.fields.takbisDate && !state.fields.takbisMethod && !hasTitleChange) {
    return { detail: "", summary: "", exceedsLimit: false };
  }

  const date = encumbranceDateOrBila(state.fields.takbisDate);
  const method = encumbranceTextOrBila(state.fields.takbisMethod || "Webtapu Sistemi");
  const declarationRowsWithoutRights = declarationRows.filter((row) => !isEncumbranceRightOrLiabilityRow(row));
  const easementRows = declarationRows.filter(isEncumbranceRightOrLiabilityRow);
  const intro = buildEncumbranceIntroSentence();
  const sections = [
    {
      key: "declarations",
      detail: buildEncumbranceSectionParagraph(
      "Beyanlar Bölümü",
      declarationRowsWithoutRights,
      (row) => formatEncumbranceDeclarationRow(row, { addIsbankManagementPlanNote: true }),
      ),
      summary: buildCondensedEncumbranceSectionSummary(
        "Beyanlar Bölümü",
        declarationRowsWithoutRights.length,
        "beyan",
      ),
    },
    {
      key: "easements",
      detail: buildEncumbranceSectionParagraph(
        "Hak ve Mükellefiyetler Bölümü",
        easementRows,
        formatEncumbranceDeclarationRow,
      ),
      summary: buildCondensedEncumbranceSectionSummary(
        "Hak ve Mükellefiyetler Bölümü",
        easementRows.length,
        "hak ve mükellefiyet",
      ),
    },
    {
      key: "mortgages",
      detail: buildEncumbranceSectionParagraph(
        "İpotekler Bölümü",
        mortgageRows,
        formatEncumbranceMortgageRow,
      ),
      summary: buildCondensedEncumbranceSectionSummary(
        "İpotekler Bölümü",
        mortgageRows.length,
        "ipotek",
      ),
    },
    {
      key: "annotations",
      detail: buildEncumbranceSectionParagraph(
        "Şerhler Bölümü",
        annotationRows,
        formatEncumbranceAnnotationRow,
      ),
      summary: annotationRows.length
        ? `Şerhler Bölümü:\n${buildCondensedAnnotationSummary(annotationRows)}`
        : buildEncumbranceSectionParagraph("Şerhler Bölümü", [], formatEncumbranceAnnotationRow),
    },
  ];

  const titleChangeParagraph = buildEncumbranceTitleRecordChangeParagraph(date, method);
  const detail = normalizeEncumbranceSummaryText(
    [intro, ...sections.map((section) => section.detail), titleChangeParagraph]
      .filter(Boolean)
      .join("\n\n"),
  );
  const exceedsLimit = detail.length > 2000;
  if (!exceedsLimit) {
    return { detail, summary: detail, exceedsLimit: false };
  }

  const summary = buildAdaptiveEncumbranceSummary({
    intro,
    sections,
    tail: titleChangeParagraph,
    maxLength: 2000,
  });
  return { detail, summary, exceedsLimit: true };
}

function normalizeEncumbranceSummaryText(value) {
  return normalizeReportDescriptionText(value)
    .replace(/\b(A\.Ş\.|T\.A\.O\.|T\.A\.Ş\.|Ltd\. Şti\.)\s+Lehine\b/g, "$1 lehine");
}

function getEncumbranceNumericCounts(rows = {}) {
  const declarationRows = Array.isArray(rows.declarationRows)
    ? rows.declarationRows
    : getFilledEncumbranceRows("encumbranceDeclarations");
  const mortgageRows = Array.isArray(rows.mortgageRows)
    ? rows.mortgageRows
    : getFilledEncumbranceRows("encumbranceMortgages");
  const annotationRows = Array.isArray(rows.annotationRows)
    ? rows.annotationRows
    : getFilledEncumbranceRows("encumbranceAnnotations");
  const easements = declarationRows.filter(isEncumbranceRightOrLiabilityRow).length;
  const declarations = declarationRows.length - easements;
  const mortgages = mortgageRows.length;
  const annotations = annotationRows.length;
  return {
    declarations,
    mortgages,
    annotations,
    easements,
    total: declarations + mortgages + annotations + easements,
  };
}

function classifyEncumbranceAnnotation(row) {
  const text = foldTurkish([row?.c0, row?.c1].filter(Boolean).join(" "));
  if (/\bIHTIYATI\s+HACIZ/.test(text)) return "precautionary";
  if (/\bKAMU\s+HACZI|\bKAMU\s+HACIZ/.test(text)) return "public";
  if (/\bICRAI\s+HACIZ|\bICRA\s+HACZI|\bICRA\s+HACIZ/.test(text)) return "enforcement";
  return "other";
}

function buildCondensedAnnotationSummary(rows = []) {
  const counts = {
    enforcement: 0,
    public: 0,
    precautionary: 0,
    other: 0,
  };
  rows.forEach((row) => {
    counts[classifyEncumbranceAnnotation(row)] += 1;
  });
  const phrases = [
    counts.enforcement ? `${counts.enforcement} adet icrai haciz` : "",
    counts.public ? `${counts.public} adet kamu haczi` : "",
    counts.precautionary ? `${counts.precautionary} adet ihtiyati haciz` : "",
    counts.other ? `${counts.other} adet diğer tür şerh` : "",
  ].filter(Boolean);
  const list = phrases.length > 1
    ? `${phrases.slice(0, -1).join(", ")} ve ${phrases.at(-1)}`
    : phrases[0] || "herhangi bir şerh";
  return `Taşınmaz üzerinde şerh türüne göre ${list} kaydı bulunmaktadır. Şerh kayıtları karakter kısıtlaması sebebiyle rapor ekinde tablo olarak tarafınıza sunulmuştur.`;
}

function buildCondensedEncumbranceSectionSummary(title, count, recordLabel) {
  if (!count) return `${title}:\nHerhangi bir kayıt bulunmamaktadır.`;
  return `${title}:\nTaşınmaz üzerinde ${count} adet ${recordLabel} kaydı bulunmaktadır. Bu bölümdeki kayıtlar karakter kısıtlaması sebebiyle rapor ekinde tablo olarak tarafınıza sunulmuştur.`;
}

function buildAdaptiveEncumbranceSummary({
  intro = "",
  sections = [],
  tail = "",
  maxLength = 2000,
} = {}) {
  const workingSections = sections.map((section) => ({
    detail: String(section?.detail || "").trim(),
    summary: String(section?.summary || section?.detail || "").trim(),
    condensed: false,
  }));
  const compose = () => normalizeEncumbranceSummaryText(
    [intro, ...workingSections.map((section) => (section.condensed ? section.summary : section.detail)), tail]
      .filter(Boolean)
      .join("\n\n"),
  );
  let result = compose();
  if (result.length <= maxLength) return result;

  const condensationOrder = workingSections
    .map((section, index) => ({
      index,
      detailLength: section.detail.length,
      saving: section.detail.length - section.summary.length,
    }))
    .filter((item) => item.saving > 0)
    .sort((left, right) => right.detailLength - left.detailLength || right.saving - left.saving);

  for (const item of condensationOrder) {
    workingSections[item.index].condensed = true;
    result = compose();
    if (result.length <= maxLength) return result;
  }

  const requiredSections = workingSections
    .map((section) => section.summary)
    .filter(Boolean);
  const requiredTail = [...requiredSections, tail].filter(Boolean).join("\n\n");
  return limitEncumbranceSummaryCharacters(result, maxLength, requiredTail);
}

function limitEncumbranceSummaryCharacters(value, maxLength = 2000, requiredTail = "") {
  const text = String(value || "").trim();
  if (text.length <= maxLength) return text;
  const normalizedTail = String(requiredTail || "").trim();
  const fallbackNotice = "Karakter kısıtlaması sebebiyle devam eden takyidat kayıtları rapor ekinde tablo olarak tarafınıza sunulmuştur.";
  const suffix = `\n\n${normalizedTail || fallbackNotice}`;
  const tailIndex = normalizedTail ? text.lastIndexOf(normalizedTail) : -1;
  const bodySource = tailIndex >= 0 ? text.slice(0, tailIndex).trim() : text;
  const available = Math.max(0, maxLength - suffix.length);
  const candidate = bodySource.slice(0, available);
  const lineEnd = candidate.lastIndexOf("\n");
  const sentenceEnd = Math.max(candidate.lastIndexOf("."), candidate.lastIndexOf(";"));
  const safeEnd = lineEnd > 0 ? lineEnd : sentenceEnd + 1;
  const body = candidate.slice(0, safeEnd > available * 0.65 ? safeEnd : available).trim();
  return `${body}${suffix}`.slice(0, maxLength);
}

// ==========================================================
//  Takyidat Tablosu (14 - Açıklamalar bölümü)
//  Beyanlar / Hak ve Mükellefiyetler / Rehinler / Şerhler alt
//  başlıkları altında, mevcut takyidat verisinden otomatik üretilir.
// ==========================================================
function buildTakyidatTableGroups() {
  const declarationRows = getFilledEncumbranceRows("encumbranceDeclarations");
  return [
    {
      key: "beyan",
      title: "Beyanlar",
      items: declarationRows
        .filter((row) => !isEncumbranceRightOrLiabilityRow(row))
        .map((row) => formatEncumbranceDeclarationRow(row, { addIsbankManagementPlanNote: true }))
        .filter(Boolean),
    },
    {
      key: "hak",
      title: "Hak ve Mükellefiyetler",
      items: declarationRows
        .filter(isEncumbranceRightOrLiabilityRow)
        .map((row) => formatEncumbranceDeclarationRow(row))
        .filter(Boolean),
    },
    {
      key: "rehin",
      title: "Rehinler",
      items: getFilledEncumbranceRows("encumbranceMortgages")
        .map(formatEncumbranceMortgageRow)
        .filter(Boolean),
    },
    {
      key: "serh",
      title: "Şerhler",
      items: getFilledEncumbranceRows("encumbranceAnnotations")
        .map(formatEncumbranceAnnotationRow)
        .filter(Boolean),
    },
  ];
}

function hasTakyidatTableData() {
  return buildTakyidatTableGroups().some((group) => group.items.length);
}

function createEncumbranceCountSummaryPanel() {
  const counts = getEncumbranceNumericCounts();
  const panel = document.createElement("div");
  panel.className = "subsection encumbrance-count-panel";

  const title = document.createElement("h4");
  title.textContent = "Takyidat Sayısal Verileri";
  panel.append(title);

  const shell = document.createElement("div");
  shell.className = "table-shell encumbrance-count-table-shell";
  const table = document.createElement("table");
  table.className = "encumbrance-count-table";
  table.innerHTML = `
    <thead>
      <tr>
        <th>Beyanlar Bölümü</th>
        <th>Rehinler (İpotekler) Bölümü</th>
        <th>Şerhler Bölümü</th>
        <th>İrtifaklar Bölümü</th>
      </tr>
    </thead>
    <tbody>
      <tr>
        <td>${counts.declarations}</td>
        <td>${counts.mortgages}</td>
        <td>${counts.annotations}</td>
        <td>${counts.easements}</td>
      </tr>
    </tbody>
  `;
  shell.append(table);
  panel.append(shell);
  return panel;
}

function buildTakyidatTableText() {
  return buildTakyidatTableGroups()
    .map((group) => {
      const lines = group.items.length
        ? group.items.map((item, index) => `${index + 1}. ${item}`)
        : ["Herhangi bir kayıt bulunmamaktadır."];
      return `${group.title}:\n${lines.join("\n")}`;
    })
    .join("\n\n");
}

function createTakyidatTablePanel() {
  const groups = buildTakyidatTableGroups();
  const hasData = groups.some((group) => group.items.length);
  const panel = document.createElement("div");
  panel.className = "subsection takyidat-table-panel";

  const head = document.createElement("div");
  head.className = "subsection-title-row";
  const title = document.createElement("h4");
  title.textContent = "Takyidat Tablosu";
  head.append(title);
  if (hasData) {
    const copyButton = document.createElement("button");
    copyButton.type = "button";
    copyButton.className = "valuation-method-copy-button";
    copyButton.textContent = "Kopyala";
    copyButton.title = "Takyidat tablosunu metin olarak kopyala";
    copyButton.addEventListener("click", async () => {
      try {
        await navigator.clipboard.writeText(buildTakyidatTableText());
        copyButton.textContent = "Kopyalandı";
      } catch {
        copyButton.textContent = "Kopyalanamadı";
      }
      setTimeout(() => {
        copyButton.textContent = "Kopyala";
      }, 1500);
    });
    head.append(copyButton);
  }
  panel.append(head);

  const hint = document.createElement("p");
  hint.className = "subtle-text";
  hint.textContent = "Takyidat bölümüne girilen kayıtlar; Beyanlar, Hak ve Mükellefiyetler, Rehinler ve Şerhler başlıkları altında otomatik listelenir.";
  panel.append(hint);

  if (!hasData) {
    const note = document.createElement("p");
    note.className = "subtle-text takyidat-empty-note";
    note.textContent = "Henüz takyidat kaydı girilmedi. Takyidat bölümünden kayıt eklendiğinde tablo burada otomatik oluşacaktır.";
    panel.append(note);
    return panel;
  }

  const shell = document.createElement("div");
  shell.className = "table-shell takyidat-table-shell";
  const table = document.createElement("table");
  table.className = "takyidat-table";
  const tbody = document.createElement("tbody");

  groups.forEach((group) => {
    const groupRow = document.createElement("tr");
    groupRow.className = `takyidat-group-row takyidat-group-${group.key}`;
    const groupCell = document.createElement("th");
    groupCell.colSpan = 2;
    groupCell.textContent = group.title.toLocaleUpperCase("tr-TR");
    groupRow.append(groupCell);
    tbody.append(groupRow);

    if (!group.items.length) {
      const emptyRow = document.createElement("tr");
      emptyRow.className = "takyidat-empty-row";
      const emptyCell = document.createElement("td");
      emptyCell.colSpan = 2;
      emptyCell.textContent = "Herhangi bir kayıt bulunmamaktadır.";
      emptyRow.append(emptyCell);
      tbody.append(emptyRow);
      return;
    }

    group.items.forEach((item, index) => {
      const tr = document.createElement("tr");
      const noCell = document.createElement("td");
      noCell.className = "takyidat-no";
      noCell.textContent = String(index + 1);
      const textCell = document.createElement("td");
      textCell.textContent = item;
      tr.append(noCell, textCell);
      tbody.append(tr);
    });
  });

  table.append(tbody);
  shell.append(table);
  panel.append(shell);
  return panel;
}

// ==========================================================
//  Açık Adres (14 - Açıklamalar bölümü)
//  İdari mahalle, sokak/cadde, site/apartman, blok, dış kapı, kat,
//  iç kapı, ilçe/il ve UAVT kodundan Türkçe adres metni üretir.
//  Örnek: "Görükle Mahallesi, Koza Caddesi, Atalay Apartmanı No: 26,
//          Kat: 1. kat, D: 4 Nilüfer / Bursa (UAVT Kodu: 1234567)"
// ==========================================================
// Açık adres tam yazım/kısaltma STİLİ — kullanıcı talebi (2026-08-08):
// "açık adres için varyantlar var mı? yoksa mahalle cadde sokak eklentilerini
// kısaltabilir yada uzatabilirsin". Gerçek değerleme uzmanları arasında da bu
// tür resmi kısaltmalar (Mah./Apt./Sit./K./No.) değişkenlik gösterir. Bir stil
// TÜM adres BİR KEZ seçilip tutarlı uygulanır (composeImarPlanningStatusParagraphs'daki
// "genel fiil-dönüşüm stili" deseniyle aynı gerekçe — aynı raporda "Mahallesi"
// ile "Apt." karışık görünmesin). Adresin KENDİSİ (il/ilçe/mahalle/sokak adı,
// kapı no vb.) DEĞİŞMEZ — yalnızca resmi ek kelimelerin tam/kısa yazımı değişir.
const openAddressStyleVariants = [
  { neighborhoodSuffix: " Mahallesi", neighborhoodShortRe: /mahalle|mah\.?$/i, apartmanSuffix: " Apartmanı", apartmanRe: /apartman/i, apartmanStripRe: /\s+apartman(?:ı|i)?$/i, siteSuffix: " Sitesi", siteRe: /site/i, siteStripRe: /\s+site(?:si)?$/i, blokSuffix: " Blok", noLabel: "No: ", katLabel: "Kat: ", daireLabel: "D: " },
  { neighborhoodSuffix: " Mah.", neighborhoodShortRe: /mahalle|mah\.?$/i, apartmanSuffix: " Apt.", apartmanRe: /apartman/i, apartmanStripRe: /\s+apartman(?:ı|i)?$/i, siteSuffix: " Sit.", siteRe: /site/i, siteStripRe: /\s+site(?:si)?$/i, blokSuffix: " Blok", noLabel: "No: ", katLabel: "K: ", daireLabel: "D: " },
];
registerVariantGroup("buildOpenAddressText:style", "Açık Adres — Tam Yazım/Kısaltma Stili (Adres/Konum/Çevre)", openAddressStyleVariants.length);

function formatOpenAddressNeighborhood(value, style) {
  const text = String(value || "").trim();
  if (!text) return "";
  return style.neighborhoodShortRe.test(text) ? text : `${text}${style.neighborhoodSuffix}`;
}

function formatOpenAddressBuildingName(value, style) {
  const text = String(value || "").trim().replace(/\s+/g, " ");
  if (!text) return "";
  if (style.apartmanRe.test(text)) return text.replace(style.apartmanStripRe, "").trim() + style.apartmanSuffix;
  if (style.siteRe.test(text)) return text.replace(style.siteStripRe, "").trim() + style.siteSuffix;
  // Adres kodu alanı türü ayrı vermediğinde bloklu adları site olarak adlandırırız.
  return `${text}${style.siteSuffix}`;
}

function buildOpenAddressText() {
  if (isLandPropertyForBankTemplate() || isLandProjectReview()) return buildLandOpenAddressText();

  const get = (...keys) => {
    for (const key of keys) {
      const value = String(state.fields[key] || "").trim();
      if (value) return value;
    }
    return "";
  };
  const neighborhood = get("neighborhood", "titleNeighborhood");
  const street = get("street");
  const siteName = get("addressSiteName");
  const blockName = get("addressBlockName", "titleBlockName");
  const outerDoor = get("outerDoor");
  const floor = get("addressFloor", "titleFloor");
  const innerDoor = get("innerDoor");
  const district = get("district", "titleDistrict");
  const city = get("city", "titleCity");
  const uavt = get("uavt");
  const style = openAddressStyleVariants[selectVariant("buildOpenAddressText:style", openAddressStyleVariants.length)];

  const segments = [];
  if (neighborhood) segments.push(formatOpenAddressNeighborhood(neighborhood, style));
  if (street) segments.push(street);

  const buildingParts = [];
  if (siteName) buildingParts.push(formatOpenAddressBuildingName(siteName, style));
  if (blockName) buildingParts.push(/blok/i.test(blockName) ? blockName : `${blockName}${style.blokSuffix}`);
  if (outerDoor) buildingParts.push(`${style.noLabel}${outerDoor}`);
  if (buildingParts.length) segments.push(buildingParts.join(" "));

  if (floor) segments.push(`${style.katLabel}${floor}`);

  const lastParts = [];
  if (innerDoor) lastParts.push(`${style.daireLabel}${innerDoor}`);
  const districtCity = [district, city].filter(Boolean).join(" / ");
  if (districtCity) lastParts.push(districtCity);
  if (lastParts.length) segments.push(lastParts.join(" "));

  let result = segments.join(", ");
  if (result && uavt) result += ` (UAVT Kodu: ${uavt})`;
  return result;
}

function buildLandOpenAddressText() {
  const get = (...keys) => {
    for (const key of keys) {
      const value = String(state.fields[key] || "").trim();
      if (value) return value;
    }
    return "";
  };

  const neighborhood = get("neighborhood", "titleNeighborhood");
  const locationName = get("locationName");
  const street = get("street");
  const blockNo = get("blockNo");
  const parcelNo = get("parcelNo");
  const district = get("district", "titleDistrict");
  const city = get("city", "titleCity");

  const segments = [];
  if (neighborhood) segments.push(formatOpenAddressNeighborhood(neighborhood, openAddressStyleVariants[0]));
  if (locationName) segments.push(`Mevkii ${locationName}`);
  if (street) segments.push(street);
  if (blockNo || parcelNo) {
    const parcel = [blockNo ? `${blockNo} Ada` : "", parcelNo ? `${parcelNo} Parsel` : ""]
      .filter(Boolean)
      .join(" ");
    if (parcel) segments.push(parcel);
  }
  const districtCity = [district, city].filter(Boolean).join(" / ");
  if (districtCity) segments.push(districtCity);
  return segments.join(", ");
}
function createOpenAddressPanel() {
  const address = buildOpenAddressText();
  state.fields.openAddress = address;
  const card = document.createElement("div");
  card.className = "subsection open-address-card";

  const head = document.createElement("div");
  head.className = "open-address-head";
  const title = document.createElement("h4");
  title.textContent = "Açık Adres";
  head.append(title);
  if (address) {
    const copyButton = document.createElement("button");
    copyButton.type = "button";
    copyButton.className = "valuation-method-copy-button";
    copyButton.textContent = "Kopyala";
    copyButton.title = "Açık adres metnini kopyala";
    copyButton.addEventListener("click", async () => {
      try {
        await navigator.clipboard.writeText(address);
        copyButton.textContent = "Kopyalandı";
      } catch {
        copyButton.textContent = "Kopyalanamadı";
      }
      setTimeout(() => {
        copyButton.textContent = "Kopyala";
      }, 1500);
    });
    head.append(copyButton);
  }
  card.append(head);

  const text = document.createElement("p");
  text.className = "open-address-text";
  text.textContent = address || "Adres ve Konum bölümündeki alanlar doldurulduğunda açık adres metni burada otomatik oluşacaktır.";
  if (!address) text.classList.add("open-address-empty");
  card.append(text);
  return card;
}

// ==========================================================
//  Malikler Tablosu (14 - Açıklamalar bölümü)
//  Hisse yasal/mevcut durum değerleri, değerleme bölümündeki toplam
//  yasal/mevcut değerlerden hisse oranına göre otomatik hesaplanır.
//  Toplam değer henüz girilmemişse hisse değeri 0 gösterilir.
// ==========================================================
function getMaliklerOwnerRows() {
  return (state.tables.title || []).filter((row) => String(row?.c0 || "").trim());
}

// template-engine.js'in kendi (yerel/kapsam-içi) firstTitleRowCell()'inin
// app.js karşılığı — {{TAPU_TARİHİ}}/{{TAPU_YEVMİYESİ}} gibi ilk dolu tapu
// satırından okunan alanların "Placeholder" ekranı kataloğunda GERÇEK
// dışa aktarım değeriyle tutarlı görünmesi için (kullanıcı bildirimi:
// "placeholder bölümünde gözükmüyor").
function getFirstFilledTitleRow() {
  const rows = Array.isArray(state.tables?.title) ? state.tables.title : [];
  return rows.find((row) => Object.values(row || {}).some((value) => String(value || "").trim())) || null;
}

function parseOwnerShareComponent(value) {
  const number = Number.parseFloat(String(value || "").replace(/\s/g, "").replace(",", "."));
  return Number.isFinite(number) ? number : Number.NaN;
}

function parseOwnerShareRatioValue(shareText) {
  const text = cleanTakbisValue(shareText);
  if (!text) return Number.NaN;
  if (/tam/i.test(text)) return 1;
  const [payRaw, paydaRaw] = splitFirst(text, "/");
  const pay = parseOwnerShareComponent(payRaw);
  if (paydaRaw) {
    const payda = parseOwnerShareComponent(paydaRaw);
    return Number.isFinite(pay) && Number.isFinite(payda) && payda !== 0 ? pay / payda : Number.NaN;
  }
  return Number.isFinite(pay) ? pay : Number.NaN;
}

function formatMaliklerShareValue(value) {
  if (!Number.isFinite(value) || value <= 0) return "0";
  return `${Math.round(value).toLocaleString("tr-TR")} TL`;
}

function buildMaliklerTableRows() {
  const owners = getMaliklerOwnerRows();
  const legalTotal = parseValuationNumber(state.fields.legalValue);
  const currentTotal = parseValuationNumber(state.fields.currentValue);
  const ownerCount = owners.length;
  return owners.map((row) => {
    const share = cleanTakbisValue(row.c1);
    let ratio = parseOwnerShareRatioValue(share);
    if (!Number.isFinite(ratio) && ownerCount === 1) ratio = 1;
    const legalShareValue = Number.isFinite(ratio) && Number.isFinite(legalTotal) ? ratio * legalTotal : 0;
    const currentShareValue = Number.isFinite(ratio) && Number.isFinite(currentTotal) ? ratio * currentTotal : 0;
    return {
      malik: String(row.c0 || "").trim().toLocaleUpperCase("tr-TR"),
      share: share || "-",
      reason: String(row.c2 || "").trim() || "-",
      deedDate: (dateIsoToTr(String(row.c3 || "").trim()) || "").trim() || "-",
      journal: String(row.c4 || "").trim() || "-",
      legalShareValue,
      currentShareValue,
    };
  });
}

function hasMaliklerTableData() {
  return getMaliklerOwnerRows().length > 0;
}

function buildMaliklerTableText() {
  const rows = buildMaliklerTableRows();
  if (!rows.length) return "";
  const header = ["Malik / Hissedar", "Hisse Payı", "Edinme Sebebi", "Tapu Tarihi", "Yevmiye", "Hisse Yasal Durum Değeri", "Hisse Mevcut Durum Değeri"].join(" | ");
  const lines = rows.map((row) => [
    row.malik,
    row.share,
    row.reason,
    row.deedDate,
    row.journal,
    formatMaliklerShareValue(row.legalShareValue),
    formatMaliklerShareValue(row.currentShareValue),
  ].join(" | "));
  return [header, ...lines].join("\n");
}

// Ekrandaki "Malikler Tablosu" panelinin (bkz. createMaliklerTablePanel,
// .malikler-table) BIREBIR ayni yapida Word/HTML karsiligi: 7 sutun, deger
// sutunlari sag hizali/tabular, ilk sutun kalin, en altta TOPLAM satiri
// (koyu zemin + beyaz yazi). Renkler satir ici stille sabitlenir; hangi
// banka sablonuna yerlestirilirse yerlestirilsin ayni gorunur.
function buildMaliklerTableWordHtml() {
  const rows = buildMaliklerTableRows();
  if (!rows.length) return "";
  const line = getReportThemeToken("--line", "#dde3ef");
  const blue = getReportThemeToken("--blue", "#3a5691");
  const blueSoft = getReportThemeToken("--blue-soft", "#e4ebf8");
  const surfaceMuted = getReportThemeToken("--surface-muted", "#eef2fa");
  const border = `border:1pt solid ${line};`;
  const cellPad = "padding:2.4pt 3pt;vertical-align:top;line-height:1.1;";
  const headerCell = `${border}${cellPad}background:${surfaceMuted};color:${blue};font-weight:800;text-align:center;`;
  const nameCell = `${border}${cellPad}font-weight:700;text-align:left;`;
  const plainCell = `${border}${cellPad}text-align:center;`;
  const valueCell = `${border}${cellPad}text-align:right;white-space:nowrap;`;
  const zebraExtra = `background:${surfaceMuted};`;
  const totalCell = `${border}${cellPad}background:${blue};color:#ffffff;font-weight:800;`;
  const headers = ["Malik / Hissedar", "Hisse Payı", "Edinme Sebebi", "Tapu Tarihi", "Yevmiye", "Hisse Yasal Durum Değeri", "Hisse Mevcut Durum Değeri"];
  const theadHtml = `<tr>${headers.map((header) => `<th style="${headerCell}">${escapeHtml(header)}</th>`).join("")}</tr>`;
  const bodyHtml = rows.map((row, rowIndex) => {
    const zebra = rowIndex % 2 === 1 ? zebraExtra : "";
    return `<tr>
      <td style="${nameCell}${zebra}">${escapeHtml(row.malik)}</td>
      <td style="${plainCell}${zebra}">${escapeHtml(row.share)}</td>
      <td style="${plainCell}${zebra}">${escapeHtml(row.reason)}</td>
      <td style="${plainCell}${zebra}">${escapeHtml(row.deedDate)}</td>
      <td style="${plainCell}${zebra}">${escapeHtml(row.journal)}</td>
      <td style="${valueCell}${zebra}">${escapeHtml(formatMaliklerShareValue(row.legalShareValue))}</td>
      <td style="${valueCell}${zebra}">${escapeHtml(formatMaliklerShareValue(row.currentShareValue))}</td>
    </tr>`;
  }).join("");
  const legalSum = rows.reduce((sum, row) => sum + (Number.isFinite(row.legalShareValue) ? row.legalShareValue : 0), 0);
  const currentSum = rows.reduce((sum, row) => sum + (Number.isFinite(row.currentShareValue) ? row.currentShareValue : 0), 0);
  const totalHtml = `<tr>
    <th colspan="5" style="${totalCell}text-align:right;">TOPLAM</th>
    <td style="${totalCell}text-align:right;white-space:nowrap;">${escapeHtml(formatMaliklerShareValue(legalSum))}</td>
    <td style="${totalCell}text-align:right;white-space:nowrap;">${escapeHtml(formatMaliklerShareValue(currentSum))}</td>
  </tr>`;
  return `<table class="word-table" style="border-collapse:collapse;width:100%;margin:5pt 0 12pt;table-layout:fixed;font-size:7pt;">
    <thead>${theadHtml}</thead>
    <tbody>${bodyHtml}</tbody>
    <tfoot>${totalHtml}</tfoot>
  </table>`;
}

function createMaliklerTablePanel() {
  const rows = buildMaliklerTableRows();
  const panel = document.createElement("div");
  panel.className = "subsection malikler-table-panel";

  const head = document.createElement("div");
  head.className = "subsection-title-row";
  const title = document.createElement("h4");
  title.textContent = "Malikler Tablosu";
  head.append(title);
  if (rows.length) {
    const copyButton = document.createElement("button");
    copyButton.type = "button";
    copyButton.className = "valuation-method-copy-button";
    copyButton.textContent = "Kopyala";
    copyButton.title = "Malikler tablosunu metin olarak kopyala";
    copyButton.addEventListener("click", async () => {
      try {
        await navigator.clipboard.writeText(buildMaliklerTableText());
        copyButton.textContent = "Kopyalandı";
      } catch {
        copyButton.textContent = "Kopyalanamadı";
      }
      setTimeout(() => {
        copyButton.textContent = "Kopyala";
      }, 1500);
    });
    head.append(copyButton);
  }
  panel.append(head);

  const hint = document.createElement("p");
  hint.className = "subtle-text";
  hint.textContent = "Tapu ve Mülkiyet bölümündeki malikler listelenir. Hisse yasal/mevcut durum değerleri, değerleme bölümündeki toplam değerlerden hisse oranına göre otomatik hesaplanır (toplam değer girilmemişse 0).";
  panel.append(hint);

  if (!rows.length) {
    const note = document.createElement("p");
    note.className = "subtle-text malikler-empty-note";
    note.textContent = "Henüz malik girilmedi. Tapu ve Mülkiyet bölümünden malik eklendiğinde tablo burada otomatik oluşacaktır.";
    panel.append(note);
    return panel;
  }

  const shell = document.createElement("div");
  shell.className = "table-shell malikler-table-shell";
  const table = document.createElement("table");
  table.className = "malikler-table";
  table.innerHTML = `
    <thead>
      <tr>
        <th>Malik / Hissedar</th>
        <th>Hisse Payı</th>
        <th>Edinme Sebebi</th>
        <th>Tapu Tarihi</th>
        <th>Yevmiye</th>
        <th class="malikler-value-col">Hisse Yasal Durum Değeri</th>
        <th class="malikler-value-col">Hisse Mevcut Durum Değeri</th>
      </tr>
    </thead>
  `;
  const tbody = document.createElement("tbody");
  rows.forEach((row) => {
    const tr = document.createElement("tr");
    [row.malik, row.share, row.reason, row.deedDate, row.journal].forEach((value) => {
      const td = document.createElement("td");
      td.textContent = value;
      tr.append(td);
    });
    const legalCell = document.createElement("td");
    legalCell.className = "malikler-value-col";
    legalCell.textContent = formatMaliklerShareValue(row.legalShareValue);
    const currentCell = document.createElement("td");
    currentCell.className = "malikler-value-col";
    currentCell.textContent = formatMaliklerShareValue(row.currentShareValue);
    tr.append(legalCell, currentCell);
    tbody.append(tr);
  });
  table.append(tbody);

  const legalSum = rows.reduce((sum, row) => sum + (Number.isFinite(row.legalShareValue) ? row.legalShareValue : 0), 0);
  const currentSum = rows.reduce((sum, row) => sum + (Number.isFinite(row.currentShareValue) ? row.currentShareValue : 0), 0);
  const tfoot = document.createElement("tfoot");
  const totalRow = document.createElement("tr");
  totalRow.className = "malikler-total-row";
  const totalLabel = document.createElement("th");
  totalLabel.colSpan = 5;
  totalLabel.textContent = "TOPLAM";
  const legalTotalCell = document.createElement("td");
  legalTotalCell.className = "malikler-value-col";
  legalTotalCell.textContent = formatMaliklerShareValue(legalSum);
  const currentTotalCell = document.createElement("td");
  currentTotalCell.className = "malikler-value-col";
  currentTotalCell.textContent = formatMaliklerShareValue(currentSum);
  totalRow.append(totalLabel, legalTotalCell, currentTotalCell);
  tfoot.append(totalRow);
  table.append(tfoot);

  shell.append(table);
  panel.append(shell);
  return panel;
}

function getFilledEncumbranceRows(tableKey) {
  return (state.tables[tableKey] || []).filter((row) => hasMeaningfulEncumbranceTableRow(tableKey, row));
}

function getEncumbranceRowJournalNo(tableKey, row) {
  const column = tableKey === "encumbranceDeclarations" ? "c3" : "c4";
  return encumbranceCleanText(row?.[column] || "");
}

function formatTitleUnitEncumbranceReference(fields = {}, index = 0, compact = false) {
  const block = encumbranceCleanText(fields.blockNo);
  const parcel = encumbranceCleanText(fields.parcelNo);
  const unitNo = encumbranceCleanText(fields.unitNo);
  const buildingBlock = encumbranceCleanText(fields.titleBlockName || fields.addressBlockName || block);
  if (compact && buildingBlock && unitNo) return `${buildingBlock}-${unitNo}`;
  if (block && parcel && unitNo) return `${block} ada ${parcel} parsel, ${unitNo} no.lu B.B.`;
  if (block && parcel) return `${block} ada ${parcel} parsel`;
  if (fields.titlePropertyId) return `${encumbranceCleanText(fields.titlePropertyId)} kimlik no.lu taşınmaz`;
  return `${index + 1}. taşınmaz`;
}

function groupEncumbranceRowsAcrossTitleUnits(rowsByUnit = [], tableKey = "") {
  const grouped = new Map();
  rowsByUnit.forEach(({ rows = [], fields = {}, index = 0 }) => {
    rows.forEach((row, rowIndex) => {
      const journalNo = getEncumbranceRowJournalNo(tableKey, row);
      const key = journalNo ? `journal:${journalNo}` : `unit:${index}:row:${rowIndex}`;
      const existing = grouped.get(key);
      const groupEntries = journalNo
        ? rowsByUnit.filter((entry) => entry.rows.some((entryRow) => getEncumbranceRowJournalNo(tableKey, entryRow) === journalNo))
        : [{ fields, index }];
      const firstEntry = groupEntries[0];
      const sameParcel = groupEntries.every(
        (entry) => encumbranceCleanText(entry.fields?.blockNo) === encumbranceCleanText(firstEntry.fields?.blockNo)
          && encumbranceCleanText(entry.fields?.parcelNo) === encumbranceCleanText(firstEntry.fields?.parcelNo),
      );
      const reference = formatTitleUnitEncumbranceReference(fields, index, sameParcel);
      if (existing) {
        if (!existing.__titleUnitReferences.includes(reference)) existing.__titleUnitReferences.push(reference);
        return;
      }
      grouped.set(key, { ...row, __titleUnitReferences: [reference] });
    });
  });
  return [...grouped.values()];
}

function getMultiTitleUnitEncumbranceRows(tableKey) {
  if (getTitleUnitCount() <= 1) return getFilledEncumbranceRows(tableKey);
  const rowsByUnit = Array.from({ length: getTitleUnitCount() }, (_, index) => {
    const tables = getTitleUnitTablesForLabel(index);
    const rows = (tables?.[tableKey] || []).filter((row) => hasMeaningfulEncumbranceTableRow(tableKey, row));
    return { rows, fields: getTitleUnitFieldsForLabel(index), index };
  });
  return groupEncumbranceRowsAcrossTitleUnits(rowsByUnit, tableKey);
}

function hasMeaningfulEncumbranceTableRow(tableKey, row) {
  const keys = tableKey === "encumbranceMortgages" ? ["c0", "c1", "c2"] : Object.keys(row || {});
  return keys.some((key) => String(row?.[key] || "").trim());
}

// Kullanıcı talebi (2026-08-12): "Takyidat Excel tablosunda ortak/ayrı
// kayıtlar nasıl belirtiliyor" — Bölüm Excel'i (getSectionExcelRows) HAM
// veriyi taşınmaz başına ayrı tutar, ortak/ayrı bilgisini HİÇ göstermez;
// bu bilgi yalnızca RAPOR METNİ üretilirken (formatEncumbranceTitleUnitScope)
// yevmiye numarasından OTOMATIK hesaplanır. Kullanıcı bu hesaplamanın
// AYRI, salt-okunur bir özet Excel'i olarak da indirilebilmesini istedi —
// mevcut Bölüm Excel'inden BAĞIMSIZ, içe aktarımı YOK (yevmiye eşleşmesi
// TEK doğru kaynak olarak kalsın diye kasıtlı olarak salt-okunur).
const ENCUMBRANCE_MULTI_UNIT_SUMMARY_TABLES = [
  { key: "encumbranceDeclarations", label: "Beyanlar / Hak ve Mükellefiyetler", formatter: (row) => formatEncumbranceDeclarationRow(row) },
  { key: "encumbranceAnnotations", label: "Şerhler", formatter: formatEncumbranceAnnotationRow },
  { key: "encumbranceMortgages", label: "İpotekler", formatter: formatEncumbranceMortgageRow },
];

function getEncumbranceMultiUnitSummaryRows() {
  const header = ["Bölüm", "Yevmiye No", "Ortak mı?", "Kapsadığı Taşınmazlar", "Açıklama (rapor metni)"];
  const rows = [header];
  ENCUMBRANCE_MULTI_UNIT_SUMMARY_TABLES.forEach((table) => {
    getMultiTitleUnitEncumbranceRows(table.key).forEach((row) => {
      const text = table.formatter(row);
      if (!text) return;
      const references = Array.isArray(row.__titleUnitReferences) ? row.__titleUnitReferences.filter(Boolean) : [];
      const journalNo = getEncumbranceRowJournalNo(table.key, row);
      rows.push([
        table.label,
        encumbranceTextOrBila(journalNo),
        references.length > 1 ? "Evet" : "Hayır",
        references.join(", "),
        text,
      ]);
    });
  });
  return rows;
}

function isEncumbranceRightOrLiabilityRow(row) {
  const text = foldTurkish([row?.c0, row?.c1].filter(Boolean).join(" "));
  return /HAK|MUKELLEFIYET|IRTIFAK|INTIFA|SUKNA|OTURMA|UST HAKKI|GECIT HAKKI|KAYNAK HAKKI|DAIMI HAK/.test(text);
}

function buildEncumbranceSectionParagraph(title, rows, formatter) {
  const lines = rows.map(formatter).filter(Boolean);
  return `${title}:\n${lines.length ? lines.join("\n") : "Herhangi bir kayıt bulunmamaktadır."}`;
}

function isIsbankSelectedForReport() {
  const bank = foldTurkish(state.fields.bank || "");
  return bank.includes("IS BANKASI") || bank.includes("TURKIYE IS BANKASI");
}

function hasManagementPlanStatement(value = "") {
  const folded = foldTurkish(value)
    .replace(/[.\-_/\\():;]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  const compact = folded.replace(/\s+/g, "");
  return folded.includes("YONETIM PLANI")
    || folded.includes("YONETIM PLAN")
    || folded.includes("YONETIM PL")
    || folded.includes("YON PLAN")
    || folded.includes("YON PL")
    || /\bY\s+PLANI?\b/.test(folded)
    || /\bY\s+PLN\b/.test(folded)
    || /\bY\s+PL\b/.test(folded)
    || /\bY\s+P\b/.test(folded)
    || compact.includes("YONETIMPLANI")
    || compact.includes("YONETIMPLAN")
    || compact.includes("YONETIMPL")
    || compact.includes("YONPLAN")
    || compact.includes("YONPL")
    || compact.includes("YPLAN")
    || compact.includes("YPLANI")
    || compact.includes("YPLN")
    || compact.includes("YPL")
    || compact.includes("YP");
}

function getIsbankManagementPlanNote() {
  return "(Yönetim planı, ana taşınmazın yönetim tarzını, kullanma maksat ve şeklini, yönetici ve denetçilerin alacakları ücreti ve yönetime ait diğer hususları ve bütün kat maliklerini bağlayan sözleşme hükmündeki bir belgedir. Söz konusu beyan, taşınmazın satışını ve/veya taşınmaz üzerinde ipotek tesisi edilmesini kısıtlayıcı bir faktör oluşturmamaktadır.)";
}

function formatEncumbranceRestrictedOwner(row, columnIndex) {
  const restrictedOwner = encumbranceCleanText(row?.[`c${columnIndex}`]);
  return restrictedOwner ? ` (Kısıtlı Malik: ${restrictedOwner})` : "";
}

function formatEncumbranceTitleUnitScope(row, totalTitleUnitCount = null) {
  const references = Array.isArray(row?.__titleUnitReferences)
    ? row.__titleUnitReferences.filter(Boolean)
    : [];
  if (!references.length) return "";
  const resolvedTitleUnitCount = Number.isFinite(totalTitleUnitCount)
    ? totalTitleUnitCount
    : (typeof getTitleUnitCount === "function" ? getTitleUnitCount() : references.length);
  if (resolvedTitleUnitCount > 1 && references.length === resolvedTitleUnitCount) {
    return " (Tüm Taşınmazlar üzerinde müştereken)";
  }
  return ` (${references.join(", ")} üzerinde)`;
}

function formatEncumbranceDeclarationRow(row, options = {}) {
  const type = encumbranceCleanText(row.c0);
  const description = encumbranceCleanText(row.c1);
  const mainText = description
    ? (type && !/^BEYAN|HAK|MUKELLEFIYET$/i.test(foldTurkish(type)) ? `${type}: ${description}` : description)
    : type;
  if (!mainText) return "";
  const note = options.addIsbankManagementPlanNote
    && isIsbankSelectedForReport()
    && hasManagementPlanStatement([type, description].join(" "))
    ? ` ${getIsbankManagementPlanNote()}`
    : "";
  return `${mainText} (Tarih: ${encumbranceDateOrBila(row.c2)}, Yevmiye No: ${encumbranceTextOrBila(row.c3)})${formatEncumbranceTitleUnitScope(row)}${formatEncumbranceRestrictedOwner(row, 4)}${note}`;
}

function formatEncumbranceAnnotationRow(row) {
  const type = encumbranceCleanText(row.c0);
  const description = encumbranceCleanText(row.c1);
  const amount = encumbranceCleanText(row.c2);
  const detailParts = [];
  if (amount) detailParts.push(`Haciz Tutarı: ${formatEncumbranceMoney(amount)}`);
  detailParts.push(`Tarih: ${encumbranceDateOrBila(row.c3)}`);
  detailParts.push(`Yevmiye No: ${encumbranceTextOrBila(row.c4)}`);
  const mainText = [type, description].filter(Boolean).join(type && description ? ": " : "");
  if (!mainText) return "";
  return `${mainText} (${detailParts.join(", ")})${formatEncumbranceTitleUnitScope(row)}${formatEncumbranceRestrictedOwner(row, 5)}`;
}

function formatEncumbranceMortgageRow(row) {
  const creditor = normalizeMortgageCreditorDisplay(row.c0) || "Bila";
  const degree = formatEncumbranceMortgageDegree(row.c1);
  const amount = formatEncumbranceMoney(row.c2);
  return `${creditor} lehine ${degree} ${amount} tutarında ipotek kaydı bulunmaktadır. (Tarih: ${encumbranceDateOrBila(row.c3)}, Yevmiye No: ${encumbranceTextOrBila(row.c4)})${formatEncumbranceTitleUnitScope(row)}${formatEncumbranceRestrictedOwner(row, 5)}`;
}

// Kullanıcı talebi: "takyidatlar bölümünde beyanlar bölümü rehinler bölümü
// şerhler bölümü hak ve mükellefiyetler bölümü olarak her bir bölüme
// placeholder oluştur." — buildEncumbranceSummaryVariants() içindeki dört
// bölümün AYNI kaynak fonksiyonlarını (getFilledEncumbranceRows,
// isEncumbranceRightOrLiabilityRow, formatEncumbrance*Row) tek tek
// çağırarak her birini AYRI bir metin olarak döner — davranış birleşik
// özetle birebir tutarlı kalır. buildEncumbranceSectionParagraph'ın
// eklediği "Bölümü Adı:\n" başlığı KASITLI OLARAK KULLANILMAZ — kullanıcı
// talebi: "beyanlar bölümü gibi başlık olması [değil] direkt ilk kayıttan
// başlasın" (şablonda hücre zaten kendi etiketini taşıyor, ör. "Şerhler
// Kısmında:").
function joinEncumbranceRows(rows, formatter) {
  const lines = rows.map(formatter).filter(Boolean);
  return lines.length ? lines.join("\n") : "Herhangi bir kayıt bulunmamaktadır.";
}

function getEncumbranceDeclarationsSectionText() {
  const rows = (typeof getMultiTitleUnitEncumbranceRows === "function"
    ? getMultiTitleUnitEncumbranceRows("encumbranceDeclarations")
    : getFilledEncumbranceRows("encumbranceDeclarations"))
    .filter((row) => !isEncumbranceRightOrLiabilityRow(row));
  return joinEncumbranceRows(
    rows,
    (row) => formatEncumbranceDeclarationRow(row, { addIsbankManagementPlanNote: true }),
  );
}

function getEncumbranceEasementsSectionText() {
  const rows = (typeof getMultiTitleUnitEncumbranceRows === "function"
    ? getMultiTitleUnitEncumbranceRows("encumbranceDeclarations")
    : getFilledEncumbranceRows("encumbranceDeclarations"))
    .filter(isEncumbranceRightOrLiabilityRow);
  return joinEncumbranceRows(rows, formatEncumbranceDeclarationRow);
}

// Kullanıcının "Rehinler Bölümü" dediği kısım tapuda "İpotekler" tablosuna
// (encumbranceMortgages) karşılık gelir — ipotek, gayrimenkul hukukunda
// rehin hakkının tapu sicilindeki karşılığıdır.
function getEncumbranceMortgagesSectionText() {
  const rows = typeof getMultiTitleUnitEncumbranceRows === "function"
    ? getMultiTitleUnitEncumbranceRows("encumbranceMortgages")
    : getFilledEncumbranceRows("encumbranceMortgages");
  return joinEncumbranceRows(rows, formatEncumbranceMortgageRow);
}

function getEncumbranceAnnotationsSectionText() {
  const rows = typeof getMultiTitleUnitEncumbranceRows === "function"
    ? getMultiTitleUnitEncumbranceRows("encumbranceAnnotations")
    : getFilledEncumbranceRows("encumbranceAnnotations");
  return rows.length ? buildCondensedAnnotationSummary(rows) : "Herhangi bir kayıt bulunmamaktadır.";
}

// Varyantlar docs/cumle-envanteri.md Bölüm 2'de belgelendi.
function buildEncumbranceTitleRecordChangeParagraph(date, method) {
  const answer = normalizeYesNoChoice(state.fields.titleRecordChange);
  if (!answer) return "";
  const prefixVariants = [
    `${date} tarihinde ${method} üzerinden alınan TKGM (TAKBİS) kaydı ile tapu senedi arasında`,
    `${date} tarihli, ${method} aracılığıyla temin edilen TKGM (TAKBİS) kaydı ile tapu senedi arasında`,
    `${date} tarihinde ${method} üzerinden alınan TKGM (TAKBİS) kaydı ile tapu senedi karşılaştırıldığında`,
    `${date} tarihli ${method} kaynaklı TKGM (TAKBİS) kaydı ile tapu senedi arasında`,
  ];
  const prefixIndex = selectVariant("buildEncumbranceTitleRecordChangeParagraph:prefix", prefixVariants.length);
  const prefix = prefixVariants[prefixIndex];

  if (answer === "Hayır") {
    const noneVariants = [
      "herhangi bir farklılık tespit edilmemiştir.",
      "herhangi bir farklılığa rastlanmamıştır.",
      "herhangi bir uyumsuzluk tespit edilmemiştir.",
      "fark bulunmadığı görülmüştür.",
    ];
    return `Tapu Kaydı Değişikliği:\n${prefix} ${noneVariants[selectVariant("buildEncumbranceTitleRecordChangeParagraph:none", noneVariants.length)]}`;
  }
  const selectedLabels = (state.fields.titleChangedRecords || [])
    .map((key) => titleRecordChangeOptions.find((option) => option.key === key)?.label)
    .filter(Boolean);
  if (!selectedLabels.length) {
    const noSelectionVariants = [
      "farklılık bulunduğu belirtilmiş, değişen kayıt bölümleri seçilmemiştir.",
      "bir farklılık tespit edilmiş olup, değişen kayıt bölümleri belirtilmemiştir.",
      "bir uyumsuzluk saptanmış, ancak hangi bölümlerin değiştiği ifade edilmemiştir.",
      "bir farklılığa rastlanmış olup, değişikliğin hangi bölümlere ait olduğu belirtilmemiştir.",
    ];
    return `Tapu Kaydı Değişikliği:\n${prefix} ${noSelectionVariants[selectVariant("buildEncumbranceTitleRecordChangeParagraph:noSelection", noSelectionVariants.length)]}`;
  }
  const selectedVariants = [
    `farklılık olarak ${joinTurkishList(selectedLabels)} bölümlerinin değişmiş olduğu tespit edilmiştir.`,
    `${joinTurkishList(selectedLabels)} bölümlerinde değişiklik olduğu tespit edilmiştir.`,
    `${joinTurkishList(selectedLabels)} bölümlerinde farklılık olduğu saptanmıştır.`,
    `${joinTurkishList(selectedLabels)} bölümlerinde uyumsuzluk bulunduğu görülmüştür.`,
  ];
  return `Tapu Kaydı Değişikliği:\n${prefix} ${selectedVariants[selectVariant("buildEncumbranceTitleRecordChangeParagraph:selected", selectedVariants.length)]}`;
}
registerVariantGroup("buildEncumbranceTitleRecordChangeParagraph:prefix", "Tapu Kaydı Değişikliği — Önsöz (Tapu ve Mülkiyet)", 4);
registerVariantGroup("buildEncumbranceTitleRecordChangeParagraph:none", "Tapu Kaydı Değişikliği — Farklılık Yok (Tapu ve Mülkiyet)", 4);
registerVariantGroup("buildEncumbranceTitleRecordChangeParagraph:noSelection", "Tapu Kaydı Değişikliği — Farklılık Var, Seçim Yok (Tapu ve Mülkiyet)", 4);
registerVariantGroup("buildEncumbranceTitleRecordChangeParagraph:selected", "Tapu Kaydı Değişikliği — Farklılık Var, Seçim Var (Tapu ve Mülkiyet)", 4);

function encumbranceCleanText(value) {
  return String(value || "").replace(/\s+/g, " ").trim();
}

function encumbranceTextOrBila(value) {
  const text = encumbranceCleanText(value);
  return text || "Bila";
}

function encumbranceDateOrBila(value) {
  return encumbranceTextOrBila(dateIsoToTr(value));
}

function formatEncumbranceMortgageDegree(value) {
  const text = encumbranceCleanText(value).split("/")[0].replace(/\s*derece.*$/i, "").replace(/[.\s]+$/g, "");
  return text ? `${text}. dereceden` : "Bila dereceden";
}

function formatEncumbranceMoney(value) {
  const raw = encumbranceCleanText(value);
  if (!raw) return "Bila";
  const currency = raw.match(/\b(TL|YTL|USD|EUR|GBP)\b/i)?.[1]?.toUpperCase().replace("YTL", "TL") || "TL";
  const amount = parseEncumbranceMoneyNumber(raw);
  if (Number.isFinite(amount) && amount > 0) {
    return `${amount.toLocaleString("tr-TR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ${currency}`;
  }
  return /\b(TL|YTL|USD|EUR|GBP)\b/i.test(raw) ? raw.replace(/\bYTL\b/gi, "TL") : `${raw} ${currency}`;
}

function parseEncumbranceMoneyNumber(value) {
  const text = String(value || "").replace(/\s+/g, "").replace(/[^\d,.-]/g, "");
  if (!text) return Number.NaN;
  if (text.includes(",")) {
    return parseReportNumber(text);
  }
  const normalized = /\.\d{3}(\.|$)/.test(text)
    ? text.replace(/\./g, "")
    : text;
  const number = Number.parseFloat(normalized);
  return Number.isFinite(number) ? number : Number.NaN;
}

function getEncumbranceReportTableKey(record) {
  const type = foldTurkish(record?.type || "");
  if (/IPOTEK|REHIN/.test(type)) return "encumbranceMortgages";
  if (/SERH/.test(type)) return "encumbranceAnnotations";
  return "encumbranceDeclarations";
}

function parseTakbisAnnotationRecord(record) {
  const parsed = extractTakbisAnnotationType(record?.description || "", record?.type || "");
  const annotationType = normalizeTakbisAnnotationReportType(parsed.type, parsed.description);
  const amountSource = stripTakbisJournalNoFromAmountSource(
    getTakbisAnnotationSearchSource(record, parsed.description),
    record?.journalNo,
  );
  const shouldReadAmount = isTakbisLienType(annotationType) && !shouldSkipTakbisLienAmount(annotationType, amountSource);
  const lienAmount = shouldReadAmount
    ? extractTakbisLienAmount(amountSource)
    : "";
  return {
    c0: annotationType,
    c1: parsed.description,
    c2: lienAmount,
    c3: record?.date || "",
    c4: record?.journalNo || "",
    c5: record?.restrictedOwner || "",
    __amountSource: amountSource,
    __requiresLienAmount: shouldReadAmount ? "1" : "",
    __amountMissing: shouldReadAmount && !lienAmount ? "1" : "",
    __date: record?.date || "",
    __journalNo: record?.journalNo || "",
  };
}

function normalizeTakbisAnnotationTableRow(row) {
  if (!row || typeof row !== "object") return row;
  const annotationType = normalizeTakbisAnnotationReportType(row.c0 || "Şerh", row.c1 || "");
  row.c0 = annotationType;
  const requiresLienAmount = isTakbisLienType(annotationType)
    && !shouldSkipTakbisLienAmount(annotationType, row.__amountSource || row.c1 || "");
  row.__requiresLienAmount = requiresLienAmount ? "1" : "";
  if (requiresLienAmount && !row.c2) {
    const amountSource = stripTakbisJournalNoFromAmountSource(
      getTakbisAnnotationAmountSource(row, annotationType),
      row.c4 || row.__journalNo,
    );
    row.__amountSource = amountSource;
    row.c2 = extractTakbisLienAmount(amountSource);
  }
  row.__amountMissing = requiresLienAmount && !row.c2 ? "1" : "";
  return row;
}

function stringifyTakbisSourceValue(value) {
  if (value == null) return "";
  if (Array.isArray(value)) {
    return value.map(stringifyTakbisSourceValue).filter(Boolean).join(" ");
  }
  if (typeof value === "object") {
    return Object.values(value).map(stringifyTakbisSourceValue).filter(Boolean).join(" ");
  }
  return cleanTakbisValue(value);
}

// Satır birleştirme sırasında tarih-yevmiye sütunundan tutar metnine karışan
// yevmiye numarasını bağımsız token olarak ayıklar ("Borç : 4101 2000000 TL"
// veya "Borç : 4500000 11760 TL"); yevmiye tutara yapışıp trilyonluk sahte
// tutarlar üretmesin. Ondalıklı sayıların parçaları (örn. "11760.00") korunur.
function stripTakbisJournalNoFromAmountSource(value, journalNo) {
  const text = String(value || "");
  const journal = cleanTakbisValue(journalNo);
  if (!text || !/^\d{1,8}$/.test(journal)) return text;
  const pattern = new RegExp(`(^|\\s)${journal}(?=\\s|$)`, "g");
  return text.replace(pattern, " ").replace(/\s+/g, " ").trim();
}

function getTakbisAnnotationSearchSource(item, parsedDescription = "") {
  if (!item && !parsedDescription) return "";
  const parts = [
    item?._MergedText,
    item?.mergedText,
    item?.merged,
    item?._TAIL,
    item?.tail,
    item?.tailText,
    item?.ACIKLAMA,
    item?.aciklama,
    parsedDescription,
    item?.description,
    item?.rawText,
    item?.sourceText,
    item?.fullText,
    item?.text,
    item?._ocrText,
    item?.ocrText,
    item?.__amountSource,
    item?.__rawText,
    item?.c1,
  ].map(stringifyTakbisSourceValue).filter(Boolean);

  return [...new Set(parts)].join(" ");
}

function shouldSkipTakbisLienAmount(annotationType, sourceValue = "") {
  const folded = foldTurkish(`${annotationType || ""} ${sourceValue || ""}`);
  const compact = folded.replace(/\s+/g, "");
  return folded.includes("150/C") || compact.includes("150C") || folded.includes("SATISA GITME");
}

function getTakbisAnnotationAmountSource(row, annotationType = "") {
  const directSource = getTakbisAnnotationSearchSource(row, row?.c1 || "");

  if (extractTakbisLienAmount(directSource)) return directSource;

  const takbisRecords = state.sourceValues.takbis?.encumbrances || [];
  const rowDate = cleanTakbisValue(row?.c3 || row?.__date || "");
  const rowJournal = cleanTakbisValue(row?.c4 || row?.__journalNo || "");
  const foldedRowDescription = foldTurkish(cleanTakbisValue(row?.c1 || ""));
  const foldedAnnotationType = foldTurkish(annotationType || row?.c0 || "");
  const annotationRecords = takbisRecords
    .filter((record) => getEncumbranceReportTableKey(record) === "encumbranceAnnotations")
    .map((record) => {
      const parsed = extractTakbisAnnotationType(record?.description || "", record?.type || "");
      const source = stripTakbisJournalNoFromAmountSource(
        getTakbisAnnotationSearchSource(record, parsed.description),
        record?.journalNo,
      );
      const recordType = normalizeTakbisAnnotationReportType(parsed.type || record?.type || "", parsed.description || record?.description || "");
      return {
        record,
        parsed,
        source,
        recordType,
        recordDate: cleanTakbisValue(record?.date || ""),
        recordJournal: cleanTakbisValue(record?.journalNo || ""),
        foldedSource: foldTurkish(source),
      };
    });

  const candidates = annotationRecords.filter((item) => {
    const sameJournal = rowJournal && item.recordJournal === rowJournal;
    const sameDate = rowDate && item.recordDate === rowDate;
    if (sameJournal && sameDate) return true;
    if (sameJournal && !rowDate) return true;
    if (sameDate && !rowJournal) return true;
    return false;
  });

  const typeMatches = (item) => !foldedAnnotationType || foldTurkish(item.recordType) === foldedAnnotationType;
  const descriptionMatches = (item) => foldedRowDescription && item.foldedSource.includes(foldedRowDescription);
  const hasAmount = (item) => Boolean(extractTakbisLienAmount(item.source));

  const matchingRecord = candidates.find((item) => typeMatches(item) && hasAmount(item))
    || candidates.find((item) => hasAmount(item))
    || annotationRecords.find((item) => typeMatches(item) && descriptionMatches(item) && hasAmount(item))
    || annotationRecords.find((item) => typeMatches(item) && hasAmount(item))
    || annotationRecords.find((item) => descriptionMatches(item) && hasAmount(item))
    || candidates.find(typeMatches)
    || candidates[0];

  if (!matchingRecord) return directSource;
  return [
    directSource,
    matchingRecord.source,
  ].filter(Boolean).join(" ");
}

function extractTakbisAnnotationType(descriptionValue, fallbackType = "") {
  let description = cleanTakbisEncumbranceText(descriptionValue);
  let annotationType = "";

  const colonMatch = description.match(/^([^:]{2,90})\s*:\s*(.+)$/);
  if (colonMatch && isLikelyTakbisAnnotationType(colonMatch[1])) {
    annotationType = cleanTakbisAnnotationType(colonMatch[1]);
    description = colonMatch[2];
  }

  if (!annotationType) {
    const trailingParenthesis = description.match(/\(([^()]{3,140})\)\s*$/);
    if (trailingParenthesis) {
      annotationType = cleanTakbisAnnotationType(trailingParenthesis[1]);
      description = description.slice(0, trailingParenthesis.index).trim();
    }
  }

  return {
    type: toTitleCaseTr(cleanTakbisAnnotationType(annotationType || fallbackType || "\u015eerh")),
    description: cleanTakbisValue(description || descriptionValue),
  };
}

function cleanTakbisAnnotationType(value) {
  let text = cleanTakbisValue(value);
  if (/^SABLON\s*:/.test(foldTurkish(text))) {
    const colonIndex = text.indexOf(":");
    text = colonIndex >= 0 ? text.slice(colonIndex + 1) : "";
  }
  return text.replace(/\s+/g, " ").trim();
}

function normalizeTakbisAnnotationReportType(typeValue, descriptionValue = "") {
  const type = cleanTakbisAnnotationType(typeValue);
  const foldedType = foldTurkish(type);
  const foldedAll = foldTurkish(`${type} ${descriptionValue}`);
  if (/KONKORDATO/.test(foldedAll)) {
    return "Konkordato \u015eerhi";
  }
  if (/(?:IIK|IIC|I\.I\.K|IICRA)\s*150\s*\/?\s*C|150\s*\/?\s*C/.test(foldedAll)) {
    return "\u0130\u0130K 150/C \u015eerhi";
  }
  // "\u0130htiyati Tedbir" bir haciz de\u011fildir: tip etiketi tedbir i\u00e7eriyorsa veya
  // metinde "ihtiyati tedbir" ge\u00e7ip "ihtiyati haciz" ge\u00e7miyorsa haciz
  // s\u0131n\u0131flamas\u0131 yap\u0131lmaz.
  const mentionsPrecautionarySeizure = /IHTIYATI\s+HAC(?:IZ|Z)/.test(foldedAll);
  if (/TEDBIR/.test(foldedType)) {
    return toTitleCaseTr(type);
  }
  if (/IHTIYATI\s+TEDBIR/.test(foldedAll) && !mentionsPrecautionarySeizure) {
    return "\u0130htiyati Tedbir";
  }
  // "Haciz" katlan\u0131nca "HACIZ", "Haczi/Haczin" ise "HACZ..." olur; ikisi de haciz say\u0131l\u0131r.
  if (/HACIZ|HACZ/.test(foldedAll)) {
    if (/IHTIYATI/.test(foldedAll)) {
      return "\u0130htiyati Haciz";
    }
    if (/KAMU|AMME|6183|VERGI|SGK|SOSYAL\s+GUVENLIK|BELEDIYE|MALIYE|HAZINE|GUMRUK/.test(foldedAll)) {
      return "Kamu Haczi";
    }
    return "\u0130crai Haciz";
  }
  return toTitleCaseTr(type);
}

function isTakbisLienType(typeValue) {
  const folded = foldTurkish(typeValue || "");
  // "Kamu Haczi" gibi tiplerde katlama "HACZI" \u00fcretir; tedbir \u015ferhleri haciz de\u011fildir.
  if (/TEDBIR/.test(folded)) return false;
  return /HACIZ|HACZ/.test(folded);
}

function extractTakbisDebtToCurrencyAmount(value) {
  const text = cleanTakbisValue(value);
  if (!text) return "";

  const sources = [text, foldTurkish(text)];
  const debtPatterns = [
    /\bBOR\S{0,4}\s*[:;]?\s*([0-9][0-9.,\s]*[0-9])\s*(?:Y\s*)?T\s*\.?\s*L\.?\b/gi,
    /\bBOR\S{0,4}\s*[:;]?\s*([^()]{1,160}?)\s*(?:Y\s*)?T\s*\.?\s*L\.?\b/gi,
  ];

  for (const source of sources) {
    for (const pattern of debtPatterns) {
      const matches = [...source.matchAll(pattern)];
      for (let i = matches.length - 1; i >= 0; i -= 1) {
        const rawAmount = (matches[i][1] || "").replace(/[^\d.,\s]/g, " ");
        const numberMatches = rawAmount.match(/[0-9][0-9.,\s]*[0-9]|[0-9]/g) || [];
        for (let j = numberMatches.length - 1; j >= 0; j -= 1) {
          const amount = extractTakbisMoneyCandidate(numberMatches[j]);
          if (amount) return amount;
        }
      }
    }
  }

  return "";
}

function extractTakbisLienAmount(value) {
  const text = cleanTakbisValue(value);
  if (!text) return "";
  const debtToCurrencyAmount = extractTakbisDebtToCurrencyAmount(text);
  if (debtToCurrencyAmount) return debtToCurrencyAmount;

  const debtWindowAmount = extractTakbisDebtWindowAmount(text);
  if (debtWindowAmount) return debtWindowAmount;

  const leftWindowAmount = extractTakbisCurrencyLeftWindowAmount(text);
  if (leftWindowAmount) return leftWindowAmount;

  const debtLabelAmount = extractTakbisDebtLabelAmount(text);
  if (debtLabelAmount) return debtLabelAmount;

  const labeledAmount = extractTakbisLabeledLienAmount(text);
  if (labeledAmount) return labeledAmount;

  const currencyNearbyAmount = extractTakbisCurrencyNearbyAmount(text);
  if (currencyNearbyAmount) return currencyNearbyAmount;

  const powerQueryAmount = extractTakbisPowerQueryLienAmount(text);
  if (powerQueryAmount) return powerQueryAmount;

  const ileCurrencyAmount = extractTakbisIleCurrencyAmount(text);
  if (ileCurrencyAmount) return ileCurrencyAmount;

  const currencyMatches = [...text.matchAll(/(?:TL|\u20ba|TRY|T\.L\.)?\s*([0-9]{5,}(?:[.,][0-9]{1,2})?|[0-9]{1,3}(?:[.,\s][0-9]{3})+(?:[.,][0-9]{1,2})?|[0-9]{1,4}[.,][0-9]{2}|[0-9]+(?:[.,][0-9]{1,2})?)\s*(?:TL|\u20ba|TRY|T\.L\.)/gi)];
  if (currencyMatches.length) {
    return formatTakbisTurkishMoney(currencyMatches[currencyMatches.length - 1][1]);
  }

  const amountOnlyMatches = [...text.matchAll(/\b([0-9]{1,3}(?:[.,\s][0-9]{3})+[.,][0-9]{2}|[0-9]{5,}(?:[.,][0-9]{2})?|[0-9]{1,4}[.,][0-9]{2})\b/g)]
    .map((match) => match[1])
    .filter((candidate) => isLikelyTakbisLienAmount(candidate, text));
  if (!amountOnlyMatches.length) return "";
  return formatTakbisTurkishMoney(amountOnlyMatches[amountOnlyMatches.length - 1]);
}

function extractTakbisDebtWindowAmount(value) {
  const text = cleanTakbisValue(value);
  if (!text) return "";
  const directDebtPattern = /(?:\bbor(?:\u00e7|c)|\bBOR(?:\u00c7|C))\s*[:：]?\s*([0-9][0-9.,\s]*[0-9])\s*(?:Y\s*)?T\s*\.?\s*L\.?\b/giu;
  const directDebtMatches = [...text.matchAll(directDebtPattern)];
  for (let i = directDebtMatches.length - 1; i >= 0; i -= 1) {
    const amount = extractTakbisMoneyCandidate(directDebtMatches[i][1]);
    if (amount) return amount;
  }
  const mojibakeDebtPattern = /\bbor\u00c3\u00a7\s*[:：]?\s*([0-9][0-9.,\s]*[0-9])\s*(?:Y\s*)?T\s*\.?\s*L\.?\b/giu;
  const mojibakeDebtMatches = [...text.matchAll(mojibakeDebtPattern)];
  for (let i = mojibakeDebtMatches.length - 1; i >= 0; i -= 1) {
    const amount = extractTakbisMoneyCandidate(mojibakeDebtMatches[i][1]);
    if (amount) return amount;
  }
  const sources = [text, foldTurkish(text)];
  const debtPattern = /\bBORC\s*[:：]?\s*([0-9][0-9.,\s]*[0-9])\s*(?:Y\s*)?T\s*\.?\s*L\.?\b/gi;
  for (const source of sources) {
    const matches = [...source.matchAll(debtPattern)];
    for (let i = matches.length - 1; i >= 0; i -= 1) {
      const amount = extractTakbisMoneyCandidate(matches[i][1]);
      if (amount) return amount;
    }
  }
  return "";
}

function extractTakbisCurrencyLeftWindowAmount(value) {
  const text = cleanTakbisValue(value);
  const currencyPattern = /(?:\bY\s*)?T\s*\.?\s*L\.?\b|\bTRY\b|\u20ba/gi;
  const currencyMatches = [...text.matchAll(currencyPattern)];
  if (!currencyMatches.length) return "";

  for (let matchIndex = currencyMatches.length - 1; matchIndex >= 0; matchIndex -= 1) {
    const currencyMatch = currencyMatches[matchIndex];
    const currencyIndex = currencyMatch.index || 0;
    const leftWindow = text.slice(Math.max(0, currencyIndex - 40), currencyIndex);
    const numericOnly = leftWindow.replace(/[^\d.,]/g, " ").replace(/\s+/g, " ").trim();
    const numberMatches = numericOnly.match(/[0-9][0-9.,]*[0-9]|[0-9]/g) || [];

    for (let i = numberMatches.length - 1; i >= 0; i -= 1) {
      const candidate = numberMatches[i].replace(/[^\d.,]/g, "");
      const amount = extractTakbisMoneyCandidate(candidate);
      if (amount) return amount;
    }
  }

  return "";
}

function extractTakbisMoneyCandidate(value) {
  const cleaned = String(value || "").replace(/[^\d.,]/g, "").trim();
  if (!cleaned) return "";
  if (/^\d{1,2}[.,]\d{1,2}[.,]\d{4}$/.test(cleaned)) return "";
  const digits = cleaned.replace(/\D/g, "");
  if (digits.length < 4) return "";
  if (/^[12]\d{3}$/.test(digits)) return "";
  return formatTakbisTurkishMoney(cleaned);
}

function extractTakbisLabeledLienAmount(value) {
  const text = cleanTakbisValue(value);
  const foldedText = foldTurkish(text);
  const moneyPattern = "([0-9]{5,}(?:[.,][0-9]{1,2})?|[0-9]{1,3}(?:[.,\\s][0-9]{3})+(?:[.,][0-9]{1,2})?|[0-9]{1,4}[.,][0-9]{2})";
  const labelRegex = new RegExp(
    `(?:HACIZ\\s+(?:TUTARI?|MIKTARI?|BEDELI?)|ALACAK\\s+(?:TUTARI?|MIKTARI?|BEDELI?)|BORC(?:\\s+(?:TUTARI?|MIKTARI?|BEDELI?))?)[^0-9]{0,50}${moneyPattern}`
  );
  const match = foldedText.match(labelRegex);
  if (!match || !isLikelyTakbisLienAmount(match[1], foldedText)) return "";
  return formatTakbisTurkishMoney(match[1]);
}

function extractTakbisDebtLabelAmountLegacy(value) {
  const text = cleanTakbisValue(value);
  const directDebtMatch = text.match(/(?:bor[çc]|borc)\s*:?\s*([0-9][0-9.,\s]*[0-9])\s*(?:YTL|TL|TRY|T\.L\.|\u20ba)\b/i);
  if (directDebtMatch && isLikelyTakbisLienAmount(directDebtMatch[1], text)) {
    return formatTakbisTurkishMoney(directDebtMatch[1]);
  }

  const debtMatch = text.match(/(?:bor[çc]|borc)\s*:?\s*([^()]{1,160}?\b(?:YTL|TL|TRY|T\.L\.)\b)/i);
  if (!debtMatch) return "";
  const numberMatch = debtMatch[1].match(/[0-9][0-9.,\s]*[0-9]/);
  if (!numberMatch) return "";
  const cleaned = numberMatch[0].replace(/[^\d.,]/g, "");
  if (!isLikelyTakbisLienAmount(cleaned, text)) return "";
  return formatTakbisTurkishMoney(cleaned);
}

function extractTakbisCurrencyNearbyAmount(value) {
  const text = cleanTakbisValue(value);
  if (!/\bY?TL\b|\u20ba|TRY|T\.L\./i.test(text)) return "";
  const amountPattern = /[0-9][0-9.,\s]*[0-9]/g;
  const candidates = [];
  for (const currencyMatch of text.matchAll(/\bY?TL\b|\u20ba|TRY|T\.L\./gi)) {
    const currencyIndex = currencyMatch.index || 0;
    const windowStart = Math.max(0, currencyIndex - 80);
    const windowEnd = Math.min(text.length, currencyIndex + 80);
    const windowText = text.slice(windowStart, windowEnd);
    for (const amountMatch of windowText.matchAll(amountPattern)) {
      const cleaned = amountMatch[0].replace(/[^\d.,]/g, "");
      if (!isLikelyTakbisLienAmount(cleaned, text)) continue;
      const absoluteIndex = windowStart + (amountMatch.index || 0);
      candidates.push({
        value: cleaned,
        distance: Math.abs(currencyIndex - absoluteIndex),
      });
    }
  }
  if (!candidates.length) return "";
  candidates.sort((a, b) => a.distance - b.distance);
  return formatTakbisTurkishMoney(candidates[0].value);
}

function extractTakbisIleCurrencyAmount(value) {
  const text = cleanTakbisValue(value);
  if (!/\bY?TL\b|\u20ba|TRY|T\.L\./i.test(text)) return "";
  const foldedText = foldTurkish(text);
  const moneyPattern = /[0-9][0-9.,\s]*[0-9]/g;

  for (const currencyMatch of foldedText.matchAll(/\bY?TL\b|\u20ba|TRY|T\.L\./gi)) {
    const currencyIndex = currencyMatch.index || 0;
    const prefixStart = Math.max(0, currencyIndex - 320);
    const foldedPrefix = foldedText.slice(prefixStart, currencyIndex);
    const ileMatchIndex = Math.max(foldedPrefix.lastIndexOf(" ILE "), foldedPrefix.lastIndexOf(".ILE "), foldedPrefix.lastIndexOf(" ILE."));
    if (ileMatchIndex < 0) continue;

    const originalSegment = text.slice(prefixStart + ileMatchIndex, currencyIndex);
    const candidates = [...originalSegment.matchAll(moneyPattern)]
      .map((match) => match[0].replace(/[^\d.,]/g, ""))
      .filter((candidate) => isLikelyTakbisLienAmount(candidate, text));
    if (!candidates.length) continue;
    return formatTakbisTurkishMoney(candidates[candidates.length - 1]);
  }

  return "";
}

function formatTakbisTurkishMoney(rawValue) {
  const text = String(rawValue || "").replace(/\s+/g, "").trim();
  if (!text) return "";
  const lastComma = text.lastIndexOf(",");
  const lastDot = text.lastIndexOf(".");
  const separator = lastComma > lastDot ? "," : lastDot >= 0 ? "." : "";
  let integerPart = text.replace(/[^\d]/g, "");
  let decimalPart = "00";

  if (separator) {
    const separatorIndex = text.lastIndexOf(separator);
    const suffixDigits = text.slice(separatorIndex + 1).replace(/[^\d]/g, "");
    if (suffixDigits.length > 0 && suffixDigits.length !== 3) {
      integerPart = text.slice(0, separatorIndex).replace(/[^\d]/g, "");
      decimalPart = suffixDigits.padEnd(2, "0").slice(0, 2);
    }
  }

  if (!integerPart) return "";
  return `${integerPart.replace(/\B(?=(\d{3})+(?!\d))/g, ".")},${decimalPart} TL`;
}

function isLikelyTakbisLienAmount(value, sourceText = "") {
  const cleaned = String(value || "").replace(/\s+/g, "").trim();
  if (!cleaned) return false;
  if (/^\d{1,2}[.,]\d{1,2}[.,]\d{4}$/.test(cleaned)) return false;
  const digits = cleaned.replace(/\D/g, "");
  if (digits.length < 5) return false;
  if (/^\d{3,8}$/.test(cleaned)) {
    const foldedSource = foldTurkish(sourceText);
    const valueIndex = foldedSource.indexOf(cleaned);
    const beforeValue = valueIndex >= 0 ? foldedSource.slice(Math.max(0, valueIndex - 35), valueIndex) : "";
    if (/YEVMIYE|YEVM|TARIH|SAYI\s*NO/.test(beforeValue) || /-\s*$/.test(beforeValue)) return false;
  }
  if (/^[12]\d{3}$/.test(cleaned)) return false;
  return /[.,]\d{2}$/.test(cleaned) || digits.length >= 5;
}

function isTakbisDebtLabelAmount(value) {
  const cleaned = String(value || "").replace(/[^\d.,]/g, "").trim();
  if (!cleaned) return false;
  if (/^\d{1,2}[.,]\d{1,2}[.,]\d{4}$/.test(cleaned)) return false;
  const digits = cleaned.replace(/\D/g, "");
  if (digits.length < 4) return false;
  if (/^[12]\d{3}$/.test(digits)) return false;
  return true;
}

function extractTakbisDebtLabelAmount(value) {
  const text = cleanTakbisValue(value);
  const sources = [text, foldTurkish(text)];
  const foldedText = foldTurkish(text);
  const explicitDebtMatches = [...foldedText.matchAll(/\bBORC\s*:?\s*([0-9][0-9.,\s]*[0-9])\s*(?:YTL|TL|TRY|T\.L\.|\u20ba)\b/gi)];
  for (let i = explicitDebtMatches.length - 1; i >= 0; i -= 1) {
    const amount = explicitDebtMatches[i][1];
    if (isTakbisDebtLabelAmount(amount)) {
      return formatTakbisTurkishMoney(amount);
    }
  }

  for (const source of sources) {
    const directDebtMatch = source.match(/(?:BORC|bor[çc]|borc)\s*:?\s*([0-9][0-9.,\s]*[0-9])\s*(?:YTL|TL|TRY|T\.L\.|\u20ba)\b/i);
    if (directDebtMatch && isLikelyTakbisLienAmount(directDebtMatch[1], source)) {
      return formatTakbisTurkishMoney(directDebtMatch[1]);
    }
  }

  for (const source of sources) {
    const debtMatch = source.match(/(?:BORC|bor[çc]|borc)\s*:?\s*([^()]{1,220}?\b(?:YTL|TL|TRY|T\.L\.)\b)/i);
    if (!debtMatch) continue;
    const numberMatch = debtMatch[1].match(/[0-9][0-9.,\s]*[0-9]/);
    if (!numberMatch) continue;
    const cleaned = numberMatch[0].replace(/[^\d.,]/g, "");
    if (!isLikelyTakbisLienAmount(cleaned, source)) continue;
    return formatTakbisTurkishMoney(cleaned);
  }

  return "";
}

function extractTakbisPowerQueryLienAmount(value) {
  const text = cleanTakbisValue(value);
  if (!/\bY?TL\b|\u20ba|TRY|T\.L\./i.test(text)) return "";
  const pieces = getTakbisNumericPieces(text)
    .map((piece) => ({
      raw: piece,
      number: parseTakbisSmartNumber(piece),
      hasDecimal: hasTakbisDecimalPart(piece),
    }))
    .filter((piece) => piece.number !== null && piece.number >= 1 && isLikelyTakbisLienAmount(piece.raw, text));

  if (!pieces.length) return "";
  const decimalPieces = pieces.filter((piece) => piece.hasDecimal);
  const candidates = decimalPieces.length ? decimalPieces : pieces;
  candidates.sort((a, b) => b.number - a.number);
  return formatTakbisTurkishMoney(candidates[0].raw);
}

function getTakbisNumericPieces(value) {
  const text = String(value || "");
  const matches = text.match(/[0-9][0-9.,]*/g) || [];
  return matches
    .map((piece) => piece.replace(/^[.,]+|[.,]+$/g, ""))
    .filter((piece) => /\d/.test(piece));
}

function hasTakbisDecimalPart(value) {
  const text = String(value || "").replace(/^[.,]+|[.,]+$/g, "");
  const lastComma = text.lastIndexOf(",");
  const lastDot = text.lastIndexOf(".");
  const index = Math.max(lastComma, lastDot);
  if (index < 0) return false;
  return /^\d{2}$/.test(text.slice(index + 1).replace(/\D/g, ""));
}

function parseTakbisSmartNumber(value) {
  let text = String(value || "").replace(/\s+/g, "").replace(/^[.,]+|[.,]+$/g, "");
  if (!text) return null;
  const lastComma = text.lastIndexOf(",");
  const lastDot = text.lastIndexOf(".");
  const separatorIndex = Math.max(lastComma, lastDot);
  if (separatorIndex >= 0) {
    const suffix = text.slice(separatorIndex + 1).replace(/\D/g, "");
    if (suffix.length === 2) {
      const integerPart = text.slice(0, separatorIndex).replace(/\D/g, "");
      const normalized = `${integerPart}.${suffix}`;
      const parsed = Number(normalized);
      return Number.isFinite(parsed) ? parsed : null;
    }
  }
  text = text.replace(/\D/g, "");
  if (!text) return null;
  const parsed = Number(text);
  return Number.isFinite(parsed) ? parsed : null;
}

function isLikelyTakbisAnnotationType(value) {
  const text = cleanTakbisValue(value);
  const folded = foldTurkish(text);
  if (!text || text.length > 90) return false;
  if (/\d{1,2}[-.\/]\d{1,2}[-.\/]\d{4}/.test(text)) return false;
  if (/^(NILUFER|OSMANGAZI|MUDANYA|BURSA|ISTANBUL|TARIH|YEVMIYE|TESIS|TERKIN)\b/.test(folded)) return false;
  return /HACIZ|IFLAS|AILE|KONUT|KAT|YONETIM|IPOTEK|REHIN|INTIFA|IRTIFAK|SATIS|KAMULASTIRMA|MUVAFAKAT|TEDBIR|DAVALI|150\s*\/?\s*C|MD\.?|MADDE/.test(folded)
    || text.split(/\s+/).length <= 5;
}

function parseTakbisMortgageRecord(record) {
  const rawDescription = cleanTakbisEncumbranceText(record?.description || "");
  const rawText = cleanTakbisEncumbranceText(record?.rawText || "");
  const sourceText = rawText || rawDescription;
  const mainDescription = sliceBeforeFolded(
    sourceText,
    /REHINE\s+AIT\s+SERH|150\s*\/?\s*C|^\s*SERH\b|IPOTEGIN\s+KONULDUGU|HISSE\s+BILGISI|BORCLU\s+MALIK|MALIK\s+BORC|TESCIL\s+TARIH/,
  );
  const amountInfo = extractTakbisMortgageAmount(mainDescription);
  const degreeMatch = mainDescription.match(/\b\d+\s*\/\s*\d+\b/);
  const fallbackDateInfo = extractTakbisEncumbranceDateInfo(sourceText || mainDescription);
  const cutIndexes = [];
  const firstCut = cutIndexes.length ? Math.min(...cutIndexes) : mainDescription.length;
  let creditor = extractTakbisMortgageCreditor(mainDescription, amountInfo.raw);
  const debtorFlagMatch = creditor.match(/\b(?:Evet|Hayır|Hayir)\b/i);
  if (debtorFlagMatch) creditor = creditor.slice(0, debtorFlagMatch.index);

  const parsedCreditor = toTitleCaseTakbisEntity(cleanTakbisMortgageCreditorTokens(cleanTakbisMortgageCreditor(creditor)));

  return {
    c0: normalizeMortgageCreditorDisplay(chooseKnownMortgageCreditor(parsedCreditor)),
    c1: degreeMatch ? degreeMatch[0].split("/")[0].trim() : "",
    c2: amountInfo.text,
    c3: record?.date || fallbackDateInfo.date || "",
    c4: record?.journalNo || fallbackDateInfo.journalNo || "",
    c5: record?.restrictedOwner || "",
  };
}

function sliceBeforeFolded(value, pattern) {
  const text = String(value || "");
  const folded = foldTurkish(text);
  const match = folded.match(pattern);
  return match ? text.slice(0, match.index).trim() : text.trim();
}

function extractTakbisMortgageCreditor(value, amountRaw = "") {
  let text = cleanTakbisValue(value);
  const vknMatch = text.match(/\bVKN\s*:?\s*\d+\b/i);
  if (vknMatch) {
    text = text.slice(0, vknMatch.index);
  }
  if (amountRaw) {
    text = text.replace(new RegExp(escapeRegExp(amountRaw), "i"), " ");
  }
  return text
    .replace(/\(\s*SN\s*:\s*\d+\s*\)/gi, " ")
    .replace(/\b(?:Alacakl[ıi]|Alacakli|Müşterek|Musterek|Bor[çc]|Mi\?|Evet|Hayır|Hayir|faizsiz|F\.?B\.?K\.?)\b/gi, " ")
    .replace(/\b\d+\s*\/\s*\d+\b/g, " ")
    .replace(/\b\d{1,2}[-.\/]\d{1,2}[-.\/]\d{4}(?:\s+\d{1,2}:\d{2})?\b/g, " ")
    .replace(/\b\d{3,8}\b\s*$/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function extractTakbisMortgageAmount(value) {
  const text = cleanTakbisValue(value)
    .replace(/[₺]/g, " TL ")
    .replace(/[€]/g, " EUR ")
    .replace(/[$]/g, " USD ")
    .replace(/\s+/g, " ")
    .trim();
  const splitDecimal = text.match(/\b\d+(?:[.,]\d{3})*\s+00\s*(?:TL|TRY|T\.L\.|USD|EUR|GBP|CHF)\b/i);
  if (splitDecimal) {
    return {
      raw: splitDecimal[0],
      text: normalizeTakbisMortgageAmountEnhanced(splitDecimal[0].replace(/\s+00\s+/i, ",00 ")),
    };
  }
  const amountWithCurrency = text.match(/\b\d+(?:[.,]\d{3})*(?:[.,]\d{2})?\s*(?:TL|TRY|T\.L\.|USD|EUR|GBP|CHF)\b/i);
  if (amountWithCurrency) {
    return {
      raw: amountWithCurrency[0],
      text: normalizeTakbisMortgageAmountEnhanced(amountWithCurrency[0]),
    };
  }
  const amountOnly = text.match(/\b\d{5,}(?:[.,]\d{2})?\b/);
  return amountOnly
    ? { raw: amountOnly[0], text: normalizeTakbisMortgageAmountEnhanced(amountOnly[0]) }
    : { raw: "", text: "" };
}

function normalizeTakbisMortgageAmountEnhanced(value) {
  const text = cleanTakbisValue(value)
    .replace(/\bTRY\b|T\.L\./gi, "TL")
    .replace(/\s+/g, " ")
    .trim();
  const match = text.match(/^(.+?)(?:\s+(TL|USD|EUR|GBP|CHF))?$/i);
  if (!match) return text;
  const currency = match[2] ? match[2].toUpperCase() : "";
  const numeric = match[1].replace(/\s/g, "");
  const decimalMatch = numeric.match(/^(.*)([.,])(\d{2})$/);
  let integerPart = numeric;
  let decimalPart = "";
  if (decimalMatch) {
    integerPart = decimalMatch[1];
    decimalPart = decimalMatch[3];
  }
  const digits = integerPart.replace(/\D/g, "");
  if (!digits) return text;
  const grouped = digits.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return [decimalPart ? `${grouped},${decimalPart}` : grouped, currency].filter(Boolean).join(" ").trim();
}

function normalizeMortgageBankCompare(value) {
  return foldTurkish(value)
    .replace(/\b(?:A\s*S|AS|T\s*A\s*O|TAO|T\s*A\s*S|TAS)\b/g, " ")
    .replace(/[^A-Z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function chooseKnownMortgageCreditor(value) {
  const cleaned = cleanTakbisValue(value);
  const source = normalizeMortgageBankCompare(cleaned);
  if (!source) return cleaned;

  let best = { name: cleaned, score: 0 };
  mortgageCreditorBankNames.forEach((bankName) => {
    const target = normalizeMortgageBankCompare(bankName);
    const score = scoreMortgageBankMatch(source, target);
    if (score > best.score) {
      best = { name: bankName, score };
    }
  });

  return best.score >= 24 ? best.name : cleaned;
}

function stripMortgageCreditorLocationLeak(value) {
  let text = cleanTakbisValue(value);
  if (!text || typeof state === "undefined") return text;
  const locations = [
    "Düzce",
    state.fields?.titleCity,
    state.fields?.titleDistrict,
    state.fields?.titleNeighborhood,
    state.fields?.city,
    state.fields?.district,
    state.fields?.neighborhood,
  ]
    .map((location) => cleanTakbisValue(location))
    .filter((location) => location.length >= 3);
  locations.forEach((location) => {
    if (foldTurkish(text) === foldTurkish(location)) return;
    text = text.replace(new RegExp(`\\b${escapeRegExp(location)}\\b`, "gi"), " ");
  });
  return text.replace(/\\s+/g, " ").trim();
}

function normalizeMortgageCreditorDisplay(value) {
  const cleaned = stripMortgageCreditorLocationLeak(value)
    .replace(/\bDeğişken\b/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!cleaned) return "";
  const known = chooseKnownMortgageCreditor(cleaned);
  if (mortgageCreditorBankNames.includes(known)) return known;
  return preserveMortgageCreditorAbbreviations(normalizeReportTitleText(cleaned));
}

function preserveMortgageCreditorAbbreviations(value) {
  return String(value || "")
    .replace(/\bA\.?\s*Ş\.?/gi, "A.Ş.")
    .replace(/\bT\.?\s*A\.?\s*O\.?/gi, "T.A.O.")
    .replace(/\bT\.?\s*A\.?\s*Ş\.?/gi, "T.A.Ş.")
    .replace(/\bA\.?\s*S\.?/gi, "A.Ş.")
    .replace(/\bT\.?\s*A\.?\s*S\.?/gi, "T.A.Ş.")
    .replace(/\bLtd\.?\s*Şti\.?/gi, "Ltd. Şti.")
    .replace(/\s+/g, " ")
    .trim();
}

function scoreMortgageBankMatch(source, target) {
  if (!source || !target) return 0;
  if (source.includes(target)) return 120;
  const sourceTokens = new Set(source.split(" ").filter(Boolean));
  const targetTokens = target.split(" ").filter(Boolean);
  const genericTokens = new Set(["TURKIYE", "BANK", "BANKASI", "KATILIM", "KREDI", "YATIRIM", "VE"]);
  let score = 0;
  let distinctive = false;

  targetTokens.forEach((token) => {
    if (!token) return;
    const matched = sourceTokens.has(token) || source.includes(token);
    if (!matched) return;
    score += token.length >= 5 ? 12 : 5;
    if (!genericTokens.has(token) && token.length >= 3) distinctive = true;
  });

  return distinctive ? score : 0;
}

function cleanTakbisMortgageCreditor(value) {
  return cleanTakbisValue(value)
    .replace(/\(\s*SN\s*:\s*\d+\s*\)/gi, "")
    .replace(/\b(?:Alacakl[ıi]|M[üu]şterek\s+Mi|Bor[çc]|Faiz|Derece\s*S[ıi]ra|S[üu]re)\b/gi, "")
    .replace(/\b(?:Evet|Hayır|Hayir)\b/gi, "")
    .replace(/\s+/g, " ")
    .trim();
}

function cleanTakbisMortgageCreditorTokens(value) {
  const noise = new Set([
    "ALACAKLI",
    "MUSTEREK",
    "BORC",
    "MI",
    "EVET",
    "HAYIR",
    "FAIZSIZ",
    "FBK",
    "IPOTEK",
    "DERECE",
    "TESIS",
    "TARIH",
    "YEV",
    "YEVMIYE",
    "SIRA",
    "SURE",
    "YILLIK",
  ]);
  return cleanTakbisValue(value)
    .replace(/\bY[ıiIİ]ll[ıiIİ]k\s*%?\s*\d+(?:[.,]\d+)?\b/gi, " ")
    .replace(/%\s*\d+(?:[.,]\d+)?/g, " ")
    .replace(/\b\d+\s*\/\s*\d+\b/g, " ")
    .replace(/\b\d{1,2}[-.\/]\d{1,2}[-.\/]\d{4}(?:\s+\d{1,2}:\d{2})?\b/g, " ")
    .split(/\s+/)
    .filter((token) => {
      const folded = foldTurkish(token).replace(/[^A-Z0-9]/g, "");
      if (!folded) return false;
      if (noise.has(folded)) return false;
      if (/^YILLIK\d*$/.test(folded)) return false;
      if (/^\d+$/.test(folded)) return false;
      return true;
    })
    .join(" ")
    .replace(/\b(Katılım|Katilim)\s+\S+\s+(Bankas[ıi])\b/gi, "$1 $2")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeTakbisMortgageAmount(value) {
  return cleanTakbisValue(value)
    .replace(/\s*(?:TRY|T\.L\.)\b/i, " TL")
    .replace(/\s+/g, " ")
    .trim();
}

// Kullanıcı bildirimi (2026-08-15): "takbis yüklendikten sonra yeni bir
// takbis yüklendiğinde eski takbisteki veriler kalıyor. üstüne ekliyor.
// tamamını silmeli yeni takbis yükleyince" — ÖNCEKİ davranış yalnızca
// kullanıcının ELLE DEĞİŞTİRMEDİĞİ alanları temizliyordu (currentValue
// === previousSourceValue kontrolü), "manuel düzeltmeyi koru" niyetiyle
// eklenmişti; ama bu YENİ bir TAKBİS'in eski verinin bir kısmının
// (özellikle elle dokunulmuş görünen alanların) TABLODA KALMASINA yol
// açıyordu — kullanıcı bunu istemiyor. Yeni bir TAKBİS yüklendiğinde
// TÜM türetilmiş alanlar KOŞULSUZ temizlenir — resetKmlDerivedFields()
// zaten AYNI koşulsuz deseni kullanıyordu, TAKBİS artık ona uyuyor.
function resetTakbisTitleDerivedFields() {
  [
    "takbisReportDate",
    "takbisReportTime",
    "groundType",
    "titleQuality",
    "titlePropertyId",
    "titleCity",
    "titleDistrict",
    "titleNeighborhood",
    "blockNo",
    "parcelNo",
    "titleBlockName",
    "titleEntrance",
    "titleFloor",
    "unitNo",
    "share",
    "denominator",
    "landArea",
    "registryVolume",
    "registryPage",
    "mainPropertyQuality",
    "titleAttachment",
    "titleDate",
    "journalNo",
    "titleOwnershipKind",
    "addressBlockName",
    "takbisDate",
    "takbisTime",
    "takbisMethod",
    "takbisSummary",
  ].forEach((key) => {
    state.fields[key] = "";
  });
  state.tables.title = Array.from({ length: sections.find((section) => section.id === "title")?.table?.rows || 3 }, () => ({}));
  state.tables.encumbrance = Array.from({ length: sections.find((section) => section.id === "encumbrance")?.table?.rows || 5 }, () => ({}));
  encumbranceReportTables.forEach((table) => {
    state.tables[table.key] = [];
  });
  state.sourceValues.takbis = {};
  state.sourceConflicts.takbis = {};
}

function applyEkbFieldsToReport(options = {}) {
  const fields = state.sourceValues.ekb?.fields || {};
  state.sourceConflicts.ekb = {};

  Object.entries(fields).forEach(([key, value]) => {
    if (!value) return;
    setFieldFromSource("ekb", key, value, options);
  });
  refreshEkbExplanationFromCurrentFields("hasEkb");
}

function resetEkbDerivedFields() {
  [
    "ekbDocumentNo",
    "ekbIssueDate",
    "ekbValidUntil",
    "ekbEnergyClass",
    "ekbEmissionClass",
    "ekbExplanation",
    "ekbRawText",
  ].forEach((key) => {
    state.fields[key] = "";
  });
  state.fields.hasEkb = "";
  state.sourceValues.ekb = {};
  state.sourceConflicts.ekb = {};
}

function applyImarFieldsToReport(options = {}) {
  const fields = state.sourceValues.imar?.fields || {};
  state.sourceConflicts.imar = {};

  const mapped = {
    imarInfoInstitution: fields.bilgiAlinanKurum,
    planName: fields.planAdi,
    planScale: fields.planOlcegi,
    planDate: dateTrToIso(fields.planTarihi) || fields.planTarihi,
    legend: fields.planFonk,
    order: fields.insaatNizami,
    taks: fields.taks,
    kaks: fields.kaks,
    hmax: fields.binaYuksekligi,
    floorCount: fields.katAdedi,
    frontGarden: fields.onBahce,
    sideGarden: fields.yanBahce,
    backGarden: fields.arkaBahce,
    roadSetback: normalizeYesNoChoice(fields.yolaTerk),
    planRestrictionNote: fields.planRestrictionNote,
    planningNote: buildImarPlanningNote(fields),
    calculatedEmsal: buildImarCalculatedEmsal(fields),
  };

  Object.entries(mapped).forEach(([key, value]) => {
    if (!value) return;
    setFieldFromSource("imar", key, value, key === "planningNote" ? { ...options, force: true } : options);
  });
}

function resetImarDerivedFields() {
  [
    "imarInfoInstitution",
    "planName",
    "planScale",
    "planDate",
    "legend",
    "order",
    "taks",
    "kaks",
    "hmax",
    "floorCount",
    "frontGarden",
    "sideGarden",
    "backGarden",
    "roadSetback",
    "roadSetbackAmount",
    "roadSetbackBuildingImpact",
    "minimumFrontageCondition",
    "minimumFrontageConditionNote",
    "tevhidCondition",
    "tevhidConditionNote",
    "article18Applied",
    "article18AppliedNote",
    "urbanTransformationArea",
    "urbanTransformationAreaNote",
    "licenseObstacle",
    "licenseObstacleNote",
    "planRestrictionNote",
    "planningNote",
    "calculatedEmsal",
  ].forEach((key) => {
    const currentValue = state.fields[key] || "";
    const previousSourceValue = state.sourceValues.imar?.applied?.[key] || "";
    if (!currentValue || currentValue === previousSourceValue) {
      state.fields[key] = "";
    }
  });
  state.sourceValues.imar = {};
  state.sourceConflicts.imar = {};
}

function refreshMissingImarPlanDateFromRawText() {
  const rawText = state.sourceValues.imar?.rawText || "";
  if (!rawText || state.sourceValues.imar?.fields?.planTarihi) return false;
  const parsed = parseImarFields(rawText);
  if (!parsed.planTarihi) return false;
  state.sourceValues.imar.fields = {
    ...(state.sourceValues.imar.fields || {}),
    planTarihi: parsed.planTarihi,
  };
  if (!state.fields.planDate) {
    state.fields.planDate = dateTrToIso(parsed.planTarihi) || parsed.planTarihi;
  }
  return true;
}

function normalizeImarPlanNameForReport(value) {
  const text = normalizeReportTitleText(value || "").trim();
  if (!text) return "";
  if (!/IMAR\s+PLAN/.test(foldTurkish(text))) return text;
  const suffix = String(text.match(/\S+\s+\S+\s*$/)?.[0] || "");
  if (!/^IMAR\s+PLAN[II]?$/i.test(foldTurkish(suffix))) return text;
  return `${text.slice(0, text.length - suffix.length).trimEnd()} İmar Planı`.trim();
}

function normalizeImarLegendForReport(value) {
  const text = normalizeReportTitleText(value || "").trim();
  if (!text) return "";
  return text.replace(/\s+Alanı\s*$/i, "");
}

// Varyantlar docs/cumle-envanteri.md Bölüm 3'te belgelendi (buildImarPlanningNote
// ana paragraf gövdesi — daha önce plan iptali/plan-koşulları birleştirme
// mantığının karmaşıklığı nedeniyle ertelenmişti; burada yalnızca sabit
// bağlaç/kalıp ifadeler varyantlanıyor, koşul listesi (composeImarConditionList)
// ve tarih/kurum verisi öncekiyle aynı gerekçeyle DEĞİŞMİYOR).
const imarPlanCancelledVariants = [
  "yer aldığı imar planında iptal/yürütmeyi durdurma kararı bulunmaktadır.",
  "yer aldığı imar planı hakkında iptal/yürütmeyi durdurma kararı verilmiştir.",
];
const imarPlanCancelledConditionsVariants = [
  (conditions) => `Belediyeden alınan bilgiye göre plan iptali öncesindeki yapılaşma koşullarının ${conditions} şeklinde olduğu bilgisi alınmıştır.`,
  (conditions) => `Belediyeden edinilen bilgiye göre, plan iptalinden önceki yapılaşma koşullarının ${conditions} şeklinde olduğu tespit edilmiştir.`,
];
const imarPlanParcelLeadVariants = ["yer aldığı parsel", "içinde bulunduğu parsel"];
const imarPlanLegendClauseVariants = [
  (legend) => ` ${legend} alanında yer almakta olup`,
  (legend) => ` ${legend} alanı kapsamında bulunmakta olup`,
];
const imarPlanNoLegendClauseVariants = [" imar planı kapsamında değerlendirilmekte olup", " imar planı sınırları içerisinde değerlendirilmekte olup"];
const imarPlanConditionsTailVariants = [
  (conditions) => `, ${conditions} yapılaşma koşullarına sahiptir.`,
  (conditions) => `, ${conditions} yapılaşma koşullarını haizdir.`,
];
const imarPlanAgriculturalTailVariants = [", Plansız Alanlar Tip İmar Yönetmeliğine tabidir.", ", Plansız Alanlar Tip İmar Yönetmeliği hükümlerine tabidir."];
registerVariantGroup("buildImarPlanningNote:cancelled", "İmar Planı İptali — Ana Cümle (İmar Durumu)", imarPlanCancelledVariants.length);
registerVariantGroup("buildImarPlanningNote:cancelledConditions", "İmar Planı İptali — Önceki Koşullar (İmar Durumu)", imarPlanCancelledConditionsVariants.length);
registerVariantGroup("buildImarPlanningNote:parcelLead", "İmar Planı Notu — Parsel Girişi (İmar Durumu)", imarPlanParcelLeadVariants.length);
registerVariantGroup("buildImarPlanningNote:legendClause", "İmar Planı Notu — Lejant Bağlacı (İmar Durumu)", imarPlanLegendClauseVariants.length);
registerVariantGroup("buildImarPlanningNote:noLegendClause", "İmar Planı Notu — Lejantsız Bağlaç (İmar Durumu)", imarPlanNoLegendClauseVariants.length);
registerVariantGroup("buildImarPlanningNote:conditionsTail", "İmar Planı Notu — Yapılaşma Koşulları Kuyruğu (İmar Durumu)", imarPlanConditionsTailVariants.length);
registerVariantGroup("buildImarPlanningNote:agriculturalTail", "İmar Planı Notu — Plansız Alanlar Kuyruğu (İmar Durumu)", imarPlanAgriculturalTailVariants.length);

function buildImarPlanningNote(fields = {}) {
  const current = state.fields || {};
  const data = {
    infoInstitution: firstFilled(fields.bilgiAlinanKurum, current.imarInfoInstitution),
    inspectionDate: firstFilled(dateIsoToTr(current.municipalityInspectionDate), current.municipalityInspectionDate),
    planScale: firstFilled(fields.planOlcegi, current.planScale),
    planDate: firstFilled(fields.planTarihi, dateIsoToTr(current.planDate)),
    planName: normalizeImarPlanNameForReport(firstFilled(fields.planAdi, current.planName)),
    order: firstFilled(fields.insaatNizami, current.order),
    legend: normalizeImarLegendForReport(firstFilled(fields.planFonk, current.legend)),
    roadSetback: normalizeYesNoChoice(firstFilled(fields.yolaTerk, current.roadSetback)),
    roadSetbackAmount: firstFilled(fields.terkMiktari, current.roadSetbackAmount),
    roadSetbackBuildingImpact: normalizeYesNoChoice(firstFilled(fields.yapidanEtkilenme, current.roadSetbackBuildingImpact)),
    hmax: firstFilled(fields.binaYuksekligi, current.hmax),
    floorCount: firstFilled(fields.katAdedi, current.floorCount),
    taks: firstFilled(fields.taks, current.taks),
    kaks: firstFilled(fields.kaks, current.kaks),
    frontGarden: firstFilled(fields.onBahce, current.frontGarden),
    sideGarden: firstFilled(fields.yanBahce, current.sideGarden),
    backGarden: firstFilled(fields.arkaBahce, current.backGarden),
    minimumFrontageCondition: normalizeYesNoChoice(current.minimumFrontageCondition),
    minimumFrontageConditionNote: current.minimumFrontageConditionNote || "",
    tevhidCondition: normalizeYesNoChoice(current.tevhidCondition),
    tevhidConditionNote: current.tevhidConditionNote || "",
    article18Applied: normalizeYesNoChoice(current.article18Applied),
    article18AppliedNote: current.article18AppliedNote || "",
    urbanTransformationArea: normalizeYesNoChoice(current.urbanTransformationArea),
    urbanTransformationAreaNote: current.urbanTransformationAreaNote || "",
    licenseObstacle: normalizeYesNoChoice(current.licenseObstacle),
    licenseObstacleNote: current.licenseObstacleNote || "",
    planRestrictionNote: firstFilled(fields.planRestrictionNote, current.planRestrictionNote),
    ownershipType: firstFilled(fields.mulkuliyetTuru, current.ownershipType),
    planCancellationStay: normalizeYesNoChoice(current.planCancellationStay),
    planCancellationStayNote: current.planCancellationStayNote || "",
    hasPlanningIssue: normalizeYesNoChoice(current.hasPlanningIssue),
    netParcelArea: firstFilled(fields.netParselAlan, current.landArea),
  };

  const hasPlanningIssue = data.hasPlanningIssue === "Evet";
  const useDetailedStatus = isKuveytTurkSelectedForPlanning();
  if (!hasPlanningIssue) {
    Object.assign(data, {
      planCancellationStay: "Hayır",
      roadSetback: "Hayır",
      minimumFrontageCondition: "Hayır",
      tevhidCondition: "Hayır",
      article18Applied: "Evet",
      urbanTransformationArea: "Hayır",
      licenseObstacle: "Hayır",
      roadSetbackAmount: "",
      roadSetbackBuildingImpact: "",
    });
    data.planRestrictionNote = "";
    if (!useDetailedStatus) {
      data.planCancellationStayNote = "";
      data.minimumFrontageConditionNote = "";
      data.tevhidConditionNote = "";
      data.article18AppliedNote = "";
      data.urbanTransformationAreaNote = "";
      data.licenseObstacleNote = "";
    }
  }

  const planCancelled = data.planCancellationStay === "Evet";
  const parts = [];
  const sourcePrefix = composeImarInfoSourcePrefix(data);

  if (planCancelled) {
    let cancelledText = `${sourcePrefix || "Konu taşınmazın "}${imarPlanCancelledVariants[selectVariant("buildImarPlanningNote:cancelled", imarPlanCancelledVariants.length)]}`;
    if (data.planCancellationStayNote) cancelledText += ` (${data.planCancellationStayNote})`;
    if (data.planRestrictionNote) cancelledText += ` ${data.planRestrictionNote}`;
    const conditions = composeImarConditionList(data);
    if (conditions.length) {
      cancelledText += ` ${imarPlanCancelledConditionsVariants[selectVariant("buildImarPlanningNote:cancelledConditions", imarPlanCancelledConditionsVariants.length)](conditions.join(", "))}`;
    }
    parts.push(cancelledText);
  } else {
    const introBits = [];
    if (data.planDate) introBits.push(`${data.planDate} tarihli`);
    if (data.planScale) introBits.push(`${data.planScale} ölçekli`);
    if (data.planName) introBits.push(data.planName);

    let mainText = `${sourcePrefix || "Konu taşınmazın "}${imarPlanParcelLeadVariants[selectVariant("buildImarPlanningNote:parcelLead", imarPlanParcelLeadVariants.length)]}`;
    if (introBits.length) mainText += `, ${introBits.join(" ")} kapsamında`;
    mainText += data.legend
      ? imarPlanLegendClauseVariants[selectVariant("buildImarPlanningNote:legendClause", imarPlanLegendClauseVariants.length)](data.legend)
      : imarPlanNoLegendClauseVariants[selectVariant("buildImarPlanningNote:noLegendClause", imarPlanNoLegendClauseVariants.length)];
    const conditions = composeImarConditionList(data);
    if (conditions.length) {
      mainText += imarPlanConditionsTailVariants[selectVariant("buildImarPlanningNote:conditionsTail", imarPlanConditionsTailVariants.length)](conditions.join(", "));
    } else if (isAgriculturalPlanningLegend(data.legend)) {
      mainText += imarPlanAgriculturalTailVariants[selectVariant("buildImarPlanningNote:agriculturalTail", imarPlanAgriculturalTailVariants.length)];
    } else {
      mainText += ".";
    }
    parts.push(mainText);

    const shouldIncludeRoadSetbackText = (data.roadSetback === "Hayır" && isThousandScalePlan(data.planScale))
      || hasPlanningIssue
      || useDetailedStatus;
    const roadSetbackText = shouldIncludeRoadSetbackText
      ? composeImarRoadSetbackSentence(data)
      : "";
    if (roadSetbackText) parts.push(roadSetbackText);
    if (shouldIncludeIsbankUrbanNoRiskAreaNote(data)) {
      parts.push("KENTSEL DÖNÜŞÜM(RİSKLİ ALAN) BÖLGESİNDE KALMAMAKTADIR.");
    }
    if (data.planRestrictionNote) parts.push(data.planRestrictionNote);
  }

 parts.push(...composeImarPlanningStatusParagraphs(data));
  const note = normalizeReportDescriptionText(parts.filter(Boolean).join("\n\n"));
  const sharedParcelNarrative = typeof getSharedNarrativeParcelPhrase === "function"
    ? getSharedNarrativeParcelPhrase()
    : "";
  return pluralizeEnvironmentalSubjectText(note, Boolean(sharedParcelNarrative));
}

function isAgriculturalPlanningLegend(value = "") {
  const legend = foldTurkish(normalizeReportTitleText(value || ""));
  return legend.includes("TARLA") || legend.includes("TARIM");
}

function buildImarCalculatedEmsal(fields = {}) {
  const current = state.fields || {};
  return composeImarCalculatedEmsal({
    netParcelArea: firstFilled(fields.netParselAlan, current.landArea),
    kaks: firstFilled(fields.kaks, current.kaks),
    floorCount: firstFilled(fields.katAdedi, current.floorCount),
    planCancellationStay: normalizeYesNoChoice(firstFilled(fields.planCancellationStay, current.planCancellationStay)),
  });
}

function firstFilled(...values) {
  return values.find((value) => String(value || "").trim()) || "";
}

// Varyantlar docs/cumle-envanteri.md Bölüm 3'te belgelendi.
function composeImarInfoSourcePrefix(data) {
  const date = data.inspectionDate ? dateIsoToTr(data.inspectionDate) : "";
  const institution = formatImarInstitutionSource(data.infoInstitution);
  if (date && institution) {
    const variants = [
      `${date} tarihinde ${institution} alınan bilgiye göre konu taşınmazın `,
      `${date} tarihinde ${institution} edinilen bilgiye göre söz konusu taşınmazın `,
      `${institution} ${date} tarihinde temin edilen bilgiye göre ekspertize konu gayrimenkulün `,
      `${institution} ${date} tarihinde alınan bilgiye göre söz konusu taşınmazın `,
    ];
    return variants[selectVariant("composeImarInfoSourcePrefix:both", variants.length)];
  }
  if (date) {
    const variants = [
      `${date} tarihinde alınan bilgiye göre konu taşınmazın `,
      `${date} tarihinde edinilen bilgiye göre söz konusu taşınmazın `,
      `${date} tarihinde temin edilen bilgiye göre ekspertize konu gayrimenkulün `,
    ];
    return variants[selectVariant("composeImarInfoSourcePrefix:dateOnly", variants.length)];
  }
  if (institution) {
    const variants = [
      `${institution} alınan bilgiye göre konu taşınmazın `,
      `${institution} edinilen bilgiye göre söz konusu taşınmazın `,
      `${institution} temin edilen bilgiye göre ekspertize konu gayrimenkulün `,
    ];
    return variants[selectVariant("composeImarInfoSourcePrefix:institutionOnly", variants.length)];
  }
  return "";
}
registerVariantGroup("composeImarInfoSourcePrefix:both", "İmar Bilgi Kaynağı Önsözü — tarih+kurum (İmar Durumu)", 4);
registerVariantGroup("composeImarInfoSourcePrefix:dateOnly", "İmar Bilgi Kaynağı Önsözü — yalnız tarih (İmar Durumu)", 3);
registerVariantGroup("composeImarInfoSourcePrefix:institutionOnly", "İmar Bilgi Kaynağı Önsözü — yalnız kurum (İmar Durumu)", 3);

function formatImarInstitutionSource(value) {
  const institution = getImarInstitutionValues(value)
    .map((item) => normalizeReportTitleText(item).trim())
    .filter(Boolean)
    .join(" ve ");
  if (!institution) return "";
  if (/Belediyesi$/i.test(institution)) return institution.replace(/Belediyesi$/i, "Belediyesinden");
  if (/Müdürlüğü$/i.test(institution)) return institution.replace(/Müdürlüğü$/i, "Müdürlüğünden");
  if (/İdaresi$/i.test(institution)) return institution.replace(/İdaresi$/i, "İdaresinden");
  return `${institution} kurumundan`;
}

function composeImarConditionList(data) {
  return [
    data.order ? `${data.order} nizam` : "",
    data.floorCount ? formatImarFloorCount(data.floorCount) : "",
    data.hmax ? `Hmax: ${formatImarMeasurement(data.hmax)}` : "",
    data.taks ? `TAKS: ${formatImarDecimal(data.taks)}` : "",
    data.kaks ? `KAKS/Emsal: ${formatImarDecimal(data.kaks)}` : "",
    data.frontGarden ? `Ön Bahçe: ${formatImarMeasurement(data.frontGarden)}` : "",
    data.sideGarden ? `Yan Bahçe: ${formatImarMeasurement(data.sideGarden)}` : "",
    data.backGarden ? `Arka Bahçe: ${formatImarMeasurement(data.backGarden)}` : "",
  ].filter(Boolean);
}

function formatImarFloorCount(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  if (/kat/i.test(text)) return text;
  const number = parseReportNumber(text);
  if (Number.isFinite(number)) return `${number.toLocaleString("tr-TR", { maximumFractionDigits: 0 })} kat`;
  return `Kat Adedi: ${text}`;
}

function formatImarMeasurement(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  if (/serbest/i.test(text)) return normalizeReportTitleText(text);
  const number = parseReportNumber(text);
  if (!Number.isFinite(number)) return text;
  return `${number.toLocaleString("tr-TR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} m`;
}

function formatImarDecimal(value) {
  const text = String(value || "").trim();
  const number = parseReportNumber(text);
  if (!Number.isFinite(number)) return text;
  return number.toLocaleString("tr-TR", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// Varyantlar docs/cumle-envanteri.md Bölüm 3'te belgelendi.
function composeImarRoadSetbackSentence(data) {
  if (data.roadSetback === "Evet") {
    const amount = data.roadSetbackAmount ? ` yaklaşık ${formatImarSquareMeter(data.roadSetbackAmount)}` : "";
    const impactYesVariants = [" Söz konusu terkin yapıya etkisi bulunmaktadır.", " Bu terkin yapı üzerinde etkisi bulunmaktadır."];
    const impactNoVariants = [" Söz konusu terkin yapıya etkisi bulunmamaktadır.", " Bu terkin yapı üzerinde etkisi bulunmamaktadır."];
    const impact = data.roadSetbackBuildingImpact === "Evet"
      ? impactYesVariants[selectVariant("composeImarRoadSetbackSentence:impact:evet", impactYesVariants.length)]
      : data.roadSetbackBuildingImpact === "Hayır"
        ? impactNoVariants[selectVariant("composeImarRoadSetbackSentence:impact:hayir", impactNoVariants.length)]
        : "";
    const variants = [
      `Taşınmazın yer aldığı parselin yola/parka${amount} terki bulunmaktadır.`,
      `Gayrimenkulün konumlandığı parselden yola/parka${amount} terk ayrılmıştır.`,
      `Söz konusu parselden yola/parka${amount} terk ayrılmıştır.`,
      `Parselin yola/parka${amount} terki bulunmaktadır.`,
    ];
    return `${variants[selectVariant("composeImarRoadSetbackSentence:var", variants.length)]}${impact}`;
  }
  if (data.roadSetback === "Hayır") {
    const isKatIrtifaki = ["Dikey Kat İrtifakı", "Yatay Kat İrtifakı"].includes(data.ownershipType);
    if (isKatIrtifaki) {
      const subject = isMultiTitleUnitReportForNarrative() ? "Taşınmazların" : "Taşınmazın";
      return `${subject} yer aldığı parselin yola/parka terki bulunmamaktadır.`;
    }
    if (isThousandScalePlan(data.planScale)) {
      const variants = [
        "Taşınmazın Yola/Parka terki bulunmamaktadır.",
        "Gayrimenkulün yola/parka terki bulunmamaktadır.",
        "Söz konusu taşınmazın yola/parka herhangi bir terki bulunmamaktadır.",
      ];
      return variants[selectVariant("composeImarRoadSetbackSentence:yok:1000", variants.length)];
    }
    const variants = [
      "Taşınmazın yer aldığı parselin yola/parka terki bulunmamaktadır.",
      "Gayrimenkulün yer aldığı parselden yola/parka herhangi bir terk ayrılmamıştır.",
      "Söz konusu parselden yola/parka herhangi bir terk söz konusu değildir.",
      "Taşınmazın bulunduğu parselde yola/parka terke rastlanmamıştır.",
    ];
    return variants[selectVariant("composeImarRoadSetbackSentence:yok:parsel", variants.length)];
  }
  return "";
}
registerVariantGroup("composeImarRoadSetbackSentence:var", "Yola/Parka Terk — terk var (İmar Durumu)", 4);
registerVariantGroup("composeImarRoadSetbackSentence:impact:evet", "Yola/Parka Terk — yapıya etkisi var (İmar Durumu)", 2);
registerVariantGroup("composeImarRoadSetbackSentence:impact:hayir", "Yola/Parka Terk — yapıya etkisi yok (İmar Durumu)", 2);
registerVariantGroup("composeImarRoadSetbackSentence:yok:1000", "Yola/Parka Terk — terk yok, 1/1000 plan (İmar Durumu)", 3);
registerVariantGroup("composeImarRoadSetbackSentence:yok:parsel", "Yola/Parka Terk — terk yok, genel (İmar Durumu)", 4);

function isThousandScalePlan(value) {
  const text = String(value || "").trim();
  if (!text) return false;
  return /^1\s*\/\s*1\.?000\b/.test(text) || /^1\s*\/\s*1000\b/.test(text);
}

function shouldIncludeIsbankUrbanNoRiskAreaNote(data) {
  return isIsbankSelectedForReport()
    && data.roadSetback === "Hayır"
    && data.urbanTransformationArea === "Hayır"
    && isThousandScalePlan(data.planScale);
}

// Varyantlar docs/cumle-envanteri.md Bölüm 3'te belgelendi — "genel fiil-
// dönüşüm kuralı": 5 alt-durumun (Min. Cephe/18. Madde/Tevhid/Kentsel
// Dönüşüm/Ruhsat) hepsine AYNI stil bir kez seçilip uygulanır (rapor içi
// tutarlılık için — bir raporun bir yerinde "mevcuttur" derken başka
// yerinde "bulunmaktadır" demesi tuhaf kaçar).
const imarVerbStyleVariants = [
  { bulunmaktadir: "bulunmaktadır", bulunmamaktadir: "bulunmamaktadır", yapilmistir: "yapılmıştır", yapilmamistir: "yapılmamıştır", yerAlmaktadir: "yer almaktadır", yerAlmamaktadir: "yer almamaktadır" },
  { bulunmaktadir: "mevcuttur", bulunmamaktadir: "söz konusu değildir", yapilmistir: "uygulanmıştır", yapilmamistir: "uygulanmamıştır", yerAlmaktadir: "kapsamında bulunmaktadır", yerAlmamaktadir: "kapsamı dışındadır" },
  { bulunmaktadir: "vardır", bulunmamaktadir: "yoktur", yapilmistir: "gerçekleştirilmiştir", yapilmamistir: "gerçekleştirilmemiştir", yerAlmaktadir: "dahilindedir", yerAlmamaktadir: "dahil değildir" },
  { bulunmaktadir: "mevcuttur", bulunmamaktadir: "mevcut değildir", yapilmistir: "icra edilmiştir", yapilmamistir: "icra edilmemiştir", yerAlmaktadir: "kapsam dahilindedir", yerAlmamaktadir: "kapsam haricindedir" },
  { bulunmaktadir: "söz konusudur", bulunmamaktadir: "söz konusu değildir", yapilmistir: "hayata geçirilmiştir", yapilmamistir: "hayata geçirilmemiştir", yerAlmaktadir: "içerisinde yer almaktadır", yerAlmamaktadir: "dışında kalmaktadır" },
];
registerVariantGroup("composeImarPlanningStatusParagraphs:verbStyle", "İmar Durum Paragrafları — genel fiil-dönüşüm stili (İmar Durumu)", imarVerbStyleVariants.length);

const urbanTransformationYesVariants = [
  "Taşınmaz kentsel dönüşüm/yenileme alanında yer almaktadır.",
  "Taşınmaz kentsel dönüşüm/yenileme alanı kapsamında bulunmaktadır.",
  "Söz konusu taşınmaz kentsel dönüşüm/yenileme alanı içerisindedir.",
];
const urbanTransformationNoVariants = [
  "Taşınmaz kentsel dönüşüm/yenileme alanında yer almamaktadır.",
  "Taşınmaz kentsel dönüşüm/yenileme alanı kapsamında bulunmamaktadır.",
  "Söz konusu taşınmaz kentsel dönüşüm/yenileme alanı dışındadır.",
];
registerVariantGroup("composeImarPlanningStatusParagraphs:urbanTransformation:evet", "Kentsel Dönüşüm — alanda (İmar Durumu)", urbanTransformationYesVariants.length);
registerVariantGroup("composeImarPlanningStatusParagraphs:urbanTransformation:hayir", "Kentsel Dönüşüm — alan dışı (İmar Durumu)", urbanTransformationNoVariants.length);

function composeImarPlanningStatusParagraphs(data) {
  const paragraphs = [];
  const includeFallback = data.hasPlanningIssue === "Evet" || isKuveytTurkSelectedForPlanning();
  const verbStyle = imarVerbStyleVariants[selectVariant("composeImarPlanningStatusParagraphs:verbStyle", imarVerbStyleVariants.length)];
  if (data.minimumFrontageCondition) {
    const paragraph = composeImarStatusParagraph(
      "Minimum Cephe Şartı",
      data.minimumFrontageConditionNote,
      `Minimum cephe şartı ${data.minimumFrontageCondition === "Evet" ? verbStyle.bulunmaktadir : verbStyle.bulunmamaktadir}.`,
      includeFallback
    );
    if (paragraph) paragraphs.push(paragraph);
  }
  if (data.article18Applied) {
    const paragraph = composeImarStatusParagraph(
      "18. Madde Uygulaması",
      data.article18AppliedNote,
      `18. Madde uygulaması ${data.article18Applied === "Evet" ? verbStyle.yapilmistir : verbStyle.yapilmamistir}.`,
      includeFallback
    );
    if (paragraph) paragraphs.push(paragraph);
  }
  if (data.tevhidCondition) {
    const paragraph = composeImarStatusParagraph(
      "Tevhid Şartı",
      data.tevhidConditionNote,
      `Tevhid şartı ${data.tevhidCondition === "Evet" ? verbStyle.bulunmaktadir : verbStyle.bulunmamaktadir}.`,
      includeFallback
    );
    if (paragraph) paragraphs.push(paragraph);
  }
  if (data.urbanTransformationArea) {
    const paragraph = composeImarStatusParagraph(
      "Kentsel Dönüşüm",
      data.urbanTransformationAreaNote,
      data.urbanTransformationArea === "Evet"
        ? urbanTransformationYesVariants[selectVariant("composeImarPlanningStatusParagraphs:urbanTransformation:evet", urbanTransformationYesVariants.length)]
        : urbanTransformationNoVariants[selectVariant("composeImarPlanningStatusParagraphs:urbanTransformation:hayir", urbanTransformationNoVariants.length)],
      includeFallback
    );
    if (paragraph) paragraphs.push(paragraph);
  }
  if (data.licenseObstacle) {
    const paragraph = composeImarStatusParagraph(
      "Ruhsat Durumu",
      data.licenseObstacleNote,
      `Ruhsat almaya engel herhangi bir durum ${data.licenseObstacle === "Evet" ? verbStyle.bulunmaktadir : verbStyle.bulunmamaktadir}.`,
      includeFallback
    );
    if (paragraph) paragraphs.push(paragraph);
  }
  return paragraphs;
}

function composeImarStatusParagraph(title, note, fallbackSentence, includeFallback = true) {
  const cleanNote = normalizeReportDescriptionText(note || "").trim();
  if (!cleanNote && !includeFallback) return "";
  return `${title}:\n${cleanNote || fallbackSentence}`;
}

function isKuveytTurkSelectedForPlanning() {
  return foldTurkish(state.fields?.bank || "").includes("KUVEYT TURK");
}

function composeImarCalculatedEmsal(data) {
  if (normalizeYesNoChoice(data.planCancellationStay) === "Evet") return "";
  const parcelArea = parseReportNumber(data.netParcelArea);
  if (!Number.isFinite(parcelArea) || parcelArea <= 0) return "";
  const rawKaks = String(data.kaks || "").trim();
  if (rawKaks) {
    const kaks = parseReportNumber(rawKaks);
    if (Number.isFinite(kaks) && kaks > 0) {
      return formatImarSquareMeter(kaks * parcelArea);
    }
    return "";
  }
  const floorCount = parseReportNumber(data.floorCount);
  if (Number.isFinite(floorCount) && floorCount > 0) {
    return formatImarSquareMeter(floorCount * parcelArea);
  }
  return "";
}

function formatImarSquareMeter(value) {
  const number = Number.isFinite(value) ? value : parseReportNumber(value);
  if (!Number.isFinite(number)) return String(value || "");
  return `${number.toLocaleString("tr-TR", { maximumFractionDigits: 0 })} m²`;
}

function refreshTransportAfterAddressChange() {
  const road = getAllMainArteryPlacesWithUser(state.sourceValues.nearbyPlaces?.places || [])
    .find((item) => item.id === state.fields.mainArteryId);
  if (road) {
    updateTransportFromMainArtery(road);
  }
}

