function createNearbyEnvironmentTools(options = {}) {
  const wrapper = document.createElement("div");
  wrapper.className = options.compact ? "nearby-tools nearby-tools-inline" : "nearby-tools";
  refreshUserPoisForCurrentLocationOnce();
  const source = state.sourceValues.nearbyPlaces || {};
  const places = getAllNearbyPlacesWithUser(source.places || []);
  const error = formatNearbyError(state.uploadErrors?.nearbyPlaces);
  const loadingText = source.loading ? "Çevre taraması sürüyor..." : `${places.length} öğe bulundu`;
  const statusText = places.length ? loadingText : `KML yüklendiğinde ${getNearbyScanRadiusMeters()} m çevre otomatik taranacak.`;
  const buttonDisabled = !getSelectedMapPoint() || source.loading;
  const selectedIds = new Set(source.selectedIds || []);
  const displayPlaces = getNearbySelectionDisplayPlaces(source);
  const displaySelectedCount = displayPlaces.filter((place) => selectedIds.has(place.id)).length;

  wrapper.innerHTML = `
    <div class="nearby-inline-head">
      <strong>Yakın çevre seçimi</strong>
      <button class="mini-button" type="button" data-nearby-refresh ${buttonDisabled ? "disabled" : ""}>${source.loading ? "Taranıyor" : "Çevreyi tara"}</button>
    </div>
    <div class="kml-summary">
      <span>${statusText}</span>
      <span>${displaySelectedCount} öğe seçili</span>
      ${source.center ? `<span>Merkez: ${escapeHtml(source.center.lat)}, ${escapeHtml(source.center.lng)}</span>` : ""}
      ${error ? `<span class="warning-text">${escapeHtml(error)}</span>` : ""}
    </div>
    <div class="nearby-flat-list"></div>
  `;

  const list = wrapper.querySelector(".nearby-flat-list");
  if (error) {
    const status = document.createElement("p");
    status.className = "muted-note warning-text nearby-warning";
    status.textContent = error;
    wrapper.insertBefore(status, list);
  }
  if (!displayPlaces.length) {
    const empty = document.createElement("p");
    empty.className = "muted-note";
    empty.textContent = "Bulgu yok";
    list.append(empty);
  } else {
    displayPlaces.forEach((place) => {
      const item = document.createElement("label");
      item.className = "nearby-item nearby-flat-item";
      item.innerHTML = `
        <input type="checkbox" data-nearby-id="${escapeHtml(place.id)}" ${selectedIds.has(place.id) ? "checked" : ""} />
        <span>${escapeHtml(place.name)}<small>${Math.round(place.distance)} m</small></span>
      `;
      list.append(item);
    });
  }

  wrapper.querySelector("[data-nearby-refresh]").addEventListener("click", async () => {
    await fetchNearbyPlacesForCurrentLocation({ force: true, rotate: true });
    autosave();
    renderSection();
  });

  wrapper.querySelectorAll("[data-nearby-id]").forEach((input) => {
    input.addEventListener("change", () => {
      toggleNearbySelection(input.dataset.nearbyId, input.checked);
      autosave();
      renderSection();
      if (document.querySelector("#kmlMapPanel")) {
        renderLeafletKmlMap();
      }
    });
  });

  return wrapper;
}

function formatNearbyError(message) {
  if (!message) return "";
  if (/failed to fetch|networkerror|load failed/i.test(message)) {
    return "Çevre servisine ulaşılamadı. İnternet bağlantısını kontrol edip tekrar deneyin.";
  }
  return message;
}

async function fetchNearbyPlacesForCurrentLocation(options = {}) {
  const point = getSelectedMapPoint();
  if (!point) {
    if (!options.silent) {
      state.uploadErrors = { ...(state.uploadErrors || {}), nearbyPlaces: "Çevre taraması için önce KML veya koordinat gerekli." };
    }
    return;
  }

  const [lat, lng] = point;
  if (state.sourceValues.nearbyPlaces?.loading && !options.force) return;
  const requestId = ++nearbyRequestSerial;

  state.sourceValues.nearbyPlaces = {
    ...(state.sourceValues.nearbyPlaces || {}),
    loading: true,
    center: { lat: Number(lat).toFixed(6), lng: Number(lng).toFixed(6) },
  };

  try {
    const environment = await fetchNearbyPlacesWithCoverage(lat, lng);
    if (requestId !== nearbyRequestSerial) return;
    const places = environment.places || [];
    const scanCycle = options.rotate ? (state.sourceValues.nearbyPlaces?.scanCycle || 0) + 1 : state.sourceValues.nearbyPlaces?.scanCycle || 0;
    state.sourceValues.nearbyPlaces = {
      places,
      selectedIds: [],
      selectionCustomized: false,
      scanCycle,
      center: { lat: Number(lat).toFixed(6), lng: Number(lng).toFixed(6) },
      radius: environment.radius || nearbyRadiusMeters,
      readAt: new Date().toISOString(),
      loading: false,
    };
    state.uploadErrors = { ...(state.uploadErrors || {}), nearbyPlaces: "" };
    applyRegionAnalysisFields(environment.regionAnalysis);
    clearOutOfRangeMainArterySelection(places);
    updateNearbyFieldFromSelection();
  } catch (error) {
    if (requestId !== nearbyRequestSerial) return;
    state.sourceValues.nearbyPlaces = {
      ...(state.sourceValues.nearbyPlaces || {}),
      loading: false,
    };
    state.uploadErrors = {
      ...(state.uploadErrors || {}),
      nearbyPlaces: error.message || "Yakın çevre verileri okunamadı.",
    };
  }
}

function getAllNearbyPlacesWithUser(places = []) {
  const map = new Map();
  const selectedIds = new Set(state.sourceValues.nearbyPlaces?.selectedIds || []);
  [...getUserNearbyPlaces(), ...places].forEach((place) => {
    if (!place?.id || (!selectedIds.has(place.id) && !isNearbyPlaceInAddressRadius(place))) return;
    map.set(place.id, place);
  });
  return [...map.values()];
}

function getUserNearbyPlaces() {
  const selectedIds = new Set(state.sourceValues.nearbyPlaces?.selectedIds || []);
  return (state.sourceValues.userNearbyPlaces?.places || [])
    .filter((place) => place.category === "user")
    .filter((place) => selectedIds.has(place.id) || isNearbyPlaceInAddressRadius(place))
    .sort((a, b) => a.distance - b.distance);
}

function isUserNearbyPlaceInAddressRadius(place = {}) {
  return isNearbyPlaceInAddressRadius(place);
}

function isNearbyPlaceInAddressRadius(place = {}) {
  const distance = Number(place.distance);
  getNearbySelectionRadiusMeters();
  return Number.isFinite(distance) && distance >= 0 && distance <= nearbySelectionRadiusMeters;
}

function getUserMainArteryPlaces() {
  return (state.sourceValues.userNearbyPlaces?.places || [])
    .filter((place) => place.category === "user-artery")
    .filter((place) => isNearbyPlaceInAddressRadius(place))
    .sort((a, b) => a.distance - b.distance);
}

function getAllMainArteryPlacesWithUser(places = []) {
  const map = new Map();
  [...getUserMainArteryPlaces(), ...getNearbyArteries(places)].forEach((place) => {
    if (!place?.id || !isNearbyPlaceInAddressRadius(place)) return;
    map.set(place.id, place);
  });
  return [...map.values()];
}

function getNearbySelectionDisplayPlaces(source = state.sourceValues.nearbyPlaces || {}) {
  const allUserPlaces = getUserNearbyPlaces();
  const selectedIds = new Set(source.selectedIds || []);
  const autoSourcePlaces = (source.places || []).filter((place) => selectedIds.has(place.id) || isNearbyPlaceInAddressRadius(place));
  const usefulPlaceCount = [...allUserPlaces, ...autoSourcePlaces]
    .filter((place) => importantNearbyCategories.has(place.category) && !isSettlementLikeNearbyPlace(place))
    .length;
  const userPlaces = usefulPlaceCount >= nearbySettlementFallbackMinUsefulCount
    ? allUserPlaces.filter((place) => !isSettlementLikeNearbyPlace(place))
    : allUserPlaces;
  const userIds = new Set(userPlaces.map((place) => place.id));
  const autoPlaces = getNearbyDisplayPlaces(autoSourcePlaces, source.scanCycle || 0)
    .filter((place) => !userIds.has(place.id));
  return [...userPlaces, ...autoPlaces];
}

function isSettlementLikeNearbyPlace(place) {
  const name = String(place?.name || "");
  return place?.category === "settlements" || /\b(?:mah\.?|mahallesi|mahalle|köyü|koyu|köy|koy)\b/i.test(name);
}

function refreshUserPoisForCurrentLocationOnce() {
  const point = getSelectedMapPoint();
  if (!point) return;
  const key = `${Number(point[0]).toFixed(4)},${Number(point[1]).toFixed(4)}`;
  if (state.sourceValues.userNearbyPlaces?.loadedFor === key || state.sourceValues.userNearbyPlaces?.loading) return;
  refreshUserPoisFromServer({ loadedFor: key, select: true }).catch(() => {});
}

async function refreshUserPoisFromServer(options = {}) {
  const point = getSelectedMapPoint();
  if (!point) return [];
  state.sourceValues.userNearbyPlaces = {
    ...(state.sourceValues.userNearbyPlaces || {}),
    loading: true,
  };
  try {
    const response = await fetchRaporApi("/api/user-pois");
    const data = await response.json();
    const places = (data.pois || [])
      .map((poi) => normalizeUserPoiAsNearbyPlace(poi, point))
      .filter(Boolean)
      .sort((a, b) => a.distance - b.distance);
    state.sourceValues.userNearbyPlaces = {
      places,
      loadedFor: options.loadedFor || `${Number(point[0]).toFixed(4)},${Number(point[1]).toFixed(4)}`,
      loading: false,
    };
    clearOutOfRangeMainArterySelection(state.sourceValues.nearbyPlaces?.places || []);
    if (options.select) {
      const nearbySource = state.sourceValues.nearbyPlaces || {};
      const validIds = new Set(getNearbySelectionDisplayPlaces(nearbySource).map((place) => place.id));
      state.sourceValues.nearbyPlaces = {
        ...nearbySource,
        selectedIds: nearbySource.selectionCustomized
          ? (nearbySource.selectedIds || []).filter((id) => validIds.has(id))
          : [],
      };
    }
    updateNearbyFieldFromSelection();
    return places;
  } catch (error) {
    state.sourceValues.userNearbyPlaces = {
      ...(state.sourceValues.userNearbyPlaces || {}),
      loading: false,
      error: error.message || String(error),
    };
    return [];
  }
}

function normalizeUserPoiAsNearbyPlace(poi, point) {
  const lat = Number(poi?.lat);
  const lng = Number(poi?.lng);
  const name = cleanupPlaceName(poi?.name || "");
  const category = poi?.category === "user-artery" ? "user-artery" : "user";
  if (!name || !Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  return {
    id: poi.id || `user-${lat}-${lng}-${name}`,
    name,
    category,
    source: category === "user-artery" ? "Kullanıcı Ulaşım Arteri" : "Kullanıcı",
    lat,
    lng,
    distance: calculateDistanceMeters(point[0], point[1], lat, lng),
  };
}

async function saveUserPoiFromMap(input, statusElement) {
  const point = getSelectedMapPoint();
  const name = normalizeReportTitleText(input?.value || "").trim();
  if (!point) {
    if (statusElement) statusElement.textContent = "Önce haritada koordinat seçin.";
    return;
  }
  if (!name) {
    if (statusElement) statusElement.textContent = "Nokta adını yazın.";
    return;
  }
  if (statusElement) statusElement.textContent = "Kaydediliyor...";
  const response = await fetchRaporApi("/api/user-pois", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name, lat: point[0], lng: point[1] }),
  });
  const data = await response.json();
  if (!response.ok || data.ok === false) {
    if (statusElement) statusElement.textContent = data.error || "Kaydedilemedi.";
    return;
  }
  if (input) input.value = "";
  await refreshUserPoisFromServer({ force: true });
  updateNearbyFieldFromSelection();
  autosave();
  if (statusElement) statusElement.textContent = "Kaydedildi.";
  renderSection();
}

async function saveUserMainArteryFromMap(input, statusElement) {
  const point = getSelectedMapPoint();
  const name = normalizeReportTitleText(input?.value || "").trim();
  if (!point) {
    if (statusElement) statusElement.textContent = "Önce haritada koordinat seçin.";
    return;
  }
  if (!name) {
    if (statusElement) statusElement.textContent = "Arter adını yazın.";
    return;
  }
  if (statusElement) statusElement.textContent = "Ulaşım arteri kaydediliyor...";
  const response = await fetchRaporApi("/api/user-pois", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name, lat: point[0], lng: point[1], category: "user-artery" }),
  });
  const data = await response.json();
  if (!response.ok || data.ok === false) {
    if (statusElement) statusElement.textContent = data.error || "Ulaşım arteri kaydedilemedi.";
    return;
  }
  if (input) input.value = "";
  await refreshUserPoisFromServer({ force: true });
  autosave();
  if (statusElement) statusElement.textContent = "Ulaşım arteri kaydedildi.";
  renderSection();
}

function maybeAutoFetchNearbyPlaces() {
  const hasKmlPoint = Boolean(state.sourceValues.kml?.centroid || getSelectedMapPoint());
  const source = state.sourceValues.nearbyPlaces;
  // Kullanıcı talebi: "yakın çevre seçiliyor, talepten çıkıldığında tekrar
  // girildiğinde seçili yakın çevrenin seçili olmadığı görülüyor" — kök
  // neden: `hasRequiredNearbyCoverage` eşiği (en az `nearbyAutoLimit`
  // öğe + `mainArteryAutoLimit` arter) karşılanmayan bölgelerde (ör. az
  // POI'li kırsal/yeni yerleşim) HER sayfa yüklemesinde/rapor tekrar
  // açılışında (nearbyAutoFetchStarted modül-kapsamlı bir bayrak olduğu
  // için sayfa yenilenince sıfırlanıyor) bu fonksiyon sessizce yeniden
  // tarama başlatıyordu — `fetchNearbyPlacesForCurrentLocation` HER
  // taramada `selectedIds`'i KOŞULSUZ boşaltıyor, yani kullanıcının elle
  // seçtiği öğeler (`selectionCustomized: true`) sessizce siliniyordu.
  // Kullanıcı zaten seçim yaptıysa (selectionCustomized) kapsam eşiği
  // karşılanmasa bile OTOMATİK yeniden taramayı ATLA — mevcut seçim
  // korunsun; kullanıcı isterse "Çevreyi tara" düğmesiyle elle
  // yenileyebilir (o akış hâlâ eskisi gibi sıfırlar, bilinçli bir eylem).
  const hasEnoughNearbyData = source?.readAt
    && (source.selectionCustomized || hasRequiredNearbyCoverage(source.places || []));
  if (!hasKmlPoint || hasEnoughNearbyData || source?.loading || nearbyAutoFetchStarted) return;

  nearbyAutoFetchStarted = true;
  state.sourceValues.nearbyPlaces = {
    ...(state.sourceValues.nearbyPlaces || {}),
    loading: true,
  };
  if (activeSectionId === "address") {
    renderSection();
  }
  fetchNearbyPlacesForCurrentLocation({ silent: true, force: true }).then(() => {
    autosave();
    if (activeSectionId === "address") {
      renderSection();
    }
    renderValidation();
    updateStatus();
  });
  fetchAddressLookupForCurrentLocation({ silent: true }).then(() => {
    autosave();
    if (activeSectionId === "address") {
      renderSection();
    }
  });
}

async function fetchNearbyPlaces(lat, lng) {
  const query = buildNearbyOverpassQuery(lat, lng);
  const endpoints = [
    "/api/overpass",
    "https://overpass-api.de/api/interpreter",
    "https://overpass.kumi.systems/api/interpreter",
    "https://overpass.osm.ch/api/interpreter",
  ];
  let lastError = null;

  for (const endpoint of endpoints) {
    try {
      const response = await fetch(endpoint);
      if (!response.ok) {
        lastError = new Error("Yakın çevre servisi şu anda cevap vermedi.");
        continue;
      }
      const data = await response.json();
      const elements = data.elements || [];
      const places = parseNearbyOverpassElements(elements, lat, lng);
      return {
        places,
        regionAnalysis: analyzeRegionElements(elements, places),
      };
    } catch (error) {
      lastError = error;
    }
  }

  throw new Error(lastError?.message || "Yakın çevre verileri okunamadı.");
}

async function fetchNearbyPlacesFast(lat, lng) {
  return fetchNearbyPlacesFastByRadius(lat, lng, nearbyRadiusMeters);
}

async function fetchNearbyPlacesWithCoverage(lat, lng) {
  const scanRadius = getNearbyScanRadiusMeters();
  let first = { places: [], radius: scanRadius, regionAnalysis: {} };
  try {
    first = await fetchNearbyPlacesFastByRadius(lat, lng, scanRadius);
  } catch (error) {
    first = { places: [], radius: scanRadius, regionAnalysis: {}, error };
  }
  if (hasRequiredNearbyCoverage(first.places)) return first;

  let merged = first;
  try {
    const expanded = await fetchNearbyPlacesFastByRadius(lat, lng, Math.max(nearbyExpandedRadiusMeters, scanRadius));
    merged = mergeNearbyEnvironments(first, expanded);
  } catch (error) {
    merged = first;
  }

  if (hasRequiredNearbyCoverage(merged.places)) return merged;

  try {
    const fallback = await fetchFallbackNearbyPlaces(lat, lng);
    const withFallback = mergeNearbyEnvironments(merged, fallback);
    const withArteries = await ensureNearbyArteryCoverage(withFallback, lat, lng);
    if ((withArteries.places || []).length && hasRequiredNearbyCoverage(withArteries.places)) return withArteries;
    if ((withArteries.places || []).length && getNearbyArteries(withArteries.places).length) return withArteries;
    if ((withArteries.places || []).length) return withArteries;
    const settlements = await fetchLocalSettlementNearbyPlaces(lat, lng);
    if (!settlements.length) return withArteries;
    return {
      ...withArteries,
      places: dedupeAndSortNearbyPlaces([...(withArteries.places || []), ...settlements]),
      radius: nearbySettlementFallbackRadiusMeters,
      source: "local-settlements",
    };
  } catch (error) {
    if ((merged.places || []).length) return merged;
    const settlements = await fetchLocalSettlementNearbyPlaces(lat, lng);
    if (!settlements.length) return merged;
    return {
      ...merged,
      places: dedupeAndSortNearbyPlaces([...(merged.places || []), ...settlements]),
      radius: nearbySettlementFallbackRadiusMeters,
      source: "local-settlements",
    };
  }
}

async function fetchNearbyPlacesFastByRadius(lat, lng, radius) {
  const cached = getCachedNearbyEnvironment(lat, lng, radius);
  if (cached) return cached;

  const query = buildNearbyOverpassQuery(lat, lng, radius);
  const endpoints = [
    "/api/overpass",
    "https://overpass-api.de/api/interpreter",
    "https://overpass.kumi.systems/api/interpreter",
    "https://overpass.osm.ch/api/interpreter",
  ];

  try {
    const environment = await Promise.any(endpoints.map((endpoint) => fetchNearbyEndpoint(endpoint, query, lat, lng)));
    const result = { ...environment, radius };
    cacheNearbyEnvironment(lat, lng, radius, result);
    return result;
  } catch (error) {
    const lastError = error?.errors?.find(Boolean) || error;
    throw new Error(lastError?.message || "Yakın çevre verileri okunamadı.");
  }
}

async function ensureNearbyArteryCoverage(environment, lat, lng) {
  if (getNearbyArteries(environment.places || []).length >= mainArteryAutoLimit) return environment;
  try {
    const wider = await fetchNearbyPlacesFastByRadius(lat, lng, nearbyArteryFallbackRadiusMeters);
    const arteryPlaces = (wider.places || []).filter((place) => place.category === "arteries" || place.category === "junctions");
    if (!arteryPlaces.length) return environment;
    return mergeNearbyEnvironments(environment, {
      places: arteryPlaces,
      radius: nearbyArteryFallbackRadiusMeters,
      regionAnalysis: environment.regionAnalysis || {},
    });
  } catch (error) {
    return environment;
  }
}

function getNearbyCacheKey(lat, lng, radius) {
  return `${Number(lat).toFixed(5)}|${Number(lng).toFixed(5)}|${radius}`;
}

function readNearbyCache() {
  try {
    const cache = JSON.parse(localStorage.getItem(nearbyCacheStorageKey) || "{}");
    return cache && typeof cache === "object" ? cache : {};
  } catch (error) {
    return {};
  }
}

function writeNearbyCache(cache) {
  try {
    const entries = Object.entries(cache)
      .sort(([, a], [, b]) => Number(b?.storedAt || 0) - Number(a?.storedAt || 0))
      .slice(0, nearbyCacheMaxEntries);
    localStorage.setItem(nearbyCacheStorageKey, JSON.stringify(Object.fromEntries(entries)));
  } catch (error) {
    // Cache yardımcıdır; yazılamazsa tarama akışı bozulmasın.
  }
}

function getCachedNearbyEnvironment(lat, lng, radius) {
  const cache = readNearbyCache();
  const item = cache[getNearbyCacheKey(lat, lng, radius)];
  if (!item?.environment || Date.now() - Number(item.storedAt || 0) > nearbyCacheTtlMs) return null;
  return {
    ...item.environment,
    radius,
    cached: true,
  };
}

function cacheNearbyEnvironment(lat, lng, radius, environment) {
  const cache = readNearbyCache();
  cache[getNearbyCacheKey(lat, lng, radius)] = {
    storedAt: Date.now(),
    environment,
  };
  writeNearbyCache(cache);
}

async function fetchNearbyEndpoint(endpoint, query, lat, lng) {
  // Özel header sadece KENDİ /api/overpass proxy'imize gönderilir — üçüncü taraf
  // Overpass ayna sunucuları (overpass-api.de vb.) bu header'ı görünce CORS
  // preflight'ında reddedebilir ve yedek yollar kırılır.
  const isOwnProxy = endpoint.startsWith("/api/");
  let response;
  try {
    const requestInit = {
      method: "POST",
      body: new URLSearchParams({ data: query }),
    };
    response = isOwnProxy
      ? await fetchRaporApi(endpoint, requestInit, nearbyRequestTimeoutMs)
      : await fetchWithTimeout(endpoint, nearbyRequestTimeoutMs, requestInit);
  } catch (error) {
    if (isOwnProxy) throw error;
    response = await fetchWithTimeout(`${endpoint}?data=${encodeURIComponent(query)}`, nearbyRequestTimeoutMs);
  }
  if (!response.ok) {
    throw new Error("Yakın çevre servisi şu anda cevap vermedi.");
  }
  const data = await response.json();
  const elements = data.elements || [];
  const places = parseNearbyOverpassElements(elements, lat, lng);
  return {
    places,
    regionAnalysis: analyzeRegionElements(elements, places),
  };
}

async function fetchWithTimeout(url, timeoutMs, options = {}) {
  const controller = new AbortController();
  const timeout = window.setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(url, { ...options, signal: controller.signal });
  } catch (error) {
    if (error.name === "AbortError") {
      throw new Error("Yakın çevre servisi zamanında cevap vermedi.");
    }
    throw error;
  } finally {
    window.clearTimeout(timeout);
  }
}

async function fetchFallbackNearbyPlaces(lat, lng) {
  const [nominatim, arcgis] = await Promise.allSettled([
    fetchNominatimNearbyPlaces(lat, lng),
    fetchArcgisNearbyRoads(lat, lng),
  ]);
  const places = [
    ...((nominatim.status === "fulfilled" && nominatim.value) || []),
    ...((arcgis.status === "fulfilled" && arcgis.value) || []),
  ];
  return {
    places: dedupeAndSortNearbyPlaces(places),
    radius: nearbyExpandedRadiusMeters,
    regionAnalysis: {},
  };
}

async function fetchNominatimNearbyPlaces(lat, lng) {
  const viewbox = createNominatimViewbox(lat, lng, nearbyExpandedRadiusMeters);
  const searches = [
    { query: "cadde", category: "arteries" },
    { query: "bulvar", category: "arteries" },
    { query: "karayolu", category: "arteries" },
    { query: "yolu", category: "arteries" },
    { query: "okul", category: "education" },
    { query: "lise", category: "education" },
    { query: "üniversite", category: "education" },
    { query: "metro", category: "metro" },
    { query: "kavşak", category: "junctions" },
    { query: "park", category: "parks" },
    { query: "hastane", category: "health" },
    { query: "belediye", category: "government" },
    { query: "emniyet", category: "government" },
    { query: "alışveriş merkezi", category: "malls" },
  ];
  const requests = searches.map(async (search) => {
    const url = `https://nominatim.openstreetmap.org/search?format=jsonv2&limit=6&addressdetails=1&bounded=1&viewbox=${encodeURIComponent(viewbox)}&q=${encodeURIComponent(search.query)}&accept-language=tr`;
    const response = await fetchWithTimeout(url, 3500);
    if (!response.ok) return [];
    const rows = await response.json();
    return rows.map((row) => normalizeNominatimPlace(row, lat, lng, search.category)).filter(Boolean);
  });
  const results = await Promise.allSettled(requests);
  return dedupeAndSortNearbyPlaces(results.flatMap((result) => (result.status === "fulfilled" ? result.value : [])));
}

async function fetchArcgisNearbyRoads(lat, lng) {
  const offsets = [
    [0, 0],
    [0.0035, 0],
    [-0.0035, 0],
    [0, 0.0045],
    [0, -0.0045],
    [0.006, 0.006],
    [-0.006, -0.006],
  ];
  const requests = offsets.map(async ([latOffset, lngOffset], index) => {
    const sampleLat = Number(lat) + latOffset;
    const sampleLng = Number(lng) + lngOffset;
    const url = `https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/reverseGeocode?location=${encodeURIComponent(`${sampleLng},${sampleLat}`)}&f=json&langCode=tr&featureTypes=StreetInt,StreetAddress`;
    const response = await fetchWithTimeout(url, 3500);
    if (!response.ok) return null;
    const row = await response.json();
    const address = row.address || {};
  const name = cleanupRoadName(address.StreetName || address.Address || address.LongLabel || "");
    if (!name || !isAllowedMainArteryName(name, { highway: "primary" })) return null;
    return {
      id: `arcgis-road-${index}-${normalizeNameForCompare(name)}`,
      category: "arteries",
      name,
      lat: Number(row.location?.y || sampleLat),
      lng: Number(row.location?.x || sampleLng),
      distance: calculateDistanceMeters(lat, lng, Number(row.location?.y || sampleLat), Number(row.location?.x || sampleLng)),
    };
  });
  const results = await Promise.allSettled(requests);
  return dedupeAndSortNearbyPlaces(results.map((result) => (result.status === "fulfilled" ? result.value : null)).filter(Boolean));
}

function createNominatimViewbox(lat, lng, radiusMeters) {
  const latDelta = radiusMeters / 111320;
  const lngDelta = radiusMeters / (111320 * Math.max(Math.cos((Number(lat) * Math.PI) / 180), 0.2));
  const minLng = Number(lng) - lngDelta;
  const maxLng = Number(lng) + lngDelta;
  const minLat = Number(lat) - latDelta;
  const maxLat = Number(lat) + latDelta;
  return `${minLng},${maxLat},${maxLng},${minLat}`;
}

function normalizeNominatimPlace(row, lat, lng, category) {
  const placeLat = Number(row.lat);
  const placeLng = Number(row.lon);
  if (!Number.isFinite(placeLat) || !Number.isFinite(placeLng)) return null;
  const rawName = category === "arteries"
    ? cleanupRoadName(row.name || String(row.display_name || "").split(",")[0])
    : cleanupPlaceName(row.name || String(row.display_name || "").split(",")[0]);
  if (!rawName) return null;
  if (category === "arteries" && !isAllowedMainArteryName(rawName, { highway: "primary" })) return null;
  if (category === "education" && !isAllowedEducationName(rawName)) return null;
  return {
    id: `nominatim-${category}-${row.place_id || normalizeNameForCompare(rawName)}`,
    category,
    name: rawName,
    lat: placeLat,
    lng: placeLng,
    distance: calculateDistanceMeters(lat, lng, placeLat, placeLng),
  };
}

function dedupeAndSortNearbyPlaces(places) {
  const byKey = new Map();
  (places || []).filter(Boolean).forEach((place) => {
    const key = `${place.category}|${normalizeNameForCompare(place.name)}`;
    if (!byKey.has(key) || (place.distance || 0) < (byKey.get(key).distance || 0)) {
      byKey.set(key, place);
    }
  });
  return [...byKey.values()]
    .sort((a, b) => {
      const priorityDiff = (nearbyCategoryPriority[a.category] ?? 99) - (nearbyCategoryPriority[b.category] ?? 99);
      return priorityDiff || a.distance - b.distance;
    })
    .slice(0, nearbyResultLimit);
}

async function fetchLocalSettlementNearbyPlaces(lat, lng) {
  try {
    const result = await fetchNeighborhoodLookup("nearby", {
      lat,
      lng,
      radius: nearbySettlementFallbackRadiusMeters,
      limit: nearbyResultLimit,
    });
    const places = (result.nearby || [])
      .map((row) => normalizeNeighborhoodApiRow(row, lat, lng))
      .filter(Boolean)
      .map((row) => ({
        id: `local-settlement-${row.cityKey}-${row.districtKey}-${row.neighborhoodKey}`,
        category: "settlements",
        name: row.neighborhood,
        lat: row.lat,
        lng: row.lng,
        distance: row.distance,
      }));
    return dedupeAndSortNearbyPlaces(places);
  } catch {
    return [];
  }
}

async function fetchAddressLookupForCurrentLocation(options = {}) {
  const point = getSelectedMapPoint();
  if (!point) return;

  const [lat, lng] = point;
  const previousValues = {
    city: state.fields.city || "",
    district: state.fields.district || "",
    neighborhood: state.fields.neighborhood || "",
    postalCode: state.fields.postalCode || "",
  };
  try {
    const response = await fetch(
      `https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${encodeURIComponent(lat)}&lon=${encodeURIComponent(lng)}&zoom=18&addressdetails=1&accept-language=tr`,
    );
    if (!response.ok) {
      throw new Error("Adres doğrulama servisi cevap vermedi.");
    }

    const data = await response.json();
    const fields = normalizeReverseGeocodeAddress(data.address || {});
    const lookupFields = { ...fields };
    delete lookupFields.neighborhood;
    mergeLookupOptions(lookupFields);
    state.sourceValues.geoLookup = {
      ...(state.sourceValues.geoLookup || {}),
      fields,
      displayName: data.display_name || "",
      readAt: new Date().toISOString(),
    };
    state.sourceConflicts.geoLookup = {};

    Object.entries(fields).forEach(([key, value]) => {
      if (!value) return;
      if (key === "neighborhood") return;
      setFieldFromSource("geoLookup", key, value, options);
    });
    state.uploadErrors = { ...(state.uploadErrors || {}), geoLookup: "" };
    return Object.keys(previousValues).some((key) => previousValues[key] !== (state.fields[key] || ""));
  } catch (error) {
    if (!options.silent) {
      state.uploadErrors = {
        ...(state.uploadErrors || {}),
        geoLookup: error.message || "Adres doğrulama verisi alınamadı.",
      };
    }
  }
  return false;
}

function normalizeReverseGeocodeAddress(address) {
  return {
    city: address.province || address.state || address.city || "",
    district: address.town || address.city_district || address.county || address.district || "",
    neighborhood: address.neighbourhood || address.suburb || address.quarter || address.village || "",
    postalCode: address.postcode || "",
  };
}

async function applyLocalNeighborhoodForCurrentLocation(options = {}) {
  const point = getSelectedMapPoint();
  if (!point) return false;
  const kml = state.sourceValues.kml;
  const result = await fetchNeighborhoodLookup("location", {
    lat: point[0],
    lng: point[1],
    city: kml?.fields?.city || state.fields.city || state.fields.titleCity || "",
    district: kml?.fields?.district || state.fields.district || state.fields.titleDistrict || "",
    neighborhood: kml?.parcelNeighborhood || "",
  });
  const nearest = normalizeNeighborhoodApiRow(result.nearest, point[0], point[1]);
  if (!nearest) return false;
  const bound = normalizeNeighborhoodApiRow(result.bound, point[0], point[1], kml?.parcelNeighborhood || "");

  const fields = buildLocalNeighborhoodFields(nearest, bound);
  applyLocalNeighborhoodFields(fields, { ...options, skipKeys: ["city", "district", "neighborhood", "postalCode"] });
  return true;
}

async function applyPostalCodeFromSelectedNeighborhood(options = {}) {
  // Adres kodu PDF'i çoğu zaman il/ilçe içermediğinden, boşsa TAKBİS'ten (tapu il/
  // ilçe) yedeklenir. Aksi halde mahalle adı başka ildeki bir mahalleyle eşleşip
  // yanlış posta kodu gelebiliyordu (ör. Panayır → Balıkesir 10442, Soğanlı → 72502).
  const result = await fetchNeighborhoodLookup("postal", {
    city: state.fields.city || state.fields.titleCity,
    district: state.fields.district || state.fields.titleDistrict,
    neighborhood: state.fields.neighborhood,
  });
  const match = normalizeNeighborhoodApiRow(result.match);
  const casingChanged = applyAdministrativePlaceCasingFromMatch(match, options);
  if (!match?.postalCode) return casingChanged;
  const shouldForcePostalCode = !state.fields.postalCode || isFieldValueAppliedFromSource("postalCode");
  applyLocalNeighborhoodFields({
    postalCode: match.postalCode,
  }, { ...options, force: Boolean(options.force || shouldForcePostalCode) });
  return true;
}

// Tapu il/ilçe/mahalle açılır listelerindeki (populateTitleLocationSelect)
// aynı mantık: il/ilçe/mahalle idari veritabanındaki BİR SATIRLA (yalnızca
// harf büyüklüğü/aksan farkıyla) eşleşiyorsa "Baş Harf Büyük" (title case)
// yazılışa düzeltilir — burada Tapu'daki gibi TÜMÜ BÜYÜK değil, çünkü bu
// alanlar Adres ve Konum'da serbest metin, açılır liste değil. Eşleşme
// bulunamazsa (ör. UAVT PDF'indeki mahalle adı veritabanında yoksa) hiçbir
// şey değiştirilmez; UAVT'ten gelen değer olduğu gibi korunur.
function applyAdministrativePlaceCasingFromMatch(match, options = {}) {
  if (!match) return false;
  const corrections = {};
  [
    ["city", match.city, "city"],
    ["district", match.district, "district"],
    ["neighborhood", match.neighborhood, "neighborhood"],
  ].forEach(([key, matchValue, level]) => {
    const current = String(state.fields[key] || "").trim();
    if (!current || !matchValue) return;
    if (foldPlaceNameForMatch(current, level) !== foldPlaceNameForMatch(matchValue, level)) return;
    // Mahallede ek (Mahallesi/Mah./Köyü...) varsa temizlenip Baş Harf Büyük
    // yazılışa çevrilir: "Hacıseyfettin Mahallesi" -> "Hacıseyfettin".
    const sourceText = level === "neighborhood" ? stripNeighborhoodSuffix(current) : current;
    const titleCased = toTitleCaseTr(sourceText);
    if (titleCased !== current) corrections[key] = titleCased;
  });
  if (!Object.keys(corrections).length) return false;
  applyLocalNeighborhoodFields(corrections, { ...options, force: true });
  return true;
}

async function fetchNeighborhoodLookup(operation, payload = {}) {
  const response = await fetchRaporApi("/api/neighborhoods", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ operation, ...payload }),
  }, nearbyRequestTimeoutMs);
  let result = null;
  try {
    result = await response.json();
  } catch {
    result = null;
  }
  if (!response.ok || !result?.ok) {
    throw new Error(result?.error || "Mahalle verisi sunucudan alınamadı.");
  }
  return result;
}

function normalizeNeighborhoodApiRow(row, lat = Number.NaN, lng = Number.NaN, neighborhoodOverride = "") {
  if (!row || typeof row !== "object") return null;
  const normalized = {
    city: cleanupPlaceName(row.city),
    district: cleanupPlaceName(row.district),
    neighborhood: cleanNeighborhoodName(neighborhoodOverride || row.neighborhood),
    postalCode: normalizePostalCodeValue(row.postalCode),
    lat: parseCsvNumber(row.lat),
    lng: parseCsvNumber(row.lng),
    cityKey: normalizeLocalPlaceKey(row.cityKey || row.city),
    districtKey: normalizeLocalPlaceKey(row.districtKey || row.district),
    neighborhoodKey: normalizeLocalNeighborhoodKey(row.neighborhoodKey || row.neighborhood),
    cityCenterLat: parseCsvNumber(row.cityCenterLat),
    cityCenterLng: parseCsvNumber(row.cityCenterLng),
    cityCenterDistanceKm: parseCsvNumber(row.cityCenterDistanceKm),
    cityCenterDirection: cleanupPlaceName(row.cityCenterDirection),
    districtCenterLat: parseCsvNumber(row.districtCenterLat),
    districtCenterLng: parseCsvNumber(row.districtCenterLng),
    districtCenterDistanceKm: parseCsvNumber(row.districtCenterDistanceKm),
    districtCenterDirection: cleanupPlaceName(row.districtCenterDirection),
  };
  if (!normalized.city || !normalized.district || !normalized.neighborhood
    || !Number.isFinite(normalized.lat) || !Number.isFinite(normalized.lng)) return null;
  if (![lat, lng].every((value) => Number.isFinite(Number(value)))) return normalized;
  return {
    ...normalized,
    distance: calculateDistanceMeters(lat, lng, normalized.lat, normalized.lng),
    direction: calculateRelativeDirectionText(normalized.lat, normalized.lng, lat, lng),
    cityCenterDistance: calculateDistanceMetersIfPossible(lat, lng, normalized.cityCenterLat, normalized.cityCenterLng),
    cityCenterDirectionFromPoint: calculateRelativeDirectionText(normalized.cityCenterLat, normalized.cityCenterLng, lat, lng),
    districtCenterDistance: calculateDistanceMetersIfPossible(lat, lng, normalized.districtCenterLat, normalized.districtCenterLng),
    districtCenterDirectionFromPoint: calculateRelativeDirectionText(normalized.districtCenterLat, normalized.districtCenterLng, lat, lng),
  };
}

function applyLocalNeighborhoodFields(fields, options = {}) {
  state.sourceValues.localNeighborhood = {
    ...(state.sourceValues.localNeighborhood || {}),
    fields,
    readAt: new Date().toISOString(),
    applied: state.sourceValues.localNeighborhood?.applied || {},
  };
  state.sourceConflicts.localNeighborhood = {};
  const skipKeys = new Set(options.skipKeys || []);
  const lookupFields = {
    city: fields.city,
    district: fields.district,
    neighborhood: fields.neighborhood,
    postalCode: fields.postalCode,
  };
  skipKeys.forEach((key) => delete lookupFields[key]);
  mergeLookupOptions(lookupFields);
  Object.entries(fields).forEach(([key, value]) => {
    if (!value) return;
    if (skipKeys.has(key)) return;
    setFieldFromSource("localNeighborhood", key, value, options);
  });
}

function buildLocalNeighborhoodFields(row, boundRow = null) {
  const bound = boundRow || row;
  return {
    city: row.city,
    district: row.district,
    neighborhood: row.neighborhood,
    postalCode: row.postalCode,
    boundNeighborhood: bound ? `${bound.neighborhood} - ${bound.district} / ${bound.city}` : "",
    boundNeighborhoodDistance: bound ? formatBoundNeighborhoodDistance(bound.distance, bound.direction) : "",
    nearestNeighborhood: `${row.neighborhood} - ${row.district} / ${row.city}`,
    nearestNeighborhoodDistance: formatDistanceWithDirection(row.distance, row.direction),
    districtCenterDistance: formatDistanceWithDirection(row.districtCenterDistance, row.districtCenterDirectionFromPoint) || formatCenterDistance(row.districtCenterDistanceKm, row.districtCenterDirection),
    cityCenterDistance: formatDistanceWithDirection(row.cityCenterDistance, row.cityCenterDirectionFromPoint) || formatCenterDistance(row.cityCenterDistanceKm, row.cityCenterDirection),
  };
}

function cleanNeighborhoodName(value) {
  const withoutSuffix = stripNeighborhoodSuffix(cleanupPlaceName(value));
  return normalizeReportTitleText(withoutSuffix);
}

function stripNeighborhoodSuffix(value) {
  let text = cleanupPlaceName(value);
  let previous = "";
  while (text && text !== previous) {
    previous = text;
    text = text
      .replace(/\s+(mahallesi|mahalle|mah\.?|köyü|koyu|köy|koy)$/i, "")
      .replace(/\s+/g, " ")
      .trim();
  }
  return text;
}

// İl/İlçe/Mahalle eşleşmelerinde (populateLocationSelect,
// applyAdministrativePlaceCasingFromMatch) kullanılan ortak karşılaştırma
// anahtarı. UAVT PDF'i mahalleyi genelde "Hacıseyfettin Mahallesi" gibi
// EKLİ verirken idari veritabanı "Hacıseyfettin" (eksiz) tutar; yalnızca
// harf büyüklüğü/aksan farkına bakan foldTurkish bu durumda eşleşmeyi
// KAÇIRIYORDU (kullanıcı bildirimi). Mahalle seviyesinde önce ek
// (mahallesi/mah./köyü...) atılır, sonra foldTurkish uygulanır.
function foldPlaceNameForMatch(value, level) {
  const text = level === "neighborhood" ? stripNeighborhoodSuffix(value) : value;
  return foldTurkish(text);
}

function normalizeLocalNeighborhoodKey(value) {
  return normalizeLocalPlaceKey(stripNeighborhoodSuffix(value));
}

function normalizeLocalPlaceKey(value) {
  return String(value || "")
    .toLocaleLowerCase("tr")
    .replace(/ç/g, "c")
    .replace(/ğ/g, "g")
    .replace(/[ıi]/g, "i")
    .replace(/ö/g, "o")
    .replace(/ş/g, "s")
    .replace(/ü/g, "u")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function parseCsvNumber(value) {
  const number = Number.parseFloat(String(value || "").replace(",", "."));
  return Number.isFinite(number) ? number : Number.NaN;
}

function formatDistanceMeters(value) {
  const distance = Number(value);
  if (!Number.isFinite(distance)) return "";
  if (distance >= 1000) return `${(distance / 1000).toLocaleString("tr-TR", { maximumFractionDigits: 2 })} km`;
  return `${Math.round(distance)} m`;
}

function formatDistanceWithDirection(distance, direction) {
  const text = formatDistanceMeters(distance);
  return text && direction ? `${text} ${direction}` : text;
}

function formatBoundNeighborhoodDistance(distance, direction) {
  const text = formatDistanceMeters(distance);
  if (!text) return "";
  if (!direction) return text;
  return `Taşınmaz mahalle merkezinin ${text} ${direction}`;
}

function formatCenterDistance(distanceKm, direction) {
  if (!Number.isFinite(distanceKm)) return "";
  const distance = `${distanceKm.toLocaleString("tr-TR", { maximumFractionDigits: 2 })} km`;
  return direction ? `${distance} ${direction}` : distance;
}

function calculateDistanceMetersIfPossible(lat1, lng1, lat2, lng2) {
  if (![lat1, lng1, lat2, lng2].every((value) => Number.isFinite(Number(value)))) return Number.NaN;
  return calculateDistanceMeters(lat1, lng1, lat2, lng2);
}

function calculateRelativeDirectionText(fromLat, fromLng, toLat, toLng) {
  if (![fromLat, fromLng, toLat, toLng].every((value) => Number.isFinite(Number(value)))) return "";
  const bearing = calculateBearing(fromLat, fromLng, toLat, toLng);
  const directions = ["kuzeyinde", "kuzeydoğusunda", "doğusunda", "güneydoğusunda", "güneyinde", "güneybatısında", "batısında", "kuzeybatısında"];
  return directions[Math.round(bearing / 45) % 8];
}

function buildNearbyOverpassQuery(lat, lng, radius = nearbyRadiusMeters) {
  const around = `(around:${radius},${lat},${lng})`;
  return `
    [out:json][timeout:8];
    (
      nwr${around}["amenity"~"townhall|courthouse|police|post_office|fire_station|public_building"];
      nwr${around}["office"="government"];
      nwr${around}["office"~"administrative|public"];
      nwr${around}["historic"];
      nwr${around}["tourism"~"museum|attraction|viewpoint"];
      nwr${around}["leisure"~"park|garden|playground|sports_centre|recreation_ground"];
      nwr${around}["landuse"~"recreation_ground|grass|village_green"];
      way${around}["highway"~"motorway|trunk|primary|secondary|tertiary"]["name"];
      way${around}["highway"~"motorway|trunk|primary|secondary|tertiary"]["ref"];
      way${around}["highway"]["name"~"Cadde|Caddesi|Bulvar|Bulvarı|Bulvari|Karayolu|Otoyol|Çevre Yolu|Cevre Yolu|Yolu|Asfalt", i];
      way${around}["highway"]["ref"~"^(D|E)[ -]?[0-9]", i];
      nwr${around}["highway"~"motorway_junction|traffic_signals"]["name"];
      nwr${around}["junction"]["name"];
      nwr${around}["railway"~"station|halt|subway_entrance|tram_stop"]["name"];
      nwr${around}["station"="subway"]["name"];
      nwr${around}["public_transport"~"station|stop_position|platform"]["name"];
      nwr${around}["amenity"~"bus_station|ferry_terminal"]["name"];
      nwr${around}["amenity"~"school|university|college|kindergarten|library"]["name"];
      nwr${around}["amenity"~"hospital|clinic|doctors|pharmacy|dentist"]["name"];
      nwr${around}["shop"="mall"]["name"];
      nwr${around}["building"="retail"]["name"];
      nwr${around}["amenity"="marketplace"]["name"];
      nwr${around}["natural"~"coastline|beach|water|bay"]["name"];
      nwr${around}["water"="sea"];
      nwr${around}["waterway"~"river|stream|canal"]["name"];
    );
    out body geom ${nearbyResultLimit};
  `;
}

function parseNearbyOverpassElements(elements, lat, lng) {
  const seen = new Set();
  return elements
    .map((element) => normalizeNearbyPlace(element, lat, lng))
    .filter(Boolean)
    .filter((place) => {
      const key = `${place.category}|${normalizeNameForCompare(place.name)}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .sort((a, b) => {
      const priorityDiff = (nearbyCategoryPriority[a.category] ?? 99) - (nearbyCategoryPriority[b.category] ?? 99);
      return priorityDiff || a.distance - b.distance;
    })
    .slice(0, nearbyResultLimit);
}

function analyzeRegionElements(elements, places) {
  const buildingElements = elements.filter((element) => element.tags?.building);
  const buildingLevels = buildingElements
    .map((element) => parseBuildingLevel(element.tags))
    .filter((value) => Number.isFinite(value) && value > 0);
  const medianLevel = median(buildingLevels);
  const landuses = new Set(elements.map((element) => element.tags?.landuse).filter(Boolean));
  const counts = {
    buildings: buildingElements.length,
    roads: places.filter((place) => place.category === "arteries").length,
    education: places.filter((place) => place.category === "education").length,
    government: places.filter((place) => place.category === "government").length,
    parks: places.filter((place) => place.category === "parks").length,
    malls: places.filter((place) => place.category === "malls").length,
    metro: places.filter((place) => place.category === "metro").length,
    health: places.filter((place) => place.category === "health").length,
    junctions: places.filter((place) => place.category === "junctions").length,
  };

  const amenityScore = counts.education + counts.government + counts.parks + counts.malls + counts.metro + counts.health + counts.junctions;
  return {
    fields: {
      regionBuildOrder: inferBuildOrder(medianLevel, counts, landuses),
      regionFloorRange: inferFloorRange(medianLevel, counts),
      regionIncomeLevel: inferIncomeLevel(places, counts, landuses),
      infrastructureLevel: inferInfrastructureLevel(counts, amenityScore),
      developmentSpeed: inferDevelopmentSpeed(counts, landuses),
      regionBuildingAge: inferBuildingAge(elements, counts),
      developmentDensity: inferDevelopmentDensity(medianLevel, counts),
      socialNeeds: inferSocialNeeds(amenityScore),
      regionUsePurpose: inferRegionUsePurpose(landuses, counts),
    },
    metrics: {
      medianLevel: medianLevel || "",
      amenityScore,
      ...counts,
      landuses: [...landuses],
    },
  };
}

function applyRegionAnalysisFields(regionAnalysis) {
  if (!regionAnalysis?.fields) return;
  state.sourceValues.regionAnalysis = {
    ...(state.sourceValues.regionAnalysis || {}),
    fields: regionAnalysis.fields,
    metrics: regionAnalysis.metrics || {},
    readAt: new Date().toISOString(),
  };
  state.sourceConflicts.regionAnalysis = {};

  Object.entries(regionAnalysis.fields).forEach(([key, value]) => {
    if (!value) return;
    setFieldFromSource("regionAnalysis", key, value);
  });
  refreshEnvironmentDescriptionFromCurrentFields("regionUsePurpose");
}

function parseBuildingLevel(tags = {}) {
  const raw = tags["building:levels"] || tags.levels || tags["building:levels:aboveground"];
  if (!raw) return null;
  const match = String(raw).replace(",", ".").match(/[0-9]+(?:\.[0-9]+)?/);
  return match ? Number(match[0]) : null;
}

function median(values) {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
}

function inferFloorRange(medianLevel, counts) {
  if (medianLevel) {
    if (medianLevel <= 2) return "1-2";
    if (medianLevel <= 4) return "3-4";
    if (medianLevel <= 8) return "5-8";
    if (medianLevel <= 12) return "9-12";
    return "12+";
  }
  if (counts.buildings > 45) return "5-8";
  if (counts.buildings > 15) return "3-4";
  return "";
}

function inferBuildOrder(medianLevel, counts, landuses) {
  if (medianLevel && medianLevel >= 9) return "blok";
  if (landuses.has("commercial") || landuses.has("retail")) return "karma";
  if (counts.buildings >= 12) return "ayrık";
  return "";
}

function inferIncomeLevel(places, counts, landuses) {
  const privateSchoolCount = places.filter((place) => /özel|kolej|college|akademi/i.test(place.name)).length;
  if (counts.malls || privateSchoolCount >= 2 || landuses.has("commercial") || landuses.has("retail")) return "orta ve üst";
  if (counts.education + counts.parks + counts.government >= 4) return "orta";
  return "";
}

function inferInfrastructureLevel(counts, amenityScore) {
  if (counts.roads >= 3 && amenityScore >= 8) return "çok iyi";
  if (counts.roads >= 1 && amenityScore >= 3) return "iyi";
  if (counts.roads >= 1 || amenityScore >= 2) return "orta";
  return "";
}

function inferDevelopmentSpeed(counts, landuses) {
  if (landuses.has("construction")) return "yüksek";
  if (counts.buildings >= 30) return "orta";
  if (counts.buildings > 0) return "düşük";
  return "";
}

function inferBuildingAge(elements, counts) {
  const currentYear = new Date().getFullYear();
  const years = elements
    .map((element) => String(element.tags?.start_date || element.tags?.["building:start_date"] || "").match(/\b(19|20)\d{2}\b/)?.[0])
    .filter(Boolean)
    .map(Number);
  const medianYear = median(years);
  if (medianYear) {
    const age = currentYear - medianYear;
    if (age <= 5) return "yeni";
    if (age <= 10) return "5-10";
    if (age <= 15) return "10-15";
    if (age <= 20) return "15-20";
    if (age <= 25) return "20-25";
    if (age <= 30) return "20-30";
    return "30-40";
  }
  if (counts.buildings >= 25) return "5-10";
  if (counts.buildings > 0) return "10-15";
  return "";
}

function inferDevelopmentDensity(medianLevel, counts) {
  if ((medianLevel && medianLevel >= 7) || counts.buildings >= 45) return "yüksek";
  if ((medianLevel && medianLevel >= 3) || counts.buildings >= 15) return "orta";
  if (counts.buildings > 0) return "düşük";
  return "";
}

function inferSocialNeeds(amenityScore) {
  if (amenityScore >= 8) return "kısa";
  if (amenityScore >= 3) return "orta";
  if (amenityScore > 0) return "uzun";
  return "";
}

function inferRegionUsePurpose(landuses, counts) {
  if ((landuses.has("commercial") || landuses.has("retail")) && (landuses.has("residential") || counts.buildings)) {
    return "zemin katları işyeri, normal katları konut";
  }
  if (landuses.has("commercial") || landuses.has("retail")) return "zemin katları işyeri, normal katları ofis";
  if (landuses.has("residential") || counts.buildings) return "zemin ve normal katları konut";
  return "";
}

function normalizeNearbyPlace(element, lat, lng) {
  const tags = element.tags || {};
  const category = classifyNearbyElement(tags, element.type);
  if (!category) return null;

  const geometryPoint = getClosestElementPoint(element, lat, lng);
  const elementLat = geometryPoint?.lat ?? element.lat ?? element.center?.lat;
  const elementLng = geometryPoint?.lng ?? element.lon ?? element.center?.lon;
  if (!Number.isFinite(Number(elementLat)) || !Number.isFinite(Number(elementLng))) return null;

  const rawName = tags.name || tags["name:tr"] || tags.official_name || tags.operator || (category === "arteries" ? tags.ref : "") || readableNearbyFallback(category, tags);
  const name = category === "arteries" ? cleanupRoadName(rawName) : cleanupPlaceName(rawName);
  if (!name) return null;
  if (category === "arteries" && !isAllowedMainArteryName(name, tags)) return null;
  if (category === "education" && !isAllowedEducationName(name, tags)) return null;

  return {
    id: `${element.type}-${element.id}`,
    category,
    name,
    lat: Number(elementLat),
    lng: Number(elementLng),
    distance: geometryPoint?.distance ?? calculateDistanceMeters(lat, lng, Number(elementLat), Number(elementLng)),
  };
}

function classifyNearbyElement(tags, type) {
  const roadName = tags.name || tags["name:tr"] || tags.official_name || tags.ref || "";
  const roadCompare = normalizeNameForCompare(roadName);
  if (tags.junction || /kavsak|kavsagi/i.test(roadCompare) || /motorway_junction|traffic_signals/.test(tags.highway || "")) return "junctions";
  if (/hospital|clinic|doctors|pharmacy|dentist/.test(tags.amenity || "")) return "health";
  if (/government|administrative|public/.test(tags.office || "") || /townhall|courthouse|police|post_office|fire_station|public_building/.test(tags.amenity || "")) return "government";
  if (tags.historic || /museum|attraction|viewpoint/.test(tags.tourism || "")) return "historic";
  if (/park|garden|playground|sports_centre|recreation_ground/.test(tags.leisure || "") || /recreation_ground|grass|village_green/.test(tags.landuse || "")) return "parks";
  if (type === "way" && tags.highway) {
    if (/motorway|trunk|primary|secondary|tertiary/.test(tags.highway || "") || isAllowedMainArteryName(roadName, tags)) {
      return "arteries";
    }
  }
  if (/station|halt|subway_entrance|tram_stop/.test(tags.railway || "") || /station|stop_position|platform/.test(tags.public_transport || "") || /bus_station|ferry_terminal/.test(tags.amenity || "") || tags.station === "subway") return "metro";
  if (/school|university|college|kindergarten|library/.test(tags.amenity || "")) return "education";
  if (tags.shop === "mall" || tags.amenity === "marketplace" || tags.building === "retail") return "malls";
  if (/coastline|beach|water|bay/.test(tags.natural || "") || tags.water === "sea" || /river|stream|canal/.test(tags.waterway || "")) return "coast";
  return "";
}

function isAllowedMainArteryName(name, tags = {}) {
  const compare = normalizeNameForCompare(name);
  if (/\b(sokak|sokagi|sok|sk)\b/i.test(compare)) return false;
  if (/(cadde|caddesi|bulvar|bulvari|karayolu|otoyol|cevre yolu|cevreyolu|devlet yolu|asfalti|asfalt|anayol|ana yol|yolu|\bd\s*-?\s*\d+|\be\s*-?\s*\d+)/i.test(compare)) return true;
  return /motorway|trunk|primary|secondary/i.test(tags.highway || "");
}

function isAllowedEducationName(name, tags = {}) {
  const compare = normalizeNameForCompare(`${name} ${tags.school || ""} ${tags.amenity || ""}`);
  if (/\b(kurs|surucu|dershane|akademi|akademisi|etut|egitim merkezi)\b/i.test(compare)) return false;
  return /okul|ilkokul|ortaokul|lise|universite|fakulte|kolej|school|university|college|kindergarten|anaokulu/i.test(compare);
}

function getClosestElementPoint(element, lat, lng) {
  const geometry = Array.isArray(element.geometry) ? element.geometry : [];
  if (!geometry.length) return null;
  const points = geometry
    .map((point) => ({ lat: Number(point.lat), lng: Number(point.lon ?? point.lng) }))
    .filter((point) => Number.isFinite(point.lat) && Number.isFinite(point.lng));
  if (!points.length) return null;
  if (points.length === 1) {
    return {
      ...points[0],
      distance: calculateDistanceMeters(lat, lng, points[0].lat, points[0].lng),
    };
  }

  const originLat = Number(lat);
  const originLng = Number(lng);
  const metersPerLat = 111320;
  const metersPerLng = 111320 * Math.max(Math.cos((originLat * Math.PI) / 180), 0.2);
  const project = (point) => ({
    x: (point.lng - originLng) * metersPerLng,
    y: (point.lat - originLat) * metersPerLat,
  });
  let best = null;
  for (let index = 0; index < points.length - 1; index += 1) {
    const a = points[index];
    const b = points[index + 1];
    const pa = project(a);
    const pb = project(b);
    const dx = pb.x - pa.x;
    const dy = pb.y - pa.y;
    const lengthSquared = dx * dx + dy * dy;
    const t = lengthSquared ? Math.max(0, Math.min(1, -(pa.x * dx + pa.y * dy) / lengthSquared)) : 0;
    const x = pa.x + dx * t;
    const y = pa.y + dy * t;
    const distance = Math.sqrt(x * x + y * y);
    if (!best || distance < best.distance) {
      best = {
        lat: a.lat + (b.lat - a.lat) * t,
        lng: a.lng + (b.lng - a.lng) * t,
        distance,
      };
    }
  }
  return best;
}

function readableNearbyFallback(category, tags) {
  if (category === "coast") return tags.natural === "beach" ? "Sahil" : "Deniz / kıyı alanı";
  if (category === "parks") return "Park / yeşil alan";
  if (category === "government") return "Kamu kurumu";
  if (category === "historic") return tags.tourism === "museum" ? "Müze" : "Tarihi / turistik nokta";
  if (category === "health") return tags.amenity === "pharmacy" ? "Eczane" : "Sağlık tesisi";
  if (category === "metro") return tags.amenity === "bus_station" ? "Otobüs terminali" : "Raylı sistem / ulaşım durağı";
  if (category === "education") return tags.amenity === "library" ? "Kütüphane" : "Eğitim kurumu";
  if (category === "malls") return tags.amenity === "marketplace" ? "Pazar alanı" : "Alışveriş merkezi";
  if (category === "junctions") return "Kavşak";
  return "";
}

function cleanupPlaceName(value) {
  return String(value || "").replace(/\s+/g, " ").trim();
}

function cleanupRoadName(value) {
  let text = cleanupPlaceName(value)
    .replace(/\bNo\s*[:.]?\s*\d+[A-Z]?\b/gi, "")
    .replace(/\s*\/\s*[A-Z0-9]+$/i, "")
    .replace(/\s*[-–—]\s*\d+[A-Z]?\s*$/i, "")
    .replace(/\s+\d+[A-Z]?\s*$/i, "")
    .replace(/\s+/g, " ")
    .trim();
  text = text.replace(/\b(Caddesi|Cadde|Bulvarı|Bulvari|Bulvar|Karayolu|Otoyol|Yolu)\s+\d+[A-Z]?\b/gi, "$1").trim();
  text = text
    .replace(/\bCadde$/i, "Caddesi")
    .replace(/\bBulvar$/i, "Bulvarı")
    .replace(/\bBulvari$/i, "Bulvarı");
  return text;
}

function calculateDistanceMeters(lat1, lng1, lat2, lng2) {
  const earthRadius = 6371000;
  const toRad = (value) => (Number(value) * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return earthRadius * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

function getNearbyDisplayPlaces(places, scanCycle = state.sourceValues.nearbyPlaces?.scanCycle || 0) {
  const eligiblePlaces = (places || []).filter((place) => isNearbyPlaceInAddressRadius(place));
  let candidates = eligiblePlaces
    .filter((place) => importantNearbyCategories.has(place.category))
    .sort((a, b) => {
      const priorityDiff = (nearbyCategoryPriority[a.category] ?? 99) - (nearbyCategoryPriority[b.category] ?? 99);
      return priorityDiff || a.distance - b.distance;
    });
  const nonSettlementCandidates = candidates.filter((place) => !isSettlementLikeNearbyPlace(place));
  if (nonSettlementCandidates.length >= nearbySettlementFallbackMinUsefulCount) {
    candidates = nonSettlementCandidates;
  }
  if (!candidates.length) {
    candidates = eligiblePlaces
      .filter((place) => place.category !== "arteries")
      .sort((a, b) => {
        const priorityDiff = (nearbyCategoryPriority[a.category] ?? 99) - (nearbyCategoryPriority[b.category] ?? 99);
        return priorityDiff || a.distance - b.distance;
      });
  }
  if (!candidates.length) {
    candidates = getNearbyArteries(eligiblePlaces);
  }
  if (candidates.length <= nearbyAutoLimit) return candidates;
  const start = (scanCycle * nearbyAutoLimit) % candidates.length;
  return [...candidates.slice(start), ...candidates.slice(0, start)].slice(0, nearbyAutoLimit);
}

function getAutoNearbySelectedIds(places, previousSelected, validIds, options = {}) {
  const displayPlaces = getNearbyDisplayPlaces(places, options.scanCycle || 0);
  const displayIds = new Set(displayPlaces.map((place) => place.id));
  const kept = [...previousSelected].filter((id) => validIds.has(id) && displayIds.has(id));
  if (kept.length && !options.rotate) return kept.slice(0, nearbyAutoLimit);
  return displayPlaces.map((place) => place.id);
}

function hasRequiredNearbyCoverage(places) {
  return getNearbyArteries(places).length >= mainArteryAutoLimit && getNearbyDisplayPlaces(places).length >= nearbyAutoLimit;
}

function mergeNearbyEnvironments(primary, secondary) {
  const places = dedupeAndSortNearbyPlaces([...(primary.places || []), ...(secondary.places || [])]);

  return {
    places,
    radius: Math.max(primary.radius || nearbyRadiusMeters, secondary.radius || nearbyRadiusMeters),
    regionAnalysis: secondary.regionAnalysis || primary.regionAnalysis,
  };
}

function toggleNearbySelection(id, checked) {
  const source = state.sourceValues.nearbyPlaces || { places: [], selectedIds: [] };
  const selected = new Set(source.selectedIds || []);
  if (checked) {
    selected.add(id);
  } else {
    selected.delete(id);
  }
  state.sourceValues.nearbyPlaces = {
    ...source,
    selectedIds: [...selected],
    selectionCustomized: true,
  };
  updateNearbyFieldFromSelection();
}

function updateNearbyFieldFromSelection() {
  const source = state.sourceValues.nearbyPlaces || {};
  const selected = new Set(source.selectedIds || []);
  const places = getNearbySelectionDisplayPlaces(source).filter((place) => selected.has(place.id)).sort((a, b) => a.distance - b.distance);
  state.fields.nearby = buildNearbyReportText(places);
  refreshEnvironmentDescriptionFromCurrentFields("nearby");
}

function getNearbyArteries(places) {
  const arteries = (places || [])
    .filter((place) => place.category === "arteries" && isNearbyPlaceInAddressRadius(place))
    .sort((a, b) => a.distance - b.distance);
  const withinRadius = arteries.filter((place) => place.distance <= getNearbySelectionRadiusMeters());
  if (withinRadius.length >= mainArteryAutoLimit) return withinRadius;
  const withinExpanded = arteries.filter((place) => place.distance <= Math.max(nearbyExpandedRadiusMeters, getNearbySelectionRadiusMeters()));
  return withinExpanded.slice(0, mainArteryAutoLimit);
}

function clearOutOfRangeMainArterySelection(places = []) {
  const currentId = state.fields.mainArteryId || "";
  if (!currentId) return false;
  const selectedRoad = [
    ...(state.sourceValues.userNearbyPlaces?.places || []),
    ...(places || []),
  ].find((road) => road?.id === currentId);
  if (!selectedRoad || isNearbyPlaceInAddressRadius(selectedRoad)) return false;

  state.fields.mainArteryId = "";
  const arterySource = state.sourceValues.nearbyArtery || {};
  const appliedArtery = arterySource.applied?.mainArtery || "";
  if (state.fields.mainArtery === appliedArtery || state.fields.mainArtery === selectedRoad.name) {
    state.fields.mainArtery = "";
    arterySource.applied = { ...(arterySource.applied || {}), mainArtery: "" };
    state.sourceValues.nearbyArtery = arterySource;
  }
  const transportSource = state.sourceValues.nearbyTransport || {};
  const appliedTransport = transportSource.applied?.transport || "";
  if (appliedTransport && state.fields.transport === appliedTransport) {
    state.fields.transport = "";
    transportSource.applied = { ...(transportSource.applied || {}), transport: "" };
    state.sourceValues.nearbyTransport = transportSource;
  }
  refreshEnvironmentDescriptionFromCurrentFields("mainArtery");
  return true;
}

function selectMainArtery(id, options = {}) {
  const roads = getAllMainArteryPlacesWithUser(state.sourceValues.nearbyPlaces?.places || []);
  const road = roads.find((item) => item.id === id);
  if (!road) return;

  state.fields.mainArteryId = road.id;
  state.sourceValues.nearbyArtery = state.sourceValues.nearbyArtery || {};
  setFieldFromSource("nearbyArtery", "mainArtery", road.name, { force: !options.auto });
  updateTransportFromMainArtery(road, { force: !options.auto });
  refreshEnvironmentDescriptionFromCurrentFields("mainArtery");
}

function updateTransportFromMainArtery(road, options = {}) {
  if (!road) return;
  const text = buildTransportDirectionText(road);
  // Kullanıcı talebi (2026-08-12): Çoklu Talep + Tarımsal Alan raporlarında
  // taşınmazlar AYNI parseldeyse (tek KML), Ulaşım Tarifi normal tekli
  // rapordaki AYNI ana-arter tabanlı otomatik metinle üretilmeli — yalnızca
  // "taşınmaz" ifadesi çoğullaşmalı ("taşınmazlar"). Farklı ada/parsellerde
  // (hasMixedTitleUnitParcels) bu metin uygun DEĞİL — o durum ayrı bir
  // taşınmaz-bazlı liste/özet ile ele alınıyor, bkz.
  // buildAgriculturalMultiTitleUnitTransportText.
  const shouldPluralize = state.fields?.environmentRegionType === "Tarımsal Alan"
    && isMultiTitleUnitReportForNarrative()
    && !hasMixedTitleUnitParcels();
  const finalText = shouldPluralize ? pluralizeEnvironmentalSubjectText(text, true) : text;
  state.sourceValues.nearbyTransport = state.sourceValues.nearbyTransport || {};
  setFieldFromSource("nearbyTransport", "transport", finalText, options);
}

// Varyantlar: kullanıcı talebi (2026-08-08) — "ulaşım ana arteri seçildiğinde
// gelen otomatik cümle de varyantlanmalı" (Ulaşım Tarifi alanı bizzat serbest
// metin olduğundan varyant sistemi dışında kalıyordu, ama HARİTADAN OTOMATİK
// ÜRETİLEN bu üç cümlelik kalıp — her ana arter seçiminde birebir aynı
// çıkıyordu — gerçek bir BDDK-risk kaynağıydı).
const transportDirectionVariants = [
  (roadSuffix, direction, distance, street) => `Ekspertize konu taşınmaza ulaşım için bölgenin ana arterlerinden ${roadSuffix} üzerinden ${direction} istikametine ilerlenir. Yaklaşık ${distance} metre sonra taşınmazın bulunduğu ${street} güzergahına ulaşılır. Ekspertize konu taşınmaz ${street} üzerinde yer almaktadır.`,
  (roadSuffix, direction, distance, street) => `Taşınmaza ulaşım, bölgenin ana arterlerinden ${roadSuffix} üzerinden ${direction} istikametine ilerlenerek sağlanır. Yaklaşık ${distance} metre sonra ${street} güzergâhına ulaşılmaktadır. Değerlemeye konu taşınmaz ${street} üzerinde yer almaktadır.`,
  (roadSuffix, direction, distance, street) => `Bölgenin ana arterlerinden ${roadSuffix} üzerinden ${direction} yönünde ilerlendiğinde, yaklaşık ${distance} metre sonra taşınmazın bulunduğu ${street} güzergâhına varılmaktadır. Söz konusu taşınmaz ${street} üzerinde konumludur.`,
  (roadSuffix, direction, distance, street) => `Taşınmaza erişim, ana arterlerden ${roadSuffix} üzerinden ${direction} istikametine hareket edilerek gerçekleştirilir; yaklaşık ${distance} metre sonra ${street} güzergâhına ulaşılır. Rapor konusu gayrimenkul ${street} üzerinde bulunmaktadır.`,
];
registerVariantGroup("buildTransportDirectionText", "Ana Arterden Otomatik Ulaşım Tarifi (Adres/Konum/Çevre)", transportDirectionVariants.length);

function buildTransportDirectionText(road) {
  // "Sokak / Cadde" boşsa (tarla/arazi gibi kırsal taşınmazlarda yaygın)
  // yedek değer BARE bir isim olmalı — varyant 0/2 zaten "taşınmazın
  // bulunduğu ${street}" kalıbını KENDİSİ kuruyor; yedek değer de aynı
  // ifadeyi içerirse "taşınmazın bulunduğu taşınmazın bulunduğu sokak"
  // gibi tekrarlı bir cümle çıkıyordu (kullanıcı bildirimi, 2026-08-12).
  const street = cleanupStreetName(state.fields.street || "sokak");
  const distance = Math.max(50, Math.round((road.distance || 0) / 10) * 10);
  const direction = getDirectionTextFromRoad(road);
  const roadSuffix = road.name.match(/caddesi|cadde|bulvarı|bulvar|sokak|sokağı/i) ? road.name : `${road.name} güzergahı`;
  return transportDirectionVariants[selectVariant("buildTransportDirectionText", transportDirectionVariants.length)](roadSuffix, direction, distance, street);
}

function getDirectionTextFromRoad(road) {
  const point = getSelectedMapPoint();
  if (!point || !Number.isFinite(road.lat) || !Number.isFinite(road.lng)) return "taşınmaz yönüne";
  const [lat, lng] = point;
  const bearing = calculateBearing(road.lat, road.lng, lat, lng);
  const directions = ["kuzey", "kuzeydoğu", "doğu", "güneydoğu", "güney", "güneybatı", "batı", "kuzeybatı"];
  return directions[Math.round(bearing / 45) % 8];
}

function calculateBearing(lat1, lng1, lat2, lng2) {
  const toRad = (value) => (Number(value) * Math.PI) / 180;
  const toDeg = (value) => (value * 180) / Math.PI;
  const y = Math.sin(toRad(lng2 - lng1)) * Math.cos(toRad(lat2));
  const x =
    Math.cos(toRad(lat1)) * Math.sin(toRad(lat2)) -
    Math.sin(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.cos(toRad(lng2 - lng1));
  return (toDeg(Math.atan2(y, x)) + 360) % 360;
}

function cleanupStreetName(value) {
  const text = cleanupPlaceName(value).replace(/\.$/, "");
  if (!text) return "sokak";
  return /sokak|sokağı|cadde|caddesi|bulvar|bulvarı/i.test(text) ? text : `${text} Sokak`;
}

function buildNearbyReportText(places) {
  if (!places.length) return "";
  return joinTurkishList(places.map((place) => place.name));
}

function joinTurkishList(items) {
  const clean = items.map((item) => cleanupPlaceName(item)).filter(Boolean);
  if (!clean.length) return "";
  if (clean.length === 1) return clean[0];
  if (clean.length === 2) return `${clean[0]} ve ${clean[1]}`;
  return `${clean.slice(0, -1).join(", ")} ve ${clean[clean.length - 1]}`;
}

async function processKmlFile(file) {
  const text = await readFileAsText(file);
  const parsed = parseKml(text);
  await applyKmlRecordsToTitleUnits([{ parsed, fileName: file.name || "" }]);
}

async function processKmlFiles(files) {
  const records = await Promise.all(
    (files || []).map(async (file) => ({
      parsed: parseKml(await readFileAsText(file)),
      fileName: file.name || "",
    })),
  );
  await applyKmlRecordsToTitleUnits(records);
}

// Kullanıcı talebi (2026-08-15, AskUserQuestion onayı): "KML'i tek seferde
// yükleyip tüm taşınmazlara uygula" — bkz. "aynı ada parsel taleplerinde 1
// adet kml olacak zaten kml parsel bazında bir dosya". Çoklu Talep'te aynı
// bina/parseldeki TÜM taşınmazlar (bağımsız bölümler) için gerçekte TEK bir
// KML yeterlidir; normal akışta (processKmlFiles → applyKmlRecordsToTitleUnits
// → getKmlTargetIndexes) her KML kaydı YALNIZCA BİR taşınmaza eşleşirdi,
// diğerleri İl/İlçe/Mahalle/Pafta/Ada/Parsel/Yüzölçümü gibi KML kaynaklı
// alanlar BOŞ kalırdı (yalnızca tabloda değil, RAPORUN KENDİSİNDE eksik veri
// anlamına gelirdi). Bu fonksiyon TEK dosyayı ayrıştırıp mevcut taşınmaz
// sayısı kadar (sığ kopyalanmış, birbirinden bağımsız) kayda çoğaltır ve
// applyKmlRecordsToTitleUnits()'e verir — getKmlTargetIndexes() zaten N
// kaydı N farklı taşınmaza (varsa ada/parsel eşleşmesiyle, yoksa sırayla
// boşta olana) dağıtan mantığa zaten sahip; burada YENİDEN YAZILMADI.
async function applyKmlFileToAllTitleUnits(file) {
  const parsed = parseKml(await readFileAsText(file));
  const unitCount = Math.max(getTitleUnitCount(), 1);
  const records = Array.from({ length: unitCount }, () => ({
    parsed: { ...parsed, fields: { ...parsed.fields } },
    fileName: file.name || "",
  }));
  await applyKmlRecordsToTitleUnits(records);
}

function normalizeKmlParcelMatchPart(value) {
  return String(value ?? "")
    .trim()
    .replace(/\s+/g, "")
    .toLocaleLowerCase("tr-TR");
}

function getKmlParcelMatchKey(fields = {}) {
  const blockNo = normalizeKmlParcelMatchPart(fields.blockNo);
  const parcelNo = normalizeKmlParcelMatchPart(fields.parcelNo);
  if (!parcelNo) return "";
  return blockNo ? `ada|${blockNo}|${parcelNo}` : `parsel|${parcelNo}`;
}

function kmlParcelMatchesTitleUnit(kmlFields = {}, titleFields = {}) {
  const kmlParcel = normalizeKmlParcelMatchPart(kmlFields.parcelNo);
  const titleParcel = normalizeKmlParcelMatchPart(titleFields.parcelNo);
  if (!kmlParcel || kmlParcel !== titleParcel) return false;
  const kmlBlock = normalizeKmlParcelMatchPart(kmlFields.blockNo);
  const titleBlock = normalizeKmlParcelMatchPart(titleFields.blockNo);
  return !kmlBlock || !titleBlock || kmlBlock === titleBlock;
}

function getKmlTargetIndexes(records) {
  while (getTitleUnitCount() < records.length) addTitleUnitTab();
  const available = new Set(Array.from({ length: getTitleUnitCount() }, (_, index) => index));
  return records.map((record, orderIndex) => {
    const kmlKey = getKmlParcelMatchKey(record.parsed?.fields);
    let targetIndex = -1;
    if (kmlKey) {
      targetIndex = [...available].find(
        (index) => kmlParcelMatchesTitleUnit(record.parsed?.fields, getTitleUnitFieldsForLabel(index)),
      ) ?? -1;
    }
    if (targetIndex < 0) targetIndex = [...available][0] ?? orderIndex;
    available.delete(targetIndex);
    return targetIndex;
  });
}

async function applyKmlRecordsToTitleUnits(records) {
  const validRecords = (records || []).filter((record) => record?.parsed?.fields);
  if (!validRecords.length) return;
  const targetIndexes = getKmlTargetIndexes(validRecords);

  for (let recordIndex = 0; recordIndex < validRecords.length; recordIndex += 1) {
    const record = validRecords[recordIndex];
    const targetIndex = targetIndexes[recordIndex];
    if (targetIndex !== state.activeTitleUnitIndex) switchActiveTitleUnit(targetIndex);
    const preserveShared = recordIndex > 0;
    resetKmlDerivedFields({ preserveShared });
    state.sourceValues.kml = record.parsed;
    state.sourceValues.kml.fileName = record.fileName;
    applyKmlFieldsToReport({ force: true, preserveShared });

    // Her KML kendi taşınmazının mahalle/köy/ilçe ve mesafe verisini üretmelidir.
    // Açıklama alanları ortak kalsa da bu teknik konum verileri tab bazında saklanır.
    await applyLocalNeighborhoodForCurrentLocation({ force: true, silent: true }).catch(() => false);
    nearbyAutoFetchStarted = false;
    state.sourceValues.nearbyPlaces = {
      ...(state.sourceValues.nearbyPlaces || {}),
      loading: true,
      center: record.parsed.centroid
        ? { lat: record.parsed.centroid.lat, lng: record.parsed.centroid.lng }
        : state.sourceValues.nearbyPlaces?.center,
    };
    await fetchNearbyPlacesForCurrentLocation({ silent: true, force: true }).catch(() => false);
  }
  switchActiveTitleUnit(0);
  // Tüm taşınmazların KML/mesafe verisi artık bilinir (döngü bitti) — Çoklu
  // Talep + Tarımsal Alan raporlarında "Ulaşım Tarifi"ni bu güncel listeyle
  // yeniden üret (bkz. refreshMultiTitleUnitAgriculturalTransport yorumu).
  refreshMultiTitleUnitAgriculturalTransport();
  // Paylaşımlı "Çevresel Özellikler Açıklaması" da (buildAgriculturalKmlDistanceSentence
  // üzerinden) aynı güncel taşınmaz listesiyle yeniden hesaplansın — aksi
  // halde son işlenen taşınmazın mesafesiyle donmuş kalırdı (kullanıcı
  // bildirimi, 2026-08-12).
  refreshEnvironmentDescriptionFromCurrentFields("boundNeighborhoodDistance");
  autosave();
  renderValidation();
  updateStatus();
}

function resetKmlDerivedFields(options = {}) {
  const preserveShared = Boolean(options.preserveShared);
  nearbyRequestSerial += 1;
  nearbyAutoFetchStarted = false;
  [
    "latitude",
    "longitude",
    "boundNeighborhood",
    "boundNeighborhoodDistance",
    "nearestNeighborhood",
    "nearestNeighborhoodDistance",
    "districtCenterDistance",
    "cityCenterDistance",
    "landRoadType",
    "landRoadName",
    "landRoadDirection",
    "landRoadFrontageLength",
    "mainArtery",
    "mainArteryProximity",
    "mainArteryId",
    "transport",
    "nearby",
    "regionBuildOrder",
    "regionFloorRange",
    "regionIncomeLevel",
    "infrastructureLevel",
    "developmentSpeed",
    "regionBuildingAge",
    "developmentDensity",
    "socialNeeds",
    "regionUsePurpose",
    "environmentRegionType",
    "agriculturalActivityDensity",
    "agriculturalActivityTypes",
    "agriculturalSuitability",
    "commercialFunctionDensity",
    "commercialFirmType",
    "commercialFrontageRoadType",
    "commercialDevelopmentCompleted",
    "environmentDescription",
  ].filter((key) => !preserveShared || !TITLE_UNIT_SHARED_EXPLANATION_FIELD_KEYS.has(key)).forEach((key) => {
    state.fields[key] = "";
  });
  state.fields.landRoadFrontageItems = [];
  state.sourceValues.nearbyPlaces = {};
  state.sourceValues.nearbyArtery = {};
  state.sourceValues.nearbyTransport = {};
  state.sourceValues.regionAnalysis = {};
  state.sourceValues.localNeighborhood = {};
  state.sourceConflicts.nearbyArtery = {};
  state.sourceConflicts.nearbyTransport = {};
  state.sourceConflicts.regionAnalysis = {};
  state.sourceConflicts.localNeighborhood = {};
  state.uploadErrors = {
    ...(state.uploadErrors || {}),
    nearbyPlaces: "",
    geoLookup: "",
  };
}

function parseKml(text) {
  const kmlParser = globalThis.RaporKmlParser;
  if (!kmlParser || typeof kmlParser.parseKmlDocument !== "function") {
    throw new Error("KML ayrıştırıcı yüklenemedi.");
  }

  const { extended, coordinates, centroid, rawText } = kmlParser.parseKmlDocument(text);
  const fields = {
    city: readKmlExtendedValue(extended, ["İl", "Il", "il", "IL"]),
    district: readKmlExtendedValue(extended, ["İlçe", "Ilce", "ilce", "ILCE"]),
    // KML "Nitelik" değeri parselin (ana taşınmazın) niteliğidir; bağımsız bölüm
    // niteliği değildir. Bu yüzden mainPropertyQuality'e yazılır. Bağımsız bölüm
    // niteliği (titleQuality) yalnızca TAKBİS boşsa fallback olarak doldurulur
    // (bkz. applyKmlFieldsToReport) — TAKBİS'ten gelen BB niteliği ezilmez.
    mainPropertyQuality: firstValue(extended, ["Nitelik", "nitelik", "NITELIK"]),
    blockNo: firstValue(extended, ["Ada", "ada", "ADA"]),
    parcelNo: firstValue(extended, ["ParselNo", "Parsel", "parsel", "PARSEL"]),
    sheetNo: firstValue(extended, ["Pafta", "pafta", "PAFTA"]) || extractPaftaFromText(rawText),
    landShape: inferLandShapeFromKmlCoordinates(coordinates),
    landNote: inferLandFrontageSummaryFromKmlCoordinates(coordinates),
    latitude: centroid?.lat || "",
    longitude: centroid?.lng || "",
  };

  return {
    fields,
    parcelNeighborhood: readKmlExtendedValue(extended, ["Mahalle", "mahalle", "MAHALLE"]),
    coordinates,
    centroid,
    readAt: new Date().toISOString(),
  };
}

function inferLandShapeFromKmlCoordinates(coordinates = []) {
  const projected = projectKmlCoordinatesToMeters(coordinates);
  const points = removeClosingDuplicatePoints(removeNearDuplicatePoints(projected));
  if (points.length < 3) return "";

  const perimeter = calculatePolygonPerimeter(points);
  const area = Math.abs(calculatePolygonArea(points));
  if (!perimeter || !area) return "";

  const bounds = getPointBounds(points);
  const diagonal = Math.hypot(bounds.maxX - bounds.minX, bounds.maxY - bounds.minY);
  const tolerance = Math.max(1, diagonal * 0.04);
  const simplified = simplifyClosedPolygon(points, tolerance);
  const vertexCount = simplified.length;

  const circularity = (4 * Math.PI * area) / (perimeter * perimeter);
  if (vertexCount >= 8 && circularity >= 0.78) return "Daire";

  const orientedBox = calculatePrincipalOrientedBox(points);
  if (orientedBox.area > 0) {
    const fillRatio = area / orientedBox.area;
    const rightAngleShare = calculateRightAngleShare(simplified);
    const parallelPairCount = countParallelEdgePairs(simplified);
    const isVisuallyRectangular = rightAngleShare >= 0.55 && (parallelPairCount >= 2 || vertexCount > 5);
    if (fillRatio >= 0.6 && isVisuallyRectangular) {
      return orientedBox.aspectRatio <= 1.25 ? "Kare" : "Dikdörtgen";
    }
  }

  if (vertexCount <= 3 && points.length <= 4) return "Üçgen";
  if (vertexCount <= 5 && hasTrapezoidLikeParallelEdges(simplified)) return "Yamuk";
  return "Amorf";
}

function inferLandFrontageSummaryFromKmlCoordinates(coordinates = []) {
  const directionTotals = getKmlFrontageOptionsFromCoordinates(coordinates);
  if (!directionTotals.length) return "";
  const formattedLengths = directionTotals
    .map((edge) => `${edge.direction} cephesi ${formatMeterLength(edge.length)}`)
    .join(", ");
  return `KML sınırına göre yaklaşık cephe/kenar uzunlukları: ${formattedLengths}.`;
}

function getKmlFrontageOptionsFromCoordinates(coordinates = []) {
  const projected = projectKmlCoordinatesToMeters(coordinates);
  const points = removeClosingDuplicatePoints(removeNearDuplicatePoints(projected));
  if (points.length < 3) return [];

  const bounds = getPointBounds(points);
  const diagonal = Math.hypot(bounds.maxX - bounds.minX, bounds.maxY - bounds.minY);
  const tolerance = Math.max(1, diagonal * 0.018);
  const simplified = simplifyClosedPolygonToMaxVertices(points, tolerance, 8);
  if (simplified.length < 3) return [];

  const lengths = simplified.map((point, index) => {
    const next = simplified[(index + 1) % simplified.length];
    return {
      direction: getEdgeFacingDirection(simplified, index),
      length: Math.hypot(point.x - next.x, point.y - next.y),
    };
  }).filter((edge) => Number.isFinite(edge.length) && edge.length > 0.5);

  if (!lengths.length) return [];
  return mergeFrontageLengthsByDirection(lengths);
}

function formatMeterLength(value) {
  return `${Number(value).toLocaleString("tr-TR", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })} m`;
}

function mergeFrontageLengthsByDirection(edges = []) {
  const directionOrder = ["Kuzey", "Kuzeydoğu", "Doğu", "Güneydoğu", "Güney", "Güneybatı", "Batı", "Kuzeybatı", "Belirsiz"];
  const totals = new Map();
  edges.forEach((edge) => {
    const direction = edge.direction || "Belirsiz";
    totals.set(direction, (totals.get(direction) || 0) + Number(edge.length || 0));
  });
  return directionOrder
    .filter((direction) => totals.has(direction))
    .map((direction) => ({ direction, length: totals.get(direction) }));
}

function simplifyClosedPolygonToMaxVertices(points = [], tolerance = 1, maxVertices = 8) {
  let simplified = simplifyClosedPolygon(points, tolerance);
  let nextTolerance = tolerance;
  for (let pass = 0; pass < 12 && simplified.length > maxVertices; pass += 1) {
    nextTolerance *= 1.25;
    const next = simplifyClosedPolygon(points, nextTolerance);
    if (next.length < 3 || next.length === simplified.length) break;
    simplified = next;
  }

  while (simplified.length > maxVertices) {
    simplified = removeLeastVisiblePolygonVertex(simplified);
  }
  return simplified;
}

function removeLeastVisiblePolygonVertex(points = []) {
  if (points.length <= 3) return points;
  let removeIndex = -1;
  let smallestDistance = Infinity;
  points.forEach((point, index) => {
    const previous = points[(index - 1 + points.length) % points.length];
    const next = points[(index + 1) % points.length];
    const distance = distancePointToSegment(point, previous, next);
    if (distance < smallestDistance) {
      smallestDistance = distance;
      removeIndex = index;
    }
  });
  return points.filter((_, index) => index !== removeIndex);
}

function getEdgeFacingDirection(points = [], index = 0) {
  const point = points[index];
  const next = points[(index + 1) % points.length];
  const signedArea = calculatePolygonArea(points);
  const dx = next.x - point.x;
  const dy = next.y - point.y;
  const outward = signedArea >= 0
    ? { x: dy, y: -dx }
    : { x: -dy, y: dx };
  return getCompassDirectionFromVector(outward.x, outward.y);
}

function getCompassDirectionFromVector(x, y) {
  if (!Number.isFinite(x) || !Number.isFinite(y) || (!x && !y)) return "Belirsiz";
  const angle = (Math.atan2(y, x) * 180) / Math.PI;
  const normalized = (90 - angle + 360) % 360;
  const directions = ["Kuzey", "Kuzeydoğu", "Doğu", "Güneydoğu", "Güney", "Güneybatı", "Batı", "Kuzeybatı"];
  return directions[Math.round(normalized / 45) % directions.length];
}

function projectKmlCoordinatesToMeters(coordinates = []) {
  const valid = coordinates
    .map((point) => ({ lat: Number(point.lat), lng: Number(point.lng) }))
    .filter((point) => Number.isFinite(point.lat) && Number.isFinite(point.lng));
  if (!valid.length) return [];

  const centerLat = valid.reduce((sum, point) => sum + point.lat, 0) / valid.length;
  const latScale = 110540;
  const lngScale = 111320 * Math.cos((centerLat * Math.PI) / 180);
  return valid.map((point) => ({
    x: point.lng * lngScale,
    y: point.lat * latScale,
  }));
}

function removeClosingDuplicatePoints(points = []) {
  if (points.length < 2) return points;
  const first = points[0];
  const last = points[points.length - 1];
  return Math.hypot(first.x - last.x, first.y - last.y) < 0.2 ? points.slice(0, -1) : points;
}

function removeNearDuplicatePoints(points = []) {
  const clean = [];
  points.forEach((point) => {
    const last = clean[clean.length - 1];
    if (!last || Math.hypot(point.x - last.x, point.y - last.y) >= 0.2) {
      clean.push(point);
    }
  });
  return clean;
}

function simplifyClosedPolygon(points = [], tolerance = 1) {
  let simplified = [...points];
  for (let pass = 0; pass < 20 && simplified.length > 3; pass += 1) {
    const next = simplified.filter((point, index, list) => {
      const previous = list[(index - 1 + list.length) % list.length];
      const following = list[(index + 1) % list.length];
      return distancePointToSegment(point, previous, following) > tolerance;
    });
    if (next.length === simplified.length || next.length < 3) break;
    simplified = next;
  }
  return simplified;
}

function distancePointToSegment(point, start, end) {
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  if (!dx && !dy) return Math.hypot(point.x - start.x, point.y - start.y);
  const ratio = Math.max(0, Math.min(1, ((point.x - start.x) * dx + (point.y - start.y) * dy) / (dx * dx + dy * dy)));
  const projected = { x: start.x + ratio * dx, y: start.y + ratio * dy };
  return Math.hypot(point.x - projected.x, point.y - projected.y);
}

function calculatePolygonArea(points = []) {
  return points.reduce((sum, point, index) => {
    const next = points[(index + 1) % points.length];
    return sum + point.x * next.y - next.x * point.y;
  }, 0) / 2;
}

function calculatePolygonPerimeter(points = []) {
  return points.reduce((sum, point, index) => {
    const next = points[(index + 1) % points.length];
    return sum + Math.hypot(point.x - next.x, point.y - next.y);
  }, 0);
}

function getPointBounds(points = []) {
  return points.reduce(
    (bounds, point) => ({
      minX: Math.min(bounds.minX, point.x),
      maxX: Math.max(bounds.maxX, point.x),
      minY: Math.min(bounds.minY, point.y),
      maxY: Math.max(bounds.maxY, point.y),
    }),
    { minX: Infinity, maxX: -Infinity, minY: Infinity, maxY: -Infinity },
  );
}

function calculatePrincipalOrientedBox(points = []) {
  const center = points.reduce((acc, point) => ({ x: acc.x + point.x, y: acc.y + point.y }), { x: 0, y: 0 });
  center.x /= points.length;
  center.y /= points.length;

  const covariance = points.reduce(
    (acc, point) => {
      const x = point.x - center.x;
      const y = point.y - center.y;
      acc.xx += x * x;
      acc.xy += x * y;
      acc.yy += y * y;
      return acc;
    },
    { xx: 0, xy: 0, yy: 0 },
  );
  const angle = Math.atan2(2 * covariance.xy, covariance.xx - covariance.yy) / 2;
  const cos = Math.cos(angle);
  const sin = Math.sin(angle);
  const projections = points.map((point) => ({
    x: (point.x - center.x) * cos + (point.y - center.y) * sin,
    y: -(point.x - center.x) * sin + (point.y - center.y) * cos,
  }));
  const bounds = getPointBounds(projections);
  const width = bounds.maxX - bounds.minX;
  const height = bounds.maxY - bounds.minY;
  const minSide = Math.min(width, height);
  const maxSide = Math.max(width, height);
  return {
    area: width * height,
    aspectRatio: minSide > 0 ? maxSide / minSide : Infinity,
  };
}

function calculateRightAngleShare(points = []) {
  if (points.length < 4) return 0;
  const rightAngles = points.filter((point, index) => {
    const previous = points[(index - 1 + points.length) % points.length];
    const next = points[(index + 1) % points.length];
    const vectorA = { x: previous.x - point.x, y: previous.y - point.y };
    const vectorB = { x: next.x - point.x, y: next.y - point.y };
    const lengthA = Math.hypot(vectorA.x, vectorA.y);
    const lengthB = Math.hypot(vectorB.x, vectorB.y);
    if (!lengthA || !lengthB) return false;
    const cosine = Math.max(-1, Math.min(1, (vectorA.x * vectorB.x + vectorA.y * vectorB.y) / (lengthA * lengthB)));
    const angle = Math.acos(cosine);
    return Math.abs(angle - Math.PI / 2) <= Math.PI / 5;
  });
  return rightAngles.length / points.length;
}

function hasTrapezoidLikeParallelEdges(points = []) {
  return countParallelEdgePairs(points) === 1;
}

function countParallelEdgePairs(points = []) {
  if (points.length < 4) return 0;
  const angles = points.map((point, index) => {
    const next = points[(index + 1) % points.length];
    return Math.atan2(next.y - point.y, next.x - point.x);
  });
  let count = 0;
  for (let index = 0; index < angles.length; index += 1) {
    for (let other = index + 1; other < angles.length; other += 1) {
      if (Math.abs(index - other) === 1 || Math.abs(index - other) === angles.length - 1) continue;
      const diff = Math.abs(Math.atan2(Math.sin(angles[index] - angles[other]), Math.cos(angles[index] - angles[other])));
      if (Math.min(diff, Math.PI - diff) <= Math.PI / 12) count += 1;
    }
  }
  return count;
}

function firstValue(values, keys) {
  for (const key of keys) {
    if (values[key]) return values[key];
  }
  return "";
}

function readKmlExtendedValue(values, labels) {
  const labelKeys = labels.map(normalizeLocalPlaceKey);
  for (const [key, value] of Object.entries(values || {})) {
    if (labelKeys.includes(normalizeLocalPlaceKey(key))) return value;
  }
  return "";
}

function extractPaftaFromText(text) {
  const match = text.match(/pafta\s*(?:no|numarası|numarasi)?\s*[:\-]?\s*([A-ZÇĞİÖŞÜ0-9/.\-\s]{2,30})/i);
  return match ? match[1].replace(/\s+/g, " ").trim() : "";
}

function applyKmlFieldsToReport(options = {}) {
  const fields = state.sourceValues.kml?.fields || {};
  state.sourceConflicts.kml = {};
  mergeLookupOptions({
    city: fields.city,
    district: fields.district,
  });

  Object.entries(fields).forEach(([key, value]) => {
    if (!value) return;
    // KML verisi bağımsız bölüm niteliği (titleQuality) ve posta koduna (postalCode)
    // hiç dokunmaz; bu alanlar yalnızca TAKBİS/adres kaynaklarından gelir.
    if (key === "titleQuality" || key === "postalCode") return;
    setFieldFromSource("kml", key, value, options);
  });
  applyAdministrativeNeighborhoodFallback("kml", state.sourceValues.kml?.parcelNeighborhood);
  refreshLandDescriptionFromCurrentFields("landShape");
}

function applyAdministrativeNeighborhoodFallback(source, value) {
  const neighborhood = cleanNeighborhoodName(value || "");
  if (!neighborhood || hasUavtAddressSource()) return;
  const currentValue = state.fields.neighborhood || "";
  const currentSource = state.sourceValues.administrativeNeighborhoodFallback?.source || "";
  if (source === "kml" && currentValue && currentSource && currentSource !== "kml") return;
  if (currentValue && !currentSource) return;

  state.sourceValues.administrativeNeighborhoodFallback = {
    source,
    value: neighborhood,
    readAt: new Date().toISOString(),
  };
  state.sourceValues[source] = state.sourceValues[source] || {};
  setFieldFromSource(source, "neighborhood", neighborhood, { force: !currentValue || currentSource === source || (source === "takbis" && currentSource === "kml") });
}

function hasUavtAddressSource() {
  return Boolean(state.sourceValues.address?.fileName || state.sourceValues.address?.rawText);
}

function setFieldFromSource(source, key, value, options = {}) {
  const nextValue = normalizeReportFieldValue(key, value);
  const currentValue = state.fields[key] || "";
  const previousSourceValue = state.sourceValues[source]?.applied?.[key] || "";
  const shouldApply = options.force || !currentValue || currentValue === previousSourceValue;

  state.sourceValues[source].applied = {
    ...(state.sourceValues[source].applied || {}),
    [key]: nextValue,
  };

  if (shouldApply) {
    state.fields[key] = nextValue;
    delete state.sourceConflicts[source]?.[key];
    return;
  }

  state.sourceConflicts[source] = {
    ...(state.sourceConflicts[source] || {}),
    [key]: {
      currentValue,
      suggestedValue: nextValue,
    },
  };
}

function getTitleUnitKmlRecordsForMap() {
  return Array.from({ length: getTitleUnitCount() }, (_, index) => {
    const sourceValues = index === state.activeTitleUnitIndex
      ? state.sourceValues
      : index === 0
        ? state.primaryTitleUnitShadow?.sourceValues
        : state.titleUnits[index - 1]?.sourceValues;
    const parsed = sourceValues?.kml;
    if (!parsed?.coordinates?.length) return null;
    return { index, parsed, fields: getTitleUnitFieldsForLabel(index), sourceValues };
  }).filter(Boolean);
}

function getKmlRecordParcelFields(record = {}) {
  const parsedFields = record.parsed?.fields || {};
  const reportFields = record.fields || {};
  return {
    blockNo: String(parsedFields.blockNo || reportFields.blockNo || "").trim(),
    parcelNo: String(parsedFields.parcelNo || reportFields.parcelNo || "").trim(),
  };
}

function getKmlMapSubjectEntries(records = []) {
  const isMulti = isMultiTitleUnitReportForNarrative() || records.length > 1;
  if (!isMulti) return [{ index: state.activeTitleUnitIndex, text: "KONU TAŞINMAZ" }];

  const distinctParcelKeys = new Set(records.map((record) => {
    const { blockNo, parcelNo } = getKmlRecordParcelFields(record);
    return [blockNo, parcelNo].map(normalizeKmlParcelMatchPart).join("|");
  }));
  if (distinctParcelKeys.size <= 1) {
    return [{ index: state.activeTitleUnitIndex, text: "KONU TAŞINMAZLAR" }];
  }

  return records.map((record) => {
    const { blockNo, parcelNo } = getKmlRecordParcelFields(record);
    const parcelText = [blockNo ? `${blockNo} Ada` : "", parcelNo ? `${parcelNo} Parsel` : ""]
      .filter(Boolean)
      .join(" ");
    return { index: record.index, text: parcelText || `TAŞINMAZ ${record.index + 1}` };
  });
}

function getCompactKmlSubjectLabel(record, fallback = "KONU TAŞINMAZ") {
  const { blockNo, parcelNo } = getKmlRecordParcelFields(record);
  return blockNo && parcelNo ? `${blockNo}/${parcelNo}` : fallback;
}
function renderLeafletKmlMap() {
  const panel = document.querySelector("#kmlMapPanel");
  const records = getTitleUnitKmlRecordsForMap();
  const parsed = state.sourceValues.kml;
  if (!panel) return;

  const selectedPoint = getSelectedMapPoint();
  const hasKmlGeometry = records.length > 0;

  if (!hasKmlGeometry && !selectedPoint) {
    renderKmlMapFallback("KML dosyası yükleyin veya enlem/boylam alanlarını doldurun.");
    return;
  }

  if (!isLeafletReady()) {
    renderStaticKmlMap();
    scheduleLeafletMapRetry();
    return;
  }

  try {
    const leaflet = window.L;

  if (leafletMap) {
    leafletMap.remove();
  }

  panel.innerHTML = "";
  leafletMap = null;
  leafletKmlLayer = null;
  leafletSelectedMarker = null;
  leafletKmlSubjectMarkers = [];

  const firstRecord = records[0];
  const center = selectedPoint || (firstRecord?.parsed?.centroid
    ? [Number(firstRecord.parsed.centroid.lat), Number(firstRecord.parsed.centroid.lng)]
    : firstRecord?.parsed?.coordinates?.[0]
      ? [firstRecord.parsed.coordinates[0].lat, firstRecord.parsed.coordinates[0].lng]
      : [Number(state.fields.latitude), Number(state.fields.longitude)]);

  leafletMap = leaflet.map(panel, getLeafletInteractionOptions({ forceDraggable: true })).setView(center, 16);

  getLeafletTileLayer().addTo(leafletMap);

  const polygonLayers = records.map((record, recordIndex) => leaflet.polygon(
    record.parsed.coordinates.map((point) => [point.lat, point.lng]),
    {
      color: recordIndex === 0 ? "#d92525" : "#2563eb",
      weight: 3,
      opacity: 0.95,
      fillColor: recordIndex === 0 ? "#d92525" : "#2563eb",
      fillOpacity: 0.16,
    },
  ).addTo(leafletMap));
  leafletKmlLayer = polygonLayers.length ? leaflet.featureGroup(polygonLayers).addTo(leafletMap) : null;

  records.forEach((record) => {
    if (!record.parsed.centroid || record.index === state.activeTitleUnitIndex) return;
    const marker = leaflet.marker([record.parsed.centroid.lat, record.parsed.centroid.lng])
      .addTo(leafletMap)
      .bindPopup(`Taşınmaz ${record.index + 1}${record.fields?.blockNo ? `<br>Blok: ${escapeHtml(record.fields.blockNo)}` : ""}`);
    leafletKmlSubjectMarkers.push({ index: record.index, marker });
  });

  leafletSelectedMarker = leaflet.marker(center, { draggable: !isCoarsePointerDevice() })
    .addTo(leafletMap)
    .bindPopup(`Seçili konum${parsed?.fields?.sheetNo ? `<br>Pafta: ${escapeHtml(parsed.fields.sheetNo)}` : ""}`);

  leafletSelectedMarker.on("dragend", (event) => {
    const point = event.target.getLatLng();
    updateSelectedCoordinates(point.lat, point.lng);
  });

  leafletMap.on("click", (event) => {
    const { lat, lng } = event.latlng;
    updateSelectedCoordinates(lat, lng);
    leafletSelectedMarker.setLatLng([lat, lng]);
  });

  renderSelectedNearbyMarkers();

  if (leafletKmlLayer) {
    leafletMap.fitBounds(leafletKmlLayer.getBounds(), {
      padding: [70, 70],
      maxZoom: 16,
    });
  } else {
    leafletMap.setView(center, 16);
  }

  window.setTimeout(() => leafletMap?.invalidateSize?.(), 0);
  } catch (error) {
    console.warn("Leaflet haritasi cizilemedi.", error);
    renderStaticKmlMap();
  }
}

function scheduleLeafletMapRetry() {
  if (leafletMapRetryTimer || typeof window === "undefined") return;
  let attempts = 0;
  const retry = () => {
    leafletMapRetryTimer = null;
    const panel = document.querySelector("#kmlMapPanel");
    if (!panel || panel.querySelector(".leaflet-container")) return;
    if (isLeafletReady()) {
      renderLeafletKmlMap();
      return;
    }
    attempts += 1;
    if (attempts < 20) {
      leafletMapRetryTimer = window.setTimeout(retry, 250);
    }
  };
  leafletMapRetryTimer = window.setTimeout(retry, 0);
}

function isLeafletReady() {
  const ready = Boolean(
    window.L
      && typeof window.L.map === "function"
      && typeof window.L.tileLayer === "function"
      && typeof window.L.polygon === "function"
      && typeof window.L.marker === "function",
  );
  if (ready) configureLeafletMarkerIcon();
  return ready;
}

function isCoarsePointerDevice() {
  try {
    return Boolean(window.matchMedia && window.matchMedia("(hover: none), (pointer: coarse)").matches);
  } catch (error) {
    return false;
  }
}

function getLeafletInteractionOptions(options = {}) {
  const base = isCoarsePointerDevice()
    ? { dragging: false, tap: false, touchZoom: true, scrollWheelZoom: false }
    : {};
  // Kullanıcı talebi (2026-08-05): "adres ve konum haritası ve emsal
  // haritasında serbest gezinemiyorum" — dokunmatik cihazlarda haritanın
  // tek parmak kaydırmayı yutup sayfa kaymasını engellemesini önlemek
  // için eklenen dragging:false koruması (0.0.168) BU İKİ harita için
  // kullanıcının açık isteğiyle geri açılıyor; diğer haritalardaki
  // (ör. emsal nokta seçme overlay'i) mobil koruma DOKUNULMADAN kalıyor.
  if (options.forceDraggable) return { ...base, dragging: true };
  return base;
}

let leafletMarkerIconConfigured = false;

function configureLeafletMarkerIcon() {
  if (leafletMarkerIconConfigured || !window.L?.divIcon || !window.L?.Marker?.prototype) return;
  window.L.Marker.prototype.options.icon = window.L.divIcon({
    className: "experify-map-marker",
    html: "<span aria-hidden=\"true\"></span>",
    iconSize: [26, 34],
    iconAnchor: [13, 34],
    popupAnchor: [0, -32],
  });
  leafletMarkerIconConfigured = true;
}

function renderSelectedNearbyMarkers() {
  if (!isLeafletReady() || !leafletMap) return;
  const places = getMapLabelPlaces().filter((place) => Number.isFinite(place.lat) && Number.isFinite(place.lng));
  places.forEach((place) => {
    const marker = window.L.circleMarker([place.lat, place.lng], {
      radius: 7,
      color: place.category === "arteries" ? "#7f1212" : "#0f6b5d",
      weight: 2,
      fillColor: place.category === "arteries" ? "#d92525" : "#1f8f7a",
      fillOpacity: 0.9,
    }).addTo(leafletMap);
    marker.bindPopup(escapeHtml(place.name));
  });
  // Etiketler: tekli talepte konu taşınmaz; çoklu talepte aynı parsel için
  // konu taşınmazlar, farklı parseller için her KML'nin ada/parseli gösterilir.
  const entries = [];
  const kmlRecords = getTitleUnitKmlRecordsForMap();
  const subjectEntries = getKmlMapSubjectEntries(kmlRecords);
  subjectEntries.forEach((subject) => {
    const marker = subject.index === state.activeTitleUnitIndex
      ? leafletSelectedMarker
      : leafletKmlSubjectMarkers.find((item) => item.index === subject.index)?.marker;
    if (marker) entries.push({ kind: "subject", subjectIndex: subject.index, latlng: marker.getLatLng(), text: subject.text });
  });
  places.forEach((place) => {
    entries.push({
      kind: "place",
      latlng: [place.lat, place.lng],
      text: place.name,
      color: place.category === "arteries" ? "#7f1212" : "#0f6b5d",
    });
  });
  const leader = renderMapLeaderLabels(leafletMap, window.L, entries);
  if (leafletSelectedMarker && entries.length && subjectEntries.some((item) => item.index === state.activeTitleUnitIndex)) {
    leafletSelectedMarker.on("drag", () => {
      const activeEntry = entries.find((entry) => entry.kind === "subject"
        && entry.subjectIndex === state.activeTitleUnitIndex);
      if (activeEntry) activeEntry.latlng = leafletSelectedMarker.getLatLng();
      leader.relayout();
    });
  }
}

function getMapLabelPlaces() {
  const records = getTitleUnitKmlRecordsForMap();
  const sources = records.length
    ? records.map((record) => ({
      sourceValues: record.sourceValues || {},
      fields: record.fields || {},
    }))
    : [{ sourceValues: state.sourceValues, fields: state.fields }];
  const allPlaces = sources.flatMap(({ sourceValues, fields }) => {
    const nearbySource = sourceValues.nearbyPlaces || {};
    const selected = new Set(nearbySource.selectedIds || []);
    const selectedPlaces = getAllNearbyPlacesWithUser(nearbySource.places || [])
      .filter((place) => selected.has(place.id));
    const selectedArteryId = String(fields.mainArteryId || "");
    const selectedArtery = selectedArteryId
      ? getAllMainArteryPlacesWithUser(nearbySource.places || [])
        .find((place) => place.id === selectedArteryId)
      : null;
    return [...selectedPlaces, ...(selectedArtery ? [selectedArtery] : [])];
  });
  return [...new Map(
    allPlaces
      .map((place) => [place.id, place]),
  ).values()];
}

function renderStaticKmlMap() {
  const panel = document.querySelector("#kmlMapPanel");
  const records = getTitleUnitKmlRecordsForMap();
  const parsed = state.sourceValues.kml;
  if (!panel) return;

  const selectedPoint = getSelectedMapPoint();
  const hasKmlGeometry = records.length > 0;
  if (!hasKmlGeometry && !selectedPoint) {
    renderKmlMapFallback("KML dosyası yükleyin veya enlem/boylam alanlarını doldurun.");
    return;
  }

  const firstRecord = records[0];
  const points = firstRecord?.parsed?.coordinates || [];
  const center = selectedPoint || (firstRecord?.parsed?.centroid
    ? [Number(firstRecord.parsed.centroid.lat), Number(firstRecord.parsed.centroid.lng)]
    : [Number(points[0]?.lat), Number(points[0]?.lng)]);
  const nearby = getMapLabelPlaces().filter((place) => Number.isFinite(place.lat) && Number.isFinite(place.lng));
  const allPoints = [
    ...records.flatMap((record) => record.parsed.coordinates.map((point) => [Number(point.lat), Number(point.lng)])),
    center,
    ...nearby.map((place) => [place.lat, place.lng]),
  ].filter(([lat, lng]) => Number.isFinite(lat) && Number.isFinite(lng));

  const bounds = getCoordinateBounds(allPoints);
  const project = createStaticMapProjector(bounds, 760, 420);
  const polygons = records.map((record, recordIndex) => {
    const pointsForRecord = record.parsed.coordinates
      .map((point) => project(Number(point.lat), Number(point.lng)))
      .map(([x, y]) => `${x},${y}`)
      .join(" ");
    return `<polygon class="static-kml-polygon${recordIndex ? " secondary" : ""}" points="${pointsForRecord}"></polygon>`;
  }).join("");
  const [markerX, markerY] = project(center[0], center[1]);
  const nearbyMarkup = nearby.map((place) => {
    const [x, y] = project(place.lat, place.lng);
    return `
      <g class="static-nearby-marker">
        <circle cx="${x}" cy="${y}" r="5"></circle>
        <text x="${x + 8}" y="${y - 8}">${escapeHtml(place.name)}</text>
      </g>
    `;
  }).join("");
  const subjectEntries = getKmlMapSubjectEntries(records);
  const subjectMarkup = subjectEntries.map((subject) => {
    const record = records.find((item) => item.index === subject.index);
    const point = record?.parsed?.centroid
      ? [Number(record.parsed.centroid.lat), Number(record.parsed.centroid.lng)]
      : center;
    const [x, y] = project(point[0], point[1]);
    return `
      <g class="static-subject-marker">
        <path d="M ${x} ${y - 30} C ${x - 16} ${y - 30}, ${x - 18} ${y - 8}, ${x} ${y + 10} C ${x + 18} ${y - 8}, ${x + 16} ${y - 30}, ${x} ${y - 30} Z"></path>
        <circle cx="${x}" cy="${y - 17}" r="6"></circle>
        <text x="${x + 14}" y="${y - 24}">${escapeHtml(subject.text)}</text>
      </g>
    `;
  }).join("");

  panel.innerHTML = `
    <svg class="static-map" viewBox="0 0 760 420" role="img" aria-label="KML konum haritası">
      <rect class="static-map-bg" x="0" y="0" width="760" height="420"></rect>
      <g class="static-map-grid">
        ${Array.from({ length: 8 }, (_, index) => `<line x1="${index * 110}" y1="0" x2="${index * 110 - 80}" y2="420"></line>`).join("")}
        ${Array.from({ length: 6 }, (_, index) => `<line x1="0" y1="${index * 90}" x2="760" y2="${index * 90 - 35}"></line>`).join("")}
      </g>
       ${polygons}
      ${nearbyMarkup}
       ${subjectMarkup}
      <text class="static-map-note" x="18" y="398">Yerel harita görünümü - KML sınırı ve seçili konum</text>
    </svg>
  `;
}

function getCoordinateBounds(points) {
  const lats = points.map(([lat]) => lat);
  const lngs = points.map(([, lng]) => lng);
  let minLat = Math.min(...lats);
  let maxLat = Math.max(...lats);
  let minLng = Math.min(...lngs);
  let maxLng = Math.max(...lngs);
  const latPad = Math.max((maxLat - minLat) * 0.35, 0.0008);
  const lngPad = Math.max((maxLng - minLng) * 0.35, 0.0008);
  minLat -= latPad;
  maxLat += latPad;
  minLng -= lngPad;
  maxLng += lngPad;
  return { minLat, maxLat, minLng, maxLng };
}

function createStaticMapProjector(bounds, width, height) {
  return (lat, lng) => {
    const x = 36 + ((lng - bounds.minLng) / Math.max(bounds.maxLng - bounds.minLng, 0.000001)) * (width - 72);
    const y = 36 + ((bounds.maxLat - lat) / Math.max(bounds.maxLat - bounds.minLat, 0.000001)) * (height - 72);
    return [Number(x.toFixed(1)), Number(y.toFixed(1))];
  };
}

function getSelectedNearbyPlaces() {
  const source = state.sourceValues.nearbyPlaces || {};
  const selected = new Set(source.selectedIds || []);
  return getAllNearbyPlacesWithUser(source.places || []).filter((place) => selected.has(place.id));
}

function normalizeMapMode(mode) {
  if (mode === "physical") return "hybrid";
  if (mode === "satellite" || mode === "hybrid" || mode === "street") return mode;
  return "hybrid";
}

function getMapModeOptionsMarkup(selected = state.settings.mapMode) {
  const mode = normalizeMapMode(selected);
  return [
    ["street", "Yol"],
    ["satellite", "Uydu"],
    ["hybrid", "Hibrit"],
  ].map(([value, label]) => `<option value="${value}" ${mode === value ? "selected" : ""}>${label}</option>`).join("");
}

function getMapExportRatioOptionsMarkup(selected = state.settings.mapExportRatio) {
  const value = selected || "4:3";
  return [
    "1:1",
    "3:4",
    "4:3",
    "4:5",
    "5:4",
    "9:16",
    "16:9",
  ].map((ratio) => `<option value="${ratio}" ${value === ratio ? "selected" : ""}>${ratio}</option>`).join("");
}

function getMapExportRatioMenuMarkup(selected = state.settings.mapExportRatio) {
  const value = selected || "4:3";
  return ["1:1", "3:4", "4:3", "4:5", "5:4", "9:16", "16:9"]
    .map((ratio) => `
      <button type="button" role="menuitemradio" aria-checked="${String(value === ratio)}"
        data-map-export-ratio-option="${ratio}">${ratio}</button>`)
    .join("");
}

function getLeafletTileLayer() {
  const mode = normalizeMapMode(state.settings.mapMode);
  const mapTileUrl = (source) => `/map-tiles/${source}/{z}/{x}/{y}`;
  // Hem ekran hem kroki üretimi aynı origin proxy'sini kullanır. Böylece
  // iOS/CORS kaynaklı tile kayıpları ile Word/JPEG krokilerindeki boş altlık
  // sorunu tek noktadan giderilir.
  const streetLayer = window.L.tileLayer(mapTileUrl("osm"), {
    attribution: "© OpenStreetMap",
    maxZoom: 20,
  });
  const imageryLayer = window.L.tileLayer(mapTileUrl("imagery"), {
    attribution: "Tiles © Esri",
    maxZoom: 20,
  });
  // Yol katmanı Esri görüntüsü yüklenemediğinde altta hazır bulunur; böylece
  // telefon bağlantısındaki geçici bir tile hatası haritayı gri bırakmaz.
  const baseLayers = [streetLayer, imageryLayer];
  if (mode === "satellite") {
    return window.L.layerGroup(baseLayers);
  }
  if (mode === "hybrid") {
    return window.L.layerGroup([
      ...baseLayers,
      window.L.tileLayer(mapTileUrl("transport"), {
        attribution: "Road labels © Esri",
        maxZoom: 20,
        opacity: 0.96,
      }),
      window.L.tileLayer(mapTileUrl("places"), {
        attribution: "Place labels © Esri",
        maxZoom: 20,
        opacity: 0.96,
      }),
    ]);
  }

  return streetLayer;
}

function getSavedReportImageConfigs() {
  state.sourceValues.reportImages = state.sourceValues.reportImages || {};
  return state.sourceValues.reportImages;
}

function getLocationMapViewportSnapshot() {
  const leafletSize = leafletMap?.getSize?.();
  if (Number(leafletSize?.x) > 0 && Number(leafletSize?.y) > 0) {
    return { width: Number(leafletSize.x), height: Number(leafletSize.y) };
  }
  const panel = document.querySelector("#kmlMapPanel");
  const rect = panel?.getBoundingClientRect?.();
  if (Number(rect?.width) > 0 && Number(rect?.height) > 0) {
    return { width: Number(rect.width), height: Number(rect.height) };
  }
  return { width: 1120, height: 630 };
}

function getLocationMapLabelScale(config, canvas) {
  const viewport = config?.viewport || getLocationMapViewportSnapshot();
  const widthScale = canvas.width / Math.max(1, Number(viewport.width) || 1120);
  const heightScale = canvas.height / Math.max(1, Number(viewport.height) || 630);
  return Math.max(0.8, Math.min(2.25, Math.min(widthScale, heightScale)));
}

function ensureReportMapImagesForExport() {
  const configs = getSavedReportImageConfigs();
  const missingLocation = !configs.location;
  const missingComparables = !configs.comparables;
  if (!missingLocation && !missingComparables) return { created: [], unavailable: [] };

  let message = "";
  if (missingLocation && missingComparables) {
    message = "Konum ve emsal krokisi kaydedilmedi. Otomatik olarak kaydedilerek devam edilecektir.";
  } else if (missingLocation) {
    message = "Konum krokisi kaydedilmedi. Otomatik olarak kaydedilerek devam edilecektir.";
  } else {
    message = "Emsal krokisi kaydedilmedi. Otomatik olarak kaydedilerek devam edilecektir.";
  }

  const created = [];
  const unavailable = [];
  const size = getMapExportCanvasSize("16:9", 1200);
  const selectedPoint = getSelectedMapPoint();
  const parsed = getComparableSketchExportKml();
  if (missingLocation) {
    if (selectedPoint || parsed?.coordinates?.length) {
      const center = getExportMapCenter(selectedPoint, parsed);
      configs.location = {
        center,
        zoom: getExportMapZoom(center, parsed, size.width, size.height),
        mode: normalizeMapMode(state.settings.mapMode),
        ratio: "16:9",
        labels: true,
        viewport: getLocationMapViewportSnapshot(),
        savedAt: new Date().toISOString(),
        automatic: true,
      };
      created.push("location");
    } else {
      unavailable.push("Konum krokisi");
    }
  }

  if (missingComparables) {
    const subjectPoint = getComparableSubjectPoint();
    const comparablePoints = getComparableSketchPoints();
    if (subjectPoint && comparablePoints.length) {
      const center = getComparableSketchExportCenter(null, subjectPoint, comparablePoints, parsed);
      configs.comparables = {
        center,
        zoom: getComparableSketchExportZoom(null, center, subjectPoint, comparablePoints, parsed, size.width, size.height),
        mode: normalizeMapMode(state.settings.mapMode),
        ratio: "16:9",
        savedAt: new Date().toISOString(),
        automatic: true,
      };
      created.push("comparables");
    } else {
      unavailable.push("Emsal krokisi");
    }
  }

  if (unavailable.length) {
    message += `\n\n${unavailable.join(" ve ")} için gerekli koordinat bilgileri bulunamadığından bu görsel oluşturulamadı.`;
  }
  window.alert(message);
  if (created.length) saveState();
  return { created, unavailable };
}

function saveLocationMapForReport(triggerButton) {
  const selectedPoint = getSelectedMapPoint();
  const parsed = state.sourceValues.kml;
  if (!selectedPoint && !parsed?.coordinates?.length) {
    window.alert("Haritayı rapora kaydetmek için önce KML veya koordinat bilgisi gerekiyor.");
    return;
  }
  const center = getExportMapCenter(selectedPoint, parsed);
  const size = getMapExportCanvasSize("16:9", 1200);
  getSavedReportImageConfigs().location = {
    center,
    zoom: getExportMapZoom(center, parsed, size.width, size.height),
    mode: normalizeMapMode(state.settings.mapMode),
    ratio: "16:9",
    labels: true,
    viewport: getLocationMapViewportSnapshot(),
    savedAt: new Date().toISOString(),
  };
  autosave();
  if (triggerButton) triggerButton.textContent = "Kroki Kaydedildi";
  setMapExportStatus("Konum haritası Word çıktıları için kaydedildi.");
}

async function buildSavedReportImageAssets() {
  const configs = state.sourceValues?.reportImages || {};
  const assets = [];
  if (configs.location) {
    const asset = await buildSavedLocationMapAsset(configs.location);
    if (asset) assets.push(asset);
  }
  if (configs.comparables) {
    const asset = await buildSavedComparableSketchAsset(configs.comparables);
    if (asset) assets.push(asset);
  }
  return assets;
}

// "8. Ekler" fotoğraf modülü (2026-08-13) — template-engine.js'in
// exportDocxTemplate()'i safeCall("getReportPhotoGroupsForExport") ile
// dinamik çağırır (bkz. 147-dinamik-çağrı uyarısı, CLAUDE.md 0.0.285 —
// terser mangle.toplevel:false bu ismi KORUR). window.RaporReportPhotos
// (src/exports/report-photos.js) yüklenmemişse/desteklenmiyorsa boş dizi
// döner — hiçbir zaman sunucuya istek atmaz.
async function getReportPhotoGroupsForExport() {
  if (!window.RaporReportPhotos) return [];
  try {
    return await window.RaporReportPhotos.getPhotoGroupsForExport(state.reportId);
  } catch (error) {
    console.warn("Rapor fotoğrafları export için hazırlanamadı:", error?.message || error);
    return [];
  }
}

async function buildSavedLocationMapAsset(config) {
  const selectedPoint = getSelectedMapPoint();
  const parsed = state.sourceValues.kml;
  const center = Array.isArray(config.center) ? config.center : getExportMapCenter(selectedPoint, parsed);
  const size = getMapExportCanvasSize("16:9", 1200);
  const zoom = Number.isFinite(Number(config.zoom))
    ? Number(config.zoom)
    : getExportMapZoom(center, parsed, size.width, size.height);
  const canvas = document.createElement("canvas");
  canvas.width = size.width;
  canvas.height = size.height;
  const context = canvas.getContext("2d");
  if (!context) return null;
  const mode = normalizeMapMode(config.mode || state.settings.mapMode);
  const topLeft = latLngToWorldPixel(center[0], center[1], zoom);
  topLeft.x -= canvas.width / 2;
  topLeft.y -= canvas.height / 2;
  context.fillStyle = mode === "street" ? "#eef2ef" : "#d8e2df";
  context.fillRect(0, 0, canvas.width, canvas.height);
  await drawExportTiles(context, canvas, topLeft, zoom, "base", mode);
  await drawExportTiles(context, canvas, topLeft, zoom, "labels", mode);
  drawExportKmlPolygons(context, getTitleUnitKmlRecordsForMap(), topLeft, zoom);
  const subjectPoint = selectedPoint || (parsed?.centroid ? [Number(parsed.centroid.lat), Number(parsed.centroid.lng)] : center);
  drawExportMultiLocationLabels(
    context,
    subjectPoint,
    topLeft,
    zoom,
    true,
    getLocationMapLabelScale(config, canvas),
  );
  return buildReportJpegAsset("location", "Konu Taşınmaz Konum Haritası", "report-location-map.jpg", canvas, [
    { label: "Konu Taşınmaz", lat: subjectPoint[0], lng: subjectPoint[1], kind: "subject" },
  ]);
}

async function buildSavedComparableSketchAsset(config) {
  const subjectPoint = getComparableSubjectPoint();
  const comparablePoints = getComparableSketchPoints();
  const kmlRecords = getTitleUnitKmlRecordsForMap();
  const parsed = state.sourceValues.kml;
  if (!subjectPoint && !comparablePoints.length) return null;
  const size = getMapExportCanvasSize("16:9", 1200);
  const center = Array.isArray(config.center)
    ? config.center
    : getComparableSketchExportCenter(null, subjectPoint, comparablePoints, parsed);
  const zoom = Number.isFinite(Number(config.zoom))
    ? Number(config.zoom)
    : getComparableSketchExportZoom(null, center, subjectPoint, comparablePoints, parsed, size.width, size.height);
  const canvas = document.createElement("canvas");
  canvas.width = size.width;
  canvas.height = size.height;
  const context = canvas.getContext("2d");
  if (!context) return null;
  const mode = normalizeMapMode(config.mode || state.settings.mapMode);
  const topLeft = latLngToWorldPixel(center[0], center[1], zoom);
  topLeft.x -= canvas.width / 2;
  topLeft.y -= canvas.height / 2;
  context.fillStyle = mode === "street" ? "#eef2ef" : "#d8e2df";
  context.fillRect(0, 0, canvas.width, canvas.height);
  await drawExportTiles(context, canvas, topLeft, zoom, "base", mode);
  await drawExportTiles(context, canvas, topLeft, zoom, "labels", mode);
  drawExportKmlPolygons(context, getTitleUnitKmlRecordsForMap(), topLeft, zoom);
  drawExportComparableSketch(context, subjectPoint, comparablePoints, topLeft, zoom, parsed);
  const items = [
    ...(subjectPoint ? [{ label: "Konu Taşınmaz", lat: subjectPoint[0], lng: subjectPoint[1], kind: "subject" }] : []),
    ...comparablePoints.map((item) => ({ label: `Emsal ${item.index + 1}`, lat: item.point[0], lng: item.point[1], kind: "comparable" })),
  ];
  return buildReportJpegAsset("comparables", "Emsal Konum Krokisi", "report-comparable-sketch.jpg", canvas, items);
}

function buildReportJpegAsset(key, title, location, canvas, items) {
  const dataUrl = canvas.toDataURL("image/jpeg", 0.82);
  const base64 = String(dataUrl || "").split(",")[1] || "";
  return base64 ? { key, title, location, dataUrl, base64, mimeType: "image/jpeg", items } : null;
}

async function exportMapAsJpeg(triggerButton) {
  const selectedPoint = getSelectedMapPoint();
  const parsed = getComparableSketchExportKml();
  const hasKmlGeometry = Boolean(parsed?.coordinates?.length);
  if (!selectedPoint && !hasKmlGeometry) {
    window.alert("Harita kaydı için önce KML veya koordinat bilgisi gerekiyor.");
    return;
  }

  const originalButtonHtml = triggerButton?.innerHTML;
  if (triggerButton) {
    triggerButton.disabled = true;
    triggerButton.textContent = "JPEG HAZIRLANIYOR...";
  }
  setMapExportStatus("Harita JPEG kaydi hazirlaniyor...");

  const canvas = document.createElement("canvas");
  const exportSize = getMapExportCanvasSize();
  canvas.width = exportSize.width;
  canvas.height = exportSize.height;
  const context = canvas.getContext("2d");
  const center = getExportMapCenter(selectedPoint, parsed);
  const subjectPoint = selectedPoint || (parsed?.centroid ? [Number(parsed.centroid.lat), Number(parsed.centroid.lng)] : center);
  const zoom = getExportMapZoom(center, parsed, canvas.width, canvas.height);
  const topLeft = latLngToWorldPixel(center[0], center[1], zoom);
  topLeft.x -= canvas.width / 2;
  topLeft.y -= canvas.height / 2;

  context.fillStyle = normalizeMapMode(state.settings.mapMode) === "street" ? "#eef2ef" : "#d8e2df";
  context.fillRect(0, 0, canvas.width, canvas.height);
  await drawExportTiles(context, canvas, topLeft, zoom, "base");
  await drawExportTiles(context, canvas, topLeft, zoom, "labels");
  drawExportKmlPolygons(context, getTitleUnitKmlRecordsForMap(), topLeft, zoom);
  drawExportMultiLocationLabels(
    context,
    subjectPoint,
    topLeft,
    zoom,
    true,
    getLocationMapLabelScale(null, canvas),
  );

  try {
    const link = document.createElement("a");
    link.download = `harita-konu-tasinmaz-${dateIsoToTr(new Date().toISOString().slice(0, 10))}.jpg`;
    link.href = canvas.toDataURL("image/jpeg", 0.92);
    document.body.appendChild(link);
    link.click();
    link.remove();
    if (triggerButton) {
      triggerButton.disabled = false;
      triggerButton.innerHTML = originalButtonHtml || "JPG";
    }
    setMapExportStatus("JPEG kaydedildi.");
  } catch (error) {
    try {
      drawExportFallbackBase(context, canvas);
      drawExportKmlPolygons(context, getTitleUnitKmlRecordsForMap(), topLeft, zoom);
      drawExportMultiLocationLabels(
    context,
    subjectPoint,
    topLeft,
    zoom,
    true,
    getLocationMapLabelScale(null, canvas),
  );
      const fallbackLink = document.createElement("a");
      fallbackLink.download = `harita-konu-tasinmaz-${dateIsoToTr(new Date().toISOString().slice(0, 10))}.jpg`;
      fallbackLink.href = canvas.toDataURL("image/jpeg", 0.92);
      document.body.appendChild(fallbackLink);
      fallbackLink.click();
      fallbackLink.remove();
      if (triggerButton) {
        triggerButton.disabled = false;
        triggerButton.innerHTML = originalButtonHtml || "JPG";
      }
      setMapExportStatus("Harita altligi izin vermedi; yedek JPEG kaydedildi.", true);
      return;
    } catch (fallbackError) {
      console.warn("Harita JPEG olarak kaydedilemedi.", fallbackError);
      if (triggerButton) {
        triggerButton.disabled = false;
        triggerButton.innerHTML = originalButtonHtml || "JPG";
      }
      setMapExportStatus("JPEG kaydedilemedi. Haritayi yenileyip tekrar deneyin.", true);
    }
    window.alert("Harita JPEG olarak kaydedilemedi. Harita altlığı bu işlem için izin vermedi.");
  }
}

function setMapExportStatus(message, isWarning = false) {
  const status = document.querySelector("[data-map-export-status]");
  if (!status) return;
  status.textContent = message;
  status.classList.toggle("is-warning", Boolean(isWarning));
}

function getMapExportCanvasSize(ratio = state.settings.mapExportRatio, maxLongSide = 1600) {
  const sizes = {
    "1:1": [1400, 1400],
    "3:4": [1200, 1600],
    "9:16": [1080, 1920],
    "4:5": [1280, 1600],
    "5:4": [1600, 1280],
    "4:3": [1600, 1200],
    "16:9": [1600, 900],
  };
  const [sourceWidth, sourceHeight] = sizes[ratio] || sizes["4:3"];
  const scale = Math.min(1, Math.max(320, Number(maxLongSide) || 1600) / Math.max(sourceWidth, sourceHeight));
  return { width: Math.round(sourceWidth * scale), height: Math.round(sourceHeight * scale) };
}

function drawExportFallbackBase(context, canvas) {
  const pixel = { x: Number.NaN, y: Number.NaN };
  context.save();
  context.clearRect(0, 0, canvas.width, canvas.height);
  context.fillStyle = "#dfe9e4";
  context.fillRect(0, 0, canvas.width, canvas.height);
  context.strokeStyle = "rgba(87, 112, 124, 0.28)";
  context.lineWidth = 12;
  for (let x = -canvas.height; x < canvas.width + canvas.height; x += 180) {
    context.beginPath();
    context.moveTo(x, 0);
    context.lineTo(x + canvas.height * 0.45, canvas.height);
    context.stroke();
  }
  context.strokeStyle = "rgba(87, 112, 124, 0.18)";
  context.lineWidth = 8;
  for (let y = 90; y < canvas.height; y += 170) {
    context.beginPath();
    context.moveTo(0, y);
    context.lineTo(canvas.width, y - 45);
    context.stroke();
  }
  context.fillStyle = "#58717c";
  context.font = "700 24px Arial";
  context.fillText("Harita altligi kayda izin vermedi; KML siniri ve isaretli noktalar kaydedildi.", 38, canvas.height - 42);
  drawExportSubjectCallout(context, pixel.x, pixel.y, "KONU TAŞINMAZ");
  context.restore();
}

function getExportMapCenter(selectedPoint, parsed) {
  if (leafletMap?.getCenter) {
    const center = leafletMap.getCenter();
    return [center.lat, center.lng];
  }
  if (selectedPoint && getTitleUnitCount() <= 1) return selectedPoint;
  if (getTitleUnitCount() > 1 && parsed?.coordinates?.length) {
    const points = parsed.coordinates
      .map((point) => [Number(point.lat), Number(point.lng)])
      .filter(([lat, lng]) => Number.isFinite(lat) && Number.isFinite(lng));
    if (points.length) {
      const lats = points.map(([lat]) => lat);
      const lngs = points.map(([, lng]) => lng);
      return [(Math.min(...lats) + Math.max(...lats)) / 2, (Math.min(...lngs) + Math.max(...lngs)) / 2];
    }
  }
  if (selectedPoint) return selectedPoint;
  if (parsed?.centroid) return [Number(parsed.centroid.lat), Number(parsed.centroid.lng)];
  const first = parsed?.coordinates?.[0];
  return [Number(first?.lat) || 40.1826, Number(first?.lng) || 29.0665];
}

function getExportMapZoom(center, parsed, canvasWidth = 1600, canvasHeight = 1200) {
  if (leafletMap?.getZoom) return leafletMap.getZoom();
  const points = [
    ...(parsed?.coordinates || []).map((point) => [Number(point.lat), Number(point.lng)]),
    ...getMapLabelPlaces().map((place) => [place.lat, place.lng]),
    center,
  ].filter(([lat, lng]) => Number.isFinite(lat) && Number.isFinite(lng));
  if (points.length < 2) return 16;

  for (let zoom = 18; zoom >= 12; zoom -= 1) {
    const projected = points.map(([lat, lng]) => latLngToWorldPixel(lat, lng, zoom));
    const width = Math.max(...projected.map((point) => point.x)) - Math.min(...projected.map((point) => point.x));
    const height = Math.max(...projected.map((point) => point.y)) - Math.min(...projected.map((point) => point.y));
    if (width <= canvasWidth * 0.84 && height <= canvasHeight * 0.78) return zoom;
  }
  return 12;
}

async function drawExportTiles(context, canvas, topLeft, zoom, layerType = "base", mapMode = state.settings.mapMode) {
  const tileSize = 256;
  const minTileX = Math.floor(topLeft.x / tileSize);
  const maxTileX = Math.floor((topLeft.x + canvas.width) / tileSize);
  const minTileY = Math.floor(topLeft.y / tileSize);
  const maxTileY = Math.floor((topLeft.y + canvas.height) / tileSize);
  const jobs = [];

  for (let tileX = minTileX; tileX <= maxTileX; tileX += 1) {
    for (let tileY = minTileY; tileY <= maxTileY; tileY += 1) {
      const urls = getExportTileUrls(tileX, tileY, zoom, layerType, mapMode);
      urls.forEach((url) => {
        jobs.push(loadTileImage(url).then((image) => {
        context.drawImage(
          image,
          Math.round(tileX * tileSize - topLeft.x),
          Math.round(tileY * tileSize - topLeft.y),
          tileSize,
          tileSize,
        );
        }).catch(() => {}));
      });
    }
  }

  await Promise.allSettled(jobs);
}

function getExportTileUrls(tileX, tileY, zoom, layerType = "base", mapMode = state.settings.mapMode) {
  const maxTile = 2 ** zoom;
  const wrappedX = ((tileX % maxTile) + maxTile) % maxTile;
  const y = Math.max(0, Math.min(maxTile - 1, tileY));
  if (layerType === "labels") {
    if (normalizeMapMode(mapMode) !== "hybrid") return [];
    return [
      `/map-tiles/transport/${zoom}/${wrappedX}/${y}`,
      `/map-tiles/places/${zoom}/${wrappedX}/${y}`,
    ];
  }
  if (normalizeMapMode(mapMode) !== "street") {
    return [`/map-tiles/imagery/${zoom}/${wrappedX}/${y}`];
  }
  return [`/map-tiles/osm/${zoom}/${wrappedX}/${y}`];
}

function loadTileImage(url) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    const timer = window.setTimeout(() => {
      reject(new Error("Harita altligi zaman asimina ugradi."));
    }, 4500);
    image.onload = () => {
      window.clearTimeout(timer);
      resolve(image);
    };
    image.onerror = () => {
      window.clearTimeout(timer);
      reject(new Error("Harita altligi yuklenemedi."));
    };
    image.src = url;
  });
}

function drawExportKmlPolygon(context, parsed, topLeft, zoom) {
  const coordinates = parsed?.coordinates || [];
  if (!coordinates.length) return;
  context.save();
  context.beginPath();
  coordinates.forEach((point, index) => {
    const pixel = projectExportPoint(Number(point.lat), Number(point.lng), topLeft, zoom);
    if (index === 0) context.moveTo(pixel.x, pixel.y);
    else context.lineTo(pixel.x, pixel.y);
  });
  context.closePath();
  context.fillStyle = "rgba(217, 37, 37, 0.18)";
  context.strokeStyle = "#d92525";
  context.lineWidth = 5;
  context.fill();
  context.stroke();
  context.restore();
}

function drawExportKmlPolygons(context, records, topLeft, zoom) {
  (records || []).forEach((record) => {
    drawExportKmlPolygon(context, record.parsed, topLeft, zoom);
  });
}

function drawExportPlaces(context, topLeft, zoom) {
  const places = getMapLabelPlaces().filter((place) => Number.isFinite(place.lat) && Number.isFinite(place.lng));

  places.forEach((place) => {
    const pixel = projectExportPoint(place.lat, place.lng, topLeft, zoom);
    drawExportPointLabel(context, pixel.x, pixel.y, place.name, place.category === "arteries" ? "#7f1212" : "#0f6b5d");
  });
}

function isExportPointVisible(pixel, canvas) {
  return Boolean(
    pixel &&
      canvas &&
      Number.isFinite(pixel.x) &&
      Number.isFinite(pixel.y) &&
      pixel.x >= 0 &&
      pixel.y >= 0 &&
      pixel.x <= canvas.width &&
      pixel.y <= canvas.height
  );
}

// Konum haritası JPEG export'unda konu taşınmaz + yakın çevre etiketlerini
// çakışma-önleyen leader etiketleriyle çizer (emsal krokisiyle aynı mantık).
function drawExportMultiLocationLabels(context, fallbackSubjectPoint, topLeft, zoom, includePlaces, labelScale = 1.5) {
  const records = getTitleUnitKmlRecordsForMap();
  const entries = getKmlMapSubjectEntries(records);
  const subjectPoints = entries.map((entry) => {
    const record = records.find((item) => item.index === entry.index);
    if (entry.index === state.activeTitleUnitIndex && fallbackSubjectPoint) {
      return { ...entry, point: fallbackSubjectPoint };
    }
    const centroid = record?.parsed?.centroid;
    if (centroid && Number.isFinite(Number(centroid.lat)) && Number.isFinite(Number(centroid.lng))) {
      return { ...entry, point: [Number(centroid.lat), Number(centroid.lng)] };
    }
    return { ...entry, point: fallbackSubjectPoint };
  }).filter((entry) => Array.isArray(entry.point));

  subjectPoints.forEach((entry) => {
    drawExportLocationLeaderLabels(context, entry.point, topLeft, zoom, false, labelScale, entry.text);
  });
  if (includePlaces) {
    drawExportLocationLeaderLabels(context, null, topLeft, zoom, true, labelScale);
  }
}

function drawExportLocationLeaderLabels(context, subjectPoint, topLeft, zoom, includePlaces, labelScale = 1.5, subjectLabel = "KONU TAŞINMAZ") {
  const scale = Math.max(0.8, Math.min(2.25, Number(labelScale) || 1.5));
  const anchors = [];
  if (subjectPoint && Number.isFinite(subjectPoint[0]) && Number.isFinite(subjectPoint[1])) {
    const pixel = projectExportPoint(subjectPoint[0], subjectPoint[1], topLeft, zoom);
    const font = `800 ${Math.round(12 * scale)}px Arial`;
    context.font = font;
    anchors.push({
      kind: "subject",
      x: pixel.x,
      y: pixel.y,
      text: subjectLabel,
      w: Math.min(context.measureText(subjectLabel).width + 24 * scale, 240 * scale),
      h: 26 * scale,
      font,
      fill: "#c81e1e",
      textColor: "#ffffff",
      borderColor: "#ffffff",
      markerColor: "#c81e1e",
      markerRadius: 7 * scale,
      scale,
      leaderWidth: 1.6 * scale,
      borderWidth: 1.5 * scale,
      cornerRadius: 7 * scale,
      padX: 12 * scale,
    });
  }
  if (includePlaces) {
    getMapLabelPlaces()
      .filter((place) => Number.isFinite(place.lat) && Number.isFinite(place.lng))
      .forEach((place) => {
        const pixel = projectExportPoint(place.lat, place.lng, topLeft, zoom);
        if (!isExportPointVisible(pixel, context.canvas)) return;
        const color = place.category === "arteries" ? "#7f1212" : "#0f6b5d";
        const font = `700 ${Math.round(11 * scale)}px Arial`;
        context.font = font;
        anchors.push({
          kind: "comparable",
          x: pixel.x,
          y: pixel.y,
          text: place.name,
          w: Math.min(context.measureText(place.name).width + 20 * scale, 240 * scale),
          h: 22 * scale,
          font,
          fill: "rgba(255, 255, 255, 0.94)",
          textColor: color,
          borderColor: color,
          markerColor: color,
          markerRadius: 6 * scale,
          scale,
          leaderWidth: 1.6 * scale,
          borderWidth: 1.5 * scale,
          cornerRadius: 7 * scale,
          padX: 10 * scale,
        });
      });
  }
  if (!anchors.length) return;
  layoutSketchLabels(anchors, context.canvas.width, context.canvas.height);
  anchors.forEach((a) => drawSketchLeaderAndMarker(context, a));
  anchors.forEach((a) => drawSketchLabelBox(context, a));
}

function drawExportSubject(context, center, topLeft, zoom) {
  const pixel = projectExportPoint(center[0], center[1], topLeft, zoom);
  drawExportSubjectCallout(context, pixel.x, pixel.y, "KONU TAŞINMAZ");
}

function drawExportSubjectCallout(context, x, y, text) {
  if (!Number.isFinite(x) || !Number.isFinite(y)) return;
  context.save();
  context.font = "900 30px Arial";
  const paddingX = 20;
  const paddingY = 12;
  const width = Math.min(context.measureText(text).width + paddingX * 2, 430);
  const height = 58;
  const labelX = Math.max(18, Math.min(x + 42, context.canvas.width - width - 18));
  const labelY = Math.max(18, Math.min(y - height - 28, context.canvas.height - height - 18));
  const arrowBaseX = Math.max(labelX + 24, Math.min(x + 22, labelX + width - 24));

  context.fillStyle = "#c81e1e";
  context.strokeStyle = "#ffffff";
  context.lineWidth = 5;
  context.beginPath();
  context.roundRect(labelX, labelY, width, height, 12);
  context.fill();
  context.stroke();

  context.beginPath();
  context.moveTo(arrowBaseX - 18, labelY + height - 2);
  context.lineTo(arrowBaseX + 18, labelY + height - 2);
  context.lineTo(x, y - 5);
  context.closePath();
  context.fill();
  context.stroke();

  context.fillStyle = "#ffffff";
  context.fillText(text, labelX + paddingX, labelY + paddingY + 27, width - paddingX * 2);
  context.restore();
}

function drawExportPointLabel(context, x, y, text, color) {
  if (/^KONU/i.test(String(text || ""))) return;
  context.save();
  context.font = "700 22px Arial";
  const paddingX = 12;
  const paddingY = 8;
  const width = Math.min(context.measureText(text).width + paddingX * 2, 420);
  const height = 42;
  const labelX = Math.max(12, Math.min(x + 12, context.canvas.width - width - 12));
  const labelY = Math.max(12, Math.min(y - height - 12, context.canvas.height - height - 12));

  context.fillStyle = "rgba(255, 255, 255, 0.92)";
  context.strokeStyle = color;
  context.lineWidth = 2;
  context.beginPath();
  context.roundRect(labelX, labelY, width, height, 10);
  context.fill();
  context.stroke();
  context.fillStyle = color;
  context.fillText(text, labelX + paddingX, labelY + paddingY + 20, width - paddingX * 2);

  context.fillStyle = color;
  context.beginPath();
  context.arc(x, y, 10, 0, Math.PI * 2);
  context.fill();
  context.restore();
}

function latLngToWorldPixel(lat, lng, zoom) {
  const sinLat = Math.sin((Math.max(Math.min(lat, 85.05112878), -85.05112878) * Math.PI) / 180);
  const scale = 256 * (2 ** zoom);
  return {
    x: ((lng + 180) / 360) * scale,
    y: (0.5 - Math.log((1 + sinLat) / (1 - sinLat)) / (4 * Math.PI)) * scale,
  };
}

function projectExportPoint(lat, lng, topLeft, zoom) {
  const pixel = latLngToWorldPixel(lat, lng, zoom);
  return {
    x: pixel.x - topLeft.x,
    y: pixel.y - topLeft.y,
  };
}

function getSelectedMapPoint() {
  const lat = Number.parseFloat(String(state.fields.latitude || "").replace(",", "."));
  const lng = Number.parseFloat(String(state.fields.longitude || "").replace(",", "."));
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  return [lat, lng];
}

function updateSelectedCoordinates(lat, lng) {
  const formattedLat = Number(lat).toFixed(6);
  const formattedLng = Number(lng).toFixed(6);
  state.fields.latitude = formattedLat;
  state.fields.longitude = formattedLng;

  const latInput = document.querySelector('[data-field="latitude"]');
  const lngInput = document.querySelector('[data-field="longitude"]');
  if (latInput) latInput.value = formattedLat;
  if (lngInput) lngInput.value = formattedLng;

  autosave();
  applyLocalNeighborhoodForCurrentLocation({ silent: true }).then((changed) => {
    if (!changed) return;
    syncRenderedAddressFields();
    autosave();
    renderValidation();
    updateStatus();
  }).catch(() => {});
  fetchAddressLookupDebounced();
  renderValidation();
  updateStatus();
}

function renderKmlMapFallback(message) {
  const placeholder = document.querySelector("#kmlMapPlaceholder");
  const panel = document.querySelector("#kmlMapPanel");
  const parsed = state.sourceValues.kml;
  if (!panel) return;

  if (!placeholder) {
    panel.innerHTML = `<div class="map-placeholder" id="kmlMapPlaceholder"></div>`;
  }

  const target = document.querySelector("#kmlMapPlaceholder");
  if (!target) return;

  if (message) {
    target.textContent = message;
    return;
  }

  if (!parsed?.coordinates?.length) {
    target.textContent = "KML yüklendiğinde harita burada OpenStreetMap altlığıyla gösterilecek.";
    return;
  }

  target.innerHTML = `
    <strong>KML okundu</strong>
    <span>${parsed.coordinates.length} koordinat bulundu.</span>
    <span>Merkez: ${parsed.centroid?.lat || "-"}, ${parsed.centroid?.lng || "-"}</span>
    <span>Pafta: ${parsed.fields?.sheetNo || "-"}</span>
  `;
}

function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function createPlaceholderDefinitionsPanel() {
  ensureLegacyPlaceholderRowsLoaded();

  const wrapper = document.createElement("div");
  wrapper.className = "placeholder-manager";

  const allRows = collectPlaceholderDefinitions();
  const categories = [...new Set(allRows.map((row) => row.category).filter(Boolean))];
  const sources = [...new Set(allRows.map((row) => row.source).filter(Boolean))];

  const toolbar = document.createElement("div");
  toolbar.className = "placeholder-toolbar";

  const searchField = createPlaceholderFilterField("Arama", "placeholderSearch");
  const searchInput = searchField.querySelector("input");
  searchInput.placeholder = "Placeholder, başlık, bölüm veya değer ara";

  const categoryField = createPlaceholderSelectField("Kategori", "placeholderCategory", ["", ...categories]);
  const categorySelect = categoryField.querySelector("select");

  const sourceField = createPlaceholderSelectField("Kaynak", "placeholderSource", ["", ...sources]);
  const sourceSelect = sourceField.querySelector("select");

  toolbar.append(searchField, categoryField, sourceField);

  const summary = document.createElement("div");
  summary.className = "placeholder-summary";

  const tableWrap = document.createElement("div");
  tableWrap.className = "placeholder-table-wrap";

  const renderRows = () => {
    const query = normalizeSearchText(searchInput.value);
    const category = categorySelect.value;
    const source = sourceSelect.value;
    const rows = collectPlaceholderDefinitions().filter((row) => {
      if (category && row.category !== category) return false;
      if (source && row.source !== source) return false;
      if (!query) return true;
      return normalizeSearchText([
        row.category,
        row.token,
        row.title,
        row.type,
        row.source,
        row.value,
        row.reference,
      ].join(" ")).includes(query);
    });

    summary.textContent = `${rows.length} placeholder gösteriliyor. Excel kaynağı: ${
      legacyPlaceholderRowsLoaded ? `${legacyPlaceholderRows.length} kayıt` : "yükleniyor"
    }.`;
    tableWrap.replaceChildren(createPlaceholderTable(rows));
  };

  [searchInput, categorySelect, sourceSelect].forEach((control) => {
    control.addEventListener("input", renderRows);
    control.addEventListener("change", renderRows);
  });

  wrapper.append(createUserDefaultSelectionsPanel(), toolbar, summary, tableWrap);
  renderRows();
  return wrapper;
}

function createUserDefaultSelectionsPanel() {
  const panel = document.createElement("div");
  panel.className = "placeholder-defaults-panel";

  const head = document.createElement("div");
  head.className = "placeholder-defaults-head";
  const title = document.createElement("div");
  title.innerHTML = `
    <strong>Kullanıcı Varsayılanları</strong>
    <span>Bu ayarlar sadece boş kalan ve belge/KML/PDF tarafından doldurulmamış kullanıcı alanlarına uygulanır.</span>
  `;
  const resetAllButton = document.createElement("button");
  resetAllButton.type = "button";
  resetAllButton.className = "mini-button";
  resetAllButton.textContent = "Tümünü temizle";
  resetAllButton.addEventListener("click", () => {
    state.settings.userDefaults = {};
    saveUserDefaults(state.settings.userDefaults);
    autosave();
    renderSection();
  });
  head.append(title, resetAllButton);

  const rows = collectUserDefaultEligibleFields();
  const tableWrap = document.createElement("div");
  tableWrap.className = "placeholder-defaults-table-wrap";
  const table = document.createElement("table");
  table.className = "placeholder-defaults-table";
  table.innerHTML = `
    <thead>
      <tr>
        <th>Bölüm</th>
        <th>Alan</th>
        <th>Varsayılan Değer</th>
        <th>Durum</th>
        <th>İşlem</th>
      </tr>
    </thead>
  `;

  const tbody = document.createElement("tbody");
  rows.forEach(({ section, field }) => {
    const tr = document.createElement("tr");
    const sourceOwned = isFieldKeyOwnedBySource(field.key);
    tr.append(
      createPlaceholderCell(section.title),
      createPlaceholderCell(field.label || field.key),
    );

    const controlCell = document.createElement("td");
    controlCell.append(createUserDefaultControl(field));

    const statusCell = document.createElement("td");
    statusCell.textContent = sourceOwned
      ? "Bu işte belge verisi korunur"
      : state.fields[field.key]
        ? "Bu işte alan dolu"
        : "Boş alanlara uygulanır";

    const actionCell = document.createElement("td");
    const clearButton = document.createElement("button");
    clearButton.type = "button";
    clearButton.className = "mini-button placeholder-copy-button";
    clearButton.textContent = "Temizle";
    clearButton.addEventListener("click", () => {
      delete state.settings.userDefaults[field.key];
      saveUserDefaults(state.settings.userDefaults);
      autosave();
      renderSection();
    });
    actionCell.append(clearButton);

    tr.append(controlCell, statusCell, actionCell);
    tbody.append(tr);
  });

  if (!rows.length) {
    const emptyRow = document.createElement("tr");
    const emptyCell = document.createElement("td");
    emptyCell.colSpan = 5;
    emptyCell.className = "placeholder-empty";
    emptyCell.textContent = "Varsayılan atanabilecek kullanıcı alanı bulunamadı.";
    emptyRow.append(emptyCell);
    tbody.append(emptyRow);
  }

  table.append(tbody);
  tableWrap.append(table);
  panel.append(head, tableWrap);
  return panel;
}

function collectUserDefaultEligibleFields() {
  const eligibleTypes = new Set(["select", "multiCheckbox", "conditionalYesNo", "checkbox"]);
  const rows = [];
  sections.forEach((section) => {
    if (section.id === "placeholders") return;
    (section.fields || []).forEach((field) => {
      if (!field?.key || !eligibleTypes.has(field.type)) return;
      if (!isUserDefaultEligibleField(field)) return;
      if (!getUserDefaultFieldOptions(field).length) return;
      rows.push({ section, field });
    });
  });
  return rows;
}

function isUserDefaultEligibleField(field) {
  if (field.autoFill || field.hidden || field.computed) return false;
  return !sourceGeneratedDefaultExcludedKeys.has(field.key);
}

function getUserDefaultFieldOptions(field) {
  if (field.type === "conditionalYesNo") return ["Evet", "Hayır"];
  if (field.type === "checkbox") return [field.checkedValue || "Evet", field.uncheckedValue || "Hayır"];
  return getFieldOptions(field).filter(Boolean);
}

function createUserDefaultControl(field) {
  if (field.type === "multiCheckbox") {
    return createUserDefaultMultiCheckboxControl(field);
  }

  const select = document.createElement("select");
  select.className = "placeholder-default-control";
  const current = getUserDefaultValueForField(field);
  ["", ...getUserDefaultFieldOptions(field)].forEach((option) => {
    const item = document.createElement("option");
    item.value = option;
    item.textContent = option || "Varsayılan yok";
    select.append(item);
  });
  select.value = current;
  select.addEventListener("change", () => updateUserDefaultField(field, select.value));
  return select;
}

function createUserDefaultMultiCheckboxControl(field) {
  const wrapper = document.createElement("div");
  wrapper.className = "placeholder-default-checks";
  const selected = new Set(parseMultiValue(getUserDefaultValueForField(field)));
  getUserDefaultFieldOptions(field).forEach((option) => {
    const label = document.createElement("label");
    label.className = "checkbox-row";
    const input = document.createElement("input");
    input.type = "checkbox";
    input.value = option;
    input.checked = selected.has(option);
    input.addEventListener("change", () => {
      const values = [...wrapper.querySelectorAll("input[type='checkbox']:checked")].map((item) => item.value);
      updateUserDefaultField(field, values.join(", "));
    });
    label.append(input, createSpan(option));
    wrapper.append(label);
  });
  return wrapper;
}

function parseMultiValue(value) {
  return String(value || "")
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

function updateUserDefaultField(field, value) {
  state.settings = state.settings || {};
  state.settings.userDefaults = state.settings.userDefaults || {};
  if (value) {
    state.settings.userDefaults[field.key] = value;
  } else {
    delete state.settings.userDefaults[field.key];
  }
  saveUserDefaults(state.settings.userDefaults);
  applyUserDefaultToField(field, state);
  autosave();
  renderValidation();
  updateStatus();
}

function createPlaceholderFilterField(labelText, inputName) {
  const label = document.createElement("label");
  label.className = "field placeholder-filter-field";
  label.append(createSpan(labelText));
  const input = document.createElement("input");
  input.type = "search";
  input.name = inputName;
  label.append(input);
  return label;
}

function createPlaceholderSelectField(labelText, inputName, options) {
  const label = document.createElement("label");
  label.className = "field placeholder-filter-field";
  label.append(createSpan(labelText));
  const select = document.createElement("select");
  select.name = inputName;
  options.forEach((option) => {
    const item = document.createElement("option");
    item.value = option;
    item.textContent = option || "Tümü";
    select.append(item);
  });
  label.append(select);
  return label;
}

function createPlaceholderTable(rows) {
  const table = document.createElement("table");
  table.className = "placeholder-table";

  const thead = document.createElement("thead");
  thead.innerHTML = `
    <tr>
      <th>Placeholder</th>
      <th>Başlık</th>
      <th>Tür</th>
      <th>Kaynak</th>
      <th>Mevcut Değer</th>
      <th>İşlem</th>
    </tr>
  `;
  table.append(thead);

  const tbody = document.createElement("tbody");
  let currentCategory = "";
  rows.forEach((row) => {
    if (row.category !== currentCategory) {
      currentCategory = row.category;
      const groupRow = document.createElement("tr");
      groupRow.className = "placeholder-group-row";
      const groupCell = document.createElement("td");
      groupCell.colSpan = 6;
      groupCell.textContent = currentCategory || "Genel";
      groupRow.append(groupCell);
      tbody.append(groupRow);
    }

    const tr = document.createElement("tr");
    tr.append(
      createPlaceholderCell(row.token, "placeholder-token"),
      createPlaceholderCell(row.title),
      createPlaceholderCell(row.type),
      createPlaceholderCell(row.source),
      createPlaceholderCell(row.value || "-", "placeholder-value"),
    );
    const actionCell = document.createElement("td");
    const copyButton = document.createElement("button");
    copyButton.type = "button";
    copyButton.className = "mini-button placeholder-copy-button";
    copyButton.textContent = "Kopyala";
    copyButton.addEventListener("click", () => copyPlaceholderToken(row.token, copyButton));
    actionCell.append(copyButton);
    tr.append(actionCell);
    tbody.append(tr);
  });

  if (!rows.length) {
    const emptyRow = document.createElement("tr");
    const emptyCell = document.createElement("td");
    emptyCell.colSpan = 6;
    emptyCell.className = "placeholder-empty";
    emptyCell.textContent = "Kayıt bulunamadı.";
    emptyRow.append(emptyCell);
    tbody.append(emptyRow);
  }

  table.append(tbody);
  return table;
}

function createPlaceholderCell(value, className = "") {
  const cell = document.createElement("td");
  if (className) cell.className = className;
  cell.textContent = value;
  return cell;
}

function copyPlaceholderToken(token, button) {
  const done = () => {
    const previousText = button.textContent;
    button.textContent = "Kopyalandı";
    setTimeout(() => {
      button.textContent = previousText;
    }, 1100);
  };
  if (navigator.clipboard?.writeText) {
    navigator.clipboard.writeText(token).then(done).catch(done);
  } else {
    done();
  }
}

function createHalkbankRiskCodesPanel() {
  const panel = document.createElement("div");
  panel.className = "halkbank-risk-panel";

  if (!globalThis.HalkbankRiskRules) {
    const warning = document.createElement("p");
    warning.className = "hint-text";
    warning.textContent = "Halkbank risk kodu motoru yüklenemedi.";
    panel.append(warning);
    return panel;
  }

  const result = refreshHalkbankRiskCodesFromCurrentState();
  panel.append(createHalkbankRiskSummary(result));
  panel.append(createHalkbankRiskTable(result.selected));
  panel.append(createHalkbankRiskDisabledList());
  panel.append(createHalkbankRiskManualEditor());
  panel.append(createHalkbankRiskReportTextBox(result.selected));
  return panel;
}

function refreshHalkbankRiskCodesFromCurrentState() {
  const result = globalThis.HalkbankRiskRules.calculateHalkbankRiskCodes(getHalkbankRiskInput());
  state.fields.halkbankRiskSelectedCodes = result.selected.map((item) => item.code).join(", ");
  state.fields.halkbankRiskReportText = globalThis.HalkbankRiskRules.formatHalkbankRiskReportText(result.selected);
  return result;
}

function getHalkbankRiskInput() {
  return {
    fields: state.fields || {},
    tables: state.tables || {},
    disabledCodes: parseHalkbankRiskDisabledCodes(),
    manualCodes: getHalkbankRiskManualRows(),
  };
}

function parseHalkbankRiskDisabledCodes() {
  return String(state.fields.halkbankRiskDisabledCodes || "")
    .split(",")
    .map((code) => code.trim().toUpperCase())
    .filter(Boolean);
}

function setHalkbankRiskDisabledCodes(codes = []) {
  const sorted = globalThis.HalkbankRiskRules?.sortHalkbankRiskCodes
    ? globalThis.HalkbankRiskRules.sortHalkbankRiskCodes(codes)
    : codes;
  state.fields.halkbankRiskDisabledCodes = sorted.join(", ");
}

function getHalkbankRiskManualRows() {
  return Array.isArray(state.tables.halkbankRiskManual)
    ? state.tables.halkbankRiskManual.filter((row) => String(row?.code || "").trim())
    : [];
}

function setHalkbankRiskManualRows(rows = []) {
  state.tables.halkbankRiskManual = rows
    .map((row) => ({
      code: String(row?.code || "").trim().toUpperCase(),
      reason: normalizeReportDescriptionText(row?.reason || "").trim(),
    }))
    .filter((row) => row.code);
}

function createHalkbankRiskSummary(result) {
  const summary = document.createElement("div");
  summary.className = "halkbank-risk-summary";
  const values = [
    ["Seçilen kod", result.selected.length],
    ["Manuel kod", getHalkbankRiskManualRows().length],
    ["Pasif kod", parseHalkbankRiskDisabledCodes().length],
  ];
  values.forEach(([label, value]) => {
    const item = document.createElement("article");
    const small = document.createElement("span");
    small.textContent = label;
    const strong = document.createElement("strong");
    strong.textContent = String(value);
    item.append(small, strong);
    summary.append(item);
  });
  return summary;
}

function createHalkbankRiskTable(items = []) {
  const wrapper = document.createElement("div");
  wrapper.className = "halkbank-risk-table-wrap";
  const table = document.createElement("table");
  table.className = "halkbank-risk-table";
  table.innerHTML = `
    <thead>
      <tr>
        <th>Kod</th>
        <th>Konu</th>
        <th>Durum</th>
        <th>Değer Tipi</th>
        <th>Seçilme Nedeni</th>
        <th>İşlem</th>
      </tr>
    </thead>
  `;
  const tbody = document.createElement("tbody");
  if (!items.length) {
    const row = document.createElement("tr");
    const cell = document.createElement("td");
    cell.colSpan = 6;
    cell.className = "empty-cell";
    cell.textContent = "Seçilen risk kodu bulunmuyor.";
    row.append(cell);
    tbody.append(row);
  } else {
    items.forEach((item) => {
      const row = document.createElement("tr");
      row.append(
        createHalkbankRiskCell(item.code, "risk-code"),
        createHalkbankRiskCell(item.topic || "-"),
        createHalkbankRiskCell(item.status || "-"),
        createHalkbankRiskCell(item.valueType || "-"),
        createHalkbankRiskCell(item.reason || "-"),
        createHalkbankRiskActionCell(item),
      );
      tbody.append(row);
    });
  }
  table.append(tbody);
  wrapper.append(table);
  return wrapper;
}

function createHalkbankRiskCell(text, className = "") {
  const cell = document.createElement("td");
  if (className) cell.className = className;
  cell.textContent = text;
  return cell;
}

function createHalkbankRiskActionCell(item) {
  const cell = document.createElement("td");
  const button = document.createElement("button");
  button.type = "button";
  button.className = "halkbank-risk-passive-button";
  button.textContent = "Pasife al";
  button.addEventListener("click", () => {
    const disabled = new Set(parseHalkbankRiskDisabledCodes());
    disabled.add(item.code);
    setHalkbankRiskDisabledCodes(Array.from(disabled));
    saveState();
    renderSection();
  });
  cell.append(button);
  return cell;
}

function createHalkbankRiskDisabledList() {
  const codes = parseHalkbankRiskDisabledCodes();
  const box = document.createElement("div");
  box.className = "halkbank-risk-disabled-list";
  const title = document.createElement("h4");
  title.textContent = "Pasife Alınan Kodlar";
  box.append(title);
  if (!codes.length) {
    const empty = document.createElement("p");
    empty.className = "hint-text";
    empty.textContent = "Pasife alınan kod yok.";
    box.append(empty);
    return box;
  }
  codes.forEach((code) => {
    const chip = document.createElement("button");
    chip.type = "button";
    chip.textContent = `${code} geri al`;
    chip.addEventListener("click", () => {
      setHalkbankRiskDisabledCodes(codes.filter((item) => item !== code));
      saveState();
      renderSection();
    });
    box.append(chip);
  });
  return box;
}

function createHalkbankRiskManualEditor() {
  const box = document.createElement("div");
  box.className = "halkbank-risk-manual";
  const title = document.createElement("h4");
  title.textContent = "Manuel Risk Kodu";
  const controls = document.createElement("div");
  controls.className = "halkbank-risk-manual-controls";
  const select = document.createElement("select");
  select.append(new Option("Kod seçiniz", ""));
  getHalkbankRiskDefinitions().forEach((row) => {
    select.append(new Option(`${row.code} - ${row.status || row.topic || ""}`.trim(), row.code));
  });
  const reason = document.createElement("input");
  reason.type = "text";
  reason.placeholder = "Manuel ekleme nedeni";
  const addButton = document.createElement("button");
  addButton.type = "button";
  addButton.className = "secondary-button";
  addButton.textContent = "Ekle";
  addButton.addEventListener("click", () => {
    if (!select.value) return;
    const rows = getHalkbankRiskManualRows();
    if (!rows.some((row) => row.code === select.value)) {
      rows.push({ code: select.value, reason: reason.value || "Kullanıcı tarafından manuel eklendi." });
      setHalkbankRiskManualRows(rows);
    }
    reason.value = "";
    select.value = "";
    saveState();
    renderSection();
  });
  controls.append(select, reason, addButton);
  box.append(title, controls, createHalkbankRiskManualList());
  return box;
}

function createHalkbankRiskManualList() {
  const rows = getHalkbankRiskManualRows();
  const list = document.createElement("div");
  list.className = "halkbank-risk-manual-list";
  if (!rows.length) {
    const empty = document.createElement("p");
    empty.className = "hint-text";
    empty.textContent = "Manuel eklenen risk kodu yok.";
    list.append(empty);
    return list;
  }
  rows.forEach((row, index) => {
    const item = document.createElement("article");
    const text = document.createElement("span");
    text.textContent = `${row.code} - ${row.reason || "Manuel"}`;
    const remove = document.createElement("button");
    remove.type = "button";
    remove.textContent = "Kaldır";
    remove.addEventListener("click", () => {
      const nextRows = getHalkbankRiskManualRows();
      nextRows.splice(index, 1);
      setHalkbankRiskManualRows(nextRows);
      saveState();
      renderSection();
    });
    item.append(text, remove);
    list.append(item);
  });
  return list;
}

function createHalkbankRiskReportTextBox(items = []) {
  const box = document.createElement("label");
  box.className = "field field-wide halkbank-risk-report-text";
  const title = document.createElement("span");
  title.textContent = "Rapor Açıklaması";
  const textarea = document.createElement("textarea");
  textarea.readOnly = true;
  textarea.className = "is-readonly";
  textarea.value = globalThis.HalkbankRiskRules.formatHalkbankRiskReportText(items);
  box.append(title, textarea, createFieldCopyButton());
  return box;
}

function getHalkbankRiskDefinitions() {
  const rows = Array.isArray(globalThis.HalkbankRiskData) ? globalThis.HalkbankRiskData : [];
  const seen = new Set();
  return rows
    .filter((row) => {
      const code = String(row?.code || "").trim().toUpperCase();
      if (!code || seen.has(code)) return false;
      seen.add(code);
      return true;
    })
    .sort((a, b) => globalThis.HalkbankRiskRules.compareRiskCodes(a.code, b.code));
}

function buildHalkbankRiskCodesText() {
  if (!globalThis.HalkbankRiskRules) return "";
  const result = globalThis.HalkbankRiskRules.calculateHalkbankRiskCodes(getHalkbankRiskInput());
  return globalThis.HalkbankRiskRules.formatHalkbankRiskReportText(result.selected);
}

function buildHalkbankRiskCodesTableText() {
  if (!globalThis.HalkbankRiskRules) return "";
  const result = globalThis.HalkbankRiskRules.calculateHalkbankRiskCodes(getHalkbankRiskInput());
  return result.selected
    .map((item) => `${item.code}\t${item.status || ""}\t${item.reason || ""}`)
    .join("\n");
}

function createValueFactorsPanel() {
  const panel = document.createElement("div");
  panel.className = "value-factors-panel";
  if (!globalThis.ValueFactorsRules) {
    const warning = document.createElement("p");
    warning.className = "hint-text";
    warning.textContent = "Değeri etkileyen faktör motoru yüklenemedi.";
    panel.append(warning);
    return panel;
  }
  const result = refreshValueFactorsFromCurrentState();
  panel.append(createValueFactorsSummary(result));
  panel.append(createValueFactorsGroup("Olumlu Özellikler", "positive", result.positive));
  panel.append(createValueFactorsGroup("Olumsuz Özellikler", "negative", result.negative));
  // Kullanıcı talebi: "Değere etki eden faktörlerde Rapor Metni kısmını
  // gizle" — state.fields.valueFactorsReportText yukarıdaki
  // refreshValueFactorsFromCurrentState() ile zaten hesaplandı, yalnızca
  // görünürlük atlanıyor.
  if (canViewSensitiveContent()) panel.append(createValueFactorsReportTextBox(result));
  return panel;
}

function refreshValueFactorsFromCurrentState() {
  const result = globalThis.ValueFactorsRules.calculateValueFactors(getValueFactorsInput());
  state.fields.valueFactorsPositiveText = formatValueFactorsList(result.positive);
  state.fields.valueFactorsNegativeText = formatValueFactorsList(result.negative);
  state.fields.valueFactorsReportText = globalThis.ValueFactorsRules.formatValueFactorsText(result);
  return result;
}

function getValueFactorsInput() {
  refreshHalkbankRiskCodesFromCurrentState();
  return {
    fields: state.fields || {},
    tables: {
      unitFloors: Array.isArray(state.tables.unitFloors) ? state.tables.unitFloors : [],
      documents: Array.isArray(state.tables.documents)
        ? state.tables.documents.map(normalizeReviewedDocumentRow)
        : [],
    },
    disabledIds: parseValueFactorsDisabledIds(),
    manualPositive: getValueFactorsManualRows("positive"),
    manualNegative: getValueFactorsManualRows("negative"),
  };
}

function parseValueFactorsDisabledIds() {
  return String(state.fields.valueFactorsDisabledIds || "")
    .split(",")
    .map((id) => id.trim())
    .filter(Boolean);
}

function setValueFactorsDisabledIds(ids = []) {
  state.fields.valueFactorsDisabledIds = Array.from(new Set(ids.filter(Boolean))).join(", ");
}

function getValueFactorsManualRows(kind) {
  const key = kind === "positive" ? "valueFactorsManualPositive" : "valueFactorsManualNegative";
  return Array.isArray(state.tables[key])
    ? state.tables[key].filter((row) => String(row?.text || "").trim())
    : [];
}

function setValueFactorsManualRows(kind, rows = []) {
  const key = kind === "positive" ? "valueFactorsManualPositive" : "valueFactorsManualNegative";
  state.tables[key] = rows
    .map((row) => ({ text: normalizeReportDescriptionText(row?.text || "").trim() }))
    .filter((row) => row.text);
}

function createValueFactorsSummary(result) {
  const summary = document.createElement("div");
  summary.className = "value-factors-summary";
  [
    ["Olumlu", result.positive.length],
    ["Olumsuz", result.negative.length],
    ["Pasif", parseValueFactorsDisabledIds().length],
  ].forEach(([label, value]) => {
    const item = document.createElement("article");
    const small = document.createElement("span");
    small.textContent = label;
    const strong = document.createElement("strong");
    strong.textContent = String(value);
    item.append(small, strong);
    summary.append(item);
  });
  return summary;
}

function createValueFactorsGroup(title, kind, items = []) {
  const section = document.createElement("div");
  section.className = `value-factors-group value-factors-${kind}`;
  const head = document.createElement("div");
  head.className = "value-factors-group-head";
  const h4 = document.createElement("h4");
  h4.textContent = title;
  head.append(h4);
  section.append(head, createValueFactorsTable(items), createValueFactorsManualEditor(kind));
  return section;
}

function createValueFactorsTable(items = []) {
  const wrapper = document.createElement("div");
  wrapper.className = "value-factors-table-wrap";
  const table = document.createElement("table");
  table.className = "value-factors-table";
  table.innerHTML = `
    <thead>
      <tr>
        <th>Özellik</th>
        <th>Kaynak</th>
        <th>Tür</th>
        <th>İşlem</th>
      </tr>
    </thead>
  `;
  const tbody = document.createElement("tbody");
  if (!items.length) {
    const row = document.createElement("tr");
    const cell = document.createElement("td");
    cell.colSpan = 4;
    cell.className = "empty-cell";
    cell.textContent = "Kayıt bulunmuyor.";
    row.append(cell);
    tbody.append(row);
  } else {
    items.forEach((item) => {
      const row = document.createElement("tr");
      row.append(
        createValueFactorsCell(item.text),
        createValueFactorsCell(item.sourceLabel || "-"),
        createValueFactorsCell(item.source === "manual" ? "Manuel" : "Otomatik"),
        createValueFactorsActionCell(item),
      );
      tbody.append(row);
    });
  }
  table.append(tbody);
  wrapper.append(table);
  return wrapper;
}

function createValueFactorsCell(text) {
  const cell = document.createElement("td");
  cell.textContent = text || "-";
  return cell;
}

function createValueFactorsActionCell(item) {
  const cell = document.createElement("td");
  const button = document.createElement("button");
  button.type = "button";
  button.className = "value-factor-passive-button";
  button.textContent = item.source === "manual" ? "Kaldır" : "Pasife al";
  button.addEventListener("click", () => {
    if (item.source === "manual") {
      const rows = getValueFactorsManualRows(item.kind).filter((row) => row.text !== item.text);
      setValueFactorsManualRows(item.kind, rows);
    } else {
      const disabled = new Set(parseValueFactorsDisabledIds());
      disabled.add(item.id);
      setValueFactorsDisabledIds(Array.from(disabled));
    }
    saveState();
    renderSection();
  });
  cell.append(button);
  return cell;
}

function createValueFactorsManualEditor(kind) {
  const box = document.createElement("div");
  box.className = "value-factors-manual";
  const input = document.createElement("input");
  input.type = "text";
  input.placeholder = kind === "positive" ? "Olumlu özellik ekle" : "Olumsuz özellik ekle";
  const button = document.createElement("button");
  button.type = "button";
  button.className = "secondary-button";
  button.textContent = "Ekle";
  button.addEventListener("click", () => {
    const text = normalizeReportDescriptionText(input.value || "").trim();
    if (!text) return;
    const rows = getValueFactorsManualRows(kind);
    rows.push({ text });
    setValueFactorsManualRows(kind, rows);
    saveState();
    renderSection();
  });
  box.append(input, button, createValueFactorsDisabledList());
  return box;
}

function createValueFactorsDisabledList() {
  const ids = parseValueFactorsDisabledIds();
  const box = document.createElement("div");
  box.className = "value-factors-disabled-list";
  if (!ids.length) return box;
  ids.forEach((id) => {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = "Pasifi geri al";
    button.title = id;
    button.addEventListener("click", () => {
      setValueFactorsDisabledIds(ids.filter((item) => item !== id));
      saveState();
      renderSection();
    });
    box.append(button);
  });
  return box;
}

function createValueFactorsReportTextBox(result) {
  const box = document.createElement("label");
  box.className = "field field-wide value-factors-report-text";
  const title = document.createElement("span");
  title.textContent = "Rapor Metni";
  const textarea = document.createElement("textarea");
  textarea.readOnly = true;
  textarea.className = "is-readonly";
  textarea.value = globalThis.ValueFactorsRules.formatValueFactorsText(result);
  box.append(title, textarea, createFieldCopyButton());
  return box;
}

function buildValueFactorsPositiveText() {
  if (!globalThis.ValueFactorsRules) return "";
  const result = globalThis.ValueFactorsRules.calculateValueFactors(getValueFactorsInput());
  return formatValueFactorsList(result.positive);
}

function buildValueFactorsNegativeText() {
  if (!globalThis.ValueFactorsRules) return "";
  const result = globalThis.ValueFactorsRules.calculateValueFactors(getValueFactorsInput());
  return formatValueFactorsList(result.negative);
}

function buildValueFactorsReportText() {
  if (!globalThis.ValueFactorsRules) return "";
  const result = globalThis.ValueFactorsRules.calculateValueFactors(getValueFactorsInput());
  return globalThis.ValueFactorsRules.formatValueFactorsText(result);
}

// Kullanıcı talebi: "değeri etkileyen olumlu ve olumsuz faktörlerde çıktı
// 1. 2. 3. olarak numaralandırılarak geliyor. bunun yerine hiç bir
// numaralandırma yada * yada - ... her bir faktör bir satır diğer faktör
// alt satırdan başlasın" — numaralandırma/işaret KALDIRILDI, her madde
// kendi satırında düz metin.
function formatValueFactorsList(items = []) {
  return items.map((item) => item.text).join("\n");
}

