// buildGabimDataGroups() ekrandaki panel için HER ZAMAN tüm alanları
// (üst küme) döner — kullanıcı ileride Ziraat Ekspertiz Sistemine elle veri girerken referans
// olarak faydalı olsun diye hiçbir satır gizlenmez. Ziraat Ekspertiz Sisteminin GERÇEK "Gabim
// Veri Seti" formu ise gayrimenkul türüne göre (Arsa/Tarla, Konut, Diğer
// Bina, Arazi) farklı grup/alan kümeleri gösterir — bkz. kullanıcının
// paylaştığı 4 ekran görüntüsü. Rapor çıktısı (Word/HTML) Ziraat Ekspertiz Sisteminin gerçek
// şeklini birebir yansıtmalı; bu yüzden ekrandaki üst kümeyi türe göre
// budayan ayrı bir filtre katmanı kullanılır — ekran panelini bozmadan.
// Her grubun Ziraat Ekspertiz Sisteminin gerçek "Gabim Veri Seti" formunda kaç sütunlu bir
// ızgarada gösterildiği (bkz. kullanıcının paylaştığı ekran görüntüleri —
// Arsa/Konut/Diğer Bina/Arazi). Grup burada yoksa varsayılan 3 kullanılır.
// GABIM_SUBGROUPS'ta tanımlı gruplar bu tabloyu KULLANMAZ, kendi alt blok
// sütun sayılarını taşır.
const GABIM_GROUP_COLUMNS = {
  "Genel Ek Bilgiler": 4,
  "Tapu Bilgileri": 4,
  "Tapuya Özel Bilgiler": 4,
  "Araziye Özel Bilgiler": 3,
  "Yapıya Özel Bilgiler": 3,
  "Yapı Tür Bilgisi": 1,
  "Ek Bilgiler": 3,
};

// Ziraat Ekspertiz Sisteminin gerçek formunda "Bağımsız Bölüm / Taşınmaz Özellikleri" ve "BB
// İçin İmar Bilgileri" grupları tek bir düz ızgara değil; soldaki küçük gri
// kategori etiketiyle ayrılmış alt bloklardan oluşuyor (bkz. kullanıcının
// paylaştığı ekran görüntüleri: "BB İçin Alanlar", "BB İçin Değerler",
// "BB İçin Birim Değerler", "BB İçin Cephe ve Kat"). Her tanım:
// - `title` varsa: solda kategori etiketiyle girintili satır.
// - `indent: true` varsa: aynı kategorinin devamı, etiketsiz ama girintili.
// - ikisi de yoksa: girintisiz, tam genişlik satır (ör. tek başına dropdown).
const GABIM_SUBGROUPS = {
  "Bağımsız Bölüm / Taşınmaz Özellikleri": [
    { labels: ["Fiili Kullanım Amacı"], columns: 1 },
    { title: "BB İçin Alanlar", labels: ["Yasal Brüt Kullanım Alanı (m²)", "Mevcut Brüt Kullanım Alanı (m²)"], columns: 2 },
    { title: "BB İçin Değerler", labels: ["Yasal Kullanıma Esas Piyasa Değeri (TL)", "Mevcut Kullanıma Esas Piyasa Değeri (TL)"], columns: 2 },
    { title: "BB İçin Birim Değerler", labels: ["Aylık Kira Birim Değeri (TL/m²)", "Arsa Birim Değeri (TL/m²)"], columns: 2 },
    { title: "BB İçin Cephe ve Kat", labels: ["Site Adı"], columns: 1 },
    { indent: true, labels: ["Oda", "Salon", "Banyo", "Mutfak", "Balkon"], columns: 5 },
    { indent: true, labels: ["Cepheler", "Enerji Sınıfı"], columns: 2 },
  ],
  "BB İçin İmar Bilgileri": [
    { labels: ["İmar Lejandı"], columns: 1 },
    { labels: ["TAKS", "KAKS", "Hmax (m)"], columns: 3 },
  ],
};

// Ziraat Ekspertiz Sisteminde açık gri gölgeli bir kart panelinde gösterilen gruplar (bkz.
// kullanıcının paylaştığı 4 ekran görüntüsünün tamamında "Tapuya Özel
// Bilgiler" bloğu bu şekilde).
const GABIM_SHADED_GROUPS = new Set(["Tapuya Özel Bilgiler"]);

function buildGabimExportGroups() {
  const profile = gabimPropertyProfile();
  const groups = buildGabimDataGroups();

  const dropRowsByLabel = (rows, labels) => rows.filter(([label]) => !labels.includes(label));

  return groups
    .map((group) => {
      if (group.title === "Genel Ek Bilgiler") {
        const drop = profile.hasBuilding ? ["Ana Ulaşım Yoluna Cephesi Var mı?"] : ["İnşaat Kalitesi"];
        return { ...group, rows: dropRowsByLabel(group.rows, drop) };
      }
      if (group.title === "Araziye Özel Bilgiler") {
        return profile.isAgricultural ? group : null;
      }
      if (group.title === "Yapıya Özel Bilgiler") {
        return profile.hasBuilding ? group : null;
      }
      if (group.title === "Yapı Tür Bilgisi") {
        return profile.hasBuilding && profile.isResidential ? group : null;
      }
      if (group.title === "Ek Bilgiler") {
        if (!profile.hasBuilding) return null;
        if (profile.isResidential) return group;
        return {
          ...group,
          rows: group.rows.filter(([label]) =>
            ["Yönetici Var mı?", "Açık Otopark Var mı?", "Kapalı Otopark Var mı?", "Asansör Var mı?", "Güvenlik Var mı?"].includes(label)
          ),
        };
      }
      if (group.title === "Bağımsız Bölüm / Taşınmaz Özellikleri") {
        let rows = dropRowsByLabel(group.rows, ["Zemin Kata İndirgenmiş Yasal Alan", "Zemin Kata İndirgenmiş Mevcut Alan"]);
        const konutOnlyLabels = ["Site Adı", "Oda", "Salon", "Banyo", "Mutfak", "Balkon", "Cepheler"];
        if (!profile.hasBuilding) {
          rows = dropRowsByLabel(rows, [
            "Aylık Kira Birim Değeri (TL/m²)",
            "Arsa Birim Değeri (TL/m²)",
            "Enerji Sınıfı",
            ...konutOnlyLabels,
          ]);
        } else if (!profile.isResidential) {
          rows = dropRowsByLabel(rows, konutOnlyLabels);
        } else {
          rows = dropRowsByLabel(rows, ["Enerji Sınıfı"]);
        }
        return { ...group, rows };
      }
      return group;
    })
    .filter(Boolean)
    .filter((group) => group.rows.some(([, value]) => String(value ?? "").trim()))
    .map((group) => {
      const subgroupDefs = GABIM_SUBGROUPS[group.title];
      if (!subgroupDefs) return { ...group, columns: GABIM_GROUP_COLUMNS[group.title] || 3 };
      const rowsByLabel = new Map(group.rows);
      const subgroups = subgroupDefs
        .map((def) => ({
          title: def.title,
          indent: def.indent,
          columns: def.columns,
          rows: def.labels.filter((label) => rowsByLabel.has(label)).map((label) => [label, rowsByLabel.get(label)]),
        }))
        .filter((sub) => sub.rows.some(([, value]) => String(value ?? "").trim()));
      return { ...group, subgroups };
    });
}

// Ziraat Ekspertiz Sisteminin gerçek "Gabim Veri Seti" formu satır-içi label:değer tablosu
// DEĞİL — her alan "üstte küçük gri etiket, altında beyaz/gri çerçeveli
// kutu" şeklinde, çok sütunlu bir ızgarada gösteriliyor; "Bağımsız Bölüm /
// Taşınmaz Özellikleri" ve "BB İçin İmar Bilgileri" grupları ise soldaki
// kategori etiketiyle ayrılmış alt bloklara bölünüyor, "Tapuya Özel
// Bilgiler" açık gri bir kart panelinde gösteriliyor (bkz. kullanıcının
// paylaştığı ekran görüntüleri: Arsa/Konut/Diğer Bina/Arazi). Kullanıcı
// "satır ve sütun yerleşimi, renk paletleri birebir görsellerdeki gibi
// olmalı" dedi — bu yüzden renkler burada uygulama temasından (Navy Blue/
// Apple/Glass/Aurora/Clay/Neumorphism) BAĞIMSIZ, Ziraat Ekspertiz Sistemi ekran görüntülerinden
// alınan SABİT değerlerdir; hangi rapor teması aktif olursa olsun değişmez.
function buildGabimDataSetWordHtml() {
  const groups = buildGabimExportGroups();
  if (!groups.length) return "";
  const ink = "#383838";
  const muted = "#666666";
  const line = "#d6d6d6";
  const boxBg = "#ffffff";
  const panelBg = "#fafafa";
  const panelLine = "#dedede";

  // Gabim Bölümü kendi sayfasında başlayıp tek sayfaya sığmalı (kullanıcı
  // talebi) — punto ve hücre boşlukları önceki sürüme göre bir miktar
  // daha sıkı tutulur.
  const groupTitleStyle = `font-weight:700;font-size:7pt;color:${ink};border:1pt solid ${panelLine};border-left:3pt solid #e86c49;background:#f2f2f2;padding:3pt 5pt;margin:5pt 0 3pt;`;
  const subgroupLabelStyle = `font-size:6pt;font-weight:700;color:${muted};padding:3pt 5pt 0 0;width:68pt;vertical-align:top;`;
  const labelStyle = `font-size:5.5pt;font-weight:700;color:${muted};margin:0 0 1pt;line-height:1.1;`;
  // GDYS form dilindeki gibi değerler beyaz kutuda, ince gri çerçeveyle
  // gösterilir. Keskin köşeli yapı Word'ün HTML motorunda da korunur.
  const boxStyle = `border:1pt solid ${line};background:${boxBg};color:${ink};padding:2.5pt 4pt;font-size:6.3pt;line-height:1.15;min-height:9pt;`;
  const cellStyle = `vertical-align:top;padding:2pt 5pt 4pt 0;`;

  const fieldsTable = (rows, columns) => {
    const rowsHtml = [];
    for (let i = 0; i < rows.length; i += columns) {
      const chunk = rows.slice(i, i + columns);
      const tds = chunk
        .map(
          ([label, value]) =>
            `<td style="${cellStyle}width:${Math.round(100 / columns)}%;">
              <div style="${labelStyle}">${escapeHtml(label)}</div>
              <div style="${boxStyle}">${escapeHtml(value ?? "") || "&nbsp;"}</div>
            </td>`
        )
        .join("");
      const padding = chunk.length < columns ? `<td colspan="${columns - chunk.length}"></td>` : "";
      rowsHtml.push(`<tr>${tds}${padding}</tr>`);
    }
    return `<table style="border-collapse:collapse;width:100%;table-layout:fixed;"><tbody>${rowsHtml.join("")}</tbody></table>`;
  };

  const groupsHtml = groups
    .map((group, groupIndex) => {
      const topBorder = groupIndex === 0 ? "border-top:none;" : "";
      const title = `<div style="${groupTitleStyle}${topBorder}">${escapeHtml(group.title)}</div>`;

      let body;
      if (group.subgroups) {
        const subRowsHtml = group.subgroups
          .map((sub) => {
            if (sub.title) {
              return `<tr>
                <td style="${subgroupLabelStyle}">${escapeHtml(sub.title)}</td>
                <td style="padding:2pt 0;">${fieldsTable(sub.rows, sub.columns)}</td>
              </tr>`;
            }
            if (sub.indent) {
              return `<tr>
                <td style="${subgroupLabelStyle}"></td>
                <td style="padding:2pt 0;">${fieldsTable(sub.rows, sub.columns)}</td>
              </tr>`;
            }
            return `<tr><td colspan="2" style="padding:2pt 0;">${fieldsTable(sub.rows, sub.columns)}</td></tr>`;
          })
          .join("");
        body = `<table style="border-collapse:collapse;width:100%;table-layout:fixed;margin:0 0 2pt;"><tbody>${subRowsHtml}</tbody></table>`;
      } else {
        body = `<div style="margin:0 0 2pt;">${fieldsTable(group.rows, group.columns)}</div>`;
      }

      if (GABIM_SHADED_GROUPS.has(group.title)) {
        body = `<div style="background:${panelBg};border:1pt solid ${panelLine};border-radius:4pt;padding:6pt 8pt;">${body}</div>`;
      }

      return `${title}${body}`;
    })
    .join("");

  return `<div class="gdys-gabim-sheet">${groupsHtml}</div>`;
}

function buildGabimGeneralExtraInfoRows() {
  return [
    ["Değer Türü", gabimValueTypeText()],
    ["Tasarruf Finansman Şirketi Adı", gabimField("savingsFinanceCompanyName") || gabimSelect()],
    ["Hesaplanan Emsal (m²)", gabimCalculatedEmsalText()],
    ["Ulaşım İmkanı", gabimTransportationLevelText()],
    ["Çevresinde Büyük Yatırım Projeleri Var mı?", gabimMajorInvestmentProjectText()],
    ["Çevresinde Markalı Konut Projelerinin Yoğunluğu", gabimBrandedHousingDensityText()],
    ["Çevresinin Genel Yapılaşma Hızı", gabimDevelopmentSpeedText()],
    ["Çevresinde Ticari Alanların Gelişme Hızı", gabimCommercialDevelopmentSpeedText()],
    ["Çevrenin Sanayileşme Hızı", gabimIndustrializationSpeedText()],
    ["Çevrenin Turizm Gelişme Potansiyeli", gabimTourismPotentialText()],
    ["Gayrimenkulün Satılabilirliği", gabimSaleabilityText()],
    ["Tercihli Kullanım Alanı mı?", gabimPreferredUseAreaText()],
    ["İnşaat Kalitesi", gabimConstructionQualityText()],
    ["Ana Ulaşım Yoluna Cephesi Var mı?", gabimField("landRoadFrontage")],
  ];
}

function createGabimDataGroup(group) {
  const section = document.createElement("div");
  section.className = "gabim-data-group";
  const header = document.createElement("div");
  header.className = "gabim-data-group-head";
  const title = document.createElement("h4");
  title.textContent = group.title;
  header.append(title);
  const grid = document.createElement("div");
  grid.className = "gabim-data-grid";
  group.rows.forEach(([label, value]) => grid.append(createGabimDataField(label, value)));
  section.append(header, grid);
  return section;
}

function createGabimDataField(labelText, value) {
  const label = document.createElement("label");
  label.className = "gabim-data-field";
  const title = document.createElement("span");
  title.textContent = labelText;
  const input = document.createElement("input");
  input.type = "text";
  input.readOnly = true;
  input.value = gabimDisplayValue(value);
  label.append(title, input);
  return label;
}

function gabimDisplayValue(value) {
  const text = String(value ?? "").trim();
  return text || "";
}

function gabimField(...keys) {
  for (const key of keys) {
    const value = String(state.fields?.[key] ?? "").trim();
    if (value) return value;
  }
  return "";
}

function gabimTitle(...keys) {
  const value = gabimField(...keys);
  return value ? normalizeReportTitleText(value) : "";
}

function gabimDate(key) {
  const value = gabimField(key);
  return value ? dateIsoToTr(value) || value : "";
}

function gabimMoney(key) {
  const value = parseValuationNumber(state.fields?.[key]);
  return Number.isFinite(value) && value > 0 ? `${formatSchemeNumber(value)} TL` : "";
}

function gabimSelect(defaultValue = "Seçiniz") {
  return defaultValue;
}

function gabimTextFromKeys(...keys) {
  return keys.map((key) => gabimField(key)).filter(Boolean).join(" ");
}

function gabimFoldedTextFromKeys(...keys) {
  return foldTurkish(gabimTextFromKeys(...keys));
}

function gabimLevelFromChoice(value, fallback = "Orta") {
  const folded = foldTurkish(value);
  if (folded.includes("YUKSEK") || folded.includes("HIZLI") || folded.includes("IYI")) return "Yüksek";
  if (folded.includes("DUSUK") || folded.includes("YAVAS") || folded.includes("ZAYIF")) return "Düşük";
  if (folded.includes("ORTA")) return "Orta";
  return fallback;
}

function gabimValueTypeText() {
  const methods = foldTurkish(gabimField("valuationMethod"));
  if (methods.includes("MALIYET")) return "Maliyet";
  if (methods.includes("GELIR")) return "Gelir";
  return "Satış/Pazar";
}

function gabimCalculatedEmsalText() {
  const fieldValue = gabimField("calculatedEmsal");
  if (fieldValue) return fieldValue.replace(/\s*m²\s*$/i, "");
  const calculated = buildImarCalculatedEmsal();
  if (calculated) return calculated.replace(/\s*m²\s*$/i, "");
  const parcelArea = parseValuationNumber(gabimField("landArea"));
  const kaks = parseValuationNumber(gabimField("kaks"));
  if (Number.isFinite(parcelArea) && parcelArea > 0 && Number.isFinite(kaks) && kaks > 0) {
    return formatValuationArea(parcelArea * kaks);
  }
  return "";
}

function gabimTransportationLevelText() {
  const proximity = foldTurkish(gabimField("mainArteryProximity"));
  if (proximity.includes("ORTA YAKIN")) return "Orta";
  if (proximity.includes("YAKIN")) return "Yüksek";
  if (proximity.includes("UZAK")) return "Düşük";
  const text = gabimFoldedTextFromKeys(
    "transportDescription",
    "mainArtery",
    "mainArteryName",
    "nearbyImportantRoads",
    "environmentDescription"
  );
  if (/(METRO|TRAMVAY|OTOBUS|DURAK|CADDE|BULVAR|ANA ARTER|ULASIM|YAKIN)/.test(text)) return "Yüksek";
  return text ? "Orta" : "Orta";
}

function gabimMajorInvestmentProjectText() {
  const text = gabimFoldedTextFromKeys(
    "environmentDescription",
    "nearbyImportantPlaces",
    "nearbyPlacesText",
    "transportNearbyText",
    "planningNote"
  );
  return /(AVM|METRO|HASTANE|UNIVERSITE|KAMU|PROJE|KENTSEL DONUSUM|TERMINAL|OSB|LIMAN)/.test(text) ? "Var" : "Yok";
}

function gabimBrandedHousingDensityText() {
  const text = gabimFoldedTextFromKeys(
    "environmentDescription",
    "regionType",
    "environmentRegionType",
    "regionUsePurpose",
    "addressSiteName"
  );
  if (/(REZIDANS|MARKALI|SITE|TOPLU KONUT|KONUT PROJESI)/.test(text)) return "Orta";
  return "Düşük";
}

function gabimDevelopmentSpeedText() {
  return gabimLevelFromChoice(gabimField("developmentSpeed"), "Orta");
}

function gabimCommercialDevelopmentSpeedText() {
  const text = gabimFoldedTextFromKeys("legend", "regionUsePurpose", "environmentDescription", "actualUsePurpose");
  if (/(TICARET|ISYERI|OFIS|DUKKAN|MAGAZA|AVM|CADDE)/.test(text)) return "Orta";
  return "Düşük";
}

function gabimIndustrializationSpeedText() {
  const text = gabimFoldedTextFromKeys("legend", "regionUsePurpose", "environmentDescription", "actualUsePurpose");
  if (/(SANAYI|DEPO|IMALAT|FABRIKA|OSB|LOJISTIK)/.test(text)) return "Orta";
  return "Düşük";
}

function gabimTourismPotentialText() {
  const text = gabimFoldedTextFromKeys("legend", "regionUsePurpose", "environmentDescription", "nearbyImportantPlaces");
  if (/(TURIZM|OTEL|SAHIL|DENIZ|TERMAL|TARIHI|PLAJ|MARINA)/.test(text)) return "Orta";
  return "Düşük";
}

function gabimSaleabilityText() {
  return gabimField("saleability") || "Satılabilir";
}

function gabimPreferredUseAreaText() {
  return "Hayır";
}

function gabimConstructionQualityText() {
  const quality = foldTurkish(gabimField("unitMaterialQuality"));
  if (quality.includes("LUKS")) return "Lüks";
  if (quality.includes("KALITELI")) return "İyi";
  if (quality.includes("ORTA")) return "Orta";
  if (quality.includes("VASAT") || quality.includes("KOTU") || quality.includes("DUSUK") || quality.includes("EKSIK")) return "Kötü";
  const buildingClass = foldTurkish(gabimField("buildingClass"));
  if (/^[45]\s*\//.test(buildingClass) || buildingClass.includes("5/") || buildingClass.includes("4/")) return "İyi";
  if (buildingClass.includes("3/")) return "Orta";
  if (buildingClass.includes("1/") || buildingClass.includes("2/")) return "Kötü";
  return "Orta";
}

function gabimTitleTypeText() {
  return [gabimField("groundType"), gabimField("ownershipType")]
    .map((value) => normalizeReportTitleText(value || "").trim())
    .filter(Boolean)
    .join(" & ");
}

function gabimHasShareText() {
  const ownershipKind = foldTurkish(gabimField("titleOwnershipKind"));
  if (ownershipKind.includes("HISSELI")) return "Evet";
  if (ownershipKind.includes("TAM MULKIYET")) return "Hayır";
  return gabimSelect();
}

function gabimUrbanTransformationText() {
  const hasPlanningIssue = normalizeYesNoChoice(state.fields.hasPlanningIssue);
  const urbanTransformation = normalizeYesNoChoice(state.fields.urbanTransformationArea);
  return hasPlanningIssue === "Evet" && urbanTransformation === "Evet" ? "Evet" : "Hayır";
}

function gabimOccupancyPermitText() {
  return hasReviewedOccupancyPermitDocument() ? "Var" : "Yok";
}

function gabimConstructionYearText() {
  const date = gabimField("buildingCompletionDate");
  const match = String(date || "").match(/\b(19|20)\d{2}\b/);
  return match ? match[0] : "";
}

function gabimUnitFloorsText() {
  return getUnitFloorRows().map((row) => row.floor).filter(Boolean).join(", ");
}

function gabimTotalReducedAreaText(mode = "legal") {
  const rows = getUnitFloorRows();
  if (!rows.length) return "";
  return formatUnitReducedAreaValue(calculateReducedUnitFloorTotal(rows, mode));
}

// "Site içerisinde mi?" yalnızca GERÇEKTEN site ise Evet olmalı. Apartman adı
// (addressSiteName) tek başına site anlamına gelmez — tek bloklu bir apartmanın
// da adı vardır. Ölçüt, ana gayrimenkul metinlerinde kullanılan kanonik kuralla
// aynıdır (bkz. getMainPropertyStructureContext): blok adı VARSA ya da blok
// adedi girilmiş ve "Tek" değilse site sayılır.
function gabimSiteWithinText() {
  const blockCountText = gabimField("buildingBlockCount");
  const isSite = Boolean(gabimField("titleBlockName"))
    || Boolean(blockCountText && blockCountText.toLocaleLowerCase("tr-TR") !== "tek");
  return isSite ? "Evet" : "Hayır";
}

function gabimCarparkText(keyword) {
  const carpark = foldTurkish(gabimField("carpark"));
  if (!carpark) return gabimSelect();
  if (carpark.includes("YOK")) return "Yok";
  return carpark.includes(foldTurkish(keyword)) ? "Var" : "Yok";
}

function gabimElevatorText() {
  const elevator = foldTurkish(gabimField("elevator"));
  if (!elevator) return gabimSelect();
  if (elevator.includes("YOK")) return "Yok";
  return "Var";
}

function gabimSocialFacilityText(keyword) {
  const source = foldTurkish([gabimField("socialFacilities"), gabimField("siteFacilities")].filter(Boolean).join(", "));
  if (!source) return "Hayır";
  return source.includes(foldTurkish(keyword)) ? "Var" : "Yok";
}

function gabimPoolText() {
  const facilities = foldTurkish(gabimField("socialFacilities"));
  return facilities.includes("ACIK YUZME HAVUZU") || facilities.includes("KAPALI YUZME HAVUZU") ? "Evet" : "Hayır";
}

function gabimFirstSaleText() {
  return refreshUnitFirstSaleStatusFromCurrentFields();
}

function gabimSecurityText() {
  return foldTurkish(gabimField("socialFacilities")).includes("OZEL GUVENLIK") ? "Evet" : "Hayır";
}

// --- Ziraat GABIM ekranı: Arsa/Arazi'ye özgü alanlar ---
function gabimLandSlopeText() {
  const value = foldTurkish(gabimField("landTopography"));
  if (value.includes("COK EGIMLI")) return "Dik Eğimli";
  if (value.includes("AZ EGIMLI")) return "Az Eğimli";
  if (value.includes("EGIMSIZ")) return "Eğim Yok";
  return gabimSelect();
}

function gabimRoadFrontageText() {
  const value = normalizeYesNoChoice(gabimField("landRoadFrontage"));
  if (value === "Evet") return "Kadastral Yola Cepheli";
  if (value === "Hayır") return "Kadastral Yola Cepheli Değil";
  return gabimSelect();
}

function gabimAgricultureTypeText() {
  return gabimField("landAgricultureType") || gabimSelect();
}

function gabimLandClassificationText() {
  return gabimField("landClassification") || gabimSelect();
}

function gabimArableLandText() {
  const suitability = foldTurkish(gabimField("agriculturalSuitability"));
  if (suitability.includes("UYGUN DEGIL")) return "Hayır";
  if (suitability.includes("UYGUN")) return "Evet";
  return "Evet";
}

function gabimArableSoilText() {
  return gabimArableLandText() === "Hayır" ? "Tarıma Elverişli Olmayan Toprak" : "Tarıma Elverişli Toprak";
}

function getGabimUnitInteriorCounts() {
  const summary = foldTurkish(formatUnitFloorInteriorSummary(getUnitFloorRows())).toLocaleLowerCase("tr");
  const countMentions = (...words) => {
    const total = words.reduce((sum, word) => {
      // Sondaki \b KASITLI OLARAK \w* ile değiştirildi: Türkçe ek alan
      // serbest metinler ("Ebeveyn Banyosu", "Balkonu", "Terası" gibi)
      // yalnızca tam "banyo"/"balkon" kelimesiyle eşleşmiyordu — bu daha
      // kapsayıcı hali GERİYE DÖNÜK UYUMLU (yalnızca EK eşleşme yakalar,
      // hiçbir mevcut eşleşmeyi kaybetmez).
      const matches = [...summary.matchAll(new RegExp(`\\b(?:(\\d+)\\s*)?${word}\\w*`, "gi"))];
      return sum + matches.reduce((wordSum, match) => wordSum + Number(match[1] || 1), 0);
    }, 0);
    return total ? String(total) : "";
  };
  return {
    salon: countMentions("salon"),
    oda: countMentions("oda"),
    // "duş ve ebeveyn banyosu dahil wc hariç" (kullanıcı talebi) — "ebeveyn
    // banyosu" zaten "banyo" ön ekiyle (\w* sayesinde) eşleşir, ayrı kelime
    // eklemeye gerek yok.
    banyo: countMentions("banyo", "dus"),
    tuvalet: countMentions("wc", "tuvalet"),
    mutfak: countMentions("mutfak"),
    // "balkon (Teras ve verandalar dahil)" (kullanıcı talebi)
    balkon: countMentions("balkon", "teras", "veranda"),
  };
}

// Kullanıcı talebi: "iç hacimlerde konut için iç hacimleri gruplandıracağız...
// bunları sayısal olarak kaç adet var ise placeholder mantığında grupla
// örnek salon 1 oda 4 banyo 2 wc 1 balkon 3 gibi" — yukarıdaki
// getGabimUnitInteriorCounts()'un (zaten SALON/ODA/BANYO/TUVALET/MUTFAK/
// BALKON placeholder'larını besleyen) altı grubunu TEK bir metinde
// "Etiket Adet" ikilileri olarak birleştirir; adedi 0/boş olan gruplar
// atlanır.
function getUnitInteriorGroupSummaryText() {
  const counts = getGabimUnitInteriorCounts();
  return [
    ["Salon", counts.salon],
    ["Oda", counts.oda],
    ["Mutfak", counts.mutfak],
    ["Banyo", counts.banyo],
    ["Wc", counts.tuvalet],
    ["Balkon", counts.balkon],
  ]
    .filter(([, count]) => count)
    .map(([label, count]) => `${label} ${count}`)
    .join(" ");
}

const UNIT_INTERIOR_KNOWN_GROUP_PREFIXES = ["salon", "oda", "mutfak", "banyo", "dus", "wc", "tuvalet", "balkon", "teras", "veranda"];

function isKnownUnitInteriorGroupName(name) {
  const folded = foldTurkish(name || "").toLocaleLowerCase("tr");
  return UNIT_INTERIOR_KNOWN_GROUP_PREFIXES.some((prefix) => folded.startsWith(prefix));
}

// Kullanıcı talebi: "bu gruplandırmalar harici iç hacimleri diğer kategorisi
// olarak placeholder oluştur. örnek antre çamaşırlık" — Salon/Oda/Mutfak/
// Banyo/Wc/Balkon gruplarının HİÇBİRİNE uymayan iç hacim kalemlerinin
// (antre, hol, kiler, çamaşırlık, depo, sığınak, vb.) toplam adedini döner.
function getUnitInteriorOtherCount() {
  const totals = new Map();
  getUnitFloorRows().forEach((row) => {
    String(row.interiors || "")
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean)
      .forEach((item) => {
        const parsed = parseUnitInteriorItem(item);
        if (!parsed.name) return;
        totals.set(parsed.name, (totals.get(parsed.name) || 0) + parsed.count);
      });
  });
  let other = 0;
  totals.forEach((count, name) => {
    if (!isKnownUnitInteriorGroupName(name)) other += count;
  });
  return other ? String(other) : "";
}

function ensureLegacyPlaceholderRowsLoaded() {
  if (legacyPlaceholderRowsLoaded || legacyPlaceholderRowsLoading) return;
  legacyPlaceholderRowsLoading = true;
  fetch(legacyPlaceholderDefinitionsUrl)
    .then((response) => {
      if (!response.ok) throw new Error("Placeholder listesi okunamadı.");
      return response.json();
    })
    .then((rows) => {
      legacyPlaceholderRows = Array.isArray(rows) ? rows : [];
    })
    .catch(() => {
      legacyPlaceholderRows = [];
    })
    .finally(() => {
      legacyPlaceholderRowsLoaded = true;
      legacyPlaceholderRowsLoading = false;
      if (activeSectionId === "placeholders") renderSection();
    });
}

function collectPlaceholderDefinitions() {
  return [
    ...collectApplicationFieldPlaceholders(),
    ...collectGeneratedTextPlaceholders(),
    ...collectTablePlaceholders(),
    ...collectLegacyExcelPlaceholders(),
  ];
}

function collectApplicationFieldPlaceholders() {
  const rows = [];
  const registeredKeys = new Set();
  getVisibleSections()
    .filter((section) => section.id !== "placeholders")
    .forEach((section) => {
      (section.fields || []).forEach((field) => {
        registeredKeys.add(field.key);
        rows.push({
          category: section.title,
          token: makePlaceholderToken(field.key),
          title: field.label || field.key,
          type: field.hidden ? "Gizli Alan" : getPlaceholderFieldTypeLabel(field),
          source: "Uygulama Alanı",
          value: formatPlaceholderValue(formatOutputFieldValue(state.fields[field.key], field)),
          reference: field.key,
        });
      });
      (section.uploads || []).forEach((upload) => {
        rows.push({
          category: section.title,
          token: makePlaceholderToken(`upload_${upload.id}`),
          title: upload.title,
          type: "Belge Yükleme",
          source: "Uygulama Alanı",
          value: state.uploads?.[upload.id]?.name || "",
          reference: upload.id,
        });
      });
    });

  // Özel panellerin yönettiği, sections[].fields dışında kalan alanlar da
  // placeholder kataloğunda görünür olmalı. Böylece yeni bir panel alanı
  // eklenince ayrıca unutulmuş bir katalog kaydı bırakmayız.
  Object.keys(state.fields || {})
    .filter((key) => key && !registeredKeys.has(key) && !key.startsWith("_") && !key.startsWith("calc"))
    .forEach((key) => {
      rows.push({
        category: "Özel Uygulama Alanları",
        token: makePlaceholderToken(key),
        title: key,
        type: "Özel Alan",
        source: "Uygulama Alanı",
        value: formatPlaceholderValue(state.fields[key]),
        reference: key,
      });
    });
  return rows;
}

// "_BÜYÜK" katalog satırları (Placeholder referans ekranı önizlemesi) için
// yardımcılar — template-engine.js'teki LEGACY_ALIASES'teki AYNI adlı
// girdilerle (toTrUpper/malikNamesText) birebir aynı hesaplamayı yapar.
function toTrUpperForPlaceholderPreview(value) {
  return String(value || "").toLocaleUpperCase("tr-TR");
}

function getMalikNamesForPlaceholderPreview() {
  const rows = Array.isArray(state.tables?.title) ? state.tables.title : [];
  return rows.map((row) => String(row?.c0 || "").trim()).filter(Boolean).join(", ");
}

// template-engine.js'teki ownersListText() ile ayni (isim+hisse birlesik,
// SAHIPLER'i besleyen) — SAHIPLER_BUYUK katalog onizlemesi icin.
function getOwnersListForPlaceholderPreview() {
  const rows = Array.isArray(state.tables?.title) ? state.tables.title : [];
  return rows
    .filter((row) => String(row?.c0 || "").trim())
    .map((row) => (row.c1 ? `${row.c0} (${row.c1})` : row.c0))
    .join(", ");
}

