function normalizeComparableNature(row = {}) {
  const raw = String(row.c23 || "Konut").trim();
  return foldTurkish(raw).toLowerCase();
}

function isLandComparable(row = {}) {
  return comparableLandNatureKeys.has(normalizeComparableNature(row));
}

function isAgriculturalComparable(row = {}) {
  return comparableAgriculturalNatureKeys.has(normalizeComparableNature(row));
}

function isComparableFurnished(row = {}) {
  return !isLandComparable(row) && foldTurkish(String(row.c32 || "").trim()) === "EVET";
}

function buildComparableFurnishedMarketNote() {
  const saleRows = getComparableRows().filter((row) => !isLandComparable(row) && /satilik/i.test(foldTurkish(row.c2 || "")));
  const furnishedCount = saleRows.filter((row) => isComparableFurnished(row)).length;
  if (!saleRows.length || furnishedCount <= saleRows.length / 2) return "";
  return "* Not: Yapılan piyasa araştırmasında, bölgede satışa sunulan benzer nitelikteki gayrimenkullerin çoğunluğunun eşyalı olarak pazarlandığı gözlemlenmiştir. Bu nedenle eşyalı ilanların bedelleri analiz edilirken mobilya ve diğer taşınır eşyalara atfedilen tutarlar mümkün olduğu ölçüde ayrıştırılmış, değerleme hesabında yalnızca gayrimenkule atfedilen net bedel esas alınmıştır.";
}

function getComparableViewMode() {
  const value = state.fields.comparableViewMode || "all";
  return comparableViewModeOptions.some((option) => option.value === value) ? value : "all";
}

function getComparableRowsForView(rows, viewMode) {
  return rows
    .map((row, index) => ({ row, index }))
    .filter(({ row }) => {
      if (viewMode === "land") return isLandComparable(row);
      if (viewMode === "residential") return !isLandComparable(row);
      return true;
    });
}

function getComparableDisplayFields(viewMode) {
  const showWorkplaceFields = isWorkplaceLikeUsageNature();
  const comparableRows = Array.isArray(state.tables?.comparables) ? state.tables.comparables : [];
  const showFurnitureValue = comparableRows.some((row) => String(row?.c32 || "").trim().toLocaleLowerCase("tr-TR") === "evet");
  return comparableFields.filter((field) => {
    if (field.hidden) return false;
    if (field.key === "c33" && !showFurnitureValue) return false;
    if (!showWorkplaceFields && comparableWorkplaceOnlyFieldKeys.has(field.key)) return false;
    if (showWorkplaceFields && comparableHiddenForWorkplaceFieldKeys.has(field.key)) return false;
    if (viewMode === "all") return true;
    if (viewMode === "land") return !comparableResidentialOnlyFieldKeys.has(field.key);
    return !comparableLandOnlyFieldKeys.has(field.key);
  });
}

// Emsaller'de Kat Bazında İndirgeme Oranı/Toplam İndirgenmiş Alan alanları
// yalnızca konu taşınmaz işyeri/ofis/ticari bina ise gösterilir (konut hariç
// — kullanıcı talebi; Ana Gayrimenkul'deki kat indirgeme tablosundan farklı
// olarak konut kapsanmaz, bkz. shouldShowUnitReductionFields).
function isWorkplaceLikeUsageNature(value = state.fields.legalUsageNature) {
  const normalized = foldTurkish(value || "").replace(/\s+/g, " ").trim();
  return ["OFIS", "ISYERI", "TICARI BINA"].includes(normalized);
}

function createComparableViewModeControl() {
  const wrapper = document.createElement("label");
  wrapper.className = "comparable-view-mode-control";
  const label = document.createElement("span");
  label.textContent = "Görünüm";
  const select = document.createElement("select");
  comparableViewModeOptions.forEach((option) => {
    const optionElement = document.createElement("option");
    optionElement.value = option.value;
    optionElement.textContent = option.label;
    select.append(optionElement);
  });
  select.value = getComparableViewMode();
  select.addEventListener("change", (event) => {
    state.fields.comparableViewMode = event.target.value;
    autosave();
    renderSection();
  });
  wrapper.append(label, select);
  return wrapper;
}

function areComparableRowLabelsVisible() {
  return state.settings?.comparableRowLabelsVisible !== false;
}

function createComparableRowLabelsToggle() {
  const button = document.createElement("button");
  const visible = areComparableRowLabelsVisible();
  button.type = "button";
  button.className = "mini-button comparable-row-labels-toggle";
  button.textContent = visible ? "Başlıkları gizle" : "Başlıkları göster";
  button.setAttribute("aria-pressed", String(visible));
  button.addEventListener("click", () => {
    state.settings = { ...state.settings, comparableRowLabelsVisible: !visible };
    autosave();
    renderSection();
  });
  return button;
}

function attachComparableColumnTabNavigation(shell, visibleRows) {
  const columnOrder = visibleRows.map(({ index }) => String(index));
  const isUsableTabStop = (el) => {
    if (!el || el.disabled) return false;
    if (typeof el.focus !== "function") return false;
    return el.offsetParent !== null;
  };
  const stopsForColumn = (rowKey) => [...shell.querySelectorAll(`[data-comparable-row="${rowKey}"]`)].filter(isUsableTabStop);

  shell.addEventListener("keydown", (event) => {
    if (event.key !== "Tab") return;
    const target = event.target;
    const rowKey = target?.dataset?.comparableRow;
    if (rowKey === undefined) return;
    const columnPos = columnOrder.indexOf(rowKey);
    if (columnPos === -1) return;

    const stops = stopsForColumn(rowKey);
    const currentIndex = stops.indexOf(target);
    if (currentIndex === -1) return;
    const forward = !event.shiftKey;
    const nextIndex = currentIndex + (forward ? 1 : -1);
    if (nextIndex >= 0 && nextIndex < stops.length) {
      event.preventDefault();
      stops[nextIndex].focus();
      return;
    }

    // Sütun sonuna/başına gelindi: bir sonraki/önceki emsal sütununa geç.
    const nextColumnPos = columnPos + (forward ? 1 : -1);
    if (nextColumnPos < 0 || nextColumnPos >= columnOrder.length) return; // tablo dışına çıkışı tarayıcıya bırak
    const nextStops = stopsForColumn(columnOrder[nextColumnPos]);
    if (!nextStops.length) return;
    event.preventDefault();
    (forward ? nextStops[0] : nextStops[nextStops.length - 1]).focus();
  });
}

function getComparableFieldForRow(field, row) {
  if (!isLandComparable(row)) return field;
  if (field.key === "c7") return { ...field, options: comparableLandLocationOptions };
  if (isAgriculturalComparable(row) && comparableTarlaZoningFieldKeys.has(field.key)) {
    return { ...field, allowEmpty: true, options: field.type === "select" ? ["", ...(field.options || [])] : field.options };
  }
  return field;
}

function calculateComparableLandBuildableArea(row = {}) {
  if (!isLandComparable(row)) return Number.NaN;
  const landArea = parseComparableNumber(row.c24);
  const kaks = parseComparableNumber(row.c27);
  if (!Number.isFinite(landArea) || landArea <= 0) return Number.NaN;
  if (Number.isFinite(kaks) && kaks > 0) return landArea * kaks;
  const floorCount = parseComparableNumber(row.c28);
  if (Number.isFinite(floorCount) && floorCount > 0) return landArea * floorCount;
  return Number.NaN;
}

function formatComparableAreaInput(value) {
  if (!Number.isFinite(value)) return "";
  return value.toLocaleString("tr-TR", { maximumFractionDigits: 2 });
}

function syncComparableLandBuildableArea(row = {}, force = false) {
  if (!force && row.c31Manual === "1" && String(row.c31 || "").trim()) return false;
  if (force || row.c31Manual === "1") row.c31Manual = "";
  const buildableArea = calculateComparableLandBuildableArea(row);
  const nextValue = formatComparableAreaInput(buildableArea);
  if ((row.c31 || "") === nextValue) return false;
  row.c31 = nextValue;
  return true;
}

// "Sahibinden.com üzerinden ara" düğmesi (0.0.43x, 2026-08-13) — kullanıcı
// bir rakip programın (Ekspress Rapor) Emsaller ekranındaki aynı düğmeyi
// örnek gösterdi: aktif taşınmazın il/ilçesine göre sahibinden.com'da o
// bölgenin ilanlarını yeni sekmede açar. sahibinden.com otomatik erişimi
// (bot koruması, Cloudflare benzeri "Olağan dışı erişim" hata sayfası)
// engellediğinden harita/koordinat tabanlı bir URL şeması DOĞRULANAMADI —
// bunun yerine sahibinden'in kendi herkese açık, arama motorlarınca
// indekslenmiş SEO URL kalıbı kullanıldı (doğrulanan gerçek örnekler:
// sahibinden.com/satilik-arsa/bursa-nilufer, .../satilik-daire/bursa,
// .../satilik-is-yeri/bursa) — yalnızca İl-İlçe düzeyinde, çünkü mahalle
// düzeyi köy/mahalle'ye göre tutarsız bir ek slug kullanıyor
// (ör. ".../bursa-nilufer-koyler-gokce-mh.") ve güvenilir şekilde
// üretilemiyor.
const SAHIBINDEN_CATEGORY_BY_USAGE_NATURE = {
  KONUT: "satilik-daire",
  ARSA: "satilik-arsa",
  ARAZI: "satilik-arsa",
  TARLA: "satilik-arsa",
  "SANAYI TESISI": "satilik-arsa",
  ISYERI: "satilik-is-yeri",
  OFIS: "satilik-is-yeri",
  "TICARI BINA": "satilik-is-yeri",
};

function getSahibindenCategorySlug() {
  const usageKey = foldTurkish(state.fields.currentUsageNature || state.fields.legalUsageNature || "");
  if (SAHIBINDEN_CATEGORY_BY_USAGE_NATURE[usageKey]) return SAHIBINDEN_CATEGORY_BY_USAGE_NATURE[usageKey];
  return isLandOwnershipType() ? "satilik-arsa" : "satilik-daire";
}

// sahibinden'in SEO URL'lerindeki il/ilçe parçası: küçük harf, Türkçe
// karakterler ASCII'ye katlanmış, boşluklar tire. foldTurkish() BÜYÜK harf
// döndürdüğü için burada ayrıca küçültülüyor (ör. "Nilüfer" → "nilufer").
function buildSahibindenLocationSlugPart(value) {
  return foldTurkish(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, "")
    .trim()
    .replace(/\s+/g, "-");
}

function buildSahibindenNeighborhoodSlug(value) {
  return buildSahibindenLocationSlugPart(value)
    .replace(/-mahallesi$/i, "-mah")
    .replace(/-mah\.?$/i, "-mah.");
}

function getSahibindenSubjectCentroid() {
  const selected = getSelectedMapPoint();
  if (selected) return selected;
  const records = typeof getTitleUnitKmlRecordsForMap === "function" ? getTitleUnitKmlRecordsForMap() : [];
  const points = [state.sourceValues.kml?.centroid, ...records.map((record) => record?.parsed?.centroid)]
    .map((point) => [Number(point?.lat), Number(point?.lng)])
    .filter(([lat, lng]) => Number.isFinite(lat) && Number.isFinite(lng));
  if (!points.length) return null;
  return [points.reduce((sum, point) => sum + point[0], 0) / points.length, points.reduce((sum, point) => sum + point[1], 0) / points.length];
}

function buildSahibindenMapBounds(point, radiusMeters = 3000) {
  if (!point) return null;
  const [lat, lng] = point;
  const latDelta = radiusMeters / 111320;
  const lngDelta = radiusMeters / (111320 * Math.max(Math.cos((lat * Math.PI) / 180), 0.2));
  return { north: lat + latDelta, south: lat - latDelta, east: lng + lngDelta, west: lng - lngDelta };
}

function getComparablePortalCategory(portal) {
  const usageKey = foldTurkish(state.fields.currentUsageNature || state.fields.legalUsageNature || "");
  const isLand = isLandOwnershipType() || ["ARSA", "TARLA", "ARAZI", "SANAYI TESISI"].includes(usageKey);
  if (portal === "hepsiemlak") return isLand ? "arsa" : usageKey.includes("ISYERI") || usageKey.includes("TICARI") ? "isyeri" : "daire";
  return isLand ? "satilik-arsa" : usageKey.includes("ISYERI") || usageKey.includes("TICARI") ? "satilik-isyeri" : "satilik-daire";
}

function buildHepsiemlakSearchUrl() {
  const city = buildSahibindenLocationSlugPart(state.fields.titleCity || state.fields.city);
  const district = buildSahibindenLocationSlugPart(state.fields.titleDistrict || state.fields.district);
  const bounds = buildSahibindenMapBounds(getSahibindenSubjectCentroid());
  if (!city || !district || !bounds) return "https://www.hepsiemlak.com/harita";
  const query = new URLSearchParams({
    mapTopLeft: `${bounds.north.toFixed(6)},${bounds.west.toFixed(6)}`,
    mapBottomRight: `${bounds.south.toFixed(6)},${bounds.east.toFixed(6)}`,
  });
  return `https://www.hepsiemlak.com/harita/${city}-satilik/${getComparablePortalCategory("hepsiemlak")}?${query.toString()}`;
}

function buildEmlakjetSearchUrl() {
  const city = buildSahibindenLocationSlugPart(state.fields.titleCity || state.fields.city);
  const district = buildSahibindenLocationSlugPart(state.fields.titleDistrict || state.fields.district);
  const bounds = buildSahibindenMapBounds(getSahibindenSubjectCentroid());
  if (!city || !district || !bounds) return "https://www.emlakjet.com/";
  const query = new URLSearchParams({
    bottom_left: `${bounds.south.toFixed(6)},${bounds.west.toFixed(6)}`,
    top_right: `${bounds.north.toFixed(6)},${bounds.east.toFixed(6)}`,
  });
  return `https://www.emlakjet.com/${getComparablePortalCategory("emlakjet")}/${city}-${district}/?${query.toString()}`;
}

function createComparablePortalButton({ label, initials, className, title, buildUrl }) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = `mini-button comparable-portal-button ${className}`;
  button.setAttribute("aria-label", label);
  const logoMap = {
    "hepsiemlak-search-button": "assets/portal-logos/emlakjet.png",
    "emlakjet-search-button": "assets/portal-logos/hepsiemlak.png",
    "sahibinden-search-button": "assets/portal-logos/sahibinden.png",
  };
  const logo = logoMap[className];
  button.innerHTML = `<img class="comparable-portal-logo" src="${logo || ""}" width="24" height="24" alt="" aria-hidden="true">`;
  button.title = title;
  button.addEventListener("click", () => {
    const url = buildUrl();
    const userAgent = navigator.userAgent || "";
    if (/Android/i.test(userAgent)) {
      // Android universal-link yönlendirmesini atlayıp Chrome'un web sekmesini aç.
      const parsed = new URL(url);
      const intentUrl = `intent://${parsed.host}${parsed.pathname}${parsed.search}#Intent;scheme=https;package=com.android.chrome;end`;
      window.location.href = intentUrl;
      return;
    }
    window.open(url, "_blank", "noopener,noreferrer");
  });
  return button;
}

function createHepsiemlakSearchButton() {
  return createComparablePortalButton({
    label: "Hepsiemlak",
    initials: "HE",
    className: "hepsiemlak-search-button",
    title: "Konu taşınmazın KML merkezinin yaklaşık 3 km çevresindeki Hepsiemlak ilanlarını açar.",
    buildUrl: buildHepsiemlakSearchUrl,
  });
}

function createEmlakjetSearchButton() {
  return createComparablePortalButton({
    label: "Emlakjet",
    initials: "EJ",
    className: "emlakjet-search-button",
    title: "Konu taşınmazın KML merkezinin yaklaşık 3 km çevresindeki Emlakjet ilanlarını açar.",
    buildUrl: buildEmlakjetSearchUrl,
  });
}

function buildSahibindenSearchUrl() {
  const city = buildSahibindenLocationSlugPart(state.fields.titleCity || state.fields.city);
  const district = buildSahibindenLocationSlugPart(state.fields.titleDistrict || state.fields.district);
  const neighborhood = buildSahibindenNeighborhoodSlug(state.fields.titleNeighborhood || state.fields.neighborhood);
  const bounds = buildSahibindenMapBounds(getSahibindenSubjectCentroid());
  const category = getSahibindenCategorySlug();
  const subjectPoint = getSahibindenSubjectCentroid();
  if (subjectPoint && bounds) {
    // Sahibinden liste rotası geoLocation_* parametrelerini yok sayıp il
    // geneline dönebilir. Harita rotası dört köşe sınırını gerçekten işler.
    const query = new URLSearchParams({
      geoLocation_longitude_east: bounds.east.toFixed(6),
      geoLocation_latitude_north: bounds.north.toFixed(6),
      geoLocation_latitude_south: bounds.south.toFixed(6),
      geoLocation_longitude_west: bounds.west.toFixed(6),
    });
    return `https://www.sahibinden.com/haritada-emlak-arama/${category}?${query.toString()}`;
  }
  const base = `https://www.sahibinden.com/${category}`;
  // Sahibinden mahalle rotalarında ilçe/semt parçası da bulunuyor. Uygulamada
  // ayrı bir semt alanı olmadığından ilçe adı semt karşılığı olarak kullanılır.
  // viewType=map ile ilanlar harita görünümünde açılır.
  if (city && district && neighborhood) return `${base}/${city}-${district}-${district}-${neighborhood}?viewType=map`;
  if (city && district) return `${base}/${city}-${district}?viewType=map`;
  if (city) return `${base}/${city}?viewType=map`;
  return `${base}?viewType=map`;
}
function createSahibindenSearchButton() {
  return createComparablePortalButton({
    label: "Sahibinden.com",
    initials: "S",
    className: "sahibinden-search-button",
    title: "Konu taşınmazın KML merkezinin yaklaşık 3 km çevresindeki Sahibinden ilanlarını harita görünümünde açar.",
    buildUrl: buildSahibindenSearchUrl,
  });
}

function createComparablesVerticalEditor(section) {
  const wrapper = document.createElement("div");
  wrapper.className = "subsection is-detail comparables-excel-editor";

  const headingRow = document.createElement("div");
  headingRow.className = "subsection-table-head";
  headingRow.innerHTML = `<h4>${formatUiHeading(section.table.title)}</h4>`;

  const addButton = document.createElement("button");
  addButton.type = "button";
  addButton.className = "mini-button";
  addButton.textContent = "Emsal ekle";
  addButton.addEventListener("click", () => {
    const viewMode = getComparableViewMode();
    getComparableRows().push({
      _comparablesVersion: 2,
      c23: viewMode === "land" ? "Arsa" : "Konut",
    });
    autosave();
    renderSection();
  });
  const portalGroup = document.createElement("div");
  portalGroup.className = "comparable-portal-group";
  portalGroup.append(createSahibindenSearchButton(), createHepsiemlakSearchButton(), createEmlakjetSearchButton());
  headingRow.append(portalGroup, createComparableViewModeControl(), createComparableRowLabelsToggle(), addButton);

  const rows = getComparableRows();
  const viewMode = getComparableViewMode();
  const visibleRows = getComparableRowsForView(rows, viewMode);
  const showRowLabels = areComparableRowLabelsVisible();

  if (!rows.length) {
    const emptyLine = document.createElement("div");
    emptyLine.className = "encumbrance-empty-line";
    emptyLine.textContent = "Henüz emsal eklenmedi. Yeni kayıt için Emsal ekle düğmesini kullanın.";
    wrapper.append(headingRow, emptyLine, createComparableMarketAnalysisPanel(), createComparableLocationSketchPanel(), createComparableValuationSummaryPanel());
    return wrapper;
  }

  if (!visibleRows.length) {
    const emptyLine = document.createElement("div");
    emptyLine.className = "encumbrance-empty-line";
    emptyLine.textContent = "Bu görünümde emsal bulunmuyor. Bu türe ait yeni kayıt için Emsal ekle düğmesini kullanın.";
    wrapper.append(headingRow, emptyLine, createComparableMarketAnalysisPanel(), createComparableLocationSketchPanel(), createComparableValuationSummaryPanel());
    return wrapper;
  }

  const shell = document.createElement("div");
  shell.className = "table-shell comparables-matrix-shell";
  const topScroll = document.createElement("div");
  topScroll.className = "comparables-top-scroll";
  const topScrollInner = document.createElement("div");
  topScrollInner.className = "comparables-top-scroll-inner";
  topScroll.append(topScrollInner);
  const table = document.createElement("table");
  table.className = `comparables-matrix-table${showRowLabels ? "" : " is-row-labels-hidden"}`;

  const thead = document.createElement("thead");
  const headerCells = visibleRows.map(({ index: rowIndex }, displayIndex) => `
    <th>
      <div class="comparable-column-head">
        <span>Emsal ${displayIndex + 1}</span>
        <div class="comparable-column-actions">
          <button type="button" class="mini-button comparable-copy-button" data-comparable-copy="${rowIndex}" aria-label="Emsali sonraki sütuna kopyala">Kopyala</button>
          <button type="button" class="mini-button comparable-reset-button" data-comparable-reset="${rowIndex}" aria-label="Emsali temizle">Reset</button>
          <button type="button" class="row-delete-button" data-comparable-delete="${rowIndex}" aria-label="Emsali sil">X</button>
        </div>
      </div>
    </th>
  `).join("");
  thead.innerHTML = `<tr>${showRowLabels ? '<th class="comparables-row-label-cell">Sıra No</th>' : ""}${headerCells}</tr>`;

  const tbody = document.createElement("tbody");
  getComparableDisplayFields(viewMode).forEach((field) => {
    const tr = document.createElement("tr");
    if (field.key === "c10") tr.dataset.comparableReasonRow = "true";
    if (showRowLabels) {
      const labelCell = document.createElement("th");
      labelCell.className = "comparables-row-label-cell";
      labelCell.textContent = formatUiHeading(field.label);
      tr.append(labelCell);
    }

    visibleRows.forEach(({ row, index: rowIndex }) => {
      const td = document.createElement("td");
      td.append(createComparableMatrixCell(section, getComparableFieldForRow(field, row), row, rowIndex));
      tr.append(td);
    });
    tbody.append(tr);
  });

  table.append(thead, tbody);
  shell.append(table);
  topScrollInner.style.width = `${table.scrollWidth || 1180}px`;
  topScroll.addEventListener("scroll", () => {
    if (Math.abs(shell.scrollLeft - topScroll.scrollLeft) > 1) shell.scrollLeft = topScroll.scrollLeft;
  });
  shell.addEventListener("scroll", () => {
    if (Math.abs(topScroll.scrollLeft - shell.scrollLeft) > 1) topScroll.scrollLeft = shell.scrollLeft;
  });
  wrapper.append(headingRow, topScroll, shell);
  requestAnimationFrame(() => {
    topScrollInner.style.width = `${table.scrollWidth}px`;
  });
  updateComparableReasonRowsVisibility(shell);
  attachComparableColumnTabNavigation(shell, visibleRows);
  shell.querySelectorAll("[data-comparable-delete]").forEach((button) => {
    button.addEventListener("click", () => {
      const rowIndex = Number(button.dataset.comparableDelete);
      getComparableRows().splice(rowIndex, 1);
      autosave();
      renderSection();
    });
  });
  shell.querySelectorAll("[data-comparable-reset]").forEach((button) => {
    button.addEventListener("click", () => {
      const rowIndex = Number(button.dataset.comparableReset);
      getComparableRows()[rowIndex] = { _comparablesVersion: 2 };
      autosave();
      renderSection();
    });
  });
  shell.querySelectorAll("[data-comparable-copy]").forEach((button) => {
    button.addEventListener("click", () => {
      const rowIndex = Number(button.dataset.comparableCopy);
      const rows = getComparableRows();
      if (!rows[rowIndex]) return;
      if (!rows[rowIndex + 1]) rows.push({ _comparablesVersion: 2 });
      rows[rowIndex + 1] = cloneComparableRow(rows[rowIndex]);
      autosave();
      renderSection();
    });
  });

  wrapper.append(createComparableMarketAnalysisPanel(), createComparableLocationSketchPanel(), createComparableValuationSummaryPanel());
  return wrapper;
}

function createComparableMarketAnalysisPanel() {
  const wrapper = document.createElement("div");
  wrapper.className = "subsection is-detail comparable-market-analysis";
  wrapper.dataset.comparableMarketAnalysis = "true";
  const titleRow = document.createElement("div");
  titleRow.className = "subsection-table-head";
  titleRow.innerHTML = `<h4>Piyasa Analizi ve Emsal Değerlendirmesi</h4>`;
  const textarea = document.createElement("textarea");
  textarea.readOnly = true;
  textarea.className = "computed-input";
  textarea.rows = 7;
  textarea.dataset.comparableMarketAnalysisText = "true";
  textarea.value = buildComparableMarketAnalysisText();
  wrapper.append(titleRow, textarea);
  return wrapper;
}

// src/comparables/comparable-market-analysis.js AYRI bir modül (state'e
// erişemiyor) — kendi varyant gruplarını burada, app.js'te elle kaydeder.
registerVariantGroup("buildComparableMarketAnalysisText:p1", "Emsal Piyasa Analizi — Paragraf 1 (Konut/İşyeri)", 2);
registerVariantGroup("buildComparableMarketAnalysisText:p2", "Emsal Piyasa Analizi — Paragraf 2 (Konut/İşyeri)", 2);
registerVariantGroup("buildComparableMarketAnalysisText:p3", "Emsal Piyasa Analizi — Paragraf 3, koşullu (Konut/İşyeri)", 2);
registerVariantGroup("buildLandComparableMarketAnalysisText:p1", "Emsal Piyasa Analizi — Paragraf 1 (Arsa/Tarla)", 2);
registerVariantGroup("buildLandComparableMarketAnalysisText:p2", "Emsal Piyasa Analizi — Paragraf 2 (Arsa/Tarla)", 2);
registerVariantGroup("buildLandComparableMarketAnalysisText:p3", "Emsal Piyasa Analizi — Paragraf 3, koşullu (Arsa/Tarla)", 2);

function refreshComparableMarketAnalysisPanel() {
  const textarea = document.querySelector("[data-comparable-market-analysis-text]");
  if (!textarea) return;
  textarea.value = buildComparableMarketAnalysisText();
}

function buildComparableMarketAnalysisText() {
  if (!globalThis.ComparableMarketAnalysis) return "";
  const text = globalThis.ComparableMarketAnalysis.buildComparableMarketAnalysisText({
    fields: state.fields || {},
    rows: getComparableRows(),
    selectVariant,
    // Kullanıcı talebi (2026-08-19, 2026-08-20'de TÜM mülkiyet türlerine
    // genişletildi): Çoklu Talep raporlarında (isComparablesSharedAcrossUnits)
    // modül ÇOĞUL varyantları kullanır — hem Arsa/Tarla dalı
    // (buildLandComparableMarketAnalysisText) hem genel/Konut-İşyeri dalı
    // (buildComparableMarketAnalysisText) artık isMultiUnit'e bakıyor.
    isMultiUnit: isComparablesSharedAcrossUnits(),
  });
  const furnishedMarketNote = buildComparableFurnishedMarketNote();
  const fullText = [text, furnishedMarketNote].filter(Boolean).join("\n\n");
  state.fields.comparableMarketAnalysisText = fullText;
  return fullText;
}

