// Kullanıcı talebi: "kullanıcı emsal haritası üzerinden etiketleri istediği
// yere sürüklese ancak emsal ve konu taşınmaz noktaları aynı kalacak" —
// etiketin (metin kutusunun) kullanıcı tarafından elle bırakıldığı konum,
// {{lat,lng}} olarak id'ye (subject / comparable-<index>) göre saklanır.
// Nokta/marker'ın kendisi HER ZAMAN gerçek koordinattan (subjectPoint/
// comparablePoints) gelir — burada değişmez.
function getComparableSketchLabelOverride(id) {
  const stored = state.sourceValues?.comparableSketchLabelOverrides?.[id];
  if (!stored || !Number.isFinite(Number(stored.lat)) || !Number.isFinite(Number(stored.lng))) return null;
  return { lat: Number(stored.lat), lng: Number(stored.lng) };
}

function setComparableSketchLabelOverride(id, latlng) {
  if (!id || !latlng) return;
  state.sourceValues.comparableSketchLabelOverrides = state.sourceValues.comparableSketchLabelOverrides || {};
  state.sourceValues.comparableSketchLabelOverrides[id] = { lat: Number(latlng.lat), lng: Number(latlng.lng) };
  autosave();
}

function resetComparableSketchLabelOverrides() {
  state.sourceValues.comparableSketchLabelOverrides = {};
  autosave();
}

function renderComparableLocationSketchMap(wrapper) {
  const panel = wrapper.querySelector("[data-comparable-location-sketch-map]");
  if (!panel) return;

  const subjectPoint = getComparableSubjectPoint();
  const comparablePoints = getComparableSketchPoints();
  const kmlRecords = getTitleUnitKmlRecordsForMap();
  if (!isLeafletReady()) {
    panel.innerHTML = `<div class="map-placeholder">Harita kütüphanesi yüklenemedi.</div>`;
    return;
  }
  if (!subjectPoint) {
    panel.innerHTML = `<div class="map-placeholder">Kroki için önce Adres ve Konum bölümünde taşınmaz konumu işaretlenmeli.</div>`;
    return;
  }

  if (wrapper._comparableSketchMap?.remove) {
    wrapper._comparableSketchMap.remove();
    wrapper._comparableSketchMap = null;
  }
  panel.innerHTML = "";
  const leaflet = window.L;
  const map = leaflet.map(panel, getLeafletInteractionOptions({ forceDraggable: true })).setView(subjectPoint, 15);
  wrapper._comparableSketchMap = map;
  getLeafletTileLayer().addTo(map);

  kmlRecords.forEach((record, recordIndex) => {
    leaflet.polygon(record.parsed.coordinates.map((point) => [point.lat, point.lng]), {
      color: recordIndex === 0 ? "#d92525" : "#2563eb",
      weight: 3,
      opacity: 0.95,
      fillColor: recordIndex === 0 ? "#d92525" : "#2563eb",
      fillOpacity: 0.12,
    }).addTo(map);
  });

  const boundsPoints = [subjectPoint];
  const subjectEntries = getKmlMapSubjectEntries(kmlRecords);
  const subjectMarkers = new Map();
  subjectEntries.forEach((subject) => {
    const record = kmlRecords.find((item) => item.index === subject.index);
    const point = subject.index === state.activeTitleUnitIndex
      ? subjectPoint
      : record?.parsed?.centroid
        ? [Number(record.parsed.centroid.lat), Number(record.parsed.centroid.lng)]
        : subjectPoint;
    boundsPoints.push(point);
    subjectMarkers.set(subject.index, leaflet.marker(point).addTo(map));
  });
  if (!subjectEntries.length) {
    subjectMarkers.set(state.activeTitleUnitIndex, leaflet.marker(subjectPoint).addTo(map));
  }
  // id: getComparableSketchLabelOverride/setComparableSketchLabelOverride'in
  // anahtarı — kullanıcı bu etiketi sürükleyip bıraktığında konumu bu id
  // altında kalıcı olarak saklanır (nokta/marker'ın kendisi HER ZAMAN
  // subjectPoint/item.point'ten gelir, değişmez).
  const labelEntries = subjectEntries.length
    ? subjectEntries.map((subject) => ({
      id: subject.index === state.activeTitleUnitIndex ? "subject" : `subject-${subject.index}`,
      kind: "subject",
      latlng: subjectMarkers.get(subject.index).getLatLng(),
      text: subject.text,
    }))
    : [{ id: "subject", kind: "subject", latlng: subjectPoint, text: "KONU TAŞINMAZ" }];

  comparablePoints.forEach((item) => {
    boundsPoints.push(item.point);
    leaflet.circleMarker(item.point, {
      radius: 8,
      color: "#0f766e",
      weight: 2,
      fillColor: "#14b8a6",
      fillOpacity: 0.95,
    }).addTo(map);
    labelEntries.push({ id: `comparable-${item.index}`, kind: "comparable", latlng: item.point, text: `Emsal ${item.index + 1}` });
  });

  if (!comparablePoints.length) {
    const notice = leaflet.control({ position: "bottomleft" });
    notice.onAdd = () => {
      const div = leaflet.DomUtil.create("div", "comparable-sketch-notice");
      div.textContent = "Haritadan işaretlenmiş emsal konumu yok.";
      return div;
    };
    notice.addTo(map);
  }

  if (boundsPoints.length > 1) {
    map.fitBounds(leaflet.latLngBounds(boundsPoints), {
      padding: [78, 78],
      maxZoom: 17,
    });
  }
  renderMapLeaderLabels(map, leaflet, labelEntries, {
    draggable: true,
    getLabelOverride: getComparableSketchLabelOverride,
    onLabelDragEnd: setComparableSketchLabelOverride,
  });
  window.setTimeout(() => map.invalidateSize(), 0);
}

const sketchLabelMeasureContext = document.createElement("canvas").getContext("2d");

function measureSketchLabelWidth(text, font) {
  sketchLabelMeasureContext.font = font;
  return sketchLabelMeasureContext.measureText(String(text || "")).width;
}

// Ekran haritasında etiketleri, kendi marker'larından kaydırılmış divIcon'lar
// olarak çizer ve leader çizgisiyle bağlar; çakışma-önleyen yerleşim (layoutSketchLabels)
// yakın konumlarda üst üste binmeyi engeller. Zoom/pan'de yeniden hesaplanır.
// entries: [{ id?, kind:'subject'|<diğer>, latlng, text, color? }]
// options.draggable: true ise etiketler elle sürüklenebilir (NOKTA/marker
// SABİT kalır, yalnızca etiket metninin konumu değişir — kullanıcı talebi:
// "emsal ve konu taşınmaz noktaları aynı kalacak. kullanıcı düzenlemesine
// göre görsel oluşsa"). options.getLabelOverride(id) daha önce kullanıcının
// elle bıraktığı bir konum varsa {lat,lng} döner (varsa o anchor otomatik
// yerleşimden HARİÇ tutulur, kullanıcının seçimi korunur).
// options.onLabelDragEnd(id, {lat,lng}) sürükleme bittiğinde çağrılır.
function renderMapLeaderLabels(map, leaflet, entries, options = {}) {
  if (!entries.length) return { relayout: () => {}, layer: null };
  const layer = leaflet.layerGroup().addTo(map);
  const relayout = () => {
    if (!map._container) return;
    layer.clearLayers();
    const size = map.getSize();
    const anchors = entries.map((entry) => {
      const isSubject = entry.kind === "subject";
      const font = isSubject ? "800 12px Arial" : "700 11px Arial";
      const point = map.latLngToContainerPoint(entry.latlng);
      const override = entry.id ? options.getLabelOverride?.(entry.id) : null;
      const overridePoint = override ? map.latLngToContainerPoint([override.lat, override.lng]) : null;
      return {
        id: entry.id,
        kind: isSubject ? "subject" : "place",
        latlng: entry.latlng,
        text: entry.text,
        x: point.x,
        y: point.y,
        w: Math.min(measureSketchLabelWidth(entry.text, font) + (isSubject ? 24 : 20), 240),
        h: isSubject ? 26 : 22,
        markerColor: isSubject ? "#c81e1e" : (entry.color || "#0f766e"),
        manualCx: overridePoint?.x,
        manualCy: overridePoint?.y,
      };
    });
    // Kullanıcının elle konumlandırdığı etiketler otomatik yerleşimden
    // HARİÇ tutulur (kendi seçimleri korunur); yalnızca konumlandırılmamış
    // olanlar çakışma-önleyen otomatik algoritmadan geçer.
    const autoAnchors = anchors.filter((a) => !Number.isFinite(a.manualCx));
    if (autoAnchors.length) layoutSketchLabels(autoAnchors, size.x, size.y);
    anchors.forEach((a) => {
      if (Number.isFinite(a.manualCx)) { a.cx = a.manualCx; a.cy = a.manualCy; }
    });
    anchors.forEach((a) => {
      const labelLatLng = map.containerPointToLatLng([a.cx, a.cy]);
      const line = leaflet.polyline([a.latlng, labelLatLng], {
        color: a.markerColor,
        weight: 1.6,
        opacity: 0.9,
      }).addTo(layer);
      const isSubject = a.kind === "subject";
      const styleAttr = isSubject ? "" : ` style="border-color:${a.markerColor};color:${a.markerColor}"`;
      const draggable = Boolean(options.draggable && a.id);
      const icon = leaflet.divIcon({
        className: `sketch-leader-label${isSubject ? " is-subject" : ""}${draggable ? " is-draggable" : ""}`,
        html: `<span class="sketch-leader-label-inner"${styleAttr}>${escapeHtml(a.text)}</span>`,
        iconSize: [0, 0],
        iconAnchor: [0, 0],
      });
      const marker = leaflet.marker(labelLatLng, {
        icon,
        interactive: draggable,
        keyboard: false,
        draggable,
      }).addTo(layer);
      if (draggable) {
        marker.on("drag", () => {
          line.setLatLngs([a.latlng, marker.getLatLng()]);
        });
        marker.on("dragend", () => {
          const newLatLng = marker.getLatLng();
          options.onLabelDragEnd?.(a.id, { lat: newLatLng.lat, lng: newLatLng.lng });
        });
      }
    });
  };
  relayout();
  map.on("zoomend moveend", relayout);
  return { relayout, layer };
}

function getComparableSketchPoints() {
  return getComparableRows()
    .map((row, index) => ({ row, index, point: getComparableSavedPoint(row) }))
    .filter((item) => Array.isArray(item.point));
}

function saveComparableSketchForReport(wrapper, triggerButton) {
  const subjectPoint = getComparableSubjectPoint();
  const comparablePoints = getComparableSketchPoints();
  const parsed = getComparableSketchExportKml();
  if (!subjectPoint || !comparablePoints.length) {
    window.alert("Krokiyi rapora kaydetmek için konu taşınmaz ve en az bir emsal konumu gerekiyor.");
    return;
  }
  const center = getComparableSketchExportCenter(wrapper, subjectPoint, comparablePoints, parsed);
  const size = getMapExportCanvasSize("16:9", 1200);
  getSavedReportImageConfigs().comparables = {
    center,
    zoom: getComparableSketchExportZoom(wrapper, center, subjectPoint, comparablePoints, parsed, size.width, size.height),
    mode: normalizeMapMode(state.settings.mapMode),
    ratio: "16:9",
    savedAt: new Date().toISOString(),
  };
  autosave();
  if (triggerButton) triggerButton.textContent = "KROKİ KAYDEDİLDİ";
  setComparableSketchExportStatus(wrapper, "Emsal krokisi Word çıktıları için kaydedildi.");
}

async function exportComparableSketchAsJpeg(wrapper, triggerButton) {
  const subjectPoint = getComparableSubjectPoint();
  const comparablePoints = getComparableSketchPoints();
  const parsed = getComparableSketchExportKml();
  if (!subjectPoint && !comparablePoints.length && !parsed?.coordinates?.length) {
    window.alert("Emsal krokisi kaydı için önce taşınmaz veya emsal konumu gerekiyor.");
    return;
  }

  const originalButtonText = triggerButton?.textContent;
  if (triggerButton) {
    triggerButton.disabled = true;
    triggerButton.textContent = "JPEG HAZIRLANIYOR...";
  }
  setComparableSketchExportStatus(wrapper, "Emsal krokisi JPEG kaydı hazırlanıyor...");

  const canvas = document.createElement("canvas");
  const exportSize = getMapExportCanvasSize();
  canvas.width = exportSize.width;
  canvas.height = exportSize.height;
  const context = canvas.getContext("2d");
  const center = getComparableSketchExportCenter(wrapper, subjectPoint, comparablePoints, parsed);
  const zoom = getComparableSketchExportZoom(wrapper, center, subjectPoint, comparablePoints, parsed, canvas.width, canvas.height);
  const topLeft = latLngToWorldPixel(center[0], center[1], zoom);
  topLeft.x -= canvas.width / 2;
  topLeft.y -= canvas.height / 2;

  context.fillStyle = normalizeMapMode(state.settings.mapMode) === "street" ? "#eef2ef" : "#d8e2df";
  context.fillRect(0, 0, canvas.width, canvas.height);
  await drawExportTiles(context, canvas, topLeft, zoom, "base");
  await drawExportTiles(context, canvas, topLeft, zoom, "labels");
  drawExportKmlPolygons(context, getTitleUnitKmlRecordsForMap(), topLeft, zoom);
  drawExportPlaces(context, topLeft, zoom);
  drawExportComparableSketch(context, subjectPoint, comparablePoints, topLeft, zoom, parsed);

  try {
    const link = document.createElement("a");
    link.download = `emsal-konum-krokisi-${dateIsoToTr(new Date().toISOString().slice(0, 10))}.jpg`;
    link.href = canvas.toDataURL("image/jpeg", 0.92);
    document.body.appendChild(link);
    link.click();
    link.remove();
    setComparableSketchExportStatus(wrapper, "JPEG kaydedildi.");
  } catch (error) {
    try {
      drawExportFallbackBase(context, canvas);
      drawExportKmlPolygons(context, getTitleUnitKmlRecordsForMap(), topLeft, zoom);
      drawExportPlaces(context, topLeft, zoom);
      drawExportComparableSketch(context, subjectPoint, comparablePoints, topLeft, zoom, parsed);
      const fallbackLink = document.createElement("a");
      fallbackLink.download = `emsal-konum-krokisi-${dateIsoToTr(new Date().toISOString().slice(0, 10))}.jpg`;
      fallbackLink.href = canvas.toDataURL("image/jpeg", 0.92);
      document.body.appendChild(fallbackLink);
      fallbackLink.click();
      fallbackLink.remove();
      setComparableSketchExportStatus(wrapper, "Harita altlığı izin vermedi; yedek JPEG kaydedildi.", true);
    } catch (fallbackError) {
      console.warn("Emsal krokisi JPEG olarak kaydedilemedi.", fallbackError);
      setComparableSketchExportStatus(wrapper, "JPEG kaydedilemedi. Haritayı yenileyip tekrar deneyin.", true);
      window.alert("Emsal krokisi JPEG olarak kaydedilemedi. Harita altlığı bu işlem için izin vermedi.");
    }
  } finally {
    if (triggerButton) {
      triggerButton.disabled = false;
      triggerButton.textContent = originalButtonText || "EMSAL KROKİSİNİ JPEG OLARAK KAYDET";
    }
  }
}

function setComparableSketchExportStatus(wrapper, message, isWarning = false) {
  const status = wrapper?.querySelector("[data-comparable-sketch-export-status]");
  if (!status) return;
  status.textContent = message;
  status.classList.toggle("is-warning", Boolean(isWarning));
}

function getComparableSketchExportCenter(wrapper, subjectPoint, comparablePoints, parsed) {
  const mapCenter = wrapper?._comparableSketchMap?.getCenter?.();
  if (mapCenter) return [mapCenter.lat, mapCenter.lng];
  const points = getComparableSketchExportPoints(subjectPoint, comparablePoints, parsed);
  if (!points.length) return [40.1826, 29.0665];
  const lats = points.map(([lat]) => lat);
  const lngs = points.map(([, lng]) => lng);
  return [
    (Math.min(...lats) + Math.max(...lats)) / 2,
    (Math.min(...lngs) + Math.max(...lngs)) / 2,
  ];
}

function getComparableSketchExportZoom(wrapper, center, subjectPoint, comparablePoints, parsed, canvasWidth, canvasHeight) {
  const mapZoom = wrapper?._comparableSketchMap?.getZoom?.();
  if (Number.isFinite(mapZoom)) return mapZoom;
  const points = getComparableSketchExportPoints(subjectPoint, comparablePoints, parsed);
  if (points.length < 2) return 16;

  for (let zoom = 18; zoom >= 9; zoom -= 1) {
    const projected = points.map(([lat, lng]) => latLngToWorldPixel(lat, lng, zoom));
    const width = Math.max(...projected.map((point) => point.x)) - Math.min(...projected.map((point) => point.x));
    const height = Math.max(...projected.map((point) => point.y)) - Math.min(...projected.map((point) => point.y));
    if (width <= canvasWidth * 0.82 && height <= canvasHeight * 0.76) return zoom;
  }
  return 9;
}

function getComparableSketchExportPoints(subjectPoint, comparablePoints, parsed) {
  return [
    ...(parsed?.coordinates || []).map((point) => [Number(point.lat), Number(point.lng)]),
    ...(subjectPoint ? [subjectPoint] : []),
    ...comparablePoints.map((item) => item.point),
    ...getMapLabelPlaces().map((place) => [Number(place.lat), Number(place.lng)]),
  ].filter(([lat, lng]) => Number.isFinite(lat) && Number.isFinite(lng));
}

// Çakışma-önleyen etiket yerleşimi (piksel uzayında). Etiket merkezleri önce
// küme merkezinden dışa doğru itilir, ardından birbirleriyle ve marker'larla
// çakışmayacak şekilde ayrıştırılır. Böylece yakın konumlarda etiketler üst üste
// binmez; her etiket kendi marker'ına leader çizgisiyle bağlanır.
// hardPoints: anchor'ların KENDİ noktalarına EK OLARAK hiçbir etiket
// kutusunun üstüne binmemesi gereken ekstra "sert" noktalar (ör. konu
// taşınmazın gerçek koordinatı, etiket artık KML sınırına bağlansa bile).
// Kullanıcı talebi: "Konu taşınmaz ve Emsal yazıları ... noktalarının hiç
// bir şekilde üstüne gelmemeli" — anchor-anchor (birbirini örtme) VE
// anchor-nokta (bir markerı örtme) çakışmaları AYNI yinelemeli döngüde
// birlikte çözülür (ayrı, sıralı bir "son düzeltme" geçişi öncekini
// bozabildiği için — 2026-08-05 kullanıcı geri bildirimi: iki etiket
// üst üste binmişti çünkü ayrı geçiş anchor-anchor ayrımını bozuyordu).
function layoutSketchLabels(anchors, canvasWidth, canvasHeight, hardPoints = []) {
  const count = anchors.length;
  if (!count) return anchors;
  const centerX = anchors.reduce((sum, a) => sum + a.x, 0) / count;
  const centerY = anchors.reduce((sum, a) => sum + a.y, 0) / count;
  anchors.forEach((a, index) => {
    let dirX = Number.isFinite(a.dirX) ? a.dirX : a.x - centerX;
    let dirY = Number.isFinite(a.dirY) ? a.dirY : a.y - centerY;
    let length = Math.hypot(dirX, dirY);
    if (length < 1) {
      const angle = (index / count) * Math.PI * 2 - Math.PI / 2;
      dirX = Math.cos(angle);
      dirY = Math.sin(angle);
      length = 1;
    }
    const baseDistance = Number.isFinite(a.pushDistance) ? a.pushDistance : 36 * (a.scale || 1);
    const distance = baseDistance + a.h / 2;
    a.cx = a.x + (dirX / length) * distance;
    a.cy = a.y + (dirY / length) * distance;
  });

  const allHardPoints = [
    ...anchors.map((a) => ({ x: a.x, y: a.y })),
    ...hardPoints,
  ].filter((p) => p && Number.isFinite(p.x) && Number.isFinite(p.y));

  // Kullanıcı geri bildirimi (2026-08-05): "emsal 1 ve 2 üstüste binmiş" —
  // önceki "her yinelemede TÜM çakışmaları aynı anda hafifçe it" yaklaşımı
  // salınıma (bir kısıtı çözerken başka birini bozma) düşüp bazı
  // düzenlerde YARIM çözümde takılabiliyordu. Artık HER SEFERİNDE tek bir
  // çakışmayı (anchor-anchor veya anchor-nokta) TAMAMEN/kesin olarak
  // çözüp bir sonrakine geçen basit ama GARANTİLİ yakınsayan bir döngü
  // kullanılıyor — bir düzeltme asla bir öncekini yarım bırakmaz.
  function findWorstOverlap() {
    for (let i = 0; i < count; i += 1) {
      const a = anchors[i];
      for (let j = i + 1; j < count; j += 1) {
        const b = anchors[j];
        const dx = a.cx - b.cx;
        const dy = a.cy - b.cy;
        const overlapX = (a.w + b.w) / 2 + 10 - Math.abs(dx);
        const overlapY = (a.h + b.h) / 2 + 8 - Math.abs(dy);
        if (overlapX > 0 && overlapY > 0) return { kind: "anchor", i, j, dx, dy, overlapX, overlapY };
      }
      const halfW = a.w / 2 + 10;
      const halfH = a.h / 2 + 8;
      for (let k = 0; k < allHardPoints.length; k += 1) {
        const p = allHardPoints[k];
        const dx = a.cx - p.x;
        const dy = a.cy - p.y;
        if (Math.abs(dx) < halfW && Math.abs(dy) < halfH) {
          return { kind: "point", i, dx, dy, overlapX: halfW - Math.abs(dx), overlapY: halfH - Math.abs(dy) };
        }
      }
    }
    return null;
  }

  // Kanvas kenarına yaslanan bir kutu, çakışma çözüldükten SONRA tek
  // seferlik kenar kırpma (clamp) ile geri itilirse çözülmüş çakışma
  // sessizce YENİDEN oluşabiliyordu (iki kutu aynı kenara yaslanıp
  // birbirine değebiliyordu). Bu yüzden kenar sınırı da her itmeden
  // hemen sonra uygulanan bir kısıt — findWorstOverlap HER ZAMAN zaten
  // kenara-kırpılmış konumlar üzerinden karar veriyor.
  function clampAnchor(a) {
    a.cx = Math.max(a.w / 2 + 6, Math.min(a.cx, canvasWidth - a.w / 2 - 6));
    a.cy = Math.max(a.h / 2 + 6, Math.min(a.cy, canvasHeight - a.h / 2 - 6));
  }
  anchors.forEach(clampAnchor);

  let guard = 0;
  let noProgressStreak = 0;
  let conflict = findWorstOverlap();
  while (conflict && guard < 4000) {
    guard += 1;
    let progressed = false;
    if (conflict.kind === "anchor") {
      const a = anchors[conflict.i];
      const b = anchors[conflict.j];
      const applyAxis = (useX) => {
        const beforeAx = a.cx, beforeAy = a.cy, beforeBx = b.cx, beforeBy = b.cy;
        if (useX) {
          const push = (conflict.dx >= 0 ? 1 : -1) * (conflict.overlapX / 2 + 1);
          a.cx += push;
          b.cx -= push;
        } else {
          const push = (conflict.dy >= 0 ? 1 : -1) * (conflict.overlapY / 2 + 1);
          a.cy += push;
          b.cy -= push;
        }
        clampAnchor(a);
        clampAnchor(b);
        return a.cx !== beforeAx || a.cy !== beforeAy || b.cx !== beforeBx || b.cy !== beforeBy;
      };
      progressed = applyAxis(conflict.overlapX < conflict.overlapY);
      // Tercih edilen eksen kanvas kenarına kilitlenmişse (clamp itmeyi
      // tamamen yuttuysa) diğer ekseni dene — kullanıcı geri bildirimi
      // (2026-08-05): kenara yaslı bir etiket aynı çakışmada SONSUZ
      // döngüye girip hiç ilerleme kaydetmeden 4000 turu tüketebiliyordu.
      if (!progressed) progressed = applyAxis(!(conflict.overlapX < conflict.overlapY));
    } else {
      const a = anchors[conflict.i];
      const applyAxis = (useX) => {
        const beforeX = a.cx, beforeY = a.cy;
        if (useX) a.cx += (conflict.dx >= 0 ? 1 : -1) * (conflict.overlapX + 1);
        else a.cy += (conflict.dy >= 0 ? 1 : -1) * (conflict.overlapY + 1);
        clampAnchor(a);
        return a.cx !== beforeX || a.cy !== beforeY;
      };
      progressed = applyAxis(conflict.overlapX < conflict.overlapY);
      if (!progressed) progressed = applyAxis(!(conflict.overlapX < conflict.overlapY));
    }
    // Ne tercih edilen ne de alternatif eksen ilerleme sağlamıyorsa
    // (kutu kanvasın hiçbir yönünde kaçacak yeri yoksa) art arda
    // birkaç kez bunu görürsek sonsuz döngüde takılmak yerine en iyi
    // çaba ile döngüden çık — gerçekten yer olmayan patolojik durumlar
    // için bir güvenlik supabı, normal akışta tetiklenmez.
    noProgressStreak = progressed ? 0 : noProgressStreak + 1;
    if (noProgressStreak > 8) break;
    conflict = findWorstOverlap();
  }
  anchors.forEach((a) => {
    a.lx = a.cx - a.w / 2;
    a.ly = a.cy - a.h / 2;
  });
  return anchors;
}

function drawSketchLeaderAndMarker(context, a) {
  if (!Number.isFinite(a.x) || !Number.isFinite(a.y)) return;
  const scale = a.scale || 1;
  context.save();
  context.setLineDash(a.leaderDashed ? [14, 10] : []);
  context.strokeStyle = a.leaderColor || a.markerColor;
  context.lineWidth = a.leaderWidth || (a.kind === "subject" ? 4 : 3) * scale;
  context.beginPath();
  context.moveTo(a.x, a.y);
  context.lineTo(a.cx, a.cy);
  context.stroke();

  if (a.leaderDashed) {
    // Kesikli OK ucu — etiketten sınıra doğru çizilen çizginin sınır
    // ucunda (a.x, a.y) bir ok başı (kullanıcı talebi: "kesik çizgili
    // kırmızı ok ile konu taşınmaz yazısı bağlansın").
    context.setLineDash([]);
    const angle = Math.atan2(a.y - a.cy, a.x - a.cx);
    const headLength = 14 * scale;
    context.beginPath();
    context.moveTo(a.x, a.y);
    context.lineTo(a.x - headLength * Math.cos(angle - Math.PI / 7), a.y - headLength * Math.sin(angle - Math.PI / 7));
    context.lineTo(a.x - headLength * Math.cos(angle + Math.PI / 7), a.y - headLength * Math.sin(angle + Math.PI / 7));
    context.closePath();
    context.fillStyle = a.leaderColor || a.markerColor;
    context.fill();
    context.restore();
    return;
  }

  context.beginPath();
  context.fillStyle = "#ffffff";
  context.arc(a.x, a.y, a.markerRadius + 3 * scale, 0, Math.PI * 2);
  context.fill();
  context.beginPath();
  context.fillStyle = a.markerColor;
  context.arc(a.x, a.y, a.markerRadius, 0, Math.PI * 2);
  context.fill();
  context.restore();
}

function drawSketchLabelBox(context, a) {
  if (!Number.isFinite(a.cx) || !Number.isFinite(a.cy)) return;
  const scale = a.scale || 1;
  context.save();
  context.beginPath();
  context.fillStyle = a.fill;
  context.strokeStyle = a.borderColor;
  context.lineWidth = a.borderWidth || (a.kind === "subject" ? 5 : 2) * scale;
  context.roundRect(a.lx, a.ly, a.w, a.h, a.cornerRadius || (a.kind === "subject" ? 12 : 10) * scale);
  context.fill();
  context.stroke();
  context.fillStyle = a.textColor;
  context.font = a.font;
  context.textBaseline = "middle";
  const padX = a.padX || (a.kind === "subject" ? 20 : 12) * scale;
  context.fillText(a.text, a.lx + padX, a.cy + 1, a.w - padX * 2);
  context.restore();
}

// KML sınırının, verilen noktadan (genelde emsal kümesinin merkezi) EN UZAK
// köşesini döner — "Konu Taşınmaz" etiketini emsal kalabalığından uzağa,
// açık alana yönlendirmek için kullanılır (bkz. drawExportComparableSketch).
function pickKmlBoundaryAnchorPixel(parsed, topLeft, zoom, awayFromPoint) {
  const coordinates = Array.isArray(parsed?.coordinates) ? parsed.coordinates : [];
  if (!coordinates.length) return null;
  const pixels = coordinates
    .map((point) => projectExportPoint(Number(point.lat), Number(point.lng), topLeft, zoom))
    .filter((p) => Number.isFinite(p.x) && Number.isFinite(p.y));
  if (!pixels.length) return null;
  if (!awayFromPoint) return pixels[0];
  let best = pixels[0];
  let bestDist = -Infinity;
  pixels.forEach((p) => {
    const d = Math.hypot(p.x - awayFromPoint.x, p.y - awayFromPoint.y);
    if (d > bestDist) { bestDist = d; best = p; }
  });
  return best;
}

function pickKmlBoundaryNearestPixel(parsed, topLeft, zoom, targetPoint) {
  const coordinates = Array.isArray(parsed?.coordinates) ? parsed.coordinates : [];
  if (!coordinates.length || !targetPoint) return null;
  const pixels = coordinates
    .map((point) => projectExportPoint(Number(point.lat), Number(point.lng), topLeft, zoom))
    .filter((point) => Number.isFinite(point.x) && Number.isFinite(point.y));
  if (!pixels.length) return null;
  return pixels.reduce((nearest, point) => {
    const pointDistance = Math.hypot(point.x - targetPoint.x, point.y - targetPoint.y);
    const nearestDistance = Math.hypot(nearest.x - targetPoint.x, nearest.y - targetPoint.y);
    return pointDistance < nearestDistance ? point : nearest;
  });
}
function drawExportComparableSketch(context, subjectPoint, comparablePoints, topLeft, zoom, parsed) {
  const subjectPixel = subjectPoint ? projectExportPoint(subjectPoint[0], subjectPoint[1], topLeft, zoom) : null;
  const comps = comparablePoints.map((item) => ({
    item,
    pixel: projectExportPoint(item.point[0], item.point[1], topLeft, zoom),
  }));

  const compCenter = comps.length
    ? {
      x: comps.reduce((sum, c) => sum + c.pixel.x, 0) / comps.length,
      y: comps.reduce((sum, c) => sum + c.pixel.y, 0) / comps.length,
    }
    : { x: context.canvas.width / 2, y: context.canvas.height / 2 };
  const kmlRecordsForSketch = typeof getTitleUnitKmlRecordsForMap === "function"
    ? getTitleUnitKmlRecordsForMap()
    : [];
  const compactKmlLabel = typeof getCompactKmlSubjectLabel === "function"
    ? getCompactKmlSubjectLabel
    : (record, fallback = "KONU TAŞINMAZ") => {
      const blockNo = String(record?.parsed?.fields?.blockNo || "").trim();
      const parcelNo = String(record?.parsed?.fields?.parcelNo || "").trim();
      return blockNo && parcelNo ? `${blockNo}/${parcelNo}` : fallback;
    };
  const nearestKmlBoundary = typeof pickKmlBoundaryNearestPixel === "function"
    ? pickKmlBoundaryNearestPixel
    : (boundary, boundaryTopLeft, boundaryZoom, targetPoint) => pickKmlBoundaryAnchorPixel(boundary, boundaryTopLeft, boundaryZoom, targetPoint);
  const kmlSubjectEntries = typeof getKmlMapSubjectEntries === "function"
    ? getKmlMapSubjectEntries(kmlRecordsForSketch)
    : [];
  const activeKmlRecord = kmlRecordsForSketch.find((record) => record.index === state.activeTitleUnitIndex);
  const activeSubjectLabel = kmlSubjectEntries.find((entry) => entry.index === state.activeTitleUnitIndex)?.text
    || compactKmlLabel(activeKmlRecord, "KONU TAŞINMAZ");

  // Etiket anchor'ları
  const anchors = [];
  let subjectAnchorPixel = null;
  if (subjectPixel) {
    // Kullanıcı talebi: "Kml sınırlarına kesik çizgili kırmızı ok ile konu
    // taşınmaz yazısı bağlansın" — devasa kutu artık noktanın TAM ÜSTÜNDE
    // değil, KML sınırının (emsal kümesinden en uzak) bir köşesine kesikli
    // kırmızı OK ile bağlanıyor; sınır poligonu zaten kırmızı dolgulu
    // çizildiğinden (drawExportKmlPolygon) ayrı bir nokta işaretine gerek
    // yok. KML yoksa (eski davranış) doğrudan koordinat noktasına bağlanır.
    subjectAnchorPixel = nearestKmlBoundary(activeKmlRecord?.parsed || parsed, topLeft, zoom, subjectPixel) || subjectPixel;
    context.font = "900 13px Arial";
    // Kullanıcı talebi (2026-08-05): "konu taşınmaz daha uzağa, emsal
    // yazılarının olmadığı bir kısma konumlanmalıydı" — kaçış yönü genel
    // ağırlık merkezine göre DEĞİL, doğrudan emsal kümesinin merkezinden
    // (compCenter) UZAĞA doğru zorlanır, ve başlangıç itme mesafesi
    // (pushDistance) diğer etiketlerden çok daha büyük tutulur.
    const escapeDirX = subjectAnchorPixel.x - compCenter.x;
    const escapeDirY = subjectAnchorPixel.y - compCenter.y;
    anchors.push({
      id: "subject",
      kind: "subject",
      x: subjectAnchorPixel.x,
      y: subjectAnchorPixel.y,
      text: activeSubjectLabel,
      w: Math.min(context.measureText(activeSubjectLabel).width + 16, 220),
      h: 26,
      font: "900 13px Arial",
      fill: "#c81e1e",
      textColor: "#ffffff",
      borderColor: "#ffffff",
      markerColor: "#c81e1e",
      leaderColor: "#c81e1e",
      leaderDashed: true,
      markerRadius: 4,
      dirX: escapeDirX,
      dirY: escapeDirY,
      pushDistance: 75,
    });
  }
  kmlSubjectEntries
    .filter((entry) => entry.index !== state.activeTitleUnitIndex)
    .forEach((entry) => {
      const record = kmlRecordsForSketch.find((item) => item.index === entry.index);
      const centroid = record?.parsed?.centroid;
      if (!centroid) return;
      const point = projectExportPoint(Number(centroid.lat), Number(centroid.lng), topLeft, zoom);
      const boundaryPoint = nearestKmlBoundary(record.parsed, topLeft, zoom, point) || point;
      const text = entry.text;
      context.font = "900 13px Arial";
      const escapeDirX = boundaryPoint.x - compCenter.x;
      const escapeDirY = boundaryPoint.y - compCenter.y;
      anchors.push({
        id: `subject-${entry.index}`,
        kind: "subject",
        x: boundaryPoint.x,
        y: boundaryPoint.y,
        text,
        w: Math.min(context.measureText(text).width + 16, 220),
        h: 26,
        font: "900 13px Arial",
        fill: "#c81e1e",
        textColor: "#ffffff",
        borderColor: "#ffffff",
        markerColor: "#c81e1e",
        leaderColor: "#c81e1e",
        leaderDashed: true,
        markerRadius: 4,
        dirX: escapeDirX,
        dirY: escapeDirY,
        pushDistance: 75,
      });
    });  comps.forEach(({ item, pixel }) => {
    const text = `Emsal ${item.index + 1}`;
    context.font = "700 22px Arial";
    anchors.push({
      id: `comparable-${item.index}`,
      kind: "comparable",
      x: pixel.x,
      y: pixel.y,
      text,
      w: Math.min(context.measureText(text).width + 24, 420),
      h: 42,
      font: "700 22px Arial",
      fill: "rgba(255, 255, 255, 0.94)",
      textColor: "#0f766e",
      borderColor: "#0f766e",
      markerColor: "#0f766e",
      markerRadius: 10,
    });
  });

  // Kullanıcı talebi: "kullanıcı emsal haritası üzerinden etiketleri
  // istediği yere sürüklese ... kullanıcı düzenlemesine göre görsel
  // oluşsa" — ekrandaki interaktif haritada (renderComparableLocationSketchMap)
  // elle bırakılmış bir etiket konumu varsa (getComparableSketchLabelOverride)
  // dışa aktarılan görsel de AYNI konumu kullanır; o anchor otomatik
  // çakışma-önleyen yerleşimden HARİÇ tutulur (kullanıcının seçimi asla
  // otomatik algoritma tarafından değiştirilmez). Nokta/marker'ın kendisi
  // (a.x/a.y, leader çizgisinin başladığı yer) HER ZAMAN gerçek koordinat.
  anchors.forEach((a) => {
    const override = a.id ? getComparableSketchLabelOverride(a.id) : null;
    if (!override) return;
    const overridePixel = projectExportPoint(override.lat, override.lng, topLeft, zoom);
    a.cx = overridePixel.x;
    a.cy = overridePixel.y;
    a.manualOverride = true;
  });
  const autoAnchors = anchors.filter((a) => !a.manualOverride);
  // subjectPixel (gerçek koordinat) anchor listesinde YOK artık (anchor
  // KML sınırına — subjectAnchorPixel'e — bağlı); bu yüzden ayrıca
  // "sert nokta" olarak geçiliyor ki hiçbir etiket onu da örtmesin.
  const extraHardPoints = [subjectPixel].filter(Boolean);
  if (autoAnchors.length) layoutSketchLabels(autoAnchors, context.canvas.width, context.canvas.height, extraHardPoints);
  anchors.forEach((a) => {
    if (!a.manualOverride) return;
    a.cx = Math.max(a.w / 2 + 6, Math.min(a.cx, context.canvas.width - a.w / 2 - 6));
    a.cy = Math.max(a.h / 2 + 6, Math.min(a.cy, context.canvas.height - a.h / 2 - 6));
    a.lx = a.cx - a.w / 2;
    a.ly = a.cy - a.h / 2;
  });
  anchors.forEach((a) => drawSketchLeaderAndMarker(context, a));
  anchors.forEach((a) => drawSketchLabelBox(context, a));
}

function cloneComparableRow(row) {
  const clone = {};
  comparableFields.forEach((field) => {
    if (field.computed) return;
    if (!Object.prototype.hasOwnProperty.call(row, field.key)) return;
    if (field.key === "workplaceFloors") {
      // Dizi referansı paylaşılırsa "Kopyala" ile oluşan yeni satırda kat
      // alan/oranı düzenlemesi orijinal satırı da değiştirir — derin kopya.
      clone.workplaceFloors = Array.isArray(row.workplaceFloors) ? row.workplaceFloors.map((entry) => ({ ...entry })) : [];
      return;
    }
    clone[field.key] = row[field.key];
  });
  clone._comparablesVersion = 2;
  return clone;
}

function getComparableRows() {
  let rows = state.tables.comparables;
  if (!Array.isArray(rows)) {
    rows = Array.from({ length: comparableDefaultRowCount }, () => ({ _comparablesVersion: 2 }));
  }
  rows = rows.map(migrateComparableRow);
  rows.forEach((row) => {
    if (isAgriculturalComparable(row)) {
      comparableTarlaZoningFieldKeys.forEach((key) => {
        row[key] = "";
      });
      row.c31Manual = "";
    }
  });
  rows = trimEmptyDefaultComparableRows(rows);
  state.tables.comparables = rows;
  return rows;
}

function trimEmptyDefaultComparableRows(rows) {
  if (rows.length <= comparableDefaultRowCount) return rows;
  const trimmedRows = [...rows];
  while (
    trimmedRows.length > comparableDefaultRowCount
    && isComparableRowEmpty(trimmedRows[trimmedRows.length - 1])
  ) {
    trimmedRows.pop();
  }
  return trimmedRows;
}

function isComparableRowEmpty(row = {}) {
  return comparableFields
    .filter((field) => !field.computed)
    .every((field) => {
      if (field.key === "workplaceFloors") {
        return !Array.isArray(row.workplaceFloors) || row.workplaceFloors.every((entry) => !String(entry?.area || "").trim());
      }
      return !String(row[field.key] || "").trim();
    });
}

function migrateComparableRow(row = {}) {
  if (row._comparablesVersion === 2) return row;
  const hasExpandedComparableData = comparableFields
    .filter((field) => Number(field.key.slice(1)) > 4)
    .some((field) => String(row[field.key] || "").trim());
  if (hasExpandedComparableData) {
    return { ...row, _comparablesVersion: 2 };
  }
  return {
    c0: row.c0 || "",
    c7: row.c1 || "",
    c12: row.c2 || "",
    c13: row.c2 || "",
    c15: row.c3 || "",
    c17: row.c4 || "",
    _comparablesVersion: 2,
  };
}

function createComparableMatrixCell(section, field, row, rowIndex) {
  const cell = document.createElement("div");
  cell.className = `comparable-matrix-cell${field.key === "c7" ? " comparable-location-cell" : ""}`;
  if (field.key === "c31") {
    syncComparableLandBuildableArea(row);
  }
  if (field.computed) {
    const computed = createComparableComputedControl(field, row, rowIndex);
    cell.append(computed);
    return cell;
  }
  if (field.type === "multiSelect") {
    cell.append(createComparableMultiSelectControl(field, row, rowIndex));
    return cell;
  }
  if (field.type === "workplaceFloorBreakdown") {
    cell.append(createComparableWorkplaceFloorBreakdown(row, rowIndex));
    return cell;
  }
  const control = createComparableFieldControl(field);
  control.dataset.comparableRow = String(rowIndex);
  control.dataset.comparableField = field.key;
  let currentValue = row[field.key] || "";
  if (control.tagName === "SELECT" && field.allowEmpty === false && !currentValue && field.options?.length) {
    currentValue = field.options[0];
    row[field.key] = currentValue;
  }
  if (control.tagName === "SELECT" && currentValue && !Array.from(control.options).some((option) => option.value === currentValue)) {
    const currentOption = document.createElement("option");
    currentOption.value = currentValue;
    currentOption.textContent = currentValue;
    control.append(currentOption);
  }
  control.value = field.type === "date" ? toComparableDateInputValue(currentValue) : currentValue;
  if (field.readOnly) {
    control.readOnly = true;
    control.classList.add("is-readonly");
    if (!currentValue) control.placeholder = "Haritadan seçilince dolar";
    cell.append(control);
    return cell;
  }
  control.addEventListener("input", (event) => {
    row[field.key] = event.target.value;
    if (field.key === "c31") {
      row.c31Manual = event.target.value.trim() ? "1" : "";
      if (!row.c31Manual && syncComparableLandBuildableArea(row)) {
        event.target.value = row.c31 || "";
      }
    }
    autosave();
    if (["c24", "c26", "c27", "c28"].includes(field.key)) return;
    refreshComparableComputedCells(row, rowIndex);
    updateComparableReasonRowsVisibility(cell.closest(".comparables-matrix-shell"));
    if (field.key === "c23" || field.key === "c32") renderSection();
  });
  control.addEventListener("change", (event) => {
    row[field.key] = event.target.value;
    if (field.key === "c31") {
      row.c31Manual = event.target.value.trim() ? "1" : "";
      if (!row.c31Manual) syncComparableLandBuildableArea(row);
    }
    if (["c24", "c26", "c27", "c28"].includes(field.key) && syncComparableLandBuildableArea(row, true)) {
      autosave();
      renderSection();
      return;
    }
    autosave();
    refreshComparableComputedCells(row, rowIndex);
    updateComparableReasonRowsVisibility(cell.closest(".comparables-matrix-shell"));
    if (field.key === "c23" || field.key === "c32") renderSection();
  });
  control.addEventListener("blur", () => {
    if (control.tagName === "SELECT" || field.type === "date") return;
    if (field.key === "c10") return;
    const formattedValue = comparableNumericInputFieldKeys.has(field.key)
      ? formatComparableNumericInputValue(control.value)
      : normalizeReportTableValue(section, field.label, control.value);
    if (formattedValue === control.value) return;
    control.value = formattedValue;
    row[field.key] = formattedValue;
    autosave();
    refreshComparableComputedCells(row, rowIndex);
  });
  cell.append(control);

  if (field.percentKey) {
    const percentControl = createComparableFieldControl({
      key: field.percentKey,
      label: `${field.label} Şerefiye Oranı`,
      type: "select",
      options: comparablePercentOptions,
    });
    percentControl.value = row[field.percentKey] || "";
    percentControl.dataset.comparableRow = String(rowIndex);
    percentControl.dataset.comparableField = field.percentKey;
    percentControl.addEventListener("input", (event) => {
      row[field.percentKey] = event.target.value;
      autosave();
      refreshComparableComputedCells(row, rowIndex);
      updateComparableReasonRowsVisibility(cell.closest(".comparables-matrix-shell"));
    });
    percentControl.addEventListener("change", (event) => {
      row[field.percentKey] = event.target.value;
      autosave();
      refreshComparableComputedCells(row, rowIndex);
      updateComparableReasonRowsVisibility(cell.closest(".comparables-matrix-shell"));
    });
    cell.append(percentControl);
    cell.classList.add("comparable-split-cell");
  }

  if (field.key === "c7") {
    const mapButton = document.createElement("button");
    mapButton.type = "button";
    mapButton.className = "mini-button comparable-map-button";
    mapButton.innerHTML = '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 21s-7-6.5-7-11a7 7 0 0 1 14 0c0 4.5-7 11-7 11z"/><circle cx="12" cy="10" r="2.5"/></svg>';
    mapButton.title = "Haritadan seç";
    mapButton.setAttribute("aria-label", "Haritadan seç");
    mapButton.dataset.comparableRow = String(rowIndex);
    mapButton.dataset.comparableField = "c7map";
    mapButton.addEventListener("click", () => {
      openComparableLocationModal(row, rowIndex, () => {
        autosave();
        renderSection();
      });
    });
    const locationText = document.createElement("small");
    locationText.className = "conditional-summary";
    locationText.textContent = row.c20 || (row.c18 && row.c19 ? `${row.c18}, ${row.c19}` : "");
    cell.append(mapButton, locationText);
    cell.classList.add("comparable-location-split-cell");
  }

  return cell;
}

function createComparableMultiSelectControl(field, row, rowIndex) {
  const reopenKey = `comparable-multi-select:${rowIndex}:${field.key}`;
  const wrapper = document.createElement("div");
  wrapper.className = "multi-checkbox-dropdown comparable-multi-checkbox";
  const selected = getComparableMultiValues(row[field.key], field.options);
  const summaryButton = document.createElement("button");
  summaryButton.type = "button";
  summaryButton.className = "multi-checkbox-summary";
  summaryButton.setAttribute("aria-expanded", "false");
  summaryButton.dataset.comparableRow = String(rowIndex);
  summaryButton.dataset.comparableField = field.key;
  summaryButton.textContent = selected.length ? selected.join(", ") : "Seçiniz";

  const list = document.createElement("div");
  list.className = "inline-checkbox-list";
  list.hidden = true;

  (field.options || []).forEach((option) => {
    const item = document.createElement("label");
    item.className = "checkbox-row";
    item.innerHTML = `
      <input type="checkbox" value="${escapeHtml(option)}" ${selected.includes(option) ? "checked" : ""}>
      <span>${escapeHtml(option)}</span>
    `;
    list.append(item);
  });

  const syncValue = () => {
    const values = [...list.querySelectorAll("input[type='checkbox']:checked")].map((checkbox) => checkbox.value);
    const targetRow = getComparableRows()[rowIndex] || row;
    targetRow[field.key] = values.join(", ");
    row[field.key] = targetRow[field.key];
    summaryButton.textContent = values.length ? values.join(", ") : "Seçiniz";
    autosave();
    refreshComparableComputedCells(targetRow, rowIndex);
    // Kat seçimi değişince alttaki kat bazında alan/indirgeme oranı
    // listesinin satırları da senkronize olmalı (bkz.
    // syncComparableWorkplaceFloors) — bu, tam yeniden render gerektirir.
    if (field.key === "c6") {
      multiCheckboxFieldToReopen = reopenKey;
      renderSection();
    }
  };

  list.querySelectorAll("input[type='checkbox']").forEach((input) => {
    input.addEventListener("change", syncValue);
  });

  let outsideClickListener = null;
  const setOpen = (isOpen) => {
    list.hidden = !isOpen;
    wrapper.classList.toggle("is-open", isOpen);
    summaryButton.setAttribute("aria-expanded", String(isOpen));
    if (outsideClickListener) {
      document.removeEventListener("pointerdown", outsideClickListener);
      outsideClickListener = null;
    }
    if (isOpen) {
      outsideClickListener = (event) => {
        if (!wrapper.contains(event.target)) setOpen(false);
      };
      const currentOutsideClickListener = outsideClickListener;
      setTimeout(() => {
        if (outsideClickListener === currentOutsideClickListener) {
          document.addEventListener("pointerdown", currentOutsideClickListener);
        }
      }, 0);
    }
  };

  if (multiCheckboxFieldToReopen === reopenKey) {
    multiCheckboxFieldToReopen = "";
    setOpen(true);
  }

  summaryButton.addEventListener("click", () => {
    setOpen(list.hidden);
  });
  list.addEventListener("pointerdown", (event) => {
    event.stopPropagation();
  });

  wrapper.append(summaryButton, list);
  return wrapper;
}

function getComparableMultiValues(value, options = []) {
  const allowed = new Set(options);
  return String(value || "")
    .split(",")
    .map((item) => item.trim())
    .filter((item) => item && allowed.has(item));
}

// "Kat" (c6, çoklu seçim) alanında seçili her kat için row.workplaceFloors
// dizisinde bir {floor, area, rate} girdisi bulunmasını sağlar — yeni
// seçilen katlar için boş girdi eklenir, seçimi kaldırılan katların
// girdisi silinir, kalan katların önceden girilmiş alan/oranı KORUNUR.
function syncComparableWorkplaceFloors(row) {
  const selectedFloors = getComparableMultiValues(row.c6, comparableFloorOptions);
  const existingByFloor = new Map(
    (Array.isArray(row.workplaceFloors) ? row.workplaceFloors : []).map((entry) => [entry.floor, entry])
  );
  row.workplaceFloors = selectedFloors.map((floor) => existingByFloor.get(floor) || { floor, area: "", rate: "" });
  return row.workplaceFloors;
}

function createComparableWorkplaceFloorBreakdown(row, rowIndex) {
  const wrapper = document.createElement("div");
  wrapper.className = "comparable-workplace-floor-breakdown";
  const floors = syncComparableWorkplaceFloors(row);

  if (!floors.length) {
    const hint = document.createElement("p");
    hint.className = "comparable-workplace-floor-hint";
    hint.textContent = "Önce \"Kat\" alanından seçim yapınız.";
    wrapper.append(hint);
    return wrapper;
  }

  const commit = () => {
    row.workplaceFloors = floors;
    autosave();
    refreshComparableComputedCells(row, rowIndex);
  };

  floors.forEach((entry) => {
    const floorRow = document.createElement("div");
    floorRow.className = "comparable-workplace-floor-row";

    const label = document.createElement("span");
    label.className = "comparable-workplace-floor-name";
    label.textContent = entry.floor;

    const areaInput = document.createElement("input");
    areaInput.type = "text";
    areaInput.inputMode = "decimal";
    areaInput.placeholder = "m²";
    areaInput.value = entry.area || "";
    areaInput.addEventListener("input", (event) => {
      entry.area = event.target.value;
      commit();
    });
    areaInput.addEventListener("blur", () => {
      const formatted = formatComparableNumericInputValue(areaInput.value);
      areaInput.value = formatted;
      entry.area = formatted;
      commit();
    });

    const rateSelect = document.createElement("select");
    comparablePercentOptions.forEach((option) => {
      const item = document.createElement("option");
      item.value = option;
      item.textContent = option;
      rateSelect.append(item);
    });
    rateSelect.value = entry.rate && comparablePercentOptions.includes(entry.rate) ? entry.rate : "100%";
    entry.rate = rateSelect.value;
    rateSelect.addEventListener("change", (event) => {
      entry.rate = event.target.value;
      commit();
    });

    floorRow.append(label, areaInput, rateSelect);
    wrapper.append(floorRow);
  });

  return wrapper;
}

function updateComparableReasonRowsVisibility(scope = document) {
  const rows = getComparableRows();
  const shouldShow = rows.some((row) => {
    const sign = String(row.c9 || "").trim();
    return sign === "+" || sign === "-";
  });
  scope?.querySelectorAll?.("[data-comparable-reason-row]").forEach((rowElement) => {
    rowElement.hidden = !shouldShow;
  });
}

function createComparableComputedControl(field, row, rowIndex) {
  const value = calculateComparableFieldValue(field.key, row, rowIndex);
  const control = document.createElement(field.type === "textarea" ? "textarea" : "input");
  control.value = value;
  control.readOnly = true;
  control.className = "computed-input";
  control.dataset.comparableRow = String(rowIndex);
  control.dataset.comparableComputed = field.key;
  if (field.type === "textarea") {
    control.rows = field.key === "calcLongText" ? 4 : 3;
  }
  return control;
}

function refreshComparableComputedCells(row, rowIndex) {
  if (syncComparableLandBuildableArea(row)) {
    document.querySelectorAll(`[data-comparable-row="${rowIndex}"][data-comparable-field="c31"]`).forEach((control) => {
      control.value = row.c31 || "";
    });
  }
  document.querySelectorAll(`[data-comparable-row="${rowIndex}"][data-comparable-computed]`).forEach((control) => {
    control.value = calculateComparableFieldValue(control.dataset.comparableComputed, row, rowIndex);
  });
  syncComparableValuationMarketValues();
  refreshComparableValuationSummaryPanel();
  refreshComparableMarketAnalysisPanel();
}

function createComparableValuationSummaryPanel() {
  syncComparableValuationMarketValues();
  const wrapper = document.createElement("div");
  wrapper.className = "subsection is-detail comparable-valuation-summary";
  wrapper.dataset.comparableValuationSummary = "true";
  const titleRow = document.createElement("div");
  titleRow.className = "subsection-table-head";
  titleRow.innerHTML = `<h4>Emsal Değerleme Tablosu</h4>`;
  const tableWrap = document.createElement("div");
  tableWrap.className = "table-shell comparable-valuation-summary-shell";
  tableWrap.append(createComparableValuationSummaryTable());
  wrapper.append(titleRow, tableWrap);
  return wrapper;
}

function refreshComparableValuationSummaryPanel() {
  const panel = document.querySelector("[data-comparable-valuation-summary]");
  if (!panel) return;
  const shell = panel.querySelector(".comparable-valuation-summary-shell");
  if (!shell) return;
  shell.replaceChildren(createComparableValuationSummaryTable());
  refreshComparableCalculatedEmsalValuationPanel();
}

function createComparableCalculatedEmsalValuationPanel() {
  const wrapper = document.createElement("div");
  wrapper.className = "comparable-calculated-emsal-valuation";
  wrapper.dataset.comparableCalculatedEmsalValuation = "true";
  const title = document.createElement("h4");
  title.textContent = "Hesaplanan Emsale Göre Arsa Piyasa Değeri";
  wrapper.append(title, createComparableCalculatedEmsalValuationTable());
  return wrapper;
}

function refreshComparableCalculatedEmsalValuationPanel() {
  const panel = document.querySelector("[data-comparable-calculated-emsal-valuation]");
  if (!panel) return;
  panel.replaceChildren(
    Object.assign(document.createElement("h4"), { textContent: "Hesaplanan Emsale Göre Arsa Piyasa Değeri" }),
    createComparableCalculatedEmsalValuationTable()
  );
}

function getComparableCalculatedEmsalValuationMetrics() {
  const landRows = getComparableValuationRows().filter((row) => row.landComparable);
  const average = calculateComparableValuationAverages(landRows);
  const subjectLandArea = parseValuationNumber(gabimField("landArea"));
  const subjectKaks = parseValuationNumber(gabimField("kaks"));
  const calculatedFromZoning = Number.isFinite(subjectLandArea) && subjectLandArea > 0 && Number.isFinite(subjectKaks) && subjectKaks > 0
    ? subjectLandArea * subjectKaks
    : parseValuationNumber(gabimCalculatedEmsalText());
  const sourceUnitValue = average.adjustedCalculatedEmsalUnitValue;
  const marketValue = Number.isFinite(calculatedFromZoning) && Number.isFinite(sourceUnitValue)
    ? roundComparableValuationValue(calculatedFromZoning * sourceUnitValue, comparableValuationRoundStep)
    : Number.NaN;
  const unitValue = Number.isFinite(marketValue) && Number.isFinite(subjectLandArea) && subjectLandArea > 0
    ? marketValue / subjectLandArea
    : Number.NaN;
  const calculatedUnitValue = Number.isFinite(marketValue) && Number.isFinite(calculatedFromZoning) && calculatedFromZoning > 0
    ? marketValue / calculatedFromZoning
    : Number.NaN;
  return {
    subjectLandArea,
    subjectKaks,
    subjectArea: calculatedFromZoning,
    calculatedUnitValue,
    unitValue,
    marketValue,
  };
}

function createComparableCalculatedEmsalValuationTable() {
  const table = document.createElement("table");
  table.className = "comparable-calculated-emsal-table";
  const metrics = getComparableCalculatedEmsalValuationMetrics();
  table.innerHTML = `
    <thead>
      <tr>
        <th>TAŞINMAZ YÜZÖLÇÜMÜ<span>m²</span></th>
        <th>KAKS ORANI</th>
        <th>KONU TAŞINMAZIN HESAPLANAN EMSALİ<span>m²</span></th>
        <th>HESAPLANAN EMSAL M² BİRİM DEĞERİ<span>TL/m²</span></th>
        <th>m² BİRİM DEĞERİ<span>TL/m²</span></th>
        <th>PİYASA DEĞERİ<span>TL</span></th>
      </tr>
    </thead>
    <tbody>
      <tr>
        <td>${formatComparableSummaryNumber(metrics.subjectLandArea, { decimals: 2 })}</td>
        <td>${formatComparableSummaryNumber(metrics.subjectKaks, { decimals: 2 })}</td>
        <td>${formatComparableSummaryNumber(metrics.subjectArea, { decimals: 2 })}</td>
        <td>${formatComparableSummaryNumber(metrics.calculatedUnitValue, { decimals: 2 })}</td>
        <td>${formatComparableSummaryNumber(metrics.unitValue, { decimals: 2 })}</td>
        <td class="is-accent is-accent-sale">${formatComparableSummaryMoney(metrics.marketValue)}</td>
      </tr>
    </tbody>
  `;
  return table;
}

