function getComparableValuationRows() {
  return getComparableRows()
    .map((row, index) => {
      const metrics = calculateComparableMetrics(row);
      const landComparable = isLandComparable(row);
      return {
        no: `E${index + 1}`,
        landComparable,
        // ALAN sütunu toplam (indirgeme UYGULANMADAN) emsal alanını gösterir;
        // hesaplamalarda kullanılan indirgenmiş alan workplaceEffectiveArea'da
        // ayrıca taşınır (kullanıcı talebi).
        area: landComparable ? metrics.adjustedArea : metrics.workplaceTotalArea,
        workplaceEffectiveArea: metrics.adjustedArea,
        workplaceFloors: Array.isArray(row.workplaceFloors) ? row.workplaceFloors : [],
        calculatedEmsalArea: metrics.calculatedEmsalArea,
        askingPrice: metrics.askingPrice,
        negotiationRate: metrics.negotiationRate,
        saleValue: metrics.saleValue,
        unitValue: metrics.unitValue,
        featureAdjustment: metrics.featureAdjustment,
        locationAdjustment: metrics.locationAdjustment,
        adjustedUnitValue: metrics.adjustedUnitValue,
        calculatedEmsalUnitValue: metrics.calculatedEmsalUnitValue,
        adjustedCalculatedEmsalUnitValue: metrics.adjustedCalculatedEmsalUnitValue,
        rent: metrics.rent,
        rentUnitValue: metrics.rentUnitValue,
        adjustedRentUnitValue: metrics.adjustedRentUnitValue,
      };
    })
    .filter((row) => Number.isFinite(row.adjustedUnitValue) || Number.isFinite(row.unitValue) || Number.isFinite(row.rentUnitValue));
}

function calculateComparableValuationAverages(rows = getComparableValuationRows()) {
  const averageOf = (key) => {
    const values = rows.map((row) => row[key]).filter(Number.isFinite);
    if (!values.length) return Number.NaN;
    return values.reduce((sum, value) => sum + value, 0) / values.length;
  };
  return {
    area: averageOf("area"),
    calculatedEmsalArea: averageOf("calculatedEmsalArea"),
    askingPrice: averageOf("askingPrice"),
    negotiationRate: averageOf("negotiationRate"),
    saleValue: averageOf("saleValue"),
    unitValue: averageOf("unitValue"),
    featureAdjustment: averageOf("featureAdjustment"),
    locationAdjustment: averageOf("locationAdjustment"),
    adjustedUnitValue: averageOf("adjustedUnitValue"),
    calculatedEmsalUnitValue: averageOf("calculatedEmsalUnitValue"),
    adjustedCalculatedEmsalUnitValue: averageOf("adjustedCalculatedEmsalUnitValue"),
    rent: averageOf("rent"),
    rentUnitValue: averageOf("rentUnitValue"),
    adjustedRentUnitValue: averageOf("adjustedRentUnitValue"),
  };
}

function formatComparableSummaryAreaCell(row) {
  return formatComparableSummaryNumber(row.area, { decimals: 2 });
}

// Emsal Değerleme Tablosu'nda ALAN sütununun yanında "KAT ALANLARI" grup
// başlığı altında 3 alt sütun bulunur: KAT, ALAN, İND. ORANI. Kat bazında
// alan/indirgeme girilmişse (bkz. workplaceFloors) her alt sütunun
// hücresinde kendi değeri satır satır, en altta da toplam satırı
// gösterilir (kullanıcı talebi): "Zemin Kat" / "100 m²" / "%100",
// "Asma Kat" / "50 m²" / "%30", "Toplam" / "115 m²" / "".
function formatComparableWorkplaceFloorColumnLine(entry, key) {
  if (key === "floor") {
    const name = normalizeComparableFloorName(entry.floor);
    return name ? `${name.charAt(0).toLocaleUpperCase("tr-TR")}${name.slice(1)} Kat` : "Kat";
  }
  if (key === "area") {
    const areaNumber = parseComparableNumber(entry.area);
    return Number.isFinite(areaNumber)
      ? `${areaNumber.toLocaleString("tr-TR", { maximumFractionDigits: 2 })} m²`
      : String(entry.area || "").trim();
  }
  const rateText = String(entry.rate || "100%").replace("%", "").trim() || "100";
  return `%${rateText}`;
}

function formatComparableWorkplaceFloorColumn(row, key) {
  const floors = (Array.isArray(row.workplaceFloors) ? row.workplaceFloors : []).filter((entry) =>
    String(entry?.area || "").trim()
  );
  if (!floors.length) return "";
  const totalLine =
    key === "floor"
      ? "Toplam"
      : key === "area" && Number.isFinite(row.workplaceEffectiveArea)
        ? `${row.workplaceEffectiveArea.toLocaleString("tr-TR", { maximumFractionDigits: 2 })} m²`
        : "";
  const lines = [...floors.map((entry) => formatComparableWorkplaceFloorColumnLine(entry, key)), totalLine];
  // Boş satır (ör. İND. ORANI'nın toplam satırı) &nbsp; ile doldurulur; aksi
  // halde içerik yüksekliği diğer alt sütunlardan az olur ve tablo hücresinin
  // dikey ortalaması satırları birbirinden kaydırır (kullanıcının bildirdiği
  // hizalama sorunu).
  return lines.map((line) => `<div class="comparable-summary-floor-area-line">${line ? escapeHtml(line) : "&nbsp;"}</div>`).join("");
}

function formatComparableSummaryNumber(value, options = {}) {
  if (!Number.isFinite(value)) return "";
  return value.toLocaleString("tr-TR", {
    minimumFractionDigits: options.decimals ?? 0,
    maximumFractionDigits: options.decimals ?? 0,
  });
}

function formatComparableSummaryMoney(value) {
  if (!Number.isFinite(value)) return "";
  return Math.round(value).toLocaleString("tr-TR");
}

function formatComparableSummaryPercent(value) {
  if (!Number.isFinite(value)) return "";
  return `%${(value * 100).toLocaleString("tr-TR", { maximumFractionDigits: 2 })}`;
}

function formatComparableSummarySignedPercent(value) {
  if (!Number.isFinite(value) || value === 0) return "+ 0%";
  const sign = value > 0 ? "+" : "-";
  return `${sign} %${(Math.abs(value) * 100).toLocaleString("tr-TR", { maximumFractionDigits: 2 })}`;
}

function roundComparableValuationValue(value, step = comparableValuationRoundStep) {
  if (!Number.isFinite(value) || value <= 0) return Number.NaN;
  return Math.round(value / step) * step;
}

function syncComparableValuationMarketValues() {
  syncValuationAreasFromUnitAreas();
  const average = calculateComparableValuationAverages();
  const unitValue = average.adjustedUnitValue;
  if (Number.isFinite(unitValue) && unitValue > 0) {
    syncComparableValuationMarketValue("legalValue", "legalValueArea", unitValue);
    syncComparableValuationMarketValue("currentValue", "currentValueArea", unitValue);
  }
  const rentUnitValue = average.adjustedRentUnitValue;
  if (Number.isFinite(rentUnitValue) && rentUnitValue > 0) {
    syncComparableValuationMarketValue("legalRent", "legalRentArea", rentUnitValue, comparableValuationRentRoundStep);
    syncComparableValuationMarketValue("currentRent", "currentRentArea", rentUnitValue, comparableValuationRentRoundStep);
  }
  refreshValuationControls();
}

function syncComparableValuationMarketValue(totalKey, areaKey, unitValue, roundStep = comparableValuationRoundStep) {
  if (state.fields[`${totalKey}ComparableAutoManual`] === "1" || hasUserDefinedLandMarketValue(totalKey)) return;
  const area = parseValuationNumber(state.fields[areaKey]);
  if (!Number.isFinite(area) || area <= 0) return;
  const roundedValue = roundComparableValuationValue(area * unitValue, roundStep);
  if (!Number.isFinite(roundedValue)) return;
  const formatted = formatValuationMoney(roundedValue);
  state.fields[totalKey] = formatted;
  state.fields[`${totalKey}ComparableAuto`] = formatted;
}

function calculateComparableFieldValue(key, row, rowIndex = 0) {
  const metrics = calculateComparableMetrics(row);
  if (key === "calcNegotiation") return formatComparablePercent(metrics.negotiationRate);
  if (key === "calcUnitValue") return formatComparableMoney(metrics.unitValue, " TL/m²");
  if (key === "calcFeatureAdjustment") return formatComparableSignedPercent(metrics.featureAdjustment);
  if (key === "calcLocationAdjustment") return formatComparableSignedPercent(metrics.locationAdjustment);
  if (key === "calcAdjustedUnitValue") return formatComparableMoney(metrics.adjustedUnitValue, " TL/m²");
  if (key === "calcCalculatedEmsalUnitValue") return formatComparableMoney(metrics.calculatedEmsalUnitValue, " TL/m²");
  if (key === "calcAdjustedCalculatedEmsalUnitValue") return formatComparableMoney(metrics.adjustedCalculatedEmsalUnitValue, " TL/m²");
  if (key === "calcRentUnitValue") return formatComparableMoney(metrics.rentUnitValue, " TL/m²/ay");
  if (key === "calcWorkplaceReducedArea") return formatComparableMoney(metrics.workplaceReducedArea, " m²");
  if (key === "calcLongText") return buildComparableLongText(row, rowIndex, metrics);
  return "";
}

// Kat Bazında İndirgeme Oranı (c32) metnini orana çevirir. Boş/geçersizse
// %100 (indirgeme yok) varsayılır — bu sayede alan boş bırakıldığında
// geriye dönük davranış (Düzeltilmiş/Beyan Edilen Alanın doğrudan
// kullanılması) AYNEN korunur (kullanıcı talebi).
// Kat bazında alan/oran girdilerini Word/placeholder çıktısı için okunabilir
// tek satıra çevirir, örn. "Zemin kat: 100 m² (%100), Asma kat: 50 m² (%30)".
function formatComparableWorkplaceFloorsSummary(row) {
  const floors = Array.isArray(row?.workplaceFloors) ? row.workplaceFloors : [];
  return floors
    .filter((entry) => String(entry?.area || "").trim())
    .map((entry) => `${entry.floor}: ${entry.area} m² (${entry.rate || "100%"})`)
    .join(", ");
}

function parseComparableWorkplaceReductionRate(value) {
  const text = String(value || "").replace("%", "").trim();
  if (!text) return 1;
  const number = parseComparableNumber(text);
  if (!Number.isFinite(number) || number < 0) return 1;
  return number > 1 ? number / 100 : number;
}

function calculateComparableMetrics(row) {
  const status = String(row.c2 || "").toLocaleLowerCase("tr-TR");
  const landComparable = isLandComparable(row);
  const askingPrice = parseComparableNumber(row.c14);
  const bargainPrice = parseComparableNumber(row.c15);
  if (landComparable) syncComparableLandBuildableArea(row);
  const rawArea = parseComparableNumber(row.c13 || row.c12);
  // Kat bazında alan/indirgeme SADECE işyeri benzeri raporlarda (İşyeri,
  // Ofis, Ticari Bina) uygulanır — bu davranış zaten UI'da bu durumda
  // gösteriliyor. "Kat" (c6) alanı konut emsallerinde de mevcut olduğundan
  // bu kontrol olmazsa syncComparableWorkplaceFloors boş "area" alanlı
  // satırlar üretir ve adjustedArea 0'a düşerek M² birim değer
  // hesaplanamaz hale gelir (bkz. kullanıcı bildirdiği regresyon — konut
  // emsalleri). İşyeri türü raporlarda ise kat seçiliyken alan boş
  // bırakılırsa (kasıtlı olarak) hesap yine bozuk kalır — kullanıcı
  // verileri tamamlamaya zorlanır.
  const workplaceFloors = landComparable || !isWorkplaceLikeUsageNature() ? [] : syncComparableWorkplaceFloors(row);
  const workplaceReducedArea = workplaceFloors.length
    ? workplaceFloors.reduce((sum, entry) => {
        const area = parseComparableNumber(entry.area);
        const rate = parseComparableWorkplaceReductionRate(entry.rate);
        return sum + (Number.isFinite(area) ? area * rate : 0);
      }, 0)
    : rawArea;
  // ALAN sütununda gösterilecek toplam emsal alanı (indirgeme UYGULANMADAN,
  // ör. Zemin kat 100 m² + Asma kat 50 m² = 150 m²) — kullanıcı talebi:
  // hesaplamalar yine de indirgenmiş alan (workplaceReducedArea) üzerinden
  // yapılmaya devam eder, bu alan yalnızca gösterim içindir.
  const workplaceTotalArea = workplaceFloors.length
    ? workplaceFloors.reduce((sum, entry) => {
        const area = parseComparableNumber(entry.area);
        return sum + (Number.isFinite(area) ? area : 0);
      }, 0)
    : rawArea;
  // Kullanıcı bildirimi (2026-08-16): "ARSA raporlarında emsal tablosu
  // excel olarak export edilmiyor" — kök neden: arsa/tarla nitelikli bir
  // emsal satırında "Yüzölçümü" (c24) alanı boş bırakılıp bunun yerine
  // (varsayılan "Tüm Alanlar" görünümünde c12/c13 de AYNI ekranda
  // görünüyor, bkz. getComparableDisplayFields) "Beyan Edilen Alan"/
  // "Düzeltilmiş Alan" (c12/c13, KONUT'a özgü alanlar) dolduruluyordu —
  // bu durumda adjustedArea daima NaN kalıyor, unitValue/adjustedUnitValue
  // hesaplanamıyor, satır getComparableValuationRows()'un filtresinden
  // (Number.isFinite kontrolü) SESSİZCE elenip "Emsal Değerleme Tablosu"
  // boş kalıyordu — arsa raporlarında AYRICA "Kat Bazında İndirgenmiş
  // Alan Tablosu" da HER ZAMAN boş olduğundan (arazi için kat kavramı
  // yok), "Değerleme ve Emsaller" Excel sayfasının 5 alt-tablosundan 2'si
  // garanti boşken emsal hesaplaması da boşalınca sayfa TAMAMEN
  // kayboluyordu. Düzeltme: arsa/tarla satırında c24 boş/geçersizse
  // c12/c13'ten (rawArea, YUKARIDA zaten hesaplanmıştı ama önceden
  // arsa/tarla için YOK SAYILIYORDU) YEDEK olarak düşülür.
  const adjustedArea = landComparable ? (parseComparableNumber(row.c24) || rawArea) : workplaceReducedArea;
  const calculatedEmsalArea = landComparable ? parseComparableNumber(row.c31) : Number.NaN;
  const rent = landComparable ? Number.NaN : parseComparableNumber(row.c16);
  const featureAdjustment = landComparable ? 0 : calculateComparableAdjustment(row.c8, row.c21);
  const locationAdjustment = calculateComparableAdjustment(row.c9, row.c22);
  const negotiationRate = askingPrice > 0 && bargainPrice > 0 ? 1 - bargainPrice / askingPrice : Number.NaN;
  const saleValue = status.includes("satılmış")
    ? askingPrice
    : bargainPrice > 0
      ? bargainPrice
      : askingPrice;
  const furnished = !landComparable && String(row.c32 || "").trim().toLocaleLowerCase("tr-TR") === "evet";
  const furnitureValue = furnished ? parseComparableNumber(row.c33) : Number.NaN;
  const netSaleValue = saleValue - (Number.isFinite(furnitureValue) && furnitureValue > 0 ? furnitureValue : 0);
  const unitValue = netSaleValue > 0 && adjustedArea > 0 ? netSaleValue / adjustedArea : Number.NaN;
  const adjustedUnitValue = Number.isFinite(unitValue) ? unitValue * (1 + featureAdjustment + locationAdjustment) : Number.NaN;
  const calculatedEmsalUnitValue = netSaleValue > 0 && calculatedEmsalArea > 0 ? netSaleValue / calculatedEmsalArea : Number.NaN;
  const adjustedCalculatedEmsalUnitValue = Number.isFinite(calculatedEmsalUnitValue)
    ? calculatedEmsalUnitValue * (1 + locationAdjustment)
    : Number.NaN;
  const rentUnitValue = rent > 0 && adjustedArea > 0 ? rent / adjustedArea : Number.NaN;
  const adjustedRentUnitValue = Number.isFinite(rentUnitValue) ? rentUnitValue * (1 + featureAdjustment + locationAdjustment) : Number.NaN;
  return {
    askingPrice,
    bargainPrice,
    saleValue,
    furnished,
    furnitureValue,
    netSaleValue,
    adjustedArea,
    workplaceReducedArea,
    workplaceTotalArea,
    calculatedEmsalArea,
    rent,
    featureAdjustment,
    locationAdjustment,
    negotiationRate,
    unitValue,
    adjustedUnitValue,
    calculatedEmsalUnitValue,
    adjustedCalculatedEmsalUnitValue,
    rentUnitValue,
    adjustedRentUnitValue,
  };
}

// Emlak Katılım .docx şablonu ("4. Taşınmazın Konum Krokisi Ve Emsal
// Taşınmazlar" — Emsal 1/2/3 sabit kartları) için: belgede sabit 3 emsal
// kartı yeri var (dinamik satır çoğaltma değil), bu yüzden emsal
// dizisinden İNDEKSLİ erişim yeterli — 0/1/2. index karşılığı yoksa
// (o kadar emsal girilmemişse) boş döner, kart Word'de bomboş kalır.
function getComparableCardEntries() {
  return getComparableRows().filter((row) => Object.values(row || {}).some((value) => String(value || "").trim()));
}

function getComparableCardData(index) {
  const row = getComparableCardEntries()[index];
  if (!row) return null;
  return { row, metrics: calculateComparableMetrics(row) };
}

function getComparableCardContactText(index) {
  const data = getComparableCardData(index);
  if (!data) return "";
  const phone = formatComparablePhoneForOutput(data.row.c1);
  return [data.row.c0, phone].filter(Boolean).join(" / ");
}

// Kullanici talebi: "Emsalin Açıklaması bölümünde sürekli ekspertize konu
// taşınmaz satılık olup diyor. oysa ki sadece 1. emsal konu taşınmaz
// diğerlerinin açıklaması farklı olmalı ayrıca irtibat numarası ve
// telefon numarası yazmamalı" — eskiden HER karta, satırın gerçek
// durumundan (c2) bağımsız olarak sabit buildComparableSubjectStatement
// ("Ekspertize konu taşınmaz satılık olup...") çağrılıyordu. Artık
// buildComparableLongText (calcLongText/UZUN_EMSAL_METNI'nin de kullandığı,
// satırın c2 durumuna göre Genel/Konu Taşınmaz/standart karşılaştırma
// metnini seçen fonksiyon) kullanılıyor VE tüm varyantların baştaki
// "(İrtibat Kişisi ve Telefon No: ...)" satırı çıkarılıyor.
function stripComparableContactLine(text) {
  // Telefon numaralari kendi ic parantezleri icerebildigi icin ([^)]* yerine
  // ic parantezlere toleransli, ilk ")\n\n" e kadar giden non-greedy eslesme.
  return String(text || "").replace(/^\(İrtibat Kişisi ve Telefon No:[\s\S]*?\)\n\n/, "");
}

function getComparableCardDescriptionText(index) {
  const data = getComparableCardData(index);
  if (!data) return "";
  return stripComparableContactLine(buildComparableLongText(data.row, index, data.metrics));
}

function getComparableCardAreaText(index) {
  const data = getComparableCardData(index);
  return data ? formatComparableArea(data.metrics.adjustedArea) : "";
}

function getComparableCardSaleValueText(index) {
  const data = getComparableCardData(index);
  return data ? formatComparableMoney(data.metrics.saleValue) : "";
}

function getComparableCardUnitValueText(index) {
  const data = getComparableCardData(index);
  return data ? formatComparableMoney(data.metrics.adjustedUnitValue, " TL/m2") : "";
}

// Kullanıcı talebi: irtibat kişisi/telefon ile emsal açıklamasını TEK bir
// placeholder'da birleştir, örnek çıktı: "(İrtibat Kişisi ve Telefon No:
// Raif Bey / 0 (546) 582 19 29)\n\nEkspertize konu taşınmaz satılık olup, ..."
function getComparableCardFullText(index) {
  const data = getComparableCardData(index);
  if (!data) return "";
  const contact = getComparableCardContactText(index);
  const description = getComparableCardDescriptionText(index);
  const contactLine = contact ? `(İrtibat Kişisi ve Telefon No: ${contact})` : "";
  return [contactLine, description].filter(Boolean).join("\n\n");
}

// Emlak Katılım .docx şablonu — "2.1. Gayrimenkulün Çevre Analizi" ve
// "5.5. Kira Kabiliyeti" bölümlerindeki seçenekler Word'de AYRI hücrelerde
// duruyor (bir hücrenin içine yazılan tek bir metin değil); kullanıcı
// talebi: doğru seçeneği KOYU (bold) yap. Bizim alanlarımızın ölçeği
// belgedeki seçeneklerle HER ZAMAN birebir örtüşmüyor (ör. developmentDensity
// "düşük/orta/yüksek" 3'lü ölçek, belge "%25'in altında/%25-75/%75'ten
// fazla" 3'lü ölçek) — sıralı (ordinal) eşleme yapılır, YAKLAŞIKTIR.
// regionUsePurpose çoklu seçim/serbest metin olduğundan anahtar kelime
// eşleşmesiyle (konut/işyeri-ticaret/sanayi) yaklaşık eşlenir.
function getEmlakKatilimBoldFlags() {
  const density = String(state.fields.developmentDensity || "");
  const speed = String(state.fields.developmentSpeed || "");
  const earthquake = String(state.fields.earthquakeZone || "");
  const earthquakeDegreeMatch = earthquake.match(/^(\d)\./);
  const earthquakeDegree = earthquakeDegreeMatch ? earthquakeDegreeMatch[1] : "";
  const purpose = foldTurkish(String(state.fields.regionUsePurpose || "")).toLocaleLowerCase("tr");
  const hasKonut = purpose.includes("konut") || purpose.includes("villa") || purpose.includes("yazlik");
  const hasIsyeri = purpose.includes("isyeri") || purpose.includes("ticaret") || purpose.includes("ofis");
  const hasSanayi = purpose.includes("sanayi");
  const tenantOccupied = isUnitTenantOccupied();

  return {
    YOGUNLUK_75USTU: density === "yüksek",
    YOGUNLUK_25_75: density === "orta",
    YOGUNLUK_25ALTI: density === "düşük",
    HIZ_HIZLI: speed === "yüksek",
    HIZ_SABIT: speed === "orta",
    HIZ_YAVAS: speed === "düşük",
    DEPREM_1: earthquakeDegree === "1",
    DEPREM_2: earthquakeDegree === "2",
    DEPREM_3: earthquakeDegree === "3",
    DEPREM_4: earthquakeDegree === "4",
    DEPREM_5: earthquakeDegree === "5",
    TUR_SANAYI: hasSanayi,
    TUR_KARMA: hasKonut && hasIsyeri && !hasSanayi,
    TUR_KONUT: hasKonut && !hasIsyeri && !hasSanayi,
    TUR_TICARET: hasIsyeri && !hasKonut && !hasSanayi,
    TUR_TURIZM: false,
    TUR_DIGER: !hasKonut && !hasIsyeri && !hasSanayi,
    KIRACI_VAR: tenantOccupied,
    KIRACI_YOK: !tenantOccupied,
    KONTRAT_VAR: false,
    KONTRAT_YOK: !tenantOccupied,
  };
}

function getComparableCard1ContactText() { return getComparableCardContactText(0); }
function getComparableCard1DescriptionText() { return getComparableCardDescriptionText(0); }
function getComparableCard1AreaText() { return getComparableCardAreaText(0); }
function getComparableCard1SaleValueText() { return getComparableCardSaleValueText(0); }
function getComparableCard1UnitValueText() { return getComparableCardUnitValueText(0); }
function getComparableCard2ContactText() { return getComparableCardContactText(1); }
function getComparableCard2DescriptionText() { return getComparableCardDescriptionText(1); }
function getComparableCard2AreaText() { return getComparableCardAreaText(1); }
function getComparableCard2SaleValueText() { return getComparableCardSaleValueText(1); }
function getComparableCard2UnitValueText() { return getComparableCardUnitValueText(1); }
function getComparableCard3ContactText() { return getComparableCardContactText(2); }
function getComparableCard3DescriptionText() { return getComparableCardDescriptionText(2); }
function getComparableCard3AreaText() { return getComparableCardAreaText(2); }
function getComparableCard3SaleValueText() { return getComparableCardSaleValueText(2); }
function getComparableCard3UnitValueText() { return getComparableCardUnitValueText(2); }
function getComparableCard1FullText() { return getComparableCardFullText(0); }
function getComparableCard2FullText() { return getComparableCardFullText(1); }
function getComparableCard3FullText() { return getComparableCardFullText(2); }

function calculateComparableAdjustment(direction, percentValue) {
  const percent = parseComparablePercent(percentValue);
  const sign = String(direction || "").trim();
  if (!Number.isFinite(percent) || !sign || sign === "0") return 0;
  if (sign === "+") return -percent;
  if (sign === "-") return percent;
  return 0;
}

function parseComparableNumber(value) {
  const text = String(value || "")
    .replace(/\b(?:TL|TRY|m2|m²|%|\/ay)\b/gi, "")
    .replace(/[₺\s]/g, "")
    .trim();
  if (!text) return Number.NaN;
  const normalized = text.includes(",")
    ? text.replace(/\./g, "").replace(",", ".")
    : /^\d{1,3}(?:\.\d{3})+$/.test(text)
      ? text.replace(/\./g, "")
      : text;
  const number = Number.parseFloat(normalized.replace(/[^0-9.-]/g, ""));
  return Number.isFinite(number) ? number : Number.NaN;
}

function parseComparablePercent(value) {
  const number = parseComparableNumber(value);
  if (!Number.isFinite(number)) return Number.NaN;
  return number > 1 ? number / 100 : number;
}

// Emsal matrisindeki m2/değer alanları (c12/c13/c24/c14/c15/c16) ham "4000000"
// gibi giriliyordu; kullanıcı talebi geregi diğer para/alan alanlarıyla
// (bkz. normalizeValuationInputValue) aynı tr-TR binler+ondalık ayracı ile
// gösterilir: 4.000.000 / 3.542,24. Birim (m²/TL) eklenmez — sütun başlığı
// zaten birimi belirtiyor.
function formatComparableNumericInputValue(value) {
  const text = String(value ?? "").trim();
  if (!text) return "";
  const number = parseComparableNumber(text);
  if (!Number.isFinite(number)) return text;
  return number.toLocaleString("tr-TR", {
    minimumFractionDigits: Number.isInteger(number) ? 0 : 2,
    maximumFractionDigits: 2,
  });
}

function formatComparableMoney(value, suffix = " TL") {
  if (!Number.isFinite(value)) return "";
  return `${Math.round(value).toLocaleString("tr-TR")}${suffix}`;
}

function formatComparablePercent(value) {
  if (!Number.isFinite(value)) return "";
  return `%${(value * 100).toLocaleString("tr-TR", { maximumFractionDigits: 1 })}`;
}

function formatComparableSignedPercent(value) {
  if (!Number.isFinite(value) || value === 0) return "%0";
  const sign = value > 0 ? "+" : "-";
  return `${sign}%${(Math.abs(value) * 100).toLocaleString("tr-TR", { maximumFractionDigits: 1 })}`;
}

function buildComparableLongText(row, rowIndex, metrics) {
  if (isLandComparable(row)) return buildComparableLandLongText(row, rowIndex, metrics);
  if (!String(row.c0 || row.c2 || row.c4 || "").trim()) return "";
  const status = String(row.c2 || "").toLocaleLowerCase("tr-TR");
  if (status.includes("genel")) return buildComparableGeneralStatement(row, metrics);
  if (status.includes("konu")) return buildComparableSubjectStatement(row, metrics);

  const contactLine = buildComparableContactLine(row);
  const location = buildComparableLocationLocative(row.c7);
  const age = buildComparableBuildingAgePhrase(row);
  // Kat bazında alan/indirgeme girilmişse (bkz. workplaceFloors) açıklama
  // her katın kendi alanını ayrı ayrı belirtir; girilmemişse eski davranış
  // (tek kat ibaresi + Beyan Edilen/Düzeltilmiş Alan) aynen korunur
  // (kullanıcı talebi: "dükkana ve katlara göre bu açıklama düzenlenmeli").
  const workplaceFloorAreaPhrase = buildComparableWorkplaceFloorAreaPhrase(row);
  const floor = workplaceFloorAreaPhrase ? "" : buildComparableFloorPhrase(row.c6);
  const declaredArea = workplaceFloorAreaPhrase ? "" : formatComparableArea(row.c12, "m2");
  const correctedArea = workplaceFloorAreaPhrase ? "" : formatComparableArea(row.c13 || row.c12, "m2");
  // Oda Sayısı (c5) işyeri/ofis/ticari raporlarda anlamsız — açıklamadan
  // da kaldırılır (kullanıcı talebi).
  const roomCountText = isWorkplaceLikeUsageNature() ? "" : row.c5;
  const statusText = getComparableStatusText(row, metrics);
  const positionText = buildComparablePositionComparisonText(row)
    .replace(/konum bak\u0131m\u0131ndan benzerdir$/i, "benzer konumda")
    .replace(/benzer bir konumdad\u0131r$/i, "benzer konumda")
    .replace(/benzer bir konuma sahiptir$/i, "benzer konumda");
 const isExternalAppraisal = isExternalAppointmentType(state.fields.appointmentType);
const featureText = buildComparableFeatureComparisonText(row).replace(/^Emsal,\s*/i, "");
// Kullanıcı talebi (2026-08-20): "ÇOK TALEPLERDE ekspertize konu
// taşınmazla aynı bölgede yerine ekspertize konu taşınmazlarla aynı
// bölgede demesi gerekiyor... konum olarak taşınmazla benzer konumda
// yerine konum olarak taşınmazlarla benzer konumda demeli" — Emsaller
// artık Çoklu Talep raporlarında ORTAK (bkz. isComparablesSharedAcrossUnits,
// 0.0.489) olduğundan, emsal kartı açıklamasındaki TÜM tekil "taşınmaz"
// (taşınmazla/taşınmaza göre/taşınmazın) referansları da bu durumda çoğul
// olmalı. Regex ile serbest metin çevirimi YAPILMIYOR — yalnızca bu
// fonksiyonun KENDİ kontrolündeki sabit bağlaç kelimesi (${subjectDative})
// koşullu; positionText/featureText'in İÇİNDEKİ çoğullaştırma AYRICA
// buildComparablePositionComparisonText/buildComparableFeatureComparisonText'te
// yapılıyor (aşağıda), regex burada yalnızca O ÖNCEDEN çoğullaştırılmış
// metni (hem tekil hem çoğul biçimini) doğru şekilde ayıklamak için var.
const isMultiUnitComparable = isComparablesSharedAcrossUnits();
const comparisonText = isExternalAppraisal
    ? positionText
      ? `Emsal konu ${isMultiUnitComparable ? "taşınmazlarla" : "taşınmaz ile"} ${positionText.replace(/taşınmaz(?:lar)?a göre\s*/i, "")} yer almakta olup, ${featureText}`
      : `Emsalin ${featureText}`
    : positionText || featureText
      ? `Emsal, ${[positionText, featureText].filter(Boolean).join(" ve ")}.`
      : "";
  const bargainRentText = buildComparableBargainAndRentText(row, metrics);
  const furnitureText = metrics.furnished && Number.isFinite(metrics.furnitureValue) && metrics.furnitureValue > 0
    ? `Emsal eşyalı olarak ${status.includes("satılmış") ? "pazarlanmış" : "pazarlanmakta"} olup eşya bedeli ${formatComparableMoney(metrics.furnitureValue)} olarak değerlemede dikkate alınmıştır.`
    : "";
  const workplaceFloorReductionExplanation = buildComparableWorkplaceFloorReductionExplanation(row, metrics);
  const calculationText = buildComparableCalculationText(row, metrics);
  const extraText = formatComparableExtraNote(row.c17);
  const sentence = [
    isMultiUnitComparable ? "Ekspertize konu taşınmazlarla " : "Ekspertize konu taşınmazla ",
    location,
    age ? `, ${age}` : "",
    workplaceFloorAreaPhrase ? `, ${workplaceFloorAreaPhrase}` : (floor ? `, ${floor}` : ""),
    declaredArea ? `, ${declaredArea} olarak beyan edilen` : "",
    correctedArea ? `, ${correctedArea} olduğu düşünülen` : "",
    roomCountText ? `, ${roomCountText} planında` : "",
    row.c4 ? ` ${row.c4}` : "",
    statusText ? ` ${statusText}` : "",
    comparisonText ? ` ${comparisonText}` : "",
    furnitureText ? ` ${furnitureText}` : "",
    bargainRentText ? ` ${bargainRentText}` : "",
    workplaceFloorReductionExplanation ? ` ${workplaceFloorReductionExplanation}` : "",
    extraText ? ` ${extraText}` : "",
    calculationText,
  ].join("");
  return normalizeComparableText(`${contactLine}\n\n${sentence}`);
}

function buildComparableLandLongText(row, rowIndex, metrics) {
  if (!String(row.c0 || row.c2 || row.c23 || row.c24 || "").trim()) return "";
  const status = String(row.c2 || "").toLocaleLowerCase("tr-TR");
  if (status.includes("genel")) return buildComparableGeneralStatement(row, metrics);
  const contactLine = buildComparableContactLine(row);
  const location = buildComparableLocationLocative(row.c7);
  const mapLocation = formatComparableMapLocationPhrase(row);
  const positionText = buildComparableLandPositionText(row);
  const roadFrontageText = buildComparableRoadFrontageText(row);
  const area = formatComparableArea(row.c24, "m2");
  const zoningText = buildComparableLandZoningText(row);
  const nature = String(row.c23 || "Arsa").trim();
  const statusText = getComparableStatusText(row, metrics);
  const negotiationText = buildComparableLandNegotiationText(metrics);
  const calculationText = buildComparableLandCalculationText(row, metrics);
  const extraText = formatComparableExtraNote(row.c17);
  // bkz. buildComparableLongText() yorumu — Emsaller Çoklu Talep'te ortak
  // olduğundan (isComparablesSharedAcrossUnits) tekil "taşınmaz" referansları
  // burada da çoğullaştırılır.
  const sentence = [
    isComparablesSharedAcrossUnits() ? "Ekspertize konu taşınmazlarla " : "Ekspertize konu taşınmazla ",
    location,
    mapLocation ? `, ${mapLocation}` : "",
    positionText ? `, konum olarak ${positionText}` : "",
    roadFrontageText ? `, ${roadFrontageText}` : "",
    area ? `, ${area} yüzölçümüne sahip` : "",
    zoningText ? `, ${zoningText}` : "",
    ` ${nature} nitelikli gayrimenkul`,
    statusText ? ` ${statusText}` : "",
    negotiationText ? ` ${negotiationText}` : "",
    extraText ? ` ${extraText}` : "",
    calculationText,
  ].join("");
  return normalizeComparableText(`${contactLine}\n\n${sentence}`);
}

function buildComparableRoadFrontageText(row = {}) {
  const frontage = String(row.c29 || "").trim();
  return frontage ? `yola cephe durumu ${frontage.toLocaleLowerCase("tr-TR")}` : "";
}

function formatComparableMapLocationPhrase(row = {}) {
  const text = String(row.c20 || "").trim();
  if (!text) return "";
  // bkz. buildComparableLongText() yorumu — Emsaller Çoklu Talep'te ortak
  // olduğundan (isComparablesSharedAcrossUnits) tekil "taşınmazın" (genitif)
  // referansı burada da çoğullaştırılır.
  const subjectGenitive = isComparablesSharedAcrossUnits() ? "taşınmazların" : "taşınmazın";
  const match = text.match(/([\d.,]+)\s*(?:m|metre)\s+(.+)/i);
  if (!match) return `${subjectGenitive} ${text}`;
  const distance = parseComparableNumber(match[1]);
  const direction = String(match[2] || "").trim();
  if (!Number.isFinite(distance) || distance <= 0 || !direction) return `${subjectGenitive} ${text}`;
  const roundedDistance = Math.max(10, Math.round(distance / 10) * 10);
  return `${subjectGenitive} yaklaşık ${roundedDistance.toLocaleString("tr-TR")} metre ${direction}`;
}

function buildComparableLandPositionText(row) {
  const sign = String(row.c9 || "").trim();
  const reason = row.c10 ? `${row.c10} sebebiyle ` : "";
  const percent = parseComparablePercent(row.c22);
  // bkz. buildComparableLongText() yorumu — Emsaller Çoklu Talep'te ortak
  // olduğundan (isComparablesSharedAcrossUnits) tekil "taşınmaza göre"
  // (dativ) referansı burada da çoğullaştırılır.
  const subjectDative = isComparablesSharedAcrossUnits() ? "taşınmazlara" : "taşınmaza";
  if (!Number.isFinite(percent) || percent === 0 || sign === "0") return "benzer konumda";
  if (sign === "+") return `${reason}${subjectDative} göre ${percent > 0.25 ? "çok daha iyi" : "daha iyi"} konumda`;
  if (sign === "-") return `${reason}${subjectDative} göre ${percent > 0.25 ? "çok daha vasat" : "daha vasat"} konumda`;
  return "benzer konumda";
}

function buildComparableLandZoningText(row) {
  syncComparableLandBuildableArea(row);
  const conditions = [
    formatComparableLandOrderText(row.c26),
    formatComparableLandKaksText(row.c27),
    formatComparableLandFloorCountText(row.c28),
  ].filter(Boolean).join(", ");
  const legend = String(row.c25 || "").trim();
  const parts = [];
  if (conditions) parts.push(`${conditions} yapılaşma koşullarına sahip`);
  if (legend) parts.push(`${legend} lejantlı`);
  return parts.join(", ");
}

function formatComparableLandOrderText(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  const key = foldTurkish(text).toLocaleLowerCase("tr-TR");
  if (key.includes("nizam")) return formatUiHeading(text);
  return `${formatUiHeading(text)} Nizam`;
}

function formatComparableLandKaksText(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  const key = foldTurkish(text).toLocaleLowerCase("tr-TR");
  if (key.includes("kaks") || key.includes("emsal")) return formatUiHeading(text);
  const number = parseComparableNumber(text);
  if (Number.isFinite(number)) {
    return `KAKS: ${number.toLocaleString("tr-TR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  }
  return `KAKS: ${text}`;
}

function formatComparableLandFloorCountText(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  const key = foldTurkish(text).toLocaleLowerCase("tr-TR");
  if (key.includes("kat") || key === "serbest") return formatUiHeading(text);
  const number = parseComparableNumber(text);
  if (Number.isFinite(number)) return `${Math.round(number).toLocaleString("tr-TR")} Kat`;
  return `${formatUiHeading(text)} Kat`;
}

function buildComparableLandNegotiationText(metrics) {
  if (!Number.isFinite(metrics.negotiationRate) || metrics.negotiationRate <= 0) return "";
  const negotiationRateText = Math.round(metrics.negotiationRate * 100).toLocaleString("tr-TR");
  return `Pazarlık payının yaklaşık %${negotiationRateText} olduğu düşünülmektedir.`;
}

function buildComparableLandCalculationText(row, metrics) {
  const status = String(row.c2 || "").toLocaleLowerCase("tr-TR");
  if (!status.includes("satılık") && !status.includes("satılmış")) return "";
  if (!Number.isFinite(metrics.adjustedUnitValue) || metrics.adjustedArea <= 0 || metrics.saleValue <= 0) return "";
  const totalAdjustment = 1 + metrics.locationAdjustment;
  const label = status.includes("satılmış") ? "Satış Değeri" : "Pazarlıklı Değer";
  return ` (Pazarlık Payı Düşülmüş ve İndirgenmiş m2 birim Değeri: ${formatComparableMoney(metrics.saleValue)} (${label}) / ${metrics.adjustedArea.toLocaleString("tr-TR", { maximumFractionDigits: 2 })} m2 X ${totalAdjustment.toLocaleString("tr-TR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} (Toplam Şerefiye) = ${formatComparableMoney(metrics.adjustedUnitValue, " TL/m2")})`;
}

function formatComparableExtraNote(value) {
  const text = String(value || "").trim();
  return text ? `(Not: ${text})` : "";
}

function buildComparableLocationPhrase(row) {
  const location = buildComparableLocationLocative(row.c7);
  const mapLocation = String(row.c20 || "").trim();
  if (location && mapLocation) return `${location}, taşınmaza göre ${mapLocation}`;
  if (location) return location;
  if (mapLocation) return `taşınmaza göre ${mapLocation}`;
  return "";
}

function buildComparableAgeFloorPhrase(row) {
  const parts = [];
  const age = buildComparableBuildingAgePhrase(row);
  const floor = buildComparableFloorPhrase(row.c6);
  if (age) parts.push(age);
  if (floor) parts.push(floor);
  if (row.c5) parts.push(`${row.c5} oda düzeninde`);
  return parts.join(", ");
}

function getComparableStatusText(row, metrics) {
  const status = String(row.c2 || "").toLocaleLowerCase("tr-TR");
  if (status.includes("konu")) return "";
  if (status.includes("kiralık")) {
    return metrics.rent > 0 ? `${formatComparableMoney(metrics.rent, " TL/ay")} bedelle kiralıktır.` : "kiralık olduğu bilgisi alınmıştır.";
  }
  if (status.includes("satılmış")) {
    const dateText = buildComparableSaleDateText(row.c3);
    return metrics.askingPrice > 0
      ? `${formatComparableMoney(metrics.askingPrice)} bedelle ${dateText} satıldığı bilgisi alınmıştır.`
      : `${dateText} satıldığı bilgisi alınmıştır.`;
  }
  if (status.includes("genel")) {
    return "";
  }
  if (metrics.askingPrice > 0) return `${formatComparableMoney(metrics.askingPrice)} bedelle satılıktır.`;
  return status ? `${status} olduğu bilgisi alınmıştır.` : "";
}

const comparablePositionSimilarVariants = [
  (reason) => (reason ? `${reason} olmasına rağmen benzer konumda` : "benzer konumda"),
  (reason) => (reason ? `${reason} olmasına karşın benzer bir konumdadır` : "benzer bir konumdadır"),
  (reason) => (reason ? `${reason} olmasına rağmen konum bakımından benzerdir` : "konum bakımından benzerdir"),
  (reason) => (reason ? `${reason} olmasına rağmen benzer bir konuma sahiptir` : "benzer bir konuma sahiptir"),
];
// bkz. buildComparableLongText() yorumu — Emsaller Çoklu Talep'te ortak
// olduğundan (isComparablesSharedAcrossUnits) tekil "taşınmaza" (dativ)
// referansı bu varyantlarda da çoğullaştırılır.
const comparablePositionBetterVariants = [
  (reason, level) => `${reason}${isComparablesSharedAcrossUnits() ? "taşınmazlara" : "taşınmaza"} göre ${level} konumda`,
  (reason, level) => `${reason}${isComparablesSharedAcrossUnits() ? "taşınmazlara" : "taşınmaza"} kıyasla ${level} bir konumdadır`,
  (reason, level) => `${reason}${isComparablesSharedAcrossUnits() ? "taşınmazlara" : "taşınmaza"} göre ${level} bir konuma sahiptir`,
  (reason, level) => `${reason}${isComparablesSharedAcrossUnits() ? "taşınmazlara" : "taşınmaza"} nazaran ${level} konumdadır`,
];
registerVariantGroup("buildComparablePositionComparisonText:similar", "Emsal Konum Karşılaştırması — Benzer (Emsaller)", comparablePositionSimilarVariants.length);
registerVariantGroup("buildComparablePositionComparisonText:diff", "Emsal Konum Karşılaştırması — Farklı (Emsaller)", comparablePositionBetterVariants.length);

function buildComparablePositionComparisonText(row) {
  const sign = String(row.c9 || "").trim();
  const reason = row.c10 ? `${row.c10} sebebiyle ` : "";
  const percent = parseComparablePercent(row.c22);
  const variantIndex = selectVariant("buildComparablePositionComparisonText:similar", comparablePositionSimilarVariants.length);
  const diffVariantIndex = selectVariant("buildComparablePositionComparisonText:diff", comparablePositionBetterVariants.length);
  if (!Number.isFinite(percent) || percent === 0) {
    return comparablePositionSimilarVariants[variantIndex](row.c10);
  }
  if (sign === "+") return comparablePositionBetterVariants[diffVariantIndex](reason, percent > 0.25 ? "çok daha iyi" : "daha iyi");
  if (sign === "-") return comparablePositionBetterVariants[diffVariantIndex](reason, percent > 0.25 ? "çok daha vasat" : "daha vasat");
  return comparablePositionSimilarVariants[variantIndex](row.c10);
}

const comparableFeatureExternalVariants = [
  (level) => `iç özellikleri ${level} seviyededir.`,
  (level) => `iç mekân özellikleri ${level} seviyededir.`,
  (level) => `iç özellikleri ${level} seviyede olduğu değerlendirilmiştir.`,
  (level) => `iç mekân niteliği ${level} seviyededir.`,
];
// bkz. buildComparableLongText() yorumu — Emsaller Çoklu Talep'te ortak
// olduğundan (isComparablesSharedAcrossUnits) tekil "taşınmaza"/"gayrimenkule"
// (dativ) referansları bu varyantlarda da çoğullaştırılır.
const comparableFeatureInternalVariants = [
  (level) => `Emsal, konu ${isComparablesSharedAcrossUnits() ? "taşınmazlara" : "taşınmaza"} göre ${level} iç özelliklere sahiptir.`,
  (level) => `Emsal, değerlemeye konu ${isComparablesSharedAcrossUnits() ? "gayrimenkullere" : "gayrimenkule"} kıyasla ${level} iç özelliklere sahiptir.`,
  (level) => `Emsal, konu ${isComparablesSharedAcrossUnits() ? "taşınmazlara" : "taşınmaza"} göre ${level} iç mekân niteliği taşımaktadır.`,
  (level) => `Emsal, değerlemeye konu ${isComparablesSharedAcrossUnits() ? "gayrimenkullere" : "gayrimenkule"} göre ${level} iç özellikler barındırmaktadır.`,
];
registerVariantGroup("buildComparableFeatureComparisonText:external", "Emsal İç Özellik Karşılaştırması — Dışarıdan Ekspertiz (Emsaller)", comparableFeatureExternalVariants.length);
registerVariantGroup("buildComparableFeatureComparisonText:internal", "Emsal İç Özellik Karşılaştırması (Emsaller)", comparableFeatureInternalVariants.length);

function buildComparableFeatureComparisonText(row) {
  const sign = String(row.c8 || "").trim();
  const percent = parseComparablePercent(row.c21);
  if (isExternalAppointmentType(state.fields.appointmentType)) {
    const externalIndex = selectVariant("buildComparableFeatureComparisonText:external", comparableFeatureExternalVariants.length);
    if (sign === "+") {
      return comparableFeatureExternalVariants[externalIndex](percent > 0.25 ? "lüks" : "bakımlı");
    }
    if (sign === "-") {
      return comparableFeatureExternalVariants[externalIndex](percent > 0.25 ? "çok vasat" : "vasat");
    }
    return comparableFeatureExternalVariants[externalIndex]("orta");
  }
  const internalIndex = selectVariant("buildComparableFeatureComparisonText:internal", comparableFeatureInternalVariants.length);
  if (!Number.isFinite(percent) || percent === 0 || sign === "0") return comparableFeatureInternalVariants[internalIndex]("benzer");
  if (sign === "+") return comparableFeatureInternalVariants[internalIndex](percent > 0.25 ? "çok daha iyi" : "daha iyi");
  if (sign === "-") return comparableFeatureInternalVariants[internalIndex](percent > 0.25 ? "çok daha vasat" : "daha vasat");
  return comparableFeatureInternalVariants[internalIndex]("benzer");
}

// İş Bankası ve Kuveyt Türk raporlarında emsal telefon numarası tam 10
// haneli (başında 0 olmadan, boşluk/parantez/tire olmadan); Halkbank
// raporlarında ise tam 11 haneli (başında 0 İLE, boşluk/parantez/tire
// olmadan) girilmelidir — kullanıcı emsal matrisine "05321111212" /
// "0 (532) 111 12 12" / "5321111212" gibi serbest formatta girebilir,
// çıktıya basılırken bu bankalar için otomatik normalize edilir
// (kullanıcı talebi).
function getComparablePhoneNormalizationDigitsForBank() {
  const bank = foldTurkish(state.fields.bank || "");
  if (bank.includes("IS BANKASI") || bank.includes("TURKIYE IS BANKASI") || bank.includes("KUVEYT TURK")) return 10;
  if (isHalkbankSelectedForReport()) return 11;
  return 0;
}

function normalizeComparablePhoneForBank(value, targetDigitCount) {
  let digits = String(value || "").replace(/\D+/g, "");
  if (digits.length === 12 && digits.startsWith("90")) digits = digits.slice(2);
  if (targetDigitCount === 10 && digits.length === 11 && digits.startsWith("0")) digits = digits.slice(1);
  if (targetDigitCount === 11 && digits.length === 10 && !digits.startsWith("0")) digits = `0${digits}`;
  return digits;
}

function formatComparablePhoneForOutput(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  const targetDigitCount = getComparablePhoneNormalizationDigitsForBank();
  return targetDigitCount ? normalizeComparablePhoneForBank(text, targetDigitCount) : text;
}

function buildComparableContactLine(row) {
  const phone = formatComparablePhoneForOutput(row.c1);
  return `(İrtibat Kişisi ve Telefon No: ${[row.c0, phone].filter(Boolean).join(" / ") || "-"})`;
}

const comparableSubjectOpeningVariants = [
  "Ekspertize konu taşınmaz satılık olup",
  "Değerlemeye konu gayrimenkul satışa sunulmuş olup",
  "Söz konusu taşınmaz satılık olarak piyasaya sunulmuş olup",
  "Rapor konusu gayrimenkul satışa arz edilmiş olup",
];
registerVariantGroup("buildComparableSubjectStatement", "'Konu Taşınmaz' Emsal Kartı Açılışı (Emsaller)", comparableSubjectOpeningVariants.length);

function buildComparableSubjectStatement(row, metrics) {
  const contactLine = buildComparableContactLine(row);
  const declaredArea = formatComparableArea(row.c12, "m2");
  const correctedArea = formatComparableArea(row.c13 || row.c12, "m2");
  const priceText = metrics.askingPrice > 0
    ? `Taşınmaz için ${formatComparableMoney(metrics.askingPrice)} talep edilmektedir.`
    : "Taşınmaz için fiyat bilgisi paylaşılmamıştır.";
  const negotiationText = Number.isFinite(metrics.negotiationRate) && metrics.negotiationRate > 0
    ? `Pazarlık payı vardır. Pazarlık payının yaklaşık %${Math.round(metrics.negotiationRate * 100).toLocaleString("tr-TR")} olduğu düşünülmektedir.`
    : "Pazarlık payı yoktur.";
  const opening = comparableSubjectOpeningVariants[selectVariant("buildComparableSubjectStatement", comparableSubjectOpeningVariants.length)];
  const sentence = [
    opening,
    declaredArea ? `, ${declaredArea} olarak beyan edilmiş` : "",
    correctedArea ? `, ${correctedArea} olduğu bilinmektedir.` : ".",
    ` ${priceText}`,
    ` ${negotiationText}`,
  ].join("");
  return normalizeComparableText(`${contactLine}\n\n${sentence}`);
}

const comparableGeneralStatementVariants = [
  (source, valueText) => `${source} alınan sözlü bilgiye göre bölgede yer alan benzer özellikteki gayrimenkullerin m2 birim değerinin ${valueText} civarında olabileceği bilgisi alınmıştır.`,
  (source, valueText) => `${source} edinilen sözlü bilgiye göre, bölgedeki benzer nitelikli gayrimenkullerin m² birim değerinin ${valueText} arasında değişebileceği bilgisine ulaşılmıştır.`,
];
registerVariantGroup("buildComparableGeneralStatement", "'Genel' Emsal Kartı Açıklaması (Emsaller)", comparableGeneralStatementVariants.length);

function buildComparableGeneralStatement(row, metrics) {
  const value = Number.isFinite(metrics.adjustedUnitValue) ? metrics.adjustedUnitValue : metrics.unitValue;
  const lower = Number.isFinite(value) ? roundComparableToNearest1000(value * 0.96) : Number.NaN;
  const upper = Number.isFinite(value) ? roundComparableToNearest1000(value * 1.04) : Number.NaN;
  const valueText = Number.isFinite(lower) && Number.isFinite(upper)
    ? `${formatComparableMoney(lower, " TL/m2")} ila ${formatComparableMoney(upper, " TL/m2")}`
    : "piyasa koşullarına göre değişen değerler";
  return normalizeComparableText(
    comparableGeneralStatementVariants[selectVariant("buildComparableGeneralStatement", comparableGeneralStatementVariants.length)](
      buildComparableSourceAblative(row.c0),
      valueText
    )
  );
}

const comparableRentalMarketValueVariants = [
  (range) => `Bölgedeki kapitalizasyon oranı dikkate alındığında emsalin piyasa değerinin yaklaşık ${range} arasında olabileceği düşünülmektedir.`,
  (range) => `Bölgedeki kapitalizasyon oranı esas alındığında, emsalin piyasa değerinin yaklaşık ${range} bandında olabileceği değerlendirilmektedir.`,
];
const comparableRentTextVariants = [
  (rent) => `Kira değerinin ${rent} olacağı düşünülmektedir.`,
  (rent) => `Kira bedelinin ${rent} olacağı değerlendirilmektedir.`,
];
const comparableNegotiationYesRentVariants = [
  (rate, rent) => `Pazarlık payı vardır. Pazarlık payının yaklaşık %${rate}, kira değerinin ${rent} olacağı düşünülmektedir.`,
  (rate, rent) => `Emsalde pazarlık payı bulunmaktadır. Pazarlık payının yaklaşık %${rate}, kira bedelinin ise ${rent} olacağı değerlendirilmektedir.`,
];
const comparableNegotiationYesVariants = [
  (rate) => `Pazarlık payı vardır. Pazarlık payının yaklaşık %${rate} olduğu düşünülmektedir.`,
  (rate) => `Emsalde pazarlık payı bulunmaktadır. Pazarlık payının yaklaşık %${rate} olduğu değerlendirilmektedir.`,
];
const comparableNegotiationNoRentVariants = [
  (rent) => `Pazarlık payı yoktur. Kira değerinin ${rent} olacağı düşünülmektedir.`,
  (rent) => `Emsalde pazarlık payı bulunmamaktadır. Kira bedelinin ${rent} olacağı değerlendirilmektedir.`,
];
const comparableNegotiationNoVariants = ["Pazarlık payı yoktur.", "Emsalde pazarlık payı bulunmamaktadır."];
registerVariantGroup("buildComparableBargainAndRentText:rentalMarketValue", "Emsal Kiralık — Bölge Piyasa Değeri (Emsaller)", comparableRentalMarketValueVariants.length);
registerVariantGroup("buildComparableBargainAndRentText:rentOnly", "Emsal — Yalnız Kira Cümlesi (Emsaller)", comparableRentTextVariants.length);
registerVariantGroup("buildComparableBargainAndRentText:negotiationYesRent", "Emsal — Pazarlık Var + Kira (Emsaller)", comparableNegotiationYesRentVariants.length);
registerVariantGroup("buildComparableBargainAndRentText:negotiationYes", "Emsal — Yalnız Pazarlık Var (Emsaller)", comparableNegotiationYesVariants.length);
registerVariantGroup("buildComparableBargainAndRentText:negotiationNoRent", "Emsal — Pazarlık Yok + Kira (Emsaller)", comparableNegotiationNoRentVariants.length);
registerVariantGroup("buildComparableBargainAndRentText:negotiationNo", "Emsal — Yalnız Pazarlık Yok (Emsaller)", comparableNegotiationNoVariants.length);

function buildComparableBargainAndRentText(row, metrics) {
  const status = String(row.c2 || "").toLocaleLowerCase("tr-TR");
  if (status.includes("kiralık")) {
    const lower = metrics.bargainPrice > 0 ? formatComparableMoney(metrics.bargainPrice) : "";
    const upper = metrics.askingPrice > 0 ? formatComparableMoney(metrics.askingPrice) : "";
    if (!lower && !upper) return "";
    return comparableRentalMarketValueVariants[selectVariant("buildComparableBargainAndRentText:rentalMarketValue", comparableRentalMarketValueVariants.length)](
      [lower, upper].filter(Boolean).join(" - ")
    );
  }
  if (status.includes("genel")) return "";
  if (status.includes("satılmış")) {
    return metrics.rent > 0
      ? comparableRentTextVariants[selectVariant("buildComparableBargainAndRentText:rentOnly", comparableRentTextVariants.length)](formatComparableMoney(metrics.rent, " TL/ay"))
      : "";
  }
  if (Number.isFinite(metrics.negotiationRate) && metrics.negotiationRate > 0) {
    const negotiationRateText = Math.round(metrics.negotiationRate * 100).toLocaleString("tr-TR");
    return metrics.rent > 0
      ? comparableNegotiationYesRentVariants[selectVariant("buildComparableBargainAndRentText:negotiationYesRent", comparableNegotiationYesRentVariants.length)](
          negotiationRateText,
          formatComparableMoney(metrics.rent, " TL/ay")
        )
      : comparableNegotiationYesVariants[selectVariant("buildComparableBargainAndRentText:negotiationYes", comparableNegotiationYesVariants.length)](negotiationRateText);
  }
  return metrics.rent > 0
    ? comparableNegotiationNoRentVariants[selectVariant("buildComparableBargainAndRentText:negotiationNoRent", comparableNegotiationNoRentVariants.length)](formatComparableMoney(metrics.rent, " TL/ay"))
    : comparableNegotiationNoVariants[selectVariant("buildComparableBargainAndRentText:negotiationNo", comparableNegotiationNoVariants.length)];
}

function buildComparableCalculationText(row, metrics) {
  const status = String(row.c2 || "").toLocaleLowerCase("tr-TR");
  if (!status.includes("satılık") && !status.includes("satılmış")) return "";
  if (!Number.isFinite(metrics.adjustedUnitValue) || metrics.adjustedArea <= 0 || metrics.netSaleValue <= 0) return "";
  const totalAdjustment = 1 + metrics.featureAdjustment + metrics.locationAdjustment;
  const label = status.includes("satılmış") ? "Satış Değeri" : "Pazarlıklı Değer";
  const valueExpression = Number.isFinite(metrics.furnitureValue) && metrics.furnitureValue > 0
    ? `(${formatComparableMoney(metrics.saleValue)} (${label}) - ${formatComparableMoney(metrics.furnitureValue)} (Eşya Bedeli))`
    : `${formatComparableMoney(metrics.saleValue)} (${label})`;
  return ` (İndirgenmiş m2 Birim Değeri: ${valueExpression} × ${totalAdjustment.toLocaleString("tr-TR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} (Toplam Şerefiye Katsayısı) / ${metrics.adjustedArea.toLocaleString("tr-TR", { maximumFractionDigits: 2 })} m2 = ${formatComparableMoney(metrics.adjustedUnitValue, " TL/m2")})`;
}

function buildComparableLocationLocative(value) {
  const key = String(value || "").trim().toLocaleLowerCase("tr-TR");
  if (["aynı bölge", "aynı bölge / site", "aynı bölge / bina"].includes(key)) return "aynı bölgede";
  if (["aynı cadde", "aynı cadde / site", "aynı cadde / bina"].includes(key)) return "aynı caddede";
  if (["aynı sokak", "aynı sokak / site", "aynı sokak / bina"].includes(key)) return "aynı sokakta";
  if (key === "aynı site") return "aynı sitede";
  if (key === "aynı site aynı blok") return "aynı sitede aynı blokta";
  if (key === "aynı bina") return "aynı binada";
  return key ? `${key} konumunda` : "aynı bölgede";
}

function buildComparableStructureLocative(value) {
  const key = String(value || "").trim().toLocaleLowerCase("tr-TR");
  if (["aynı bölge / site", "aynı cadde / site", "aynı sokak / site"].includes(key)) return "sitede";
  if (["aynı bölge / bina", "aynı cadde / bina", "aynı sokak / bina"].includes(key)) return "binada";
  return "";
}

function buildComparableBuildingAgePhrase(row) {
  const locationKey = String(row.c7 || "").trim().toLocaleLowerCase("tr-TR");
  if (["aynı site", "aynı site aynı blok", "aynı bina"].includes(locationKey)) return "";
  const structure = buildComparableStructureLocative(row.c7) || "binada";
  const age = String(row.c11 || "").replace(/\s*yaş$/i, "").trim();
  if (!age || age.toLocaleLowerCase("tr-TR") === "yeni") return `yeni bir ${structure} konumlu`;
  return `${age} yıllık bir ${structure} konumlu`;
}

function buildComparableFloorPhrase(value) {
  const parts = String(value || "")
    .split(",")
    .map((item) => normalizeComparableFloorName(item))
    .filter(Boolean);
  if (!parts.length) return "";
  return `${joinComparableTurkishList([...new Set(parts)])} katta yer alan`;
}

// Kat bazında alan/indirgeme (workplaceFloors) girilmişse her katın kendi
// alanını ayrı ayrı belirten bir ifade üretir. Tek kat girilmişse eski
// tekil ifade ("zemin katta 100 m2 olarak beyan edilen") korunur; birden
// fazla kat girilmişse "zemin katı 100 m2 asma katı 50 m2 olmak üzere
// toplam 150 m2 olacak şekilde" biçiminde toplamlı ifade kurulur
// (kullanıcı talebi). Hiçbir katta alan girilmemişse boş döner — çağıran
// yer eski (tek kat + Beyan Edilen Alan) davranışa geri döner.
function buildComparableWorkplaceFloorAreaPhrase(row) {
  const floors = Array.isArray(row?.workplaceFloors) ? row.workplaceFloors : [];
  const filled = floors.filter((entry) => String(entry?.area || "").trim());
  if (!filled.length) return "";
  if (filled.length === 1) {
    const entry = filled[0];
    return `${normalizeComparableFloorName(entry.floor)} katta ${formatComparableArea(entry.area, "m2")} olarak beyan edilen`;
  }
  const parts = filled.map((entry) => `${normalizeComparableFloorName(entry.floor)} katı ${formatComparableArea(entry.area, "m2")}`);
  const totalArea = filled.reduce((sum, entry) => {
    const area = parseComparableNumber(entry.area);
    return sum + (Number.isFinite(area) ? area : 0);
  }, 0);
  return `${parts.join(" ")} olmak üzere toplam ${formatComparableArea(totalArea, "m2")} olacak şekilde`;
}

// Kat bazında indirgeme mantığını ayrı bir cümlede açıklar, örn: "Kat
// bazında indirgenmiş alan zemin kat etkili alan olarak belirlenmiş olup
// asma kat %30 oranında indirgenerek etkili alan 115 m2 olarak
// hesaplanmıştır." (kullanıcı talebi — kira cümlesinden hemen sonra).
// Hiçbir katta alan girilmemişse boş döner.
function buildComparableWorkplaceFloorReductionExplanation(row, metrics) {
  const floors = (Array.isArray(row?.workplaceFloors) ? row.workplaceFloors : [])
    .filter((entry) => String(entry?.area || "").trim());
  if (!floors.length) return "";
  const withRate = floors.map((entry) => ({
    label: `${normalizeComparableFloorName(entry.floor)} kat`,
    rate: parseComparableWorkplaceReductionRate(entry.rate),
  }));
  const baselineLabels = withRate.filter((entry) => entry.rate >= 1).map((entry) => entry.label);
  const reducedLabels = withRate
    .filter((entry) => entry.rate < 1)
    .map((entry) => `${entry.label} %${Math.round(entry.rate * 100)}`);
  const totalArea = formatComparableArea(metrics?.workplaceReducedArea, "m2");
  if (!totalArea) return "";
  const baselinePhrase = baselineLabels.length ? `${joinComparableTurkishList(baselineLabels)} etkili alan olarak belirlenmiş olup ` : "";
  const reducedPhrase = reducedLabels.length ? `${joinComparableTurkishList(reducedLabels)} oranında indirgenerek ` : "";
  return workplaceFloorReductionVariants[selectVariant("buildComparableWorkplaceFloorReductionExplanation", workplaceFloorReductionVariants.length)](
    baselinePhrase,
    reducedPhrase,
    totalArea
  );
}

const workplaceFloorReductionVariants = [
  (baselinePhrase, reducedPhrase, totalArea) => `Kat bazında indirgenmiş alan ${baselinePhrase}${reducedPhrase}etkili alan ${totalArea} olarak hesaplanmıştır.`,
  (baselinePhrase, reducedPhrase, totalArea) => `Kat bazında indirgenmiş alan hesabında ${baselinePhrase}${reducedPhrase}toplam etkili alan ${totalArea} olarak belirlenmiştir.`,
];
registerVariantGroup("buildComparableWorkplaceFloorReductionExplanation", "İşyeri Emsali Kat Bazında İndirgeme Açıklaması (Emsaller)", workplaceFloorReductionVariants.length);

function normalizeComparableFloorName(value) {
  const text = String(value || "").trim();
  const key = text.toLocaleLowerCase("tr-TR");
  if (!key) return "";
  const normalMatch = key.match(/^(\d+)\.\s*normal/);
  if (normalMatch) return `${normalMatch[1]}. normal`;
  if (key.includes("bahçe")) return "bahçe dubleks";
  if (key.includes("çatı dubleks")) return "çatı dubleks";
  if (key.includes("çatı")) return "çatı";
  if (key.includes("teras")) return "teras";
  if (key.includes("zemin")) return "zemin";
  if (key.includes("asma")) return "asma";
  if (key.includes("ara")) return "ara";
  if (key.includes("en üst")) return "en üst";
  if (key.includes("bodrum")) return "bodrum";
  return text.replace(/\s*kat$/i, "").trim();
}

function joinComparableTurkishList(items) {
  if (!items.length) return "";
  if (items.length === 1) return items[0];
  if (items.length === 2) return `${items[0]} ve ${items[1]}`;
  return `${items.slice(0, -1).join(", ")} ve ${items[items.length - 1]}`;
}

function buildComparableSaleDateText(value) {
  const date = parseComparableDate(value);
  if (!date) return "yakın zamanda";
  const now = new Date();
  const diffDays = Math.max(0, Math.round((now.getTime() - date.getTime()) / 86400000));
  if (diffDays < 31) return `${diffDays} gün önce`;
  return `${Math.round(diffDays / 30)} ay önce`;
}

function parseComparableDate(value) {
  const text = String(value || "").trim();
  const isoMatch = text.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (isoMatch) {
    const date = new Date(Number(isoMatch[1]), Number(isoMatch[2]) - 1, Number(isoMatch[3]));
    return Number.isNaN(date.getTime()) ? null : date;
  }
  const match = text.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{2,4})$/);
  if (!match) return null;
  const year = Number(match[3].length === 2 ? `20${match[3]}` : match[3]);
  const date = new Date(year, Number(match[2]) - 1, Number(match[1]));
  return Number.isNaN(date.getTime()) ? null : date;
}

function formatComparableArea(value, suffix = "m²") {
  const number = parseComparableNumber(value);
  if (Number.isFinite(number)) return `${number.toLocaleString("tr-TR", { maximumFractionDigits: 2 })} ${suffix}`;
  const text = String(value || "").trim();
  return text ? text.replace(/\s*m[²2]?$/i, ` ${suffix}`) : "";
}

function roundComparableToNearest1000(value) {
  if (!Number.isFinite(value) || value <= 0) return Number.NaN;
  return Math.floor((value + 500) / 1000) * 1000;
}

function buildComparableSourceAblative(source) {
  const text = String(source || "").trim();
  if (!text) return "irtibattan";
  const lower = text.toLocaleLowerCase("tr-TR");
  const vowels = lower.match(/[aeıioöuü]/g);
  const lastVowel = vowels ? vowels[vowels.length - 1] : "a";
  let suffix = "eiöü".includes(lastVowel) ? "den" : "dan";
  if ("fstkçşhp".includes(lower.slice(-1))) suffix = suffix.replace("d", "t");
  return `${text}'${suffix}`;
}

function normalizeComparableText(value) {
  return String(value || "")
    .split("\n")
    .map((line) => normalizeReportSentenceLine(cleanComparablePunctuation(line.replace(/\s+/g, " ").trim())))
    .join("\n")
    .trim();
}

function cleanComparablePunctuation(value) {
  return String(value || "")
    .replace(/\s+([.,;:!?])/g, "$1")
    .replace(/([.!?])\s*\1+/g, "$1")
    .replace(/([.!?])\s+([.!?])/g, "$1")
    .replace(/\s{2,}/g, " ")
    .trim();
}

function openComparableLocationModal(row, rowIndex, onSave = () => {}) {
  document.querySelector(".modal-overlay")?.remove();
  const subjectPoint = getComparableSubjectPoint();
  const initialPoint = getComparableSavedPoint(row) || subjectPoint;
  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  overlay.innerHTML = `
    <div class="modal-card modal-card-wide" role="dialog" aria-modal="true" aria-labelledby="comparableLocationModalTitle">
      <div class="modal-head">
        <h3 id="comparableLocationModalTitle">Emsal ${rowIndex + 1} Konumu</h3>
        <button class="modal-close" type="button" aria-label="Kapat">×</button>
      </div>
      <div class="modal-body">
        <p class="modal-lead">Haritada emsalin yerini işaretleyin. KML merkezi varsa konu taşınmaz referansı olarak kullanılır.</p>
        <div class="comparable-location-map" data-comparable-location-map></div>
        <div class="form-grid">
          <label class="field">
            <span>Enlem</span>
            <input data-comparable-lat value="${escapeHtml(row.c18 || "")}" />
          </label>
          <label class="field">
            <span>Boylam</span>
            <input data-comparable-lng value="${escapeHtml(row.c19 || "")}" />
          </label>
          <label class="field field-wide">
            <span>Taşınmaza Göre Konum</span>
            <input data-comparable-location-text value="${escapeHtml(row.c20 || "")}" />
          </label>
        </div>
      </div>
      <div class="modal-actions">
        <button class="secondary-button" type="button" data-cancel>Vazgeç</button>
        <button class="primary-button" type="button" data-save>Kaydet</button>
      </div>
    </div>
  `;

  const close = () => overlay.remove();
  overlay.querySelector(".modal-close").addEventListener("click", close);
  overlay.querySelector("[data-cancel]").addEventListener("click", close);
  document.body.append(overlay);

  const latInput = overlay.querySelector("[data-comparable-lat]");
  const lngInput = overlay.querySelector("[data-comparable-lng]");
  const textInput = overlay.querySelector("[data-comparable-location-text]");
  let selectedPoint = initialPoint ? { lat: Number(initialPoint[0]), lng: Number(initialPoint[1]) } : null;

  const syncInputsFromPoint = (lat, lng) => {
    selectedPoint = { lat: Number(lat), lng: Number(lng) };
    latInput.value = selectedPoint.lat.toFixed(6);
    lngInput.value = selectedPoint.lng.toFixed(6);
    textInput.value = buildComparableLocationText(selectedPoint.lat, selectedPoint.lng);
  };

  [latInput, lngInput].forEach((input) => {
    input.addEventListener("input", () => {
      const lat = Number.parseFloat(String(latInput.value || "").replace(",", "."));
      const lng = Number.parseFloat(String(lngInput.value || "").replace(",", "."));
      if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;
      selectedPoint = { lat, lng };
      textInput.value = buildComparableLocationText(lat, lng);
    });
  });

  renderComparableLocationMap(overlay, subjectPoint, selectedPoint, syncInputsFromPoint);

  overlay.querySelector("[data-save]").addEventListener("click", () => {
    const lat = Number.parseFloat(String(latInput.value || "").replace(",", "."));
    const lng = Number.parseFloat(String(lngInput.value || "").replace(",", "."));
    const targetRow = getComparableRows()[rowIndex] || row;
    targetRow.c18 = Number.isFinite(lat) ? lat.toFixed(6) : "";
    targetRow.c19 = Number.isFinite(lng) ? lng.toFixed(6) : "";
    targetRow.c20 = textInput.value.trim();
    row.c18 = targetRow.c18;
    row.c19 = targetRow.c19;
    row.c20 = targetRow.c20;
    onSave();
    close();
  });
}

function getComparableSubjectPoint() {
  const selected = getSelectedMapPoint();
  if (selected) return selected;
  const kmlRecords = getTitleUnitKmlRecordsForMap();
  const centroid = state.sourceValues.kml?.centroid || kmlRecords[0]?.parsed?.centroid;
  if (centroid && Number.isFinite(Number(centroid.lat)) && Number.isFinite(Number(centroid.lng))) {
    return [Number(centroid.lat), Number(centroid.lng)];
  }
  const firstCoordinate = state.sourceValues.kml?.coordinates?.[0] || kmlRecords[0]?.parsed?.coordinates?.[0];
  if (firstCoordinate && Number.isFinite(Number(firstCoordinate.lat)) && Number.isFinite(Number(firstCoordinate.lng))) {
    return [Number(firstCoordinate.lat), Number(firstCoordinate.lng)];
  }
  return null;
}

function getComparableSketchExportKml() {
  const records = getTitleUnitKmlRecordsForMap();
  if (!records.length) return state.sourceValues.kml;
  return {
    ...(state.sourceValues.kml || {}),
    coordinates: records.flatMap((record) => record.parsed.coordinates || []),
  };
}

function getComparableSavedPoint(row) {
  const lat = Number.parseFloat(String(row.c18 || "").replace(",", "."));
  const lng = Number.parseFloat(String(row.c19 || "").replace(",", "."));
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  return [lat, lng];
}

function buildComparableLocationText(lat, lng) {
  const subjectPoint = getComparableSubjectPoint();
  if (!subjectPoint) return "";
  const distance = calculateDistanceMeters(subjectPoint[0], subjectPoint[1], lat, lng);
  const direction = calculateRelativeDirectionText(subjectPoint[0], subjectPoint[1], lat, lng);
  return formatDistanceWithDirection(distance, direction);
}

function renderComparableLocationMap(overlay, subjectPoint, selectedPoint, onPointSelected) {
  const panel = overlay.querySelector("[data-comparable-location-map]");
  if (!panel) return;
  if (!isLeafletReady() || !subjectPoint) {
    panel.innerHTML = `<div class="map-placeholder">Harita için önce KML veya koordinat bilgisi gerekli.</div>`;
    return;
  }
  const leaflet = window.L;
  const map = leaflet.map(panel, getLeafletInteractionOptions({ forceDraggable: true })).setView(selectedPoint ? [selectedPoint.lat, selectedPoint.lng] : subjectPoint, 16);
  getLeafletTileLayer().addTo(map);

  const coordinates = state.sourceValues.kml?.coordinates || [];
  if (coordinates.length) {
    leaflet.polygon(coordinates.map((point) => [point.lat, point.lng]), {
      color: "#d92525",
      weight: 3,
      opacity: 0.95,
      fillColor: "#d92525",
      fillOpacity: 0.12,
    }).addTo(map);
  }

  leaflet.marker(subjectPoint).addTo(map).bindTooltip("KONU TAŞINMAZ", {
    permanent: true,
    direction: "left",
    offset: [-10, -20],
    className: "subject-map-label",
  });

  let marker = null;
  const setMarker = (lat, lng) => {
    if (!marker) {
      marker = leaflet.marker([lat, lng], { draggable: !isCoarsePointerDevice() }).addTo(map);
      marker.on("dragend", (event) => {
        const point = event.target.getLatLng();
        onPointSelected(point.lat, point.lng);
      });
    } else {
      marker.setLatLng([lat, lng]);
    }
    marker.bindPopup("Emsal konumu").openPopup();
  };

  if (selectedPoint && Number.isFinite(selectedPoint.lat) && Number.isFinite(selectedPoint.lng)) {
    setMarker(selectedPoint.lat, selectedPoint.lng);
  }

  map.on("click", (event) => {
    const { lat, lng } = event.latlng;
    setMarker(lat, lng);
    onPointSelected(lat, lng);
  });

  window.setTimeout(() => map.invalidateSize(), 0);
}

function createComparableFieldControl(field) {
  if (field.type === "select") {
    const select = document.createElement("select");
    if (field.allowEmpty !== false) {
      const empty = document.createElement("option");
      empty.value = "";
      empty.textContent = "Seçiniz";
      select.append(empty);
    }
    field.options.forEach((option) => {
      const item = document.createElement("option");
      item.value = option;
      item.textContent = option;
      select.append(item);
    });
    return select;
  }
  if (field.type === "textarea") {
    const textarea = document.createElement("textarea");
    textarea.rows = 2;
    return textarea;
  }
  const input = document.createElement("input");
  if (field.type === "date") input.type = "date";
  return input;
}

function toComparableDateInputValue(value) {
  const text = String(value || "").trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) return text;
  const match = text.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{2,4})$/);
  if (!match) return "";
  const day = match[1].padStart(2, "0");
  const month = match[2].padStart(2, "0");
  const year = match[3].length === 2 ? `20${match[3]}` : match[3];
  return `${year}-${month}-${day}`;
}

function createTable(section) {
  const wrapper = document.createElement("div");
  wrapper.className = "subsection is-detail";
  const isOwnersTable = section.id === "title";
  const isEncumbranceReportTable = isEncumbranceReportTableKey(section.id);
  const isDocumentsTable = section.id === "documents";
  const hasDeleteColumn = isOwnersTable || isEncumbranceReportTable || isDocumentsTable;
  const headingRow = document.createElement("div");
  headingRow.className = "subsection-table-head";
  headingRow.innerHTML = `<h4>${formatUiHeading(section.table.title)}</h4>`;

  const shell = document.createElement("div");
  shell.className = "table-shell";
  const table = document.createElement("table");
  table.classList.add(`table-${section.id}`);
  if (isOwnersTable) {
    table.classList.add("owners-table");
  }
  const thead = document.createElement("thead");
  const tbody = document.createElement("tbody");

  thead.innerHTML = `<tr>${section.table.columns.map((column) => `<th>${formatUiHeading(column)}</th>`).join("")}${hasDeleteColumn ? "<th></th>" : ""}</tr>`;

  let tableState = state.tables[section.id] || (isEncumbranceReportTable ? [] : Array.from({ length: section.table.rows }, () => ({})));
  if (isDocumentsTable && isLegacyEmptyDocumentTable(tableState)) {
    tableState = [];
  }
  if (isDocumentsTable) {
    tableState = tableState.map(prepareReviewedDocumentTableRow);
  }
  if (section.id === "encumbranceAnnotations") {
    tableState.forEach(normalizeTakbisAnnotationTableRow);
  }
  if (section.id === "encumbranceMortgages") {
    tableState = tableState.filter((row) => hasMeaningfulEncumbranceTableRow(section.id, row));
    tableState.forEach((row) => {
      if (row?.c0) row.c0 = normalizeMortgageCreditorDisplay(row.c0);
    });
  }
  state.tables[section.id] = tableState;
  let ownerSummary = null;
  let annotationLienSummary = null;

  const tableEntries = isDocumentsTable
    ? getReviewedDocumentTableEntries(tableState)
    : tableState.map((row, index) => ({ row, index }));
  tableEntries.forEach(({ row, index: rowIndex, isArchitecturalProject = false }) => {
    const tr = document.createElement("tr");
    section.table.columns.forEach((column, columnIndex) => {
      const key = `c${columnIndex}`;
      const td = document.createElement("td");
      const isAnnotationDescription = section.id === "encumbranceAnnotations" && key === "c1";
      const isAnnotationAmount = section.id === "encumbranceAnnotations" && key === "c2";
      const input = createTableCellControl(section, key, isAnnotationDescription);
      if (isAnnotationDescription) {
        input.rows = 4;
        input.className = "table-textarea table-textarea-description";
      }
      input.value = input.type === "date" ? toComparableDateInputValue(row[key] || "") : row[key] || "";
      if (input.tagName === "SELECT" && row[key] && !Array.from(input.options).some((option) => option.value === row[key])) {
        const generatedOption = document.createElement("option");
        generatedOption.value = row[key];
        generatedOption.textContent = row[key];
        input.append(generatedOption);
        input.value = row[key];
      }
      if (isArchitecturalProject) {
        input.disabled = true;
        input.classList.add("is-readonly");
      }
      applyAnnotationAmountWarning(td, input, row, isAnnotationAmount);
      const handleTableCellChange = (event) => {
        row[key] = event.target.value;
        if (section.id === "encumbranceAnnotations") {
          normalizeTakbisAnnotationTableRow(row);
          const amountInput = tr.querySelector("td:nth-child(3) input");
          if (amountInput && amountInput.value !== (row.c2 || "")) {
            amountInput.value = row.c2 || "";
          }
          const amountCell = amountInput?.closest("td");
          applyAnnotationAmountWarning(amountCell, amountInput, row, Boolean(amountInput));
        }
        if (isOwnersTable && ownerSummary) {
          refreshTitleOwnershipKindFromOwners();
          updateOwnerShareSummary(ownerSummary, state.tables[section.id]);
        }
        if (section.id === "encumbranceAnnotations" && annotationLienSummary) {
          updateAnnotationLienSummary(annotationLienSummary, state.tables[section.id]);
        }
        if (isEncumbranceReportTableKey(section.id)) {
          syncLegacyEncumbranceTable();
          refreshEncumbranceSummaryFromCurrentData();
        }
        if (isDocumentsTable) {
          refreshReviewedDocumentsDescriptionFromCurrentRows();
          // Belgeler ve Proje blok-senkronu (2026-08-19) — "İncelenen
          // Belgeler" tablosu blok ortak alanlardan; ayrı ele alınır (bkz.
          // syncDocumentsSharedDataToBlockSiblings, tables.documents'ı
          // resolveTitleUnitDocumentsRowsWriteTarget ile kopyalar).
          syncDocumentsSharedDataToBlockSiblings();
          if (key === "c0") {
            renderSection();
          } else {
            // Kullanıcı talebi (2026-08-19): "Belgeler ve Proje" için
            // Taşınmazlar Belgeler Özeti'ndeki dinamik "İncelenen Belge N"
            // sütunları bu satırların (c1-c4) içeriğini de gösterir —
            // c0 zaten yukarıda tam renderSection() tetikliyor (bu ANINDA
            // özet tabloyu da içerir), diğer sütunlar için debounce'lu
            // tazeleme yeterli (isOwnersTable'ın AYNI ilkesi).
            refreshDocumentsUnitsSummaryTablePreviewDebounced();
          }
        }
        // Kullanıcı talebi (2026-08-15): "tab üzerinden değiştirince
        // tablo değişsin" — kullanıcının verdiği TAM örnek ("malik ismi
        // hatalı gelmiş") bu tablo (section.id === "title", Malikler)
        // üzerinden düzeltiliyor; Taşınmazlar Tapu Özeti'ndeki Malik(ler)/
        // Hisse Payı/Edinme Sebebi/Tapu Tarihi/Yevmiye No sütunları bu
        // tablodan (joinTitleUnitOwnerColumn ile) besleniyor.
        if (isOwnersTable) {
          refreshTitleUnitsSummaryTablePreviewDebounced();
        }
        autosave();
      };
      if (!isArchitecturalProject) input.addEventListener("input", handleTableCellChange);
      if (!isArchitecturalProject && input.tagName === "SELECT") {
        input.addEventListener("change", handleTableCellChange);
      }
      if (!isArchitecturalProject) input.addEventListener("blur", () => {
        const formattedValue = normalizeReportTableValue(section, column, input.value);
        if (formattedValue === input.value) return;
        input.value = formattedValue;
        row[key] = formattedValue;
        if (section.id === "encumbranceAnnotations") {
          normalizeTakbisAnnotationTableRow(row);
        }
        if (isOwnersTable && ownerSummary) {
          refreshTitleOwnershipKindFromOwners();
          updateOwnerShareSummary(ownerSummary, state.tables[section.id]);
        }
        if (section.id === "encumbranceAnnotations" && annotationLienSummary) {
          updateAnnotationLienSummary(annotationLienSummary, state.tables[section.id]);
        }
        if (isEncumbranceReportTableKey(section.id)) {
          syncLegacyEncumbranceTable();
          refreshEncumbranceSummaryFromCurrentData();
        }
        if (isDocumentsTable) {
          refreshReviewedDocumentsDescriptionFromCurrentRows();
          syncDocumentsSharedDataToBlockSiblings();
        }
        autosave();
        if (isDocumentsTable && key === "c2") {
          renderSection();
        } else if (isDocumentsTable) {
          refreshDocumentsUnitsSummaryTablePreviewDebounced();
        }
      });
      td.append(input);
      tr.append(td);
    });
    if (hasDeleteColumn) {
      const td = document.createElement("td");
      td.className = "table-action-cell";
      if (isArchitecturalProject) {
        tr.append(td);
        tbody.append(tr);
        return;
      }
      const deleteButton = document.createElement("button");
      deleteButton.type = "button";
      deleteButton.className = "row-delete-button";
      deleteButton.textContent = "X";
      deleteButton.setAttribute("aria-label", getTableDeleteButtonLabel(section.id, isOwnersTable));
      deleteButton.addEventListener("click", () => {
        state.tables[section.id].splice(rowIndex, 1);
        if (isOwnersTable && !state.tables[section.id].length) state.tables[section.id].push({});
        if (isOwnersTable) {
          refreshTitleOwnershipKindFromOwners();
        }
        if (isEncumbranceReportTable) {
          syncLegacyEncumbranceTable();
          refreshEncumbranceSummaryFromCurrentData();
        }
        if (isDocumentsTable) {
          refreshReviewedDocumentsDescriptionFromCurrentRows();
          syncDocumentsSharedDataToBlockSiblings();
        }
        autosave();
        renderSection();
      });
      td.append(deleteButton);
      tr.append(td);
    }
    tbody.append(tr);
  });

  table.append(thead, tbody);
  if (tableState.length) {
    shell.append(table);
  }
  if (isOwnersTable) {
    ownerSummary = document.createElement("div");
    ownerSummary.className = "owner-share-summary";
    updateOwnerShareSummary(ownerSummary, tableState);
    shell.append(ownerSummary);
  }
  if (section.id === "encumbranceAnnotations") {
    annotationLienSummary = document.createElement("div");
    annotationLienSummary.className = "annotation-lien-summary";
    updateAnnotationLienSummary(annotationLienSummary, tableState);
  }

  const addButton = document.createElement("button");
  addButton.type = "button";
  addButton.className = "mini-button";
  addButton.textContent = getTableAddButtonText(section.id, isOwnersTable);
  if (isDocumentsTable) addButton.dataset.documentsAddButton = "true";
  addButton.addEventListener("click", () => {
    state.tables[section.id].push(isDocumentsTable ? createEmptyReviewedDocumentRow() : {});
    if (isOwnersTable) {
      refreshTitleOwnershipKindFromOwners();
    }
    if (isEncumbranceReportTableKey(section.id)) {
      syncLegacyEncumbranceTable();
      refreshEncumbranceSummaryFromCurrentData();
    }
    if (isDocumentsTable) {
      refreshReviewedDocumentsDescriptionFromCurrentRows();
      syncDocumentsSharedDataToBlockSiblings();
    }
    autosave();
    renderSection();
  });

  if (isOwnersTable) {
    headingRow.append(addButton);
    wrapper.append(headingRow, shell);
  } else if (isEncumbranceReportTable) {
    headingRow.append(addButton);
    wrapper.append(headingRow);
    if (tableState.length) {
      wrapper.append(shell);
    } else {
      const emptyLine = document.createElement("div");
      emptyLine.className = "encumbrance-empty-line";
      wrapper.append(emptyLine);
    }
    if (annotationLienSummary) wrapper.append(annotationLienSummary);
  } else if (isDocumentsTable) {
    wrapper.append(headingRow);
    if (tableState.length) {
      headingRow.append(addButton);
      wrapper.append(shell);
    } else {
      // Tablo boşken sadece küçük bir buton başlığın yanında kayboluyor ve
      // kullanıcılar bu bölümü fark etmeden atlıyor (kullanıcı bildirimi).
      // Bunun yerine tüm dikkati üzerine çeken, kesikli çerçeveli belirgin
      // bir "boş durum" kutusu gösterilir; buton bu kutunun içinde ortalanır.
      const emptyState = document.createElement("div");
      emptyState.className = "documents-table-empty-state";
      const icon = document.createElement("span");
      icon.className = "documents-table-empty-state-icon";
      icon.textContent = "📄";
      icon.setAttribute("aria-hidden", "true");
      const message = document.createElement("p");
      message.className = "documents-table-empty-state-text";
      message.textContent = "Henüz belge eklenmedi. İncelenen ruhsat, iskan veya proje belgelerini eklemek için aşağıdaki butonu kullanın.";
      emptyState.append(icon, message, addButton);
      wrapper.append(emptyState);
    }
  } else {
    wrapper.append(headingRow, shell);
    if (annotationLienSummary) wrapper.append(annotationLienSummary);
    wrapper.append(addButton);
  }
  return wrapper;
}

function getTableAddButtonText(sectionId, isOwnersTable = false) {
  if (isOwnersTable) return "Malik ekle";
  if (sectionId === "documents") return "Belge ekle";
  if (sectionId === "encumbranceDeclarations") return "Beyan ekle";
  if (sectionId === "encumbranceMortgages") return "İpotek ekle";
  if (sectionId === "encumbranceAnnotations") return "Şerh ekle";
  return "Satır ekle";
}

function getTableDeleteButtonLabel(sectionId, isOwnersTable = false) {
  if (isOwnersTable) return "Maliki sil";
  if (sectionId === "documents") return "Belgeyi sil";
  if (sectionId === "encumbranceDeclarations") return "Beyanı sil";
  if (sectionId === "encumbranceMortgages") return "İpoteği sil";
  if (sectionId === "encumbranceAnnotations") return "Şerhi sil";
  return "Satırı sil";
}

function isLegacyEmptyDocumentTable(rows = []) {
  return rows.length === 4 && rows.every((row) => ["c0", "c1", "c2", "c3"].every((key) => !String(row?.[key] || "").trim()));
}

function prepareReviewedDocumentTableRow(row = {}) {
  const prepared = normalizeReviewedDocumentStorageRow(row);
  if (!String(prepared.c1 || "").trim()) {
    prepared.c1 = buildDefaultDocumentReviewInstitution();
  }
  return prepared;
}

function createEmptyReviewedDocumentRow() {
  return { c1: buildDefaultDocumentReviewInstitution() };
}

function createTableCellControl(section, key, isAnnotationDescription = false) {
  if (section.id === "documents" && key === "c0") {
    const select = document.createElement("select");
    const empty = document.createElement("option");
    empty.value = "";
    empty.textContent = "Seçiniz";
    select.append(empty);
    documentTypeOptions.forEach((option) => {
      const item = document.createElement("option");
      item.value = option;
      item.textContent = option;
      select.append(item);
    });
    return select;
  }
  if (section.id === "documents" && key === "c1") {
    const select = document.createElement("select");
    getDocumentInstitutionOptions().forEach((option) => {
      const item = document.createElement("option");
      item.value = option;
      item.textContent = option || "Seçiniz";
      select.append(item);
    });
    return select;
  }
  if (section.id === "documents" && key === "c2") {
    const input = document.createElement("input");
    input.type = "date";
    return input;
  }
  if (section.id === "encumbranceDeclarations" && key === "c0") {
    ensureEncumbranceTypeDatalist("encumbrance-declaration-type-list", encumbranceDeclarationTypeOptions);
    const input = document.createElement("input");
    input.setAttribute("list", "encumbrance-declaration-type-list");
    input.autocomplete = "off";
    return input;
  }
  if (section.id === "encumbranceAnnotations" && key === "c0") {
    ensureEncumbranceTypeDatalist("encumbrance-annotation-type-list", encumbranceAnnotationTypeOptions);
    const input = document.createElement("input");
    input.setAttribute("list", "encumbrance-annotation-type-list");
    input.autocomplete = "off";
    return input;
  }
  if ((section.id === "encumbranceDeclarations" && key === "c2") || (section.id === "encumbranceAnnotations" && key === "c3")) {
    const input = document.createElement("input");
    input.type = "date";
    return input;
  }
  if (section.id === "encumbranceMortgages" && key === "c0") {
    const input = document.createElement("input");
    input.autocomplete = "off";
    input.placeholder = "Banka seçin veya lehdar yazın";
    setupMortgageCreditorCombobox(input);
    return input;
  }
  return document.createElement(isAnnotationDescription ? "textarea" : "input");
}

function getDocumentInstitutionOptions() {
  const options = [
    buildDefaultDocumentReviewInstitution(),
    ...documentInstitutionStaticOptions,
    buildCitySpecificInstitution("İl Özel İdaresi"),
    buildCitySpecificInstitution("Büyükşehir Belediyesi"),
  ].map(normalizeDocumentInstitutionText).filter(Boolean);
  return ["", ...new Set(options)];
}

function buildCitySpecificInstitution(suffix) {
  const city = normalizeReportTitleText(state.fields.titleCity || state.fields.city || "").trim();
  return city ? `${city} ${suffix}` : suffix;
}

function setupMortgageCreditorCombobox(input) {
  // TAKBİS değeri input.value olarak gelmeye devam eder; kullanıcı tüm banka
  // listesinden seçebilir ya da serbest metin (örn. özel kuruluş) yazabilir.
  input.setAttribute("role", "combobox");
  input.setAttribute("aria-autocomplete", "list");
  input.classList.add("creditor-combo-input");
  let panel = null;
  let activeIndex = -1;
  let matches = [];
  // Odakta tüm liste gösterilir; yalnızca kullanıcı yazdıkça filtrelenir.
  let filterActive = false;

  const reposition = () => {
    if (!panel) return;
    if (!panel.isConnected || !input.isConnected) {
      closePanel();
      return;
    }
    const rect = input.getBoundingClientRect();
    panel.style.left = `${rect.left}px`;
    panel.style.minWidth = `${Math.max(rect.width, 240)}px`;
    panel.style.top = `${rect.bottom + 2}px`;
    panel.style.bottom = "auto";
    const panelRect = panel.getBoundingClientRect();
    if (panelRect.bottom > window.innerHeight - 8 && rect.top > panelRect.height) {
      panel.style.top = "auto";
      panel.style.bottom = `${window.innerHeight - rect.top + 2}px`;
    }
  };

  const scrollActiveIntoView = () => {
    panel?.querySelector(".creditor-combo-option.is-active")?.scrollIntoView({ block: "nearest" });
  };

  const renderOptions = () => {
    if (!panel) return;
    const filter = filterActive ? foldTurkish(input.value || "").toLocaleLowerCase("tr").trim() : "";
    matches = mortgageCreditorBankNames.filter(
      (name) => !filter || foldTurkish(name).toLocaleLowerCase("tr").includes(filter),
    );
    if (activeIndex >= matches.length) activeIndex = matches.length - 1;
    panel.innerHTML = "";
    const hint = document.createElement("div");
    hint.className = "creditor-combo-hint";
    hint.textContent = "Listeden seçin veya serbest yazın (örn. özel kuruluş)";
    panel.append(hint);
    if (!matches.length) {
      const empty = document.createElement("div");
      empty.className = "creditor-combo-empty";
      empty.textContent = "Eşleşen banka yok — yazdığınız değer korunur.";
      panel.append(empty);
      reposition();
      return;
    }
    matches.forEach((name, index) => {
      const option = document.createElement("button");
      option.type = "button";
      option.className = "creditor-combo-option";
      if (index === activeIndex) option.classList.add("is-active");
      if (name === input.value) option.classList.add("is-current");
      option.textContent = name;
      option.addEventListener("mousedown", (event) => {
        event.preventDefault();
        commit(name);
      });
      panel.append(option);
    });
    reposition();
  };

  const commit = (name) => {
    input.value = name;
    input.dispatchEvent(new Event("input", { bubbles: true }));
    closePanel();
    input.focus();
  };

  const openPanel = () => {
    if (!panel) {
      // Aynı anda yalnızca bir panel olsun; eski/yetim panelleri temizle.
      document.querySelectorAll(".creditor-combo-panel").forEach((node) => node.remove());
      panel = document.createElement("div");
      panel.className = "creditor-combo-panel";
      document.body.append(panel);
      window.addEventListener("scroll", reposition, true);
      window.addEventListener("resize", reposition);
    }
    renderOptions();
  };

  function closePanel() {
    if (!panel) return;
    panel.remove();
    panel = null;
    activeIndex = -1;
    filterActive = false;
    window.removeEventListener("scroll", reposition, true);
    window.removeEventListener("resize", reposition);
  }

  input.addEventListener("focus", () => {
    filterActive = false;
    openPanel();
  });
  input.addEventListener("click", () => {
    filterActive = false;
    openPanel();
  });
  input.addEventListener("input", () => {
    filterActive = true;
    activeIndex = -1;
    openPanel();
  });
  input.addEventListener("blur", () => {
    setTimeout(closePanel, 150);
  });
  input.addEventListener("keydown", (event) => {
    if (event.key === "ArrowDown") {
      event.preventDefault();
      if (!panel) {
        openPanel();
        return;
      }
      activeIndex = Math.min(activeIndex + 1, matches.length - 1);
      renderOptions();
      scrollActiveIntoView();
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      if (!panel) return;
      activeIndex = Math.max(activeIndex - 1, 0);
      renderOptions();
      scrollActiveIntoView();
    } else if (event.key === "Enter") {
      if (panel && activeIndex >= 0 && matches[activeIndex]) {
        event.preventDefault();
        commit(matches[activeIndex]);
      }
    } else if (event.key === "Escape") {
      closePanel();
    }
  });
}

function ensureEncumbranceTypeDatalist(id, options = []) {
  if (document.querySelector(`#${id}`)) return;
  const list = document.createElement("datalist");
  list.id = id;
  options.forEach((value) => {
    const option = document.createElement("option");
    option.value = value;
    list.append(option);
  });
  document.body.append(list);
}

function updateAnnotationLienSummary(summaryElement, rows = []) {
  const totals = {
    public: 0,
    precautionary: 0,
    executive: 0,
  };
  const counts = {
    public: 0,
    precautionary: 0,
    executive: 0,
  };

  rows.forEach((row) => {
    const normalizedType = normalizeTakbisAnnotationReportType(row?.c0 || "", row?.c1 || "");
    const foldedType = foldTurkish(normalizedType);
    // Yalnızca haciz kayıtları sayılır; İhtiyati Tedbir gibi tedbir şerhleri
    // ihtiyati haciz toplamına girmez.
    if (!/HACIZ|HACZ/.test(foldedType) || /TEDBIR/.test(foldedType)) return;
    const amount = parseTakbisMoneyToNumber(row?.c2 || "");
    if (/KAMU/.test(foldedType)) {
      counts.public += 1;
      totals.public += amount;
    } else if (/IHTIYATI/.test(foldedType)) {
      counts.precautionary += 1;
      totals.precautionary += amount;
    } else {
      counts.executive += 1;
      totals.executive += amount;
    }
  });

  summaryElement.innerHTML = [
    "<strong>Haciz Toplamlar\u0131</strong>",
    `<span>Kamu Haczi Toplam\u0131 (${counts.public}): ${formatTakbisSummaryMoney(totals.public)}</span>`,
    `<span>\u0130htiyati Haciz Toplam\u0131 (${counts.precautionary}): ${formatTakbisSummaryMoney(totals.precautionary)}</span>`,
    `<span>\u0130crai Haciz Toplam\u0131 (${counts.executive}): ${formatTakbisSummaryMoney(totals.executive)}</span>`,
  ].join("");
}

function parseTakbisMoneyToNumber(value) {
  const rawText = cleanTakbisValue(value)
    .replace(/\b(?:TL|YTL|TRY|T\.L\.)\b/gi, "")
    .replace(/[₺]/g, "")
    .trim();
  if (!rawText) return 0;

  const match = rawText.match(/[0-9][0-9.,\s]*[0-9]|[0-9]/);
  if (!match) return 0;
  const text = match[0].replace(/\s+/g, "");
  const lastComma = text.lastIndexOf(",");
  const lastDot = text.lastIndexOf(".");
  const decimalSeparator = lastComma > lastDot ? "," : lastDot > lastComma ? "." : "";
  let integerPart = text.replace(/\D/g, "");
  let decimalPart = "";

  if (decimalSeparator) {
    const separatorIndex = text.lastIndexOf(decimalSeparator);
    const suffix = text.slice(separatorIndex + 1).replace(/\D/g, "");
    if (suffix.length > 0 && suffix.length <= 2) {
      integerPart = text.slice(0, separatorIndex).replace(/\D/g, "");
      decimalPart = suffix.padEnd(2, "0").slice(0, 2);
    }
  }

  const amount = Number(`${integerPart || "0"}.${decimalPart || "00"}`);
  return Number.isFinite(amount) ? amount : 0;
}

function formatTakbisSummaryMoney(value) {
  if (!value) return "-";
  return `${value.toLocaleString("tr-TR", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })} TL`;
}

function applyAnnotationAmountWarning(cell, input, row, isAmountCell) {
  if (!isAmountCell || !cell || !input) return;
  const isMissing = Boolean(row?.__amountMissing);
  cell.classList.toggle("cell-warning", isMissing);
  input.classList.toggle("input-warning", isMissing);
  input.placeholder = isMissing ? "OCR/ham metinden okunamadı" : "";
  input.title = isMissing
    ? "Haciz tutarı OCR ve ham metin kaynaklarından bulunamadı. Lütfen TAKBİS çıktısından kontrol edin."
    : "";
}

function isEncumbranceReportTableKey(key) {
  return encumbranceReportTables.some((table) => table.key === key);
}

function syncLegacyEncumbranceTable() {
  state.tables.encumbrance = encumbranceReportTables
    .flatMap((table) => (state.tables[table.key] || [])
      .filter((row) => hasMeaningfulEncumbranceTableRow(table.key, row))
      .map((row) => table.key === "encumbranceMortgages"
        ? {
            c0: "İpotek",
            c1: [row.c0, row.c1 ? `Derece: ${row.c1}` : "", row.c2 ? `Tutar: ${row.c2}` : ""]
              .filter(Boolean)
              .join(" - "),
            c2: row.c3 || "",
            c3: row.c4 || "",
          }
        : table.key === "encumbranceAnnotations"
          ? {
              c0: row.c0 || "",
              c1: row.c1 || "",
              c2: row.c3 || "",
              c3: row.c4 || "",
            }
        : { ...row }))
    .filter((row) => Object.values(row || {}).some(Boolean))
    .map((row) => ({ ...row }));
}

function updateOwnerShareSummary(element, rows) {
  const summary = formatOwnerShareSummary((rows || []).filter((row) => Object.values(row || {}).some(Boolean)));
  element.classList.toggle("is-ok", summary.ok);
  element.classList.toggle("is-warning", !summary.ok);
  element.textContent = summary.text;
}

function setSidebarCollapsed(collapsed) {
  if (!appShell) return;
  appShell.classList.toggle("sidebar-collapsed", collapsed);
  localStorage.setItem("reportSidebarCollapsed", collapsed ? "1" : "0");
  if (sidebarCollapseBtn) {
    sidebarCollapseBtn.setAttribute("aria-expanded", collapsed ? "false" : "true");
  }
  if (sidebarOpenBtn) {
    sidebarOpenBtn.setAttribute("aria-expanded", collapsed ? "false" : "true");
  }
}

function initSidebarCollapse() {
  if (!appShell) return;
  const saved = localStorage.getItem("reportSidebarCollapsed") === "1";
  setSidebarCollapsed(saved);
  sidebarCollapseBtn?.addEventListener("click", () => setSidebarCollapsed(true));
  sidebarOpenBtn?.addEventListener("click", () => setSidebarCollapsed(false));
}

function renderWorkflow() {
  if (!workflowList) return;
  const currentIndex = Math.min(
    Math.floor((sections.findIndex((item) => item.id === activeSectionId) / sections.length) * workflow.length),
    workflow.length - 1,
  );

  workflowList.innerHTML = "";
  workflow.forEach((item, index) => {
    const li = document.createElement("li");
    li.textContent = item;
    li.classList.toggle("is-current", index === currentIndex);
    workflowList.append(li);
  });
}

function renderDocuments() {
  if (!documentQueue) return;
  const documents = [
    ["TAKBİS", state.uploads.takbis],
    ["Adres", state.uploads.address],
    ["EKB", state.uploads.ekb],
    ["KML", state.uploads.kml],
  ];

  documentQueue.innerHTML = "";
  documents.forEach(([label, file]) => {
    const item = document.createElement("div");
    item.className = "queue-item";
    item.innerHTML = `<span>${label}</span><span class="queue-status">${file ? "Hazır" : "Bekliyor"}</span>`;
    documentQueue.append(item);
  });
}

